// 解锁条件  level-玩家等级 campid-英雄阵营 heroCnt-英雄个数
let unlockCondition = [
    { level: 50, vip: 0, },
    { level: 75, vip: 2, },
    { level: 155, vip: 3, },
    { level: 220, vip: 4, },
    { level: 310, vip: 5, },];

cc.Class({
    extends: cc.Component,

    properties: {
        cardItem: cc.Node,
        atlas: cc.SpriteAtlas,
        _posNodeList: [],
        _itemNodeList: [],
        _lockInfo: [],

        _norW: 0,
        _norH: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._content = cc.find("content", this.node);
        let norNode = cc.find("content/pos1", this.node);
        this._norW = norNode.width * norNode.scale;
        this._norH = norNode.height * norNode.scale;

        cc.vv.NetManager.registerMsg(MsgId.REQ_PVP_SET_FORMATION, this.OnRcvPvpSetFormation, this);
        Global.registerEvent("HEROCARD_UPDATED", this.onCardUpate, this)
        cc.vv.NetManager.registerMsg(MsgId.PULL_LEVEL_UP_EXP, this.onRecvLevelupExp, this);

        for (let i = 0; i < 5; i++) {
            let nodePos = cc.find(cc.js.formatStr("pos%s/lock/suo_%s", (i + 1), (i + 1)), this._content)
            Global.btnClickEvent(nodePos, this.onClickUnlock, this)

        }
    },

    start() {

    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PVP_SET_FORMATION, this.OnRcvPvpSetFormation, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PULL_LEVEL_UP_EXP, this.onRecvLevelupExp, false, this);
    },

    createCard: function (cardInfo, idx) {
        let item = cc.instantiate(this.cardItem);
        item.active = true;
        item.isAlive = true;
        item.parent = this._content;
        item.posIdx = idx;  // 在哪个位置上
        item.zIndex = idx;
        item.position = this.getPosByIdx(idx);
        item.cardid = cardInfo.cardid;
        this._itemNodeList[idx] = item;

        item.getComponent('CH_Herocard_HallFormationItem').init(cardInfo, this._pageHeroScript, this);
    },

    onClickUnlock: function (event) {
        let lv = 2
        let clickNode = event.node
        if (clickNode) {
            lv = Number(clickNode.name.split("_")[1])
        }
        cc.vv.UserManager.goSystemUI("vip", { "lv": lv, "benfist": 5 })
    },

    initFormation: function (pageHeroScript) {
        this._pageHeroScript = pageHeroScript

        this.showUnlock(unlockCondition);

        let cartList = cc.vv.UserManager.getPvpDefendTeam();
        if (cartList && cartList.length > 0) {
            for (let i = 0; i < cartList.length; i++) {
                let cardInfo = cc.vv.HerocardManager.getCardInfo(cartList[i]);
                this.createCard(cardInfo, i + 1)
            }
        } else {
            let unlockedCardList = cc.vv.HerocardManager.getUnlockedCardList();
            for (let i = 0; i < this._posNodeList.length - 1; i++) {
                if (unlockedCardList[i]) {
                    let cardInfo = cc.vv.HerocardManager.getCardInfo(unlockedCardList[i].cardid);
                    this.createCard(cardInfo, i + 1)
                }
            }
            if (unlockedCardList.length > 0) {
                this.sendPvpSetFormation();
            }
        }
    },

    handleInfo: function (info) {
        // let list = cc.vv.HerocardManager.getCardListByCamp(info.campid);
        // for (let i = list.length-1;i >=0; i--){
        //     if(list[i].lv <= 0){
        //         list.splice(i,1)
        //     }
        // }

        let userLv = cc.vv.UserManager.getCurLv();
        let vipLv = cc.vv.UserManager.getVipLevel()
        info.bLock = !(userLv >= info.level /*&& list.length >= info.heroCnt*/);
        if (info.bLock) {
            if (vipLv >= info.vip) {
                info.bLock = false
            }
        }

        return info;
    },

    showUnlock: function (infoList) {
        let userLv = cc.vv.UserManager.getCurLv();
        let lockList = [];
        this._lockInfo = [];
        for (let i = 0; i < infoList.length; i++) {
            let info = infoList[i];
            lockList[i] = this.handleInfo(info);
            if (lockList[i].bLock) {
                this._lockInfo.push(lockList[i]);
            }
        }
        lockList.sort((a, b) => {
            return a.bLock - b.bLock;
        })
        let nodeVipTips = cc.find("vip_tip", this.node)
        let firstLockNode = null
        let curI = this._posNodeList.length > 1 ? this._posNodeList.length : 1;
        for (let i = 0; i < infoList.length; i++) {
            let info = lockList[i];
            let posNode = cc.find("content/pos" + (i + curI), this.node);
            if (firstLockNode == null && info.bLock) {
                firstLockNode = posNode
                Global.setLabelString("lbl", nodeVipTips, "vip " + info.vip)
            }
            cc.find("unlock", posNode).active = !info.bLock;
            cc.find("lock", posNode).active = info.bLock;
            if (info.bLock) {
                cc.find("lock/lv", posNode).getComponent(cc.Label).string = userLv + "/" + info.level;
                // cc.find("lock/zhenying", posNode).getComponent(cc.Sprite).spriteFrame = this.atlas.getSpriteFrame('zhenying_anniu_'+info.campid);
                // cc.find("lock/cnt", posNode).getComponent(cc.Label).string = info.curHeroCnt+"/"+info.heroCnt;
            } else {
                this._posNodeList[i + curI] = posNode;
            }
        }
        if (firstLockNode) {
            let tipPos = this.node.convertToNodeSpaceAR(firstLockNode.convertToWorldSpaceAR(cc.v2(0, 0)));
            nodeVipTips.x = tipPos.x
            nodeVipTips.active = true
            nodeVipTips.scale = 0
            cc.tween(nodeVipTips)
                .to(0.2, { scale: 1 }, { easing: "backOut" })
                .delay(2)
                .to(0.2, { scale: 0 })
                .call(() => {
                    nodeVipTips.active = false
                })
                .start()
        }
    },

    // 某个位置的默认position
    getPosByIdx: function (idx) {
        return cc.v2(this._posNodeList[idx].x, -this._norH / 2);
    },

    // 某个位置上的item
    getItemByIdx: function (idx) {
        return this._itemNodeList[idx];
    },

    getItemMinX: function () {
        return this._posNodeList[1].x
    },
    getItemMaxX: function () {
        return this._posNodeList[this._posNodeList.length - 1].x
    },

    changeItem(idx1, newItem1, idx2, newItem2) {
        if (idx1) {
            this._itemNodeList[idx1] = newItem1;
        }
        if (idx2) {
            this._itemNodeList[idx2] = newItem2;
        }

        // console.log(this._itemNodeList)
    },

    putItemAtPosIdx: function (item, posIdx) {
        this._itemNodeList[item.posIdx] = null

        let dir = item.posIdx > posIdx ? -1 : 1
        for (let idx = item.posIdx; idx != posIdx; idx += dir) {
            let fromIdx = idx + dir
            let it = this._itemNodeList[fromIdx]
            if (it) {
                it.posIdx = idx
                it.stopAllActions()
                it.runAction(cc.moveTo(0.25, this._posNodeList[idx].x, it.y))
                this._itemNodeList[idx] = it
            } else {
                this._itemNodeList[idx] = null
            }
        }

        item.posIdx = posIdx
        this._itemNodeList[item.posIdx] = item
    },

    // 移动item def=1:右移 def=-1左移
    // moveItem:function(item, def){
    //     let nextIdx = item.posIdx + def
    //     if (nextIdx < 1) nextIdx = this._posNodeList.length-1
    //     if (nextIdx > this._posNodeList.length-1) nextIdx = 1
    //     item.posIdx = nextIdx;
    //     item.stopAllActions()
    //     item.runAction(cc.moveTo(0.25, this._posNodeList[nextIdx].x, item.y))
    //     return nextIdx
    // },

    getIdxByPosX: function (posX, def = 1) {
        if (def > 0) {
            for (let i = 1; i <= this._posNodeList.length - 1; i++) {
                if (posX + this._norW / 2 >= this._posNodeList[i].x && posX - this._norW / 2 <= this._posNodeList[i].x) {
                    return i;
                }
            }
        } else {
            for (let i = this._posNodeList.length - 1; i >= 1; i--) {
                if (posX + this._norW / 2 >= this._posNodeList[i].x && posX - this._norW / 2 <= this._posNodeList[i].x) {
                    return i;
                }
            }
        }
    },

    addFormation: function (cardInfo) {
        for (let i = 1; i < this._itemNodeList.length; i++) {
            if (this._itemNodeList[i] && this._itemNodeList[i].cardid == cardInfo.cardid) {
                cc.vv.FloatTip.show(cc.vv.Language.herocard_formation1)//"Already in formation"
                return false;
            }
        }

        for (let i = 1; i < this._posNodeList.length; i++) {
            if (!this._itemNodeList[i]) {
                this.createCard(cardInfo, i)

                this.sendPvpSetFormation();
                return true
            }
        }

        cc.vv.FloatTip.show(cc.vv.Language.herocard_formation2)//"No more position"
        return false;
    },

    deleteFormation: function (cardid) {
        for (let i = 1; i < this._itemNodeList.length; i++) {
            if (this._itemNodeList[i] && this._itemNodeList[i].cardid == cardid) {
                this._itemNodeList[i].destroy();
                this._itemNodeList[i] = null;
                this.sendPvpSetFormation();
                return;
            }
        }
    },

    sendPvpSetFormation: function () {
        let list = [];
        for (let i = 1; i < this._itemNodeList.length; i++) {
            if (this._itemNodeList[i]) {
                list.push(this._itemNodeList[i].cardid)
            }
        }
        cc.vv.UserManager.setPvpDefendTeam(list);
        if (list.length > 0) {
            var req = { 'c': MsgId.REQ_PVP_SET_FORMATION };
            req.cardids = list;
            cc.vv.NetManager.sendAndCache(req, true);
        }
        Global.dispatchEvent("PVP_FORMATION_UPDATED")
    },

    OnRcvPvpSetFormation: function (msg) {
        if (msg.code == 200) {

        }
    },

    //更新卡片数据
    onCardUpate: function (data) {
        if (this._lockInfo.length > 0) {   // 格子没全解锁，判断是否可以解锁新的格子
            this.showUnlock(this._lockInfo)
        }
    },

    // 等级提升
    onRecvLevelupExp: function (msg) {
        if (msg.code == 200) {
            if (this._lockInfo.length > 0) {   // 格子没全解锁，判断是否可以解锁新的格子
                this.showUnlock(this._lockInfo)
            }
        }
    },

    // update (dt) {},
});
