let BTNSTR = {
    SEND: 'SEND',
    EXPRIED: 'EXPRIED',
    COLLECT: 'COLLECT',
};

let BTNPOS = {
    SEND: -192,
    EXPRIED: -140,
};

let TITLESTR = {
    GETCARD: 'Can you send me',
    THANKS: 'Thank you for sending me',
};

let TIMEPOS = {
    OTHER: -117,
    MYSELF: -160,
};

let TIPTYPE = {
    NOTFBBIND: 2,
    HASCHIPS: 3,
    NOTENOUGH: 4,
};

let UITYPE = {
    CANCOLLECT: 1,
    WAITTING: 2,
    OUTTIME: 3,
    SEND: 4,
    RIGHT: 5,
};

let RECTYPE = {
    WAITSEND: 0,
    HASSEND: 1, //可收集
    HASGET: 2,  //已经获得
};


cc.Class({
    extends: cc.Component,

    properties: {
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('sendBtn', this.node), this.onClick, this)
        Global.btnClickEvent(cc.find('btn_reject', this.node), this.onClickReject, this)
        this._cardId = 0

        this._inter = 0
        this._time = 0
        this.showRight(false)
        cc.vv.NetManager.registerMsg(MsgId.REQ_PRIVATE_GETCARD, this.onRcvPrivatePopCard, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_PRIVATE_SENDCARD, this.onRcvRejectSend, this)
    },

    start() {

    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PRIVATE_GETCARD, this.onRcvPrivatePopCard, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PRIVATE_SENDCARD, this.onRcvRejectSend, false, this)
    },

    initGiftChat(data, endCall) {
        if (data.id) {
            this.node._chatID = data.id
        }
        this._endCall = endCall
        this._serverData = data

        //需要时间 判断当前处于哪种状态 cardid
        let packInfo = data.packinfo

        this._cardId = packInfo.cardid
        //显示卡牌
        let cardicon = cc.find("card/icon", this.node)
        this._cardid = packInfo.cardid
        cc.vv.HerocardManager.loadFragmentHero(cardicon, packInfo.cardid)

        this.showTitle(TITLESTR.GETCARD)
        //my chips
        let cardInfo = cc.vv.HerocardManager.getCardInfo(this._cardId)
        if (cardInfo) {
            cc.find('lbl', this.node).getComponent(cc.Label).string = "My Chips:" + cardInfo.chips
        }

        // I18N.setI18nLabel(cc.find("lbl", this.node),cc.vv.Language["cardname_"+packInfo.cardid])        

        //三种状态  主动发送角度 不显示按钮   显示收集    显示过期
        //对方  显示send 显示过期
        //是否是主动发送
        this._uiType = 0
        let _str = ''
        if (Global.playerData.uid == data.uid) {
            if (packInfo.received == RECTYPE.HASSEND && packInfo.time) {
                //可收集
                this._uiType = UITYPE.CANCOLLECT
                _str = BTNSTR.COLLECT
                this.showTitle(TITLESTR.THANKS)
                cc.find('btn_reject', this.node).active = false
            } else if (packInfo.received == RECTYPE.HASGET) {
                this.getChips()
            } else if (packInfo.time) {
                //不可收集且有倒计时
                this._uiType = UITYPE.WAITTING
            } else {
                //过期
                this._uiType = UITYPE.OUTTIME
                _str = BTNSTR.EXPRIED
                if (packInfo.received == RECTYPE.HASSEND) {
                    this.showTitle(TITLESTR.THANKS)
                }
            }
        } else {
            if (packInfo.received == RECTYPE.HASSEND || packInfo.received == RECTYPE.HASGET) {
                this.getChips()
            } else if (packInfo.time) {
                this._uiType = UITYPE.SEND
                _str = BTNSTR.SEND
            } else {
                this._uiType = UITYPE.OUTTIME
                _str = BTNSTR.EXPRIED
            }
        }
        //按钮
        if (this._uiType) {
            this.showRight(false)
            this.btnEnable(_str)
            //时间
            this.showTime(packInfo.time)
            this._time = packInfo.time
        }
    },

    btnEnable(str) {
        let sendBtn = cc.find('sendBtn', this.node)
        sendBtn.active = this._uiType != UITYPE.WAITTING

        if (this._uiType != UITYPE.WAITTING) {
            sendBtn.getComponent(cc.Button).interactable = this._uiType == UITYPE.CANCOLLECT || this._uiType == UITYPE.SEND

            this.scheduleOnce(() => {
                Global.showSpriteGray(cc.find('Background', sendBtn), this._uiType == UITYPE.OUTTIME)
            }, 0.1)

            sendBtn.y = this._uiType == UITYPE.OUTTIME ? BTNPOS.EXPRIED : BTNPOS.SEND

            cc.find('lbl', sendBtn).getComponent(cc.Label).string = str
        }


    },

    showTime(flag) {
        let timeNode = cc.find('time', this.node)
        timeNode.active = flag
        if (flag) {
            this.updateTime(flag)
            // timeNode.y = this._uiType == UITYPE.WAITTING? TIMEPOS.MYSELF:TIMEPOS.OTHER
        }
    },

    updateTime(time) {
        Global.setLabelString('label', cc.find('time', this.node), Global.formatSec(time))
        if (time < 1) {
            this.showTime(false)
            this._uiType = UITYPE.OUTTIME
            this.btnEnable(BTNSTR.EXPRIED)
        }
    },

    onClick() {
        Global.playComEff("ch_btn_click")


        if (this._uiType == UITYPE.SEND) {
            let cardInfo = cc.vv.HerocardManager.getCardInfo(this._cardId)
            let type = TIPTYPE.NOTENOUGH
            if (cardInfo) {
                type = cardInfo.chips ? TIPTYPE.HASCHIPS : TIPTYPE.NOTENOUGH
                //可以送
                let req = { c: MsgId.REQ_PRIVATE_SENDCARD }
                req.chatid = this.node._chatID
                cc.vv.NetManager.send(req)
            }
            else {
                //不可以送
                cc.vv.FloatTip.show("You don't have the chip ")
            }
            // this.fbConnectPop(type)
        } else if (this._uiType == UITYPE.CANCOLLECT) {
            this.sendReqGetCard()
            this.getChips()
        }

    },

    onClickReject() {
        let req = { c: MsgId.REQ_PRIVATE_SENDCARD }
        req.reject = 1
        req.chatid = this.node._chatID
        cc.vv.NetManager.send(req)
    },

    onRcvRejectSend: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode) {

                if (msg.spcode == 1002) {
                    cc.vv.FloatTip.show("You don't have the chip ")
                }
                else {
                    cc.vv.FloatTip.show("Spcode: " + msg.spcode)
                }
            }
            else {
                if (msg.reject) {
                    Global.dispatchEvent("Reject_send", this._serverData.uid)
                }
                else {
                    Global.dispatchEvent("Reject_send", this._serverData.uid)
                }
            }
            if (this._endCall) {
                this._endCall()
            }



        }
    },

    onRcvPrivatePopCard: function (msg) {
        // id
        if (msg.code == 200 && msg.chatid == this.node._chatID) {
            //卡牌更新
            if (msg.rewards) {
                this.popReward(msg.rewards)
            }
        }
    },

    popReward: function (rd) {


        let self = this
        let nextCall = function () {
            Global.dispatchEvent("Collect_send", self._serverData.friendid)
            if (self._endCall) {
                self._endCall()
            }
        }
        cc.vv.UserManager.loadPopReward(rd, nextCall)
    },


    sendReqGetCard() {
        let req = { c: MsgId.REQ_PRIVATE_GETCARD }
        if (this.node._chatID) {
            req.chatid = this.node._chatID
        }
        cc.vv.NetManager.send(req)

        //本地更新聊天记录数据
        Global.dispatchEvent(EventId.REFRUSH_PRIVATE_CARD, { chatID: this.node._chatID })
    },

    fbConnectPop(type) {
        let _id = this.node._chatID
        let self = this

        cc.loader.loadRes("CashHero/prefab/CH_MailTipPop", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas");
                if (canvas.isValid && !cc.find('CH_MailTipPop', canvas)) {
                    let obj = cc.instantiate(prefab)
                    obj.parent = canvas
                    let callback = () => {
                        if (type == TIPTYPE.HASCHIPS) {
                            self.getChips()
                        }
                    }
                    obj.getComponent('CH_MailTipPop').setFrom(type, callback, _id)
                }
            }
        })
    },

    getChips() {
        this.showTime(false)
        this._time = 0
        cc.find('sendBtn', this.node).active = false
        this.showRight(true)

    },

    showRight(flag) {
        cc.find('right', this.node).active = flag

        if (flag) {
            this.showTitle(TITLESTR.THANKS)
        }
    },

    showTitle(str) {
        cc.find('title', this.node).getComponent(cc.Label).string = str
    },


    update(dt) {
        if (this._time) {
            this._inter += dt
            if (this._inter >= 1) {
                this._inter = 0
                this._time--
                this.updateTime(this._time)
            }
        }
    },
});
