let CDKEYTYPE = {
    SUCCESS: 1,
    DEFEATED: 2,
};

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        // spriteTitle:[cc.SpriteFrame],
        // arSpriteTitle:[cc.SpriteFrame],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_confirm = cc.find('confirmBtn', this.node)
        Global.btnClickEvent(btn_confirm, this.onClickConfirm, this)
    },

    start() { },

    //支持当前所有奖励领取
    setCdkeyType(cdkeyType, data, callback) {
        this._cdkeytype = cdkeyType
        if (cc.isValid(data.rewards)) {
            this._rewards = data.rewards
        }
        this._callback = callback
        let self = this
        // let titleNode = cc.find('title',this.node)
        // let changeCall = function(){
        //     if (Global.language==Global.LANGUAGE.EN) {
        //         titleNode.getComponent(cc.Sprite).spriteFrame = cdkeyType==CDKEYTYPE.SUCCESS?self.spriteTitle[0]:self.spriteTitle[2]
        //     }else {
        //         titleNode.getComponent(cc.Sprite).spriteFrame = cdkeyType==CDKEYTYPE.SUCCESS?self.arSpriteTitle[0]:self.arSpriteTitle[2]
        //     }
        // }
        // I18N.setI18SpriteChangeCall(titleNode,changeCall)
        // let txtNode = cc.find('txt1',this.node)
        // let txtChangeCall = function(){
        //     if (Global.language==Global.LANGUAGE.EN) {
        //         txtNode.getComponent(cc.Sprite).spriteFrame = cdkeyType==CDKEYTYPE.SUCCESS?self.spriteTitle[1]:self.spriteTitle[3]
        //     }else {
        //         txtNode.getComponent(cc.Sprite).spriteFrame = cdkeyType==CDKEYTYPE.SUCCESS?self.arSpriteTitle[1]:self.arSpriteTitle[3]
        //     }
        // }
        // I18N.setI18SpriteChangeCall(txtNode,txtChangeCall)
        // cc.find('error',this.node).active = cdkeyType==CDKEYTYPE.DEFEATED
        let iconNode = cc.find('icon', this.node)
        iconNode.active = cdkeyType == CDKEYTYPE.SUCCESS
        if (cdkeyType == CDKEYTYPE.SUCCESS) {
            let _curData = this.dataSort(data.rewards)
            let _cardCount = this.getCardNum(data.rewards)
            let _cardFlag = false
            for (let i = 0; i < 3; i++) {
                let item = cc.find("rewards" + (i + 1), iconNode)
                // item.active = _curData[i] && !_cardFlag
                if (_curData[i] && !_cardFlag) {
                    let rewardscp = cc.find("CH_reward_item", item).getComponent("CH_RewardItem")
                    let _count = _curData[i].type == Global.PROP_ID.HERO_CARD ? _cardCount : _curData[i].count
                    rewardscp.init(_curData[i].type, _count, true, true)
                    if (_curData[i].type == Global.PROP_ID.HERO_CARD) {
                        _cardFlag = true
                    }
                }
            }
        }
        this.showUIAnimation()
    },

    showUIAnimation: function () {
        let nLen = this._rewards.length
        let btn_confirm = cc.find('confirmBtn', this.node)
        btn_confirm.active = false
        for (let i = 0; i < nLen; i++) {
            let item = cc.find("icon/rewards" + (i + 1), this.node)
            item.scale = 0
            item.active = true
            cc.tween(item)
                .delay(i * 0.1)
                .to(0.1, { scale: 1 }, { easing: "backOut" })
                .call(() => {
                    if (i == nLen - 1) {
                        btn_confirm.active = true
                        btn_confirm.opacity = 0
                        cc.tween(btn_confirm)
                            .to(0.5, { opacity: 255 })
                            .start()
                    }
                })
                .start()
        }
    },

    //数据清洗 卡牌8 全部靠后 金币第一
    dataSort(data) {
        let sorFunc = function (a, b) {
            let aVal = 0
            if (a.type == Global.PROP_ID.COIN) {
                aVal = 1
            }
            let bVal = 0
            if (b.type == Global.PROP_ID.COIN) {
                bVal = 1
            }
            if (aVal != bVal) {
                return bVal - aVal
            }
            else {
                aVal = 0
                if (a.type == Global.PROP_ID.HERO_CARD) {
                    aVal = 1
                }
                bVal = 0
                if (b.type == Global.PROP_ID.HERO_CARD) {
                    bVal = 1
                }
                if (aVal != bVal) {
                    return aVal - bVal
                }
                else {
                    return a.type < b.type
                }
            }
        }
        data.sort(sorFunc)
        return data;
    },

    getCardNum(rd) {
        let num = 0
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.HERO_CARD) {
                num += rd[i].count
            }
        }
        return num
    },

    onClickConfirm() {
        cc.find('confirmBtn', this.node).getComponent(cc.Button).interactable = false
        if (this._cdkeytype == CDKEYTYPE.SUCCESS) {
            this.updateReward()
        } else {
            this.node.destroy()
        }
    },

    updateReward() {
        // let rdArr = []
        let rd = this._rewards
        let pos = cc.find("icon", this.node).convertToWorldSpaceAR(cc.v2(0, 0))
        Global.RewardFly(rd, pos, () => {
            this.node.destroy()
        })
        // for (let i = 0; i < rd.length; i++) {
        //     if (rd[i].type == Global.PROP_ID.COIN) {
        //         // cc.vv.UserManager.AddCoin(rd[i].count,true)
        //         //推了一次100057 因此只要更新金币即可
        //         Global.dispatchEvent(EventId.UPATE_COINS)
        //     }else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD) {
        //         rdArr.push(rd[i])
        //     }else if (rd[i].type == Global.PROP_ID.DIAMOND) {
        //         cc.vv.UserManager.AddDiamond(rd[i].count,true)
        //     }else {
        //         //活跃度不是物品 不更新
        //         if (rd[i].type == Global.PROP_ID.ACTIVITY) {
        //             continue
        //         }
        //         Global.dispatchEvent(EventId.COMM_ITEM_ADD,{id:rd[i].type,num:rd[i].count})
        //     }
        // }
        // if (rdArr.length > 0) {
        //     this.loadPopReward(rdArr)
        // }else {
        //     this.node.destroy()
        // }
    },

    // loadPopReward (rdArr) {
    //     let self = this
    //     let nextCall = function(){
    //         self.node.destroy()
    //     }
    //     cc.vv.UserManager.loadPopReward(rdArr,nextCall)
    // },

    onDestroy() {
        if (this._callback) {
            this._callback()
        }
    }

    // update (dt) {},
});
