cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
    },


    onLoad() {
        Global.onClick('btn_close', this.node, this.onClickClose, this)
        Global.onClick('btn_buy', this.node, this.onClickBuy, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_PVP_BUY_TICKET, this.onRcvNetBuyTicket, this)

        Global.playComEff("ch_popup_l2")
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PVP_BUY_TICKET, this.onRcvNetBuyTicket, false, this)
    },

    onRcvNetBuyTicket(msg) {
        if (msg.code == 200) {
            let url = 'CashHero/prefab/pop_reward'
            let self = this
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    let datas = [{ type: Global.PROP_ID.PVP_TICKET, count: 10 }]
                    node.getComponent('CH_popreward').showRewards(datas, () => {
                        self.node.destroy()
                    })
                }
            });
            cc.vv.UserManager.setDiamond(msg.diamond)
            Global.dispatchEvent("pvp_ticket_update", msg.fightInfo.restCnt)
        } else {
            cc.vv.AlertView.showSimple("Purchase failed")
        }
    },

    onClickBuy() {
        if (cc.vv.UserManager.getDiamond() < 500) {
            cc.vv.FloatTip.show(cc.vv.Language.pvp_des5);
            //    cc.vv.FloatTip.show("Insufficient Diamonds")
            return
        }
        cc.vv.NetManager.send({ c: MsgId.REQ_PVP_BUY_TICKET })
    },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.destroy();
    },

});
