/**
 * 限时优惠
 * 有服务器控制活动周期，一个周期内只能购买一次
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _purchaseData: null,  //充值数据

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, this);
        cc.vv.NetManager.registerMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, this);
    },

    start() {
        //请求协议
        var req = { 'c': MsgId.REQ_SHOP };
        req.uid = Global.playerData.uid;
        req.platform = 1;
        if (Global.isIOS()) {
            req.platform = 2
        }
        req.stype = 2
        cc.vv.NetManager.send(req);
    },

    initShow: function (data) {
        let _lbl_coin_was = cc.find('node_center/node_coin/lbl_coin_was', this.node);
        let _lbl_coin_now = cc.find('node_center/node_coin/lbl_coin_now', this.node);
        let _lbl_value = cc.find('node_center/btn_buy/Background/lbl_value', this.node);
        // let _lbl_vip = cc.find('node_center/node_vip/lbl_vip',this.node);
        this._lbl_clock = cc.find('node_center/node_clock/lbl_clock', this.node);
        Global.breathNode(this._lbl_clock)
        // let _lbl_discount = cc.find('node_center/node_discount/lbl_discount',this.node);
        _lbl_coin_was.getComponent(cc.Label).string = cc.js.formatStr('%s', Global.formatMoney(data.count * 100 / data.discount));
        _lbl_coin_now.getComponent(cc.Label).string = Global.formatMoney(data.count);
        _lbl_value.getComponent(cc.Label).string = cc.js.formatStr('$ %s', data.amount);
        // _lbl_vip.getComponent(cc.Label).string = cc.js.formatStr('+%s VIP POINTS',data.vipExp);
        // _lbl_discount.getComponent(cc.Label).string = cc.js.formatStr('%s%',data.discount);
        this.discountTime = data.discountTime;
        this.showDiscountTime();
        //benifist
        let btn = cc.find("node_center/btn_benifist", this.node)
        btn.getComponent('CH_Benifist_Btn').showBenifist(data.rewards, '限时礼包')
        // let btn_buy = cc.find("node_center/btn_buy",this.node)
        // btn_buy.active = this._roundFlag
        // let btn_close = cc.find("node_center/btn_close",this.node)
        // btn_close.active = this._roundFlag
        // let btn_benifist = cc.find("node_center/btn_benifist",this.node)
        // btn_benifist.active = this._roundFlag
        this.showActionBtns(this._roundFlag ? true : false)
        let lbl_mult = cc.find("node_center/node_discount/lbl_discount", this.node)
        lbl_mult.active = !this._roundFlag
        let spr_mult = cc.find("node_center/node_discount/spr_mult", this.node)
        spr_mult.active = this._roundFlag
        Global.shakeNodeR(spr_mult)
        _lbl_coin_now.active = this._roundFlag
        this.showWheel()
    },

    showWheel: function () {
        let self = this
        let nodeWheel = cc.find("node_center/normal_wheel", this.node)
        let endCall = function () {
            cc.vv.NetManager.send({ c: MsgId.CHOOSE_LIMIT_MULT })
            let fly_node = cc.find("node_center/normal_wheel/spr_multi", self.node)
            let toNode = cc.find("node_center/node_discount/spr_mult", self.node)
            let toPos = nodeWheel.convertToNodeSpaceAR(toNode.convertToWorldSpaceAR(cc.v2(0, 0)))
            cc.tween(fly_node)
                .to(0.5, { position: cc.v2(toPos.x, toPos.y) })
                .call(() => {
                    toNode.active = true
                    let lbl_mult = cc.find("node_center/node_discount/lbl_discount", self.node)
                    lbl_mult.active = false
                    cc.tween(nodeWheel)
                        .to(0.3, { opacity: 0 })
                        .start()
                    //滚金币
                    let lbl_coin = cc.find("node_center/node_coin/lbl_coin_now", self.node)
                    let finishCall = function () {
                        self.showActionBtns(true)
                    }
                    lbl_coin.active = true
                    Global.doRoallNumEff(lbl_coin, 0, self._purchaseData[0].count, 1.5, finishCall, null, 0, true)
                })
                .start()
        }
        nodeWheel.active = !this._roundFlag
        if (!this._roundFlag) {
            let scp = nodeWheel.getComponent("normal_wheel").showWhell(5, endCall)
        }
    },

    showActionBtns: function (bShow) {
        let btn_buy = cc.find("node_center/btn_buy", this.node)
        btn_buy.active = bShow
        let btn_close = cc.find("btn_close", this.node)
        btn_close.active = bShow
        let btn_benifist = cc.find("node_center/btn_benifist", this.node)
        btn_benifist.active = bShow
        let time_node = cc.find("node_center/node_clock", this.node)
        time_node.active = bShow
        let bg_wheel = cc.find("spr_wheel", this.node)
        bg_wheel.active = bShow
        if (bShow) {
            cc.tween(bg_wheel)
                .repeatForever(
                    cc.tween()
                        .by(3, { angle: -360 })
                        .delay(0.8)
                )
                .start()
        }
    },

    onRcvShopDetail: function (msg) {
        let self = this
        if (msg.code === 200) {
            if (msg.stype == 2) {
                this._purchaseData = msg.shoplist;
                this._roundFlag = msg.shoplist[0].rand
                self.initShow(msg.shoplist[0]);
            }
        }
    },

    //显示倒计时
    showDiscountTime: function () {
        var self = this;
        this.callback = function () {
            self._lbl_clock.getComponent(cc.Label).string = Global.formatSec(this.discountTime);
            if (self.discountTime <= 0) {
                this.unschedule(this.callback);
                this.onClickClose();
            }
            --self.discountTime;
        };
        this.schedule(this.callback, 1)
        self._lbl_clock.getComponent(cc.Label).string = Global.formatSec(this.discountTime);
    },

    //购买
    onClickPurchase: function () {
        if (this._purchaseData) {
            let productid = this._purchaseData[0].id;
            cc.vv.PayMgr.reqPurchaseOrder(productid);
        }
        else {
            console.log("没有充值数据");
        }
    },

    //关闭
    onClickClose: function () {
        this.node.destroy();
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, false, this);
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
    },

    //监听支付成功回调
    //支付校验成功
    onRcvMsgCheckOrder: function (msg) {
        if (msg.code === 200) {
            this.node.destroy();
        }
    },

});
