/**
 * 通用的加钱弹窗
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('spr_bg/btn_confirm', this.node), this.onClickConfirm, this);
        Global.playComEff("ch_popup_l2");
    },

    start() {
        Global.FixDesignScale_V(this.node)
        Global.showAlertAction(this.node, true, 0.1, this.node.scale, null);
    },

    setCoin: function (val, flyEndNode, closeCall) {
        let lblval = cc.find('spr_bg/coin_bg/lbl_coin', this.node)
        lblval.getComponent(cc.Label).string = Global.FormatNumToComma(val)

        this._flyEndNode = flyEndNode
        this._endCall = closeCall

        this._addCoin = val
    },

    onClickConfirm: function () {
        Global.playComEff("ch_collect");
        let self = this
        if (this._bFly) return
        this._bFly = true
        let flyEndCall = function () {
            if (self._endCall) {
                self._endCall()
            }
            Global.playComEff("ch_close");
            self.node.destroy()
        }

        let toNode = cc.find(Global.HALL_COIN_NODE_PATH)
        let lbladd = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        if (cc.vv.gameData) {
            toNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            lbladd = toNode
        }
        let rollData = {}
        rollData.lblCoin = lbladd
        rollData.addCoin = this._addCoin

        Global.FlyCoin(cc.find('spr_bg/coin_bg/lbl_coin', this.node), toNode, flyEndCall, rollData, true)
    },

    // update (dt) {},
});
