let BuyRewardType = {
    BingoGift: 1,
    BingoBuff: 2,
    Hummer: 3,
    Card: 4,
}

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.isHummerFlag = false
        let yeahBtn = cc.find('yeahBtn', this.node)
        Global.btnClickEvent(yeahBtn, this.yeahBtn, this)
    },

    start() { },

    //tip
    setTip() {
        cc.find('tip', this.node).active = true
    },

    //bingoGift
    buyBingoGIft(msg) {
        this.setTip()
        cc.find('bingoGift', this.node).active = true
        this.buyType = BuyRewardType.BingoGift
        this._msg = msg
        this._rd = msg.rewards
    },

    //bingoBuff
    buyBingoBuff(msg) {
        this.setTip()
        cc.find('bingoBuff', this.node).active = true
        this.buyType = BuyRewardType.BingoBuff
        this._msg = msg
        this._rd = msg.rewards
    },

    //buyHummer
    buyHummer(msg) {
        let hummer = cc.find('hummer', this.node)
        hummer.active = true
        cc.find("silver", hummer).active = (msg.stype == 1)
        cc.find("gold", hummer).active = (msg.stype == 2)
        cc.find("zi", hummer).getComponent(cc.Label).string = 'X' + msg.add
        this.isHummerFlag = true
        this._msg = msg
        this.buyType = BuyRewardType.Hummer
    },

    popHummer() {
        let self = this
        cc.loader.loadRes("CashHero/prefab/lucky_smash/lucky_hummer", cc.Prefab, (err, prefab) => {
            let canvas = cc.find("Canvas")
            if (!err && !canvas.getChildByName("lucky_hummer")) {
                let node = cc.instantiate(prefab)
                node.name = "lucky_hummer"
                node.parent = canvas
                let endCall = function () {
                    self.popRewards(self._msg.rewards)
                }
                node.getComponent("LuckySmash_Hummer").setType(self._msg.stype, self._msg.add, endCall)
            }
        })
    },

    //buyCard
    buyCard(msg) {
        cc.find('heart', this.node).active = true
        Global.setLabelString("heart/lbl_num", this.node, "X" + msg.add)
        this.buyType = BuyRewardType.Card
        this.rd = msg.rewards
    },

    popRewards(rd) {
        let self = this
        let nextCall = function () {
            self.node.destroy()
        }
        cc.vv.UserManager.loadPopReward(rd, nextCall)
    },

    yeahBtn() {
        this.node.active = false
        if (this.buyType == BuyRewardType.Hummer) {
            this.popHummer()
        } else {
            if (this._rd) {
                this.popRewards(this._rd)
            }
            else {
                this.node.destroy()
            }
        }
    },

    // update (dt) {},
});
