/**
 * sloticon显示
 */
let __Game_Item_Config__ = require("GameItemCfg");

cc.Class({
    extends: cc.Component,

    properties: {
        spr_icon: cc.Node,
        // bUseCfgScale:true,
        _gameId: null,
        _spineScale: null,
        _cfg: null,
        _loadAni: null,
        _itemIdx: null,
    },

    onLoad() {
        let spine = cc.find('spine', this.node);
        this._spineScale = spine.scale
    },

    start() { },

    //设置游戏id
    setGameId: function (gameId, ani) {
        this._gameId = gameId
        this._loadAni = ani
        let icon = cc.find('icon', this.node)
        icon.active = false
        let spine = cc.find('spine', this.node);
        spine.active = false
        this._cfg = __Game_Item_Config__[gameId]
        if (this._cfg && this._cfg.animation) {
            this.LoadIconAnimation()
        }
        else {
            this.LoadIcon()
        }
    },

    // //设置回收时的序号
    // setRecyIdx:function(idx){
    //     this._itemIdx = idx
    // },

    _getIconUrl(cfg) {
        return "CashHero/slots/icon/" + cfg.action
    },

    _getAnimationUrl(cfg) {
        return "CashHero/slots/icon/" + cfg.action + "/spine"
    },

    // _getTitleUrl(cfg) {
    //     return "CashHero/slots/icon/"+ cfg.action +"/biaotidonghua"
    // },

    //静态icon
    LoadIcon: function () {
        let icon = cc.find('icon', this.node)
        // icon.active = false
        if (!icon) {
            icon = this.spr_icon
        }
        let cfg = this._cfg
        if (!cfg) {
            console.warn(cc.js.formatStr('>>>> %s 未配置GameItemCfg', this._gameId))
            icon.active = false
            return
        }
        //配置了动画就不现实静态背景图
        if (cfg.animation) {
            return
        }
        // let frameSpr = cc.find('icon_frame',this.node)
        // if(frameSpr){
        //     frameSpr.active = true
        // }
        cc.loader.loadRes(this._getIconUrl(cfg), cc.SpriteFrame, (err, data) => {
            if (cc.isValid(icon, true)) {
                if (!err) {
                    icon.getComponent(cc.Sprite).spriteFrame = data;
                    icon.active = true
                    if (icon.anchorY == 0) {
                        if (cfg.staOffsetY || !cfg.animation) {
                            icon.y = cfg.staOffsetY || -27;
                        } else {
                            icon.y = 0.45;
                        }
                    }
                    // if (!cfg.animation) {
                    //     if(frameSpr){
                    //         frameSpr.active = false
                    //     }
                    // }
                } else {
                    icon.active = false
                }
            }
        });
    },

    LoadIconAnimation: function () {
        let self = this
        let spine = cc.find('spine', this.node);
        let icon = cc.find('icon', this.node)
        // if(spine){
        //     spine.active = false;
        // }
        let cfg = this._cfg
        if (!cfg) {
            console.log(cc.js.formatStr('>>>> %s未配置GameItemCfg', this._gameId))
            return
        }
        if (!cfg.animation) {
            return;
        }
        let iconUrl = this._getAnimationUrl(cfg)
        // console.log(">>>> config: ", cfg)
        // console.log(">>>> icon url: ", iconUrl)
        // console.log(">>>> Game Item: ", cfg.title)
        //方式：直接加载
        // cc.loader.loadRes(iconUrl, sp.SkeletonData, (err, data) => {
        //     if (!err && cfg && cfg.animation && cc.isValid(spine,true)) {
        //         //如果外部设置了动画优先显示
        //         let showAni = this._loadAni? this._loadAni:cfg.animation
        //         icon.active = false
        //         spine.active = true;
        //         let ske = spine.getComponent(sp.Skeleton);
        //         ske.skeletonData = data;
        //         ske.setAnimation(0, showAni, true);
        //         //入口动态回收
        //         if(cc.js.isNumber(self._itemIdx)){
        //             let tSave = {}
        //             tSave.dir = iconUrl.substring(0,iconUrl.length-1 - 5)
        //             tSave.res = data
        //             tSave.idx = self._itemIdx
        //             cc.vv.UserManager.setHallIconSpin(tSave)
        //         }
        //     }
        // });

        //按队列加载
        cc.vv.UserManager.loadSlotIconByQueue(spine, iconUrl, sp.SkeletonData, (err, data) => {
            if (!err && cfg && cfg.animation && cc.isValid(spine, true)) {
                //如果外部设置了动画优先显示
                let showAni = this._loadAni ? this._loadAni : cfg.animation
                icon.active = false
                spine.active = true;
                let ske = spine.getComponent(sp.Skeleton);
                ske.skeletonData = data;
                ske.setAnimation(0, showAni, true);
            }
        })
    },

    // update (dt) {},
});
