cc.Class({
    extends: cc.Component,

    statics: {
        //单例的初始化
        Init: function () {
            cc.vv.NetManager.registerMsg(MsgId.SAVE_GUIDE_ID, this.recvSaveGuideId, this);
            let callbacks = function () { }
            this._loadPrefab(callbacks)
        },

        //显示引导
        //return 是否已经做过这个引导 true已经做过
        ShowGuide: function (id, endCall, lblParm) {
            let self = this
            this._compCall = endCall
            this._lblParm = lblParm
            let bDone = this._isDoneGuide(id)
            if (!bDone) {
                if (this.GetCurGuideId() != id) {
                    this.SetCurGuideId(id)
                    this._guideStepIdx = 0
                    this.ShowGuideByStep(this._guideStepIdx)
                }
                else {
                    console.log(cc.js.formatStr('引导%s在执行中了', id))
                }
            }
            return true //bDone
        },

        ShowGuideByStep: function (nStep) {
            let id = this.GetCurGuideId()
            let guideCfg = this._getGuideCfg(id, nStep)
            if (guideCfg) {
                if (this._lblParm) {
                    guideCfg.lblParm = this._lblParm;
                }
                //屏蔽点击
                this.SetIsLoadingGuide(true)
                if (guideCfg.BeforeCall) {
                    guideCfg.BeforeCall()
                }
                let delayVal = 0
                if (guideCfg.delayTime) {
                    delayVal = guideCfg.delayTime
                }
                cc.tween(cc.find('Canvas'))
                    .delay(delayVal)
                    .call(() => {
                        let nType = guideCfg.type
                        let old = cc.find('Canvas/NewGuide')
                        if (old) {
                            old.destroy()
                        }
                        console.log(cc.js.formatStr('>>>> 开始引导( %s ), 步骤( %s )', id, nStep))
                        let callbacks = function (prefab) {
                            let node = cc.instantiate(prefab)
                            node.parent = cc.find('Canvas')
                            if (nType == 4) {
                                node.getComponent('RoleTip').ShowMsg(id, guideCfg)
                            }
                            else {
                                node.getComponent('NewGuide').init(id, guideCfg)
                            }
                        }
                        this._loadPrefab(callbacks, nType)
                    })
                    .start()
            }
            else {
                //都做完了
                this.DoComplete(id)
            }
        },

        //关闭引导
        CloseGuide: function () {
            let guideNode = cc.find('Canvas/NewGuide')
            if (guideNode) {
                guideNode.getComponent('NewGuide').CloseUI()
            }
        },

        //角色引导的界面，有时候非引导的时候需要单独显示
        ShowGuideRoleTip: function (str) {
            let callbacks = function (prefab) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                node.getComponent('RoleTip').ShowStr(str)
            }
            this._loadPrefab(callbacks, 4)
        },

        //是否是在加载引导，如果是需要屏蔽点击
        GetIsLoadingGuide: function () {
            return this._bLoading
        },
        SetIsLoadingGuide: function (val) {
            this._bLoading = val
        },

        //设置当前的引导id
        SetCurGuideId: function (id) {
            this._curGuide = id
        },

        //获取当前的引导id 可用于判断当前是否是引导模式
        GetCurGuideId: function () {
            return this._curGuide
        },

        //保存已经完成的任务id
        SaveCompleteGuide: function (id) {
            this.CloseGuide()
            //执行引导完成的回调
            let guideCfg = this._getGuideCfg(id, this._guideStepIdx)
            if (guideCfg && guideCfg.CopleteCall) {
                guideCfg.CopleteCall()
            }
            this._guideStepIdx++
            this.ShowGuideByStep(this._guideStepIdx)
        },

        //跳过引导
        SkipTheGuide: function (skiplist) {
            this.CloseGuide()
            this.DoComplete(skiplist)
        },

        SetGuideTempData: function (val) {
            this._tempVal = val
        },
        GetGuideTempData: function () {
            return this._tempVal
        },

        //更新引导数据
        DoComplete: function (id, bOnlySave) {
            if (this._isDoneGuide(id)) return
            let datas = id
            if (!Array.isArray(id)) {
                datas = [id]
            }
            //引导完成打点
            cc.vv.PlatformApiMgr.KoSDKTrackEvent('af_tutorial_completion' + id, JSON.stringify({ af_success: 1, af_content_id: id }))
            cc.vv.UserManager.saveCompleteGuideId(id)
            if (!bOnlySave) {
                this.SetCurGuideId(null)
            }
            if (this._compCall) {
                this._compCall()
                this._compCall = null
            }
            //通知服务端
            let req = { c: MsgId.SAVE_GUIDE_ID };
            req.step = datas;
            cc.vv.NetManager.sendAndCache(req, true);
        },

        //是否已经做过id的引导
        _isDoneGuide: function (id) {
            if (Global.closeGuide) return true
            let cfg = GuideCfg[id]
            if (cfg) {
                let commleteGuide = cc.vv.UserManager.getCompleteGuide()
                for (let i = 0; i < commleteGuide.length; i++) {
                    if (id == commleteGuide[i] || cfg.preGuideId == commleteGuide[i]) {
                        return true
                    }
                }
            }
            return false
        },

        _loadPrefab: function (callbacks, type = 1) {
            let url = 'CashHero/NewGuide/NewGuide'
            if (type == 4) {
                url = 'CashHero/NewGuide/RoleTip'
            }
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    callbacks(prefab)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        },

        /**
         * 获取引导配置
         * @param {*} id 
         */
        _getGuideCfg: function (id, nStep) {
            let val = GuideCfg[id]
            if (!val) {
                console.log('未找到引导配置:' + id)
            }
            if (Array.isArray(val)) {
                return val[nStep]
            }
            else {
                let temp = []
                temp.push(val)
                return temp[nStep]
            }
        },

        recvSaveGuideId: function (msg) {
            if (msg.code == 200) {
            }
        },
    },
});
