cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    //碰撞
    onCollisionExit: function (other, self) {
        self.node.stopAllActions();
        let that = this;

        let angle = 30;

        let d = Math.abs(2 * self.node.height * self.node.anchorY * Math.sin(Math.PI * (angle - self.node.angle) / 180));
        self.node.runAction(cc.sequence(
            cc.callFunc(() => { Global.playEff(Global.SOUNDS.sound_wheel_pointer); }),
            cc.rotateTo(d / 1000, -angle),
            cc.rotateTo(0.1, 0)
        ));
    },

    // update (dt) {},
});
