/**
 * shop - 金猪
 */

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClickGiftBank, this);
        Global.btnClickEvent(cc.find('buy_btn', this.node), this.onClickGiftBank, this);
        Global.btnClickEvent(cc.find('btn_quest', this.node), this.onClickPigBankQuest, this)
    },

    start() {

    },

    initData: function (data) {
        this._pigData = data

        let initCoin = data.ext.bagCnt
        let addCoin = data.ext.bankedCnt
        let maxCoin = data.ext.maxCnt
        let firstcoin = data.ext.firstCnt



        let lblCoin = cc.find('total_coin_text/val', this.node)
        lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(initCoin + addCoin + firstcoin)
        //price
        cc.find("buy_btn/lbl_text", this.node)
        Global.setLabelString("buy_btn/lbl_text", this.node, "Only $" + data.oamount)

        let lblMax = cc.find('MAXED', this.node)

        let bMax = addCoin >= maxCoin


        lblMax.active = bMax

        //保存一份数据用于游戏内刷新
        let saveData = {}
        saveData.bagfull = bMax
        cc.vv.UserManager.setPigbankData(saveData)
    },

    //Money Bank
    onClickGiftBank() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_PIGBANK)
        if (this._pigData) {
            cc.vv.PayMgr.reqPurchaseOrder(this._pigData.id);
        }

    },

    onClickPigBankQuest() {
        let nodePigPlayway = cc.find('playway', this.node)
        if (nodePigPlayway.getNumberOfRunningActions() == 0) {
            nodePigPlayway.opacity = 0
            nodePigPlayway.active = true
            cc.tween(nodePigPlayway)
                .show()
                .to(0.3, { opacity: 255 })
                .delay(3)
                .to(1, { opacity: 0 })
                .hide()
                .start()
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_PIGBANK_HELP)
    },

    // update (dt) {},
});
