let endEffect = ["wheel_stop17", "wheel_stop3", "wheel_stop12", "wheel_stop22", "wheel_stop8", "wheel_stop9", "wheel_stop17", "wheel_stop5", "wheel_stop12", "wheel_stop15", "wheel_stop8", "wheel_stop10"]
cc.Class({
    extends: cc.Component,

    properties: {
        _roleNode: null,
        _superRoleNode: null,
        _zhizhen: null,
        _zhizhenEffect: null,
        _freezhuanpan: null,
        _zhuanpanxuanzhong: null,
        _huanqipan: null,
    },

    onLoad() {
        this._roleNode = cc.find("spinNode", this.node)
        this._zhizhen = cc.find("theme224_wheel_pointer", this.node)
        this._zhizhenEffect = cc.find("superxuanzhong", this.node)
        this._superRoleNode = cc.find("superSpinNode", this.node)
        this._freezhuanpan = cc.find("freezhuanpan", this.node)
        this._zhuanpanxuanzhong = cc.find("zhuanpanxuanzhong", this.node)
        this._huanqipan = cc.find("huanqipan", this.node)
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    show() {
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_appear)
        this.node.active = true
        this._zhizhen.opacity = 0
        this._zhizhenEffect.opacity = 0
        cc.tween(this._zhizhen).to(0.2, { opacity: 255 }).start()
        cc.tween(this._zhizhenEffect).to(0.2, { opacity: 255 }).start()
        this._roleNode.active = true
        this._roleNode.scale = 0
        this._superRoleNode.active = false
        cc.tween(this._roleNode).to(0.5, { scale: 1 }).start()
    },

    showSuper() {
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.fgwheel_appear)
        this.node.active = true
        this._zhizhen.opacity = 0
        this._zhizhenEffect.opacity = 0
        cc.tween(this._zhizhen).to(0.2, { opacity: 255 }).start()
        cc.tween(this._zhizhenEffect).to(0.2, { opacity: 255 }).start()
        this._superRoleNode.active = true
        this._superRoleNode.scale = 0
        this._roleNode.active = false
        cc.tween(this._superRoleNode).to(0.5, { scale: 1 }).start()
    },

    changeZhuanPan() {
        this._superRoleNode.scale = 1
        this._superRoleNode.active = true
        this._roleNode.scale = 0
        this._roleNode.active = false
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_change)
        cc.tween(this._superRoleNode).to(0.5, { scale: 0 }).call(() => {
            this._superRoleNode.active = false
            this._huanqipan.active = true
            let huanqipanSp = this._huanqipan.getComponent(sp.Skeleton)
            huanqipanSp.setCompleteListener(() => {
                this._huanqipan.active = false
                huanqipanSp.setCompleteListener(null)
            })
            this._roleNode.scale = 0
            this._roleNode.active = true
            cc.tween(this._roleNode).to(0.5, { scale: 1 }).start()
        }).start()
    },

    hide() {
        if (this._superRoleNode.active) {
            cc.tween(this._superRoleNode).to(0.5, { scale: 0 }).call(() => {
                this.node.active = false
            }).start()
        }
        if (this._roleNode.active) {
            cc.tween(this._roleNode).to(0.5, { scale: 0 }).call(() => {
                this.node.active = false
            }).start()
        }
    },

    spineToResult(result) {
        return new Promise((sucess, failed) => {
            this._roleNode.stopAllActions()
            this._roleNode.angle = this._roleNode.angle % 360
            let angle = this._roleNode.angle + 18
            let finalAngle = (result - 1) * -30 - 360 * 3
            this._freezhuanpan.active = true
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_spin)
            cc.tween(this._roleNode).to(0.7, { angle: angle }, { easing: "quadOut" }).to(3, { angle: finalAngle - 9 }, { easing: "quadInOut" }).to(0.7, { angle: finalAngle }, { easing: "quadOut" }).call(() => {
                this._roleNode.angle = this._roleNode.angle % 360
                this._freezhuanpan.active = false
                this._zhuanpanxuanzhong.active = true
                let zhuanpanxuanzhongSp = this._zhuanpanxuanzhong.getComponent(sp.Skeleton)
                zhuanpanxuanzhongSp.setCompleteListener(() => {
                    this._zhuanpanxuanzhong.active = false
                    zhuanpanxuanzhongSp.setCompleteListener(null)
                })
                if (result == 1 || result == 5 || result == 9) {
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_jp)
                } else {
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame_appear)
                }
                Global.SlotsSoundMgr.playEffect(endEffect[result - 1])
                sucess()
            }).start()
        })
    },

    superSpineToResult(result) {
        return new Promise((sucess, failed) => {
            this._superRoleNode.stopAllActions()
            this._superRoleNode.angle = this._superRoleNode.angle % 360
            let angle = this._superRoleNode.angle + 18
            let finalAngle = (result - 1) * -30 - 360 * 5
            this._freezhuanpan.active = true
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.superwheel_spin)
            cc.tween(this._superRoleNode).to(0.7, { angle: angle }, { easing: "quadOut" }).to(3, { angle: finalAngle - 9 }, { easing: "quadInOut" }).to(0.7, { angle: finalAngle }, { easing: "quadOut" }).call(() => {
                this._superRoleNode.angle = this._superRoleNode.angle % 360
                this._freezhuanpan.active = false
                this._zhuanpanxuanzhong.active = true
                let zhuanpanxuanzhongSp = this._zhuanpanxuanzhong.getComponent(sp.Skeleton)
                zhuanpanxuanzhongSp.setCompleteListener(() => {
                    this._zhuanpanxuanzhong.active = false
                    zhuanpanxuanzhongSp.setCompleteListener(null)
                })
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame_appear)
                sucess()
            }).start()
        })
    },

    // update (dt) {},
});
