
cc.Class({
    extends: cc.Component,

    properties: {
        _data: null,
        _t: 0,
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_PVP_FIGHT, this.OnRcvPvpFight, this)
        cc.vv.AudioManager.stopBgm()
        Global.playCashEff("pvp/pk_match")

        let spine = cc.find("spine", this.node).getComponent(sp.Skeleton)
        spine.setAnimation(0, "animation", false)
        spine.addAnimation(0, "animation2", true)

        let nodename = ["left", "right"]
        for (let i = 0; i < 2; i++) {
            let node = cc.find(nodename[i], this.node)
            node.opacity = 0
            cc.tween(node)
                .delay(0.5)
                .to(0.5, { opacity: 255 }, { easing: "sineOut" })
                .start()
        }
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PVP_FIGHT, this.OnRcvPvpFight, false, this)
    },

    init(opponentInfo, cardids, revenge = 0) {
        cc.vv.NetManager.send({ c: MsgId.REQ_PVP_FIGHT, ouid: opponentInfo.uid, cardids: cardids, revenge: revenge })

        this._players = []
        this._players.push({
            playername: cc.vv.UserManager.getNickName(),
            uid: cc.vv.UserManager.uid,
            usericon: cc.vv.UserManager.userIcon
        })
        this._players.push(opponentInfo)

        let nodename = ["left", "right"]
        for (let i = 0; i < 2; i++) {
            let node = cc.find(nodename[i], this.node)
            let player = this._players[i]
            Global.setLabelString("lbl_name", node, player.playername)
            node.getComponentInChildren("UserHead").setHead(player.uid, player.usericon)
        }
    },

    OnRcvPvpFight: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode == 0) {
                let UM = cc.vv.UserManager
                let beforeRank = UM.getPvpRank()
                this._data = msg.data
                this._result = {
                    res: msg.data.res,
                    beforeRank: beforeRank,
                    curRank: msg.rank,
                    curScore: msg.curScore,
                    addScore: msg.score,
                    rewards: msg.rewards,
                }
                UM.setPvpRank(msg.rank)
                UM.setPvpScore(msg.curScore)
                Global.dispatchEvent("pvp_rank_score_update")
            } else {
                if (msg.spcode == 1006) {
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_card_not_exist);
                    // cc.vv.FloatTip.show("Card not exist")
                } else if (msg.spcode == 1013) {
                    cc.vv.AlertView.showTips("The season is over")
                } else {
                    // cc.vv.FloatTip.show("Wrong battle info with spcode: " + msg.spcode)
                    cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_wrong_battle_spcode, msg.spcode));
                }
                this.node.destroy()
                Global.playBgm(Global.SOUNDS.bgm_herocard)
                Global.dispatchEvent("pvp_battle_close")
            }
        } else {
            // cc.vv.FloatTip.show("Error with code: " + msg.code)
            cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_error_code, msg.code));
            this.node.destroy()
            Global.playBgm(Global.SOUNDS.bgm_herocard)
            Global.dispatchEvent("pvp_battle_close")
        }
    },

    async startFight(players, data, result) {
        let prefab = await new Promise((res) => {
            let url = 'CashHero/prefab/pvp/pvp_battle'
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    res(prefab)
                } else {
                    res(null)
                }
            });
        })
        let battle = cc.find('Canvas').getChildByName('pvp_battle')
        if (!battle) {
            battle = cc.instantiate(prefab)
            battle.parent = cc.find('Canvas')
        }
        battle.opacity = 0
        battle.runAction(cc.sequence(cc.delayTime(0.5), cc.fadeIn(0.3)))
        battle.getComponent("Pvp_Battle").play(players, data, result)

        this.node.setSiblingIndex(battle.getSiblingIndex() + 1)
        let spine = cc.find("spine", this.node).getComponent(sp.Skeleton)
        spine.setAnimation(0, "animation3", false)
        let nodename = ["left", "right"]
        for (let i = 0; i < 2; i++) {
            let node = cc.find(nodename[i], this.node)
            cc.tween(node)
                .to(0.5, { opacity: 0 }, { easing: "sineIn" })
                .start()
        }
        this.node.runAction(cc.sequence(cc.delayTime(0.3), cc.fadeOut(0.2), cc.destroySelf()))
    },

    update(dt) {
        this._t += dt
        if (this._t > 2 && this._data) {
            this._t = -10
            this.startFight(this._players, this._data, this._result)
        }
    },
});
