    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnSend = cc.find("lay_btns/btn_send", this.node)
        Global.btnClickEvent(btnSend, this.onClickSend, this)

        let btnRecv = cc.find("lay_btns/btn_recv", this.node)
        Global.btnClickEvent(btnRecv, this.onClickRecv, this)

        let btnHead = cc.find('node_head', this.node)
        Global.btnClickEvent(btnHead, this.onClickDetail, this)

        let btnDel = cc.find('btn_del', this.node)
        Global.btnClickEvent(btnDel, this.onClickDelFriend, this)

        Global.registerEvent("Reject_send", this.onEventRejectSend, this)
        Global.registerEvent("Collect_send", this.onEventCollectSend, this)

        Global.registerEvent("friend_del_model", this.onEventDelModel, this)


    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.FRIEND_PRESENT, this.onRcvSendGift, this);
        cc.vv.NetManager.registerMsg(MsgId.GET_JACKPOT, this.onRcvCollectJackpot, this);
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.FRIEND_PRESENT, this.onRcvSendGift, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.GET_JACKPOT, this.onRcvCollectJackpot, false, this);
    },

