    _showRequestNum() {
        let btnChat = cc.find('lay_btns/btn_chat', this.node)
        btnChat.active = true
        let bOpen = (this._itemData.level >= Global.SYS_OPEN.HERO_CARD) && cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)
        let node_lock = cc.find('node_lock', btnChat)
        node_lock.active = !bOpen
        if (bOpen) {
            let red_quest = cc.find("red", btnChat)
            let req_num = this._bHasGiftRequest()
            red_quest.active = req_num > 0
            Global.setLabelString("num", red_quest, req_num)
        }
    },

    //是否有可以领取或者send的请求
    _bHasGiftRequest() {
        let nCount = 0
        if (this._itemData.seek_card) {
            nCount += 1
        }
        if (this._itemData.self_seek && this._itemData.self_seek.status == 1) {
            nCount += 1
        }
        return nCount
    },

    onClickSend: function () {
        if (this._bSendReq) return
        Global.playComEff("ch_send");
        this._bSendReq = true
        let req = { c: MsgId.FRIEND_PRESENT };
        req.frienduid = this._itemData.uid;
        cc.vv.NetManager.send(req);
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_FRIENDS_SEND)
    },

    onClickRecv: function () {
        if (this._bRecvReq) return
        Global.playComEff("ch_collect");
        this._bRecvReq = true
        let req = { c: MsgId.GET_JACKPOT };
        req.frienduid = this._itemData.uid;
        cc.vv.NetManager.send(req);
        cc.vv.RedSys.changeRed(8, -1)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_FRIENDS_COLLECT)
    },

    onClickDetail: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_FRIENDS_COLLECTALL_OUT)
        let req = { c: MsgId.PERSIONAL_INFO };
        req.otheruid = this._itemData.uid
        req.act = 2
        cc.vv.NetManager.sendAndCache(req);
    },

