    isStaticKuang(idx) {
        for (let i = 0; i < this._staticKuang.length; i++) {
            const element = this._staticKuang[i];
            if (element === idx) {
                return true
            }
        }
        return false
    },

    speedUp(colIdx) {
        if (this._showJiLi) {
            let needSpeedUp = false
            for (let i = 0; i < this._reels.length; i++) {
                let idx = this._reels[i].GetReelIdx()
                if (idx == colIdx) {
                    //播放框激励动画
                    needSpeedUp = cc.vv.gameData.getStayKuang().playJiLiDonghua(colIdx)
                    if (needSpeedUp) {
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.anticipation)
                    }
                }
                if (idx > colIdx - 1 && needSpeedUp) {//加速显示的时候，多转1s
                    let nAddSpeedTime = cc.vv.gameData.getGameCfg().AddAntiTime || 1
                    this._reels[i].AddDelayTime(nAddSpeedTime)
                }
            }
        }
    },

    //重写
    //配置了加速节点才显示，如果点击了立即停止(_bStopRightnow)也不显示了。
    //每列停止后，会自动隐藏加速节点
    DoCheckReelAnti: function (colIdx) {
        if (!this._bStopRightnow) {
            this.speedUp(colIdx + 1)
        }
        if (this._showJiLi && colIdx === 3) {
            this.showJiLiBg()
        }
    },

    showShake(time, x, y) {
        return new Promise(async (sucess, failed) => {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.big_win)
            this.node.runAction(cc.shake(time, x, y))
            let nvhuangSp = this._nvhuang.getComponent(sp.Skeleton)
            nvhuangSp.setAnimation(0, "skill01", false)
            nvhuangSp.addAnimation(0, "idle", true)
            let kuangzhendong = cc.find("kuangzhendong", this.node)
            kuangzhendong.active = true
            await this.awaitTime(time)
            kuangzhendong.active = false
            sucess()
        })
    },

    playScatterLanding() {
        this._scatterNum++
        if (this._scatterNum > 5) {
            this._scatterNum = 5
        }
        Global.SlotsSoundMgr.playEffect("scatter" + this._scatterNum + "_landing")
    },

    playFrameAppear() {
        if (this._isPlayFrameAppear) {
            return
        }
        this._isPlayFrameAppear = true
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame_appear)
    },

    showRandomAddKuang(idxList) {
        return new Promise(async (sucess, failed) => {
            let sortArray = (a, b) => {
                let acol = (a - 1) % this._col
                let bcol = (b - 1) % this._col
                if (acol == bcol) {
                    return a - b
                } else {
                    return acol - bcol
                }
            }
            idxList.sort(sortArray)
            for (let i = 0; i < idxList.length; i++) {
                const idx = idxList[i];
                if (i == 0) {
                    cc.vv.gameData.getStayKuang().showKuangExFirst(idx)
                } else {
                    await cc.vv.gameData.getStayKuang().showKuangEx(idxList[i - 1], idx)
                }
            }
            sucess()
        })
    },

    showJPJL(jpid) {
        this._jpjl.active = true
        let jpjlSp = this._jpjl.getComponent(sp.Skeleton)
        jpjlSp.setAnimation(0, "animation" + (jpid - 1) + "_4", false)
        jpjlSp.setCompleteListener(() => {
            this._jpjl.active = false
            jpjlSp.setCompleteListener(null)
        })
    },
