/**
 * bonus taskitem
 */

let task_des =
{
    dailyorweekly_taskdes1: "Spin {0} times.",
    dailyorweekly_taskdes2: "Bet {0} different slots.",
    dailyorweekly_taskdes3: "Win a total of {0} coins.",
    dailyorweekly_taskdes4: "Bet {1} in a single spin {0} times.",
    dailyorweekly_taskdes5: "Get {0} big wins.",
    dailyorweekly_taskdes6: "Play any slot for {0} minutes.",
    dailyorweekly_taskdes7: "Bet a total of {0} Coins.",
    dailyorweekly_taskdes8: "Spin {0} times.",
    dailyorweekly_taskdes9: "Get {0} huge wins.",
    dailyorweekly_taskdes10: "Level up {0} time.",
    dailyorweekly_taskdes11: "Bet a total of {0} Coins.",
    dailyorweekly_taskdes12: "Share to Facebook {0} time.",
    dailyorweekly_taskdes21: "Scratch&win {0} times.",
    dailyorweekly_taskdes22: "Bet {1} in a single spin {0} times.",
    dailyorweekly_taskdes23: "Get {0} hero fragments.",
    dailyorweekly_taskdes24: "Play lucky flipcard for {0} times.",
    dailyorweekly_taskdes25: "Win {1} in a single spin {0} times.",
    dailyorweekly_taskdes26: "Share to Facebook for {0} days.",
    dailyorweekly_taskdes27: "Earn {0} palace points.",
    dailyorweekly_taskdes28: "Spin {0} times.",
    dailyorweekly_taskdes29: "Make a purchase.",
    dailyorweekly_taskdes30: "Unlock or evolve {0} heroes.",
    dailyorweekly_taskdes31: "Win a total of {0} coins.",
    dailyorweekly_taskdes32: "Bet a total of {0} coins.",
}

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        // let btn_diamond = cc.find("diamondBtn",this.node)
        // Global.btnClickEvent(btn_diamond, this.onClickDiaBtn, this)

        let collectBtn = cc.find('collectBtn', this.node)
        Global.btnClickEvent(collectBtn, this.onClickCollectBtn, this)

        let btn_go = cc.find('goBtn', this.node)
        btn_go.active = false
        Global.btnClickEvent(btn_go, this.onClickGoBtn, this)

    },

    start() {

    },

    init: function (data, showType) {
        this._showData = data
        this._showType = showType


        //des
        let lbl_des = task_des["dailyorweekly_taskdes" + data.id]
        lbl_des = this._changeDes(lbl_des, data.params)
        // if(lbl_des.indexOf("%") != -1){
        //     lbl_des = cc.js.formatStr(task_des["dailyorweekly_taskdes"+data.id], Global.convertNumToShort(data.need))
        // }
        Global.setLabelString("label", this.node, lbl_des)
        //pro
        let proVal = data.count / data.need
        let proNode = cc.find("pro", this.node)
        if (data.state >= 2) {
            proVal = 1
        }
        proNode.getComponent(cc.ProgressBar).progress = proVal
        Global.setLabelString("lbl_val", proNode, Math.ceil(proVal * 100) + "%")
        //rewards
        this.initReward(data.rewards)
        // //diamond
        // let diamondBtn = cc.find("diamondBtn",this.node)
        // Global.setLabelString("count",diamondBtn,data.diamond)
        //任务状态
        let collectBtn = cc.find("collectBtn", this.node)
        let getFlag = cc.find("getten", this.node)
        let goBtn = cc.find("goBtn", this.node)
        let sprlock = cc.find("spr_unlock", this.node)

        let status = data.state
        switch (status) {
            case 0://未解锁
                proNode.active = false
                collectBtn.active = false
                getFlag.active = false
                sprlock.active = true
                // diamondBtn.active = false
                goBtn.active = false
                break;
            case 1://已解锁，不可领取
                proNode.active = true
                sprlock.active = false
                collectBtn.active = false
                getFlag.active = false
                // diamondBtn.active = true
                goBtn.active = true
                break;
            case 2://已解锁，可以领取
                proNode.active = true
                collectBtn.active = true
                getFlag.active = false
                sprlock.active = false
                // diamondBtn.active = false
                goBtn.active = false
                break;
            case 3://已领取
                proNode.active = false
                collectBtn.active = false
                getFlag.active = true
                sprlock.active = false
                // diamondBtn.active = false
                goBtn.active = false
                break;
            default:
                break;
        }

    },

    _changeDes(str, params) {
        if (params) {
            for (let i = 0; i < params.length; i++) {
                str = str.replace('{' + i + '}', Global.convertNumToShort(params[i]));
            }
        }

        return str
    },

    getItemData() {
        return this._showData
    },

    initReward(rd) {
        let icon = cc.find('icon', this.node)
        let childArray = icon.children
        //奖励元素隐藏
        for (let j = 0; j < childArray.length; j++) {
            childArray[j].active = false
        }
        //奖励
        for (let i = 0; i < rd.length; i++) {
            let sprNode = cc.find('spr', childArray[i])
            sprNode.getComponent('CH_RewardItem').init(rd[i].type, rd[i].count, true, true)
            childArray[i].active = true
        }
    },

    onClickDiaBtn: function () {
        let curDiamond = cc.vv.UserManager.getDiamond()
        let needDiamond = this._showData.diamond

        let msg = ''
        let sureCall = null
        let cancelCall = null
        let self = this
        if (curDiamond < needDiamond) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石不足窗口弹出')
            //不足
            msg = "Diamonds are not enough! Go get the diamond?"
            sureCall = function () {
                cc.vv.UserManager.setEnterHallAction('Shop_Diamond')
                if (cc.vv.gameData) {
                    cc.vv.PopUIMgr.popShop()
                } else {
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
                }
                Global.dispatchEvent(EventId.MISSION_CLOSE);
                StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石不足窗口弹出 点击yes')
            }
            cancelCall = function () {

                StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石不足窗口弹出 点击no')
            }

            cc.vv.AlertView.showSimple(msg, sureCall, cancelCall)
        } else {
            //直接使用

            sureCall = function () {

                self.sendDiamondReq()

                StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石足够窗口弹出 点击yes')
            }


            sureCall()
        }
    },

    onClickCollectBtn: function () {
        Global.playComEff("ch_btn_click");
        //屏蔽点击
        cc.vv.NewGuide.SetIsLoadingGuide(true)

        let req = { c: MsgId.REQ_GET_MISSION_REWARDS }
        req.questid = this._showData.id
        cc.vv.NetManager.send(req)
    },

    sendDiamondReq() {
        let req = { c: MsgId.REQ_USE_MISSION_DIAMOND };
        req.questid = this._showData.id
        cc.vv.NetManager.send(req);
    },

    onClickGoBtn: function () {
        Global.playComEff("ch_btn_click");
        let val = this._showData.id
        if (val == 12 || val == 26) {
            //fb
            Global.dispatchEvent("BONUS_TAB", "Login")
        }
        else if (val == 21) {
            //刮刮乐
            Global.dispatchEvent("BONUS_TAB", "Login")
        }
        else if (val == 24) {
            //luckycard
            cc.vv.UserManager.goSystemUI("luckycard")
        }
        else if (val == 27) {
            //place
            cc.vv.UserManager.goSystemUI("heropalace")
        }
        else if (val == 29) {
            //shop
            cc.vv.UserManager.goSystemUI("TabShop")
        }
        else if (val == 30 || val == 23) {
            //hero
            cc.vv.UserManager.goSystemUI('Tabhero')
        }
        else {
            //enter game
            cc.vv.UserManager.goSystemUI("entergame", Global.DEFAULT_GAMEID)
        }
    }



    // update (dt) {},
});
