/**
 * 卡包分享礼包
 */
const List = require('CH_List');

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        dataList: List,
        _itemData: null,
        _bCanOpen: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('btn_close', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_CARDSHARE_GIFT, this.onRcvCardGift, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_CARDSHARE_GIFT, this.onRcvCardGift, false, this);
    },

    start() {
        let req = { c: MsgId.REQ_CARDSHARE_GIFT };
        req.packid = this._itemData.cardshare.packid
        cc.vv.NetManager.sendAndCache(req);

        Global.playCashEff("social/redpack_show");
    },

    init: function (itemData, bCanOpen) {
        this._itemData = itemData
        this._bCanOpen = bCanOpen

    },

    showUI: function () {

        let nReward = this._giftData.coin
        let strSender = cc.vv.Language.friend_sends
        if (nReward > 0) {
            strSender = cc.vv.Language.friend_sends_you
        }
        let lblSender = cc.find('ui/lbl_send', this.node)
        I18N.setI18nLabel(lblSender, strSender, this._itemData.name)

        let lblCoin = cc.find('ui/lbl_coin', this.node)
        let lblunget = cc.find('ui/lbl_unget', this.node)
        lblCoin.active = nReward > 0
        lblunget.active = !(nReward > 0)
        if (nReward > 0) {
            if (this._bCanOpen) {
                //滚金币
                let finishCall = function () {
                    //飞金币
                    let toNode = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
                    let rollData = {}
                    rollData.lblCoin = toNode
                    rollData.addCoin = nReward
                    rollData.begin = cc.vv.UserManager.coin - nReward
                    Global.FlyCoin(lblCoin, toNode, null, rollData, true)
                }
                Global.doRoallNumEff(lblCoin, 0, nReward, 1, finishCall, null, 0, true)
            }
            else {
                lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(nReward)
            }
        }



        //红包个数
        let lblOpen = cc.find('ui/lbl_num', this.node)
        lblOpen.getComponent(cc.Label).string = cc.js.formatStr('%s/%s', this._giftData.curr, 10)

        //红包金额
        let lblTotal = cc.find('ui/lbl_total', this.node)
        lblTotal.getComponent(cc.Label).string = Global.FormatNumToComma(this._giftData.totalcoin)
        this.scheduleOnce(() => {
            cc.find("ui/lbl_total/lbl_total_des", this.node).x = lblTotal.width + 12
        }, 0)

        this.dataList.numItems = this._giftData.detail.length
    },



    onRenderListitem: function (item, idx) {
        let t = this._giftData.detail[idx]

        if (t) {
            let bMax = this.isMaxLuck(t)
            item.active = true
            item.getComponent('CH_FriendCardShareGiftItem').init(t, bMax)
        }
        else {
            item.active = false
        }
    },

    onRcvCardGift: function (msg) {
        if (msg.code == 200) {
            this._giftData = msg
            this.showUI()
        }
    },

    onClickClose: function () {

        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_GIFTCLOSE)

        this.node.destroy()
    },

    isMaxLuck: function (t) {
        let bMax = false
        let nVal = 0
        if (this._giftData.detail.length == 10) {
            for (let i = 0; i < this._giftData.detail.length; i++) {
                let item = this._giftData.detail[i]
                if (item.coin > nVal) {
                    nVal = item.coin
                }
            }
            if (t.coin == nVal) {
                bMax = true
            }
        }
        return bMax
    }

    // update (dt) {},
});
