/**
 * 食用说明
 * 1.在slots_common/SlotRes/prefab里面，把LMSlots_Collect_Puzzle   LMSlots_Puzzle    预制拖到safe_node下面
 * 2.在子游戏的cfg文件里添加puzzleCfg配置项
 * puzzleCfg: {
        atlas: "puzzle_6",              // 拼图的altas，需要拖入到asset base里面
        bg: "theme_store_puzzle6_bg",   // 背景
        full: "theme_store_puzzle6_full",   // 完整拼图
        pieces: [                       // 每个拼图的名字
            "theme_store_puzzle_6_1",
            "theme_store_puzzle_6_2",
            "theme_store_puzzle_6_3",
            "theme_store_puzzle_6_4",
            "theme_store_puzzle_6_5",
            "theme_store_puzzle_6_6",
            "theme_store_puzzle_6_7",
            "theme_store_puzzle_6_8",
            "theme_store_puzzle_6_9",
            "theme_store_puzzle_6_10",
            "theme_store_puzzle_6_11",
            "theme_store_puzzle_6_12"]
    },
 *
 * 3.在子游戏的slots文件的init方法中添加 this.node.parent.parent.getComponent("LMSlots_Puzzle").setCallback((freeInfo, chipGame)=>{
 *      // 进入免费的逻辑
 * });
 * 4.需要把slots_common/SlotRes/plist/puzzle/puzzle_ui这个plist拖到asset里面
 */

cc.Class({
    extends: cc.Component,
    properties: {
        _haveClickStart: false,
        _callback: null,
        _collect_puzzle: null,
        _puzzle: null,
        _puzzle_tips: null,
        _isActiveClick: false,
        _loadPrefabs:[],
    },

    onLoad() {
        this._collect_puzzle = cc.find("safe_node/LMSlots_Collect_Puzzle", this.node);
        this._puzzle = cc.find("safe_node/LMSlots_Puzzle", this.node);
        this._puzzle.addComponent(cc.BlockInputEvents);
        this._puzzle.zIndex = 10
        this._puzzle_tips = null//cc.find("safe_node/LMSlots_Puzzle_Tips", this.node);
        let puzzleData = cc.vv.gameData.getPuzzleData();
        let cfg = cc.vv.gameData.getGameCfg().puzzleCfg;
        if (cfg) {
            let piceNum = cfg.pieces.length
            let node_puzzle = cc.find("bg/puzzle_" + piceNum, this._puzzle);
            if (node_puzzle) {
                let atlas = cc.vv.gameData.GetAtlasByName(cfg.atlas);
                for (let i = 0; i < piceNum; i++) {
                    cc.find("piece_" + (i + 1), node_puzzle).getComponent(cc.Sprite).spriteFrame =
                        atlas.getSpriteFrame(cfg.pieces[i]);
                }

                cc.find("bg", node_puzzle).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(cfg.bg);

                cc.find("full", node_puzzle).getComponent(cc.Sprite).spriteFrame = atlas.getSpriteFrame(cfg.full);
            }

            let name = cc.find("bg/name", this._puzzle);
            let atlas = cc.vv.gameData.GetAtlasByName("puzzle_ui");
            name.getComponent(cc.Sprite).spriteFrame =
                atlas.getSpriteFrame("theme_store_text_title" + puzzleData.cfg[0].titleIdx);
        }

        // 初始化的界面
        for (let i = 0; i < puzzleData.cfg[0].coinIdx.length; i++) {
            let coin = cc.find("bg/ProgressBar/icon_coin_" + (i + 1), this._puzzle);
            let targetNum = puzzleData.cfg[0].coinIdx[i];
            if (coin) {
                let lock = cc.find("lock", coin);
                let spine = cc.find("spine", coin).getComponent(sp.Skeleton);
                if (puzzleData.chips[0].length >= targetNum) {
                    lock.active = false;
                    spine.node.active = true;
                    spine.setAnimation(0, "animation2", true);
                } else {
                    lock.active = true;
                    spine.node.active = false;
                }
            }
        }

        cc.find("progress", this._collect_puzzle).getComponent(cc.Label).string =
            (puzzleData.chips[0] ? puzzleData.chips[0].length : 0) + "/" + puzzleData.cfg[0].size;



        let btn_help = cc.find("bg/btn_help", this._puzzle);
        btn_help.on("click", ()=>{
            // if (!this._puzzle_tips) {
                cc.loader.loadRes("slots_common/SlotRes/prefab/LMSlots_Puzzle_Tips", cc.Prefab, (error, resource) => {
                    if (!error) {
                        this._loadPrefabs.push(resource)
                        let parentNode = this._puzzle
                        if(!cc.find('LMSlots_Puzzle_Tips',parentNode)){
                            this._puzzle_tips = cc.instantiate(resource);
                            this._puzzle_tips.parent = parentNode;
                            this._puzzle_tips.active = true;
                            let btn_close_tips = cc.find("tips_1/btn_close", this._puzzle_tips);
                            btn_close_tips.on("click", ()=>{
                                this._puzzle_tips.destroy();
                                this._puzzle_tips = null;
                            });
                        }
                        
                    }
                })
            // } 
            // else {
            //     this._puzzle_tips.active = true;
            //     let btn_close_tips = cc.find("tips_1/btn_close", this._puzzle_tips);
            //     btn_close_tips.on("click", ()=>{
            //         this._puzzle_tips.active = false;
                    
            //     });
            // }
            // this._puzzle_tips.active = true;
        });

        let btn_start = cc.find("bg/btn_start", this._puzzle);
        btn_start.on("click", ()=>{
            if (this._haveClickStart) {
                return;
            }
            btn_start.stopAllActions();
            this._haveClickStart = true;
            let req = {c: MsgId.SLOT_SUBGAME_DATA};
            req.uid = Global.playerData.uid;
            req.gameid = cc.vv.gameData._gameId;
            req.data = {};
            req.data.rtype = 20;
            req.data.choiceId = 1;
            cc.vv.NetManager.send(req);
        });

        this._collect_puzzle.on(cc.Node.EventType.TOUCH_END, ()=>{
            if (cc.vv.gameData.GetSlotState() !== "idle") {
                return;
            }

            this.openPuzzle(true);
        });

        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameData, this);
    },

    // start () {
    //     let puzzleData = cc.vv.gameData.getPuzzleData();
    //     if (puzzleData.chips[0].length === puzzleData.cfg[0].size) {
    //         this.openPuzzle(true);
    //     }
    // },

    setCallback(callback) {
        this._callback = callback;
    },

    async openPuzzle(isActiveClick, hideCloseBtn) {
        cc.vv.gameData.PauseSlot()
        this._isActiveClick = isActiveClick;
        if (isActiveClick) {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        }

        cc.vv.AudioManager.playEff("slots_common/SlotRes/", "puzzle/click", true);
        let puzzleData = cc.vv.gameData.getPuzzleData();
        let winCoin = puzzleData.currChipInfo ? puzzleData.currChipInfo.winCoin : 0;
        let curChipNum = puzzleData.chips[0] ? puzzleData.chips[0].length : 0;
        let maxChipNum = puzzleData.cfg[0].size;

        this._puzzle.active = true;
        cc.find("bg", this._puzzle).scale = 0;
        cc.vv.AudioManager.playEff("slots_common/SlotRes/", "puzzle/dialog_in", true);
        cc.tween(cc.find("bg", this._puzzle))
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .start();

        let free_time = cc.find("bg/free_time", this._puzzle);
        free_time.getComponent(cc.Label).string = puzzleData.cfg[0].freeCnt;
        let progressBar = cc.find("bg/ProgressBar", this._puzzle);
        progressBar.getComponent(cc.ProgressBar).progress = curChipNum / maxChipNum;
        cc.find("txt_progress", progressBar).getComponent(cc.Label).string =
            Math.floor(curChipNum * 100 / maxChipNum) + "%";
        for (let i = 1; i < 13; i++) {
            cc.find("bg/puzzle_12/piece_" + i, this._puzzle).active = (puzzleData.chips[0] ? puzzleData.chips[0].indexOf(i) !== -1 : false) ;
        }

        cc.find("bg/puzzle_12/full", this._puzzle).active = curChipNum === maxChipNum;

        let btn_start = cc.find("bg/btn_start", this._puzzle);
        btn_start.getComponent(cc.Button).interactable = curChipNum === maxChipNum;
        this._haveClickStart = curChipNum !== maxChipNum;
        if (btn_start.getComponent(cc.Button).interactable) {
            cc.vv.gameData.checkAutoPlay(btn_start, ()=>{
                if (this._haveClickStart) {
                    return;
                }
                this._haveClickStart = true;
                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.uid = Global.playerData.uid;
                req.gameid = cc.vv.gameData._gameId;
                req.data = {};
                req.data.rtype = 20;
                req.data.choiceId = 1;
                cc.vv.NetManager.send(req);
            });
        }

        // 添加点击事件
        let btn_close = cc.find("bg/btn_close", this._puzzle);
        btn_close.active = !hideCloseBtn;
        let func = ()=>{
            btn_close.off("click");
            cc.vv.AudioManager.playEff("slots_common/SlotRes/", "puzzle/dialog_out", true);
            cc.tween(cc.find("bg", this._puzzle))
                .to(0.5, {scale: 0}, {easing: "backIn"})
                .call(()=>{
                    this._puzzle.active = false;
                    cc.vv.gameData.ResumeSlot();
                    if (this._isActiveClick) {
                        cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
                    }
                    // cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                })
                .start();
        }
        if (!this._isActiveClick && !hideCloseBtn) {
            cc.vv.gameData.checkAutoPlay(btn_close, func);
        }
        btn_close.on("click", ()=>{
            btn_close.stopAllActions();
            func();
        });

        for (let i = 0; i < puzzleData.cfg[0].coinIdx.length; i++) {
            let coin = cc.find("bg/ProgressBar/icon_coin_" + (i + 1), this._puzzle);
            let targetNum = puzzleData.cfg[0].coinIdx[i];
            if (coin) {
                let lock = cc.find("lock", coin);
                let spine = cc.find("spine", coin).getComponent(sp.Skeleton);
                if (curChipNum >= targetNum) {
                    if (lock.active) {
                        await cc.vv.gameData.awaitTime(0.5);
                        lock.active = false;
                        spine.node.active = true;
                        spine.setAnimation(0, "animation", false);
                        spine.addAnimation(0, "animation2", true);
                        spine.setCompleteListener((track)=>{
                            let name = track.animation ? track.animation.name : "";
                            if (name === "animation") {
                                spine.setCompleteListener(null);
                                cc.loader.loadRes("slots_common/SlotRes/prefab/LMSlots_Puzzle_Reward_Coin", cc.Prefab, (error, resource) => {
                                    if (!error) {
                                        this._loadPrefabs.push(resource)
                                        let reward_coin_node = cc.instantiate(resource);
                                        reward_coin_node.active = true;
                                        reward_coin_node.parent = this._puzzle;
                                        let scale_node = cc.find("scale_node", reward_coin_node);
                                        scale_node.scale = 0;

                                        let name = cc.find("game_name", scale_node);
                                        let atlas = cc.vv.gameData.GetAtlasByName("puzzle_ui");
                                        name.getComponent(cc.Sprite).spriteFrame =
                                            atlas.getSpriteFrame("theme_store_text_title" + puzzleData.cfg[0].titleIdx);

                                        let percent = cc.find("percent", scale_node);
                                        percent.getComponent(cc.Label).string =
                                            Math.floor(puzzleData.chips[0].length * 100 / puzzleData.cfg[0].size) + "%";

                                        // let winCoin = puzzleData.currChipInfo.winCoin;
                                        cc.find("coin", scale_node).getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);
                                        cc.find("all_coin", scale_node).getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);

                                        cc.tween(scale_node)
                                            .to(0.5, {scale: 1}, {easing: "backOut"})
                                            .start();

                                        let btn_collect = cc.find("btn_collect", scale_node);
                                        let func = ()=>{
                                            btn_collect.off("click");
                                            cc.tween(scale_node)
                                                .to(0.5, {scale: 0}, {easing: "backIn"})
                                                .call(()=>{
                                                    reward_coin_node.removeFromParent();
                                                })
                                                .start();
                                        }
                                        cc.vv.gameData.checkAutoPlay(btn_collect, func);
                                        btn_collect.on("click", ()=>{
                                            btn_collect.stopAllActions();
                                            func();
                                        });
                                    }

                                })
                            }
                        })
                    }
                }
            }
        }
    },

    puzzleFly:function(){
        let puzzleData = cc.vv.gameData.getPuzzleData();
        // if (puzzleData.currChipInfo.winCoin > 0 || puzzleData.chips[0].length === puzzleData.cfg[0].size) {
        //     cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        // }

        let safe_node = this._collect_puzzle
        let puzzle = cc.instantiate(cc.find("icon_puzzle", this._collect_puzzle));
        puzzle.active = true;
        puzzle.scale = 0;
        
        puzzle.parent = safe_node;
        let endPos = cc.v2(0,0)
        cc.tween(puzzle)
            .to(0.5, {scale: 1}, {easing: "backOut"})
            .to(0.5, {position: endPos, scale: 0.5})
            .call(()=>{
                cc.find("progress", this._collect_puzzle).getComponent(cc.Label).string =
                    (puzzleData.chips[0] ? puzzleData.chips[0].length : 0) + "/" + puzzleData.cfg[0].size;
                if (puzzleData.currChipInfo.winCoin > 0) {
                    this.openPuzzle(false);
                }

                // if ((puzzleData.chips[0] ? puzzleData.chips[0].length : 0) === puzzleData.cfg[0].size) {
                //     this.openPuzzle(false);
                // }
            })
            .removeSelf()
            .start();
    },

    puzzleFinish() {
        let puzzleData = cc.vv.gameData.getPuzzleData();
        if ((puzzleData.chips[0] ? puzzleData.chips[0].length : 0) === puzzleData.cfg[0].size) {
            this.openPuzzle(false, true);
            return true;
        }
        return false;
    },

    onRcvSubGameData(msg) {
        if (msg.code === 200 && msg.data.rtype === 20) {
            if (this._callback) {
                //设置免费次数
                cc.vv.gameData.SetIsPuzzleModel(true)
                

                this._collect_puzzle.active = false
                this._puzzle.active = false;
                cc.vv.gameData.ResumeSlot()
                cc.vv.gameData.GetBottomScript().SetWin(0);
                cc.find("progress", this._collect_puzzle).getComponent(cc.Label).string =
                    (msg.data.chipGame.chips[0] ? msg.data.chipGame.chips[0].length : 0) + "/" + msg.data.chipGame.cfg[0].size;
                for (let i = 0; i < 3; i++) {
                    let coin = cc.find("bg/ProgressBar/icon_coin_" + (i + 1), this._puzzle);
                    if (coin) {
                        let lock = cc.find("lock", coin);
                        let spine = cc.find("spine", coin).getComponent(sp.Skeleton);
                        lock.active = true;
                        spine.node.active = false;
                    }
                }

                this._callback(msg.data.freeInfo, msg.data.chipGame);
            }
        } else {
            this._haveClickStart = false;
        }
    },

    onDestroy() {
        this._callback = null
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRcvSubGameData, false, this);

        for(let i = 0; i < this._loadPrefabs.length; i++){
            let deps = cc.loader.getDependsRecursively(this._loadPrefabs[i])
            cc.loader.release(deps);
            
        }
        this._loadPrefabs = []
    }
})