/*
    更改用户头像
 */
const List = require('List');
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _picid: 0,
        listview: List,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._icon = cc.find("bg/scrollView/view/icon", this.node);
        this.btnConfirm = cc.find("bg/btn_confirm", this.node);
        Global.btnClickEvent(this.btnConfirm, this.onClickConfirm, this);
        let btnClose = cc.find("bg/btn_close", this.node);
        Global.btnClickEvent(btnClose, this.onClickClose, this);
        this.lockTip = cc.find("bg/lock_tip", this.node);
        this.lockTip.active = false;
        Global.playComEff("ch_popup_l2");
    },

    start() {
        this.registerMsg();
        //刷新红点
        Global.dispatchEvent(EventId.REFUSH_RED_TIPS)
    },

    registerMsg() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_CHANGE_USER_HEAD, this.onRcvChangeHead, this);
        Global.registerEvent(EventId.UPDATE_USER_HEAD_PICID, this.onRcvUpdateUserHeadPicid, this);
        Global.registerEvent(EventId.CLOSE_USER_HEAD, this.onClickClose, this);
        Global.registerEvent(EventId.SHOW_USER_HEAD_TIP, this.showTip, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_CHANGE_USER_HEAD, this.onRcvChangeHead, false, this);
    },

    // update (dt) {},

    initShow(picid) {
        this._picid = picid;
        this._listData = cc.vv.HerocardManager.getCardListByCamp(0, true);
        for (let i = 0; i < this._listData.length; i++) {
            let isUnlock = cc.vv.HerocardManager.isCardUnlock(this._listData[i].cfg.cardid);
            if (!isUnlock) {
                for (let j = 6; j > 0; j--) {
                    this._listData.splice(i, 0, j)
                }
                break;
            }
        }
        //华为的不显示fb
        if (Global.appId == Global.APPID.SouthAmerica || Global.appId == Global.APPID.HuaweiDRM) {
        } else {
            this._listData.unshift(7)
        }
        this.showList()
    },

    showList() {
        this.listview.numItems = this._listData.length > 0 ? this._listData.length : 0;
        this.listview.active = (this._listData.length > 0);
    },

    //list
    OnListVRender(item, idx) {
        let uid = cc.vv.UserManager.uid;
        if (!isNaN(this._listData[idx])) {
            item.name = "icon_" + this._listData[idx];
            let headIcon = this._listData[idx]
            if (this._listData[idx] == 7) {
                let flag = cc.vv.UserManager.isBindFb()
                if (flag) {
                    headIcon = cc.vv.UserManager.getFbIconPath()
                }
            }
            item.getComponent('UserHead').setHead(uid, headIcon);
            cc.find("grey", item).active = false;
        } else {
            item.name = "icon_" + this._listData[idx].cfg.cardid;
            item.getComponent('UserHead').setHead(uid, this._listData[idx].cfg.cardid);
            let isUnlock = cc.vv.HerocardManager.isCardUnlock(this._listData[idx].cfg.cardid);
            cc.find("grey", item).active = !isUnlock;
        }
        item.active = true;
        item.heroCfg = this._listData[idx].cfg
        if (item._name.slice(5) == 7 && this._picid == 20) {
            item.getComponent('changeHeadItem').setChicked(true)
        } else {
            item.getComponent('changeHeadItem').setChicked(item._name.slice(5) == this._picid)
        }
    },

    onRcvUpdateUserHeadPicid(data) {
        let picid = data.detail.picid
        this._picid = picid
        let children = this._icon.children
        for (let i = 0; i < children.length; i++) {
            children[i].getComponent('changeHeadItem').setChicked(children[i]._name.slice(5) == picid)
        }
    },

    onRcvChangeHead(msg) {
        if (msg.code == 200) {
            let userIcon = msg.usericon;
            cc.vv.UserManager.SetUserIcon(userIcon);
            Global.dispatchEvent(EventId.CHANGE_USER_HEAD, { picid: this._picid });

            this.onClickClose();
        }
    },

    onClickConfirm() {
        Global.playComEff("ch_btn_click");
        this.btnConfirm.getComponent(cc.Button).interactable = false;
        if (this._picid) {
            let req = { c: MsgId.REQ_CHANGE_USER_HEAD };
            req.uid = Global.playerData.uid;
            let _picid = (this._picid == 7) ? 20 : this._picid
            req.picid = _picid
            // req.picid = this._picid
            req.rtype = 1
            cc.vv.NetManager.send(req);
        }
    },

    onClickClose() {
        Global.playComEff("ch_close");
        if (cc.isValid(this.node)) {
            this.node.destroy();
        }
    },

    showTip(data) {
        let node = data.detail.node
        let gameName = data.detail.gameName
        this.lockTip.stopAllActions();
        if (this.lockTip.active) {
            this.lockTip.runAction(cc.sequence(
                cc.scaleTo(this.lockTip.scaleX / 3, 0, 0),
                cc.callFunc(() => { this.lockTip.active = false; })
            ))
        } else {
            this.lockTip.active = true;
            cc.find("text_lbl", this.lockTip).getComponent(cc.RichText).string = cc.js.formatStr("Get Hero %s to unlock!", gameName);
            let bg = cc.find("bg", this.node);
            let arrow_down = cc.find("arrow_down", this.lockTip);
            let arrow_up = cc.find("arrow_up", this.lockTip);
            let convertPos = bg.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0, 0)));
            let posX = node.x;
            let posY = node.y;
            if (convertPos.y > 0) {   // 提示框在下面
                this.lockTip.position = cc.v2(0, convertPos.y - node.height / 2 - this.lockTip.height / 2);
            } else {    // 提示框在上面
                this.lockTip.position = cc.v2(0, convertPos.y + node.height / 2 + this.lockTip.height / 2);
            }
            arrow_up.active = convertPos.y > 0;
            arrow_down.active = convertPos.y <= 0;
            arrow_up.x = convertPos.x;
            arrow_down.x = convertPos.x;
            this.lockTip.setScale(0);
            this.lockTip.runAction(cc.sequence(
                cc.scaleTo(0.3, 1, 1),
                cc.delayTime(2),
                cc.scaleTo(0.3, 0, 0),
                cc.callFunc(() => { this.lockTip.active = false; })
            ))
        }
    },
});
