/**
 * 通用的解锁提示
 * 配置的Key就是节点的名字：节点名字有两个：一个是文字(node_sys_name下)+一个icon(node_sys_icon)
 */

let sys_unlock_cfg = {
    // "friend":{text_tip:'Come and add your first friend!',text_go:"LET'S GO!"},
    // "pigbank":{text_tip:'Spin and fill the piggy bank!',text_go:"VIEW"},
    // "herocard":{text_tip:"Let's start to collect your heroes!",text_go:"CONFIRM"},
    // "luckysmash":{text_tip:"Smash the egg to win huge rewards!",text_go:"VIEW"},
    "bingo": { text_tip: "Get grand prize via complete bingo game!", text_go: "LET'S GO!" },
    // "luckycard":{text_tip:"Heroes are born here!",text_go:"CONFIRM"},
    // "dailymission":{text_tip:"Come and get grand prize everyday!",text_go:"VIEW"},
    // "heropalace":{text_tip:"Unlock your high roller now!",text_go:"VIEW"},
    "knight": { text_tip: "Win amazing rewards on the map!", text_go: "VIEW" },
}
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _unlockType: null,
        itemAtlas: {
            default: null,
            type: cc.SpriteAtlas,
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('btn_close', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this);
        let btn_go = cc.find('btn_go', this.node)
        Global.btnClickEvent(btn_go, this.onClickGo, this);


    },

    start() {
        Global.playComEff("ch_popup");
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }



    },

    onDestroy() {
        Global.playComEff("ch_close");
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
            cc.vv.QueueWinMrg.nextPop()
        }

    },

    //显示解锁类型 strType 系统名称
    showUnlockSys: function (strType) {
        this._unlockType = strType

        let cfg = sys_unlock_cfg[strType]
        let tip_text = cc.find('spr_ui_bg/spr_tip_bg/lbl_tip', this.node)
        tip_text.getComponent(cc.Label).string = cfg.text_tip
        let go_text = cc.find('btn_go/Background/Label', this.node)
        go_text.getComponent(cc.Label).string = cfg.text_go
        //title
        let allSysName = cc.find('spr_ui_bg/node_sys_name', this.node).getComponent(cc.Sprite)
        if (this.itemAtlas.getSpriteFrame('text_' + strType)) {
            allSysName.spriteFrame = this.itemAtlas.getSpriteFrame('text_' + strType)
        }
        // for(let i =0; i<allSysName.children.length; i++ ){
        //     let item = allSysName.children[i]
        //     if(item.name == strType){
        //         item.active = true
        //     }
        //     else{
        //         item.active = false
        //     }
        // }
        //icon
        let allSysIcon = cc.find('spr_ui_bg/node_sys_icon', this.node).getComponent(cc.Sprite)
        if (this.itemAtlas.getSpriteFrame('spr_' + strType)) {
            allSysIcon.spriteFrame = this.itemAtlas.getSpriteFrame('spr_' + strType)
        }
        // for(let i =0; i<allSysIcon.children.length; i++ ){
        //     let item = allSysIcon.children[i]
        //     if(item.name == strType){
        //         item.active = true
        //     }
        //     else{
        //         item.active = false
        //     }
        // }

        //打点
        if (this._unlockType == 'friend') {

        }
        else if (this._unlockType == 'pigbank') {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_UNLOCK_UI)
        }
        else if (this._unlockType == 'herocard') {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROCARD_UNLOCK_UI)
        }
        else if (this._unlockType == 'luckysmash') {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYSMACH_UNLOCK_UI)
        }
    },

    onClickClose: function () {
        this.node.destroy();
    },

    onClickGo: function () {
        Global.playComEff("ch_btn_click");
        if (this._unlockType == 'friend') {
            if (cc.vv.gameData) {
                cc.vv.UserManager.setEnterHallAction(this._unlockType)
                cc.vv.gameData.ReqBackLobby()
            }
        }
        else if (this._unlockType == 'pigbank') {
            if (cc.vv.gameData) {
                let top = cc.vv.gameData.GetTopScript()
                top.onClickPigBank()
            }
        }
        else if (this._unlockType == 'herocard') {
            // if(cc.vv.gameData){
            //     cc.vv.UserManager.setEnterHallAction('default')
            //     cc.vv.gameData.ReqBackLobby()
            // }

            let req = { c: MsgId.REQ_GUIDETASK_ADD_HEROCARD };
            req.step = 1
            cc.vv.NetManager.send(req, true);

            StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROCARD_UNLOCK_GO)
        }
        else if (this._unlockType == 'luckysmash') {

            cc.vv.gameData.PauseSlot()
            cc.vv.NewGuide.ShowGuide(30)
            cc.vv.NewGuide.SetGuideTempData(31)
        }
        else if (this._unlockType == 'bingo') {
            //进入bingo
            Global.dispatchEvent(EventId.OPEN_BINGO)
        }
        else if (this._unlockType == 'knight') {
            Global.dispatchEvent(EventId.OPEN_EXPLORATION)
        }
        else if (this._unlockType == 'dailymission') {
            cc.vv.gameData.PauseSlot()
            cc.vv.NewGuide.ShowGuide(10)
            cc.vv.NewGuide.SetGuideTempData(10)
        }

        this.node.destroy()
    },

    //有需要可以重写
    popWinEndCall: function () {
        let nodeTip = cc.find('spr_ui_bg/spr_tip_bg', this.node)
        nodeTip.scale = 0
        nodeTip.active = true
        cc.tween(nodeTip)
            .delay(0.2)
            .to(0.3, { scale: 1 }, { easing: 'backOut' })
            .start()
    }

    // update (dt) {},
});
