    loadPopReward(rdArr, typeWhere) {
        let url = 'CashHero/prefab/pop_reward'
        let self = this
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                let endCall = function () {
                    node.destroy()
                    if (typeWhere != 2) {
                        self.checkDaiyActiveRewards()
                    }

                }
                node.getComponent('CH_popreward').showRewards(rdArr, endCall, 0)

            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    checkDaiyActiveRewards: function () {
        //更新任务列表
        this.updateMission(this._msg)
        //更新活跃度
        let actData = this._isDailyMissionFlag ? this._msg.daily_activity : this._msg.weekly_activity
        actData.activity += 10//每个任务固定10点活跃度
        if (actData.activity % 20 == 0) {
            actData.obtain_rewards.push(actData.activity / 20)//每20个活跃度设置一个奖励
        }
        let questList = this._isDailyMissionFlag ? this._msg.daily : this._msg.weekly
        let allAct = this.countAct(questList)
        //top
        if (cc.isValid(actData)) {
            this.initTop(actData, allAct, true, () => {
                this._setTouch(false)
                if (this._activityRewards && this._activityRewards.length > 0) {
                    let pos = this.node.convertToWorldSpaceAR(cc.v2(0, 0))
                    let actData = this._isDailyMissionFlag ? this._msg.daily_activity : this._msg.weekly_activity
                    let nIdx = actData.obtain_rewards.length
                    let srcObj = cc.find("top/giftsNode/gifts" + nIdx, this.node)
                    if (srcObj) {
                        pos = srcObj.convertToWorldSpaceAR(cc.v2(0, 0))
                    }
                    Global.RewardFly(this._activityRewards, pos)
                }
            })
        }
    },

