    showBottomLine(flag) {
        cc.find('bottom', this.node).active = flag
    },

    showBg(idx) {
        let showBg = cc.find('toggleContainer/showBg', this.node)
        showBg.active = true
        showBg.stopAllActions()
        let tarPos = (idx == 1) ? -157 : 157
        cc.tween(showBg)
            .to(0.15, { x: tarPos })
            .start()
    },

    onClickClose() {
        //是否是在引导内
        let _curGuide = cc.vv.NewGuide.GetCurGuideId()
        let _isGuide = _curGuide == 11 ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_CLOSE, _isGuide)

        Global.playComEff("ch_close")

        // // //检测是否有红点 如果是游戏打开的任务页面
        // if (cc.vv.gameData && this._reddotFlag && this._autoData) {
        //     Global.dispatchEvent(EventId.OPEN_AUTOTASK, {autoData:this._autoData})
        // }
        if (this._reddotFlag) {
            Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
            Global.dispatchEvent(EventId.REFUSH_RED_TIPS)
        }

        //从bonus进入 并且有任务完成 则刷新bonus列表
        if (this._completeMissionFlag && !cc.vv.gameData) {
            Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
        }

        if (cc.isValid(this.node)) {
            this.node.destroy()
        }
    },
