

cc.Class({
    extends: cc.Component,

    properties: {
        _btnPlay: null,
        _lblPlaytimes: null,
        _girds: null,
        gridType: {  //格子类型
            default: [],
            type: cc.SpriteFrame,
        },
        ballType: {  //球类型
            default: [],
            type: cc.SpriteFrame,
        },
    },

    onLoad() {
        let btnHelp = cc.find("top/btn_help", this.node)
        btnHelp.on('click', this.onClickHelp, this)

        this._btnPlay = cc.find("machine/btn_play", this.node)
        this._btnPlay.on('click', this.onClickPlay, this)

        let btnRank = cc.find("btn_rank", this.node)
        btnRank.on('click', this.onClickRank, this)

        let btnBuyTime = cc.find("btn_buy_times", this.node)
        btnBuyTime.on('click', this.onClickBuy, this)

        let btnBuyBooster = cc.find("btn_buy_booster", this.node)
        btnBuyBooster.on('click', this.onClickBuy, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_BINGO_SPIN, this.onRcvNetBingoSpin, this)
        cc.vv.NetManager.registerMsg(MsgId.NOTIFY_BINGO_GIFT_BUYED, this.onRcvNetBingoGiftBuyed, this)
    },

    start() {
        this.startGuide()
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_BINGO_SPIN, this.onRcvNetBingoSpin, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.NOTIFY_BINGO_GIFT_BUYED, this.onRcvNetBingoGiftBuyed, false, this)
    },

    startGuide() {
        if (!this._guiding && this.node.active && this._data && this._data.point > 0) {
            this._guiding = true
            cc.vv.NewGuide.ShowGuide(28)
        }
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    init(data) {
        this._data = data

        //游戏序号
        // Global.setLabelString("top/lbl_round", this.node, "LEVEL "+data.sectionId+"-"+data.orderId + " PRIZE")
        I18N.setI18nLabel(cc.find('top/lbl_round', this.node), cc.vv.Language.bingo_main_level, data.sectionId, data.orderId)
        //游戏奖励
        let coin_count = 0
        let package_count = 0
        let vip_count = 0
        let exp_count = 0
        let rewards = data.rewards[data.sectionId - 1][data.orderId - 1]
        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            if (reward.type == Global.PROP_ID.COIN) {
                coin_count += reward.count
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                package_count += reward.count
            } else if (reward.type == Global.PROP_ID.VIP_POINT) {
                vip_count += reward.count
            } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                exp_count += reward.count / 3600
            }
        }
        let rewardNode = cc.find("top/reward", this.node)
        Global.setLabelString("lbl_coin", rewardNode, Global.FormatNumToComma(coin_count))
        cc.find("item_package", rewardNode).active = package_count > 0
        Global.setLabelString("item_package/lbl_count", rewardNode, "X" + package_count)
        cc.find("item_vip", rewardNode).active = vip_count > 0
        Global.setLabelString("item_vip/lbl_count", rewardNode, "" + vip_count)
        cc.find("item_exp", rewardNode).active = exp_count > 0
        Global.setLabelString("item_exp/lbl_count", rewardNode, "X" + exp_count)

        //剩余抽奖次数
        // this._lblPlaytimes = cc.find("machine/lbl_playtimes", this.node).getComponent(cc.Label)
        I18N.setI18nLabel(cc.find("machine/lbl_playtimes", this.node), cc.vv.Language.bingo_main_ball, this._data.point)
        // this._lblPlaytimes.string = "BALL CALLS: " + data.point

        //初始化棋盘
        this.initBoard(data.row, data.col, data.boardInfo)
        //初始化抽奖记录
        this.initRecord(data.usedBalls)
        //初始化目标样式
        this.initPattern(data.row, data.col, data.boardInfo)
        //开始指引
        this.startGuide()
    },

    initGrid(grid, info) {
        Global.setLabelString("lbl_num", grid, "" + info.fillBall)
        grid.getChildByName("sel").active = info.isFill
        let stype = grid.getChildByName("stype")
        if (info.type == 1) {
            stype.active = false
        } else if (info.type <= 5) {
            stype.active = true
            stype.getComponent(cc.Sprite).spriteFrame = this.gridType[info.type - 2]
            stype.opacity = (info.type == 5) ? 255 : 100
        }
    },

    initBoard(row, col, boardInfo) {
        let board = cc.find("play/board_bg/board", this.node)
        let grid = cc.find("play/board_bg/grid", this.node)
        this._girds = []
        board.destroyAllChildren()
        let i = 0
        for (let r = 0; r < row; r++) {
            for (let c = 0; c < col; c++) {
                let g = cc.instantiate(grid)
                g.scale = 5 / row
                g.active = true
                g.parent = board
                this.initGrid(g, boardInfo[i])
                g.name = "grid_" + r + "_" + c
                this._girds.push(g)
                i++
            }
        }
    },

    addRecord(ballId, ani) {
        let record = cc.find("play/record_bg/record", this.node)
        let ball = cc.find("play/record_bg/ball", this.node)
        let b = cc.instantiate(ball)
        b.active = true
        b.parent = record
        b.setSiblingIndex(0)  //放在前面
        Global.setLabelString("lbl_num", b, "" + ballId)
        b.getComponent(cc.Sprite).spriteFrame = this.ballType[Math.floor((ballId - 1) / 15)]

        if (ani) {
            b.scale = 0.1
            b.runAction(cc.scaleTo(0.5, 1))
        }
    },

    initRecord(usedBalls) {
        let record = cc.find("play/record_bg/record", this.node)
        record.destroyAllChildren()
        for (let i = usedBalls.length - 1; i >= 0; i--) {
            this.addRecord(usedBalls[i])
        }
    },

    initPattern(row, col, boardInfo) {
        let icon = cc.find("pattern/icon", this.node)
        let pattern = null
        for (let i = 1; i <= 3; i++) {
            let p = cc.find("pattern/pattern" + i, this.node)
            p.active = (i == 1 && row == 5) || (i == 2 && row == 6) || (i == 3 && row > 6)
            if (p.active) pattern = p
        }
        pattern.destroyAllChildren()
        let width = 130
        let height = 130
        let dx = width / col
        let dy = height / row
        for (let i = 0; i < boardInfo.length; i++) {
            if (boardInfo[i].type == 5) {
                let tmp = cc.instantiate(icon)
                tmp.active = true
                tmp.parent = pattern
                tmp.position = cc.v2(((i % col) + 0.5) * dx - width / 2, height / 2 - (Math.floor(i / col) + 0.5) * dy)
            }
        }
    },

    async showNewBall(ballInfo) {
        let data = this._data
        let ballId = ballInfo.ballId
        this.addRecord(ballId, true)
        Global.playCashEff("bingo/" + ballId)
        await this.awaitTime(0.4)

        let grid = null
        for (let i = 0; i < data.boardInfo.length; i++) {
            if (ballInfo.ballId == data.boardInfo[i].fillBall) {
                data.boardInfo[i].isFill = true
                grid = this._girds[i]
                break
            }
        }
        if (grid) {
            Global.playCashEff("bingo/particle_fly")
            let fly = cc.find("play/fly", this.node)
            let ball = cc.find("play/record_bg/ball", this.node)
            fly.position = fly.parent.convertToNodeSpaceAR(ball.convertToWorldSpaceAR(cc.v2(0, 0)))
            let target = fly.parent.convertToNodeSpaceAR(grid.convertToWorldSpaceAR(cc.v2(0, 0)))
            fly.active = true
            fly.getComponent(cc.ParticleSystem).resetSystem()
            fly.runAction(cc.moveTo(0.6, target).easing(cc.easeSineOut(2)))
            await this.awaitTime(0.8)
            grid.getChildByName("sel").active = true
        } else {
            await this.awaitTime(0.4)
        }
        //飞机球
        if (ballInfo.nextBall) {
            let nextGrid = null
            for (let i = 0; i < data.boardInfo.length; i++) {
                if (ballInfo.nextBall.ballId == data.boardInfo[i].fillBall) {
                    data.boardInfo[i].isFill = true
                    nextGrid = this._girds[i]
                    break
                }
            }
            if (nextGrid) {
                let plane = cc.find("play/plane", this.node)
                let from = plane.parent.convertToNodeSpaceAR(grid.convertToWorldSpaceAR(cc.v2(0, 0)))
                let to = plane.parent.convertToNodeSpaceAR(nextGrid.convertToWorldSpaceAR(cc.v2(0, 0)))
                plane.active = true
                let t = plane.getComponent("Bingo_Plane").fly(from, to)
                await this.awaitTime(t)
                Global.playCashEff("bingo/bonus_ball")
                plane.active = false
                nextGrid.getChildByName("sel").active = true

                let nextBallInfo = ballInfo.nextBall
                //礼包球
                if (nextBallInfo.coin) {
                    await new Promise((success, failed) => {
                        this.loadPreb("bingo_reward", (node) => {
                            node.getComponent("Bingo_Reward").showWinCoin(nextBallInfo.coin, success)
                        })
                    })
                }
                //次数球
                else if (nextBallInfo.count) {
                    await new Promise((success, failed) => {
                        this.loadPreb("bingo_reward", (node) => {
                            node.getComponent("Bingo_Reward").showWinCount(nextBallInfo.count, success)
                        })
                    })
                }
            }
        }
        //礼包球
        else if (ballInfo.coin) {
            await new Promise((success, failed) => {
                this.loadPreb("bingo_reward", (node) => {
                    node.getComponent("Bingo_Reward").showWinCoin(ballInfo.coin, success)
                })
            })
        }
        //次数球
        else if (ballInfo.count) {
            await new Promise((success, failed) => {
                this.loadPreb("bingo_reward", (node) => {
                    node.getComponent("Bingo_Reward").showWinCount(ballInfo.count, success)
                })
            })
        }
    },

    async showLevelRewards(level, rewards) {
        return new Promise((success, failed) => {
            this.loadPreb("bingo_reward", (node) => {
                node.getComponent("Bingo_Reward").showLevelPrize(level, rewards, success)
            })
        })
    },

    async showRoundReward(round, rewards) {
        return new Promise((success, failed) => {
            this.loadPreb("bingo_reward", (node) => {
                node.getComponent("Bingo_Reward").showRoundPrize(round, rewards, success)
            })
        })
    },

    async onBingoSpin(msg) {
        //次数减1
        this._data.point = this._data.point - 1
        // this._lblPlaytimes.string = "BALL CALLS: " + this._data.point
        I18N.setI18nLabel(cc.find("machine/lbl_playtimes", this.node), cc.vv.Language.bingo_main_ball, this._data.point)

        //显示抽中球
        await this.showNewBall(msg.ballInfo)
        //如果有次数球，需要更新次数
        this._data.percent = msg.percent
        this._data.point = msg.point
        // this._lblPlaytimes.string = "BALL CALLS: " + msg.point
        I18N.setI18nLabel(cc.find("machine/lbl_playtimes", this.node), cc.vv.Language.bingo_main_ball, this._data.point)

        //显示结束
        if (msg.isEnd) {
            Global.playCashEff("bingo/bingo")
            cc.find("completed", this.node).active = true
            let icon = cc.find("completed/spine", this.node)
            icon.scale = 0.2
            icon.runAction(cc.scaleTo(0.4, 1))
            await this.awaitTime(1.5)
        }
        //显示奖励
        if (msg.rewards) {
            let _levelLan = Global.language == Global.LANGUAGE.AR ? this._data.orderId + "-" + this._data.sectionId : this._data.sectionId + "-" + this._data.orderId
            await this.showLevelRewards(_levelLan, msg.rewards)
        }
        if (msg.superReward) {
            await this.awaitTime(0.5)
            await this.showRoundReward("" + this._data.roundId, msg.superReward)
        }
        if (msg.isEnd) {
            //更新新关卡数据
            this._data.roundId = msg.roundId
            this._data.sectionId = msg.sectionId
            this._data.orderId = msg.orderId
            this._data.usedBalls = []
            this._data.boardInfo = msg.boardInfo
            this._data.row = msg.row
            this._data.col = msg.col
            //下一关
            await this.awaitTime(1)
            this.nextLevel()
        }


        this._btnPlay.getComponent(cc.Button).interactable = true

        if (this._data.point == 0) {
            //没次数了
            let endCall = function () {
                Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI, 29)
            }
            cc.vv.NewGuide.ShowGuide(29, endCall)
        }
    },

    onRcvNetBingoSpin(msg) {
        if (msg.code == 200) {
            this.onBingoSpin(msg)
        } else {
            cc.vv.AlertView.showTips("Oops, the game maybe over\ncode:" + msg.code);
        }
    },

    onRcvNetBingoGiftBuyed(msg) {
        if (msg.code == 200 && this._data) {
            this._data.point += msg.point
            // Global.setLabelString("machine/lbl_playtimes", this.node, "BALL CALLS: " + this._data.point)
            I18N.setI18nLabel(cc.find("machine/lbl_playtimes", this.node), cc.vv.Language.bingo_main_ball, this._data.point)
        }
    },

    loadPreb(name, callback) {
        let parent = this.node
        cc.loader.loadRes("CashHero/prefab/bingo/" + name, cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(parent) && parent.active == true && !parent.getChildByName(name)) {
                let node = cc.instantiate(prefab)
                node.parent = parent
                if (callback) {
                    callback(node)
                }
            }
        })
    },

    onClickHelp() {
        this.loadPreb("bingo_help")
    },

    onClickRank() {
        if (!this._data) return
        this.loadPreb("bingo_rank", (node) => {
            node.getComponent("Bingo_Rank").showTime(this._data.startTime, this._data.endTime)
        })
    },

    onClickBuy() {
        if (!this._data) return
        this.loadPreb("bingo_buy", (node) => {
            node.getComponent("Bingo_Buy").showEndTime(this._data.endTime)
        })
    },

    onClickPlay() {
        //test plane
        /*
        let plane = cc.find("play/plane", this.node)
        let r1 = Global.random(0, this._girds.length-1)
        let r2 = Global.random(0, this._girds.length-1)
        let grid1 = this._girds[r1]
        let grid2 = this._girds[r2]
        let from = plane.parent.convertToNodeSpaceAR(grid1.convertToWorldSpaceAR(cc.v2(0,0)))
        let to = plane.parent.convertToNodeSpaceAR(grid2.convertToWorldSpaceAR(cc.v2(0,0)))
        plane.active = true
        plane.getComponent("Bingo_Plane").fly(from, to)
        return
        */
        if (!this._data) return
        if (this._data.point <= 0) {
            this.onClickBuy()
            return
        }
        Global.playCashEff("bingo/spin")
        this._btnPlay.getComponent(cc.Button).interactable = false
        let req = { c: MsgId.REQ_BINGO_SPIN }
        cc.vv.NetManager.send(req)

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_PLAY, cc.vv.UserManager.getBingoFrom())
    },

    nextLevel() {
        //任务界面刷新
        this.node.parent.getComponent("Bingo_Main").nextLevel()
        cc.find("completed", this.node).active = false
        this.init(this._data)
    }

});
