cc.Class({
    extends: cc.Component,

    properties: {
        _moved: false,
        _startPos: null,
        _data: null,
        _count_bg: null,
        _lbl_count: null,
        _lbl_prog: null,
        _progress: null,
        _nodeLock: null,
        balls: cc.Prefab,
    },

    onLoad() {

        // //浮窗位置
        // let box = this.node.getBoundingBox()
        // let height = Math.min(840, cc.winSize.height*0.6)
        // this.node.position = cc.v2((cc.winSize.width-box.width)/2, height-cc.winSize.height/2)

        this._count_bg = cc.find("count_bg", this.node)
        this._lbl_count = cc.find("lbl_count", this._count_bg).getComponent(cc.Label)
        this._lbl_prog = cc.find("lbl_prog", this.node).getComponent(cc.Label)
        this._progress = cc.find("progress", this.node).getComponent(cc.ProgressBar)
        this._nodeLock = cc.find("node_lock", this.node)
        // Global.btnClickEvent(cc.find('btn_icon_lock',this._nodeLock), this.onClickLock, this);
        //初始化数据
        this._data = {}
        let bingoInfo = cc.vv.gameData.getDeskInfo().bingoInfo
        if (bingoInfo) {
            this._data.percent = bingoInfo.percent
            this._data.point = bingoInfo.point
            this.refreshView()
        }

        cc.vv.NetManager.registerMsg(MsgId.SLOT_START, this.OnRcvNetSpin, this)
        Global.registerEvent("BINGO_UPDATED", this.onEventBingoUpdated, this)
        Global.registerEvent(EventId.PULL_LV_UP, this.onEventExpLevelUp, this)
        Global.registerEvent(EventId.OPEN_BINGO, this.onEventMenulOpen, this)
    },

    onEnable() {


        this.node.on(cc.Node.EventType.TOUCH_START, this._onTouchStart, this)
        this.node.on(cc.Node.EventType.TOUCH_MOVE, this._onTouchMove, this)
        this.node.on(cc.Node.EventType.TOUCH_END, this._onTouchEnd, this)

        this.showTips()
        this.showLockUI()
    },

    onDisable() {



        this.node.off(cc.Node.EventType.TOUCH_START, this._onTouchStart, this)
        this.node.off(cc.Node.EventType.TOUCH_MOVE, this._onTouchMove, this)
        this.node.off(cc.Node.EventType.TOUCH_END, this._onTouchEnd, this)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_START, this.OnRcvNetSpin, false, this)
    },


    showLockUI: function () {
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)
        this._nodeLock.active = !bOpen

        cc.find('icon', this.node).active = bOpen

        //打点
        if (bOpen) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_FLOAT_LOCK, cc.vv.UserManager.getBingoFrom())
        } else {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_FLOAT_UNLOCK, cc.vv.UserManager.getBingoFrom())
        }


        //this._count_bg.active = bOpen
        if ((this._data.point < 1)) {
            this._count_bg.active = false
        }
        this._lbl_prog.node.active = bOpen
        this._progress.node.active = bOpen
    },

    _onTouchStart(event) {
        this._moved = false
        this._startPos = event.getLocation()
        this._lastPos = cc.v2(this._startPos.x, this._startPos.y)
    },

    _onTouchMove(event) {
        let location = event.getLocation()
        if (this._lastPos.sub(location).len() > 4) {
            this._lastPos = cc.v2(location.x, location.y)
            let box = this.node.getBoundingBox()
            if (location.x + box.width / 2 > cc.winSize.width) location.x = cc.winSize.width - box.width / 2
            if (location.x - box.width / 2 < 0) location.x = box.width / 2
            if (location.y + box.height / 2 > cc.winSize.height) location.y = cc.winSize.height - box.height / 2
            if (location.y - 2 * box.height / 2 < 0) location.y = 2 * box.height / 2
            // this.node.position = this.node.parent.convertToNodeSpaceAR(location)
            if (this._startPos.sub(location).len() > 10) {
                this._moved = true
            }
        }

    },

    _onTouchEnd(event) {
        if (!this._moved) { //未移动过，触发点击
            this.onNodeClicked()
        }
    },

    onNodeClicked() {
        Global.playComEff("ch_btn_click");
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)
        if (!bOpen) {
            this.onClickLock()
            return
        }
        let scale = this.node.scale
        this.node.runAction(cc.sequence(cc.scaleTo(0.1, scale * 0.95), cc.scaleTo(0.1, scale)))

        cc.loader.loadRes("CashHero/prefab/bingo/bingo_main", cc.Prefab, (err, prefab) => {
            let canvas = cc.find("Canvas")
            if (!err && !canvas.getChildByName("bingo_main")) {
                let node = cc.instantiate(prefab)
                node.name = "bingo_main"
                node.parent = canvas
                let first_bingo = false
                if (!Global.getLocal('visit_bingo')) {
                    first_bingo = true
                    Global.saveLocal('visit_bingo', '1')
                }
                if (this._data.point <= 0 && first_bingo == true) {   //只有第一次进入关卡界面
                    node.getComponent("Bingo_Main").showLevelView(3)
                } else {
                    node.getComponent("Bingo_Main").showGameView(3)
                }
            }
        })

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_FLOAT_UNLOCK_click, cc.vv.UserManager.getBingoFrom())
    },

    refreshView() {
        this._lbl_count.string = "" + this._data.point
        this._count_bg.active = (this._data.point > 0)
        this._progress.progress = Math.max(0.01, this._data.percent / 100.0)
        if (this._data.percent >= 100) {
            this._lbl_prog.string = "Maximum"
        } else {
            this._lbl_prog.string = this._data.percent + "%"
        }
    },

    async onRcvNetBingoInfo(info) {
        let bResume
        if (!this.node.active) {
            bResume = true
            Global.dispatchEvent(EventId.SHOW_FLOAT_ITEM, 'bingo')
        }
        //飞球
        this.ballsFly()
        await new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, 1.5);
        });

        if (bResume) {
            Global.dispatchEvent(EventId.RESUME_FLOAT_ITEM)
        }

        //提示框
        let notify = Global.getLocal('bingo_notify')
        if (notify != "0" && (info.point > 0 && this._data.percent > 0 && info.percent == 0)) { //收集满1次
            cc.loader.loadRes("CashHero/prefab/bingo/bingo_playtips", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("bingo_playtips")) {
                    let node = cc.instantiate(prefab)
                    node.name = "bingo_playtips"
                    node.parent = canvas
                    node.getComponent("Bingo_PlayTips").showPlayTimes(info.point)
                }
            })
        }

        //刷新界面
        this._data.percent = info.percent
        this._data.point = info.point
        this.refreshView()
    },

    OnRcvNetSpin(msg) {
        if (msg.code == 200 && msg.currBingoInfo) {
            this.onRcvNetBingoInfo(msg.currBingoInfo)
        }
    },

    async onEventBingoUpdated(data) {
        let info = data.detail
        if (info.point !== undefined) {
            this._data.point = info.point
            if (info.percent !== undefined)
                this._data.percent = info.percent
            this.refreshView()
        }
        if (info.isOver) {  //游戏结束
            this.node.active = false
        }
        return
    },

    ballsFly() {
        let parent = this.node.parent.parent
        if (!parent) return
        let balls = cc.instantiate(this.balls)
        balls.parent = parent
        balls.position = parent.convertToNodeSpaceAR(cc.v2(cc.winSize.width / 2, 400))
        let target = balls.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0, 0)))
        for (let i = 1; i <= 5; i++) {
            let ball = cc.find("ball_0" + i, balls)
            ball.scale = 1
            let t = 0.8
            ball.runAction(cc.sequence(cc.delayTime((i - 1) * t * 0.1), cc.spawn(cc.moveTo(t, target).easing(cc.easeSineInOut()), cc.scaleTo(t, 1.2)), cc.fadeOut(t * 0.05)))

        }
        balls.runAction(cc.sequence(cc.delayTime(1.2), cc.destroySelf()))
    },

    showTips() {
        //解锁了才显示
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)
        if (!bOpen) return

        let betidx = 1
        let bingoInfo = cc.vv.gameData.getDeskInfo().bingoInfo
        if (bingoInfo) {
            betidx = bingoInfo.minBet
        }
        //只有当前档位小于最低档位的时候才需要
        let curBetIdx = cc.vv.gameData.GetBetIdx()
        if (curBetIdx < betidx) {
            let betval = Global.formatNumShort(cc.vv.gameData.IdxToBet(betidx), 0)

            let nodeTip = cc.find('spr_tip', this.node)
            // cc.find('lbl_txt',nodeTip).getComponent(cc.RichText).string = cc.js.formatStr('when the bet is greater than or <br/>equal to <color=#00ff00>%s</color>,spin to collect ball.',betval)
            I18N.setI18nLabel(cc.find('lbl_txt', nodeTip), cc.vv.Language.bingo_float_tip, betval)

            nodeTip.scale = 0
            nodeTip.active = true
            cc.tween(nodeTip)
                .to(0.3, { scale: 1 }, { easing: 'backOut' })
                .delay(5)
                .to(0.2, { scale: 0 })
                .start()

            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_FLOAT_UNLOCK_BETTIP, cc.vv.UserManager.getBingoFrom())
        }

    },

    //点击未解锁按钮
    onClickLock: function () {
        let nodeTip = cc.find('spr_tip_lock', this._nodeLock)
        if (nodeTip.getNumberOfRunningActions() == 0) {
            cc.find('lbl_txt', nodeTip).getComponent(cc.RichText).string = cc.js.formatStr('UNLOCKED <br/>AT LEVEL <color=#00ff00>%s</color>', Global.SYS_OPEN.BINGO)
            nodeTip.scale = 0
            nodeTip.active = true
            cc.tween(nodeTip)
                .to(0.3, { scale: 1 }, { easing: 'backOut' })
                .delay(5)
                .to(0.2, { scale: 0 })
                .start()

            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_FLOAT_LOCK_POPTIP, cc.vv.UserManager.getBingoFrom())
        }

    },

    onEventExpLevelUp: function () {
        this.showLockUI()
    },

    onEventMenulOpen: function () {
        this.onNodeClicked()
    },

    update(dt) {

    },


});
