cc.Class({
    extends: cc.Component,

    properties: {

    },


    onLoad() {
        let btnClose = cc.find("content/top/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        this._gift = null
        this._buff = null

        let btnBuy1 = cc.find("content/list/view/content/item1/btn_buy", this.node)
        btnBuy1.on('click', this.onClickBuyGift, this)

        let btnBuy2 = cc.find("content/list/view/content/item2/btn_buy", this.node)
        btnBuy2.on('click', this.onClickBuyBuff, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP_EX, this.onRcvShopEx, this);
        cc.vv.NetManager.registerMsg(MsgId.NOTIFY_BINGO_BUFF_BUYED, this.onRcvNetBingoBuffBuyed, this)
        cc.vv.NetManager.registerMsg(MsgId.NOTIFY_BINGO_GIFT_BUYED, this.onRcvNetBingoGiftBuyed, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_BINGO_INFO, this.onRcvNetBingoInfo, this)

        Global.playComEff("ch_popup_l2")

        var req = { 'c': MsgId.REQ_SHOP_EX };
        req.uid = Global.playerData.uid;
        req.stype = "22,23";
        cc.vv.NetManager.send(req);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP_EX, this.onRcvShopEx, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.NOTIFY_BINGO_BUFF_BUYED, this.onRcvNetBingoBuffBuyed, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.NOTIFY_BINGO_GIFT_BUYED, this.onRcvNetBingoGiftBuyed, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_BINGO_INFO, this.onRcvNetBingoInfo, false, this)
    },

    showEndTime(endTime) {
        Global.setLabelString("content/list/view/content/item2/time_bg/lbl_time",
            this.node, "End time:\n" + Global.getTimeStr(endTime))
    },

    refreshView() {
        let content = cc.find("content/list/view/content", this.node)
        if (this._gift) {
            Global.setLabelString("item1/btn_buy/lbl_price", content, "$ " + this._gift.amount)
            Global.setLabelString("item1/lbl_coin", content, Global.FormatNumToComma(this._gift.count))
            //benifist
            let btn = cc.find("item1/btn_benifist", content)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._gift.rewards, '1.99$' + cc.vv.UserManager.getBingoFrom())
        }
        if (this._buff) {
            Global.setLabelString("item2/btn_buy/lbl_price", content, "$ " + this._buff.amount)
            Global.setLabelString("item2/lbl_coin", content, Global.FormatNumToComma(this._buff.count))
            cc.find("content/list/view/content/item2/btn_buy", this.node).active = (this._buff.hasBuff == 0)
            //benifist
            let btn = cc.find("item2/btn_benifist", content)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._buff.rewards, '4.99$' + cc.vv.UserManager.getBingoFrom())
        }
    },

    onRcvShopEx(msg) {
        if (msg.code == 200) {
            this._buff = msg.shoplist["data22"][0]
            this._gift = msg.shoplist["data23"][0]
            this.refreshView()
        }
    },

    addUserCoin(coin) {
        if (cc.vv.gameData) {
            cc.vv.gameData.AddCoin(coin, true)
        } else {
            cc.vv.UserManager.AddCoin(coin, true)
        }
    },

    onRcvNetBingoInfo() { },

    onRcvNetBingoGiftBuyed(msg) {
        if (msg.code == 200) {
            //更新用户金币
            this.addUserCoin(msg.count)
            //购买后刷新页面
            let req = { c: MsgId.REQ_BINGO_INFO }
            cc.vv.NetManager.send(req)

            let rdArray = msg.rewards
            if (cc.isValid(msg.point)) {
                let obj = new Object
                obj.type = 16
                obj.count = msg.point
                rdArray.unshift(obj)
            }
            //buyRewardPop
            cc.loader.loadRes("CashHero/prefab/buyRewardPop/buyRewardPop", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("buyRewardPop")) {
                    let node = cc.instantiate(prefab)
                    node.name = "buyRewardPop"
                    node.parent = canvas
                    node.getComponent("buyRewardPop").buyBingoGIft(rdArray)
                }
            })

            this.node.destroy()
        }
    },

    onRcvNetBingoBuffBuyed(msg) {
        if (msg.code == 200) {
            //更新用户金币
            this.addUserCoin(msg.count)
            //购买后刷新页面
            let req = { c: MsgId.REQ_BINGO_INFO }
            cc.vv.NetManager.send(req)

            //buyRewardPop
            cc.loader.loadRes("CashHero/prefab/buyRewardPop/buyRewardPop", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("buyRewardPop")) {
                    let node = cc.instantiate(prefab)
                    node.name = "buyRewardPop"
                    node.parent = canvas
                    node.getComponent("buyRewardPop").buyBingoBuff(msg.rewards)
                }
            })

            this.node.destroy()
        }
    },

    onClickBuyGift() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_BUY_GIFT, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_btn_click")
        if (this._gift) {
            cc.vv.PayMgr.reqPurchaseOrder(this._gift.id)
        }
    },

    onClickBuyBuff() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_BUY_BUFF, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_btn_click")
        if (this._buff) {
            cc.vv.PayMgr.reqPurchaseOrder(this._buff.id)
        }
    },

    onClickClose() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_BUY_BACK, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_close")
        this.node.destroy()
    },
});
