        this.ShowExp()
        this.ShowCoin()
        this.ShowDiamond()
        this.ShowVip()
        // 主动检测一下小红点
        this.onEventRefushRedTips()
        StatisticsMgr.reqReport(StatisticsMgr.REQ_ENTER_HALL);
