    // 金币
    ShowCoin: function () {
        let val = cc.vv.UserManager.coin
        let lblCoin = cc.find('top/coin_bg/lbl_coin', this.node)
        lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(Math.floor(val));
    },

    //Exp
    ShowExp: function () {
        // 等级
        let lv = cc.vv.UserManager.level;
        cc.find('top/exp_bg/lbl_lv', this.node).getComponent(cc.Label).string = "Lv." + lv.toString();
        let exp = cc.vv.UserManager.getCurExp()
        let upExp = cc.vv.UserManager.getUpdateExp()
        let per = exp / upExp
        if (per > 1) {
            per = 1
        }
        else if (per < 0.1) {
            per = 0.1 // 最低就显示成0.1，有星星盖住，看不到的。主要
        }
        let proCmp = cc.find('top/exp_bg/pro_exp', this.node)
        if (proCmp) {
            proCmp.getComponent(cc.ProgressBar).progress = per

        }
    },

    //Vip
    ShowVip() {
        let vipLv = cc.vv.UserManager.getVipLevel()
        // 会有新的地方显示vip
        // TODO
        // cc.find("top/vip_bg/lbl_lv", this.node).getComponent(cc.Label).string = ""+vipLv;
        let p = cc.vv.UserManager.getVipPro();
        cc.find("top/vip_bg/pro_exp", this.node).getComponent(cc.ProgressBar).progress = Math.max(0.01, p);
        cc.find("top/vip_bg/lbl_pro", this.node).getComponent(cc.Label).string = Math.floor(p * 100) + "%"
        // 替换vipicon
        cc.find("top/vip_bg/vip_icon", this.node).getComponent("CH_Vipicon").showVip(vipLv)
    },

    // Diamond
    ShowDiamond() {
        let nVal = cc.vv.UserManager.getDiamond()
        cc.find("top/dio_bg/lbl_val", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(nVal);
    },

