    // 点击等级详情
    onClickLV: function () {
        let self = this
        cc.loader.loadRes("common/prefab/level_up_tips", cc.Prefab, (err, prefab) => {
            if (!err) {
                let tipPos
                let old = self.node.getChildByName('level_up_tips')
                if (!old) {
                    let node = cc.instantiate(prefab)
                    node.name = 'level_up_tips'
                    node.parent = self.node
                    old = node
                    let lvNode = cc.find('Canvas/top/exp_bg/lbl_lv')
                    if (lvNode) {
                        let pos = lvNode.convertToWorldSpaceAR(cc.Vec2(0, 0))
                        tipPos = self.node.convertToNodeSpaceAR(pos)

                    }
                }
                let script = old.getComponent('level_up_tips')
                let expNeed = cc.vv.UserManager.getUpdateExp() - cc.vv.UserManager.getCurExp()
                let nextReward = cc.vv.UserManager.getNextLvReward()
                script.setUIData(expNeed, nextReward, tipPos)
            }
        })
    },

