    OnRcvNetMoneyChanged: function (msg) {
        if (msg.code == 200) {
            if (msg.uid == Global.playerData.uid) {
                cc.vv.UserManager.coin = msg.coin
                this.ShowCoin()
            }
        }
    },

    OnRcvPersonalInfoChanged: function (msg) {
        if (msg.code == 200) {
            if (this._bBind && msg.playerInfo && msg.playerInfo.uid == cc.vv.UserManager.uid) {
                cc.vv.UserManager.userIcon = msg.playerInfo.usericon
                cc.vv.UserManager.setNickName(msg.playerInfo.playername)
                this.ShowHead()
                this.ShowExp()
                this.ShowCoin()
                this.ShowDiamond()
                this.ShowVip()
                this._bBind = null
            }
        }
    },

    // 刷新红点
    onEventRefushRedTips(data) {
        let refushType
        if (data && data.detail) {
            refushType = data.detail
        }
        if (refushType == 'herocard') {
            // 单独刷herocard
            if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)) {
                cc.find("bottom/btn_poker/reddot", this.node).active = cc.vv.HerocardManager.bHaveCardCanUnlock() || cc.vv.HerocardManager.bHaveCardCanAddStar() || cc.vv.HerocardManager.bHaveCardAcviment()
                cc.find("bottom/btn_poker/reddot_num", this.node).active = false
            }
            else {
                cc.find("bottom/btn_poker/reddot", this.node).active = false
                this.onEventUpdateHerocardRed()
            }
            return
        }
        // 刷所有的红点
        let AppData = cc.vv.RedSys;
        // shop 改用reddotui控制了
        // cc.find("bottom/btn_buy/reddot", this.node).active = (AppData.getRedTip(6) || AppData.getRedTip(101)) && (!Global.isClosePurchase());
        // bonus的红点
        let bonusNum = 0
        let bonusRed = [1, 3, 5, 7, 9, 14, 18, 19, 20]
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_CARD)) {
            bonusRed.push(10)
        }
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)) {
            bonusRed.push(11)
        }
        for (let i = 0; i < bonusRed.length; i++) {
            let item = AppData.getRedTip(bonusRed[i])
            if (item) {
                if (cc.js.isNumber(item)) {
                    bonusNum += item
                }
                else {
                    bonusNum += 1
                }
            }
        }
        let node_bonunRed = cc.find("bottom/btn_bonus/reddot", this.node)
        node_bonunRed.active = cc.vv.UserManager.isOpen(Global.SYS_OPEN.HALL_BONUS) && bonusNum;
        Global.setLabelString("val", node_bonunRed, bonusNum)
        // //friend红点 改用reddotui控制了
        // cc.find("bottom/btn_friend/reddot", this.node).active = AppData.getRedTip(8) || AppData.getRedTip(21)
        // let bonus_content = cc.find("pages/view/content/page_bonus/list_bonus/view/content", this.node);
        // cc.find("daily_bonus/reddot", bonus_content).active = AppData.getRedTip(5);
        // cc.find("online_bonus/reddot", bonus_content).active = AppData.getRedTip(1);
        // cc.find("daily_task/reddot", bonus_content).active = AppData.getRedTip(3);
        // cc.find("share/reddot", bonus_content).active = AppData.getRedTip(7);
        // cc.find("bonus_quest/reddot", bonus_content).active = AppData.getRedTip(9);
        // cc.find("lucky_card/reddot", bonus_content).active = AppData.getRedTip(10);
        // cc.find("bingo/reddot", bonus_content).active = AppData.getRedTip(11);
        // herocard
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)) {
            cc.find("bottom/btn_poker/reddot", this.node).active = cc.vv.HerocardManager.bHaveCardCanUnlock() || cc.vv.HerocardManager.bHaveCardCanAddStar() || cc.vv.HerocardManager.bHaveCardAcviment()
            cc.find("bottom/btn_poker/reddot_num", this.node).active = false
        }
        else {
            cc.find("bottom/btn_poker/reddot", this.node).active = false
            this.onEventUpdateHerocardRed()
        }
        // 头像红点
        cc.find("top/node_head/reddot", this.node).active = !Global.getLocal("clickHead", "") || AppData.getRedTip(26)
        // let slotMenu = this.node.getComponentInChildren("CH_PageSlot_MenuR")
        // if(slotMenu){
        //     //hero_palace红点
        //     slotMenu.checkPalaceReddot()
        //     // slotMenu.checkMailReddot()
        // }
    },

    onEventUpdateHerocardRed() {
        // herocard
        let herocardReddot = cc.find("bottom/btn_poker/reddot_num", this.node)
        let datas = cc.vv.HerocardManager.getHeroCardRedData()
        let num = datas.length
        herocardReddot.active = num
        cc.find('label', herocardReddot).getComponent(cc.Label).string = num
    },

    //FB绑定成功
    OnEventFbBindSuccess: function (data) {
        let self = this
        let bindAddCoin = data.detail
        this._bBind = true
        let req = { c: MsgId.PERSIONAL_INFO };
        req.otheruid = Global.playerData.uid;
        cc.vv.NetManager.send(req);
        // 弹出绑定奖励TODO
        // 并且清理Friend节点上的bind图标
        // cc.find('Canvas/bottom/btn_club/fbBindTip').active = false;
        if (bindAddCoin && bindAddCoin > 0) {
            let callbacks = function (prefab) {
                let node = cc.instantiate(prefab)
                if (node && cc.isValid(self.node)) {
                    node.parent = self.node
                    node.name = 'CommonAddCoin'
                    //TODO 完善CH_FBBindTip的逻辑
                    let cmp = node.getComponent('CH_CommonAddCoin')
                    cmp.setCoin(bindAddCoin, cc.find(Global.HALL_COIN_NODE_PATH))
                }
            }
            this._loadPrefab('CashHero/prefab/CommonAddCoin', callbacks)
        }
    },

    //下载成功子游戏
    OnDownloadSuccess: function (data) {
        let self = this
        let id = data.detail
        let gameCfg = cc.vv.GameItemCfg[id]
        if (gameCfg) {
            let old = cc.find('update_success', this.node)
            if (old) {
                //已经有了
                let cmp = old.getComponent('CH_HallUpdateSuccess')
                cmp.ShowGameInfo(id)
                return
            }
            let callbacks = function (prefab) {
                let node = cc.instantiate(prefab)
                if (node && cc.isValid(self.node)) {
                    node.parent = self.node
                    node.name = 'update_success'
                    let cmp = node.getComponent('CH_HallUpdateSuccess')
                    cmp.ShowGameInfo(id)
                }
            }
            this._loadPrefab('CashHero/prefab/update_success', callbacks)
        }
    },

    // 其他人中了大奖通知
    onEventJackpotNotice: function (mag) {
        let self = this;
        let data = mag.detail;
        let old = cc.find('notice_jackpot', self.node);
        if (old) return
        let url = "common/prefab/notice_jackpot"
        let callbacks = function (prefab) {
            let node = cc.instantiate(prefab);
            if (node && cc.isValid(self.node, true)) {
                node.name = 'notice_jackpot';
                node.parent = self.node;
                let script = node.getComponent('notice_jackpot');
                script.setUIData(data);
            }
        }
        this._loadPrefab(url, callbacks)

    },

    onEventLevelUpGift: function () {
        let self = this
        let url = "common/prefab/level_up_gift"
        let callbacks = function (prefab) {
            let node = cc.instantiate(prefab, true)
            if (node && cc.isValid(self.node)) {
                node.parent = self.node
                node.name = 'level_up_gift'

            }
        }
        this._loadPrefab(url, callbacks)
    },

