    _checkEnterHallAction: function () {
        let action = cc.vv.UserManager.getEnterHallAction()
        if (action) {
            cc.vv.UserManager.setEnterHallAction(null)
            switch (action) {
                case 'friend':
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 4)
                    break;
                case 'herocard':
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 1)
                    break
                case 'bonus':
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
                    break;
                case 'open_mail':
                    let slotMenu = this.node.getComponentInChildren("CH_PageSlot_MenuR")
                    if (slotMenu) {
                        slotMenu.onClickEmail()
                    }
                    break
                case 'ani_enter':
                    this._loadAniEnter()
                    break
                default:
                    break;
            }
        }
    },

    onEventRecordClickGame: function () {
        this.setCurScroff()
    },

    onEventCheckUserAction: function () {
        this._checkEnterHallAction()
    },

    _loadAniEnter: function () {
        let node_trans = cc.find('node_transion', this.node)
        node_trans.active = true
        // node_trans.x = 0
        // node_trans.y = 0
        node_trans.getComponent("LMSlots_Transition").play(-1)
    },

    onEventTabSlotScroll: function (param) {
        let data = param.detail
        let movedir = data.dir
        let bottom = cc.find("bottom", this.node)
        let top = cc.find("top", this.node)
        let ac = bottom.getNumberOfRunningActions()
        if (ac > 0) {
            return
        }
        if (movedir == 1) {
            //up：底部消失
            cc.tween(bottom)
                .to(0.2, { y: this._orgBottomY - 450 })
                .start()

            cc.tween(top)
                .to(0.2, { y: this._orgTopY + 450 })
                .start()
        }
        else {
            //down：底部出现
            cc.tween(bottom)
                .to(0.2, { y: this._orgBottomY })
                .start()

            cc.tween(top)
                .to(0.2, { y: this._orgTopY })
                .start()
        }
    },

    _resetBottomPos: function () {
        let bottom = cc.find("bottom", this.node)
        bottom.y = this._orgBottomY

        let top = cc.find("top", this.node)
        top.y = this._orgTopY
    },

    onEventGoHallTab: function (data) {
        let tabIdx = data.detail
        if (tabIdx != 2) {
            this._resetBottomPos()
        }
    },

