    sendChat(tp, txt) {
        let now = new Date().getTime();
        if (now - this._sendTime < 10000) { //5秒，防止刷数据
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_send_frequently);
            // cc.vv.FloatTip.show("Send too frequently")
            return false;
        }
        this._sendTime = now;
        this._showNewTip(false)
        //区分是否是私聊
        let req = {}
        if (this._privateFlag) {
            req.c = MsgId.REQ_PRIVATE_SEND
            req.type = 1
            req.uid = Global.playerData.uid
            req.touid = this._clickUID
            req.msg = txt
        } else {
            req.c = MsgId.REQ_WORLD_CHAT
            req.lastid = this._lastid
            req.content = txt
            req.stype = tp
        }
        cc.vv.NetManager.send(req, true);
        return true
    },

    refushUI: function () {
        this._showMsgByType(this._curSel)
    },

    _showSelMsg: function (bWithoutScro) {

        // console.log('this._listShowData:',this._listShowData)
        if (this._listShowData == null) return;
        this.chatList.numItems = this._listShowData.length > 0 ? this._listShowData.length : 0;

        let scroTime = bWithoutScro ? 0 : null
        if (this._curSel == BSELIDX.PRIVATE) {
            this.chatList.scrollTo(0, scroTime)
        }
        else {
            this.chatList.scrollTo(1000, scroTime)
        }



    },

    ShowListItem: function (item, idx) {
        let itemData = this._listShowData[idx]
        if (itemData) {
            item.active = true;

            if (this._curSel == BSELIDX.PRIVATE) {
                item.getComponent('CH_ChatListItem').init(itemData, this, 2)
            } else {
                item.getComponent('CH_ChatListItem').init(itemData, this)
            }
        }
        else {
            item.active = false
        }
    },

    // 聊天时间排序
    sortPrivateMsg: function (data) {
        let sorFunc = function (a, b) {
            return a.create_time - b.create_time
        }
        data.sort(sorFunc)
        return data;
    },

    _showPrivateSelMsg: function () {
        if (this._privateListShowData == null) return;
        this._privateListShowData = this.sortPrivateMsg(this._privateListShowData)
        this.privateList.numItems = this._privateListShowData.length > 0 ? this._privateListShowData.length : 0;
        this.scheduleOnce(() => {
            this.privateList.scrollTo(1000, 0)
        }, 0.01)
        this._showNewTip(false)
    },

    ShowPrivateListItem: function (item, idx) {
        let itemData = this._privateListShowData[idx]
        if (itemData) {
            item.active = true;
            item.getComponent('CH_ChatListItem').init(itemData, null, 3, this._friendInfo)
        }
        else {
            item.active = false
        }
    },

    //如果处于私聊情况下不刷新 私聊结束后调用刷新
    onRcvChat: function (msg) {


        if (msg.code == 200) {
            this._requestTime = PULL_INTERVAL



            if (this._listData == null) {
                this._listData = []
            }
            let maxid = 0
            let ownid = Global.playerData.uid
            let hasOwn = false
            let cnt = msg.data.items.length

            let newArray = []

            for (let i = 0; i < cnt; i++) {
                let data = msg.data.items[i]
                //不显示排行榜数据
                if (data.id > this._lastid && (data.stype != 4 && data.stype != 6)) {
                    this._listData.push(data)
                    maxid = Math.max(maxid, data.id)

                    if (this._lastid != 0) {//非首次刷新
                        newArray.push(data)
                    }
                    if (data.uid == ownid) {
                        hasOwn = true
                    }
                }
            }

            //只存储30条
            if (this._listData.length > 30) {
                let nDel = this._listData.length - 30
                for (let i = 0; i < nDel; i++) {
                    this._listData.shift()
                }

            }

            //如果正在拖动就不刷新UI
            let scr = this.chatList._scrollView
            if (this.node.active == false || scr.isScrolling()) {
                this._lastid = Math.max(this._lastid, maxid)
                return
            }


            //如果包含自己发送的，则滚动到最后
            if (this._lastid == 0) { //首次刷新
                this.refushUI()
            } else {
                if (hasOwn) {  //自己发送的
                    this._showMsgByType(this._curSel)
                } else {
                    if (cnt > 0) {

                        if (scr.getScrollOffset().y < scr.getMaxScrollOffset().y) {
                            this._newCnt = this._newCnt + cnt
                            let btn_new = cc.find("bottom/btn_new", this.node)
                            cc.find("Background/lbl_cnt", btn_new).getComponent(cc.Label).string = this._newCnt + "NEW"
                            if (this._curSel == BSELIDX.ALL) {
                                btn_new.active = true
                            }
                            // this._showReddot(newArray)
                        } else {
                            this.refushUI()
                        }
                    }
                }
            }

            this._lastid = Math.max(this._lastid, maxid)
        } else {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_send_frequently);
            // cc.vv.FloatTip.show("Send too frequently")
        }
    },



