    _showMsgByType: function (bSelIdx, bWithoutScro) {
        // let strSelType = 'ALL'
        this._curSel = bSelIdx
        this._listShowData = []
        if (this._listData) {
            //更新消息列表
            for (let i = 0; i < this._listData.length; i++) {
                let item = this._listData[i]
                if (this._curSel == BSELIDX.ALL) {
                    //all
                    if (item.stype != ITEMTYPE.GIFT) {
                        this._listShowData.push(item)
                    }
                }
                else if (this._curSel == 2) {
                    // strSelType = 'CHAT'
                    //chat
                    if (item.stype == 1) {
                        this._listShowData.push(item)
                    }
                }
                else if (this._curSel == BSELIDX.GIFT) {
                    // strSelType = 'GIFT'
                    //gift
                    if (item.stype == ITEMTYPE.GIFT) {
                        this._listShowData.push(item)
                    }
                }
                else if (this._curSel == 4) {
                    // strSelType = 'ADD'
                    //add
                    if (item.stype == 2) {
                        this._listShowData.push(item)
                    }
                }
                else if (this._curSel == BSELIDX.RANK) {
                    // strSelType = 'RANK'
                    //rank
                    if (item.stype == ITEMTYPE.RANK_HOUR || item.stype == ITEMTYPE.RANK_CHIP) {
                        this._listShowData.push(item)
                    }
                }
            }
        }


        // //修改选中的类型文字
        // let lblSel = cc.find('top/node_msg_sel/spr_show_bg/lbl_val',this.node)
        // lblSel.getComponent(cc.Label).string = strSelType
        this._showSelMsg(bWithoutScro)
        // }
    },

