    initEmotionList() {
        let self = this
        for (let i = 0; i < 5; i++) {
            let item = cc.find("bottom/lay_emoji/item" + (i + 1), this.node)
            if (item) {
                let clickCall = function () {
                    self.showEmoji(this._isShowEmoji)
                }
                item.getComponent("CH_ChatEmotion").setEmotion(cc.js.formatStr("[emotion%s]", i + 1), clickCall)
            }
        }
    }

