//子任务总数
let TASKITEM_MAX = 3
cc.Class({
    extends: cc.Component,

    properties: {
        _node_detail: null,
        _node_simple: null,
        // _orgpos_detail:null,
        // _orgpos_simple:null,
        _inter: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        //自动适配
        Global.FixDesignScale_V(this.node);

        this._node_info = cc.find('node_info', this.node)
        this._node_info.active = false
        this._node_detail = cc.find('node_drag/content_mask/node_quest_detail', this._node_info)
        this._orgpos_detail = this._node_detail.position

        this._node_simple = cc.find('node_drag/content_mask/node_quest_simple', this._node_info)
        this._orgpos_simple = this._node_simple.position
        // if(cc.sys.platform == cc.sys.IPAD){
        //     this._orgpos_simple.x -= 350
        //     this._orgpos_detail.x -= 350
        // }

        this._node_start_tip = cc.find('node_pop/node_quest_start', this.node)
        this._node_complete_tip = cc.find('node_pop/node_quest_complete', this.node)


        let btnHide = cc.find('btn_hide', this._node_detail)
        Global.btnClickEvent(btnHide, this.onClickHideDetail, this)

        Global.btnClickEvent(cc.find('btn_hide', this._node_simple), this.onClickHideSimple, this)

        let btnComplete_end = cc.find('node_pop/node_quest_complete/btn_complete', this.node)
        Global.btnClickEvent(btnComplete_end, this.onClickCompleteEnd, this)
        let btnComplete_start = cc.find('btn_complete', this._node_start_tip)
        Global.btnClickEvent(btnComplete_start, this.onClickCompleteStart, this)

        Global.registerEvent(EventId.REFUSH_QUEST_PRO, this.onEventRefushPro, this)

        this._completeFlag = false  //是否已经完成

    },


    start() {

        this.showTaskInfo()
        this.showStartUI()

    },

    //设置任务信息
    showTaskInfo: function (bUpdate) {
        let self = this
        let cfg = this._getCurTaskCfg()
        if (cfg) {
            let nCmpleteNum = 0
            for (let i = 0; i < TASKITEM_MAX; i++) {
                let taskVal = cfg.details[i]
                let detailItem = cc.find('lay_content/quest_item' + (i + 1), this._node_detail)
                detailItem.active = taskVal
                let simpleItem = cc.find('lay_content/quest_item' + (i + 1), this._node_simple)
                simpleItem.active = taskVal
                let startUIItem = cc.find(cc.js.formatStr('lay_content/item%s', i + 1), this._node_start_tip)
                let compeletUIItem = cc.find(cc.js.formatStr('lay_content/item%s', i + 1), this._node_complete_tip)
                startUIItem.active = taskVal
                compeletUIItem.active = taskVal
                if (!taskVal) {
                    continue
                }
                //进度
                let nCurVal = 0
                let node_pro_detail = cc.find('node_process/node_procress', detailItem)
                let node_pro_simple = cc.find('node_process/node_procress', simpleItem)

                let bComplete = false
                if (this._curQuestTaskData.details[i]) {
                    nCurVal = this._curQuestTaskData.details[i].value
                    if (this._curQuestTaskData.details[i].complete) {
                        bComplete = true
                        nCmpleteNum++
                    }
                }

                //是否已经完成
                let spr_complete_simple = cc.find('item_complete', simpleItem)
                let lblProSimple = cc.find('lbl_pro', simpleItem)

                let nTotal = taskVal.value
                let nPer = (nCurVal / nTotal)
                let localTaskCfg = this._getTaskLocalDes(cfg.roundid, cfg.taskid, i + 1)



                let sprCoplete_detail = cc.find('spr_gou', detailItem)
                let lblPro = cc.find('lbl_pro', detailItem)
                let lblDes = cc.find('lbl_des', detailItem)
                lblDes.getComponent(cc.Label).string = cc.js.formatStr(localTaskCfg.simple_des, Global.formatNumShort(nTotal))
                // I18N.setI18nLabel(lblDes,cc.vv.Language['quest_ingame_taskdes'+localTaskCfg.langeuageType],Global.formatNumShort(nTotal))
                //开始界面的描述
                let startDes = cc.find('spr_bg/lbl_des', startUIItem)
                startDes.getComponent(cc.Label).string = cc.js.formatStr(localTaskCfg.des, Global.formatNumShort(nTotal))
                // I18N.setI18nLabel(startDes,cc.vv.Language['quest_ingame_taskdes'+localTaskCfg.langeuageType],Global.formatNumShort(nTotal))
                let startComp = cc.find('spr_gou', startUIItem)
                startComp.active = bComplete
                //完成界面的描述
                let completetDes = cc.find('spr_bg/lbl_des', compeletUIItem)
                completetDes.getComponent(cc.Label).string = cc.js.formatStr(localTaskCfg.des, Global.formatNumShort(nTotal))
                // I18N.setI18nLabel(completetDes,cc.vv.Language['quest_ingame_taskdes'+localTaskCfg.langeuageType],Global.formatNumShort(nTotal))
                let completeComp = cc.find('spr_gou', compeletUIItem)
                completeComp.active = bComplete

                if (bUpdate) {
                    //需要动画的表现变化
                    let endCall = function () {
                        //是否完成了，现实完成的表现
                        lblPro.active = !bComplete
                        lblProSimple.active = !bComplete
                        spr_complete_simple.active = bComplete
                        sprCoplete_detail.active = bComplete
                        if (nCmpleteNum == cfg.details.length) {
                            self._completeFlag = true
                            //显示完成界面  如果处于空闲状态并且不在免费游戏中则完成 否则则在免费游戏中
                            if (!cc.vv.gameData.GetFreeTime()) {
                                self.showCompleteUI()
                            }
                        }
                    }
                    let nEnd = Math.floor(nPer * 100)
                    let newStr = nEnd + '%'
                    if (localTaskCfg.type == 1) {
                        lblPro.getComponent(cc.Label).string = cc.js.formatStr("%s/%s", nCurVal, nTotal)
                        lblProSimple.getComponent(cc.Label).string = cc.js.formatStr("%s/%s", nCurVal, nTotal)
                        endCall()
                    }
                    else {

                        let oldStr = lblPro.getComponent(cc.Label).string
                        let nBegin = Number(oldStr.replace('%', ''))

                        lblPro.getComponent('LabelRollCmp').startRoll(nBegin, nEnd, 1, endCall)

                        let oldStrSimple = lblProSimple.getComponent(cc.Label).string
                        let nBeginSimple = Number(oldStrSimple.replace('%', ''))
                        lblProSimple.getComponent('LabelRollCmp').startRoll(nBeginSimple, nEnd, 1, endCall)
                    }


                    this.setProgress(node_pro_detail, nPer, 1)
                    this.setProgress(node_pro_simple, nPer, 1)
                }
                else {
                    if (localTaskCfg.type == 1) {
                        lblPro.getComponent(cc.Label).string = cc.js.formatStr("%s/%s", nCurVal, nTotal)
                        lblProSimple.getComponent(cc.Label).string = cc.js.formatStr("%s/%s", nCurVal, nTotal)
                    }
                    else {
                        lblPro.getComponent(cc.Label).string = Math.floor(nPer * 100) + '%'
                        lblProSimple.getComponent(cc.Label).string = Math.floor(nPer * 100) + '%'
                    }

                    this.setProgress(node_pro_detail, nPer)
                    this.setProgress(node_pro_simple, nPer)
                    spr_complete_simple.active = bComplete
                    sprCoplete_detail.active = bComplete
                    lblPro.active = !bComplete
                    lblProSimple.active = !bComplete
                }
            }

            //设置间隔
            let hasTaskNum = cfg.details.length
            let spaceY = 32
            if (hasTaskNum == 2) {
                spaceY = 60
            }
            let lay_content = cc.find('lay_content', this._node_detail)
            lay_content.getComponent(cc.Layout).spacingY = spaceY
        }
    },

    //动画的进度条
    setProgress(obj, progress, nTime = 0) {
        progress = Math.min(1, Math.max(0, progress));
        let minY = -100, maxY = -24;
        let toVal = minY + (maxY - minY) * progress;
        cc.tween(obj)
            .to(nTime, { y: toVal })
            .start()
    },

    //显示进入动画
    showEnterAction: function () {
        this._node_info.active = true

        // 默认打开
        // this._node_detail.active = true
        // this._node_simple.active = false
        // this._node_detail.stopAllActions()
        // this._node_detail.y = this._orgpos_detail.y+600

        // cc.tween(this._node_detail)
        // .delay(0.2)
        // .to(0.5,{y:this._orgpos_detail.y},{easing:'backOut'})
        // .start()


        //默认收起来
        this._node_simple.active = true
        this._node_detail.active = false
        this._node_simple.stopAllActions()
        this._node_simple.y = this._orgpos_simple.y + 300
        cc.tween(this._node_simple)
            .delay(0.2)
            .to(0.5, { y: this._orgpos_simple.y }, { easing: 'backOut' })
            .start()
    },


    onClickHideDetail: function () {
        if (this._node_detail.getNumberOfRunningActions() > 0) {
            return
        }
        Global.playComEff("ch_btn_click");
        this._node_detail.stopAllActions()
        this._node_detail.active = true
        cc.tween(this._node_detail)
            .to(0.5, { y: this._orgpos_detail.y + 600 })
            .call(() => {
                this._node_detail.active = false
            })
            .start()

        this._node_simple.active = true
        this._node_simple.stopAllActions()
        this._node_simple.y = this._orgpos_simple.y + 300
        cc.tween(this._node_simple)
            .delay(0.2)
            .to(0.5, { y: this._orgpos_simple.y }, { easing: 'backOut' })
            .start()
    },

    onClickHideSimple: function () {
        if (this._node_simple.getNumberOfRunningActions() > 0) {
            return
        }
        Global.playComEff("ch_btn_click");

        this._node_detail.stopAllActions()
        this._node_detail.y = this._orgpos_detail.y + 600
        this._node_detail.active = true
        cc.tween(this._node_detail)
            .delay(0.2)
            .to(0.5, { y: this._orgpos_detail.y }, { easing: 'backOut' })
            .start()

        this._node_simple.stopAllActions()
        this._node_simple.active = true
        cc.tween(this._node_simple)
            .to(0.5, { y: this._orgpos_simple.y + 300 })
            .call(() => {
                this._node_simple.active = false
            })
            .start()
    },

    onEventRefushPro: function () {
        //如果已经完成 则弹出完成弹窗
        if (this._completeFlag) {
            this.showCompleteUI()
            return
        }

        this.showTaskInfo(true)
    },

    //显示quest界面提示
    showStartUI: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTINGAME_START)

        // cc.vv.gameData.PauseSlot()
        this._showCompopAction(this._node_start_tip)
        this.discountTime = 5;
        this.showDiscountTime();
    },

    //显示任务完成界面
    showCompleteUI: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTINGAME_END)

        // cc.vv.gameData.PauseSlot()
        let node_reward = cc.find('node_pop/node_quest_complete', this.node)
        this._showCompopAction(node_reward)
    },

    _showTimeOutUI: function () {
        // cc.vv.gameData.PauseSlot()
        let node_timeout = cc.find('node_pop/quest_time_out', this.node)
        this._showCompopAction(node_timeout)
    },

    _showCompopAction(node) {
        let nodepop = cc.find('node_pop', this.node)
        //已经存在了，就不再弹出了
        if (cc.find('Canvas/node_pop')) return

        cc.vv.gameData.PauseSlot()
        let copyNode = cc.instantiate(nodepop)
        copyNode.parent = cc.find('Canvas')
        Global.FixDesignScale_V(copyNode)


        let showNode = cc.find(node.name, copyNode)
        let laybg = cc.find('lay_bg', copyNode)
        laybg.active = true
        showNode.active = true

        let collectBtn = cc.find('btn_complete', showNode)
        // collectBtn.getComponent(cc.Button).interactable = false
        // collectBtn.active = false
        // let aniName = 'quest_time_out_play'
        if (node.name == 'node_quest_complete') {
            // aniName = 'node_quest_complete_play'
            collectBtn.getComponent(cc.Button).interactable = true;
            Global.btnClickEvent(collectBtn, this.onClickCompleteEnd, this)
            this._newLabelComplete = cc.find("node_quest_complete/btn_complete/Background/layout/DisCount", copyNode)

            this.discountTime2 = 5;
            this.showDiscountTime2();
        }
        else if (node.name == 'node_quest_start') {
            // aniName = 'node_quest_start_play'
            Global.btnClickEvent(collectBtn, this.onClickCompleteStart, this)
            this._newLabel = cc.find("node_quest_start/btn_complete/Background/layout/DisCount", copyNode)
        }

        let nodeloopEff = cc.find('node_pop_ef', copyNode)
        nodeloopEff.active = false
        let showpopEnd = function () {
            nodeloopEff.active = true
        }
        let winbase = showNode.getComponent("CH_popwin_base")
        winbase.setShowEndCall(showpopEnd)


        // //游戏icon
        // let node_icon = cc.find('slot_icon',showNode)
        // if(node_icon){
        //     let gameId = this._getCurTaskCfg().gameid
        //     node_icon.getComponent("CH_SlotIcon").setGameId(gameId)
        // }

        Global.playComEff("ch_notification");
    },

    onClickCompleteEnd: function () {
        cc.find('Canvas/node_pop/node_quest_complete/btn_complete').getComponent(cc.Button).interactable = false;
        //回到Quest主界面
        //推出游戏
        cc.vv.gameData.ResumeSlot()
        this.unschedule(this.showDiscountTime2callback);

        Global.playComEff("ch_close");
        cc.vv.gameData.requestExit()

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTINGAME_END_CONTINUE)
    },

    onClickCompleteStart: function () {
        Global.playComEff("ch_close");
        cc.vv.gameData.ResumeSlot()

        let oldNode = cc.find('Canvas/node_pop')
        if (oldNode) {
            oldNode.destroy()
        }
        this.showEnterAction()

        this.unschedule(this.showDiscountTimeCallback);

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTINGAME_START_CONTINUE)
    },



    //获取服务端的活动配置
    _getCurTaskCfg: function () {
        let taskInfo = cc.vv.UserManager.getQuestInfo()
        this._curQuestTaskData = taskInfo.data
        let taskid = this._curQuestTaskData.taskid
        let taskCfg = taskInfo.roundCfg.tasks
        for (let i = 0; i < taskCfg.length; i++) {
            if (taskid == taskCfg[i].taskid) {
                this._gameQuestTaskCfg = taskCfg[i]
                break
            }
        }
        return this._gameQuestTaskCfg
    },

    //获取本地任务的描述
    _getTaskLocalDes: function (round, taskid, detailid) {
        let id = cc.js.formatStr('%s%s%s', round, taskid, detailid)
        for (let i = 0; i < QUEST_TASK_CFG.length; i++) {
            let item = QUEST_TASK_CFG[i]
            if (item.taskid == id) {
                return item
            }
        }
    },

    //显示倒计时
    showDiscountTime: function () {

        this.schedule(this.showDiscountTimeCallback, 1)
    },

    showDiscountTimeCallback: function () {
        this._newLabel.getComponent(cc.Label).string = "(" + String(this.discountTime) + ")"

        if (this.discountTime <= 0) {
            this.unschedule(this.showDiscountTimeCallback);
            this.onClickCompleteStart()
        }
        --this.discountTime;
    },

    showDiscountTime2: function () {

        this.schedule(this.showDiscountTime2callback, 1)
    },

    showDiscountTime2callback: function () {
        this._newLabelComplete.getComponent(cc.Label).string = "(" + String(this.discountTime2) + ")"

        if (this.discountTime2 <= 0) {
            this.unschedule(this.showDiscountTime2callback);
            this.onClickCompleteEnd()
        }
        --this.discountTime2;
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1) {
            this._inter = 0
            let questInfo = cc.vv.UserManager.getQuestInfo()
            if (questInfo) {
                let endtime = questInfo.data.begintime * 1000 + questInfo.data.duration * 1000
                let nowtime = new Date().getTime();
                if (endtime - nowtime < 0) {
                    cc.vv.UserManager.setQuestInfo(null)
                    this._showTimeOutUI()
                    return
                }

            }

        }
    }


});
