    //当前英雄显示的是图片还是动画
    getCurShowNode() {
        let spineNode = cc.find('node_info/node_draw/mask/spine_hero', this.node)
        if (spineNode.active) {
            return spineNode
        }
    },

    onTouchStart(event) {
        if (this._isDoingGuide) return
        if (this._bShowNext) {
            this._startPos = event.touch.getLocation();
        }

    },

    onTouchCancel(event) {
        if (this._isDoingGuide) return
        if (this._bShowNext) {
            let node = this.getCurShowNode()
            node.x = 0

            this._prePos = null
        }

    },

    onTouchMove(event) {
        if (this._isDoingGuide) return
        if (this._bShowNext) {
            let location = event.getLocation();
            let xDif = 0
            if (this._prePos) {
                xDif = location.x - this._prePos.x
            }
            let node = this.getCurShowNode()
            node.x += xDif
            this._prePos = location
        }

    },

    onTouchEnd(event) {
        if (this._isDoingGuide) return

        if (this._bShowNext) {
            if (this._startPos) {
                let endPos = event.getLocation()
                let diffx = endPos.x - this._startPos.x
                if (diffx < -50) {  //next page
                    let btnRight = cc.find("node_info/info/btn_right", this.node)
                    if (btnRight.active && btnRight.opacity > 0) {
                        this.onBtnRight()
                    }
                    else {
                        let node = this.getCurShowNode()
                        node.x = 0
                    }
                } else if (diffx > 50) { //pre page
                    let btnLeft = cc.find("node_info/info/btn_left", this.node)
                    if (btnLeft.active && btnLeft.opacity > 0) {
                        this.onBtnLeft()
                    }
                    else {
                        let node = this.getCurShowNode()
                        node.x = 0
                    }
                }
            }

            this._prePos = null
        }


    },

    showUpgradeEffct(callback, effectType) {
        let btnLeft = cc.find("node_info/info/btn_left", this.node)
        let btnRight = cc.find("node_info/info/btn_right", this.node)
        if (btnLeft.active) btnLeft.runAction(cc.sequence(cc.fadeOut(0), cc.delayTime(2), cc.fadeIn(0.1)))
        if (btnRight.active) btnRight.runAction(cc.sequence(cc.fadeOut(0), cc.delayTime(2), cc.fadeIn(0.1)))

        //升星动画
        this.initStars(true)

        let spine = cc.find("node_info/node_draw/spine_upgrade", this.node)
        let ske = spine.getComponent(sp.Skeleton)
        spine.active = true
        ske.setAnimation(0, effectType == EFFECT_TYPE.UNLOCK ? "animation" : "animation2", false);
        spine.getComponent(sp.Skeleton).setCompleteListener(() => {
            ske.setCompleteListener(null)
            spine.active = false
            if (callback) callback()
        })
    },

