    updateCardTaskStatus() {
        if (this._cardInfo) {
            cc.find("node_top/btn_reward/reddot_num", this.node).active = this._cardInfo.st > 0 ? true : false
            cc.find("node_top/btn_reward/Background", this.node).getComponent(sp.Skeleton).setAnimation(0, this._cardInfo.st > 0 ? "animation2" : "animation", true)
            if (this._cardInfo.st > 0) {
                cc.find("node_top/btn_reward/reddot_num/num", this.node).getComponent(cc.Label).string = this._cardInfo.st
            }
        }
    },

    onEventUpdateChipsNum(msg) {
        if (cc.isValid(msg)) {
            if (this._cardInfo.cardid == msg.detail.cardid) {
                this._cardInfo = msg.detail
            } else {
                return
            }
        }

        this._bDescUp = false;
        let bUnlock = (cc.vv.HerocardManager.getChipLv(this._cardInfo) > 0)
        let cardInfo = this._cardInfo
        let starCfg = cc.vv.HerocardManager.getCardStarCfg(cardInfo.cardid, cardInfo.star + 1)
        //拥有的碎片数量
        let lbl_chipnum = cc.find('node_info/info/chips/lbl_chips', this.node)
        let chip_num = cc.vv.HerocardManager.getChipNums(cardInfo)
        if (bUnlock) {
            lbl_chipnum.getComponent(cc.Label).string = starCfg ? chip_num + "/" + starCfg.need_chips : chip_num
        } else {
            lbl_chipnum.getComponent(cc.Label).string = chip_num + "/" + cardInfo.cfg.unlock_chips
        }
        //总经验
        cc.find("node_totalExp/lbl", this.node).getComponent(cc.Label).string = Global.convertNumToShort(cc.vv.UserManager.getPvpCardExp(), 1000, 1);
        this.setDetailType()
        this._updateCardInfo(cardInfo)
        this.updateCardTaskStatus()
        this.refushInfo()
        this.showExp();
        this.showDetail();
        this.showRank();
        this.showAttribute();
    },

