    //outDir:移动出来的动画
    _showCard(cardInfo, bShowNext, outDir) {
        let self = this
        if (!cardInfo) return

        this._cardInfo = cardInfo
        this._bShowNext = bShowNext

        //判断当前处于哪种状态 锁住/能解锁 解锁后能否升星
        let bUnlock = (cc.vv.HerocardManager.getChipLv(cardInfo) > 0)
        let node_info = cc.find('node_info', this.node)

        //星级 进度条等
        this.onEventUpdateChipsNum()

        //top成就
        let maxcoin = cc.vv.HerocardManager.getCardTaskMaxCoin(cardInfo.cardid)
        Global.setLabelString("node_top/iconAnim/num", this.node, Global.FormatNumToComma(maxcoin))
        //金币跳动
        let _jumpTime = 0.8
        let _anim = cc.find('node_top/iconAnim', this.node)
        _anim.stopAllActions()
        cc.tween(_anim)
            .repeatForever(
                cc.tween()
                    .to(_jumpTime / 2, { scale: 1.3 }, { easing: 'quadOut' })
                    .to(_jumpTime / 2, { scale: 0.8 }, { easing: 'quadOut' })
                    .to(_jumpTime / 2, { scale: 1.1 }, { easing: 'quadOut' })
                    .to(_jumpTime / 3, { scale: 0.9 }, { easing: 'quadOut' })
                    .to(_jumpTime / 3, { scale: 1 }, { easing: 'quadOut' })
                    .delay(1)
            )
            .start()

        this.initStars(false)
        this.refushInfo()
        //name
        // cc.find('info/name/lbl_name',node_info).getComponent(cc.Label).string = cardInfo.cfg.name
        I18N.setI18nLabel(cc.find('info/name/lbl_name', node_info), cc.vv.Language["cardname_" + cardInfo.cardid])

        //hero
        //释放资源
        let bHasIn = false
        for (let i = 0; i < this._loadSpineIds.length; i++) {
            if (this._loadSpineIds[i] == cardInfo.cardid) {
                bHasIn = true
                break
            }
        }
        if (!bHasIn) {
            this._loadSpineIds.push(cardInfo.cardid)
        }

        let loadComplete = function () {

            if (self._loadSpineIds && self._loadSpineIds.length >= 2) {
                cc.vv.HerocardManager.releaseRoleSpineDir(self._loadSpineIds.shift())
            }
            self._bCanNext = true
        }
        let spineHero = cc.find('node_info/node_draw/mask/spine_hero', this.node)
        let spCMP = spineHero.getComponent(sp.Skeleton)
        if (bUnlock) {
            spCMP.setMaterial(0, cc.Material.getBuiltinMaterial("2d-spine"))
            if (cardInfo.star <= 0) {
                cc.vv.HerocardManager.loadHeroAvatarsSpine(spineHero, cardInfo.cardid, "idle1", loadComplete)
            } else {
                cc.vv.HerocardManager.loadHeroAvatarsSpine(spineHero, cardInfo.cardid, "idle2", loadComplete)
            }
        } else {
            cc.vv.HerocardManager.loadHeroAvatarsSpine(spineHero, cardInfo.cardid, "idle1", loadComplete)
            //spine灰太
            spCMP.setMaterial(0, this.gray_spine)
        }
        spineHero.active = true
        spineHero.x = 0
        if (cardInfo.cardid > 1060) {
            spineHero.setScale(1)
        } else {
            spineHero.setScale(0.8)
        }

        if (outDir) {
            spineHero.x = outDir * 600
            cc.tween(spineHero)
                .to(0.5, { x: 0 }, { easing: 'cubicOut' })
                .start()
        }


        let btnLeft = cc.find("node_info/info/btn_left", this.node)
        let btnRight = cc.find("node_info/info/btn_right", this.node)
        btnLeft.active = bShowNext
        btnRight.active = bShowNext

        let btnGallery = cc.find('btn_gallery', this.node)
        let btnShare = cc.find('btn_share', this.node)
        btnGallery.active = bShowNext && bUnlock
        btnShare.active = bShowNext && bUnlock

        if (bShowNext) {
            let curIdx = this._getNextCardidx(0)
            btnLeft.active = (curIdx > 0)
            btnRight.active = (curIdx < this._allCampcardlist.length - 1)
        }
    },

