    //type:-1 left 1 right 0 当前的
    _getNextCardidx(type) {
        let curIdx

        for (let i = 0; i < this._allCampcardlist.length; i++) {
            let item = this._allCampcardlist[i]
            if (item.cardid == this._cardInfo.cardid) {
                curIdx = i
                break
            }
        }
        return curIdx + type
    },

    _updateCardInfo(cardInfo) {
        if (this._allCampcardlist && cardInfo) {
            for (let i = 0; i < this._allCampcardlist.length; i++) {
                let item = this._allCampcardlist[i]
                if (item.cardid == cardInfo.cardid) {
                    this._allCampcardlist[i] = cardInfo
                    break
                }
            }
        }

    },

    //跳转到游戏
    onGoSpin() {
        if (cc.vv.gameData) {
            this.node.destroy()
            return
        }

        if (this._cardInfo) {
            let gameId = this._cardInfo.cfg.gameid
            //统计
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_SPIN, this._fromWhere + '|' + this._cardInfo.cardid)

            //是否已经解锁
            let bLock = cc.vv.UserManager.isGameLock(gameId)
            if (bLock) {
                //是否
                let gamedata = cc.vv.UserManager.getGameListById(gameId)
                if (gamedata) {
                    // cc.vv.FloatTip.show('Sorry,the game open at LV'+gamedata.level);
                    cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_game_open, gamedata.level));
                }

            }
            else {

                //判断是否关闭了
                let bServerOpen = cc.vv.UserManager.isServerOpenGame(gameId)
                if (!bServerOpen) {
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_game_not_released);
                    // cc.vv.FloatTip.show('Sorry,the game has not been released yet, so stay tuned.');
                    return
                }

                let bInnerGame = cc.vv.UserManager.isNoNeedDownGame(gameId) //是否是内置游戏
                if (bInnerGame) {
                    //直接进入
                    Global.dispatchEvent("enter_game", gameId);
                    this.node.destroy()
                    return
                }
                //是否下载了
                let bDown = cc.vv.UserManager.isDownloadSubGame(gameId)
                if (bDown) {
                    //已经下载了
                    if (Global.isNative()) {
                        //是否是最新了
                        let bUpdated = cc.vv.SubGameUpdateNode.getComponent('subGameMgr')._isAreadyNew(gameId)
                        if (bUpdated) {
                            Global.dispatchEvent("enter_game", gameId);
                            this.node.destroy()
                        }
                        else {
                            //更新并跳转
                            // cc.vv.UserManager.setGoSpinGame(gameId)
                            cc.vv.SubGameUpdateNode.emit("check_subgame", gameId)
                            Global.dispatchEvent(EventId.GO_HALL_TAB, 2)
                            this.unDownloadTip(gameId)
                            this.node.destroy()

                        }
                    }
                    else {
                        //直接进入
                        Global.dispatchEvent("enter_game", gameId);
                        this.node.destroy()
                    }
                }
                else {
                    //还没下载，并跳转
                    // cc.vv.UserManager.setGoSpinGame(gameId)
                    cc.vv.SubGameUpdateNode.emit("check_subgame", gameId)
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 2)
                    this.unDownloadTip(gameId)
                    this.node.destroy()
                }
            }
        }
    },
