cc.Class({
    extends: cc.Component,

    properties: {
        bg: cc.Node,
        bonus_node: cc.Node,
        effect_template: sp.Skeleton,
        _symbols: [],
        _isEnter: false,
        _symbolTemplate: cc.Node,
        extraBonusIdxs: [],
    },

    onLoad() {
        this.bg.active = false;
        this.bonus_node.active = false;
        this._isEnter = false;
        this._symbolTemplate = SlotsFacade.dm.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplate.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
        this.extraBonusIdxs = [];
    },

    /**
     * 开始 extra bonus game
     * @returns {Promise<void>}
     */
    async startExtraBonus() {
        // 是否打开extra ball
        if (!SlotsFacade.dm.canExtraBall()) {
            return;
        }
        // 在普通游戏中才会触发这个游戏
        if (SlotsFacade.dm.hasFree()) {
            if (!SlotsFacade.dm.isFistTriggerFree()) {
                return;
            }
        } else {
            if (SlotsFacade.dm.isLastEndFree()) {
                return;
            }
        }
        let spinData = SlotsFacade.dm.getSpinData();
        // 保存上下两个slots的bonus 数据
        let slotsBonusDataArr = [[], []];
        for (let i = 0; i < spinData.bonusIdxs.length; i++) {
            let idx = spinData.bonusIdxs[i];
            if (idx > 15) {
                slotsBonusDataArr[1].push({ idx: idx, data: spinData.bonusItems[i] });
            } else {
                slotsBonusDataArr[0].push({ idx: idx, data: spinData.bonusItems[i] });
            }
        }
        // 取bonus 数量最多的一个
        let bonusData = slotsBonusDataArr[0];
        if (slotsBonusDataArr[1].length > slotsBonusDataArr[0].length) {
            bonusData = slotsBonusDataArr[1];
        }
        // 当bonus数量>=2个才触发
        if (bonusData.length < 2) {
            return;
        }
        // 触发概率
        if (Math.random() > bonusData.length / 10) {
            return;
        }
        this._isEnter = true;
        // 播放角色动画
        await SlotsFacade.character.playExtraBonusEff();
        this.bg.active = true;
        this.bonus_node.active = true;
        // 添加extra bonus symbol
        await this.addExtraBonus(bonusData);
    },

    /**
     * 添加bonus symbol
     * @returns {Promise<void>}
     */
    async addExtraBonus(bonusData) {
        for (let i = 0; i < bonusData.length; i++) {
            let item = bonusData[i];
            this.extraBonusIdxs.push(item.idx);
            // 添加前置动画
            let pos = SlotsFacade.slots.getIdxGlobalPos(item.idx);
            pos = this.bonus_node.convertToNodeSpaceAR(pos);
            let spine = cc.instantiate(this.effect_template.node).getComponent(sp.Skeleton);
            spine.node.parent = this.bonus_node;
            spine.node.zIndex = 100 + i;
            spine.node.active = true;
            spine.node.setPosition(pos);
            spine.setAnimation(0, "animation1", false);
            spine.setCompleteListener(() => {
                spine.setCompleteListener(null);
                spine.node.removeFromParent();
            });
            SlotsFacade.soundMgr.playEffect("symbol_bonus");
            // 添加symbol
            let data = {};
            if (item.data.coin) {
                data.coin = item.data.coin;
            } else {
                data.jp = item.data.jackpot.id;
            }
            cc.tween(this.node)
                .delay(0.6)
                .call(() => {
                    let symbol = this.genABonusSymbol(item.idx, data);
                    this._symbols.push(symbol);
                })
                .start();
            await SlotsFacade.delayTime(0.35);
        }
        this.bg.active = false;
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 生成一个bonus图标
     * @param {*} idx
     * @param {*} data
     */
    genABonusSymbol(idx, data) {
        let cfg = SlotsFacade.dm.getGameCfg();
        let node = cc.instantiate(this._symbolTemplate)
        node.parent = this.bonus_node;
        let scp = node.addComponent(cfg.scripts.Symbols)
        scp.SetSymbolReelIdx(0);
        scp.Init(0, this.node);
        scp.ShowById(cfg.bonusId, data);
        let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
        pos = this.bonus_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        scp.playBonusIdleAni();
        return scp;
    },

    /**
     * 退出extra bonus game
     * @returns {Promise<void>}
     */
    async exitExtraBonus() {
        if (!this._isEnter) {
            return;
        }
        this._isEnter = false;
        this.bg.active = false;
        this._symbols = [];
        this.extraBonusIdxs = [];
        this.bonus_node.removeAllChildren();
        this.bonus_node.active = false;
    }
})