/**
 * vip升级弹窗
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        vipAtlas: cc.SpriteAtlas,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('btn_close', this.node);
        Global.btnClickEvent(btnClose, this.onClickClose, this);
        let btnConfirm = cc.find('node_content/btn', this.node);
        Global.btnClickEvent(btnConfirm, this.onClickConfirm, this);

        Global.playComEff("ch_popup");
    },

    start() {
        this.init()
    },

    init(data) {
        let curLv = cc.vv.UserManager.getVipLevel();
        let vipInfo = Global.VIP_INFO[curLv];

        let spr = cc.find("node_content/spr", this.node);
        spr.getComponent(cc.Sprite).spriteFrame = this.vipAtlas.getSpriteFrame(`0${vipInfo.level}`);

        // let layout = cc.find("node_content/layout", this.node);
        // cc.find("spr1/lbl2", layout).getComponent(cc.Label).string = `+ ${vipInfo.scratch*100}%`;
        // cc.find("spr2/lbl2", layout).getComponent(cc.Label).string = `× ${vipInfo.store}`;
        // cc.find("spr3", layout).active = vipInfo.inboxcollect;



        cc.find("node_content/lv/spr_left", this.node).getComponent(cc.Sprite).spriteFrame = this.vipAtlas.getSpriteFrame(`vip_${vipInfo.level - 1}_tile`)
        cc.find("node_content/lv/spr_right", this.node).getComponent(cc.Sprite).spriteFrame = this.vipAtlas.getSpriteFrame(`vip_${vipInfo.level}_tile`)

        let x_arrow = cc.find("node_content/lv/guang2", this.node)
        Global.ArrowAction(x_arrow, cc.v2(-10, 0), 0.5)

        // let norScale = spr.scale;
        // spr.scale = 0;
        // cc.tween(spr)
        //     .to(0.5,{scale:norScale}, {easing:"backOut"})
        //     .start()
        //
        // layout.children.forEach((node,idx)=>{
        //     if(node.active){
        //         node.scale = 0
        //         cc.tween(node)
        //             .delay(idx*0.2+0.2)
        //             .to(0.5,{scale:1}, {easing:"backOut"})
        //             .start()
        //     }
        // })

    },

    onClickConfirm: function () {
        this.node.destroy()
    },

    onClickClose: function () {
        this.node.destroy()
    },

    // update (dt) {},
});
