/**
 * Luckycard-关卡号
 */
cc.Class({
    extends: cc.Component,

    properties: {
        spr_cur: cc.SpriteFrame,
        spr_pass: cc.SpriteFrame,
        _curIdx: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnCmp = this.node.getComponent(cc.Button)
        if (btnCmp) {
            this.node.on("click", this.onClickStage, this)
        }
    },

    start() {

    },

    init: function (curLv, idx) {
        this._curIdx = idx
        let bg = cc.find('bg', this.node)
        let lbl = cc.find("lbl_num", this.node)
        let showColor
        if (idx < curLv) {
            //已经通过
            bg.getComponent(cc.Sprite).spriteFrame = this.spr_pass
            Global.showSpriteGray(bg, true)
            showColor = cc.Color(125, 125, 125)
        }
        else if (idx == curLv) {
            //当前
            bg.getComponent(cc.Sprite).spriteFrame = this.spr_cur
            Global.showSpriteGray(bg, false)
            showColor = cc.Color(182, 255, 190)
        }
        else if (idx > curLv) {
            //未通过
            bg.getComponent(cc.Sprite).spriteFrame = this.spr_pass
            Global.showSpriteGray(bg, false)
            showColor = cc.Color(182, 255, 190)
        }
        lbl.color = showColor
    },

    onClickStage: function (event) {
        //出现保护提示
        let parNode = this.node.parent.parent
        if (parNode) {
            let nodeTip = cc.find('spr_tips', parNode)
            if (!nodeTip) {
                return
            }
            let pos = parNode.convertToNodeSpaceAR(this.node.convertToWorldSpaceAR(cc.v2(0, 0)))

            let xVal = 1
            if (this._curIdx == 1) {
                xVal = -1
            }
            cc.find('lbl_text', nodeTip).scaleX = xVal
            nodeTip.position = cc.v2(pos.x, pos.y + 40)
            nodeTip.stopAllActions()
            if (nodeTip.getNumberOfRunningActions() == 0) {

                nodeTip.scale = 0
                nodeTip.active = true
                cc.tween(nodeTip)
                    .to(0.3, { scaleX: xVal, scaleY: 1 }, { easing: 'backOut' })
                    .delay(5)
                    .to(0.2, { scale: 0 })
                    .start()
            }
        }

    }

    // update (dt) {},
});
