/**
 * 更新提示
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('bg/btn_confirm', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this);
    },

    start() {

    },

    showNotice(content, title) {
        let lbl = cc.find('bg/scrol/view/content/lbl_content', this.node)
        if (lbl) {
            lbl.getComponent(cc.Label).string = content
        }
        let lblTitle = cc.find('bg/lbl_title', this.node)
        lblTitle.getComponent(cc.Label).string = title || 'UPDATE ANNOUCEMENT'
    },

    onClickClose: function () {
        this.node.destroy()
    }

    // update (dt) {},
});
