const List = require('List');
const _desInfo = {
    "1": 'UNLOCK %s HEROES',
    "2": 'OF THE LIGHT CAMP',
    "3": 'OF THE NATURE CAMP',
    "4": 'OF THE WATER CAMP',
    "5": 'OF THE FIRE CAMP',
    "6": 'OF THE STORM CAMP',
    "7": 'COLLECT %s ONE-STAR HEROES'
};
cc.Class({

    extends: require('UI_popwin_interface'),

    properties: {
        listview: List,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.offX = 145
        this.collectFont = 30
        this.progressingFont = 24
        cc.vv.NetManager.registerMsg(MsgId.REQ_SET_CARD_REWARD, this.onRcvSetCardReward, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_SET_CARD_ACHIEVE, this.onRcvSetCardAchieve, this);
        this.sendSetCardAchieve()

        this.allCollectBtn = cc.find('allCollectBtn', this.node)
        Global.btnClickEvent(this.allCollectBtn, this.onClickAllBtn, this);
        let closeBtn = cc.find('closeBtn', this.node)
        Global.btnClickEvent(closeBtn, this.onClickCloseBtn, this);
        Global.playComEff("ch_popup");

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_REWARD_POP)
    },

    isBtnActive(data) {
        this.allCollectBtn.active = false
        for (let i = 0; i < data.length; i++) {
            if (data[i].status == 1) {
                this.allCollectBtn.active = true
                return
            }
        }
        Global.dispatchEvent(EventId.CLEAN_ACHIEVE_RED);
    },

    sendSetCardAchieve() {
        var req = { 'c': MsgId.REQ_SET_CARD_ACHIEVE };
        cc.vv.NetManager.send(req);
    },

    sendSetCardReward(id = 0, flag = false) {
        var req = { 'c': MsgId.REQ_SET_CARD_REWARD };
        if (id) {
            req.taskid = id
        }
        req.is_all = flag
        cc.vv.NetManager.send(req);
    },

    onRcvSetCardAchieve(msg) {
        if (msg.code === 200) {
            this._listData = msg.tasks
            this.showList()
            this.isBtnActive(msg.tasks)
        }
    },

    onRcvSetCardReward(msg) {
        if (msg.code === 200) {
            if (msg.rewards.length > 0) {
                //可以收集
                this.showPopRewards(msg.rewards)
                this.sendSetCardAchieve()
            }
        }
    },

    showPopRewards(rd) {
        let rdArr = []

        if (rd.length == 1) {
            rdArr.push(rd[0])
        } else {
            for (let i = 0; i < rd.length; i++) {
                if (rd[i].type == Global.PROP_ID.COIN) {
                    if (cc.vv.gameData) {
                        cc.vv.gameData.AddCoin(rd[i].count)
                        cc.vv.gameData.RefushMyCoin()
                    } else {
                        cc.vv.UserManager.AddCoin(rd[i].count, true)
                    }
                } else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD) {
                    rdArr.push(rd[i])
                } else {
                    Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: rd[i].type, num: rd[i].count })
                }
            }
        }

        if (rdArr.length > 0) {
            this.loadPrefab("pop_reward", this.node, (uiNode) => {
                uiNode.active = true
                let endCall = function () {
                    uiNode.destroy()
                }
                uiNode.getComponent('CH_popreward').showRewards(rdArr, endCall)
            })
        }
    },

    showList() {
        this.listview.numItems = this._listData.length > 0 ? this._listData.length : 0;
        this.listview.active = (this._listData.length > 0);
    },

    //list
    OnListVRender(item, idx) {
        let itemData = this._listData[idx];
        this.initItem(item, itemData)
    },

    initItem(item, itemData) {
        //初始化icon节点
        let icon = cc.find('icon', item)
        if (icon.children.length > 1) {
            //全部隐藏
            this.fadeChild(icon.children)
        }

        //设置金币
        let lvLabel = cc.find('levelLabel', item)
        // let showTitle = cc.js.formatStr(_desInfo[itemData.type+""],itemData.cnt)
        //
        // lvLabel.getComponent(cc.Label).string = showTitle
        I18N.setI18nLabel(lvLabel, cc.vv.Language['herocard_achievement_des' + itemData.type], itemData.cnt)
        // if (itemData.type > 1) {
        //     lvLabel.getComponent(cc.Label).string = 'UNLOCK '+itemData.cnt+' HEROES'+' '+_desInfo[itemData.type-2]
        // }else {
        //     lvLabel.getComponent(cc.Label).string = 'UNLOCK '+itemData.cnt+' HEROES'
        // }

        //设置金币以外的奖励
        let otherRd = this.delCoinData(itemData.rewards, item)
        let iconPrefab = cc.find('icon/item', item)
        for (let i = 0; i < otherRd.length; i++) {
            if (i < 1) {
                this.setSprite(iconPrefab, otherRd[i].type, otherRd[i].count, i)
            } else {
                if (icon.children[i]) {
                    icon.children[i].active = true
                    this.setSprite(icon.children[i], otherRd[i].type, otherRd[i].count, i)
                } else {
                    let itemNode = cc.instantiate(iconPrefab);
                    itemNode.parent = iconPrefab.parent;
                    this.setSprite(itemNode, otherRd[i].type, otherRd[i].count, i)
                }
            }
        }

        //设置按钮
        let status = itemData.status

        let getBtn = cc.find('isGet/getBtn', item)
        let yes = cc.find('isGet/yes', item)

        let flag = (status == 2) ? true : false
        getBtn.active = !flag
        yes.active = flag

        // console.log('itemData.id:', itemData.id)

        if (!flag) {
            let label = cc.find('label', getBtn)
            label.active = true
            label.getComponent(cc.Label).string = status ? cc.vv.Language.btn_collect : cc.vv.Language.herocard_progressing
            label.getComponent(cc.Label).fontSize = status ? this.collectFont : this.progressingFont
            let proLabel = cc.find('proLabel', getBtn)
            proLabel.active = true
            proLabel.getComponent(cc.Label).string = itemData.currCnt + '/' + itemData.cnt

            //绑定鼠标点击事件
            let clickBtn = cc.find("isGet/getBtn", item)
            clickBtn.off("click");
            Global.btnClickEvent(clickBtn, () => {
                if (!status) {
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_REWARD_PROGRESSING)
                    //未收集满
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 2)
                    this.onClickCloseBtn()
                } else {
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_REWARD_COLLECT, itemData.id)
                    //发送集卡成就协议
                    this.sendSetCardReward(itemData.id)
                    getBtn.active = flag
                    yes.active = !flag
                }
            }, this)
        }
    },


    loadPrefab: function (prefabName, fatherNode, callbacks) {
        let url = 'CashHero/prefab/' + prefabName;
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                if (fatherNode) {
                    parObj = fatherNode
                }
                if (cc.isValid(parObj)) {
                    if (!cc.find(prefabName, parObj)) {
                        let ui = cc.instantiate(prefab);
                        ui.parent = parObj
                        ui.active = true;
                        callbacks(ui);
                    }
                }
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    fadeChild(item) {
        for (let i = 1; i < item.length; i++) {
            item[i].active = false
        }
    },

    setSprite(itemNode, id, count, posX) {
        itemNode.x = posX * this.offX
        cc.find('label', itemNode).getComponent(cc.Label).string = this.getNum(count, id)
        let url = 'common/rewarditem/' + id
        cc.loader.loadRes(url, cc.SpriteFrame, (err, data) => {
            if (!err) {
                itemNode.getComponent(cc.Sprite).spriteFrame = data
            }
        })
    },

    getNum(count, id) {
        let num = 0
        if (id == 1) {
            num = Global.convertNumToShort(count, 1000, 2)
        } else if (id == 3) {
            num = (count / 3600).toFixed(0) + "H"
        } else {
            num = count
        }
        return num
    },

    delCoinData(data, item) {
        let otherRd = []
        for (let i = 0; i < data.length; i++) {
            if (data[i].type == 1) {
                cc.find('coin/label', item).getComponent(cc.Label).string = Global.FormatNumToComma(data[i].count)
                continue
            }
            otherRd.push(data[i])
        }
        return otherRd
    },

    onClickAllBtn() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_REWARD_COLLECTALL)
        this.sendSetCardReward(0, true)
    },

    onClickCloseBtn() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_REWARD_CLOSE)

        this.node.destroy()
        Global.playComEff("ch_close")
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SET_CARD_REWARD, this.onRcvSetCardReward, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SET_CARD_ACHIEVE, this.onRcvSetCardAchieve, this);
    },

    start() {

    },

    // update (dt) {},
});
