
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._btn_entrance = cc.find("btn_entrance", this.node);
        let _wenhao = cc.find("btn_entrance/wenhao", this.node);
        let spr_tip = cc.find("btn_entrance/spr_tip", this.node);
        spr_tip.active = false;
        this._node_bonusType = cc.find("BetUp", this.node);
        Global.btnClickEvent(this._btn_entrance, this.onClickBoxBtn, this);
        Global.btnClickEvent(_wenhao, this.onClickBoxWenhaoBtn, this);
        Global.btnClickEvent(this._node_bonusType, this.onclickBonusType, this);

        this._super();

        this.initLockState();
        this.setFlagCnt(cc.vv.gameData.getFlagStore().flagCnt);
    },

    RegisterEvent:function(){
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变
    },

    //断线重连的显示
    async ReconnectShow(){
        this._topScript.SetBackLobby(false);
        this._bottomScript.ShowBtnsByState("moveing_1")

        this.ShowGameview(false);
        if(cc.vv.gameData.getPageReward()){// super免费
            cc.vv.gameData.setIsSuperFree(true);

            cc.vv.gameData.GetBottomScript().ShowFreeModel(true,cc.vv.gameData.GetFreeTime(),cc.vv.gameData.GetTotalFree());
            // 初始化
            cc.vv.gameData.getSuperFreeMgr().initShowSlotsDate();

            // this.ShowGameview(true);
        }
        else if (cc.vv.gameData.GetTotalFree() > 0){// 免费界面
            this.ShowGameview(true);
            // if(cc.vv.gameData.getState() == 1){
            //     this.setFlagState(false);
            // }
        }

        // bonus游戏
        let bonusdata = cc.vv.gameData.getBonusGame();
        if(bonusdata) {
            await cc.vv.gameData.getBonusGameMgr().showBonusGame(bonusdata);
        }

        // 结束免费
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.endFreeGame();
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    //重写
    StartMove:function(){
        if(cc.vv.gameData.isSuperFree()) {
            cc.vv.gameData.getSuperFreeMgr().StartMove();
            return
        }

        if(cc.vv.gameData.isBonusGame()){
            return
        }

        this._super()
        Global.SlotsSoundMgr.playNormalBgm();
    },

    StopMove:function(){
        if(cc.vv.gameData.isSuperFree()) {
            cc.vv.gameData.getSuperFreeMgr().StopMove();
            return
        }

        if(cc.vv.gameData.isBonusGame()){
            cc.vv.gameData.getBonusGameMgr().StopMove();
            return
        }

        this._super()
    },

    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col
        let reelResults = []

        let flagInfo = this._gameInfo.flagInfo;
        let flagIdxs;
        if(flagInfo && flagInfo.idxs){
            flagIdxs = flagInfo.idxs;
        }

        let bonusIdxs = this._gameInfo.bonusIdxs;
        let bonusItems = this._gameInfo.bonusItems;

        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {}
                res.sid = cards[i] //符号id
                res.data = {}

                if(flagIdxs && flagIdxs.includes(i+1)){
                    res.data.flag = 1;
                }

                if(bonusIdxs && bonusIdxs.includes(i+1)){
                    res.data.bonus = bonusItems[bonusIdxs.indexOf(i+1)];
                }

                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }

        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine:function(msg){
        if(cc.vv.gameData.isSuperFree()) {
            cc.vv.gameData.getSuperFreeMgr().onMsgSpine(msg);
            return
        }

        this._super(msg);

        // 随机游戏
        let isTriFree = this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0;
        let isTriBonus = this._gameInfo.bonusGame;
        let isBigWin = this._gameInfo.winCoin/cc.vv.gameData.GetTotalBet() >= 40;
        if (Math.random() < 0.25 && (isTriFree || isTriBonus || isBigWin)) {
            this.SetStopTime(3);

            this.triggerRandomGame();
        }
    },

    OnSpinEnd(){
        this.onSpinEndAction();
    },

    async onSpinEndAction() {
        let flagInfo = this._gameInfo.flagInfo;
        if(flagInfo && flagInfo.totalCnt > 0){
            this.flyFlag( this._gameInfo.flagStore.flagCnt);
        }

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.getFreeWinCoin()
        }
        await new Promise((success, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,success)
        });

        // 触发bonus
        if(this._gameInfo.bonusGame){
            await this.triBonusGame();
        }

        // 触发免费
        let freeInfo = this._gameInfo.freeResult.freeInfo;
        if(freeInfo && freeInfo.freeCnt > 0){
            await this.triFreeGame();
        }

        // 结束免费
        if(this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0){
            await this.endFreeGame();
        }

        this.CanDoNextRound();
    },

    triBonusGame(){
        return new Promise(async (success, failed)=> {
            let bonusIdxs = this._gameInfo.bonusIdxs;
            for (let idx of bonusIdxs) {
                let symbol = this.GetSymbolByIdx(idx);
                if(symbol){
                    symbol.playTriggerAnimation()
                }
            }
            Global.SlotsSoundMgr.playEffect("triggering");

            await cc.vv.gameData.awaitTime(1.5);
            await cc.vv.gameData.getPopupScript().showBonusStartUI(this._gameInfo.bonusGame.type);
            // await cc.vv.gameData.awaitTime(0.5);
            await cc.vv.gameData.getBonusGameMgr().showBonusGame(this._gameInfo.bonusGame, true);

            success();
        });
    },

    triFreeGame(){
        return new Promise(async (success, failed)=> {
            let isFirst = this._gameInfo.freeCnt === this._gameInfo.allFreeCnt;
            let freeInfo = this._gameInfo.freeResult.freeInfo
            if(isFirst){
                let idxs = freeInfo.scatterIdx;
                for (let i = 0; i < idxs.length; i++){
                    let symbol = this.GetSymbolByIdx(idxs[i]);
                    if(symbol){
                        symbol.playTriggerAnimation();
                    }
                }
                Global.SlotsSoundMgr.playEffect("triggering");
                await cc.vv.gameData.awaitTime(1.5);

                await cc.vv.gameData.getPopupScript().showFreeGameStartUI(freeInfo.freeCnt, isFirst);
                cc.vv.gameData.getPopupScript().playFreeQPAnim();

                await cc.vv.gameData.awaitTime(2);
                this.Backup();
                this.ShowGameview(true);

                await cc.vv.gameData.awaitTime(1);
            } else {
                await cc.vv.gameData.getPopupScript().showFreeGameStartUI(freeInfo.freeCnt, isFirst);
            }

            success();
        });
    },

    endFreeGame(){
        return new Promise(async (success, failed)=> {
            let nWin = cc.vv.gameData.getFreeWinCoin();

            Global.SlotsSoundMgr.playEffect("fgend");
            await cc.vv.gameData.getPopupScript().showGameWinUI(nWin);

            cc.vv.gameData.getPopupScript().playFreeQPAnim();
            await cc.vv.gameData.awaitTime(2);
            this.Resume();
            this.ShowGameview(false);
            Global.SlotsSoundMgr.stopBgm();

            await cc.vv.gameData.awaitTime(1);

            await new Promise((sucess, failed)=>{
                this.ShowBottomWin(nWin,nWin,true,sucess)
            });

            if(cc.vv.gameData.isBoxGame()){
                cc.vv.gameData.getBoxScript().openStorePage();
                cc.vv.gameData.setIsBoxGame(false)
            } else {
                success();
            }
        });
    },

    setFlagState(bShow){
        this._btn_entrance.active = bShow;
    },

    setFlagCnt(cnt){
        cc.find("lbl", this._btn_entrance).getComponent(cc.Label).string = Global.FormatNumToComma(cnt);
    },

    initLockState(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        cc.find("bg", this._node_bonusType).getComponent("ImgSwitchCmp").setIndex(curBet >= needBet ? 1 : 0);
        let spr_bonus = cc.find("betup_EN", this._node_bonusType);
        let spine_bonus = cc.find("BetUp", this._node_bonusType);

        let spr_qz = cc.find("loading_box", this._btn_entrance);
        let spine_qz = cc.find("QiZi", this._btn_entrance);
        let spine_suo = cc.find("Puzzle_collect_logo", this._btn_entrance);

        if(curBet >= needBet){
            this._isLock = false;

            spr_bonus.active = true;
            spine_bonus.active = false;

            spr_qz.active = false;
            spine_qz.active = true;
            spine_qz.getComponent(sp.Skeleton).setAnimation(0, "QiZi_loop", true);
            spine_suo.active = false;
        } else {
            this._isLock = true;

            spr_bonus.active = false;
            spine_bonus.active = true;
            spine_bonus.getComponent(sp.Skeleton).setAnimation(0,"BetUp_Loop_EN",false);

            spr_qz.active = true;
            spine_qz.active = false;
            spine_suo.active = true;
            spine_suo.getComponent(sp.Skeleton).setAnimation(0, "lock_idle_EN", true);
        }
    },

    // 点商店问号
    onClickBoxWenhaoBtn(){
        let spr_tip = cc.find("btn_entrance/spr_tip", this.node);
        spr_tip.stopAllActions();
        if(spr_tip.active){
            spr_tip.runAction(cc.sequence(
                cc.scaleTo(spr_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ spr_tip.active = false;})
            ))
        } else {
            Global.SlotsSoundMgr.playEffect("tips");
            spr_tip.active = true;
            spr_tip.setScale(0);
            spr_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ spr_tip.active = false;})
            ))
        }
    },

    // 点击商店入口
    onClickBoxBtn(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.isBonusGame()) return;

        if(this._isLock){
            let allMults = cc.vv.gameData.GetBetMults();
            let needBet = cc.vv.gameData.getNeedBet();
            if(needBet > allMults.length){
            }else {
                cc.vv.gameData.GetBottomScript().SetBetIdx(needBet)
            }
        } else {
            cc.vv.gameData.getBoxScript().openStorePage();
        }
    },

    // 点击bonus类型图片
    onclickBonusType(){
        if (!cc.vv.gameData.GetBottomScript().GetSpinBtnState()) return;
        if (cc.vv.gameData.GetAutoModelTime() > 0) return;
        if (cc.vv.gameData.isFreeGame()) return;
        if (cc.vv.gameData.isBonusGame()) return;

        if(this._isLock) {
            let needBet = cc.vv.gameData.getNeedBet();
            let allMults = cc.vv.gameData.GetBetMults();
            if (needBet > allMults.length) {
            } else {
                cc.vv.gameData.GetBottomScript().SetBetIdx(needBet)
            }
        }
    },

    // 押注额改变
    onEventTotalbetUpdated(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let needBet = cc.vv.gameData.getNeedBet();

        let bg_bonus = cc.find("bg", this._node_bonusType);
        let spr_bonus = cc.find("betup_EN", this._node_bonusType);
        let spine_bonus = cc.find("BetUp", this._node_bonusType);

        let spr_qz = cc.find("loading_box", this._btn_entrance);
        let spine_qz = cc.find("QiZi", this._btn_entrance);
        let spine_suo = cc.find("Puzzle_collect_logo", this._btn_entrance);

        if(curBet >= needBet && this._isLock){  // 解锁
            Global.SlotsSoundMgr.playEffect("unlock");

            this._isLock = false;
            bg_bonus.getComponent("ImgSwitchCmp").setIndex(1);

            spr_bonus.active = true;
            let entry1 = spine_bonus.getComponent(sp.Skeleton).setAnimation(0, "BetUp_Intro", false);
            spine_bonus.getComponent(sp.Skeleton).setTrackCompleteListener(entry1, ()=>{
                spine_bonus.getComponent(sp.Skeleton).setTrackCompleteListener(entry1, null);
                spine_bonus.active = false;
            });

            spr_qz.active = false;
            spine_qz.active = true;
            spine_qz.getComponent(sp.Skeleton).setAnimation(0, "QiZi_loop", true);
            let entry2 = spine_suo.getComponent(sp.Skeleton).setAnimation(0, "unlock_EN", false);
            spine_suo.getComponent(sp.Skeleton).setTrackCompleteListener(entry2, ()=>{
                spine_suo.getComponent(sp.Skeleton).setTrackCompleteListener(entry2, null);
                spine_suo.active = false;
            });
        } else if(curBet < needBet && !this._isLock){   // 上锁
            Global.SlotsSoundMgr.playEffect("lock");

            this._isLock = true;
            bg_bonus.getComponent("ImgSwitchCmp").setIndex(0);
            spr_bonus.active = false;
            spine_bonus.active = true;
            spine_bonus.getComponent(sp.Skeleton).setAnimation(0,"BetUp_Loop_EN",false);

            spr_qz.active = true;
            spine_qz.active = false;
            spine_suo.active = true;
            spine_suo.getComponent(sp.Skeleton).setAnimation(0, "lock_EN", false);
            spine_suo.getComponent(sp.Skeleton).addAnimation(0, "lock_idle_EN", true);
        }
    },


    async flyFlag(flagCnt){
        return new Promise(async(success, failed)=> {
            let idxs = this._gameInfo.flagInfo.idxs;
            let shoujifly = this.node.getChildByName("shoujifly");
            let qizi = this._btn_entrance.getChildByName("QiZi");
            Global.SlotsSoundMgr.playEffect("collect");
            idxs.forEach(idx => {
                let symbol = this.GetSymbolByIdx(idx);
                symbol.setFlag(false);

                let flyNode = cc.instantiate(shoujifly);
                flyNode.active = true;
                flyNode.position = this.node.convertToNodeSpaceAR(symbol.getPawWPos());
                flyNode.parent = this.node;

                let par = cc.find("LiZiFei", flyNode);
                par.getComponent(cc.ParticleSystem).resetSystem();
                let flag = cc.find("flag", flyNode);
                let endPos = flyNode.convertToNodeSpaceAR(qizi.convertToWorldSpaceAR(cc.v2(0, 0)));
                cc.tween(par).delay(0.5).to(0.5, {position: endPos}).start();
                cc.tween(flag)
                    .to(0.3, {scale: 0.8})
                    .to(0.2, {scale: 0.5})
                    .to(0.5, {position: endPos})
                    .call(() => {
                        flyNode.destroy();
                    })
                    .start();
            })

            await cc.vv.gameData.awaitTime(1);
            Global.SlotsSoundMgr.playEffect("collectdown");
            cc.tween(qizi).to(0.3, {scale: 1.2}).to(0.2, {scale: 1}).start();
            this.setFlagCnt(flagCnt);

            success()
        });
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        cc.vv.gameData.setIsFreeGame(bFree)
        if(bFree){
            Global.SlotsSoundMgr.playBgm("fgbgm");
        }

        this._super(bFree);
        this.setFlagState(!bFree);
    },

    async triggerRandomGame(){
        Global.SlotsSoundMgr.playEffect("BigAward");

        let character = cc.find("Canvas/safe_node/character");
        // character.getComponent(sp.Skeleton).setAnimation(0,"Hua_Intro",false);
        // character.getComponent(sp.Skeleton).setAnimation(0,"Hua_End",false);
        // character.getComponent(sp.Skeleton).addAnimation(0,"Hua_Loop",true);

        let dj = cc.find("Canvas/safe_node/slots/DaJiangYuGao");
        dj.active = true;
        dj.getComponent(sp.Skeleton).setAnimation(0, "DaJiangYuGao", false);
    },


    // update (dt) {},
});
