    setBar(cur, all) {
        let barNode = cc.find('barNode', this.node)
        if (barNode) {
            cc.find('mask', barNode).width = (cur / all) * bonusBarLen
        }
    },

    initAllBtn() {
        cc.find('getten', this.node).active = false
        // cc.find('unlock', this.node).active = false
        cc.find('collectBtn', this.node).active = false
        // cc.find("diamondBtn",this.node).active = false
    },

