    _closeMission() {
        // cc.find('goBtn', this.node).getComponent(cc.Button).interactable = false
        Global.dispatchEvent(EventId.MISSION_CLOSE);          //关闭界面
        StatisticsMgr.reqReport(StatisticsMgr.REQ_DAILYMISSION_GOSPIN)
    },

    _openScratch() {
        this._closeMission()
        let callbacks = function (prefab) {
            let canvas = cc.find("Canvas");
            let old = cc.find('online_rewards', canvas)
            if (!old) {
                let node = cc.instantiate(prefab);
                node.parent = canvas;
            }
        }
        this._loadPrefab('common/prefab/online_rewards', callbacks)
        // Global.dispatchEvent(EventId.SHOW_BONUS_TAB, 1)
    },

    _openLuckyFlipcard() {
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_CARD)
        if (!bOpen) {
            // cc.vv.FloatTip.show('Unlock at level '+Global.SYS_OPEN.LUCKY_CARD);
            cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.LUCKY_CARD));
            return
        }
        this._closeMission()
        let callbacks = function (prefab) {
            let canvas = cc.find("Canvas");
            let old = cc.find('CH_Luckycard', canvas)
            if (!old) {
                let node = cc.instantiate(prefab);
                node.parent = canvas;
            }
        }
        this._loadPrefab('CashHero/prefab/luck_card/CH_Luckycard', callbacks)
        // Global.dispatchEvent(EventId.SHOW_BONUS_TAB, 2)
    },

    _openShareFB() {
        this._closeMission()
        // Global.dispatchEvent(EventId.SHOW_BONUS_TAB, 2)
        let callbacks = function (prefab) {
            let canvas = cc.find("Canvas");
            let old = cc.find('fbShareWheel', canvas)
            if (!old) {
                let node = cc.instantiate(prefab);
                node.parent = canvas;
            }
        }
        this._loadPrefab('CashHero/prefab/fbShare/fbShareWheel', callbacks)
    },

    _openPalace() {
        this._closeMission()
        let callbacks = function (prefab) {
            let canvas = cc.find("Canvas");
            let old = cc.find('hero_palace', canvas)
            if (!old) {
                let node = cc.instantiate(prefab);
                node.parent = canvas;
            }
        }
        this._loadPrefab('CashHero/prefab/heropalace/hero_palace', callbacks)
        Global.dispatchEvent(EventId.GO_HALL_TAB, 2);    //到Slots列表页面
    },

    _openUnlockHero() {
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_CARD)
        if (!bOpen) {
            cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.LUCKY_CARD));
            // cc.vv.FloatTip.show('Unlock at level '+Global.SYS_OPEN.LUCKY_CARD);
            return
        }
        this._closeMission()
        Global.dispatchEvent(EventId.GO_HALL_TAB, 1);    //到卡牌列表页面
    },

    _loadPrefab: function (url, callbacks) {
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                callbacks(prefab)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    //刷新任务列表
    refreshMissionList(flag) {
        Global.dispatchEvent(EventId.MISSION_REWARDS, { _reqId: this._data.id, _flag: flag })
    },

    tipWindows() {
        let curDiamond = cc.vv.UserManager.getDiamond()
        let needDiamond = this._data.diamond

        let msg = ''
        let sureCall = null
        let cancelCall = null
        let self = this
        if (curDiamond < needDiamond) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石不足窗口弹出')
            //不足
            msg = "Diamonds are not enough! Go get the diamond?"
            sureCall = function () {
                cc.vv.UserManager.setEnterHallAction('Shop_Diamond')
                if (cc.vv.gameData) {
                    cc.vv.PopUIMgr.popShop()
                } else {
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
                }
                Global.dispatchEvent(EventId.MISSION_CLOSE);
                StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石不足窗口弹出 点击yes')
            }
            cancelCall = function () {
                // if (!self._fromBonus) {
                //     self.diaBtn.getComponent(cc.Button).interactable = true
                // }
                StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石不足窗口弹出 点击no')
            }

            cc.vv.AlertView.showSimple(msg, sureCall, cancelCall)
        } else {
            //直接使用
            // StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP,'钻石足够窗口弹出')
            // msg = cc.js.formatStr("Sure you use %s diamonds to com- plete this task?",needDiamond)
            sureCall = function () {
                // self.initBtn(true)
                self.setBar(self._data.need, self._data.need)
                self.sendDiamondReq()
                // self.setRed()
                StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP, '钻石足够窗口弹出 点击yes')
            }
            // cancelCall = function(){
            //     StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA_TIP,'钻石足够窗口弹出 点击no')
            //     if (!self._fromBonus) {
            //         self.diaBtn.getComponent(cc.Button).interactable = true
            //     }
            // }

            sureCall()
        }

    },

    // 钻石
    onClickDiaBtn() {
        // if (!self._fromBonus) {
        //     this.diaBtn.getComponent(cc.Button).interactable = false
        // }
        this.tipWindows()
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_DIA, this._count)
    },

    //收集奖励
    onClickCollectBtn() {
        cc.find('collectBtn', this.node).getComponent(cc.Button).interactable = false
        this.refreshMissionList(0)

        //是否是在引导内
        let _curGuide = cc.vv.NewGuide.GetCurGuideId()
        let _isGuide = _curGuide == 11 ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_MISSION_COLLECT, _isGuide)
    },

    sendDiamondReq() {
        let req = { c: MsgId.REQ_USE_MISSION_DIAMOND };
        req.questid = this._data.id
        cc.vv.NetManager.send(req);
    },

    sendRefushReq() {
        Global.dispatchEvent(EventId.MISSION_REFUSH)
    },

    onRcvNetUseDiamond(msg) {
        if (msg.questid != this._data.id) {
            return
        }

        if (msg.code === 200) {
            if (cc.isValid(msg.diamond)) {
                cc.vv.UserManager.setDiamond(msg.diamond, true)
                this.sendRefushReq()
            }
        }
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_USE_MISSION_DIAMOND, this.onRcvNetUseDiamond, false, this)//钻石
    },
