cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _inter: 0,
        _time: 8,
    },

    // LIFE-CYCLE CALLBACKS:
    onLoad() {
        Global.btnClickEvent(cc.find('closeBtn', this.node), this.onClickClose, this)
        Global.btnClickEvent(cc.find('goBtn', this.node), this.onClickGo, this)
        this._autoModel = false
    },

    start() {
        this._time = 8
        this._inter = 0
        if (cc.vv.gameData) {
            this._autoModel = cc.vv.gameData.GetAutoModelTime()
            cc.vv.gameData.PauseSlot()
        }
    },

    onClickGo() {

        Global.saveLocal("goodgrade", 1)

        if (Global.IsHuawei()) {

        }
        else {
            //点击了则停止自动
            this._autoModel = false
            let type = 2
            if (type == 1) {
                //url形式,会跳出app
                cc.vv.PlatformApiMgr.openRating()
            }
            else {
                cc.vv.PlatformApiMgr.loadReview()
            }



        }

        this.onClickClose()
    },

    onClickClose() {
        //点击了则停止自动
        this._autoModel = false
        this.node.destroy()
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },

    update(dt) {
        if (this._time && this._autoModel) {
            this._inter += dt
            if (this._inter >= 1) {
                this._inter = 0
                this._time--
                if (this._time < 1) {
                    this.onClickClose()
                }
            }
        }
    },
});
