/**
 * Logo 动画
 */
cc.Class({
    extends: cc.Component,

    properties: {
        showAnimation2: false,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {
        let ani = this.node.getComponent(sp.Skeleton)
        if (this.showAnimation2) {
            ani.setAnimation(0, "animation2", false)
            ani.addAnimation(0, "animation1", true)
        }
        else {
            ani.setAnimation(0, "animation1", true)
        }
    },

    // update (dt) {},
});
