
cc.Class({
    extends: cc.Component,

    properties: {
        _running: false
    },

    //数组，原点，开始弧度，结束弧度，半径，段数
    getPoints(center, startRadian, endRadian, r, segments) {
        let pos = []
        for (let i = 0; i <= segments; i++) {
            let theta = startRadian + i / segments * (endRadian - startRadian)
            pos.push(center.add(cc.v2(r * Math.cos(theta), r * Math.sin(theta))));
        }
        return pos
    },

    fly(from, to) {
        this.node.position = from
        this._lastPosition = from
        this._running = true
        let radius = 250    //飞行半径
        let p1 = from
        let p2 = cc.v2(p1.x + radius, p1.y)
        let speed = 300
        let t1 = Math.PI * (radius / 2) / speed
        let t2 = 0.5 * Math.PI * radius / speed * 0.9
        let t3 = 0
        let actions = []
        if (to.y < from.y) {    //目标点在下方
            //1
            let pos = this.getPoints(cc.v2((p1.x + p2.x) / 2, (p1.y + p2.y) / 2), Math.PI, Math.PI * 2, radius / 2, 12)
            actions.push(cc.cardinalSplineTo(t1, pos, 0))
            //2
            pos = this.getPoints(p1, 0, Math.PI / 2, radius, 8)
            actions.push(cc.cardinalSplineTo(t2, pos, 0))
            //3
            let p3 = cc.v2(p1.x, p1.y + radius)
            t3 = to.sub(p3).len() / speed * 0.8
            actions.push(cc.moveTo(t3, to))
        } else {                //目标点在上方
            //1
            let pos = this.getPoints(cc.v2((p1.x + p2.x) / 2, (p1.y + p2.y) / 2), Math.PI, 0, radius / 2, 12)
            actions.push(cc.cardinalSplineTo(t1, pos, 0))
            //2
            pos = this.getPoints(p1, 0, -Math.PI / 2, radius, 8)
            actions.push(cc.cardinalSplineTo(t2, pos, 0))
            //3
            let p3 = cc.v2(p1.x, p1.y - radius)
            t3 = to.sub(p3).len() / speed * 0.8
            actions.push(cc.moveTo(t3, to))
        }
        actions.push(cc.callFunc(() => {
            this._running = false
        }))
        this.node.runAction(cc.sequence(actions))
        return t1 + t2 + t3 + 0.2
    },

    calcDegree(from, to) {
        let degree = 0
        if (to.x - from.x == 0) {
            // 垂直
            if (to.y - from.y > 0) {
                degree = -90
            } else {
                degree = 90
            }
        } else {
            degree = -Math.atan((to.y - from.y) / (to.x - from.x)) * cc.macro.DEG
            if (to.x - from.x < 0) {// 从右边出来
                degree += 180
            }
        }
        return degree
    },

    updateDegree() {
        let currentPos = this.node.position
        if (currentPos.sub(this._lastPosition).lengthSqr() < 2) {
            return
        }
        //计算角度
        let degree = this.calcDegree(this._lastPosition, currentPos);
        this.node.angle = -degree
        this._lastPosition = currentPos
    },

    update(dt) {
        if (this._running) {
            this.updateDegree()
        }
    },
});
