let heroIdList = [
    '1004',//火
    '1002',//木
    '1003',//水
    '1001',//金
    '1005',//土
]

let heroKolId = [
    '1021',
    '1016',
    '1003',
    '1001',
    '1029'
]

cc.Class({
    extends: cc.Component,

    properties: {
        atlas: cc.SpriteAtlas,
    },

    onLoad() {
        //默认火属性
        for (let index = 1; index < 6; index++) {
            this.initHero(index)

        }

        let changeBtn = cc.find('buttom/changeBtn', this.node)
        let btn1 = cc.find('btn1', changeBtn)

        // let shareCloseBtn = cc.find('sharePage/shareCloseBtn', this.node)
        // Global.btnClickEvent(shareCloseBtn, () => {
        //     this.btnFade(true)
        // }, this);

        Global.btnClickEvent(btn1, () => {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_FIR)
            this.changeHeroPage(1)
        }, this);
        let btn2 = cc.find('btn2', changeBtn)
        Global.btnClickEvent(btn2, () => {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_WOOD)
            this.changeHeroPage(2)
        }, this);
        let btn3 = cc.find('btn3', changeBtn)
        Global.btnClickEvent(btn3, () => {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_WATER)
            this.changeHeroPage(3)
        }, this);
        let btn4 = cc.find('btn4', changeBtn)
        Global.btnClickEvent(btn4, () => {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_GOLD)
            this.changeHeroPage(4)
        }, this);
        let btn5 = cc.find('btn5', changeBtn)
        Global.btnClickEvent(btn5, () => {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_SOIL)
            this.changeHeroPage(5)
        }, this);

        let closeBtn = cc.find('buttom/closeBtn', this.node)
        Global.btnClickEvent(closeBtn, this.onClickCloseBtn, this);
        let shareBtn = cc.find('shareBtn', this.node)
        shareBtn.active = true
        Global.btnClickEvent(shareBtn, this.onClickShareBtn, this);
        let existBtn = cc.find('btn_exist', this.node)
        Global.btnClickEvent(existBtn, this.onClickExist, this);

        this.heroAllNode = cc.find('hero', this.node)
        this.changeHeroPage(1)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_POP)

        // this.btnFade(true)
    },

    start() {

    },

    sortData(data, num) {
        for (let index = 0; index < data.length; index++) {
            if (data[index].cardid == parseInt(heroKolId[num - 1])) {
                let curdata = data[index]
                data[index] = data[data.length - 1]
                data[data.length - 1] = curdata
                return data
            }
        }
    },

    initHero(num) {
        let heroData = cc.vv.HerocardManager.getCardListByCamp(heroIdList[num - 1])
        let curHeroData = this.sortData(heroData, num)

        let heroNode = cc.find(cc.js.formatStr("hero/hero%s/heroHead", num), this.node)
        for (let i = 0; i < heroNode.children.length; i++) {
            if (i < curHeroData.length) {
                let item = cc.find('mask/itemPng', heroNode.children[i])
                cc.vv.HerocardManager.loadHeroCircleHead(item, curHeroData[i].cardid)
                if (curHeroData[i].cardid != heroKolId[num - 1] && i < heroNode.children.length - 1) {
                    item.setScale(0.7)
                } else {
                    item.setScale(1)
                }

                if (curHeroData[i].lv > 0) {
                    cc.find('notOpen', heroNode.children[i]).active = false
                }
            }
        }
    },

    btnFade(flag) {
        cc.find('shareBtn', this.node).active = flag
        cc.find('buttom', this.node).active = flag
        cc.find('hero/sharePage', this.node).active = !flag
    },

    onClickShareBtn() {
        //显示关闭按钮
        let btnexist = cc.find('btn_exist', this.node)
        btnexist.active = true
        this.btnFade(false)
        let shareButtom = cc.find('hero/sharePage/buttom', this.node)
        cc.find('lv', shareButtom).getComponent(cc.Label).string = 'Lv.' + cc.vv.UserManager.getCurLv()
        cc.find('name', shareButtom).getComponent(cc.Label).string = cc.vv.UserManager.getNickName()
        let uid = cc.vv.UserManager.uid
        let headIcon = cc.vv.UserManager.userIcon
        let userHead = cc.find('head', shareButtom)
        userHead.getComponent('UserHead').setHead(uid, headIcon)

        //分享
        let node = cc.find('hero', this.node)
        let node_share_logo = cc.find('sharePage', node)
        node_share_logo.active = true
        let endCall = function (fullpath) {
            node_share_logo.active = false


            cc.vv.FBMgr.fbShareImg(fullpath)
        }
        Global.captureScreen('herocard_share_camp.jpg', node, endCall, 1)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_SHARE)
    },

    onClickCloseBtn() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_MORE_COLLECTION_CLOSE)
        this.node.destroy()
    },

    onClickExist: function () {
        this.btnFade(true)
        let btnexist = cc.find('btn_exist', this.node)
        btnexist.active = false
    },

    changeHeroPage(flag) {
        for (let i = 0; i < this.heroAllNode.children.length; i++) {
            if (this.heroAllNode.children[i]._name.slice(4) == flag) {
                this.heroAllNode.children[i].active = true
            } else {
                this.heroAllNode.children[i].active = false
            }
        }
    },

    // update (dt) {},
});
