/**
 * 通用的加钱弹窗
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('spr_bg/btn_confirm', this.node), this.onClickConfirm, this);
        Global.playComEff("ch_popup_l2");

        this.count = null
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_SHAREFB_SHAREANDENJOY_SHARETOFB_POP)
    },

    start() {
        Global.FixDesignScale_V(this.node)
        Global.showAlertAction(this.node, true, 0.1, this.node.scale, null);
    },

    setCoin: function (val, flyEndNode, closeCall) {
        this.count = val

        let lblval = cc.find('spr_bg/lbl_coin', this.node)
        lblval.getComponent(cc.Label).string = Global.FormatNumToComma(val)
        // let coin = cc.find('spr_bg/coin_bg',this.node)
        // coin.x = -lblval.width/2 - 260

        this._flyEndNode = flyEndNode
        this._endCall = closeCall
    },

    onClickConfirm: function () {
        Global.playComEff("ch_collect");
        let self = this
        let flyEndCall = function () {
            if (self._endCall) {
                self._endCall()
            }
            Global.playComEff("ch_close");

            if (cc.isValid(self.node)) {
                self.node.destroy()
            }
        }

        if (cc.vv.gameData) {
            this._flyEndNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
        }

        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH) || cc.find(Global.INGAME_COIN_LABEL_NODE_PATH);
        rollData.addCoin = this.count
        Global.FlyCoin(cc.find('spr_bg/lbl_coin', this.node), this._flyEndNode, flyEndCall, rollData, true)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_SHAREFB_SHAREANDENJOY_SHARETOFB_COLLECT)
    },

    // update (dt) {},
});
