/**
 * 升级小提示界面
 */
cc.Class({
    extends: cc.Component,

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.playComEff("ch_notification");
    },

    start() {
        this.node.opacity = 0
        cc.tween(this.node)
            .to(0.5, { opacity: 255 })
            .start()
    },

    setUIData: function (totalCoin, lv, lvCoin, bounsCoin, vipExp, maxbet, endCall) {
        let self = this
        cc.vv.gameData.setCoins(totalCoin)
        let lvTitle = cc.find('lbl_title', this.node)
        lvTitle.getComponent(cc.Label).string = cc.js.formatStr('LEVEL %s', lv)
        this._addCoin = lvCoin + bounsCoin
        this.setLabelVal('lbl_reward', Global.formatNumShort(lvCoin))
        this.setLabelVal('lbl_vip', vipExp)
        // this.setLabelVal('lbl_maxbet',maxbet)
        cc.find('lbl_maxbet/lbl_val', this.node).getComponent(cc.Label).string = Global.FormatNumToComma(maxbet)
        let flyEndCall = function () {
            if (cc.vv.gameData) {
                Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_UPDATE_BALANCE);
                cc.tween(self.node)
                    .to(1, { opacity: 0 })
                    .call(() => {
                        if (endCall) {
                            endCall()
                        }
                        self.node.destroy()
                    })
                    .start()
            }
        }
        cc.tween(this.node)
            .delay(0.5)
            .call(() => {
                self.flyCoin(flyEndCall)
            })
            .start()
    },

    setLabelVal: function (lblName, val) {
        let lbl = cc.find(cc.js.formatStr('%s/lbl_val', lblName), this.node)
        if (lbl) {
            lbl.getComponent(cc.Label).string = val
        }
    },

    flyCoin: function (endCall) {
        //飞金币
        let node_fly = this.node.getChildByName('flycoins')
        if (node_fly) {
            let script = node_fly.getComponent('FlyCoins')
            if (script) {
                let rollData = {}
                rollData.lblCoin = cc.find("Canvas/LMSlots_Top/playerCoins/lbl_coinsNum") || cc.find('Canvas/safe_node/LMSlots_Top/playerCoins/lbl_coinsNum');
                rollData.addCoin = this._addCoin
                let srcObj = cc.find('lbl_title', this.node)
                let fromPos = this.node.convertToNodeSpaceAR(srcObj.convertToWorldSpaceAR(cc.v2(0, 0)))
                let endNode = cc.find("Canvas/LMSlots_Top/playerCoins/icon_coin") || cc.find('Canvas/safe_node/LMSlots_Top/playerCoins/icon_coin');
                let endPos = this.node.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0, 0)));
                script.showFlyCoins(fromPos, endPos, 12, endCall, rollData)
            }
        }
    }

    // update (dt) {},
});
