require("RewardFlyUtils")


cc.Class({
    extends: cc.Component,

    properties: {
        boomPrefab: cc.Prefab,
        itemPrefab: cc.Prefab,
        cardFragPrefab: cc.Prefab,

        bagNode: cc.Node,
        vipExp: cc.Node,
        coin: cc.Node,
        diamond: cc.Node,

        iconVipExp: cc.SpriteFrame,
        iconCoin: cc.SpriteFrame,
        iconDiamond: cc.SpriteFrame,
        iconLight: cc.SpriteFrame,
    },

    onLoad() {
        Global.FixDesignScale_V(this.node)

        this.bagNode.opacity = 0;

        this.vipExp.active = false;
        this.coin.active = false;
        this.diamond.active = false;

        this.nodePool = new cc.NodePool();

        this._gameCoinNode = null;

        let uid = cc.vv.UserManager.uid
        let headIcon = cc.vv.UserManager.userIcon
        let userHead = this.bagNode.getComponent('UserHead')
        if (userHead) userHead.setHead(uid, headIcon)

        Global.registerEvent(EventId.CLICK_SKIP, this.setStipStatus, this);
    },

    onDestroy() {
        this.nodePool.clear();
    },

    setStipStatus() {
        this.clickSkip = true
    },

    filterData(rewards, type) {
        let itemList = [];
        for (const data of rewards) {
            if (data.type == type) {
                itemList.push(data)
            }
        }
        return itemList;
    },
    filterDataTypes(rewards, types) {
        let itemList = [];
        for (const data of rewards) {
            if (types.indexOf(data.type) >= 0) {
                itemList.push(data)
            }
        }
        return itemList;
    },
    bomb(fromWorldPos) {
        let node = cc.instantiate(this.boomPrefab);
        if (node) {
            node.parent = cc.find("Canvas");
            node.position = node.parent.convertToNodeSpaceAR(fromWorldPos);
            node.zIndex = 900;
            node.getComponent(sp.Skeleton).setCompleteListener((tck) => {
                if (tck.animation && tck.animation.name == "animation") {
                    node.destroy()
                    console.log("bomb destroy")
                }
            })
        }
    },
    hint(toWorldPos) {
        let node = this.nodePool.get()
        if (!node) {
            node = new cc.Node()
            node.addComponent(cc.Sprite)
        }
        node.stopAllActions()
        node.getComponent(cc.Sprite).spriteFrame = this.iconLight
        node.parent = cc.find("Canvas")
        node.position = node.parent.convertToNodeSpaceAR(toWorldPos);
        node.zIndex = 1100
        node.scale = 1
        node.opacity = 255
        node.active = true
        cc.tween(node)
            .to(0.2, { scale: 3, opacity: 100 })
            .call(() => {
                this.nodePool.put(node)
            })
            .start()
    },

    async showDropCard(cardid, count, id) {
        let packType = 1
        if (id == Global.PROP_ID.HERO_FRAGEMENT) {
            packType = 2
        }
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showDropUI(cardid, count, sucess, false, packType)
        });
    },

    //掉落整卡
    async showFullCard(rewards) {
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showFullDropUI(rewards, null, sucess)
        });
    },

    async run(rewards, fromWorldPos, callback) {
        this.diamond.active = false
        this.vipExp.active = false
        this.coin.active = false
        this.bagNode.active = false

        let gameCoinNode = cc.find(Global.INGAME_COIN_NODE_PATH)
        if (gameCoinNode) {
            this.runInGame(rewards, fromWorldPos, callback)
        } else {
            this.runInHall(rewards, fromWorldPos, callback)
        }
    },

    async runInHall(rewards, fromWorldPos, callback) {
        this.clickSkip = false
        fromWorldPos = fromWorldPos || cc.find("Canvas").convertToWorldSpaceAR(cc.v2(0, 0));
        cc.vv.AudioManager.playEff("CashHero/", 'reward2', true);
        //卡牌
        let cardDatas = this.filterDataTypes(rewards, [8, 21, 26])
        let haveCard = cardDatas.length > 0
        // 钻石
        let diamondData = this.filterData(rewards, 25);
        if (diamondData.length > 0) {
            this.diamond.active = true;
            // 数字跳动
            Global.doRoallNumEff(this.diamond.getChildByName("lbl_val"), cc.vv.UserManager.getDiamond(), cc.vv.UserManager.getDiamond() + diamondData[0].count, 2, () => {
                this.diamond.active = false;
            }, null, 0, true)
            // 结束世界坐标
            let toWorldPos = this.diamond.getChildByName("spine").convertToWorldSpaceAR(cc.v2(0, 0));
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                spriteFrame: this.iconDiamond,
                pool: this.nodePool,
                scale: 0.4,
                endScale: 0.36,
                count: 15,
                // delay: 0.3,
                onStart: () => {
                    this.bomb(fromWorldPos)
                },
                onEndOne: () => {
                    this.hint(toWorldPos)
                    this.diamond.stopAllActions()
                    cc.tween(this.diamond).to(0.03, { scale: 1.07 }).to(0.03, { scale: 1 }).start();
                },
                onEnd: () => {
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                }
            });
            cc.vv.UserManager.AddDiamond(diamondData[0].count, true)
        }
        //vip经验
        let vipExpData = this.filterData(rewards, 2);
        if (vipExpData.length > 0 && vipExpData[0].count > 0) {
            this.vipExp.active = true;
            let toWorldPos = this.vipExp.getChildByName("vip_icon").convertToWorldSpaceAR(cc.v2(0, 0));
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                spriteFrame: this.iconVipExp,
                pool: this.nodePool,
                scale: 0.4,
                endScale: 0.36,
                count: 10,
                // delay: 0.3,
                onEndOne: () => {
                    this.hint(toWorldPos)
                },
                onEnd: () => {
                    // 后台推送更新
                    //是否有vip升级表现
                    if (cc.vv.UserManager.getVipupFlag()) {
                        cc.vv.UserManager.setVipupFlag(null)
                        cc.vv.QueueWinMrg.addPop("CH_vip_up", null, { type: 1, prefabUrl: "CashHero/prefab/vip/CH_vip_up" })
                    }

                    this.vipExp.active = false
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                }
            });
        }
        // 金币
        let coinData = this.filterData(rewards, 1);
        if (coinData.length > 0) {
            this.coin.active = true;
            let toWorldPos = this.coin.getChildByName("spr_coin").convertToWorldSpaceAR(cc.v2(0, 0));
            // 数字跳动
            Global.doRoallNumEff(this.coin.getChildByName("lbl_coin"), cc.vv.UserManager.coin, cc.vv.UserManager.coin + coinData[0].count, 2, () => {
                this.coin.active = false;
            }, null, 0, true)
            // 飞金币
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                spriteFrame: this.iconCoin,
                pool: this.nodePool,
                scale: 0.4,
                endScale: 0.36,
                count: 15,
                // delay: 0.3,
                onStart: () => {
                    this.bomb(fromWorldPos)
                },
                onEndOne: () => {
                    this.hint(toWorldPos)
                    this.coin.stopAllActions();
                    cc.tween(this.coin).to(0.03, { scale: 1.07 }).to(0.03, { scale: 1 }).start();
                },
                onEnd: () => {
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                }
            });

            if (cc.vv.gameData) {
                cc.vv.gameData.AddCoin(coinData[0].count)
                cc.vv.gameData.RefushMyCoin()
            } else {
                cc.vv.UserManager.AddCoin(coinData[0].count, true)
            }
        }
        // 道具
        let itemDatas = this.filterDataTypes(rewards, [3, 4, 5, 9, 10, 13, 16, 20, 22, 28, 29, 1035, 10008, 10021, 31, 32, 33, 34, 35, 36, 37, 38]);
        if (itemDatas.length > 0) {
            // 出现背包
            this.bagNode.active = true;
            let toWorldPos = this.bagNode.convertToWorldSpaceAR(cc.v2(0, 0));
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                prefab: this.itemPrefab,
                scale: 1.35,
                endScale: 1,
                count: itemDatas.length,
                onInit: (index, node) => {
                    let data = itemDatas[index];
                    node.getComponent("CH_RewardItem").init(data.type);
                },
                onStart: () => {
                    this.bagNode.stopAllActions();
                    cc.tween(this.bagNode).to(0.2, { opacity: 255 }).start();
                    this.bomb(fromWorldPos)
                },
                onEndOne: () => {
                    this.hint(toWorldPos)
                },
                onEnd: () => {
                    this.bagNode.stopAllActions();
                    cc.tween(this.bagNode).to(0.2, { opacity: 0 }).start();
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                },
            });
        }
        //卡牌
        if (cardDatas.length > 0) {
            for (let i = 0; i < cardDatas.length; i++) {
                let reward = cardDatas[i]
                if (reward.cardInfo) {
                    cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                    Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                }
            }

            let showWay = 2
            if (showWay == 1) {//掉落需要点开卡包的形式
                if (diamondData.length > 0 || vipExpData.length > 0 || coinData.length > 0 || itemDatas.length > 0) {
                    await Global.awaitTime(this, 1.2)
                }
                cc.vv.UserManager.setHeroData(cardDatas)

                for (let i = 0; i < cardDatas.length; i++) {
                    let reward = cardDatas[i]
                    if (reward.type == Global.PROP_ID.HERO_CARD || reward.type == Global.PROP_ID.HERO_FRAGEMENT) {
                        await this.showDropCard(reward.cardID, reward.count, reward.type)
                    } else if (reward.type == Global.PROP_ID.FULL_CARD) {
                        await this.showFullCard([reward])
                    }
                    if (this.clickSkip) {
                        break
                    }
                }
            }
            else if (showWay == 2) {//不需要卡包，直接飞卡牌碎片
                this.bagNode.active = true;
                let toWorldPos = this.bagNode.convertToWorldSpaceAR(cc.v2(0, 0));
                Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                    prefab: this.cardFragPrefab,
                    scale: 0.5,
                    endScale: 0.3,
                    count: cardDatas.length,
                    onInit: (index, node) => {
                        let data = cardDatas[index];
                        node.getComponent("CH_Herocard_reward_frag").show(data.cardID, data.count);
                    },
                    onStart: () => {
                        this.bagNode.stopAllActions();
                        cc.tween(this.bagNode).to(0.2, { opacity: 255 }).start();
                        this.bomb(fromWorldPos)
                    },
                    onEndOne: () => {
                        this.hint(toWorldPos)
                    },
                    onEnd: () => {
                        this.bagNode.stopAllActions();
                        cc.tween(this.bagNode).to(0.2, { opacity: 0 }).start();
                        if (callback && !haveCard) {
                            callback()
                            callback = null
                        }
                    },
                });
            }

        }

        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: reward.type, num: reward.count })
            if (reward.type == Global.PROP_ID.LOCAL_FULL_CARD || reward.type == Global.PROP_ID.LOCAL_HERO_CARD) {
                Global.dispatchEvent(EventId.REFUSH_HEROCARD_RED_TIPS)
            }
        }

        if (callback) {
            callback()
            callback = null
        }
    },

    async runInGame(rewards, fromWorldPos, callback) {
        this.clickSkip = false
        fromWorldPos = fromWorldPos || cc.find("Canvas").convertToWorldSpaceAR(cc.v2(0, 0));
        cc.vv.AudioManager.playEff("CashHero/", 'reward2', true);
        //卡牌
        let cardDatas = this.filterDataTypes(rewards, [8, 21, 26])
        let haveCard = cardDatas.length > 0

        //金币节点
        let coinData = this.filterData(rewards, 1);
        if (coinData.length) {
            if (!this._gameCoinNode) {
                let targetNode = cc.find(Global.INGAME_COIN_NODE_PATH).parent
                if (targetNode) {
                    this._gameCoinNode = cc.instantiate(targetNode)
                    this._gameCoinNode.parent = this.node
                    this._gameCoinNode.position = this.node.convertToNodeSpaceAR(targetNode.convertToWorldSpaceAR(cc.v2(0, 0)))
                }
            }
        }

        //背包位置
        let bagNode = cc.find(Global.INGAME_BAG_NODE_PATH)
        let bagWorldPos = bagNode.convertToWorldSpaceAR(cc.v2(0, 0))

        // 钻石
        let diamondData = this.filterData(rewards, 25);
        if (diamondData.length > 0) {
            // 结束世界坐标
            let toWorldPos = bagWorldPos
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                spriteFrame: this.iconDiamond,
                pool: this.nodePool,
                scale: 0.4,
                endScale: 0.36,
                count: 15,
                // delay: 0.3,
                onStart: () => {
                    this.bomb(fromWorldPos)
                },
                onEndOne: () => {
                    this.hint(toWorldPos)
                },
                onEnd: () => {
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                }
            });
            cc.vv.UserManager.AddDiamond(diamondData[0].count, true)
        }
        //vip经验
        let vipExpData = this.filterData(rewards, 2);
        if (vipExpData.length > 0 && vipExpData[0].count > 0) {
            let toWorldPos = bagWorldPos
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                spriteFrame: this.iconVipExp,
                pool: this.nodePool,
                scale: 0.4,
                endScale: 0.36,
                count: 10,
                // delay: 0.3,
                onEndOne: () => {
                    this.hint(toWorldPos)
                },
                onEnd: () => {
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                }
            });
        }
        // 金币
        if (coinData.length > 0) {
            this._gameCoinNode.active = true;
            let toWorldPos = this._gameCoinNode.getChildByName("icon_coin").convertToWorldSpaceAR(cc.v2(0, 0));
            // 数字跳动
            Global.doRoallNumEff(this._gameCoinNode.getChildByName("lbl_coinsNum"), cc.vv.UserManager.coin, cc.vv.UserManager.coin + coinData[0].count, 2, () => {
                this._gameCoinNode.active = false;
            }, null, 0, true)
            // 飞金币
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                spriteFrame: this.iconCoin,
                pool: this.nodePool,
                scale: 0.4,
                endScale: 0.36,
                count: 15,
                // delay: 0.3,
                onStart: () => {
                    this.bomb(fromWorldPos)
                },
                onEndOne: () => {
                    this.hint(toWorldPos)
                    this._gameCoinNode.stopAllActions();
                    cc.tween(this._gameCoinNode).to(0.03, { scale: 1.07 }).to(0.03, { scale: 1 }).start();
                },
                onEnd: () => {
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                }
            });

            if (cc.vv.gameData) {
                cc.vv.gameData.AddCoin(coinData[0].count)
                cc.vv.gameData.RefushMyCoin()
            } else {
                cc.vv.UserManager.AddCoin(coinData[0].count, true)
            }
        }
        // 道具
        let itemDatas = this.filterDataTypes(rewards, [3, 4, 5, 9, 10, 13, 16, 20, 22, 28, 29, 1035, 10008, 10021, 31, 32, 33, 34, 35, 36, 37, 38]);
        if (itemDatas.length > 0) {
            let toWorldPos = bagWorldPos
            Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                prefab: this.itemPrefab,
                scale: 1.35,
                endScale: 1,
                count: itemDatas.length,
                onInit: (index, node) => {
                    let data = itemDatas[index];
                    node.getComponent("CH_RewardItem").init(data.type);
                },
                onStart: () => {
                    this.bomb(fromWorldPos)
                },
                onEndOne: () => {
                    this.hint(toWorldPos)
                },
                onEnd: () => {
                    if (callback && !haveCard) {
                        callback()
                        callback = null
                    }
                },
            });
        }
        //卡牌
        if (cardDatas.length > 0) {
            let showWay = 2
            if (showWay == 1) {//掉落需要点开卡包的形式
                if (diamondData.length > 0 || vipExpData.length > 0 || coinData.length > 0 || itemDatas.length > 0) {
                    await Global.awaitTime(this, 1.2)
                }
                cc.vv.UserManager.setHeroData(cardDatas)
                for (let i = 0; i < cardDatas.length; i++) {
                    let reward = cardDatas[i]
                    if (reward.cardInfo) {
                        cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                        Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                    }
                }
                for (let i = 0; i < cardDatas.length; i++) {
                    let reward = cardDatas[i]
                    if (reward.type == Global.PROP_ID.HERO_CARD || reward.type == Global.PROP_ID.HERO_FRAGEMENT) {
                        await this.showDropCard(reward.cardID, reward.count, reward.type)
                    } else if (reward.type == Global.PROP_ID.FULL_CARD) {
                        await this.showFullCard([reward])
                    }
                    if (this.clickSkip) {
                        break
                    }
                }
            }
            else {
                for (let i = 0; i < cardDatas.length; i++) {
                    let reward = cardDatas[i]
                    if (reward.cardInfo) {
                        cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                        Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                    }
                }
                let toWorldPos = bagWorldPos
                Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                    prefab: this.cardFragPrefab,
                    scale: 0.5,
                    endScale: 0.3,
                    count: cardDatas.length,
                    onInit: (index, node) => {
                        let data = cardDatas[index];
                        node.getComponent("CH_Herocard_reward_frag").show(data.cardID, data.count);
                    },
                    onStart: () => {
                        this.bomb(fromWorldPos)
                    },
                    onEndOne: () => {
                        this.hint(toWorldPos)
                    },
                    onEnd: () => {
                        if (callback && !haveCard) {
                            callback()
                            callback = null
                        }
                    },
                });
            }

        }

        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: reward.type, num: reward.count })
            if (reward.type == Global.PROP_ID.LOCAL_FULL_CARD || reward.type == Global.PROP_ID.LOCAL_HERO_CARD) {
                Global.dispatchEvent(EventId.REFUSH_HEROCARD_RED_TIPS)
            }
        }

        if (callback) {
            callback()
            callback = null
        }
    },



})
