/**
 * 10连抽卡
 */
cc.Class({
    extends: cc.Component,

    properties: {
        images: {
            default: [],
            type: cc.SpriteFrame,
        },
        campicons: {
            default: [],
            type: cc.SpriteFrame,
        },
        subicons: {
            default: [],
            type: cc.SpriteFrame,
        },
        _campid: 1003
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find("bottom/btn_close", this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this);
        let btn_rule = cc.find("btn_rule", this.node)
        Global.btnClickEvent(btn_rule, this.onClickRule, this);

        Global.onClick("hero/summon1/btn", this.node, this.onClickHeroOne, this)
        Global.onClick("hero/summon2/btn", this.node, this.onClickHeroTen, this)
        Global.onClick("camp/summon3/btn", this.node, this.onClickCampOne, this)
        Global.onClick("camp/summon4/btn", this.node, this.onClickCampTen, this)

        Global.onClick("bottom/btn_hero", this.node, this.onClickHero, this)
        Global.onClick("bottom/btn_camp", this.node, this.onClickCamp, this)

        let touchLayer = cc.find("camp/touch", this.node)
        touchLayer.on(cc.Node.EventType.TOUCH_START, this.onTouchStart, this)
        touchLayer.on(cc.Node.EventType.TOUCH_END, this.onTouchEnd, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_HEROCARD_SUMMON_DIAMOND, this.onRcvCardSummonByDiamond, this);
        Global.registerEvent(EventId.NEWGUIDE_PRO_UI, this.onEventCompleteNewGuide, this)
        Global.registerEvent(EventId.UPATE_DIAMOND, this.onEventRefushDiamond, this)

        this._moving = false
        this._icons = []
        for (let i = 1; i <= 5; i++) {
            this._icons.push(cc.find("camp/camps/icon_" + i, this.node))
        }
        this.showCamp(1003)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_POP)
    },
    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HEROCARD_SUMMON_DIAMOND, this.onRcvCardSummonByDiamond, false, this);
    },

    onEnable() {
        this._hasSend = null
    },

    start() {
        let tempGuide = cc.vv.NewGuide.GetGuideTempData()
        if (tempGuide == 22 && this._baseInfo.times) {
            cc.vv.NewGuide.ShowGuide(22)
        }
    },

    init(summonInfo) {
        this._baseInfo = summonInfo
        this.onEventRefushDiamond()
        this._setPrice()

    },

    onEventRefushDiamond: function () {
        let nVal = cc.vv.UserManager.getDiamond()
        cc.find("diamond/label", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(nVal);

        if (this._baseInfo) {
            let nOneFee = this._baseInfo.data[0].price
            let nTenFee = this._baseInfo.data[1].price
            cc.find("hero/summon1/reddot", this.node).active = (nVal < nTenFee) && (nVal >= nOneFee)
            cc.find("hero/summon2/reddot", this.node).active = (nVal >= nTenFee) || this._baseInfo.times

            let nOneCampFee = 300
            if (this._baseInfo.data[2]) nOneCampFee = this._baseInfo.data[2].price
            let nTenCampFee = 3000
            if (this._baseInfo.data[3].price) nTenCampFee = this._baseInfo.data[3].price
            cc.find("camp/summon3/reddot", this.node).active = (nVal < nOneCampFee) && (nVal >= nOneCampFee)
            cc.find("camp/summon4/reddot", this.node).active = (nVal >= nTenCampFee)
            if (!cc.find("camp", this.node).active) {
                cc.find("bottom/btn_camp/reddot", this.node).active = (nVal >= nTenCampFee)
            }
        }
    },


    onClickClose: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_CLOSE)
        Global.playComEff("ch_close");
        this.node.destroy()
    },

    onClickRule: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_RULE)
        Global.playComEff("ch_btn_click");

        let url = 'CashHero/prefab/herocard/card_sum_rule'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let old = cc.find('Canvas').getChildByName('card_sum_rule')
                if (!old) {
                    old = cc.instantiate(prefab)
                    old.parent = cc.find('Canvas')
                }
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },


    //抽1次
    onClickHeroOne: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_ONCE)
        if (!this._baseInfo) return;
        if (this._hasSend) return//防止多次快速点击
        this._doSummon(1)
    },
    //抽10次
    onClickHeroTen: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_TENTN)
        if (!this._baseInfo) return;
        if (this._hasSend) return//防止多次快速点击
        this._doSummon(2)
    },
    //抽1次
    onClickCampOne: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_ONCE)
        if (!this._baseInfo) return;
        if (this._hasSend) return//防止多次快速点击
        this._doSummon(3)
    },
    //抽10次
    onClickCampTen: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_SUMMON_TENTN)
        if (!this._baseInfo) return;
        if (this._hasSend) return//防止多次快速点击
        this._doSummon(4)
    },
    onClickHero() {
        cc.find("hero", this.node).active = true
        cc.find("camp", this.node).active = false
    },
    onClickCamp() {
        cc.find("hero", this.node).active = false
        cc.find("camp", this.node).active = true
        cc.find("bottom/btn_camp/reddot", this.node).active = false
    },

    onTouchStart(event) {
        this._startPos = event.touch.getLocation()
    },

    onTouchEnd(event) {
        let endPos = event.touch.getLocation()
        let dx = endPos.x - this._startPos.x
        if (Math.abs(dx) < 10) {
            let np = event.target.convertToNodeSpaceAR(endPos)
            if (np.x < -220) {
                this.moveCamp(-1)
            } else if (np.x > 220) {
                this.moveCamp(1)
            }
        } else {
            if (dx < 0) {
                this.moveCamp(1)
            } else {
                this.moveCamp(-1)
            }
        }
    },

    //dir:-1左->右 1右->左
    moveCamp(dir) {
        if (this._moving) return
        let campid = this._campid + dir
        if (campid < 1001) campid = 1005
        if (campid > 1005) campid = 1001
        console.log("campid", campid)
        let camps = cc.find("camp/camps", this.node)
        this._moving = true
        let dx = 500
        cc.tween(camps)
            .by(0.5, { x: -dx * dir }, { easing: 'sineOut' })
            .call(() => {
                if (dir < 0) {
                    let px = this._icons[0].x - dx
                    let icon = this._icons.pop()
                    icon.x = px
                    this._icons.unshift(icon)
                } else {
                    let px = this._icons[4].x + 500
                    let icon = this._icons.shift()
                    icon.x = px
                    this._icons.push(icon)
                }
                this._moving = false
                this.showCamp(campid)
            })
            .start()
    },

    showCamp(campid) {
        this._campid = campid
        let idx = campid - 1000
        Global.setSpriteFrame("camp/img", this.node, this.images[idx - 1])
        Global.setSpriteFrame("camp/img/campicon", this.node, this.campicons[idx - 1])
        Global.setSpriteFrame("camp/sub_1", this.node, this.subicons[idx - 1])
        Global.setSpriteFrame("camp/sub_2", this.node, this.subicons[idx - 1])
        for (let i = 1; i <= 5; i++) {
            cc.find("camp/camps/icon_" + i + "/select", this.node).active = (i == idx)
        }
    },

    _doSummon: function (type, msg = null) {
        let self = this
        let nDiamond
        if (type == 1) {
            nDiamond = this._baseInfo.data[0].price
        }
        else {
            nDiamond = this._baseInfo.data[1].price
            if (this._baseInfo.times) {
                nDiamond = 0
            }
        }
        if (cc.js.isNumber(nDiamond)) {
            let nMyDiamond = cc.vv.UserManager.getDiamond()
            if (nMyDiamond < nDiamond) {
                //钻石不够
                let sureCall = function () {
                    //跳转充值钻石
                    cc.vv.UserManager.setEnterHallAction('Shop_Diamond')
                    Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
                    self.onClickClose()
                    cc.vv.HerocardManager.hideFullDropUI()

                    StatisticsMgr.reqReport(StatisticsMgr.REQ_SHOWSIMPLE_YES, type + '|' + '钻石不足' + '|' + msg)
                }
                let cancelCall = function () {
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_SHOWSIMPLE_NO, type + '|' + '钻石不足' + '|' + msg)
                }
                StatisticsMgr.reqReport(StatisticsMgr.REQ_SHOWSIMPLE_POP, type + '|' + '钻石不足' + '|' + msg)
                cc.vv.AlertView.showSimple('Diamonds are not enough! Go get the diamond?', sureCall, cancelCall)
                return
            }
            else {
                if (nDiamond == 0) {
                    //免费直接抽
                    self._doByDiamond(type, true)
                }
                else {
                    //钻石足够
                    // let sureCall = function(){
                    //开始抽卡
                    self._doByDiamond(type)
                    //     StatisticsMgr.reqReport(StatisticsMgr.REQ_SHOWSIMPLE_YES, type+'|'+'钻石足够'+'|'+msg)
                    // }
                    // let cancelCall = function(){
                    //     StatisticsMgr.reqReport(StatisticsMgr.REQ_SHOWSIMPLE_NO, type+'|'+'钻石足够'+'|'+msg)
                    // }
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_SHOWSIMPLE_POP, type + '|' + '钻石足够' + '|' + msg)
                    // cc.vv.AlertView.showSimple(cc.js.formatStr('Sure you use %s diamonds to summon heroes?',nDiamond),sureCall,cancelCall)
                }

            }
        }


    },

    _doByDiamond: function (val, bFree) {
        var req = { 'c': MsgId.REQ_HEROCARD_SUMMON_DIAMOND };
        req.stype = val
        req.campid = this._campid
        if (bFree) {
            req.is_free = 1
        }
        cc.vv.NetManager.send(req, true);
        Global.dispatchEvent("RefushTaskStatus")
        //
        this._hasSend = true
    },

    _setPrice: function () {
        let defaultPrices = [270, 2700, 300, 3000]
        for (let i = 0; i < 4; i++) {
            let lblPrice = null
            if (i < 2) {
                lblPrice = cc.find(cc.js.formatStr('hero/summon%s/btn/Background/lbl_fee', i + 1), this.node)
            } else {
                lblPrice = cc.find(cc.js.formatStr('camp/summon%s/btn/Background/lbl_fee', i + 1), this.node)
            }

            let price = this._baseInfo.data[i].price
            if (!price) price = defaultPrices[i]
            if (1 == i && this._baseInfo.times) {
                //有10连抽的次数
                price = 0
            }
            lblPrice.getComponent(cc.Label).string = price
        }
    },
    //抽卡表现
    _showRewards: function (datas, actionType) {
        let self = this
        let againCall = function () {
            self._doSummon(actionType, 'again')
        }
        let endCall = function () {
            // cc.vv.NewGuide.ShowGuide(60)
            self._hasSend = false
        }

        cc.vv.HerocardManager.showFullDropUI(datas, againCall, endCall, actionType)
    },

    onRcvCardSummonByDiamond: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode == 0) {
                //有免费次数优先扣除
                if (this._baseInfo.times) {
                    this._baseInfo.times -= 1
                    Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI, 58)
                    this._setPrice()
                }
                //更新钻石
                cc.vv.UserManager.setDiamond(msg.diamond, true)
                //抽卡表现
                this._showRewards(msg.rewards, msg.stype)

            }
            else {
                this._hasSend = false
                // cc.vv.FloatTip.show(cc.js.formatStr('SPCODE: %s',msg.spcode));
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_spcode, msg.spcode));
            }
        }
    },

    onEventCompleteNewGuide: function (data) {
        let val = data.detail
        if (val == 21) {
            //test
            //this._baseInfo.times += 1
            //有10连抽免费次数
            if (this._baseInfo.times) {
                let bDone58 = cc.vv.NewGuide.ShowGuide(58)
                if (!bDone58) {
                    cc.vv.NewGuide.SetGuideTempData(58)
                }
            }
        }
    },

    // update (dt) {},
});
