/**弹窗队列
 */
cc.Class({
    extends: cc.Component,

    statics: {
        _queue: [],
        _bPlaying: null,//是否正在播放弹窗

        //添加一个弹窗，弹出的窗口onDestroy中一定要调用cc.vv.QueueWinMrg.nextPop()
        //winKey:弹窗的键
        //winData:弹窗需要的数据，如果需要通过脚本传递数据，否则null
        //showWay:弹窗的显示方式{type,prefabUrl,initDataCall}
        // type:1 统一的prefab加载显示.此时需要带prefabUrl. 如果有数据需要传递的话，可补充initDataCall(node), 2 自己控制显示，会发送一个消息(EventId.SHOW_QUEUE_POP)出去，带key,data
        addPop: function (winKey, winData, showWay) {
            let item = {}
            item.key = winKey
            item.data = winData
            item.showway = showWay
            this._queue.push(item)
            if (!this._bPlaying) this.startPop()
        },

        //开始检查弹窗
        startPop: function () {
            let self = this
            if (this._bPlaying) return
            //取第一个
            this._bPlaying = this._queue.shift()
            if (this._bPlaying) {
                //开始弹窗
                let showway = this._bPlaying.showway
                if (showway) {
                    if (showway.type == 1) {
                        //统一加载预制
                        let parNode = cc.find("Canvas")
                        let url = showway.prefabUrl
                        let loadEndCall = function (prefab) {
                            if (self._bPlaying.key && cc.isValid(parNode) && !cc.find(self._bPlaying.key, parNode)) {
                                let node = cc.instantiate(prefab)
                                node.parent = parNode
                                //通过initData来传第数据
                                if (self._bPlaying.data && showway.initDataCall) {
                                    showway.initDataCall(node, self._bPlaying.data)
                                    // node.getComponent(showway.scpName).initData(self._bPlaying.data)
                                }

                            }

                        }
                        this._loadPrefab(url, loadEndCall)
                        return
                    }
                }
                Global.dispatchEvent(EventId.SHOW_QUEUE_POP, this._bPlaying)
            }
            else {
                //已经没有弹窗了
                this.endPop()
            }
        },

        //可以下一个了
        nextPop: function () {
            this._bPlaying = null
            this.startPop()
        },

        endPop: function () {
            Global.dispatchEvent(EventId.END_QUEUE_POP)
        },

        _loadPrefab: function (url, callbacks) {
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    callbacks(prefab)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        },

        getQueueList() {
            return this._queue
        },

        //是否已经存在这样的队列数据
        hasInQueueList(key) {
            let _queueList = this.getQueueList()
            if (_queueList.length) {
                for (let i = 0; i < _queueList.length; i++) {
                    if (_queueList[i].key == key) {
                        return _queueList[i].data ? _queueList[i].data : true
                    }
                }
            }
            return false
        },
        //清理未播放的数据
        clearQueueList() {
            this._queue = []
        },

        delQueueItem(key) {
            let _queueList = this.getQueueList()
            if (_queueList.length) {
                for (let i = 0; i < _queueList.length; i++) {
                    if (_queueList[i].key == key) {
                        _queueList.splice(i, 1)
                    }
                }
            }
        },

    },




    // update (dt) {},
});
