/**
 * 卷轴控制单元
 */
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        handler: null,
        reelScale: 1,
    },

    onLoad() {
        this._super();
        this.isLoaded = true;
        if (this._nCount) {
            this.Init(this._reelIdx, this._nCount, this._topAniNode);
        }
    },

    onDestroy() {
        this.handler = null;
    },

    /**
     * @override
     * @param {*} idx 
     * @param {*} nCount 
     * @param {*} node 
     */
    Init: function (idx, nCount, node) {
        this._reelIdx = idx;
        this._nCount = nCount;
        this._symbols = [];
        this._topAniNode = node;
        this._cfg = cc.vv.gameData.getGameCfg();
        if (this.isLoaded) {
            this.LoadSymbols();
            this.ShowAntiEffect(false);
        }
    },

    /**
     * @override
     */
    CreateOneSymbol: function () {
        this._super();
        let symbol = this._symbols[this._symbols.length - 1];
        symbol.node.scale = this.reelScale;
        symbol.isEpic = true;
        symbol._nodeScale = this.reelScale
        symbol.showColor();
    },

    /**
     * @override
     */
    OnReelSpinEnd: function () {
        this.ShowAntiEffect(false)
        this.notifyEvt({ evtName: "reel_spin_end", data: this._reelIdx });
    },

    /**
     * @override
     */
    ReadyToStop: function () {
        if (!this._bNotifyReadyStop) {
            this._bNotifyReadyStop = true
            // let slots = cc.vv.gameData.GetSlotsScript()
            // slots.OnReelReadyToStop(this._reelIdx)
        }
    },

    //列回弹动作之前
    OnReelBounsActionBefore: function () {
        // let slots = cc.vv.gameData.GetSlotsScript()
        // slots.OnReelBounsActionBefore(this._reelIdx)
        if (this._originResult) {
            for (let i = 0; i < this._originResult.length; i++) {
                this._symbols[i].StopMoveBefore();
            }
        }
    },

    /**
     * @override
     */
    OnReelBounsActionDeep: function () {
        this.ShowAntiEffect(false)
        this.playReelStop()
        // let slots = cc.vv.gameData.GetSlotsScript()
        // slots.OnReelBounsActionDeep(this._reelIdx)
        if (this._originResult) {
            for (let i = 0; i < this._originResult.length; i++) {
                this._symbols[i].StopMoveDeep();
            }
        }

    },

    /**
     * @override
     */
    OnReelBounsActionEnd: function () {
        // let slots = cc.vv.gameData.GetSlotsScript()
        // slots.OnReelBounsActionEnd(this._reelIdx)
        if (this._originResult) {
            for (let i = 0; i < this._originResult.length; i++) {
                this._symbols[i].StopMoveEnd();
            }
        }
        else {
            console.log('回弹结束，数据已经被清空了')
        }

        this.OnReelSpinEnd()
    },

    setHandler(handler) {
        this.handler = handler;
    },

    notifyEvt(evt) {
        if (this.handler) {
            this.handler(evt);
        }
    },

    getFirstSymbol() {
        return this._symbols[0];
    }
});
