/**
 * 大厅英雄卡防守阵营
 */

cc.Class({
    extends: require('CH_Herocard_HallItem'),

    properties: {
    },

    // LIFE-CYCLE CALLBACKS:

    start() {

    },

    init: function (cardInfo, pageHeroScript, formationScript) {
        this._super(cardInfo, pageHeroScript);

        this._formationScript = formationScript;
        cc.find('ui/btn_detail', this.node).active = false;
    },

    onClickChip: function () {
        if (this._cardInfo && this._cardInfo != -1) {
            // if(this._curSelect){
            //打开详情
            this.onClickBtnDetail()
            // }
            // else{
            //     // 滚动到此位置
            //     this._pageHeroScript.scrollToCard(this._cardInfo.cfg.cardid)
            // }
        }
    },

    _onTouchStart(event) {
        this._moved = false
        this._startPos = event.getLocation()
        this._lastPos = cc.v2(this._startPos.x, this._startPos.y)
        console.log(this._lastPos);

        this._bMoveH = false;
        this._bMoveV = false;
    },

    _onTouchMove(event) {
        let location = event.getLocation()
        if (this._cardInfo && this._cardInfo != -1) {
            // if(this._curSelect){
            if (this._lastPos.sub(location).len() > 4) {
                let box = this.node.getBoundingBox()
                if (location.y < this._startPos.y && !this._bMoveH) {
                    this._bMoveV = true;
                }
                else if (location.x != this._startPos.x && !this._bMoveV) {
                    this._bMoveH = true;
                }

                if (this._bMoveV) {
                    if (location.y < this._startPos.y) {
                        let endPos = this.node.parent.convertToNodeSpaceAR(this._pageHeroScript.getListCardEndPos())
                        this.node.y = this.node.parent.convertToNodeSpaceAR(cc.v2(location.x, location.y - box.height / 2)).y

                        this.node.opacity = Math.max(0, 255 * (1 - (this._startPos.y - location.y) / box.height))
                        if (this.node.y <= endPos.y/*+box.height/2*/) {
                            this.node.isAlive = false;
                            this.node.opacity = 0;
                        } else {
                            this.node.isAlive = true;
                            this.node.opacity = 255;
                        }
                    }
                    else {
                        this.restNode();
                    }
                }
                else if (this._bMoveH) {
                    this.node.zIndex = 100;
                    let moveX = this.node.parent.convertToNodeSpaceAR(cc.v2(location.x, location.y)).x;
                    moveX = Math.max(this._formationScript.getItemMinX(), moveX);
                    moveX = Math.min(this._formationScript.getItemMaxX(), moveX);
                    this.node.x = moveX;

                    let def = 0;
                    if (location.x > this._lastPos.x) {   // 右移
                        def = -1;
                    } else if (location.x < this._lastPos.x) {    // 左移
                        def = 1;
                    }
                    if (def != 0) {
                        let oldIdx = this.node.posIdx
                        let newIdx = this._formationScript.getIdxByPosX(this.node.x, def);
                        if (newIdx && newIdx != oldIdx) {
                            this._formationScript.putItemAtPosIdx(this.node, newIdx, def)

                            // this.node.posIdx = newIdx;
                            // let newItem = this._formationScript.getItemByIdx(newIdx);
                            // if(newItem){
                            //     let moveIdx = this._formationScript.moveItem(newItem, def);
                            //     this._formationScript.changeItem(newIdx,this.node,moveIdx,newItem);
                            // } else {
                            //     this._formationScript.changeItem(newIdx,this.node,oldIdx);
                            // }
                        }
                    }
                }
                this._lastPos = cc.v2(location.x, location.y)
            }
        }
    },

    _onTouchEnd(event) {
        if (this.node.isAlive) {
            // let nextIdx = this._formationScript.getIdxByPosX(this.node.x);
            // if(nextIdx != this.node.posIdx){
            //     this.node.posIdx = nextIdx;
            //     this._formationScript.changeItem(nextIdx,this.node)
            // }

            this.restNode();
        } else {
            this.node.destroy()
            this._formationScript.deleteFormation(this.node.cardid)
        }

        if (this._bMoveH || this._bMoveV) {
        } else {
            if (this._cardInfo && this._cardInfo != -1) {
                this.onClickChip()
            }
        }
    },

    _onTouchCanel(event) {
        this._onTouchEnd(event)
    },


    restNode() {
        if (this.node.isAlive) {
            this.node.position = this._formationScript.getPosByIdx(this.node.posIdx);
            this.node.opacity = 255;
            this.node.zIndex = this.node.posIdx;
        }
    },

    showRedDot: function () {
        let sprReddot = cc.find('ui/reddot', this.node)
        sprReddot.active = false
    },

    // update (dt) {},
});
