//邮件类型
let MailType = {
    thanks_mail: 2,     //感谢邮件                  
    welcome_mail: 8,    //新手邮件
    // newGame_mail: 11,   //新的子游戏推荐            ////
    friends_mail: 12,   //往好友系统领取页面跳转    
    update_mail: 13,   //维护后的奖励邮件
    // unlockGame_mail:14, //解锁新子游戏              /////
    vip_mail: 15,   //vip邮件
    bingo_mail: 16,   //bingo排行榜
    rankGift_mail: 17,   //排行榜奖励邮件
    congrat_mail: 18,   //押注邮件
    connect_mail: 19,   //绑定邮件
    grouthfound_mail: 20,//基金限时优惠券
    pvp_season_rewards: 21,//pvp赛季奖励
    invite_friends: 22,  //邀请好友成功
};

