let SPACEKEY = '     ';

let BTNSTRING = {
    COLLECT: 'COLLECT',
    GOCLAIM: 'GO CLAIM',
    GO: 'GO',
};
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_MAIL_ATTACH, this.OnRcvNetMailAttach, this);

        this._data = null
        let funcBtn = cc.find('funcBtn', this.node)
        Global.btnClickEvent(funcBtn, this.onClickCollect, this)
        // cc.find('label',funcBtn).getComponent(cc.Label).string = BTNSTRING.COLLECT
        let btni18Scp = cc.find('label', funcBtn).getComponent("LanguageLabel")
        btni18Scp.id = 'btn_collect'
        btni18Scp.updateLabel()

        let btnClose = cc.find('closeBtn', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)
        Global.playComEff("ch_popup_l2");
    },

    start() {
        // Global.showAlertAction(cc.find('spr_bg',this.node),true)

    },

    onDestroy() {
        if (this._endCall) {
            this._endCall()
        }
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_MAIL_ATTACH, this.OnRcvNetMailAttach, false, this);
    },

    setData: function (data, endCall, boxType, openVipFlag) {
        this._data = data
        this._endCall = endCall
        //标题
        // cc.find('title',this.node).getComponent(cc.Label).string = this._data.title
        let title = cc.find('title', this.node)
        // //标题 固定邮件为固定的翻译 后台发送的系统邮件由发送者控制
        // if (this._data.type > 2) {
        //     //设置key 刷新
        //     let titlei18Scp = title.getComponent("LanguageLabel")
        //     titlei18Scp.id = 'hall_mail_title'+this._data.type
        //     titlei18Scp.updateLabel()
        // }else {
        title.getComponent(cc.Label).string = this._data.title
        // }

        //日期
        cc.find('date', this.node).getComponent(cc.Label).string = this._data.sendtime
        //发送者
        cc.find('sender', this.node).getComponent(cc.Label).string = this._data.fromname
        //信息
        let _str = this._data.msg
        let lblText = cc.find('black/scrolll/view/content/lbl', this.node).getComponent(cc.Label)
        let richText = cc.find('black/scrolll/view/content/rich', this.node).getComponent(cc.RichText)
        if (this._data.type == MailType.rankGift_mail || this._data.type == MailType.pvp_season_rewards) {
            richText.node.active = true
            lblText.node.active = false
            this._boxType = boxType
            let rankData = this._data.msg.split('&')
            if (rankData.length < 2) {
                rankData = this._data.msg.split('|')
            }
            let n = parseInt(rankData[0] - 1)
            // _str = "You've get "+ '<color=#FBF50A>' +'NO.'+rankData[1]+'</color>'+'<br/>'+rankInfo[n]+ rankData[2] + '.'
            // _str = "You've get "+ '<color=#FBF50A>' +'NO.'+rankData[1]+'</color>'+rankInfo[n]+ rankData[2] + '.' +'<br/>' + SPACEKEY + 'Go and claim your bonus!'
            if (this._data.type == MailType.pvp_season_rewards) {
                I18N.setI18nLabel(richText.node, cc.vv.Language['hall_mail_des' + this._data.type], rankData[1], rankData[2])
            }
            else {
                I18N.setI18nLabel(richText.node, cc.vv.Language['hall_mail_des' + this._data.type + '_' + n], rankData[1], rankData[2])
            }

            // richText.string = SPACEKEY + _str
        }
        else {
            richText.node.active = false
            lblText.node.active = true

            if (this._data.type > 2) {
                if (this._data.type == 18 || this._data.type == 16) {
                    I18N.setI18nLabel(lblText.node, cc.vv.Language['hall_mail_des' + this._data.type], this._data.msg)
                } else {
                    // //设置key 刷新
                    // let lbli18Scp = lblText.node.getComponent("LanguageLabel")
                    // lbli18Scp.id = 'hall_mail_des'+this._data.type
                    // lbli18Scp.updateLabel()
                    lblText.string = SPACEKEY + _str
                }
            } else {
                lblText.string = SPACEKEY + _str
            }



            // lblText.string = SPACEKEY + _str
        }

        //奖励
        cc.find('reward', this.node).active = this._data.attach.length
        this.initItem()
        //按钮 好友礼物邮件
        if (this._data.type == MailType.friends_mail && !this._data.attach.length) {
            this.goClaimBtn()
        }

        //按钮 打开vip
        if (this._data.type == MailType.vip_mail && openVipFlag) {
            this.openVIPBtn()
        }
    },

    initItem: function () {
        cc.find('reward', this.node).getComponent('CH_InitRewardItem').init(this._data.attach)
    },

    onClickCollect: function () {
        // if (this._data.type == MailType.rankGift_mail) {
        //     //领取的排行榜礼物
        //     if (!cc.vv.UserManager.isBindFb()) {
        //         this.fbConnectPop()
        //         return
        //     }
        // }

        cc.find('funcBtn', this.node).getComponent(cc.Button).interactable = false
        this.sendGetReward()
    },

    fbConnectPop() {
        let self = this
        cc.loader.loadRes("CashHero/prefab/CH_MailTipPop", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas");
                if (canvas.isValid && !cc.find('CH_MailTipPop', canvas)) {
                    let obj = cc.instantiate(prefab)
                    obj.parent = canvas
                    obj.getComponent('CH_MailTipPop').initBoxType(self._boxType)
                }
            }
        })
    },

    refrushMail: function () {
        cc.vv.NetManager.send({ c: MsgId.REQ_MAIL_LIST })
    },

    deleteMail: function () {
        Global.dispatchEvent(EventId.REMOVE_CH_MAIL_ITEM, { data: this._msg })
    },

    sendGetReward: function () {
        let req = { c: MsgId.REQ_GET_MAIL_ATTACH }
        req.mailid = this._data.mailid
        cc.vv.NetManager.send(req);
    },

    onClickGoClaim: function () {
        Global.playComEff("ch_btn_click");
        cc.find('funcBtn', this.node).getComponent(cc.Button).interactable = false

        //聊天界面
        Global.dispatchEvent(EventId.GO_HALL_TAB, 4)
        //好友界面
        Global.dispatchEvent(EventId.OPEN_HALL_FRIENDS, { fromMail: true })

        //刷新邮件
        this.sendGetReward()

        if (this.node) {
            this.node.destroy()
            Global.dispatchEvent(EventId.CLOSE_HALL_MAIL)
        }
    },

    onClickOpenVIP: function () {
        Global.playComEff("ch_btn_click");
        cc.find('funcBtn', this.node).getComponent(cc.Button).interactable = false
        //刷新邮件
        this.refrushMail()

        //打开VIP
        var canvas = cc.find("Canvas");
        cc.loader.loadRes("CashHero/prefab/vip/CH_vip", cc.Prefab, (err, prefab) => {
            if (!err) {
                if (!canvas.getChildByName('CH_vip')) {
                    let node = cc.instantiate(prefab);
                    node.parent = canvas;

                }
            }
        });

        //关闭邮件
        if (this.node) {
            this.node.destroy()
            Global.dispatchEvent(EventId.CLOSE_HALL_MAIL)
        }
    },

    openVIPBtn: function () {
        let funcBtn = cc.find('funcBtn', this.node)
        funcBtn.off('click')
        funcBtn.on('click', this.onClickOpenVIP, this)
        funcBtn.getComponent(cc.Button).interactable = true
        // cc.find('label',funcBtn).getComponent(cc.Label).string = BTNSTRING.GO
        let btni18Scp = cc.find('label', funcBtn).getComponent("LanguageLabel")
        btni18Scp.id = 'btn_go'
        btni18Scp.updateLabel()

        cc.find('reward', this.node).active = false
    },

    goClaimBtn: function () {
        let funcBtn = cc.find('funcBtn', this.node)
        funcBtn.off('click')
        funcBtn.on('click', this.onClickGoClaim, this)
        funcBtn.getComponent(cc.Button).interactable = true
        // cc.find('label',funcBtn).getComponent(cc.Label).string = BTNSTRING.GOCLAIM
        let btni18Scp = cc.find('label', funcBtn).getComponent("LanguageLabel")
        btni18Scp.id = 'btn_goclaim'
        btni18Scp.updateLabel()

        cc.find('reward', this.node).active = false
    },

    onClickClose: function () {
        if (cc.isValid(this.node)) {
            Global.playComEff("ch_close");
            this.node.destroy()
        }
    },

    OnRcvNetMailAttach: function (msg) {
        // let self = this
        if (msg.code == 200) {
            this._msg = msg

            if (this._data.type == MailType.friends_mail || this._data.type == MailType.vip_mail) {
                this.deleteMail()
            } else {
                this.refrushMail()
            }

            // Global.dispatchEvent(EventId.REFUSH_CH_MAIL_STATE,self._data.id)
            //直接飞金币加钱
            // let itemList = msg.rewards
            // for(let i = 0; i < itemList.length; i++){
            //     if(itemList[i].id == 1){
            //         //金币
            //         cc.vv.UserManager.AddCoin(itemList[i].num,true)

            //         let fromNode = cc.find('spr_bg/spr_center/coin_bg/lbl_coin',this.node)
            //         let toNode = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
            //         let endCall = function () {
            //             self.onClickClose()
            //         }

            //         let rollData = {}
            //         rollData.lblCoin = toNode
            //         rollData.addCoin = itemList[i].num
            //         let completeCall = function(){
            //             if(endCall) endCall()
            //             //刷新金币
            //             if(cc.vv.gameData){
            //                 cc.vv.gameData.AddCoin(rollData.addCoin,true)
            //             }
            //         }

            //         Global.FlyCoin(fromNode,toNode,completeCall,rollData,true)
            //     }
            // }

            // if (msg.rewards.length > 1) {
            this.loadPopPre(msg.rewards)
            // }else {
            //     this.popreward(msg.rewards)
            // }
        }
    },

    loadPopPre: function (rd) {
        // let url = 'CashHero/prefab/mail/hall_mailReward'
        // let self = this
        // cc.loader.loadRes(url,cc.Prefab, (err, prefab) => {
        //     if (!err) {
        //         let node = cc.instantiate(prefab)
        //         node.parent = cc.find('Canvas')

        //         let endCall = function(){
        //             if(self._data.type == MailType.friends_mail){
        //                 self.goClaimBtn()
        //             } else if(self._data.type == MailType.vip_mail) {
        //                 self.openVIPBtn()
        //             }else {
        //                 self.node.destroy()
        //             }
        //         }
        //         node.getComponent('CH_MailReward').showRewards(rd,endCall)
        //     }
        //     else{
        //         console.log('未找到资源:'+url)
        //     }
        // });

        let self = this
        let pos = cc.find('reward', this.node).convertToWorldSpaceAR(cc.v2(0, 0))
        Global.RewardFly(rd, pos, () => {
            if (self._data.type == MailType.friends_mail) {
                self.goClaimBtn()
            } else if (self._data.type == MailType.vip_mail) {
                self.openVIPBtn()
            } else {
                self.node.destroy()
            }
        })

    },

    popreward: function (rd) {
        let url = 'CashHero/prefab/pop_reward'
        let self = this
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                let endCall = function () {
                    if (self._data.type == MailType.friends_mail) {
                        self.goClaimBtn()
                    } else if (self._data.type == MailType.vip_mail) {
                        self.openVIPBtn()
                    } else {
                        self.node.destroy()
                    }
                }
                node.getComponent('CH_popreward').showRewards(rd, endCall)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },


    // update (dt) {},
});
