/**
 * quest 登陆弹窗
 */
let QuestData = [
    { 'labelPos': [0, 682] },
    { 'labelPos': [0, 750] },
]


cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _inter: 1,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnplay = cc.find('btn_play', this.node)
        Global.btnClickEvent(btnplay, this.onClickPlay, this)
        let btnclose = cc.find('btn_close', this.node)
        Global.btnClickEvent(btnclose, this.onClickClose, this)
        this._timeLbl = cc.find('lbl_time', this.node)
        cc.vv.NetManager.registerMsg(MsgId.REQ_QUEST_INFO_LOGINPOP, this.OnRcvNetQuestInfo, this);
        Global.registerEvent("checkSubFinish", this.downloadingFinish, this)
        Global.registerEvent("enter_game", this.downloadingFinish, this)
        Global.playComEff("ch_notification");
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_QUEST_INFO_LOGINPOP, this.OnRcvNetQuestInfo, false, this);
        // cc.loader.releaseRes('CashHero/prefab/quest_loginpop',cc.Prefab)
    },

    start() {
        this.reqQuestInfo()
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUEST_POP)
    },

    _initQuest() {
        let questID = cc.vv.UserManager.getCurQuestId()
        let questLogo = cc.find('spr_logo', this.node)
        let logoPos = (questID > 1) ? QuestData[1].labelPos : QuestData[0].labelPos
        questLogo.setPosition(cc.v2(logoPos[0], logoPos[1]))
        this._nodeActive(questID > 1)
    },

    _nodeActive(flag) {
        let card = cc.find('spr_bg/card', this.node)
        let normal = cc.find('spr_bg/normal', this.node)
        card.active = !flag
        normal.active = flag
        let data = cc.vv.UserManager.getQuestInfo()
        let lblCoin = card.active ? cc.find('label', card) : cc.find('label', normal)
        lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(data.roundCfg.tasks[5].rewardnum)
    },

    showUI: function () {
        for (let i = 0; i < this._gameIds.length; i++) {
            let item = cc.find('spr_bg/game_content/quest_gameitem' + (i + 1), this.node)
            item.getComponent('CH_quest_gameitem').setInfo(this._gameIds[i], i, this._curGameIdx, item.scale + 0.3)
            item.zIndex = (i == this._curGameIdx) ? 2 : 0
            item.getComponent(cc.Button).interactable = false
        }
    },

    reqQuestInfo() {
        cc.vv.NetManager.send({ c: MsgId.REQ_QUEST_INFO_LOGINPOP })
    },

    OnRcvNetQuestInfo: function (msg) {
        if (msg.code == 200) {
            //
            cc.vv.UserManager.setQuestInfo(msg)
            this._initQuest()
            this.initData()
            this.showUI()
        }
    },

    initData: function () {
        this._gameIds = []
        let questInfo = cc.vv.UserManager.getQuestInfo()
        let taskList = questInfo.roundCfg.tasks
        let taskData = questInfo.data
        for (let i = 0; i < taskList.length; i++) {
            this._gameIds.push(taskList[i].gameid)
            if (taskData.taskid == taskList[i].taskid) {
                this._curGameIdx = i //获取当前玩到的游戏ID序号
            }
        }
    },

    downloadingFinish(data) {
        if (cc.isValid(this.node)) {
            let gameid = data.detail
            if (gameid == this._gameIds[this._curGameIdx]) {
                //直接进入游戏
                cc.vv.GameManager.setEnterOpation({ gameTask: 1 })
                cc.vv.GameManager.EnterGame(gameid)
            }
        }
    },

    onClickPlay: function () {
        Global.playComEff("ch_btn_click");
        //检测是否下载了
        let gameId = this._gameIds[this._curGameIdx]
        let bInnerGame = cc.vv.UserManager.isNoNeedDownGame(gameId) //是否是内置游戏
        if (cc.sys.isNative && Global.openUpdate && !bInnerGame) { // 手机平台需要检测更新
            cc.vv.SubGameUpdateNode.emit("check_subgame", gameId);
        } else {
            cc.vv.GameManager.setEnterOpation({ gameTask: 1 })
            cc.vv.GameManager.EnterGame(gameId)
        }
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUEST_PLAY)
        // let loadCall = function(err,scene){
        //     if(!err){
        //         let sceneCmp = scene.getComponentInChildren('CH_quest_loading')
        //         sceneCmp.setBackType(1)
        //     }
        // }
        // cc.vv.SceneMgr.enterScene(Global.SCENE_NAME.QUEST_LOADING,loadCall,Global.APP_ORIENTATION)
    },

    onClickClose: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUEST_CLOSE)
        Global.playComEff("ch_close");
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        this.node.destroy()
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1) {
            let questInfo = cc.vv.UserManager.getQuestInfo()
            if (questInfo) {
                this._inter = 0
                let endtime = questInfo.data.begintime * 1000 + questInfo.data.duration * 1000
                let nowtime = new Date().getTime();
                if (endtime - nowtime < 0) {
                    cc.vv.UserManager.setQuestInfo(null)
                    return
                }
                let str = Global.formatSec((endtime - nowtime) / 1000)
                this._timeLbl.getComponent(cc.Label).string = str
            }
        }
    },
});
