/**
 * 刮刮乐弹出
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

    },

    start() {
        let self = this
        let delayCall = function () {
            self.flyIn()
        }
        this.scheduleOnce(delayCall, 0.05)
    },

    setData: function (fromPos, msg, curMul) {
        this._fromPos = fromPos
        this._AddCoin = msg.addCoin;//抽到的:基础的*当前倍率
        this._otherCoin = msg.otherCoin//加成:vip和富豪庭
        this._basemul = curMul
    },

    showScrach: function () {
        //开始刮
        Global.playEff(Global.SOUNDS.sound_scratch)
        let maskNode = cc.find("card/mask", this.node)
        let aniCmp = maskNode.getComponent(sp.Skeleton)
        if (aniCmp) {
            aniCmp.setAnimation(0, "animation2", false)
            aniCmp.setCompleteListener(this.AniEndCall.bind(this))
        }
    },

    //显示刮刮的动画
    flyIn: function () {
        //设置显示倍率
        Global.setLabelString("spr_mul/val", this.node, "x" + this._basemul)
        //设置刮到的金币
        Global.setLabelString("card/coin", this.node, Global.FormatNumToComma(Math.floor(this._AddCoin / this._basemul)))

        if (this._fromPos) {//设置了飞入点
            let node_card = cc.find("card", this.node)
            if (node_card) {
                node_card.active = true
                node_card.scale = 0.44
                node_card.position = this.node.convertToNodeSpaceAR(this._fromPos)

                cc.tween(node_card)
                    .to(1, { scale: 1, position: cc.v2(0, 0) }, { easing: "quintOut" })
                    .call(() => {
                        //开始刮
                        this.showScrach()
                    })
                    .start()

                let bg = cc.find("bg", this.node)
                bg.opacity = 0
                cc.tween(bg)
                    .delay(0.5)
                    .to(0.5, { opacity: 155 })
                    .start()
            }
        }
        else {
            //没设置飞入点，不飞直接刮
            this.showScrach()
        }

    },

    AniEndCall: function (trackEntry, data2) {
        let name = trackEntry.animation ? trackEntry.animation.name : '';

        if (name == 'animation2') {
            this.showAddMultIn()
        }
    },

    showAddMultIn: function () {
        let self = this
        Global.playEff(Global.SOUNDS.sound_celebration);
        if (this._basemul <= 1) {
            self.doFlyBackAction()
            return
        }
        let obj = cc.find('spr_mul', this.node)
        if (obj) {
            obj.active = true
            obj.position = cc.v2(270, -105)
            // obj.getChildByName('lbl_val').getComponent(cc.Label).string = 'x' + this._curMultAdd
            let effNode = this.node.getChildByName('node_eff')
            effNode.active = false
            obj.opacity = 100
            obj.scale = 5
            obj.stopAllActions()
            cc.tween(obj)
                .to(0.2, { opacity: 255, scale: 1 }, { easing: 'quadIn' })
                .call(() => {
                    effNode.active = true
                    let spAni = effNode.getComponent(sp.Skeleton)
                    // spAni.timeScale = 2
                    spAni.setAnimation(0, 'animation', false)

                    let finishCall = function () {
                        self.doFlyBackAction()
                    }
                    //金币再次滚动
                    Global.doRoallNumEff(cc.find("card/coin", this.node), Math.floor(this._AddCoin / this._basemul), this._AddCoin + this._otherCoin, 1, finishCall, null, 0, true)
                })
                .start()
        }
    },

    //飞回去
    doFlyBackAction: function () {
        let self = this
        let flyEndCall = function () {
            if (cc.isValid(self.node)) {
                if (self._fromPos) {
                    let node_card = cc.find("card", self.node)
                    if (cc.isValid(node_card)) {
                        cc.tween(node_card)
                            .call(() => {
                                let bg = cc.find("bg", self.node)
                                bg.opacity = 155
                                cc.tween(bg)
                                    .to(0.5, { opacity: 0 })
                                    .start()
                            })
                            .to(1, { scale: 0.44, angle: 2, position: self.node.convertToNodeSpaceAR(self._fromPos) }, { easing: "quintOut" })
                            .call(() => {
                                self.node.destroy()
                            })
                            .start()

                        //立马盖上刮刮层
                        let mask = cc.find("mask", node_card)
                        mask.getComponent(sp.Skeleton).setAnimation(0, "animation2", false)
                        mask.getComponent(sp.Skeleton).paused = true

                        let obj = cc.find('spr_mul', self.node)
                        obj.active = false
                    }
                }
                else {
                    self.node.destroy()
                }


            }



        }

        //飞金币完，就退回去
        let rollData = {}
        // if(cc.vv.gameData){
        //     rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
        // }
        // else{
        //     rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
        // }

        rollData.addCoin = this._otherCoin + this._AddCoin
        //飞金币
        let srcObj = cc.find('card/coin', this.node)
        let endNode = cc.vv.gameData ? cc.find(Global.INGAME_COIN_NODE_PATH) : cc.find(Global.HALL_COIN_NODE_PATH);
        Global.FlyCoin(srcObj, endNode, flyEndCall, rollData, true)
    }

    // update (dt) {},
});
