let CurrRandomIdx = {}; //保存列中当前随机symbol在randomSymbols中的下标
let GetSymbolId = function (reelIdx) {
    reelIdx = reelIdx || 0;
    let randomSymbols = SlotsFacade.dm.getGameCfg().randomSymbols;
    if (reelIdx == 0 || reelIdx == 5) {
        randomSymbols = SlotsFacade.dm.getGameCfg().randomSkipWildSymbols;
    }
    if (!CurrRandomIdx.hasOwnProperty(reelIdx.toString())) {
        CurrRandomIdx[reelIdx.toString()] = Math.floor(Math.random() * randomSymbols.length);
    }
    let idx = (CurrRandomIdx[reelIdx.toString()] + 1) % randomSymbols.length;
    CurrRandomIdx[reelIdx.toString()] = idx;
    return randomSymbols[idx];
};

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        isEpic: false,   // 是否是respin中的Symbol
        finalIdx: 0,     // 最终下标 respin中用到
        mirror_node: null,  // symbol 镜像父节点
        bonusSymbolMirror: null, // bonus镜像
    },

    /**
     * @override
     */
    StartMove: function () {
        this._super();
        this._data = null;
    },

    /**
     * @override
     * @param {*} id 
     * @param {*} data 
     */
    ShowById: function (id, data) {
        this._super(id, data);
        this.showBonusSymbol(id, data);
        this.showColor();
        this.updateBonusMirror();
    },

    /**
     * 显示随机符号
     * @override
     */
    ShowRandomSymbol() {
        let cfg = cc.vv.gameData.getGameCfg()
        let randVal = GetSymbolId(this.GetSymbolReelIdx());
        let data = null;
        if (randVal == cfg.bonusId) {
            data = {};
            let seed = Math.random();
            if (seed < 0.25) {
                data.jp = 1;
            } else if (seed < 0.5) {
                data.jp = 2;
            } else {
                data.coin = Global.random(1, 10) * SlotsFacade.dm.GetTotalBet();
            }
        }
        this.ShowById(randVal, data);
    },

    /**
     * 去掉千后面的小数点
     * @param coin
     * @returns {*}
     * @private
     */
    _toShortNumb(coin) {
        if (coin > 1000 && coin % 1000 != 0) {
            coin = Math.floor(coin / 1000) * 1000;
        }
        return Global.convertNumToShort(coin);
    },

    showBonusSymbol(id, data) {
        if (!data) {
            return;
        }
        let cfg = SlotsFacade.dm.getGameCfg();
        if (id != cfg.bonusId) {
            return;
        }
        let itemCfg = cfg.symbol[cfg.bonusId];
        let node = cc.find(itemCfg.node, this.node);
        let coinNode = node.getChildByName("coin");
        let jp1 = node.getChildByName("jp_1");
        let jp2 = node.getChildByName("jp_2");
        if (data.coin) {
            let label = coinNode.getChildByName("label").getComponent(cc.Label);
            label.string = this._toShortNumb(data.coin);
            coinNode.active = true;
            jp1.active = false;
            jp2.active = false;
        } else if (data.jp == 1) {
            coinNode.active = false;
            jp1.active = true;
            jp2.active = false;
        } else if (data.jp == 2) {
            coinNode.active = false;
            jp1.active = false;
            jp2.active = true;
        } else {
            console.log("非法symbo数据", data);
        }
    },

    /**
     * @override
     */
    playStopAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani) {
            this._state = "stop";
            if (this._showNode) {
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
            this._showNode.active = true

            if (cfg.symbol[id].stop_ani.name != "") {
                this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    let stopAni = cfg.symbol[id].stop_ani.name;
                    let idleAni = cfg.symbol[id].idle_ani.name;
                    if (id == cfg.bonusId) {
                        let label = this._showNode.getChildByName("label").getComponent(cc.Label);
                        if (this._data.coin) {
                            label.node.active = true;
                            label.string = this._toShortNumb(this._data.coin);
                        } else {
                            label.node.active = false;
                            if (this._data.jp == 1) {
                                stopAni = "animation3_1";
                                idleAni = "animation3_2";
                            } else {
                                stopAni = "animation2_1";
                                idleAni = "animation2_2";
                            }
                        }
                    }
                    nodeSp.setAnimation(0, stopAni, false);
                    nodeSp.addAnimation(0, idleAni, true);
                }
            }
        }
    },

    /**
     * @override
     * @returns {boolean}
     */
    playTriggerAnimation() {
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg();
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani) {
            this._state = "trigger";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true
            if (cfg.symbol[id].trigger_ani.name != "") {
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton);
                if (nodeSp) {
                    let triggerAni = cfg.symbol[id].trigger_ani.name;
                    if (id == cfg.bonusId) {
                        let label = topShowNode.getChildByName("label").getComponent(cc.Label);
                        if (this._data.coin) {
                            label.node.active = true;
                            label.string = this._toShortNumb(this._data.coin);
                        } else {
                            label.node.active = false;
                            if (this._data.jp == 1) {
                                triggerAni = "animation3_3";
                            } else {
                                triggerAni = "animation2_3";
                            }
                        }
                    }
                    nodeSp.setAnimation(0, triggerAni, cfg.symbol[id].trigger_ani.loop);

                }
            }
        }
        return isPlay;
    },

    /**
     * 播放bonus idle 动画
     */
    playBonusIdleAni() {
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (id != cfg.bonusId) {
            return;
        }
        if (!this._data) {
            return;
        }
        this._state = "idle";
        if (this._showNode) {
            this._showNode.active = false
        }
        this._showNode = cc.find(cfg.symbol[id].win_node, this.node);
        this._showNode.active = true;
        isPlay = true
        let nodeSp = this._showNode.getComponent(sp.Skeleton);
        nodeSp.setAnimation(0, cfg.symbol[id].idle_ani.name, cfg.symbol[id].idle_ani.loop);
        let label = this._showNode.getChildByName("label").getComponent(cc.Label);
        let idleAni = cfg.symbol[id].idle_ani.name;
        if (this._data.coin) {
            label.node.active = true;
            label.string = this._toShortNumb(this._data.coin);
        } else {
            label.node.active = false;
            if (this._data.jp == 1) {
                idleAni = "animation3_2";
            } else {
                idleAni = "animation2_2";
            }
        }
        nodeSp.setAnimation(0, idleAni, true);
        return isPlay;
    },

    /**
     * 播放wild出现动画，在随机wild游戏中用到
     */
    playWildAppear() {
        if (this._id != 1) {
            return;
        }
        if (this._showNode) {
            this._showNode.active = false
        }
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg()
        this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
        this._showNode.active = true;
        let nodeSp = this._showNode.getComponent(sp.Skeleton)
        if (nodeSp) {
            nodeSp.setAnimation(0, "animation", false);
        }
    },

    showColor() {
        if (this.isEpic && this._showNode) {
            if (this.GetShowId() != SlotsFacade.dm.getGameCfg().bonusId) {
                this._showNode.color = new cc.Color().fromHEX("#3E3E3E");
            }
        }
    },

    hide() {
        if (this._showNode) {
            this._showNode.active = false;
        }
    },

    createBonusSymbolMirror() {
        if (!this.mirror_node) {
            return;
        }
        if (this.bonusSymbolMirror) {
            return;
        }
        this.bonusSymbolMirror = new cc.Node();
        this.bonusSymbolMirror.parent = this.mirror_node;
        let s2 = cc.instantiate(this.node.getChildByName("s2"));
        let s3 = cc.instantiate(this.node.getChildByName("s3"));
        s2.parent = this.bonusSymbolMirror;
        s3.parent = this.bonusSymbolMirror;
    },

    updateBonusMirror() {
        if (this.isEpic) {
            return;
        }
        if (!this.bonusSymbolMirror) {
            return;
        }
        if (this.canMirrorId()) {
            this.bonusSymbolMirror.active = true;
            let scatterNode = this.bonusSymbolMirror.getChildByName("s2");
            let bonusNode = this.bonusSymbolMirror.getChildByName("s3");
            let data = this._data;
            if (data && this._id == 3) {
                scatterNode.active = false;
                bonusNode.active = true;
                let coinNode = bonusNode.getChildByName("coin");
                let jp1 = bonusNode.getChildByName("jp_1");
                let jp2 = bonusNode.getChildByName("jp_2");
                if (data.coin) {
                    let label = coinNode.getChildByName("label").getComponent(cc.Label);
                    label.string = this._toShortNumb(data.coin);
                    coinNode.active = true;
                    jp1.active = false;
                    jp2.active = false;
                } else if (data.jp == 1) {
                    coinNode.active = false;
                    jp1.active = true;
                    jp2.active = false;
                } else if (data.jp == 2) {
                    coinNode.active = false;
                    jp1.active = false;
                    jp2.active = true;
                } else {
                    console.log("非法symbo数据", data);
                }
            } else if (this._id == 2) {
                scatterNode.active = true;
                bonusNode.active = false;
            }
        } else {
            this.bonusSymbolMirror.active = false;
        }
    },

    hideBonusMirror() {
        if (this.bonusSymbolMirror) {
            this.bonusSymbolMirror.active = false;
        }
    },

    canMirrorId() {
        return this._id == 2 || this._id == 3;
    },

    update(dt) {
        if (this.isEpic) {
            return;
        }
        if (!this.mirror_node || !this.mirror_node.active) {
            return;
        }
        if (!this.canMirrorId()) {
            return;
        }
        if (!this.bonusSymbolMirror) {
            this.createBonusSymbolMirror();
        }
        let pos = this.node.convertToWorldSpaceAR(cc.v2(0, 0));
        pos = this.mirror_node.convertToNodeSpaceAR(pos);
        this.bonusSymbolMirror.setPosition(pos);
    }
});
