/**
 * Cash hero hotupdate
 */
cc.Class({
    extends: require('hotupdate'),

    properties: {
        _bStart: null,
    },

    onLoad() { },

    start() { },

    startUpdate() {
        let newPackUrl
        let launchData = cc.vv.AppData.getLaunchAnnousment()
        if (launchData) {
            newPackUrl = launchData.packurl
        }
        this.initHotupdate(newPackUrl)
        this.checkForceAppUpdate();
    },

    // 热更不更新进度，由launch的假进度来显示
    SetUpdateProcess: function (val, nDownByte, nTotalByte) {
        if (cc.isValid(this.progressBar, true)) {
            this.progressBar.progress = val
        }
        if (cc.isValid(this.lblTips, true)) {
            let byteStr = cc.js.formatStr("(%sMB/%sMB)", ((nDownByte / 1024) / 1024).toFixed(2), ((nTotalByte / 1024) / 1024).toFixed(2))
            this.lblTips.string = Math.floor(val * 100) + "%" + byteStr
        }
    },

    showUpdateingUI: function () {
        let btn_res = cc.find('btn_res_vision', this.node.parent)
        if (cc.isValid(btn_res, true)) {
            let scp = btn_res.getComponent('btn_res_vision')
            if (scp) {
                scp.showNocticeBtn(true)
                scp.onOpenAnnousment()
            }
        }
    },

    startHotupdate: function () {
        this._bStart = true
        this._super()
        //先不显示
        //this.showUpdateingUI()
    },

    isStartHotupdate: function () {
        return this._bStart
    }

    // update (dt) {},
});
