//战斗文案配置
const TextConfigs = {
    start: [
        'The battle begins!',
        'Open fire!'
    ],
    normal_atk: [
        '{0} attacked {1}, causing {2}.',
        '{0} deal {1} damage to {2}.',
        '{0} give {2} damage to {1}.',
        '{0} go straight for the jugular, causing {2} damage to {1}.',
        '{0} sneakily attacked {1}, causing {2} damage.'
    ],
    miss: [
        '{0} tried to attack {1}, but missed.'
    ],
    skill_atk: [
        '{0} used {1} to cause {2} damage to {3}.'
    ],
    skill_all: [
        '{0} used {1} to attack all enemies and causing {2} damage.'
    ],
    defeate: [
        '{0} defeated {1}.',
        'It\'s a pity that {0} caused the death of {1}.',
        '{1} died at {0}.'
    ],
    win: [
        '<b><color=#ff5454>You win!</color></b>',
        '<b><color=#ff5454>Congratulations on your victory!</color></b>',
        '<b><color=#ff5454>What a great victory!</color></b>'
    ],
    fail: [
        'You lose.',
        'Keep up the good work, come again next time.',
        'Sorry to fail.'
    ]
}

cc.Class({
    extends: cc.Component,

    properties: {
        uiAtlas: cc.SpriteAtlas,
        _battlefield: null,
        _roles: null,
        _resMgr: null,
        _lstRecords: null,
        _recContent: null,
        _recItem: null,
        _records: null,
        _recordHeight: 0,
        _skip: false,
    },

    onLoad() {
        this._resMgr = this.node.getComponent("Pvp_ResMgr")
        this._battlefield = cc.find("battlefield", this.node)
        this._records = cc.find("records", this.node)
        this._lstRecords = cc.find("lst_records", this._records).getComponent(cc.ScrollView)
        this._recContent = cc.find("lst_records/view/content", this._records)
        this._recItem = cc.find("lst_records/view/item", this._records)

        Global.onClick("expand/btn_up", this._records, this.onClickUp, this)
        Global.onClick("expand/btn_down", this._records, this.onClickDown, this)
        Global.onClick("bottom/btn_skip", this.node, this.onClickSkip, this)
    },

    start() {
        let recordHeight = this._records.height
        let ratio = cc.winSize.height / cc.winSize.width
        let designRatio = 1920 / 1080
        if (ratio > designRatio) {
            recordHeight = recordHeight + recordHeight * Math.min((ratio / designRatio - 1) * 2, 0.5)
            recordHeight = Math.floor(recordHeight)
            this._records.height = recordHeight
        }
        this._recordHeight = recordHeight

        Global.playBgm(Global.SOUNDS.bgm_battle)
        Global.playCashEff("pvp/pk_start")
    },

    onDestroy() {
        Global.playBgm(Global.SOUNDS.bgm_herocard)
    },

    _initFormation(formation) {
        let resMgr = this.node.getComponent("Pvp_ResMgr")
        let battlefield = cc.find("battlefield", this.node)
        let roleNode1 = cc.find("role1", battlefield)
        let roleNode2 = cc.find("role2", battlefield)
        this._roles = []
        for (let i = 0; i < formation.length; i++) {
            let roleInfo = formation[i]
            let pos = roleInfo.pos
            let node = null
            let r = Math.floor((pos - 1) / 2)
            let dx = 0
            if (pos % 2 == 1) {
                node = cc.instantiate(roleNode1)
                node.position = cc.v2(-500, 410 - r * 200)
                dx = 60
            } else {
                node = cc.instantiate(roleNode2)
                node.position = cc.v2(500, 410 - r * 200)
                dx = -60
            }
            battlefield.addChild(node)
            node.active = true
            node.runAction(cc.moveBy(0.3, dx, 0).easing(cc.easeSineIn()))
            let role = node.getComponent("Pvp_Role")
            role.init(roleInfo, this, resMgr)
            this._roles[pos] = role
        }
    },

    getRoleByPos(pos) {
        return this._roles[pos]
    },

    getBattlefield() {
        return this._battlefield
    },

    async playRound(round) {
        let atker = this._roles[round.ak.pos]
        await atker.playRoundAttack(round)
        //回合能量
        for (let i = 0; i < round.mp.length; i++) {
            let role = this._roles[i + 1]
            if (role && role.isAlive()) {
                role.setMp(round.mp[i])
            }
        }
        this.addRoundRecords(round)
        await Global.awaitTime(this, 0.6)
    },

    async play(players, data, result) {
        this._skip = false
        this._logid = 0
        //玩家信息
        Global.setLabelString("top/lbl_atker", this.node, players[0].playername)
        Global.setLabelString("top/lbl_defer", this.node, players[1].playername)
        let lblRound = cc.find("top/lbl_round", this.node).getComponent(cc.Label)

        //初始化阵型
        this._initFormation(data.formation)

        //开始动画
        let readygo = cc.find("readygo", this.node)
        readygo.x = -1000
        cc.tween(readygo)
            .to(0.4, { x: 0 }, { easing: 'backOut' })
            .delay(1.2)
            .to(0.2, { x: 1000 })
            .start()

        //开始战斗
        await Global.awaitTime(this, 1.8)
        this.addStartRecord()
        for (let i = 0; i < data.rounds.length; i++) {
            if (this._skip) break
            lblRound.string = "" + (i + 1)
            await this.playRound(data.rounds[i])
        }
        this.addEndRecord(result.res)
        //显示结果
        await Global.awaitTime(this, 0.8)
        this.showResult(players, result, data)
    },

    addStartRecord() {
        let texts = TextConfigs.start
        this.addText(texts[Global.random(0, texts.length - 1)])
    },

    addEndRecord(res) {
        let texts = (res == 1) ? TextConfigs.win : TextConfigs.fail
        this.addText(texts[Global.random(0, texts.length - 1)])
    },

    addRoundRecords(round) {
        let atker = this._roles[round.ak.pos]
        let side = atker.getSide()
        let text = ""
        let atk_text = ""
        if (side == 1) {
            atk_text = '<color=#288bec>[' + atker.getName() + "]</color>"
        } else {
            atk_text = '<color=#a70c1a>[' + atker.getName() + "]</color>"
        }

        let def_text = ""
        let defeate_text = ""
        let dmg = 0
        for (let i = 0; i < round.rs.length; i++) {
            let rs = round.rs[i]
            let target = this._roles[rs.pos]
            dmg += rs.dmg
            def_text = def_text + '[' + target.getName() + "] "
            if (rs.hp <= 0) {
                defeate_text = defeate_text + '[' + target.getName() + "] "
            }
        }
        if (side == 1) {
            def_text = '<color=#a70c1a>' + def_text + "</color>"
        } else {
            def_text = '<color=#288bec>' + def_text + "</color>"
        }

        if (dmg <= 0) {
            let text_fmt = TextConfigs.miss[Global.random(0, TextConfigs.miss.length - 1)]
            text = Global.formatString(text_fmt, atk_text, def_text)
        } else {
            let dmg_text = '<color=#ff0000>[' + dmg + "]</color>"
            if (round.ak.at == "nor") {
                let text_fmt = TextConfigs.normal_atk[Global.random(0, TextConfigs.normal_atk.length - 1)]
                text = Global.formatString(text_fmt, atk_text, def_text, dmg_text)
            } else {
                let skill_text = '<color=#0ebe7a>[' + atker.getSkillName() + "]</color>"
                if (round.ak.at == "m5") {
                    let text_fmt = TextConfigs.skill_all[Global.random(0, TextConfigs.skill_all.length - 1)]
                    text = Global.formatString(text_fmt, atk_text, skill_text, dmg_text)
                } else {
                    let text_fmt = TextConfigs.skill_atk[Global.random(0, TextConfigs.skill_atk.length - 1)]
                    text = Global.formatString(text_fmt, atk_text, skill_text, dmg_text, def_text)
                }
            }
        }
        this.addText(text, side)

        if (defeate_text != "") {
            let text_fmt = TextConfigs.defeate[Global.random(0, TextConfigs.defeate.length - 1)]
            if (side == 1) {
                defeate_text = '<color=#a70c1a>' + defeate_text + "</color>"
            } else {
                defeate_text = '<color=#288bec>' + defeate_text + "</color>"
            }
            this.addText(Global.formatString(text_fmt, atk_text, defeate_text), side)
        }
    },

    addText(str, side) {
        let item = cc.instantiate(this._recItem)
        item.getChildByName("label").getComponent(cc.RichText).string = str
        let icon = item.getChildByName("icon")
        if (side == 1) {
            icon.getComponent(cc.Sprite).spriteFrame = this.uiAtlas.getSpriteFrame("icon_atk")
        } else if (side == 2) {
            icon.getComponent(cc.Sprite).spriteFrame = this.uiAtlas.getSpriteFrame("icon_def")
        } else {
            icon.active = false
        }
        this._logid += 1
        if (this._logid % 2 == 0) {
            item.getComponent(cc.Sprite).enabled = false
        }
        item.active = true

        this._recContent.addChild(item)
        this._lstRecords.scrollToBottom(0.1)
    },

    showResult(players, result, data) {
        let theNode = this.node
        let url = 'CashHero/prefab/pvp/pvp_result'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = theNode.getChildByName('pvp_result')
                if (!node) {
                    node = cc.instantiate(prefab)
                    node.parent = theNode
                }
                node.getComponent("Pvp_Result").init(this, players, result, data)
            }
        });
    },

    onClose() {
        this.node.runAction(cc.sequence(cc.fadeOut(0.25), cc.destroySelf()))
        Global.dispatchEvent("pvp_battle_close")
    },

    onClickUp() {
        Global.playComEff("ch_btn_click")
        this._currentH = 0
        this._expand = 1
        cc.find("expand/btn_up", this._records).active = false
        cc.find("expand/btn_down", this._records).active = true
    },

    onClickDown() {
        Global.playComEff("ch_btn_click")
        this._currentH = this._recordHeight
        this._expand = -1
        cc.find("expand/btn_up", this._records).active = true
        cc.find("expand/btn_down", this._records).active = false
    },

    onClickSkip() {
        Global.playComEff("ch_btn_click")
        this._skip = true
    },

    updateAlignment() {
        let children = this._records.children
        for (let i = 0; i < children.length; i++) {
            children[i].getComponent(cc.Widget).updateAlignment()
        }
        let view = this._lstRecords.node.getChildByName("view")
        view.getComponent(cc.Widget).updateAlignment()
        if (view.height < 0) view.height = 0
    },

    update(dt) {
        if (this._expand && this._expand != 0) {
            this._currentH += dt * this._recordHeight * this._expand * 2.5
            if (this._currentH >= this._recordHeight) {
                this._currentH = this._recordHeight
                this._expand = 0
            } else if (this._currentH <= 0) {
                this._currentH = 0
                this._expand = 0
            }
            this._records.height = this._currentH
            this.updateAlignment()
        }
    },
});
