/**
 * 红点系统
 */

cc.Class({
    extends: cc.Component,

    statics: {
        init: function () {
            //小红点
            cc.vv.NetManager.registerMsg(MsgId.PULL_RED_NOTICE, this.onRecvPullRedTips, this);

            this._localRedTip = { shop: 1 };
        },

        //小红点推送
        onRecvPullRedTips: function (msg) {
            if (msg.code == 200) {
                this._redTipsMsg = msg

                cc.vv.UserManager.setLevelGift(this._redTipsMsg.onetimeleft);

                //显示所有的红点
                Global.dispatchEvent(EventId.REFUSH_RED_TIPS)
            }
        },

        //获取小红点提示
        getRedTip: function (type) {
            if (this._redTipsMsg) {
                if (type == 1) return this._redTipsMsg.onlieAward; //刮刮乐
                else if (type == 2) return this._redTipsMsg.mail;  //邮件
                else if (type == 3) return this._redTipsMsg.questInfo && this._redTipsMsg.questInfo.daily; //每日任务
                else if (type == 4) return this._redTipsMsg.levelgift; //等级奖励
                else if (type == 5) return this._redTipsMsg.sign; //签到
                else if (type == 7) return this._redTipsMsg.share; //分享
                else if (type == 8) return this._redTipsMsg.friend; //好友-有好友送的金币可以领取
                else if (type == 9) return this._redTipsMsg.gametask; //quest
                else if (type == 10) return this._redTipsMsg.luckcard; //幸运抽卡
                else if (type == 12) return this._redTipsMsg.firstPayGift; //首冲礼包
                else if (type == 14) return this._redTipsMsg.maintask;    //主线任务
                else if (type == 17) return this._redTipsMsg.chat;//私聊
                else if (type == 18) return this._redTipsMsg.questInfo && this._redTipsMsg.questInfo.weekly; //每周任务
                else if (type == 19) return this._redTipsMsg.trailCard    //月卡试用
                else if (type == 20) return this._redTipsMsg.egg  //砸蛋日可以砸蛋
                else if (type == 21) return this._redTipsMsg.friendSeek //好友请求碎片
                else if (type == 22) return this._redTipsMsg.weekCard //周卡可以领取商城
                else if (type == 23) return this._redTipsMsg.monthCard //月卡可以领取商城
                else if (type == 24) return this._redTipsMsg.freecoin //商城免费领取金币
                else if (type == 25) return this._redTipsMsg.freediamond //商城免费领取钻石
                else if (type == 26) return this._redTipsMsg.charmCnt //收到互动送礼
                else if (type == 27) return this._redTipsMsg.palace//富豪庭有奖励可以领取

            }
            if (this._localRedTip) {
                if (type == 6) return this._localRedTip.shop;
                else if (type == 11) return this._localRedTip.bingo;
                // else if (type==13) return this._localRedTip.firstPayGift;
                else if (type == 101) return this._localRedTip.sliverHummer;//每天领取银锤子
                else if (type == 102) return this._localRedTip.hallPalace;    //富豪庭首次开启提示
            }
            return false;
        },

        //设置红点：显示
        setRedTip: function (type, val = 1) {
            if (this._redTipsMsg) {
                if (type == 2) this._redTipsMsg.mail = val
                if (type == 3) { this._redTipsMsg.questInfo = this._redTipsMsg.questInfo || {}; this._redTipsMsg.questInfo.daily = val; }
                if (type == 14) this._redTipsMsg.maintask = val
                if (type == 17) this._redTipsMsg.chat = val
                if (type == 18) { this._redTipsMsg.questInfo = this._redTipsMsg.questInfo || {}; this._redTipsMsg.questInfo.weekly = val; }
                if (type == 27) this._redTipsMsg.palace = val
            }
            if (this._localRedTip) {
                if (type == 11) this._localRedTip.bingo = val
                // if (type==13) this._localRedTip.firstPayGift = val
                if (type == 101) this._localRedTip.sliverHummer = val
                if (type == 102) this._localRedTip.hallPalace = val
            }

            Global.dispatchEvent(EventId.REDDOT_SHOW, type)
        },

        //清理小红点数据：隐藏
        clearRedTip: function (type) {
            if (this._redTipsMsg) {
                if (type == 1) this._redTipsMsg.onlieAward = 0;
                else if (type == 2) this._redTipsMsg.mail = 0;
                else if (type == 3) { this._redTipsMsg.questInfo = this._redTipsMsg.questInfo || {}; this._redTipsMsg.questInfo.daily = 0; }
                else if (type == 4) this._redTipsMsg.levelgift = 0;
                else if (type == 5) this._redTipsMsg.sign = 0;
                else if (type == 7) this._redTipsMsg.share = 0;
                else if (type == 8) this._redTipsMsg.friend = 0;
                else if (type == 9) this._redTipsMsg.gametask = 0;
                else if (type == 10) this._redTipsMsg.luckcard = 0;
                else if (type == 12) this._redTipsMsg.firstPayGift = 0;
                else if (type == 14) this._redTipsMsg.maintask = 0;
                else if (type == 17) this._redTipsMsg.chat = 0;
                else if (type == 18) { this._redTipsMsg.questInfo = this._redTipsMsg.questInfo || {}; this._redTipsMsg.questInfo.weekly = 0; }
                else if (type == 19) this._redTipsMsg.trailCard = 0
                else if (type == 20) this._redTipsMsg.egg = 0
                else if (type == 21) this._redTipsMsg.friendSeek = 0
                else if (type == 22) this._redTipsMsg.weekCard = 0
                else if (type == 23) this._redTipsMsg.monthCard = 0
                else if (type == 24) this._redTipsMsg.freecoin = 0
                else if (type == 25) this._redTipsMsg.freediamond = 0
                else if (type == 26) this._redTipsMsg.charmCnt = 0
                else if (type == 27) this._redTipsMsg.palace = 0
            }
            if (this._localRedTip) {
                if (type == 6) this._localRedTip.shop = 0;
                else if (type == 11) this._localRedTip.bingo = 0;
                // else if (type==13) this._localRedTip.firstPayGift = 0;
                else if (type == 101) this._localRedTip.sliverHummer = 0;
                else if (type == 102) this._localRedTip.hallPalace = 0
            }

            Global.dispatchEvent(EventId.REDDOT_HIDE, type)
        },

        //红点减少/增加一个数目
        changeRed: function (type, val) {
            if (this._redTipsMsg) {
                let key = null
                if (type == 8) {
                    key = "friend"
                }
                else if (type == 14) {
                    key = "maintask"
                }
                else if (type == 3) {
                    this._redTipsMsg.questInfo.daily += val
                    if (this._redTipsMsg.questInfo.daily < 0) {
                        this._redTipsMsg.questInfo.daily = 0
                    }
                }
                else if (type == 18) {
                    this._redTipsMsg.questInfo.weekly += val
                    if (this._redTipsMsg.questInfo.weekly < 0) {
                        this._redTipsMsg.questInfo.weekly = 0
                    }
                }
                else if (type == 27) {
                    key = "palace"
                }
                if (key != null) {
                    this._redTipsMsg[key] += val
                    if (this._redTipsMsg[key] < 0) {
                        this._redTipsMsg[key] = 0
                    }
                }


                Global.dispatchEvent(EventId.REDDOT_HIDE, type)
            }
        },
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    // start () {

    // },



    // update (dt) {},
});
