let CDKEYTYPE = {
    SUCCESS: 1,
    DEFEATED: 2,
};


cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        editBox: cc.EditBox,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_confirm = cc.find('confirmBtn', this.node)
        Global.btnClickEvent(btn_confirm, this.onClickConfirm, this)
        let btn_close = cc.find('closeBtn', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)
        this.editBox.node.on('editing-did-ended', this.editingEnded, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_CDKEY, this.onRcvCdkeyRewards, this)
    },

    start() { },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_CDKEY, this.onRcvCdkeyRewards, false, this)
    },

    _confirmEnable(flag) {
        cc.find('confirmBtn', this.node).getComponent(cc.Button).interactable = flag
    },

    onClickClose() {
        this.node.destroy()
    },

    onClickConfirm() {
        if (this.editBox.string) {
            this._confirmEnable(false)
            this.sendSeq()
        }
    },

    sendSeq() {
        let req = { c: MsgId.REQ_CDKEY }
        req.code = this.editBox.string
        cc.vv.NetManager.send(req)
        this.editBox.string = ''
    },

    editingEnded(editbox) {
        if (editbox.string) {
            let test = new RegExp("^[A-Za-z0-9]+$");//由英文和数字下划线组成
            let flag = test.test(editbox.string)
            if (!flag) {
                editbox.string = ''
                this.showFaildTips('Contains invalid characters')
            }
        }
    },

    showFaildTips: function (str) {
        let tip_bg = cc.find('tips', this.node)
        tip_bg.active = true
        let lbl_tip = cc.find("txt_tips", tip_bg)
        lbl_tip.getComponent(cc.Label).string = str
        lbl_tip.active = true
        lbl_tip.stopAllActions()
        cc.tween(tip_bg)
            .delay(5)
            .call(() => {
                tip_bg.active = false
            })
            .start()
    },

    onRcvCdkeyRewards(msg) {
        if (msg.code == 200) {
            let self = this

            let _cdkeyType = msg.spcode > 0 ? CDKEYTYPE.DEFEATED : CDKEYTYPE.SUCCESS
            if (_cdkeyType == CDKEYTYPE.SUCCESS) {
                //成功弹奖励
                let url = 'CashHero/prefab/cdkey/cdkeyPop'
                let callback = function (prefab) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    node.getComponent('cdkeyPop').setCdkeyType(_cdkeyType, msg)
                    self.node.destroy()
                }
                this._loadPrefab(url, callback)
            }
            else {
                //直接提示
                this._confirmEnable(true)
                this.showFaildTips('Invalid redemption code')
            }

        } else {
            this._confirmEnable(true)
        }
    },

    _loadPrefab: function (url, callbacks) {
        cc.vv.AssetMgr.loadResPrefab(url, (prefab) => {
            if (prefab) {
                callbacks(prefab)
            }
        })
    },

    // update (dt) {},
});
