cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    onLoad() {


        let btnClose = cc.find("bg/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        let btnPlay = cc.find("bg/btn_play", this.node)
        btnPlay.on('click', this.onClickPlay, this)

        let notify = Global.getLocal('bingo_notify')
        if (notify != "0") {
            cc.find("bg/notifyLayout/check_bg/check", this.node).active = true
        }

        let btnNotify = cc.find("bg/notifyLayout/check_bg", this.node)
        btnNotify.on('click', this.onClickNotify, this)

        if (cc.vv.gameData) cc.vv.gameData.PauseSlot()

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_PLAYTIP_POP, cc.vv.UserManager.getBingoFrom())
    },

    start() {
        Global.FixDesignScale_V(this.node)
    },

    onDestroy() {
        if (cc.vv.gameData) cc.vv.gameData.ResumeSlot()
    },

    showPlayTimes(times) {
        I18N.setI18nLabel(cc.find('bg/lbl_times', this.node), cc.vv.Language.bingo_playtip_times, times)
    },

    onClickPlay() {
        Global.playComEff("ch_btn_click")
        cc.loader.loadRes("CashHero/prefab/bingo/bingo_main", cc.Prefab, (err, prefab) => {
            let canvas = cc.find("Canvas")
            if (!err && !canvas.getChildByName("bingo_main")) {
                let node = cc.instantiate(prefab)
                node.name = "bingo_main"
                node.parent = canvas
                node.getComponent("Bingo_Main").showGameView(3)

                this.node.destroy()
            }
        })
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_PLAYTIP_PLAYGAME, cc.vv.UserManager.getBingoFrom())
    },

    onClickNotify() {
        Global.playComEff("ch_btn_click")
        let check = cc.find("bg/notifyLayout/check_bg/check", this.node)
        check.active = !check.active
        if (check.active) {
            Global.saveLocal('bingo_notify', "1")
        } else {
            Global.saveLocal('bingo_notify', "0")
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_PLAYTIP_NOTIFY, cc.vv.UserManager.getBingoFrom())
    },

    onClickClose() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_PLAYTIP_CLOSE, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_close")
        this.node.destroy()
    }
});
