/**
 * 购买复活卡
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _shoplist: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('ui/btn_close', this.node)
        btnClose.on("click", this.onClickClose, this)

        Global.registerEvent(EventId.PAY_RESULT, this.onEventPayResult, this)
    },

    start() {
        Global.playComEff("ch_popup");

        let final = cc.find("ui", this.node)
        Global.showAlertAction(final, true, 0.1, 1)

        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_BUY_POP)
    },

    init: function (data) {
        this._shoplist = data
        for (let i = 0; i < data.length; i++) {
            let t = data[i]
            let node = cc.find('ui/item' + (i + 1), this.node)
            node.on('click', () => {
                this.onClicBuy(t.id)
            })
            //数量
            cc.find('lbl_num', node).getComponent(cc.Label).string = t.count
            //金币
            cc.find('lbl_coin', node).getComponent(cc.Label).string = Global.FormatNumToComma(t.coin)
            //原价
            cc.find('lbl_old_price', node).getComponent(cc.Label).string = '$' + t.oamount
            //现价
            cc.find('lbl_price', node).getComponent(cc.Label).string = '$' + t.amount
            //benifist
            let btn = cc.find("btn_benifist", node)
            btn.getComponent('CH_Benifist_Btn').showBenifist(t.rewards, '幸运翻卡权益' + '|' + (i + 1))
        }
    },

    onClickClose: function () {
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_BUY_CLOSE)

        Global.playComEff("ch_btn_click");
        this.node.destroy()
    },

    onClicBuy: function (pid) {
        Global.playComEff("ch_btn_click");
        if (cc.sys.isBrowser) {
            cc.vv.NetManager.send({ c: 355, id: 95 })
            this.node.destroy()
        }
        else {
            cc.vv.PayMgr.reqPurchaseOrder(pid);
        }
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_BUY_CONFIRM)
    },

    onEventPayResult: function () {
        this.node.destroy()
    }

    // update (dt) {},
});
