/**
 * 处理好友碎片请求
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _friendId: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._giftContent = cc.find("content", this.node)
        this._giftContent.active = false

        // cc.vv.NetManager.registerMsg(MsgId.FRIEND_GIFT_REQUEST, this.onRcvSendGiftAll, this);
    },

    onDestroy() {
        // cc.vv.NetManager.unregisterMsg(MsgId.FRIEND_GIFT_REQUEST, this.onRcvSendGiftAll,false,this);
    },

    start() {
        this._showPopList()
    },

    setFriendId(datalist, uid) {
        this._friendId = uid
        this._giftList = datalist
        // this.sendRequestDetail()
    },

    // sendRequestDetail(){
    //     let req = { c: MsgId.FRIEND_GIFT_REQUEST };
    //     cc.vv.NetManager.send(req);
    // },

    async _showPopList() {
        for (let i = 0; i < this._giftList.length; i++) {
            let data = this._giftList[i]
            await this._showOnePop(data)
        }
        this.node.destroy()
    },
    _showOnePop: function (data) {
        let self = this
        return new Promise((resolve, reject) => {
            self._giftContent.active = true
            self._giftContent.scale = 0
            cc.tween(self._giftContent)
                .to(0.5, { scale: 1.5 }, { easing: "backOut" })
                .call(() => {
                    let endCall = function () {
                        resolve()
                    }
                    let cp = self._giftContent.getComponent("CH_FriendCardGiftChat").initGiftChat(data, endCall)
                })
                .start()
        })
    },

    // onRcvSendGiftAll(msg){
    //     if(msg.code == 200){
    //         this._giftList= []
    //         this._showPopList()
    //     }
    // },

    // update (dt) {},
});
