const { bigbank_des1 } = require("../../../../resources/CashHero/i18n/ar");

/**
 * 富豪厅
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('ui/btn_close', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)

        let btn_private = cc.find('ui/bottom/btn_private', this.node)
        Global.btnClickEvent(btn_private, this.onClickPrivate, this)

        let btn_gospin = cc.find('ui/mid/item1', this.node)
        Global.btnClickEvent(btn_gospin, this.onClickGoSpin, this)
        let btn_buypig = cc.find('ui/mid/item2', this.node)
        Global.btnClickEvent(btn_buypig, this.onClickBuypig, this)
        let btn_lvup = cc.find('ui/mid/item3', this.node)
        Global.btnClickEvent(btn_lvup, this.onClicklvup, this)
        Global.btnClickEvent(cc.find("btn", btn_lvup), this.onClicklvup, this)
        let btn_heropack = cc.find('ui/mid/item4', this.node)
        Global.btnClickEvent(btn_heropack, this.onClickHeropack, this)
        Global.btnClickEvent(cc.find("btn", btn_heropack), this.onClickHeropack, this)
        let btn_scratch = cc.find('ui/mid/item5', this.node)
        Global.btnClickEvent(btn_scratch, this.onClickScratch, this)
        let btn_freeticket = cc.find('ui/node_freeticket/btn_collect', this.node)
        Global.btnClickEvent(btn_freeticket, this.onClickFreeTicket, this)

        let btn_king = cc.find('ui/bottom/spr_king', this.node)
        Global.btnClickEvent(btn_king, this.onClickKingCrown, this)


        Global.registerEvent(EventId.HEROPALACE_CLOSE, this.OnEventHeropalaceClose, this)
        Global.registerEvent(EventId.HEROPALACE_REFUSH, this.OnEventHeropalaceRefush, this)
        Global.registerEvent(EventId.NEWGUIDE_PRO_UI, this.onEventCompleteNewGuide, this)


        cc.vv.NetManager.registerMsg(MsgId.REQ_HEROPALACE, this.onRcvHeropalaceInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_HEROPALACE_COLLECT, this.onRcvHeropalaceReward, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_HEROPALACE_TICKET, this.onRcvHeropalaceFreeTicket, this);

        Global.FixDesignScale_V(this.node)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HEROPALACE, this.onRcvHeropalaceInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HEROPALACE_COLLECT, this.onRcvHeropalaceReward, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HEROPALACE_TICKET, this.onRcvHeropalaceFreeTicket, false, this);
        Global.playComEff("ch_close");
    },

    start() {
        this.OnEventHeropalaceRefush()

        Global.playComEff("ch_popup");

        let light2 = cc.find("ui/spr_logo/guang_2", this.node)
        light2.active = true
        cc.tween(light2)
            .repeatForever(
                cc.tween()
                    .show()
                    .delay(0.3)
                    .hide()
                    .delay(0.3)
            )
            .start()

        //进入动画
        let logo = cc.find("ui/spr_logo", this.node)
        let mid = cc.find("ui/mid", this.node)
        let bottom = cc.find("ui/bottom", this.node)
        logo.getComponent(cc.Widget).updateAlignment()
        let org_logo = logo.y
        bottom.getComponent(cc.Widget).updateAlignment()
        let org_bottom = bottom.y
        logo.y = org_logo + 350
        cc.tween(logo)
            .to(0.4, { y: org_logo }, { easing: "quadOut" })
            .start()
        mid.scale = 0.1
        cc.tween(mid)
            .to(0.25, { scale: 1 }, { easing: "backOut" })
            .start()
        bottom.y = org_bottom - 350
        cc.tween(bottom)
            .to(0.4, { y: org_bottom }, { easing: "quadOut" })
            .start()

        let btn_close = cc.find('ui/btn_close', this.node)
        btn_close.opacity = 0
        cc.tween(btn_close)
            .delay(0.5)
            .to(0.5, { opacity: 255 })
            .start()
    },

    showUI: function () {
        this.showMidInfo()
        this.showBottomInfo()
        this.showFreeTicket()
    },

    //中部信息
    showMidInfo: function () {
        let self = this
        let bOpen = this._isOpenPalace()
        let mid = cc.find('ui/mid', this.node)
        for (let i = 0; i < 5; i++) {
            let item = cc.find('item' + (i + 1), mid)

            let locker = cc.find('locker', item)
            locker.active = !bOpen
            Global.shakeNodeR(locker)
            if (i == 2) {
                //level up
                let btn = cc.find("btn", item)
                btn.active = this._serdata.datalist.levelup.can && bOpen
                let cd = cc.find("spr_cd", item)
                let cdTime = this._serdata.datalist.levelup.restTime
                cd.active = cdTime > 0 && bOpen
                if (cd.active) {
                    cc.find("lbl", cd).getComponent("ReTimer").setReTimer(cdTime, 1, () => {
                        self.OnEventHeropalaceRefush()
                    })
                }
            }
            else if (i == 3) {
                //hero pack
                let btn = cc.find("btn", item)
                btn.active = this._serdata.datalist.herocard.can && bOpen
                let cd = cc.find("spr_cd", item)
                let cdTime = this._serdata.datalist.herocard.restTime
                cd.active = cdTime > 0 && bOpen
                if (cd.active) {
                    cc.find("lbl", cd).getComponent("ReTimer").setReTimer(cdTime, 1, () => {
                        self.OnEventHeropalaceRefush()
                    })
                }
            }



        }


    },
    //显示底部点数信息
    showBottomInfo: function () {
        let perVal = this._serdata.upoints / this._serdata.max
        let bottom = cc.find('ui/bottom', this.node)
        cc.find('pro', bottom).getComponent(cc.ProgressBar).progress = perVal
        let showVal = this._serdata.upoints > this._serdata.max ? this._serdata.max : this._serdata.upoints
        cc.find('lbl_val', bottom).getComponent(cc.Label).string = cc.js.formatStr('%s/%s', showVal, this._serdata.max)
        let nRemindDay = this._serdata.timeout
        let bOpen = this._isOpenPalace()
        let unOpenNode = cc.find('title_unopen', bottom)
        let openNode = cc.find('title_open', bottom)
        unOpenNode.active = !bOpen
        openNode.active = bOpen
        let timeLbl = unOpenNode
        let showTip = cc.js.formatStr('Earn %s Points to open palace 7 days!', this._serdata.max)
        if (bOpen) {
            showTip = cc.js.formatStr('%s days left', nRemindDay)
            timeLbl = cc.find("lbl", openNode)
        }

        timeLbl.getComponent(cc.Label).string = showTip

        Global.showSpriteGray(cc.find("spr_king/icon", bottom), !bOpen)

    },

    //显示免费券
    showFreeTicket: function () {
        let node = cc.find('ui/node_freeticket', this.node)
        let bShow = false
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.PALACE_FREETICKET)
        if (bOpen) {
            if (this._serdata) {
                bShow = this._serdata.trial
            }
        }

        node.active = bShow

        if (bShow) {
            //显示引导
            let endCall = function () {
                Global.dispatchEvent(EventId.REFUSH_RED_TIPS)
            }
            cc.vv.NewGuide.ShowGuide(95, endCall)
        }
    },

    //领取免费体验券
    onClickFreeTicket: function () {
        Global.delayInteractable(cc.find('ui/node_freeticket/btn_collect', this.node))
        cc.vv.NetManager.send({ c: MsgId.REQ_HEROPALACE_TICKET })
    },

    onClickClose: function () {
        this.node.destroy()
    },

    //点击权益按钮
    onClickPrivate: function () {
        Global.playComEff("ch_collect");
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_EARNINGPT, this._isOpenPalace() ? 1 : -1)

        let url = 'CashHero/prefab/heropalace/hero_palace_rule'
        this._loadPrefab(url, (prefab) => {
            let par = cc.find('Canvas')
            if (!cc.find('hero_palace_rule', par)) {
                let node = cc.instantiate(prefab)
                node.parent = par
                node.getComponent("CH_Heropalace_rule").showTab(1)
            }
        })


    },

    onClickKingCrown: function () {
        Global.playComEff("ch_collect");
        let url = 'CashHero/prefab/heropalace/hero_palace_rule'
        this._loadPrefab(url, (prefab) => {
            let par = cc.find('Canvas')
            if (!cc.find('hero_palace_rule', par)) {
                let node = cc.instantiate(prefab)
                node.parent = par
                node.getComponent("CH_Heropalace_rule").showTab(2)
            }
        })
    },

    //去高倍场
    onClickGoSpin: function (event) {
        Global.playComEff("ch_collect");
        let tarNode = event.node
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_GOSPIN)
        let bOpen = this._isOpenPalace()
        if (bOpen) {
            //跳往大厅
            this.onClickClose()
        }
        else {
            //未解锁提示
            this._showUnlockTip(tarNode, "High limit mode is available for all slots games. Win better prizes with higher bets!")
        }


    },

    //升级加速
    onClicklvup: function (event) {
        Global.playComEff("ch_collect");
        let tarNode = event.node
        let bOpen = this._isOpenPalace()
        if (bOpen) {
            if (this._serdata && this._serdata.datalist.levelup.can) {

                let req = { c: MsgId.REQ_HEROPALACE_COLLECT }
                req.rtype = 1
                cc.vv.NetManager.send(req)
                cc.vv.RedSys.changeRed(27, -1)
            }
            else {
                cc.vv.FloatTip.show("Today's reward has been received!");
            }

        }
        else {
            //未解锁提示
            this._showUnlockTip(tarNode, "Get 1 hour double EXP every day. you can level up faster then before!")
        }


        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_DOUBLEEXP)
    },

    //购买金猪
    onClickBuypig: function (event) {
        Global.playComEff("ch_collect");
        let tarNode = event.node
        let bOpen = this._isOpenPalace()
        if (bOpen) {
            this._loadPrefab("hall_prefab/MoneyBankUI", (prefab) => {
                let canvas = cc.find("Canvas");
                if (canvas.isValid && !cc.find('MoneyBankUI', canvas)) {
                    let obj = cc.instantiate(prefab)
                    obj.parent = canvas

                }
            })

        }
        else {
            //未解锁提示
            this._showUnlockTip(tarNode, "Extra 200% coins for each purchase!")
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_BUYPIG)

    },

    //英雄礼包
    onClickHeropack: function (event) {
        Global.playComEff("ch_collect");
        let tarNode = event.node
        let bOpen = this._isOpenPalace()
        if (bOpen) {
            if (this._serdata && this._serdata.datalist.herocard.can) {
                let req = { c: MsgId.REQ_HEROPALACE_COLLECT }
                req.rtype = 2
                cc.vv.NetManager.send(req)
                cc.vv.RedSys.changeRed(27, -1)
            }
            else {
                cc.vv.FloatTip.show("Today's reward has been received!");
            }

        }
        else {
            this._showUnlockTip(tarNode, "Receive a hero pack every day!")
        }


        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_HEROPACK)
    },

    //刮刮乐
    onClickScratch: function (event) {
        Global.playComEff("ch_collect");
        let tarNode = event.node


        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_ONLINEREWARD)
        let bOpen = this._isOpenPalace()
        if (bOpen) {
            // 切换到bonus
            Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
            Global.dispatchEvent("BONUS_TAB", "Login")
            this.node.destroy()
        }
        else {
            this._showUnlockTip(tarNode, "Get 50% more coins from scratch every time!")
        }
    },



    _showUnlockTip(tarNode, tips) {
        let node_tip = cc.find("ui/mid/unlock_tip", this.node)
        node_tip.active = true
        node_tip.position = node_tip.parent.convertToNodeSpaceAR(cc.find("spr_name", tarNode).convertToWorldSpaceAR(cc.v2(0, 0)))
        node_tip.stopAllActions()
        node_tip.opacity = 0
        cc.tween(node_tip)
            .to(0.2, { opacity: 255 })
            .delay(3)
            .to(0.3, { opacity: 0 })
            .start()
        Global.setLabelString("lbl", node_tip, tips)

    },

    _loadPrefab: function (url, callbacks) {
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                callbacks(prefab)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },



    onRcvHeropalaceInfo: function (msg) {
        if (msg.code == 200) {
            this._serdata = msg
            this.showUI()
        }
    },

    onRcvHeropalaceReward: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode) {
                return
            }

            //刷新显示
            if (msg.rtype == 1) {
                //刷新在线奖励的领取状态
                this._serdata.datalist.levelup.can = 0
                this._serdata.datalist.levelup.restTime = msg.restTime
            }
            else if (msg.rtype == 2) {
                //刷新英雄礼包的领取状态
                this._serdata.datalist.herocard.can = 0
                this._serdata.datalist.herocard.restTime = msg.restTime
            }
            this.showMidInfo()

            //展示奖励
            this._rewarddatas = msg.rewards
            let url = 'CashHero/prefab/pop_reward'
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let par = cc.find('Canvas')
                    if (!cc.find('pop_reward', par)) {
                        let node = cc.instantiate(prefab)
                        node.parent = par
                        let endCall = function () {

                        }
                        node.getComponent('CH_popreward').showRewards(this._rewarddatas, endCall)
                    }

                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        }
    },

    onRcvHeropalaceFreeTicket: function (msg) {
        if (msg.code == 200) {
            this._serdata = msg
            this.showUI()
            cc.vv.RedSys.setRedTip(27, 2)
            let callBack = () => {
                cc.vv.NewGuide.ShowGuide(96)
            }
            this._loadFreeTicket(callBack)
        }
    },

    _loadFreeTicket(callBack) {
        let url = 'CashHero/prefab/heropalace/hero_palace_pop'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let par = cc.find('Canvas')
                if (!cc.find('hero_palace_pop', par)) {
                    let node = cc.instantiate(prefab)
                    node.parent = par
                    let endCall = function () {
                        callBack()
                    }
                    node.getComponent('CH_Heropalace_pop').setCallBack(endCall)
                }

            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    _isOpenPalace: function () {
        return this._serdata.timeout
    },

    OnEventHeropalaceClose: function () {
        this.node.destroy()
    },

    OnEventHeropalaceRefush: function () {
        cc.vv.NetManager.sendAndCache({ c: MsgId.REQ_HEROPALACE })
    },

    onEventCompleteNewGuide: function (data) {
        let val = data.detail
        if (val == 961) {
            let self = this
            cc.vv.NewGuide.SetGuideTempData(96)
            //模拟点击某个游戏，打开分档押注界面
            Global.dispatchEvent(EventId.ONCLICK_GAME, Global.DEFAULT_GAMEID)

            cc.tween(this.node)
                .delay(0.5)
                .call(() => {
                    self.node.destroy()
                })
                .start()
        }
    }

    // update (dt) {},
});
