cc.Class({
    extends: cc.Component,

    properties: {
        _qiePin: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._qiePin = cc.find("sjt_qp", this.node)
        this._qiePin.active = false
    },

    onDestroy() {},

    start() {},

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    showQiePinReady() {
        //
        // Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.super_active)
        // let qiePinSp = this._qiePin.getComponent(sp.Skeleton)
        // qiePinSp.setAnimation(0,"animation1",false)
        // qiePinSp.addAnimation(0,"animation2",true)
    },

    showQiePin() {
        return new Promise(async (sucess, failed) => {
            let nvshen = cc.find("Canvas/safe_node/logo/nvshen");
            this._qiePin.active = true
            nvshen.active = false;
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition)
            let qiePinSp = this._qiePin.getComponent(sp.Skeleton)
            qiePinSp.setAnimation(0, "animation", false)
            qiePinSp.setCompleteListener(() => {
                qiePinSp.setCompleteListener(null)
                this._qiePin.active = false
                nvshen.active = true;
            })
            await this.awaitTime(0.8);
            sucess()
        })
    },

    // update (dt) {},
});
