
cc.Class({
    extends: cc.Component,

    statics: {

        init() {
            cc.vv.NetManager.registerMsg(MsgId.PULL_GIFT_INFO, this.onRcvPullGiftInfo, this)
        },

        onRcvPullGiftInfo(msg) {

            if (cc.vv.gameData) {

            } else {

            }

            cc.loader.loadRes("CashHero/prefab/gift/gift_play", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let parObj = cc.find("Canvas");
                    let node = cc.find('gift_play', parObj)
                    if (!node) {
                        node = cc.instantiate(prefab);
                        node.parent = parObj;
                        node.getComponent("gift_play").setInfo(msg.receive, msg.send, msg.info);
                    } else {
                        node.getComponent("gift_play").addInfo(msg.receive, msg.send, msg.info);
                    }
                }
            })
        },

    },
});
