//好友个人信息查看
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _otherUid: null,//查看的好友id
        _isFriend: null,//是否是好友
        _canSend: null,//已经是好友 能否赠送礼物 0 可以 1 已赠送过
        _endCall: null,//关闭界面回调函数
    },


    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_DELETE_FRIENDS, this.onRcvRemovedFriends, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_ADD_FRIENDS, this.onRcvAddFriends, this);
        cc.vv.NetManager.registerMsg(MsgId.FRIEND_PRESENT, this.onRcvSendGift, this);

        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvFriendInfo, this);

        //移除好友btn
        Global.btnClickEvent(cc.find("bg/btn_remove", this.node), () => {
            Global.playComEff("ch_btn_click");
            let req = { c: MsgId.REQ_DELETE_FRIENDS };
            let frienduids = []
            frienduids[0] = this._otherUid
            req.frienduids = frienduids;
            cc.vv.NetManager.send(req);
        }, this)
        //添加好友btn
        Global.btnClickEvent(cc.find("bg/btn_addFriend", this.node), () => {
            Global.playComEff("ch_btn_click");
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_ADDFRIENDS_SEARCH_ADD)
            let req = { c: MsgId.REQ_ADD_FRIENDS };
            req.frienduid = this._otherUid;
            req.act = 0;
            cc.vv.NetManager.send(req);
        }, this)

        // //赠送礼物好友btn
        // Global.btnClickEvent(cc.find("bg/btn_sendGift", this.node), () => {
        //     Global.playComEff("ch_btn_click");
        //     let req = { c: MsgId.FRIEND_PRESENT };
        //     req.frienduid = this._otherUid;
        //     cc.vv.NetManager.send(req);
        // }, this)

        Global.btnClickEvent(cc.find("bg/btnClose", this.node), () => {
            Global.playComEff("ch_btn_click");
            this.node.destroy()
        }, this)

        Global.playComEff("ch_popup_l2");
    },

    start() {
        this.hideAllBtn()

        if (this._isFriend) {
            cc.find("bg/btn_remove", this.node).active = true
            // if (this._canSend == 0) {
            //     cc.find("bg/btn_sendGift", this.node).active = false
            // }

        } else {
            cc.find("bg/btn_addFriend", this.node).active = true

        }

        if (this._personInfo) {
            this.onRcvFriendInfo(this._personInfo)
        } else {
            this.sendGetPersionnalInfo()
        }
    },

    sendGetPersionnalInfo() {
        if (this._otherUid) {
            let req = { c: MsgId.PERSIONAL_INFO };
            req.otheruid = this._otherUid
            cc.vv.NetManager.sendAndCache(req);
        }
    },

    init(otherUid, isFriend, canSend, endcall, personInfo) {
        if (this._otherUid) return;
        this._otherUid = otherUid
        this._isFriend = isFriend
        this._canSend = canSend
        this._endCall = endcall

        if (this._otherUid) {
            this._personInfo = personInfo ? personInfo : null
            // if(personInfo){
            //     this.onRcvFriendInfo(personInfo)
            // }
            // else{
            //     let req = { c: MsgId.PERSIONAL_INFO };
            //     req.otheruid = this._otherUid
            //     cc.vv.NetManager.send(req);
            // }
        }

    },

    //隐藏所有可操作按钮 （用于排行榜里查看用户个人信息）
    hideAllBtn() {
        if (cc.isValid(this.node)) {
            cc.find("bg/btn_addFriend", this.node).active = false
            cc.find("bg/btn_remove", this.node).active = false
            // cc.find("bg/btn_sendGift", this.node).active = false
        } else {
            return
        }
    },

    onEnable() {
        Global.showAlertAction(this.node, true, 0.1, 1.0, null);

    },

    onDestroy() {
        if (this._endCall) {
            this._endCall()
        }

        Global.showAlertAction(this.node, false, 1.0, 0, null);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_DELETE_FRIENDS, this.onRcvRemovedFriends);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_ADD_FRIENDS, this.onRcvAddFriends);
        cc.vv.NetManager.unregisterMsg(MsgId.FRIEND_PRESENT, this.onRcvSendGift);

        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvFriendInfo);
    },
    //赠送好友礼物
    onRcvSendGift(msg) {
        if (msg.code == 200 && !msg.spcode) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_send_gift_success);
            // cc.vv.FloatTip.show('Gift send success!!')
            this.hide()
            if (this._endCall) {
                this.scheduleOnce(() => {
                    this._endCall()
                }, 0.3)
            }
        } else {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_send_gift_fail);
            // cc.vv.FloatTip.show('Gift send fail!!')
        }

    },

    //添加好友
    onRcvAddFriends(msg) {
        let str = ''
        if (msg.code == 200 && !msg.spcode) {
            str = 'Friend add success!!'
            // cc.vv.FloatTip.show('Friend add success!!')
            this.hide()
            if (this._endCall) {
                this.scheduleOnce(() => {
                    this._endCall()
                }, 0.3)
            }
        } else {
            str = 'Friend add fail!!'
            // cc.vv.FloatTip.show('Friend add fail!!')
            this.hide()
        }
        this.showSimpleTip(str)
    },
    //删除好友
    onRcvRemovedFriends(msg) {
        let str = ''
        if (msg.code == 200 && !msg.spcode) {
            // cc.vv.FloatTip.show('Friend deleted success!!')
            str = 'Friend deleted success!!'
            this.hide()
            if (this._endCall) {
                this.scheduleOnce(() => {
                    this._endCall()
                }, 0.3)
            }
        } else {
            str = 'Friend deleted fail!!'
            // cc.vv.FloatTip.show('Friend deleted fail!!')
            this.hide()
        }
        this.showSimpleTip(str)
    },

    showSimpleTip(str) {
        let sureCall = function () {

        }
        cc.vv.AlertView.showSimple(str, sureCall)
    },

    //获取单个好友信息
    onRcvFriendInfo(msg) {
        if (msg.code == 200) {
            if (msg.playerInfo.uid == cc.vv.UserManager.uid) {
                this.hideAllBtn()
            }
            if (!cc.isValid(this.node)) {
                return
            }
            let playerInfo = msg.playerInfo
            //设置头像
            let headNode = cc.find("bg/upNode/node_head", this.node)
            if (headNode) {
                var userHeadScript = cc.find("bg/upNode/node_head", this.node).getComponent('UserHead')
                userHeadScript.setHead(msg.playerInfo.uid, msg.playerInfo.usericon)
            } else {
                if (this.node) {
                    this.node.destroy()
                }
            }

            // var userHeadScript = cc.find("bg/upNode/node_head", this.node).getComponent('UserHead')
            // userHeadScript.setHead(msg.playerInfo.uid, msg.playerInfo.usericon)

            this.changeNodeLab(cc.find("bg/upNode/nameLab", this.node), playerInfo.playername)
            this.changeNodeLab(cc.find("bg/upNode/idLab", this.node), "ID:" + playerInfo.uid)

            this.changeNodeLab(cc.find("bg/upNode/lv/lab", this.node), playerInfo.level)
            this.changeNodeLab(cc.find("bg/upNode/coin/lab", this.node), Global.FormatNumToComma(playerInfo.coin))

            // this.changeNodeLab(cc.find("bg/downNode/lab1", this.node), Global.FormatNumToComma(playerInfo.ranktotalbet))
            // this.changeNodeLab(cc.find("bg/downNode/lab2", this.node), Global.FormatNumToComma(playerInfo.ranktotalwin))
            // this.changeNodeLab(cc.find("bg/downNode/lab3", this.node), Global.FormatNumToComma(playerInfo.rankwin))
        }
    },

    hide() {
        this._otherUid = null;
        // this.node.active = false;
        if (cc.isValid(this.node)) {
            this.node.destroy()
        }
    },

    onBtnCloseClicked(event) {
        Global.playComEff("ch_close");
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_ADDFRIENDS_SEARCH_CLOSE)
        this.hide();
    },

    //切换节点的 lab
    changeNodeLab(node, str) {
        if (node == null || node.getComponent(cc.Label) == null) {
            return;
        }
        node.getComponent(cc.Label).string = str;
    },
});
