cc.Class({
    extends: cc.Component,

    properties: {
    },

    onLoad() {
        Global.FixDesignScale_V(this.node)

        let guang = cc.find("guang", this.node)
        guang.scale = 0.2
        guang.runAction(cc.scaleTo(0.2, 1))
        guang.runAction(cc.rotateBy(2.5, 540))
        this.node.runAction(cc.sequence(cc.delayTime(2), cc.fadeOut(0.3), cc.destroySelf()))

        let hummer = cc.find("hummer", this.node)
        hummer.scale = 0
        hummer.runAction(cc.sequence(cc.delayTime(0.2), cc.scaleTo(0.3, 1), cc.delayTime(1.5), cc.scaleTo(0.3, 0)))
        let zi = cc.find("zi", this.node)
        zi.opacity = 0
        zi.runAction(cc.sequence(cc.delayTime(0.4), cc.fadeIn(0.2)))
    },

    setType(stype, cnt = 1, endCall, isFade = true) {
        let hummer = cc.find("hummer", this.node)
        let zi = cc.find("zi", this.node)
        cc.find("silver", hummer).active = (stype == 1)
        cc.find("gold", hummer).active = (stype == 2)
        // zi.getComponent(cc.Label).string = (stype==1)?"+"+cnt+" SILVER HUMMER":"+"+cnt+" GOLD HUMMER"
        let _str = (stype == 1) ? cc.vv.Language['hummer_silver'] : cc.vv.Language['hummer_gold']
        I18N.setI18nLabel(zi, _str, cnt)
        zi.color = (stype == 1) ? (new cc.Color(83, 223, 246)) : (new cc.Color(247, 255, 87))
        cc.find('mask', this.node).active = isFade

        this._endCall = endCall
    },

    onDestroy() {
        if (cc.isValid(this._endCall)) {
            this._endCall()
        }
    },
});
