/**
 * 卡牌：碎片掉落
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _bCanAction: false,
        _canCloseAction: false,
        _cardInfo: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

        this._nodeSpine = cc.find('spine', this.node)
        this._nodeFragement = cc.find('card_fragement', this.node)
        this._nodeClick = cc.find('node_click', this.node)
        Global.btnClickEvent(this._nodeClick, this.onClickOpen, this);

        let btngo = cc.find('card_fragement/node_up/btn_go', this.node)
        Global.btnClickEvent(btngo, this.onClickGo, this);

        let skipBtn = cc.find('skipBtn', this.node)
        Global.btnClickEvent(skipBtn, this.onClickSkip, this);

        this._endHeroID = 0

    },

    start() {
        Global.FixDesignScale_V(this.node)

        //如果有popreward 则遮布隐藏 
        let canvas = cc.find('Canvas')
        let bPop = cc.find('pop_reward', canvas)
        cc.find('lay_bg', this.node).active = !bPop

        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()

            //多个卡牌  单个卡牌
            let self = this
            let nextCall = function () {
                if (cc.find('skipBtn', self.node).active) {
                    self.onClickSkip()
                } else {
                    self.onClickOpen()
                }
            }
            cc.vv.gameData.checkAutoPlay(this.node, nextCall)
        }
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },

    /**
     * 
     * @param {*} cardid 
     * @param {*} num 
     * @param {*} endCall 界面关闭后的回调
     * @param {*} bCheckUnlock 是否检查可以解锁
     * @param {*} packType 是 1卡包 还是 2碎片
     */
    showOpen: function (cardid, num, endCall = null, bCheckUnlock = true, packType) {
        this._cardInfo = cc.vv.HerocardManager.getCardInfo(cardid)
        this._closeEndCall = endCall
        this._bCheckUnlock = bCheckUnlock
        this._cardId = cardid

        this.setNum(num)
        if (this._endHeroID > 0) {
            if (cardid == this._endHeroID) {
                this.fadeSkip(false)
            }
        }
        this.showCardFragement(cardid, num)
        if (bCheckUnlock) {
            this.showUnlockAddStarUI(cardid)
        }

        if (packType == 1) {
            this._nodeSpine.active = true
            let spineCMP = this._nodeSpine.getComponent(sp.Skeleton)
            spineCMP.timeScale = Global.ANIM_TIMESCALE_X2
            spineCMP.setAnimation(0, 'animation1_1', false)
            spineCMP.addAnimation(0, 'animation2_1', true)
            Global.playCashEff("herocard/hero_fly");
            this._nodeClick.active = false
            spineCMP.setCompleteListener((track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation1_1") {
                    this._nodeClick.active = true
                } else if (name === "animation3_1") {

                }
            });
        }
        else {
            //碎片展示
            this._nodeClick.active = true
            this._nodeSpine.active = false
            this.showResult()
        }

    },

    showCardFragement: function (cardid, num) {
        let cardInfo = cc.vv.HerocardManager.getCardInfo(cardid)
        let cfg = cardInfo.cfg
        if (cfg) {
            let lblName = cc.find('card_fragement/lbl_name', this.node)
            // lblName.getComponent(cc.Label).string = cfg.name
            I18N.setI18nLabel(lblName, cc.vv.Language["cardname_" + cfg.cardid])
            // let cardbg = cc.find("card_fragement/icon_bg",this.node)
            // cc.vv.HerocardManager.loadCampChipBg2(cardbg,cfg.campid)
            let lblAdd = cc.find('card_fragement/lbl_add', this.node)
            lblAdd.getComponent(cc.Label).string = 'x' + num
            let cardicon = cc.find("card_fragement/icon", this.node)
            cc.vv.HerocardManager.loadFragmentHero(cardicon, cardid)
            let chipNum = cc.find('card_fragement/pro/lbl_num', this.node)
            let proVal = 0
            if (cardInfo.lv <= 0) {
                proVal = cardInfo.chips / cfg.unlock_chips
                chipNum.getComponent(cc.Label).string = cardInfo.chips + "/" + cfg.unlock_chips
            } else {
                let starCfg = cc.vv.HerocardManager.getCardStarCfg(cardInfo.cardid, cardInfo.star + 1)
                if (starCfg) {
                    proVal = cardInfo.chips / starCfg.need_chips
                    chipNum.getComponent(cc.Label).string = cardInfo.chips + "/" + starCfg.need_chips
                } else {
                    chipNum.getComponent(cc.Label).string = cardInfo.chips
                }
            }

            let pro = cc.find('card_fragement/pro', this.node)
            pro.getComponent(cc.ProgressBar).progress = proVal//>0.2?proVal:0.2

        }

    },

    //显示是否可以解锁/升星
    showUnlockAddStarUI: function (cardid) {
        let cardInfo = cc.vv.HerocardManager.getCardInfo(cardid)
        if (cardInfo) {
            let bCanUnlock = cc.vv.HerocardManager.isCardCanUnlock(cardInfo)
            let bCanAddStar = cc.vv.HerocardManager.isCardCanAddStar(cardInfo)
            this._bCanAction = bCanUnlock || bCanAddStar

            let spr_light = cc.find('card_fragement/spr_light', this.node)
            spr_light.active = this._bCanAction
            let node_up = cc.find('card_fragement/node_up', this.node)
            node_up.active = this._bCanAction

            let tipstr = ''
            let btnTitle = ''
            let btnLan = ''
            if (bCanUnlock) {
                tipstr = cc.js.formatStr('You can unlock %s now!', cardInfo.cfg.name)
                btnTitle = 'GO UNLOCK'
                btnLan = 'btn_gounlock'
            }
            if (bCanAddStar) {
                tipstr = cc.js.formatStr('You can upgrade %s now!', cardInfo.cfg.name)
                btnTitle = 'GO UPGRADE'
                btnLan = 'btn_goupgrade'
            }
            let lbl_tip = cc.find('spr_title/text_tip', node_up)
            if (lbl_tip) {
                lbl_tip.getComponent(cc.Label).string = tipstr
            }

            let btnLabel = cc.find('btn_go/Background/Label', node_up)
            let btni18Scp = btnLabel.getComponent("LanguageLabel")
            btni18Scp.id = btnLan
            btni18Scp.updateLabel()
            // btnLabel.getComponent(cc.Label).string = btnTitle

            let spr_addlv = cc.find('spr_addlv', node_up)
            spr_addlv.active = bCanUnlock
            let spr_addstart = cc.find('spr_addstar', node_up)
            spr_addstart.active = bCanAddStar


        }
    },

    onClickOpen: function () {
        if (this._canCloseAction) {
            if (this._closeEndCall) {
                this._closeEndCall()
            }
            this.node.destroy()
            return
        }
        this.fadeNum(false)
        if (this._nodeFragement.getNumberOfRunningActions() == 0) {
            Global.playCashEff("herocard/hero_open_pack");
            this._nodeClick.active = false
            let spineCMP = this._nodeSpine.getComponent(sp.Skeleton)
            spineCMP.timeScale = Global.ANIM_TIMESCALE_X2
            spineCMP.setAnimation(0, 'animation3_1', false)

            this.showResult()

        }



    },

    showResult: function () {
        let orgScale = this._nodeFragement.scale
        this._nodeFragement.active = true
        this._nodeFragement.opacity = 0
        this._nodeFragement.scale = 0.6
        cc.tween(this._nodeFragement)
            .delay(0.5)
            .call(() => {
                Global.playCashEff("herocard/hero_fragement_show");
            })
            .to(0.5, { opacity: 255, scale: orgScale }, { easing: 'backOut' })
            .call(() => {
                this._nodeClick.active = true
                this._canCloseAction = true
            })
            .delay(1)
            .call(() => {
                if (!this._bCanAction) {
                    if (this._closeEndCall) {
                        this._closeEndCall()
                    }
                    this.node.destroy()

                }
                else {
                    //
                    // this._nodeClick.active = true
                    // this._canCloseAction = true

                    if (cc.vv.gameData) {
                        let self = this
                        let nextCall = function () {
                            self.onClickOpen()
                        }
                        cc.vv.gameData.checkAutoPlay(this.node, nextCall)
                    }
                }

            })
            .start()
    },

    //跳转详情
    onClickGo: function () {
        Global.playComEff("ch_btn_click");
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CARDDROP_UNLOCK, '点击了游戏内卡牌解锁弹窗')
        cc.loader.loadRes("CashHero/prefab/herocard/card_detail", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let old = cc.find('card_detail', parObj)
                if (!old) {
                    let node = cc.instantiate(prefab);
                    let cardInfo = this._cardInfo
                    let campId = 0
                    node.parent = parObj
                    node.getComponent("CH_Herocard_Detail").init(cardInfo, false, campId);
                    this.node.destroy()
                }

            }
        })
    },

    onClickSkip: function () {
        this.fadeNum(false)
        Global.dispatchEvent(EventId.CLICK_SKIP)
        let self = this
        cc.loader.loadRes("CashHero/prefab/herocard/card_skip", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let old = cc.find('card_skip', parObj)
                if (!old) {
                    let node = cc.instantiate(prefab);

                    //设置一个回调
                    let _callBack = function () {
                        if (self.node && cc.isValid(self.node)) {
                            if (self._closeEndCall) {
                                self._closeEndCall()
                            }
                            self.node.destroy();
                        }
                    }
                    node.parent = parObj
                    node.getComponent("CH_Herocard_Skip").init(_callBack, self._cardId, this.skipHeroData);

                    self.node.active = false
                }
            }
        })
    },

    fadeSkip: function (flag) {
        let skip = cc.find('skipBtn', this.node)
        skip.active = flag
        skip.getComponent(cc.Button).interactable = flag
    },

    fadeNum: function (flag, skipFlag = true) {
        cc.find('num', this.node).active = flag
        let _skipFlag = skipFlag ? flag : skipFlag
        this.fadeSkip(_skipFlag)
    },

    setNum: function (num) {
        //循环 this._cardId
        let _data = cc.vv.UserManager.getHeroData()
        if (_data) {
            let availdNum = this.getCardNum(_data)
            if (availdNum) {
                this.setCount(availdNum)
                this.setEndHeroID(_data)
                this.skipHeroData = _data
                this.fadeNum(true)
            } else {
                this.fadeNum(false)
            }
        } else {
            this.setCount(num)
            this.fadeNum(true, false)
        }
    },

    getCardNum: function (_data) {
        let count = 0
        if (_data) {
            let canAdd = false
            for (let i = 0; i < _data.length; i++) {
                if (_data[i].type == Global.PROP_ID.HERO_CARD) {
                    if (_data[i].cardID == this._cardId) {
                        canAdd = true
                    }
                    if (canAdd) {
                        count += _data[i].count
                    }
                }
            }
        }

        return count
    },

    setCount: function (count) {
        // let canAdd = false
        // let count = 0
        // for (let i = 0; i < _data.length; i++) {
        //     if (_data[i].type == Global.PROP_ID.HERO_CARD) {
        //         if (_data[i].cardID == this._cardId) {
        //             canAdd = true
        //         }
        //         if (canAdd) {
        //             count += _data[i].count
        //         }
        //     }
        // }

        cc.find('num/label', this.node).getComponent(cc.Label).string = 'x' + count
    },

    setEndHeroID: function (_data) {
        let data = _data
        let heroArray = []
        for (let i = 0; i < data.length; i++) {
            if (data[i].type == Global.PROP_ID.HERO_CARD) {
                heroArray.push(data[i])
            }
        }
        let len = heroArray.length
        this._endHeroID = (len > 0) ? heroArray[len - 1].cardID : 0
    },

    update(dt) {

    },
});
