cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {},

    onLoad() {
        this.itemChildren = cc.find('itemNode', this.node).children
        this.firstBuyGiftData = cc.vv.UserManager.getFirstBuyGift()
        cc.vv.NetManager.registerMsg(MsgId.REQ_SEND_FIRSTGIFT_COLLECT, this.onRcvGetCollectData, this);
        this.sendCollectGift(1)
        Global.btnClickEvent(cc.find('closeBtn', this.node), this.onclickCloseBtn, this);
        Global.btnClickEvent(cc.find('clickBtn', this.node), this.onClickAction, this);
        Global.playComEff("ch_popup");
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SEND_FIRSTGIFT_COLLECT, this.onRcvGetCollectData, false, this);
    },

    onRcvGetCollectData(msg) {
        if (msg.code == 200) {
            this.firstBuyGiftData = msg.firstPayGift
            this.initBtn(this.firstBuyGiftData.status == 1)
            if (msg.rtype == 2) {
                this.showCollect()
                cc.vv.UserManager.delFirstBuyGift()
            }
        }
    },

    sendCollectGift: function (tp, id) {
        var req = { 'c': MsgId.REQ_SEND_FIRSTGIFT_COLLECT };
        req.rtype = tp
        if (id) {
            req.idx = id
        }
        if (tp == 1) {
            cc.vv.NetManager.sendAndCache(req);
        }
        else {
            cc.vv.NetManager.send(req);
        }
    },

    isHasReddot() {
        if (cc.isValid(this.firstBuyGiftData)) {
            if (!this.firstBuyGiftData.status) {
                this.setReddot(false)
                return
            }
            let flag = this.isAllCollect(this.firstBuyGiftData.rewards)
            if (!flag) {
                //>12 全领取完 小于则还有未解锁
                (cc.vv.UserManager.getCurLv() > 11) ? this.closeIcon() : this.setReddot(false)
                // console.log('>12')
            } else {
                this.setReddot(true)
            }
        }
    },

    initBtn(flag) {
        let clickBtnNode = cc.find('clickBtn', this.node)
        // if (flag) {
        //     Global.btnClickEvent(clickBtnNode, this.onClickCollect, this)
        // }else {
        //     Global.btnClickEvent(clickBtnNode, this.onClickGetNowBtn, this)
        // }
        cc.find('Background/collect', clickBtnNode).active = flag
        cc.find('Background/getNow', clickBtnNode).active = !flag
    },

    onClickAction() {
        if (this.firstBuyGiftData) {
            if (this.firstBuyGiftData.status == 1) {
                this.onClickCollect()
            }
            else {
                this.onClickGetNowBtn()
            }
        }
    },

    setReddot(flag) {
        if (!flag) {
            Global.dispatchEvent(EventId.CLEAN_LOCAL_RED);
        } else {
            Global.dispatchEvent(EventId.SET_RED);
        }
    },

    closeIcon() {
        cc.vv.UserManager.delFirstBuyGift()
        // var req = {'c': EventId.REQ_CLOSE_FIRST_ICON};
        Global.dispatchEvent(EventId.CLOSE_FIRST_ICON);
    },

    isBuyGift(rd) {
        cc.find('getBtn', this.node).active = false
        // let data = rd[0]
        // rd[0] = rd[2]
        // rd[2] = data
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == 2) {
                //vip
                this.initItem(this.itemChildren[0], rd[i])
            } else if (rd[i].type == 10) {
                //rich
                this.initItem(this.itemChildren[1], rd[i])
            } else if (rd[i].type == 21) {
                //zeus
                this.initItem(this.itemChildren[2], rd[i])
            }

        }
    },

    initItem(node, rd) {
        cc.find('buy/label', node).active = false
        cc.find('collectBtn', node).active = false
        if (rd.status == 2) {
            cc.find('buy/buied', node).active = true
        }
        if (rd.status == 1) {
            cc.find('collectBtn', node).active = true
        }
        if (rd.type == 21) {
            if (cc.vv.UserManager.getCurLv() < 12) {
                cc.find('buy/label', node).active = true
            }
        }
    },

    isAllCollect(rd) {
        if (!this.isHallToHere) {
            return true
        }
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].status == 1) {
                return true
            }
        }
        return false
    },

    isCollectFunc() {
        let item = cc.find('itemNode/item' + id, this.node)
        cc.find('buy/buied', item).active = true
        cc.find('collectBtn', item).active = false
    },

    flyIcon(rd) {
        // for (let i = 0; i < rd.length; i++) {
        //     if (rd[i].type == Global.PROP_ID.FULL_CARD) {
        //         if (!cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)) {
        //             rd[i].type = 22
        //         }
        //     }
        // }
        var rdArray = rd
        let self = this
        let nextCall = function () {
            self.onclickCloseBtn()
        }
        cc.vv.UserManager.loadPopReward(rdArray, nextCall, 1)
    },

    closeLayout() {
        let canvas = cc.find("Canvas");
        if (!canvas || !canvas.isValid) return
        this.node_layout = canvas.getChildByName('node_layout');
        if (this.node_layout) {
            this.node_layout.active = false
        }
    },

    onClickCollect() {
        cc.find('clickBtn', this.node).getComponent(cc.Button).interactable = false
        this.sendCollectGift(2)
    },

    showCollect: function () {
        this.flyIcon(this.firstBuyGiftData.rewards)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FIRSTBUYGIFT_COLLECT)
    },

    isFromHallToHere(flag) {
        this.isHallToHere = flag

        this._msgInfo = flag ? '首充礼包' : '首充弹窗'
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FIRSTBUYGIFT_POP, this._msgInfo)
    },

    onClickGetNowBtn() {
        Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
        this.closeLayout()
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FIRSTBUYGIFT_GETNOW, this._msgInfo)
        this.nodeDestroy()
    },

    inPopIsClose(rd) {
        for (let i = 0; i < rd.length; i++) {
            if (!rd[i].status) {
                return false
            }
            if (rd[i].status == 1) {
                return false
            }
        }
        return true
    },

    onclickCloseBtn() {
        if (!this.isHallToHere) {
            cc.vv.EventManager.emit(EventId.NEXT_POP_UI);

            let isClose = this.inPopIsClose(this.firstBuyGiftData.rewards)
            if (isClose) {
                this.closeIcon()
            }
        } else {
            this.isHasReddot()
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FIRSTBUYGIFT_CLOSE, this._msgInfo)
        Global.playComEff("ch_close");
        this.nodeDestroy()
    },

    nodeDestroy() {
        this.node.destroy()
    },

    start() { },

    // update (dt) {},
});
