/**
 * 转盘
 */

cc.Class({
    extends: cc.Component,

    properties: {
        atlas_wheel:cc.SpriteAtlas,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._wheelData = [10, 3, 1, 5, 2, 3, 1, 2, 5, 1];
        
    },

    start () {

    },

    async showWhell(resultIdx,endCall){
        this._resultIdx = resultIdx
        this.initWheel()
        await this.moveWheel(this._resultIdx)
        await this.wheelResult()
        if(endCall) endCall()
    },

    //初始化转盘
    initWheel:function(){
        let result_node = cc.find("spine_result",this.node)
        result_node.active = false
        let result_light = cc.find("spine_light",this.node)
        result_light.active = false
        let spr_mult = cc.find("spr_multi",this.node)
        spr_mult.active = false
    },

    // idx 1开始对于10倍
    moveWheel:function(idx){
        
        return new Promise(async(sucess, failed)=> {
            let nCir = 4
        Global.playCashEff("normal_wheel/wheel_spin")
        let nIdxLen = this._wheelData.length
        let nTotalAng = (nIdxLen-(idx-1))*(360/nIdxLen) + nCir*360;
        let objLun = cc.find("spr_di",this.node)
        cc.tween(objLun)
                .by(7,{angle:-nTotalAng},{easing:'quadInOut'})
                .call(()=>{
                    sucess()
                })
                .start();
        })
        

        

    },

    //显示结果
    wheelResult:function(){
        return new Promise(async(sucess, failed)=> {
            Global.playCashEff("normal_wheel/wheel_stop2")
            let spr_multi = cc.find('spr_multi',this.node);
            let spine_light = cc.find('spine_light',this.node);
            let spine_result = cc.find('spine_result',this.node);

            spine_result.active = true;
            spine_result.getComponent(sp.Skeleton).setAnimation(0,'animation',true);
            spine_result.getComponent(sp.Skeleton).setCompleteListener(()=>{});
            await this.awaitTime(0.5);

            let multi_id = this._wheelData[this._resultIdx-1];
            spr_multi.active = true;
            spr_multi.setScale(2);
            spr_multi.opacity = 50
            spr_multi.getComponent(cc.Sprite).spriteFrame = this.atlas_wheel.getSpriteFrame('theme_bonus_multi_'+multi_id);

            cc.tween(spr_multi)
                    .to(0.5,{ scale:1,opacity:255})
                    .start()
            
            spine_light.active = true;
            spine_light.setScale(0);
            cc.tween(spine_light).to(0.5,{scale:0.7}).start()
            spine_light.getComponent(sp.Skeleton).setAnimation(0,'animation',true);
            spine_light.getComponent(sp.Skeleton).setCompleteListener(()=>{
                // spine_light.active = false;
                
            });
            await this.awaitTime(1);
            sucess()
        })
        
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    // update (dt) {},
});
