/**
 * 弹出的形式展示奖励
 */
let FROMWHERE = {
    NORMAL: 0,
    FIRSTBUY: 1,
    MISSION: 2,
};

cc.Class({
    extends: cc.Component,

    properties: {
        _datas: null,
        _endCall: null,

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.clickSkip = false  //卡牌碎片的跳过
        Global.FixDesignScale_V(this.node)
        Global.btnClickEvent(cc.find('bgBtn', this.node), this.onClick, this);
        this._curIndex = 0  //当前播放到第几个奖励
        this._clickSkipFlag = false //在弹出奖励的时候跳过
        this._isAddCoin = false //是否已经加过金币
    },

    start() {
        Global.registerEvent(EventId.CLICK_SKIP, this.setStipStatus, this);
    },

    async showDropCard(cardid, count, id) {
        let packType = 1
        if (id == Global.PROP_ID.HERO_FRAGEMENT) {
            packType = 2
        }
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showDropUI(cardid, count, sucess, false, packType)
        });
    },

    //掉落整卡
    async showFullCard(rewards) {
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showFullDropUI(rewards, null, sucess)
        });
    },

    async showDropNormal(itemId, num, datas) {
        let self = this
        return new Promise((sucess, failed) => {
            Global.playComEff("ch_popup_l2");

            let itemnormal = cc.find('item_normal', self.node)
            if (itemId == Global.PROP_ID.GLOD_HUMER) {
                itemnormal.active = false
            } else {
                itemnormal.active = true
            }
            itemnormal.scale = 0
            itemnormal.opacity = 0
            //设置信息
            let icon = cc.find('spr_item', itemnormal)
            if (Global.language === Global.LANGUAGE.AR) {
                if (itemId == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                    itemId = Global.PROP_ID.DOUBLE_LEVEL_EXP_AR
                }
            }
            icon.getComponent('CH_RewardItem').init(itemId, num)

            let labelNode = cc.find('lbl_num', itemnormal)
            labelNode.active = !(itemId == Global.PROP_ID.LOCAL_FULL_CARD)

            let _scaleTime = 0.7

            cc.tween(itemnormal)
                .to(_scaleTime / 2, { scale: 1, opacity: 255 }, { easing: 'backOut' })
                .call(() => {
                    if (itemId == Global.PROP_ID.COIN) {
                        //飞金币
                        let fromNode = icon
                        let toNode = cc.find(Global.HALL_COIN_NODE_PATH)
                        if (cc.vv.gameData) {
                            toNode = cc.find(Global.INGAME_COIN_NODE_PATH)
                        }
                        let rollData = {}
                        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
                        if (cc.vv.gameData) {
                            rollData.lblCoin = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
                        }
                        rollData.addCoin = num
                        Global.FlyCoin(fromNode, toNode, () => {
                            if (!this._isAddCoin && !this._clickSkipFlag) {
                                this._isAddCoin = true
                                if (cc.vv.gameData) {
                                    cc.vv.gameData.AddCoin(num)
                                    cc.vv.gameData.RefushMyCoin()
                                } else {
                                    cc.vv.UserManager.AddCoin(num, true)
                                }
                            }
                            sucess()
                        }, rollData, true)
                    } else if (itemId == Global.PROP_ID.RICH_POINT) {
                        if (this._fromType == FROMWHERE.FIRSTBUY) {
                            let toNode = cc.find('Canvas/menu_top/btn_palace')
                            if (toNode) {
                                this.iconFly(icon, toNode, itemId, () => {
                                    sucess()
                                }
                                )
                            }
                            else {
                                sucess()
                            }
                        } else {
                            Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: itemId, num: num })
                            sucess()
                        }
                    } else if (itemId == Global.PROP_ID.VIP_POINT) {
                        if (this._fromType == FROMWHERE.FIRSTBUY) {
                            let toNode = cc.find('Canvas/menu_top/btn_vip')
                            if (toNode) {
                                this.iconFly(icon, toNode, itemId, () => {
                                    sucess()
                                })
                            }
                            else {
                                sucess()
                            }
                        } else {
                            Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: itemId, num: num })
                            sucess()
                        }
                    } else if (itemId == Global.PROP_ID.GLOD_HUMER) {
                        //显示获得锤子
                        cc.loader.loadRes("CashHero/prefab/lucky_smash/lucky_hummer", cc.Prefab, (err, prefab) => {
                            let canvas = cc.find("Canvas")
                            if (!err && !canvas.getChildByName("lucky_hummer")) {
                                let node = cc.instantiate(prefab)
                                node.name = "lucky_hummer"
                                node.parent = canvas

                                let endCall = function () {
                                    Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: itemId, num: num })
                                    sucess()
                                }
                                node.getComponent("LuckySmash_Hummer").setType(2, 1, endCall, false)
                            }
                        })
                    } else if (itemId == Global.PROP_ID.LOCAL_FULL_CARD || itemId == Global.PROP_ID.LOCAL_HERO_CARD) {
                        let toNode = cc.find('Canvas/bottom/btn_poker')
                        if (toNode) {
                            this.iconFly(icon, toNode, itemId, () => {
                                sucess()
                            })
                        }
                        else {
                            sucess()
                        }
                        // cc.vv.HerocardManager.addHeroCardRedData(datas)
                        Global.dispatchEvent(EventId.REFUSH_HEROCARD_RED_TIPS)
                    } else if (itemId == Global.PROP_ID.DIAMOND) {
                        cc.vv.UserManager.AddDiamond(num, true)
                        Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: itemId, num: num })
                        sucess()
                    }
                    else {
                        Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: itemId, num: num })
                        sucess()
                    }
                })
                .start()



        });
    },

    /**
     * 
     * @param {*} datas [{type,count,(卡牌掉落才有cardID,cardInfo)}]
     * @param {*} endCall 
     * @param {*} fromWhere    //0正常  1首充礼包  2任务
     */
    async showRewards(datas, endCall, fromWhere = 0) {
        //数据预处理
        this._datas = this._preData(datas)
        this._endCall = endCall

        this._fromType = fromWhere
        this._setBgBtnEnable(this._fromType == FROMWHERE.MISSION)

        cc.vv.UserManager.setHeroData(datas)

        let _awaitTime = 0.4

        for (let i = 0; i < this._datas.length; i++) {
            let reward = this._datas[i]
            let id = reward.type
            console.log("物品id" + id)
            this._curIndex = i  //当前播放到第几个奖励
            // //如果卡牌系统未解锁就将整卡/卡包的表现当作普通物品来表现，数据还是照常更新
            // if (!cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)) {
            //     if(id == Global.PROP_ID.FULL_CARD || id == Global.PROP_ID.HERO_CARD){
            //         if(id == Global.PROP_ID.FULL_CARD){
            //             reward.type = Global.PROP_ID.LOCAL_FULL_CARD
            //         }
            //         if(id == Global.PROP_ID.HERO_CARD){
            //             reward.type = Global.PROP_ID.LOCAL_HERO_CARD
            //         }

            //         id = reward.type

            //         //整卡更新数据
            //         if (reward.cardInfo) {
            //             cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
            //             Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
            //         }
            //     }
            // }


            if (id == Global.PROP_ID.HERO_CARD || id == Global.PROP_ID.HERO_FRAGEMENT) {
                if (this.clickSkip) {
                    continue
                }
                this._showNormalItem(false)
                if (reward.cardInfo) {
                    cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                    Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                }

                await this.showDropCard(reward.cardID, reward.count, id)
            }
            else if (id == Global.PROP_ID.FULL_CARD) {
                //整卡
                if (reward.cardInfo) {
                    let info = cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                    Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                    if (info) {
                        cc.vv.UserManager.setGameUnlock(info.cfg.gameid)
                    }
                }
                this._showNormalItem(false)
                await this.showFullCard([reward])
            }
            else {
                await this.showDropNormal(reward.type, reward.count, datas[i])
            }
            //如果点了跳过
            if (this._clickSkipFlag) {
                console.log("跳过")
                // //全部执行完
                // if(this._endCall){
                //     this._endCall()
                // }
                // this.node.destroy()

                return
            }
            // await this.awaitTime(0.4)
            await this.awaitTime(_awaitTime / 2)
        }
        cc.vv.UserManager.clearHeroData()
        console.log("结束1")
        //全部执行完
        if (this._endCall) {
            console.log("结束2")
            this._endCall()
        }
        this.node.destroy()
        console.log("结束3")
    },

    //数据预处理
    _preData: function (datas) {
        let res = []
        let fullCardIdx
        let fullPackIdx
        let bRfushRedNum
        for (let i = 0; i < datas.length; i++) {
            let reward = datas[i]
            let id = reward.type



            if (!cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)) {
                if (id == Global.PROP_ID.FULL_CARD) {
                    //整卡更新数据
                    if (reward.cardInfo) {
                        cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                        Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                        bRfushRedNum = true


                    }

                    if (cc.js.isNumber(fullCardIdx)) {
                        //已经有了，就叠加数量
                        res[fullCardIdx].count += 1
                        continue;
                    }
                    else {

                        reward.type = Global.PROP_ID.LOCAL_FULL_CARD
                        fullCardIdx = res.length

                    }
                }

                if (id == Global.PROP_ID.HERO_CARD) {
                    //整卡更新数据
                    if (reward.cardInfo) {
                        cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                        Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                        bRfushRedNum = true
                    }

                    if (cc.js.isNumber(fullPackIdx)) {
                        //已经有了，就叠加数量
                        res[fullPackIdx].count += 1
                        continue;
                    }
                    else {
                        reward.type = Global.PROP_ID.LOCAL_HERO_CARD
                        fullPackIdx = res.length

                    }
                }

            }

            res.push(reward)
        }
        if (bRfushRedNum) {
            Global.dispatchEvent(EventId.REFUSH_HEROCARD_RED_TIPS)
        }
        return res
    },

    _setBgBtnEnable(flag) {
        cc.find('bgBtn', this.node).getComponent(cc.Button).interactable = flag
    },

    _showNormalItem(bShow) {
        let itemnormal = cc.find('item_normal', this.node)
        itemnormal.active = bShow
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    iconFly(icon, toNode, itemId, endCall) {
        var btnIcon = null
        if (itemId == Global.PROP_ID.RICH_POINT) {
            // 'Canvas/menu_top/btn_palace' //palace
            let preNode = cc.find('Canvas/menu_top/btn_palace')
            btnIcon = cc.instantiate(preNode)
        } else if (itemId == Global.PROP_ID.VIP_POINT) {
            // 'Canvas/menu_top/btn_vip'    //VIP
            let preNode = cc.find('Canvas/menu_top/btn_vip')
            btnIcon = cc.instantiate(preNode)
        } else if (itemId == Global.PROP_ID.LOCAL_FULL_CARD || itemId == Global.PROP_ID.LOCAL_HERO_CARD) {
            // 'Canvas/bottom/btn_poker'    //hero
            let preNode = cc.find('Canvas/bottom/btn_poker')
            btnIcon = cc.instantiate(preNode)
        }
        btnIcon.parent = icon.parent

        let fromNode = icon
        let flyNode = cc.instantiate(icon)
        flyNode.parent = icon.parent

        let fromWordPos = fromNode.convertToWorldSpaceAR(cc.v2(0, 0))
        let toWordPos = toNode.convertToWorldSpaceAR(cc.v2(0, 0))

        let _scaleX = (toNode.width / 2) / icon.width
        let _scaleY = (toNode.height / 2) / icon.height

        let disX = toWordPos.x - fromWordPos.x
        let disY = toWordPos.y - fromWordPos.y
        btnIcon.y = disY + flyNode.y

        let time = 0.7
        flyNode.runAction(cc.sequence(
            cc.spawn(
                cc.moveBy(time / 2, cc.v2(disX, disY)),
                cc.scaleTo(time / 2, _scaleX, _scaleY),
            ),
            cc.callFunc(function () {
                btnIcon.destroy()
                flyNode.destroy()
                if (endCall) {
                    endCall()
                }

            }, this),
        )
        )
    },

    setStipStatus() {
        this.clickSkip = true
    },

    onClick() {
        this._clickSkipFlag = true
        this._setBgBtnEnable(false)
        //关闭 更新奖励
        //除了当前的奖励 后续还有奖励
        if (this._curIndex + 1 < this._datas.length) {
            for (let i = this._curIndex + 1; i < this._datas.length; i++) {
                if (this._datas[i].type == Global.PROP_ID.HERO_CARD || this._datas[i].type == Global.PROP_ID.FULL_CARD) {
                    if (this._datas[i].cardInfo) {
                        cc.vv.HerocardManager.updateCardInfo(this._datas[i].cardInfo)
                        Global.dispatchEvent("HEROCARD_UPDATED", this._datas[i].cardInfo)
                    }
                } else {
                    Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: this._datas[i].type, num: this._datas[i].count })
                }
            }
        }

        if (!this._isAddCoin) {
            for (let j = 0; j < this._datas.length; j++) {
                if (this._datas[j].type == Global.PROP_ID.COIN) {
                    if (cc.vv.gameData) {
                        cc.vv.gameData.AddCoin(this._datas[j].count)
                        cc.vv.gameData.RefushMyCoin()
                    } else {
                        cc.vv.UserManager.AddCoin(this._datas[j].count, true)
                    }
                }
            }
        }
        cc.vv.UserManager.clearHeroData()
        //全部执行完
        if (this._endCall) {
            this._endCall()
        }
        this.node.destroy()
    },

    // update (dt) {},
});
