/**
 * vip
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        iconAtlas: cc.SpriteAtlas,
        arIconAtlas: cc.SpriteAtlas,
        _curIdx: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('btn_close', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)
        let btnTip = cc.find("node_content/node_title/point_cur/lbl/btn_tip", this.node)
        Global.btnClickEvent(btnTip, this.onClickTip, this)
        let btnLeft = cc.find("node_content/btn_left", this.node)
        Global.btnClickEvent(btnLeft, this.onClickLeft, this)
        let btnRight = cc.find("node_content/btn_right", this.node)
        Global.btnClickEvent(btnRight, this.onClickRight, this)
        let btnRecharge = cc.find("node_content/btn_recharge", this.node)
        Global.btnClickEvent(btnRecharge, this.onClickRecharge, this)

        Global.playComEff("ch_popup");

        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_VIP_INFO, this.onRcvGetVipInfo, this);
        Global.registerEvent(EventId.REFRUSH_VIP, this.onEventRefushVip, this)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_VIP_INFO, this.onRcvGetVipInfo, this);
    },

    start() {
        var req = { 'c': MsgId.REQ_GET_VIP_INFO };
        cc.vv.NetManager.sendAndCache(req, true);
    },

    //data:显示的权益页序号
    //benifist:特别突出的权益
    setShowVipBenefist: function (data, benifist) {
        this._curIdx = data
        this._selectBnifist = benifist
    },

    onClickClose: function () {
        this.node.destroy()
    },

    onClickTip: function () {
        cc.loader.loadRes("CashHero/prefab/vip/CH_vip_help", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let node = cc.find('CH_vip_help', parObj)
                if (!node) {
                    node = cc.instantiate(prefab);
                    node.parent = parObj
                }
            }
        })
    },

    onRcvGetVipInfo: function (msg) {
        if (msg.code === 200) {
            this.itemData = Global.VIP_INFO;
            let userData = msg.user;
            this._vipLv = userData.vip;
            this._curExp = userData.vipexp;
            if (this._curIdx == null) {
                this._curIdx = this._vipLv == 0 ? 1 : this._vipLv;
            }
            else {
                //否则使用预设的curIdx
            }


            this.showTitle();
            this.showInfo(this._curIdx, this.itemData[this._curIdx], this._selectBnifist);
        }
    },

    onEventRefushVip: function () {
        this.itemData = Global.VIP_INFO;
        this._vipLv = cc.vv.UserManager.getVipLevel();
        this._curExp = cc.vv.UserManager.getVipExp();
        this._curIdx = this._vipLv == 0 ? 1 : this._vipLv;
        this.showTitle();
        this.showInfo(this._curIdx, this.itemData[this._curIdx]);
    },

    showTitle: function () {
        cc.find("node_content/node_title/spr", this.node).getComponent(cc.Sprite).spriteFrame = this.iconAtlas.getSpriteFrame(`0${this._vipLv}`);
        cc.find("node_content/node_title/spr_cur", this.node).getComponent(cc.Sprite).spriteFrame = this.iconAtlas.getSpriteFrame(`vip_${this._vipLv}_tile`);
        let spr_next = cc.find("node_content/node_title/spr_next", this.node)
        if (this._vipLv + 1 < this.itemData.length) {
            spr_next.active = true;
            spr_next.getComponent(cc.Sprite).spriteFrame = this.iconAtlas.getSpriteFrame(`vip_${this._vipLv + 1}_tile`);
        } else {
            spr_next.active = false;
        }

        let needExp = this.itemData[this._vipLv].upNeedExp;
        cc.find("node_content/node_title/point_cur/lbl", this.node).getComponent(cc.Label).string = this._curExp;
        cc.find("node_content/node_title/point_need/lbl", this.node).getComponent(cc.Label).string = needExp == 0 ? needExp : needExp - this._curExp;

        let per = needExp == 0 ? 1 : this._curExp / needExp;
        cc.find("node_content/node_title/ProgressBar", this.node).getComponent(cc.ProgressBar).progress = Math.min(1, per);
        cc.find("node_content/node_title/ProgressBar/percent", this.node).getComponent(cc.Label).string = `${Math.floor((per) * 100)}%`;
        cc.find("node_content/node_title/ProgressBar/max", this.node).active = this._vipLv + 1 == this.itemData.length
    },

    showInfo: function (idx, data, selectBenifist) {
        cc.find("node_content/info/title/spr", this.node).getComponent(cc.Sprite).spriteFrame = this.iconAtlas.getSpriteFrame("0" + idx);
        cc.find("node_content/info/layout/spr1/lbl2", this.node).getComponent(cc.Label).string = `+ ${data.scratch * 100}%`;
        cc.find("node_content/info/layout/spr2/lbl2", this.node).getComponent(cc.Label).string = `× ${data.store}`;
        cc.find("node_content/info/layout/spr3", this.node).active = data.inboxcollect;
        cc.find("node_content/info/layout/spr4/lbl2", this.node).getComponent(cc.Label).string = `+ ${data.maxfriends}`;
        let benifit5 = cc.find("node_content/info/layout/spr5", this.node)
        benifit5.active = data.heroslot
        cc.find("lbl2", benifit5).getComponent(cc.Label).string = `+ ${data.heroslot}`;

        let bLock = this._curIdx > this._vipLv
        // Global.showSpriteGray(cc.find("node_content/info/layout/spr1/img1",this.node), bLock);
        // Global.showSpriteGray(cc.find("node_content/info/layout/spr2/img2",this.node), bLock);
        // Global.showSpriteGray(cc.find("node_content/info/layout/spr3/img3",this.node), bLock);
        // Global.showSpriteGray(cc.find("node_content/info/layout/spr4/img4",this.node), bLock);
        for (let i = 0; i < 5; i++) {
            let img = cc.find(cc.js.formatStr("node_content/info/layout/spr%s/img%s", (i + 1), (i + 1)), this.node)
            Global.showSpriteGray(img, bLock)
            let lbl1 = cc.find(cc.js.formatStr("node_content/info/layout/spr%s/lbl1", (i + 1)), this.node)
            lbl1.color = bLock ? cc.Color(125, 125, 125) : cc.Color(255, 255, 255)
            let lbl2 = cc.find(cc.js.formatStr("node_content/info/layout/spr%s/lbl2", (i + 1)), this.node)
            lbl2.color = bLock ? cc.Color(125, 125, 125) : cc.Color(245, 201, 61)
            if (selectBenifist && selectBenifist == (i + 1)) {
                let selImg = cc.find(cc.js.formatStr("node_content/info/layout/spr%s/select", (i + 1)), this.node)
                selImg.active = true
                let endCall = function () {
                    selImg.active = false
                }
                Global.blinkAction(selImg, 0.2, 0.1, 6, endCall)
                this._selectBnifist = null
            }
        }

        cc.find("node_content/btn_left", this.node).active = bLock && this._curIdx > 1;
        cc.find("node_content/btn_right", this.node).active = this._curIdx + 1 < this.itemData.length;

        this.showVipIdx(idx)
    },

    showVipIdx: function (idx) {
        for (let i = 0; i < 7; i++) {
            let bSel = idx == (i + 1)
            let idxNode = cc.find("node_content/lay_idx/" + (i + 1), this.node)
            idxNode.color = bSel ? cc.Color(0, 255, 0) : cc.Color(255, 255, 255)
            let lbl = cc.find("lbl", idxNode)
            lbl.color = bSel ? cc.Color(255, 255, 255) : cc.Color(155, 155, 155)
        }
    },

    onClickLeft: function () {
        if (this._curIdx > 1 && this._curIdx > this._vipLv) {
            this._curIdx -= 1;

            let self = this;
            this.playChangeAnim(20, function () {
                self.showInfo(self._curIdx, self.itemData[self._curIdx]);
            });
        }
    },

    onClickRight: function () {
        if (this._curIdx + 1 < this.itemData.length) {
            this._curIdx += 1;

            let self = this;
            this.playChangeAnim(-20, function () {
                self.showInfo(self._curIdx, self.itemData[self._curIdx]);
            });
        }
    },

    playChangeAnim(deltaX, changeFunc) {
        let info = cc.find("node_content/info", this.node);
        cc.tween(info)
            .to(0.15, { opacity: 65, position: cc.v2(deltaX, info.y) })
            .call(() => {
                if (changeFunc) {
                    changeFunc();
                }
            })
            .to(0.15, { opacity: 255, position: cc.v2(0, info.y) })
            .start()

    },

    onClickRecharge() {
        // cc.loader.loadRes("CashHero/prefab/month_card",cc.Prefab, (err, prefab) => {
        //     if(!err){
        //         let canvas = cc.find("Canvas");
        //         if(canvas.isValid && !cc.find('month_card',canvas)){
        //             let obj = cc.instantiate(prefab)
        //             obj.parent = canvas
        //         }
        //     }
        // })

        //跳转钻石
        cc.vv.UserManager.setEnterHallAction('Shop_Diamond')
        Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
        this.onClickClose()
    },

    // update (dt) {},
});
