    //bPreload:预加载
    _showSysUnlock: function (lv, bPreload) {
        let self = this
        let url
        let uiname
        if (lv == Global.SYS_OPEN.QUEST_TASK) {
            let bOpen = cc.vv.UserManager.isOpenQuestServer()
            if (bOpen) {
                //quest开放
                url = "CashHero/prefab/quest_unlock"
                uiname = "quest_unlock"
            }
        }
        else if (lv == Global.SYS_OPEN.BINGO) {
            url = "CashHero/prefab/node_sys_unlock"
            uiname = "node_sys_unlock"
        }
        else if (lv == Global.SYS_OPEN.FB_BIND_PARTY) {
            url = "CashHero/prefab/fbShare/fb_binding_ad"
            uiname = "fb_binding_ad"
        }
        else if (lv == Global.SYS_OPEN.LUCKY_SMASH) {
            url = "CashHero/prefab/lucky_smash/lucky_main"
            uiname = "lucky_main"
        }
        else if (lv == Global.SYS_OPEN.HERO_CARD) {
            url = "slots_common/SlotRes/prefab/LMSlotsSys_float"
            uiname = "LMSlotsSys_float"
        }
        else if (lv == Global.SYS_OPEN.PIG_BANK) {
            url = "hall_prefab/MoneyBankUI"
            uiname = "MoneyBankUI"
        }
        // else if(lv == Global.SYS_OPEN.DAILYTASK){
        //     url == "CashHero/prefab/mission/mission_frame"
        //     uiname = "mission_frame"
        // }
        else if (lv == Global.SYS_OPEN.CASH_BACK) {
            url = "CashHero/prefab/cashBack/cashBackPop"
            uiname = "cashBackPop"
        }

        if (url) {
            let callbacks = function (prefab) {
                if (bPreload) return
                let node = cc.instantiate(prefab);
                node.name = uiname;
                node.parent = cc.find("Canvas");
                let lifecmp = node.addComponent("NodeLifeCallBack")
                if (uiname == "mission_frame") {
                    lifecmp.setDisableCall(self._notifyNext)
                }
                else {
                    lifecmp.setDestroyCall(self._notifyNext)
                }

                if (lv == Global.SYS_OPEN.BINGO) {
                    let openType = cc.vv.UserManager.getOpenActiveType()
                    let sysname = openType == 1 ? 'bingo' : 'knight'
                    let scp = node.getComponent('CH_Sys_unlock')
                    scp.showUnlockSys(sysname)
                }

            }
            this._loadPrefab(url, callbacks)
        }

    },

    _notifyNext: function () {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }

        //刷新下一个目标
        Global.dispatchEvent(EventId.SYS_ROAD_REFUSH)

        //检查下一个弹窗
        cc.vv.QueueWinMrg.startPop()
    },

    _onTouchStart(event) {
        this._moved = false
        this._startPos = event.getLocation()
        this._lastPos = cc.v2(this._startPos.x, this._startPos.y)
    },

    _onTouchMove(event) {
        let location = event.getLocation()
        if (this._lastPos && this._lastPos.sub(location).len() > 4) {
            this._lastPos = cc.v2(location.x, location.y)
            let box = this.node.getBoundingBox()
            if (location.x + box.width / 2 > cc.winSize.width) location.x = cc.winSize.width - box.width / 2
            if (location.x - box.width / 2 < 0) location.x = box.width / 2
            if (location.y + box.height / 2 > cc.winSize.height) location.y = cc.winSize.height - box.height / 2
            if (location.y - 2 * box.height / 2 < 0) location.y = 2 * box.height / 2
            // this.node.position = this.node.parent.convertToNodeSpaceAR(location)
            if (this._startPos.sub(location).len() > 10) {
                this._moved = true

                // let deal = event.getDelta()
                // this.node.x += deal.x
                // this.node.y += deal.y
                // let nWinWidth = cc.winSize.width
                // let nWinHeight = cc.winSize.height

                // if(this.node.x + this.node.width/4 > nWinWidth/2)  this.node.x = nWinWidth/2 - this.node.width/4
                // if(this.node.x - this.node.width/4 < -nWinWidth/2) this.node.x = -nWinWidth/2 + this.node.width/4
                // if(this.node.y  > (nWinHeight/2-100)) this.node.y = (nWinHeight/2 -100)
                // if(this.node.y - (this.node.height) < -(nWinHeight/2-100)) this.node.y = this.node.height - (nWinHeight/2-100)
            }
        }

    },

    _onTouchEnd(event) {
        if (!this._moved) { //未移动过，触发点击
            this.onNodeClicked()
        }
    },

