/**
 * bonus activity
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _loginList: [],
        _activityList: [],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

        this.node_share = cc.find("src/view/content/share_wheel", this.node)
        this.node_share.active = false
        if (Global.isIOSReview()) {
            //提审不显示分享
        }
        else {
            this._loginList.push(this.node_share)
        }

        this.node_frenzy = cc.find("src/view/content/frenzy", this.node)
        this.node_frenzy.active = false
        Global.btnClickEvent(cc.find("btn_collect", this.node_frenzy), this.onClickFrienzyCollect, this)
        Global.btnClickEvent(cc.find("palace_mult/btn_go", this.node_frenzy), this.onClickFrienzyQuestMark, this)
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.DAILYFRIENZY)) {
            this._loginList.push(this.node_frenzy)
        }

        this.node_sign = cc.find("src/view/content/login_reward", this.node)
        this.node_sign.active = false
        this._loginList.push(this.node_sign)


        //月卡试用
        this.node_cardTrail = cc.find("src/view/content/card_trial", this.node)
        this.node_cardTrail.active = true
        Global.btnClickEvent(this.node_cardTrail, this.onClickCardTrailGo, this)
        this._activityList.push(this.node_cardTrail)

        this.node_quest = cc.find("src/view/content/quest", this.node)
        this.node_quest.active = false
        Global.btnClickEvent(this.node_quest, this.onClickQuestGo, this)
        if (cc.vv.PopUIMgr.isHasLoginPopId(11)) {
            Global.breathNode(cc.find("timer/val", this.node_quest))
            this._activityList.push(this.node_quest)
        }

        this.node_smash = cc.find("src/view/content/smash", this.node)
        this.node_smash.active = false
        Global.btnClickEvent(this.node_smash, this.onClickSmashGo, this)
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_SMASH)) {
            this._activityList.push(this.node_smash)
        }

        this.node_flip = cc.find("src/view/content/luckyflip", this.node)
        this.node_flip.active = false
        Global.btnClickEvent(this.node_flip, this.onClickFlipGo, this)
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_CARD)) {
            this._activityList.push(this.node_flip)
        }

        this.node_knight = cc.find("src/view/content/knight", this.node)
        this.node_knight.active = false
        Global.btnClickEvent(this.node_knight, this.onClickKnightGo, this)
        let bOpenExplore = cc.vv.UserManager.isOpen(Global.SYS_OPEN.EXPLORATION)
        if (bOpenExplore && cc.vv.UserManager.isActivityOpen(2)) {
            this._activityList.push(this.node_knight)
        }
        this.node_bingo = cc.find("src/view/content/bingo", this.node)
        this.node_bingo.active = false
        Global.btnClickEvent(this.node_bingo, this.onClickBingoGo, this)
        let bOpenBingo = cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)
        if (bOpenBingo && cc.vv.UserManager.isActivityOpen(1)) {
            this._activityList.push(this.node_bingo)
        }



        cc.vv.NetManager.registerMsg(MsgId.REQ_HALL_TAB_BONUS, this.onRcvNeActivityListInfo, this)//获得任务列表

        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_ONLINE_COIN, this.onRcvGetOnlineCoin, this);

    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HALL_TAB_BONUS, this.onRcvNeActivityListInfo, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_ONLINE_COIN, this.onRcvGetOnlineCoin, false, this);
    },

    start() {

    },

    //nType:1 login 2 activity
    showType: function (nType) {
        this._showType = nType
        for (let i = 0; i < this._loginList.length; i++) {
            let bShow = nType == 1
            let item = this._loginList[i]
            item.active = bShow
            if (bShow) {
                item.opacity = 0
                cc.tween(item)
                    .delay(i * 0.15)
                    .to(0.2, { opacity: 255 })
                    .start()
            }
        }
        for (let i = 0; i < this._activityList.length; i++) {
            let bShow = nType == 2
            let item = this._activityList[i]
            item.active = bShow
            if (bShow) {
                item.opacity = 0
                cc.tween(item)
                    .delay(i * 0.15)
                    .to(0.2, { opacity: 255 })
                    .start()
            }
        }

        this.sendBonusInfo()
    },



    //显示活动信息
    showActivityInfo: function () {
        this.showFrienzy()
        this.showQuest()
        this.showBingo()
        this.showExplore()
        this.node_share.getComponent("bonus_activity_FBWheel").show(this._activityInfo.fb)
    },

    //刮刮乐
    showFrienzy: function () {
        let self = this
        let info = this._activityInfo.online
        let nodeFrienzy = cc.find("src/view/content/frenzy", this.node)
        Global.setLabelString("lay_per_share/val", nodeFrienzy, Global.FormatNumToComma(info.coin))
        let bCollect = (info.time == 0)
        let btn_collect = cc.find("btn_collect", nodeFrienzy)
        btn_collect.active = bCollect
        // let btn_go = cc.find("btn_go",nodeFrienzy)
        // btn_go.active = !bCollect
        let lblTime = cc.find("retimer_bg", nodeFrienzy)
        lblTime.active = !bCollect
        if (!bCollect) {
            let lblVal = cc.find("lbl_screch/lbl_timer", lblTime)
            let timeEndCall = function () {
                self._activityInfo.online.time = 0
                self.showFrienzy()
            }
            lblVal.getComponent("ReTimer").setReTimer(info.time, 1, timeEndCall)
        }

        //富豪庭是否加成
        let bActive = info.palace && info.palace.open
        Global.showSpriteGray(cc.find("palace_mult/icon", nodeFrienzy), !bActive)
        let lbl_palace1 = cc.find('palace_mult/val', nodeFrienzy)
        lbl_palace1.color = bActive ? cc.Color(236, 224, 141) : cc.Color(125, 125, 125)
        let lbl_palace2 = cc.find('palace_mult/lbl_text', nodeFrienzy)
        lbl_palace2.color = bActive ? cc.Color(236, 224, 141) : cc.Color(125, 125, 125)

        //当前倍数
        let nMaxMul = 10
        let curBaseMul = info.mult
        this._scrachBaseMul = curBaseMul
        let lbl_mul_tip = cc.find("node_g_multer/mul_next", nodeFrienzy)
        lbl_mul_tip.active = (curBaseMul != nMaxMul)
        lbl_mul_tip.getComponent(cc.Label).string = cc.js.formatStr("SPIN %s TIMES GET NEXT MULTIPLIER", info.rest)
        let mulPro = cc.find("node_g_multer/pro", nodeFrienzy)
        if (curBaseMul == nMaxMul) {
            mulPro.getComponent(cc.ProgressBar).progress = 1
        }
        else {
            mulPro.getComponent(cc.ProgressBar).progress = (curBaseMul - 1) * 0.2 + info.percent / 500
        }

        //倍数刷新倒计时
        let lblMulTime = cc.find("node_g_multer/mul_timer", nodeFrienzy)
        let timeEndCall2 = function () {
            self._activityInfo.resetTime = 0
            self.showFrienzy()
        }
        lblMulTime.getComponent("ReTimer").setReTimer(info.resetTime, 1, timeEndCall2)

    },

    onClickFrienzyCollect: function () {
        Global.playComEff("ch_btn_click");

        this.sendCollectFrenzyReq()



        cc.vv.RedSys.clearRedTip(1)
    },

    //发送领取奖励协议
    sendCollectFrenzyReq: function () {
        var req = { 'c': MsgId.REQ_GET_ONLINE_COIN };
        req.rtype = 1;
        cc.vv.NetManager.send(req);
    },

    onClickFrienzyQuestMark: function () {
        Global.playComEff("ch_btn_click");
        cc.vv.UserManager.goSystemUI("heropalace")
    },

    showQuest: function () {
        let info = this._activityInfo.gametask
        if (info) {
            let questNode = cc.find("src/view/content/quest", this.node)
            Global.setLabelString("coin_bg/val", questNode, Global.FormatNumToComma(info.maxcoin))
            let lbl_timer = cc.find("timer", questNode)
            let endTime = info.begintime + info.duration
            let nowTime = new Date().getTime()
            let dif = endTime - nowTime / 1000
            let day = Math.floor(dif / (24 * 3600))
            if (day > 0) {
                Global.setLabelString("val", lbl_timer, cc.js.formatStr("End in %sd", day))
            }
            else {
                let lbl_val = cc.find("val", lbl_timer)
                let timeEndCall = function () {
                    cc.vv.PopUIMgr.delLoginPopId(11)
                    self._hideActivityItem(this.questNode)
                }
                lbl_val.getComponent("ReTimer").setReTimer(dif, 1, timeEndCall)

            }
        }



    },

    onClickQuestGo: function () {
        Global.playComEff("ch_btn_click");
        cc.vv.RedSys.clearRedTip(9)
        cc.vv.NetManager.send({ c: MsgId.REQ_QUEST_INFO })
    },

    onClickSmashGo: function () {
        Global.playComEff("ch_btn_click");
        let url = "CashHero/prefab/lucky_smash/lucky_main"
        this._loadPrefab(url, (prefab) => {
            let parNode = cc.find("Canvas")
            if (parNode.getChildByName("lucky_main")) {
                return
            }
            let node = cc.instantiate(prefab)
            node.parent = parNode

        })
    },

    onClickFlipGo: function () {
        Global.playComEff("ch_btn_click");
        let url = "CashHero/prefab/luck_card/CH_Luckycard"
        this._loadPrefab(url, (prefab) => {
            let parNode = cc.find("Canvas")
            if (parNode.getChildByName("CH_Luckycard")) {
                return
            }
            let node = cc.instantiate(prefab)
            node.parent = parNode

        })
    },

    showBingo: function () {

        let info = this._activityInfo.bingo
        if (info) {
            let bingoNode = cc.find("src/view/content/bingo", this.node)
            Global.setLabelString('coin_bg/val', bingoNode, info.num)
        }

    },

    onClickBingoGo: function () {
        Global.playComEff("ch_btn_click");
        let self = this
        let url = "CashHero/prefab/bingo/bingo_main"
        this._loadPrefab(url, (prefab) => {
            let parNode = cc.find("Canvas")
            if (parNode.getChildByName("bingo_main")) {
                return
            }
            let node = cc.instantiate(prefab)
            node.parent = parNode
            let refushCall = function () {
                self.sendBonusInfo()
            }
            node.addComponent("NodeLifeCallBack").setDestroyCall(refushCall)
        })
    },

    showExplore: function () {
        let info = this._activityInfo.journey
        if (info) {
            let knightNode = cc.find("src/view/content/knight", this.node)
            Global.setLabelString('coin_bg/val', knightNode, info.num)
        }

    },

    onClickKnightGo: function () {
        Global.playComEff("ch_btn_click");
        let self = this
        let url = "CashHero/prefab/exploration/explore_main"
        this._loadPrefab(url, (prefab) => {
            let parNode = cc.find("Canvas")
            if (parNode.getChildByName("explore_main")) {
                return
            }
            let node = cc.instantiate(prefab)
            node.parent = parNode
            let refushCall = function () {
                self.sendBonusInfo()
            }
            node.addComponent("NodeLifeCallBack").setDestroyCall(refushCall)
        })
    },

    onClickCardTrailGo: function () {
        Global.playComEff("ch_btn_click");
        let url = "CashHero/prefab/month_card"
        this._loadPrefab(url, (prefab) => {
            let parNode = cc.find("Canvas")
            if (parNode.getChildByName("month_card")) {
                return
            }
            let node = cc.instantiate(prefab)
            node.parent = parNode

        })
    },


    //bonus信息
    sendBonusInfo: function () {
        let req = { c: MsgId.REQ_HALL_TAB_BONUS }
        req.online = 1
        req.fb = 1
        req.luckcard = 1
        req.bingo = 1
        req.journey = 1
        req.sign = 1
        req.gametask = 1
        cc.vv.NetManager.sendAndCache(req)
    },

    onRcvNeActivityListInfo: function (msg) {
        if (msg.code == 200) {
            this._activityInfo = msg
            this.showActivityInfo()
        }
    },

    _loadPrefab: function (url, callbacks) {
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                callbacks(prefab)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    _hideActivityItem: function (node) {
        let findKey = null
        for (let i = 0; i < this._loginList.length; i++) {
            let item = this._loginList[i]
            if (item == node) {
                findKey = i
                node.active = false
                break
            }
        }
        if (findKey != null) {
            this._loginList.splice(findKey, 1)
            return
        }
        for (let i = 0; i < this._activityList.length; i++) {
            let item = this._activityList[i]
            if (item == node) {
                findKey = i
                node.active = false
                break
            }
        }
        if (findKey != null) {
            this._activityInfo.splice(findKey, 1)
        }
    },

    onRcvGetOnlineCoin: function (msg) {
        if (msg.code == 200) {
            cc.vv.UserManager.SetCoin(msg.coin)

            this._showScratchAni(msg)
        }
    },

    _showScratchAni: function (msg) {
        let self = this
        let url = "CashHero/prefab/frenzy_pop"
        this._loadPrefab(url, (prefab) => {
            let parNode = cc.find("Canvas")
            if (parNode.getChildByName("frenzy_pop")) {
                return
            }
            let node = cc.instantiate(prefab)
            node.parent = parNode
            let tempCard = cc.find("src/view/content/frenzy/temp_icon", self.node)
            let wordPos = tempCard.convertToWorldSpaceAR(cc.v2(0, 0))
            tempCard.active = false
            node.getComponent("bonus_frenzy_pop").setData(wordPos, msg, self._scrachBaseMul)
            let refushCall = function () {
                self._activityInfo.online.time = self._activityInfo.online.total
                self.showFrienzy()
                if (cc.isValid(tempCard)) {
                    tempCard.active = true
                }
            }
            node.addComponent("NodeLifeCallBack").setDestroyCall(refushCall)
        })
    },

    // update (dt) {},
});
