/**
 * Quest loading
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.RedSys.clearRedTip(9)

        cc.vv.NetManager.registerMsg(MsgId.REQ_QUEST_INFO, this.OnRcvNetQuestInfo, this);
    },
    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_QUEST_INFO, this.OnRcvNetQuestInfo, false, this);
    },

    //设置要回到哪里
    //nType:1quest 2 hall
    setBackType(nType) {
        this._goType = nType
    },

    start() {
        this._time = 0
        this.loadNextScene()
        //到大厅就不需要请求
        if (this._goType == 2) {
            this._bReqInfo = true
        }
        else {
            this.reqQuestInfo()
        }


        cc.vv.AudioManager.stopBgm();
        Global.playCashEff("quest/loading");
    },


    loadNextScene() {
        let self = this
        let goScene = this._getEnterScene()
        cc.director.preloadScene(goScene, (err, data) => {
            self._bLoaded = true
        })
    },

    reqQuestInfo() {
        cc.vv.NetManager.send({ c: MsgId.REQ_QUEST_INFO })

    },

    enterQuest() {

        if (!this._entering) {
            this._entering = true
            let goScene = this._getEnterScene()
            cc.vv.SceneMgr.enterScene(goScene, null, Global.APP_ORIENTATION)

        }
    },

    OnRcvNetQuestInfo: function (msg) {
        if (msg.code == 200) {

            cc.vv.UserManager.setQuestInfo(msg)
            console.log('OnRcvNetQuestInfo:', msg)
            this._bReqInfo = true
        }
    },

    _getEnterScene: function () {
        let goScene
        if (this._goType == 1) {
            goScene = Global.SCENE_NAME.QUEST
        }
        else if (this._goType == 2) {
            goScene = Global.SCENE_NAME.HALL
        }
        return goScene
    },



    update(dt) {
        this._time += dt
        if (this._bLoaded && this._time > 2 && this._bReqInfo) {
            this.enterQuest()
        } else if (this._time > 10) {  //超时，强制进入大厅（QA反馈若在QUEST界面停留很久，则返回大厅时有概率卡住，怀疑时时间过长，网络断开了，this._bReqInfo一直不能为ture，所以卡在了loading界面）
            this._goType = 2
            this.enterQuest()
        }
    },

});
