/**
 * 主场景资源
 */
cc.Class({
    extends: cc.Component,

    properties: {
    },

    onLoad() {
        this.bg = this.node.getChildByName("bg");
        this.logo = this.node.getChildByName("logo");
        this.slots = this.node.getChildByName("slots");
        this.slots777 = this.node.getChildByName("LMSlots_Subgame777");
        this.character_node = this.slots.getChildByName("character_node");
        this.collect_progress = this.slots.getChildByName("collect_progress");
        this.extra_bonus_node = this.slots.getChildByName("extra_bonus_node")
        this.popup_node = this.node.getChildByName("popup_node");
        this.map_node = this.node.getChildByName("map_node");
        this.wild_game = this.slots.getChildByName("wild_game");
        this.wheel_game_node = this.node.getChildByName("wheel_game_node");
        this.transition_node = this.node.getChildByName("transition_node");
        this.jpNode = this.node.getChildByName("LMSlots_PrizePool_1");
        this.top_node = this.node.getChildByName("top_node");
        this.respin_game_node = this.node.getChildByName("respin_game_node");
        this.respin_start = this.slots.getChildByName("respin_start");
        this.showBg(0);
    },

    /**
     * 显示免费背景
     * type 背景类型 0-普通游戏 1-respin 2-免费
     */
    showBg(type) {
        if (!type) {
            type = 0;
        }
        this.bg.getComponent("ImgSwitchCmp").setIndex(type);
        // cc.find("effect1", this.bg).active = type == 0;
        cc.find("effect2", this.bg).active = type == 1;
        this.collect_progress.active = type == 0;
        this.logo.active = type == 0 || type == 1;
        // cc.vv.gameData.showOtherSysNode(type !== 1);
    },

    /**
     * 幕布转场动画
     * @param {*} type
     * @param {*} cmpHandler 
     */
    async showSceneTransition(type) {
        let soundName = "";
        let animationName = "idle2";
        if (type == 1) {
            soundName = "transition_free";
        } else if (type == 2) {
            soundName = "transition_bonus";
        }
        SlotsFacade.soundMgr.playEffect(soundName);
        let spine = this.transition_node.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, animationName, false);
        await SlotsFacade.delayTime(1);
    },

    /**
     * 开始 respin游戏动画
     */
    async playRespinStarAni() {
        SlotsFacade.soundMgr.playEffect("bonus_start_show");
        await new Promise((res) => {
            this.respin_start.active = true;
            let spine = this.respin_start.getChildByName("spine").getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation", false);
            spine.setCompleteListener(() => {
                spine.setCompleteListener(null);
                this.respin_start.active = false;
                res();
            });
        });
    }
})