/**
 * 大厅-社交
 */

let BSELIDX = {
    ALL: 1,
    GIFT: 3,
    RANK: 5,
    PRIVATE: 6,
    FRIENDS: 7,
};

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let menu_channel = cc.find("channel", this.node)
        let btnGlobal = cc.find('global', menu_channel)
        Global.btnClickEvent(btnGlobal, this.onClickAllBtn, this)
        let btnGift = cc.find('gift', menu_channel)
        Global.btnClickEvent(btnGift, this.onClickGiftBtn, this)
        // let btnRank = cc.find('rank',menu_channel)
        // Global.btnClickEvent(btnRank,this.onClickRankBtn,this)
        // let btnPrivate = cc.find('channel/private',this.node)
        // Global.btnClickEvent(btnPrivate,this.onClickPrivateBtn,this)
        let btnFriends = cc.find('friends', menu_channel)
        Global.btnClickEvent(btnFriends, this.onClickFriendsBtn, this)
        let btnArrow = cc.find('btn_arrow', menu_channel)
        Global.btnClickEvent(btnArrow, this.onClickArrow, this)
        let btnEmpty = cc.find('btn_empty', this.node)
        btnEmpty.active = false
        Global.btnClickEvent(btnEmpty, this.onClickArrow, this)

        Global.registerEvent(EventId.OPEN_HALL_FRIENDS, this.onEventFriendPage, this)

        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, false, this);
    },

    start() {
        this._bExpand = false
        this.onClickArrow()
        let idx = BSELIDX.ALL
        if (!this._defaultTab) {
            this._defaultTab = "channel/global"
            idx = BSELIDX.ALL
        }
        else if (this._defaultTab == "channel/friends") {
            idx = BSELIDX.FRIENDS
        }
        this._showTab(cc.find(this._defaultTab, this.node), idx)
    },

    onClickAllBtn: function (event) {

        Global.playComEff("ch_btn_click");

        this._showTab(event.node, BSELIDX.ALL)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_CHAT_GLOBAL)
        let node_chat = cc.find("page_chat", this.node)
        node_chat.getComponent("CH_PageChat")._showMsgByType(BSELIDX.ALL)
    },

    onClickGiftBtn: function (event) {

        Global.playComEff("ch_btn_click");
        this._showTab(event.node, BSELIDX.GIFT)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_CHAT_GIFT)
        let node_chat = cc.find("page_chat", this.node)
        node_chat.getComponent("CH_PageChat")._showMsgByType(BSELIDX.GIFT)
    },

    onClickFriendsBtn: function (event) {
        Global.playComEff("ch_btn_click");
        this._showTab(event.node, BSELIDX.FRIENDS)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_CHAT_GIFT)
    },

    _showTab: function (node, idx) {
        if (this._curSel == idx) return;

        this._curSel = idx
        let node_chat = cc.find("page_chat", this.node)
        let node_friend = cc.find("page_friend", this.node)
        node_chat.active = (idx == BSELIDX.ALL) || (idx == BSELIDX.GIFT)
        node_friend.active = (idx == BSELIDX.FRIENDS)

        // //点完后隐藏
        // let self = this
        // let endCall = function(){
        //     self.onClickArrow()
        // }
        this._showSelTab(node)
    },

    _showSelTab: function (node, endCall) {
        // let obj = cc.find('channel/sel_bg', this.node)

        // obj.active = true
        // cc.tween(obj)
        // .to(0.2,{y:node.y})
        // .delay(0.1)
        // .call(()=>{
        //     if(endCall){
        //         endCall()
        //     }
        // })
        // .start()

        //
        let func = function (obj, bShow) {
            let selImg = cc.find('icon_light', obj)
            let unselImg = cc.find('icon_gray', obj)
            let lbl = cc.find('Label', obj)
            selImg.active = bShow
            unselImg.active = !bShow
            lbl.color = !bShow ? new cc.Color().fromHEX("#ffffff") : new cc.Color().fromHEX("#52FFC6")
        }
        if (this._preSelBtn) {
            func(this._preSelBtn, false)
        }
        func(node, true)
        this._preSelBtn = node

        if (endCall) endCall()
    },

    onClickArrow: function (bWithAudio) {
        if (bWithAudio) {
            Global.playComEff("ch_btn_click");
        }


        this._bExpand = !this._bExpand
        let tarPosx = this._bExpand ? 433.5 : 612
        // if(cc.sys.platform == cc.sys.IPAD){
        //     tarPosx = this._bExpand?cc.winSize.width/2-107:cc.winSize.width/2+95
        // }
        let nodeChannel = cc.find("channel", this.node)
        cc.tween(nodeChannel)
            .to(0.2, { x: tarPosx })
            .start()
        let arrow = cc.find('btn_arrow/arrow', nodeChannel)
        arrow.scaleX = this._bExpand ? -1 : 1
        let btnEmpty = cc.find('btn_empty', this.node)
        btnEmpty.active = this._bExpand
        arrow.x = 23
        Global.ArrowAction(arrow, cc.v2(15, 0), 0.5)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_CHAT_ARROW)
    },

    onRcvPersonInfo: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode == 423) {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_not_find_friendsinfo);
                // cc.vv.FloatTip.show('No friend information found');
                return
            }

            else if (msg.act == 1 || msg.act == 2) {
                //detail
                cc.loader.loadRes("CashHero/prefab/friend/CH_friend_detail", cc.Prefab, (err, prefab) => {
                    if (!err) {
                        let parentNode = cc.find("Canvas")
                        let oldNode = parentNode.getChildByName('CH_friend_detail')
                        if (!oldNode) {
                            let node = cc.instantiate(prefab);
                            node.parent = parentNode;
                            node.getComponent('CH_FriendsDetail').init(msg.playerInfo.uid, msg)

                        }
                        else {
                            oldNode.active = true
                            oldNode.getComponent('CH_FriendsDetail').init(msg.playerInfo.uid, msg)
                        }
                    }
                });
            }

        }
    },

    onEventFriendPage: function (data) {
        let val = data && data.detail
        if (val == "chat") {
            this._defaultTab = "channel/global"
            let node = cc.find("channel/global", this.node)
            this._showTab(node, BSELIDX.ALL)
        }
        else {
            this._defaultTab = "channel/friends"
            let node = cc.find("channel/friends", this.node)
            this._showTab(node, BSELIDX.FRIENDS)
        }

    }

    // update (dt) {},
});
