
cc.Class({
    extends: cc.Component,

    properties: {
        _lblTime: null
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_PVP_MATCH, this.onRcvPvpMatch, this)
        Global.registerEvent("pvp_rank_score_update", this.onUpdateRankScore, this)
        Global.registerEvent("pvp_ticket_update", this.onUpdateTicket, this)

        this._lblTime = cc.find("bottom/bg_chlg_num/lbl_fresh_time", this.node).getComponent(cc.Label)
        Global.onClick("bottom/btn_close", this.node, this.onClickClose, this)
        Global.onClick("bottom/btn_add", this.node, this.onClickBuy, this)
    },

    onEnable() {
        this.onUpdateRankScore()
        cc.vv.NetManager.send({ c: MsgId.REQ_PVP_MATCH })
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PVP_MATCH, this.onRcvPvpMatch, false, this)
    },

    onUpdateRankScore() {
        Global.setLabelString("top/lbl_point", this.node, cc.vv.UserManager.getPvpScore())
        //Global.setLabelString("top/lbl_cc", this.node, cc.vv.UserManager.getPvpCC())
    },

    onBattleClose() {
        this.node.active = true
        Global.unregisterEvent("pvp_battle_close", this.onBattleClose, this)
    },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.active = false
        cc.find("ranking", this.node.parent).active = true
    },

    onClickBuy() {
        let url = 'CashHero/prefab/pvp/pvp_buy'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.find('Canvas').getChildByName('pvp_buy')
                if (!node) {
                    node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                }
            }
        });
    },

    async onClickFight(event) {
        if (this._restCnt <= 0) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_insufficient_challenges);
            // cc.vv.FloatTip.show("Insufficient challenges")
            return
        }
        let positionCount = cc.vv.HerocardManager.getPvpTeamPositionSize()
        if (positionCount <= 0) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_unlock_position_first);
            // cc.vv.FloatTip.show("You need to unlock a formation position first")
            return
        }

        let useFormation = true //是否使用组队界面，暂时直接使用防守阵容
        if (useFormation) {
            let tag = event.node.userTag
            let data = this._listData[tag]
            if (data) {
                this.node.active = false
                let formation = cc.find("formation", this.node.parent)
                formation.active = true
                formation.getComponent("Pvp_Formation").init(data, 0)
            }
        } else {
            let cardids = cc.vv.UserManager.getPvpDefendTeam()
            if (!cardids || cardids.length < 1) {
                //如果没有设置防守队伍，则自动把排名前5的卡牌组成进攻队伍
                let cardlist = cc.vv.HerocardManager.getUnlockedCardList(true)
                if (cardlist.length <= 0) {
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_required_unlocked_card);
                    // cc.vv.FloatTip.show("At least one unlocked hero card is required")
                    return
                }
                cardlist.sort((a, b) => {
                    return b.lv - a.lv
                })
                cardids = []
                for (let i = 0; i < positionCount && i < cardlist.length; i++) {
                    cardids.push(cardlist[i].cardid)
                }
            }

            let tag = event.node.userTag
            let data = this._listData[tag]
            if (data) {
                await new Promise((resolve) => {
                    let url = 'CashHero/prefab/pvp/pvp_enter'
                    cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                        if (!err) {
                            let node = cc.find('Canvas').getChildByName('pvp_enter')
                            if (!node) {
                                node = cc.instantiate(prefab)
                                node.parent = cc.find('Canvas')
                            }
                            node.getComponent("Pvp_Enter").init(data, cardids, 0)
                        }
                        resolve()
                    })
                })
                this.node.active = false
            }
        }
        Global.registerEvent("pvp_battle_close", this.onBattleClose, this)
    },

    onUpdateTicket(data) {
        this._restCnt = data.detail
        Global.setLabelString("bottom/bg_chlg_num/lbl_num", this.node, this._restCnt)
    },

    refreshList() {
        let content = cc.find("list_match/view/content", this.node)
        let itemTemp = cc.find("list_match/match_item", this.node)
        content.removeAllChildren()
        for (let i = 0; i < this._listData.length; i++) {
            let data = this._listData[i]
            let item = cc.instantiate(itemTemp)
            cc.find("node_head", item).getComponent("UserHead").setHead(data.uid, data.usericon)
            Global.setLabelString("lbl_name", item, data.playername)
            Global.setLabelString("lbl_cc", item, data.cc)
            Global.setLabelString("lbl_point", item, data.score)
            item.active = true
            let btnFight = cc.find("btn_fight", item)
            btnFight.userTag = i
            btnFight.on("click", this.onClickFight, this)
            content.addChild(item)
            item.opacity = 0
            item.runAction(cc.sequence(cc.delayTime(0.1 * i), cc.fadeIn(0.2).easing(cc.easeSineIn(2))))
        }
    },

    onRcvPvpMatch(msg) {
        if (msg && msg.code == 200) {
            let isEnd = (msg.spcode != 0)
            if (msg.spcode == 0) {
                this._listData = msg.opponents
                this._restCnt = msg.fightInfo.restCnt
                this._refreshTime = msg.fightInfo.refreshTime
            } else {
                this._listData = []
                this._restCnt = 0
                this._refreshTime = 0
                this._lblTime.string = ""
            }
            this.refreshList()
            Global.setLabelString("bottom/bg_chlg_num/lbl_num", this.node, this._restCnt)
            cc.find("bottom/btn_add", this.node).active = !isEnd
            cc.find("lbl_end", this.node).active = isEnd
        }
    },

    update(dt) {
        if (this._refreshTime && this._refreshTime > 0) {
            this._refreshTime -= dt
            this._lblTime.string = cc.vv.Language.pvp_des2/*"REFRESH IN "*/ + Global.formatSec(Math.floor(this._refreshTime))
        }
    },
});
