cc.Class({
    extends: cc.Component,

    properties: {
        _shopInfo: null,
    },

    onLoad() {
        Global.btnClickEvent(cc.find("bg/btn_open", this.node), this.onOpenReCharge, this);
        Global.btnClickEvent(cc.find("bg/btn_close", this.node), this.onCloseUI, this);
        Global.btnClickEvent(cc.find("bg/text_money_bank_title/btn_tip", this.node), this.onClickTip, this);
        Global.btnClickEvent(cc.find("node_tip", this.node), this.onCloseTip, this);
        Global.btnClickEvent(cc.find("bg/palace_point_tip/btn_go", this.node), this.onClickGoPalace, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_MONEYBANK, this.onRcvMoneybank, this);
        cc.vv.NetManager.registerMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_PIGBANK_FREEOPEN, this.onRcvMsgOpenFree, this);
        Global.FixDesignScale_V(this.node)
    },

    onEnable() {
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
        Global.playComEff("ch_popup");
    },

    start() {
        // this.openMoneybank();
        var msg = { c: MsgId.REQ_GET_MONEYBANK };
        msg.platform = 1;
        if (Global.isIOS()) {
            msg.platform = 2
        }
        cc.vv.NetManager.send(msg);
        let nScale = this.node.scale
        Global.showAlertAction(this.node, true, 0.1, nScale, null);
        cc.vv.PlatformApiMgr.KoSDKTrackEvent('MoneyBankUI', JSON.stringify({ uid: Global.playerData.uid }))
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_POP)
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_MONEYBANK, this.onRcvMoneybank, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PIGBANK_FREEOPEN, this.onRcvMsgOpenFree, false, this);
    },

    //接收服务器消息
    onRcvMoneybank(msg) {
        if (msg.code === 200) {
            this._shopInfo = msg.shopInfo[0];
            //初始金币
            let initcoin = this._shopInfo.ext.bagCnt
            let addcoin = this._shopInfo.ext.bankedCnt
            let maxCount = this._shopInfo.ext.maxCnt
            let firstcoin = this._shopInfo.ext.firstCnt
            let bFree = this._shopInfo.ext.free
            let priceLbl = cc.find('bg/btn_open/lbl_price', this.node)
            priceLbl.getComponent(cc.Label).string = bFree ? 'FREE TO BREAK' : 'BREAK BY $1.99'
            let lblinit = cc.find('node_tip/spr_ui_bg/content/init_coin/lbl_coin', this.node)
            lblinit.getComponent(cc.Label).string = Global.FormatNumToComma(initcoin)
            let lbladd = cc.find('node_tip/spr_ui_bg/content/maxi_coin/lbl_coin', this.node)
            lbladd.getComponent(cc.Label).string = Global.FormatNumToComma(addcoin)
            let lbltotal = cc.find('bg/total_coin/lbl_coin', this.node)
            lbltotal.getComponent(cc.Label).string = Global.FormatNumToComma(initcoin + addcoin + firstcoin)
            //firstcoin
            let firstNode = cc.find('node_tip/spr_ui_bg/content/first_coin', this.node)
            firstNode.active = firstcoin > 0
            let firstadd = cc.find('node_tip/spr_ui_bg/content/spr_add1', this.node)
            firstadd.active = firstcoin > 0
            let lblfirst = cc.find('node_tip/spr_ui_bg/content/first_coin/lbl_coin', this.node)
            lblfirst.getComponent(cc.Label).string = Global.FormatNumToComma(firstcoin)
            let bAddMax = addcoin >= maxCount
            let addPer = (firstcoin + addcoin) / initcoin + 1
            // let sprmax = cc.find('bg/node_content/maxi_coin/spr_max',this.node)
            // let sprspin = cc.find('bg/node_content/maxi_coin/spr_spin',this.node)
            // let maxLabel = cc.find('bg/node_content/maxi_coin/small_title_bg/title_max',this.node)
            // let saveLabel = cc.find('bg/node_content/maxi_coin/small_title_bg/title_saved',this.node)
            let btnMaxicon = cc.find('bg/max', this.node)
            let lblAddPer = cc.find('bg/btn_open/more/lbl_more', this.node)
            // sprmax.active = bAddMax
            // sprspin.active = !bAddMax
            // maxLabel.active = bAddMax
            // saveLabel.active = !bAddMax
            btnMaxicon.active = bAddMax
            if (btnMaxicon.active) {
                btnMaxicon.opacity = 0
                btnMaxicon.scale = 3
                cc.tween(btnMaxicon)
                    .to(0.15, { opacity: 255, scale: 2 })
                    .to(0.15, { scale: 1 })
                    .call(() => {
                        Global.playCashEff("pigbank/full_cover")
                    })
                    .start()
            }
            lblAddPer.getComponent(cc.Label).string = Math.floor(addPer * 100) + "%"
            //benifist
            let btn = cc.find("bg/btn_benifist", this.node)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._shopInfo.rewards, '金猪权益')
            let bActive = 0
            let placeData = cc.vv.UserManager.getBetData()
            if (placeData) {
                bActive = placeData.open
            }
            let place_node = cc.find("bg/palace_point_tip", this.node)
            Global.showSpriteGray(cc.find("icon", place_node), !bActive)
            let lbl_palace1 = cc.find('lbl_desc', place_node)
            lbl_palace1.color = bActive ? cc.Color(255, 255, 255) : cc.Color(213, 213, 213)
        }
    },

    //监听支付成功回调
    //支付校验成功
    onRcvMsgCheckOrder: function (msg) {
        this._bClick = null
        if (msg.code === 200) {
            //清理满的状态
            Global.dispatchEvent(EventId.REFUSH_PIG_BANK);
            this.node.destroy();
        }
    },

    //打开充值
    onOpenReCharge() {
        if (this._shopInfo == null) { return; }
        if (this._bClick) { return }
        this._bClick = true
        if (this._shopInfo.ext.free) {
            //打点
            StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_FREE)
            //免费
            cc.vv.NetManager.send({ c: MsgId.REQ_PIGBANK_FREEOPEN })
        }
        else {
            //打点
            StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_BUY)
            //正常
            console.log('打开充值:' + this._shopInfo.id)
            cc.vv.PayMgr.reqPurchaseOrder(this._shopInfo.id);
        }
    },

    //关闭界面
    onCloseUI() {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_POP)
        Global.playComEff("ch_close");
        this.node.destroy();
    },

    onClickTip: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_RULE)
        Global.playComEff("ch_notification");
        let nodeTip = cc.find('node_tip', this.node)
        nodeTip.active = true
    },

    onCloseTip: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_PIGBANK_RULE_CLOSE)
        let nodeTip = cc.find('node_tip', this.node)
        nodeTip.active = false
        Global.playComEff("ch_close");
    },

    onRcvMsgOpenFree: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode != 0) {
                //出错了
                return
            }
            //清理满的状态
            Global.dispatchEvent(EventId.REFUSH_PIG_BANK);
            let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
            let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
            if (cc.vv.gameData) {
                toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
                endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
                cc.vv.gameData.setCoins(msg.coin)
                Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_UPDATE_BALANCE)
            }
            else {
                cc.vv.UserManager.SetCoin(msg.coin, true)
            }
            let rollData = {}
            rollData.lblCoin = toLbl;
            rollData.addCoin = msg.addcoin;
            rollData.begin = (msg.coin - msg.addcoin)
            let self = this
            let endCall = function () {
                //主动关闭界面
                // cc.vv.NetManager.dispatchNetMsg({
                //     c: MsgId.MONEY_CHANGED,
                //     code: Global.ERROR_CODE.NORMAL,
                //     coin: msg.coin,
                //     count: msg.addcoin,
                //     type:1,
                // });
                if (self.node && cc.isValid(self.node)) {
                    self.node.destroy();
                }
            }
            Global.FlyCoin(cc.find('bg/total_coin/lbl_coin', this.node), endNode, endCall, rollData, true)
        }
    },

    onClickGoPalace: function () {
        Global.playComEff("ch_btn_click");
        cc.vv.UserManager.goSystemUI("heropalace")
    }

});
