/**
 * vip icon
 */
cc.Class({
    extends: cc.Component,

    properties: {
        vipatlas: cc.SpriteAtlas,
        vip_title: cc.Sprite,
        vip_name: cc.Label,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    showVip: function (vipLv) {
        this.node.getComponent(cc.Sprite).spriteFrame = this._getVipSpriteFrame(vipLv)
        if (this.vip_title) {
            this.vip_title.spriteFrame = this._getVipTitleFrame(vipLv)
        }
        if (this.vip_name) {
            this.vip_name.string = this._getVipNamestring(vipLv)
        }
    },

    _getVipSpriteFrame: function (lv) {

        let fileName = cc.js.formatStr("0%s", lv)
        let res = this.vipatlas.getSpriteFrame(fileName)
        if (!res) {
            res = this.vipatlas.getSpriteFrame("01")
        }
        return res
    },

    _getVipTitleFrame: function (lv) {
        let fileName = cc.js.formatStr("vip_%s_tile", lv)
        let res = this.vipatlas.getSpriteFrame(fileName)
        if (!res) {
            res = this.vipatlas.getSpriteFrame("01")
        }
        return res
    },

    _getVipNamestring: function (lv) {
        let cfg = Global.VIP_INFO[lv]
        return cfg.name
    },

    // update (dt) {},
});
