/**
 * 场次选择
 */
// let itemsListCfg = require("GameItemCfg");

cc.Class({
    extends: cc.Component,

    properties: {
        _curMidx: 0,
        _curGameId: null,
        _curIdx: 0, //在已解锁列表中的序号
        _betTab: 0,  //0 普通，1 高倍场
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('btn_close', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)
        let btn_r = cc.find('btn_right', this.node)
        Global.btnClickEvent(btn_r, this.onClickRight, this)
        let btn_l = cc.find('btn_left', this.node)
        Global.btnClickEvent(btn_l, this.onClickLeft, this)

        let btn_go = cc.find('text_tip/btn_go', this.node)
        Global.btnClickEvent(btn_go, this.onClickGoPalace, this)

        //隐藏押注按钮
        // cc.find('mid0/bg_cont', this.node).active = false
        // cc.find('mid1/bg_cont', this.node).active = false
        // cc.find('bg_cont', this.node).active = false

        //是否能点击左右按钮
        this.isClickLeftRight = true

        //是否点击了押注按钮 点击了才能进游戏
        this.isClickBetBtn = false

        Global.registerEvent("checkSubFinish", this.downloadingFinish, this);
        Global.registerEvent("enter_game", this.downloadingFinish, this);
        // cc.vv.NetManager.registerMsg(MsgId.REQ_HALLBETS_SELECT, this.onRcvHallBetsinfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_HEROCARD_RANK, this.onRcvHeroCardRank, this);//英雄卡牌排行榜
    },

    onDestroy() {
        // cc.vv.NetManager.unregisterMsg(MsgId.REQ_HALLBETS_SELECT, this.onRcvHallBetsinfo, false, this);
        // cc.loader.releaseRes("CashHero/prefab/Bet_Select", cc.Prefab);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HEROCARD_RANK, this.onRcvHeroCardRank, false, this);
    },

    start() {
        //请求押注列表
        // this.reqBetlists()
        this._betData = cc.vv.UserManager.getBetData()
        this.initBet()
        this.autoUpdate()
    },

    init: function (itemData) {
        this._curGameData = itemData
        this._curMidx = 0
        this._allUnlockGames = cc.vv.UserManager.getUnlockGames()
        for (let i = 0; i < this._allUnlockGames.length; i++) {
            let item = this._allUnlockGames[i]
            if (item.id == itemData.id) {
                this._curIdx = i
                break
            }
        }
        this.showGameIcon(this._curMidx, itemData)
        this.setMaxCoin()
        this.showGameLevel(this._curMidx, itemData);
        this.showRank(this._curMidx, itemData);
    },

    setMaxCoin() {
        let nodeGrand = cc.find('maxLabel', this.node)
        let script = nodeGrand.getComponent('LMSlotMachine_PrizePool')
        if (script) {
            script.init(this._curGameData.id, cc.vv.AppData.getMaxBet());
        }
    },

    initBtn() {
        // cc.find('bg_cont', this.node).active = true
        let btn_nor = cc.find('btn_reg', this.node)
        let btn_hig = cc.find('btn_high', this.node)
        btn_nor.on('click', this.onClickBetTabNor, this)
        btn_hig.on('click', this.onClickBetTabHigh, this)

        //是否解锁
        let bOpen = this._betData.open
        let nodeLock = cc.find('spr_locker', btn_hig)
        nodeLock.active = !bOpen
    },

    btnMask(flag) {
        cc.find('btn_reg/lock_gray', this.node).active = !flag
        cc.find('btn_high/lock_gray', this.node).active = flag
    },

    // reqBetlists:function(){
    //     cc.vv.NetManager.send({c:MsgId.REQ_HALLBETS_SELECT})
    // },

    setMidInfo: function (idx, data, ani) {
        this._curGameData = data
        let mid = cc.find(cc.js.formatStr('mask/mid%s', idx), this.node)
        mid.active = true

        //betlist
        this.ShowBetList(idx, this._betTab)
        this.setMaxCoin()
        //进入动画
        if (ani) {
            let btn_r = cc.find('btn_right', this.node)
            btn_r.active = true
            btn_r.x = 800
            cc.tween(btn_r)
                .to(0.5, { x: 487 }, { easing: 'quartOut' })
                .start()
            let btn_l = cc.find('btn_left', this.node)
            btn_l.active = true
            btn_l.x = -800
            cc.tween(btn_l)
                .to(0.5, { x: -488 }, { easing: 'quartOut' })
                .start()
        }
    },

    ShowBetList: function (idx, nTab) {
        this.initBtn()

        // let mid = cc.find(cc.js.formatStr('mid%s',idx),this.node)

        //展示当前的 隐藏未显示的
        // cc.find('bg_cont', mid).active = true

        // let otherIdx = idx > 0 ? 0: 1
        // let midOther = cc.find(cc.js.formatStr('mid%s',otherIdx),this.node)
        // cc.find('bg_cont', midOther).active = false

        // let btn_nor = cc.find('btn_reg',mid)
        // let btn_hig = cc.find('btn_high',mid)
        // let btn_nor = cc.find('btn_reg',this.node)
        // let btn_hig = cc.find('btn_high',this.node)
        // btn_nor.off('click',this.onClickBetTabNor,this)
        // btn_nor.on('click',this.onClickBetTabNor,this)
        // btn_hig.off('click',this.onClickBetTabHigh,this)
        // btn_hig.on('click',this.onClickBetTabHigh,this)
        // this._showSelTab(idx,nTab)
        let list = this._betData.datalist.high.betlist
        this.btnMask(false)
        if (nTab == 0) {
            this.btnMask(true)
            list = this._betData.datalist.normal.betlist
        }
        for (let i = 0; i < 4; i++) {
            // let btn = cc.find(cc.js.formatStr('bg_cont/btn%s',i+1),mid)
            let btn = cc.find(cc.js.formatStr('bg_cont/btn%s', i + 1), this.node)
            if (list[i]) {
                btn.active = true
                let lbl_bet = cc.find('lbl_bet', btn)
                lbl_bet.getComponent(cc.Label).string = Global.FormatNumToComma(list[i])
            }
            else {
                btn.active = false
            }
            btn.off('click', this.onClickBet, this)
            btn.on('click', this.onClickBet, this)

        }

        // //是否解锁
        // let bOpen = this._betData.open
        // let nodeLock = cc.find('node_lock',btn_hig)
        // nodeLock.active = !bOpen

    },

    showGameIcon: function (idx, data) {
        let slotitem = cc.find(cc.js.formatStr('mask/mid%s/slots_item', idx), this.node)
        slotitem.getComponent('CH_PageSlotsItem').SetData(data, null, null, null, false)

        // let cfg = itemsListCfg[data.id]
        // if(cfg.leader){
        //     slotitem.scale = 0.9
        //     slotitem.y = 437
        //     slotitem.width = 850
        // }
        // else{
        //     slotitem.scale = 1
        //     slotitem.y = 477
        //     slotitem.width = 450
        // }
    },

    showGameLevel: function (idx, data) {
        let level = cc.find(cc.js.formatStr('mask/mid%s/slots_item/mid_content/level', idx), this.node)

        let cardLv = 0
        let cardStar = 0
        let cardInfo = cc.vv.HerocardManager.getCardInfoByGameid(data.id);
        if (cardInfo && cardInfo.lv > 0) {
            cardLv = cardInfo.lv
            cardStar = cardInfo.star
        }

        level.active = true;
        for (let i = 1; i <= 5; i++) {
            let star = cc.find("star/star" + i, level);
            let animName = (cardStar + 1 > i) ? 'animation2' : 'animation';
            star.getComponent(sp.Skeleton).setAnimation(0, animName, false);
        }
        cc.find("denji_db/lbl", level).getComponent(cc.Label).string = "Lv." + cardLv;
    },


    refreshRank(datalist) {
        let node_rank = cc.find("node_rank", this.node);
        if (datalist) {
            node_rank.active = true;
            for (let i = 1; i <= 3; i++) {
                cc.find(cc.js.formatStr("kuang_0%s/node_head", i), node_rank).getComponent("UserHead").setHead(datalist[i - 1].uid, datalist[i - 1].usericon)
                cc.find(cc.js.formatStr("kuang_0%s/lvNum", i), node_rank).getComponent(cc.Label).string = "L" + datalist[i - 1].lv;
                cc.find(cc.js.formatStr("kuang_0%s/name", i), node_rank).getComponent(cc.Label).string = datalist[i - 1].playername;
            }
        } else {
            node_rank.active = false;
        }
    },

    showRank: function (idx, data) {
        let cfg = cc.vv.HerocardManager.getCardCfgByGame(data.id);
        if (cfg) {
            let rankInfo = cc.vv.HerocardManager.getCardRankInfo(cfg.cardid);
            if (rankInfo) {
                this.refreshRank(rankInfo.rankList);
            } else {
            }
            this.reqCardRank(cfg.cardid, 3);
        } else {
            this.refreshRank();
        }
    },

    //请求卡牌排行榜  limit-代表获取前几名
    reqCardRank(cardid, limit = 3) {
        let req = {
            c: MsgId.REQ_HEROCARD_RANK,
            cardid: cardid,
            limit: limit,
        };
        cc.vv.NetManager.sendAndCache(req);
    },

    onRcvHeroCardRank: function (msg) {
        if (msg.code == 200) {
            let cardid = msg.cardid;
            let datalist = msg.datalist;

            if (!cc.vv.HerocardManager.getCardRankInfo(cardid)) {
                this.refreshRank(datalist);
            }
            cc.vv.HerocardManager.setCardRankInfo(cardid, datalist);
        }
    },

    onClickClose: function () {
        Global.playComEff("ch_close");
        this.node.destroy()
    },

    onClickRight: function () {
        if (!this.isClickLeftRight) {
            return
        }
        this.isClickLeftRight = false

        if (this._curIdx + 1 >= this._allUnlockGames.length) {
            this._curIdx = 0
        }
        else {
            this._curIdx += 1
        }
        //从右边滑出来
        let nextPage = 0
        if (this._curMidx == 0) {
            nextPage = 1
        }
        //gameicon
        this.showGameIcon(nextPage, this._allUnlockGames[this._curIdx])
        this.showGameLevel(nextPage, this._allUnlockGames[this._curIdx])
        this.showRank(nextPage, this._allUnlockGames[this._curIdx])
        this.setMidInfo(nextPage, this._allUnlockGames[this._curIdx])
        let right_node = cc.find(cc.js.formatStr('mask/mid%s', nextPage), this.node)
        if (right_node.getNumberOfRunningActions() == 0) {
            right_node.x = 1080
            right_node.active = true
            cc.tween(right_node)
                .to(0.35, { x: 0 }, { easing: 'quartOut' })
                .call(() => {
                    this.isClickLeftRight = true
                })
                .start()

            let curNode = cc.find(cc.js.formatStr('mask/mid%s', this._curMidx), this.node)
            cc.tween(curNode)
                .to(0.35, { x: -1080 }, { easing: 'quartOut' })
                .start()

            this._curMidx = nextPage

            StatisticsMgr.reqReport(StatisticsMgr.REQ_SELECTBET_RIGHT)
        }
        Global.playComEff("ch_btn_click");

    },

    onClickLeft: function () {
        if (!this.isClickLeftRight) {
            return
        }
        this.isClickLeftRight = false

        if (this._curIdx - 1 >= 0) {
            this._curIdx -= 1
        }
        else {
            this._curIdx = this._allUnlockGames.length - 1
        }
        //从左边滑出来
        let nextPage = 0
        if (this._curMidx == 0) {
            nextPage = 1
        }
        this.showGameIcon(nextPage, this._allUnlockGames[this._curIdx])
        this.showGameLevel(nextPage, this._allUnlockGames[this._curIdx])
        this.showRank(nextPage, this._allUnlockGames[this._curIdx])
        this.setMidInfo(nextPage, this._allUnlockGames[this._curIdx])
        let right_node = cc.find(cc.js.formatStr('mask/mid%s', nextPage), this.node)
        if (right_node.getNumberOfRunningActions() == 0) {
            right_node.x = -1080
            right_node.active = true
            cc.tween(right_node)
                .to(0.35, { x: 0 }, { easing: 'quartOut' })
                .call(() => {
                    this.isClickLeftRight = true
                })
                .start()

            let curNode = cc.find(cc.js.formatStr('mask/mid%s', this._curMidx), this.node)
            cc.tween(curNode)
                .to(0.35, { x: 1080 }, { easing: 'quartOut' })
                .start()

            this._curMidx = nextPage

            StatisticsMgr.reqReport(StatisticsMgr.REQ_SELECTBET_LEFT)
        }

        Global.playComEff("ch_btn_click");
    },

    onClickBetTabNor: function () {
        if (!this._betData) {
            return
        }
        this.btnMask(true)
        if (this._betTab != 0) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SELECTBET_TAB_NOR)
            this._betTab = 0
            this.ShowBetList(this._curMidx, this._betTab)
        }
        Global.playComEff("ch_tab");
    },

    onClickBetTabHigh: function () {
        if (!this._betData) {
            return
        }

        if (!this._betData.open) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SELECTBET_TAB_HIG, -1)
            //未解锁
            Global.playComEff("ch_notification");
            let nodeTip = cc.find('text_tip', this.node)
            nodeTip.stopAllActions()
            nodeTip.active = true
            cc.tween(nodeTip)
                .to(0.3, { scale: 1 }, { easing: 'backOut' })
                .delay(5)
                .to(0.2, { scale: 0 })
                .start()
            return
        }
        this.btnMask(false)
        if (this._betTab != 1) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SELECTBET_TAB_HIG, 1)
            this._betTab = 1
            this.ShowBetList(this._curMidx, this._betTab)
        }
        Global.playComEff("ch_tab");
    },

    _showSelTab: function (idx, nTab) {
        let mid = cc.find(cc.js.formatStr('mask/mid%s', idx), this.node)
        // let spBg = cc.find('spr_content_bg',mid)
        // spBg.scaleX = nTab==0?1:-1


    },

    onClickBet: function (event) {
        Global.playComEff("ch_btn_click");
        if (!this._ssid) {
            Global.dispatchEvent(EventId.RECORD_HALL_SCROLL)

            this.isClickBetBtn = true

            if (event && event.node) {
                let node = event.node
                let btnIdx = node.name.substr(node.name.length - 1, 1)

                this._betIdx = Number(btnIdx)
            }
            else {
                this._betIdx = 4
            }



            let trackType = StatisticsMgr.REQ_SELECTBET_NOR_BET
            //先保存起来押注，后面进入游戏后，设置成这个值。目前服务端不能修改当前的押注档位
            let betVal = this._betData.datalist.normal.betlist[this._betIdx - 1]
            this._ssid = 1
            if (this._betTab == 1) {
                this._ssid = 2
                betVal = this._betData.datalist.high.betlist[this._betIdx - 1]
                trackType = StatisticsMgr.REQ_SELECTBET_HIG_BET
            }

            cc.vv.UserManager.setEnterSelectBet(betVal)

            StatisticsMgr.reqReport(trackType, this._betIdx)

            let btn_r = cc.find('btn_right', this.node)
            btn_r.active = false
            let btn_l = cc.find('btn_left', this.node)
            btn_l.active = false
            let btn_close = cc.find('btn_close', this.node)
            btn_close.active = true
            cc.tween(btn_close)
                .hide()
                .delay(15)
                .show()
                .start()

            // let slotitem = cc.find(cc.js.formatStr('mid%s/slots_item',this._curMidx),this.node)
            // slotitem.getComponent('CH_PageSlotsItem')._enterFunc(this._curGameData.id)
            this._enterGame(this._curGameData.id)
        }


    },

    onClickGoPalace: function () {
        Global.dispatchEvent(EventId.HEROPALACE_SHOW)
        this.onClickClose()

    },

    _enterGame: function (gameId) {
        cc.vv.GameManager.setEnterOpation({ ssid: this._ssid, betidx: this._betIdx })
        let bInnerGame = cc.vv.UserManager.isNoNeedDownGame(gameId) //是否是内置游戏
        if (cc.sys.isNative && Global.openUpdate && !bInnerGame) { // 手机平台需要检测更新
            cc.vv.SubGameUpdateNode.emit("check_subgame", gameId);
        } else {

            cc.vv.GameManager.EnterGame(gameId)
        }
    },

    //自动更新已经下载过的游戏
    autoUpdate: function () {
        if (cc.sys.isNative) {
            if (this._curGameData) {
                let gameId = this._curGameData.id
                let bInnerGame = cc.vv.UserManager.isNoNeedDownGame(gameId) //是否是内置游戏
                if (!bInnerGame) {
                    let bDown = cc.vv.UserManager.isDownloadSubGame(gameId)
                    if (bDown) {
                        //不是最新的
                        let bNew = cc.vv.SubGameUpdateNode.getComponent('subGameMgr')._isAreadyNew(gameId)
                        if (!bNew) {
                            cc.vv.SubGameUpdateNode.emit("check_subgame", gameId);
                        }

                    }
                }
            }

        }

    },

    downloadingFinish: function (data) {
        if (cc.isValid(this.node) && this.isClickBetBtn) {
            let gameid = data.detail
            if (gameid == this._curGameData.id) {
                //直接进入游戏
                cc.vv.GameManager.EnterGame(gameid)
            }
        }
    },

    // onRcvHallBetsinfo:function(msg){
    //     if(msg.code == 200){
    //         this._betData = msg
    //         //解锁了高倍场就默认选中高倍场
    //         this._betTab = this._betData.open?1:0
    //         this.setMidInfo(this._curMidx,this._curGameData,true)

    //         //是否有引导
    //         let tempData = cc.vv.NewGuide.GetGuideTempData()
    //         if(tempData == 96){
    //             cc.vv.NewGuide.SetGuideTempData(null)
    //             cc.vv.NewGuide.ShowGuide(97)
    //         }
    //     }
    // },

    initBet: function () {
        // if(msg.code == 200){
        // this._betData = msg
        //解锁了高倍场就默认选中高倍场
        this._betTab = this._betData.open ? 1 : 0
        this.setMidInfo(this._curMidx, this._curGameData, true)

        //是否有引导
        let tempData = cc.vv.NewGuide.GetGuideTempData()
        if (tempData == 96) {
            cc.vv.NewGuide.SetGuideTempData(null)
            cc.vv.NewGuide.ShowGuide(97)
        }
    }
    // },


    // update (dt) {},
});
