/**
 * 离线收益
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_COLLECT_OFFLINE_REWARD, this.onRcvGetReward, this);
        Global.playComEff("ch_notification");

        Global.FixDesignScale_V(this.node)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_COLLECT_OFFLINE_REWARD, this.onRcvGetReward, false, this);
        //登录弹框
        cc.vv.EventManager.emit(EventId.LOGIN_POP_UI);
    },

    start() {
        this.showRewardUI();

        let uiAni = this.node.getComponent(cc.Animation)
        uiAni.on('finished', this.uiPlayFinish, this)
        let spr1 = cc.find('spr_bg/bg', this.node)
        let ani = spr1.getComponent(sp.Skeleton)
        ani.setAnimation(0, 'play', false)
        ani.addAnimation(0, 'idle', true)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_WELCOMEBACK_POP)
    },

    uiPlayFinish: function (type, state) {
        // if(state.name == 'offline_reward_play'){
        //     let uiAni = this.node.getComponent(cc.Animation)
        //     uiAni.play('offline_reward_idle')

        // }


    },



    // 奖励页面
    showRewardUI() {
        cc.find("spr_bg/lbl_coin", this.node).getComponent(cc.Label).string = Global.formatMoney(cc.vv.UserManager.getOfflineAward());

        let offlineTime = cc.vv.UserManager.getOfflineTime();
        let nDay = Math.floor(offlineTime / (24 * 3600));
        let day = Math.floor(offlineTime % (24 * 3600));
        let min = Math.floor(day % 3600);
        let nHour = Math.floor(day / 3600);
        let nMin = Math.floor(min / 60);

        let lbl_1 = cc.find("spr_bg/lbl_1", this.node);
        let lbl_2 = cc.find("spr_bg/lbl_2", this.node);
        lbl_1.active = nDay > 0;
        lbl_2.active = nDay === 0;
        // let showNode = lbl_1.active?lbl_1:lbl_2;
        if (lbl_1.active) {
            I18N.setI18nLabel(lbl_1, cc.vv.Language.offline_tip1, nDay, nHour, nMin)
            // cc.find("lbl_days", showNode).getComponent(cc.Label).string = nDay;
        } else {
            I18N.setI18nLabel(lbl_2, cc.vv.Language.offline_tip2, nHour, nMin)
        }
        // cc.find("lbl_hours", showNode).getComponent(cc.Label).string = nHour;
        // cc.find("lbl_mins", showNode).getComponent(cc.Label).string = nMin;

        let btn_collect = cc.find("spr_bg/btn_collect", this.node);
        btn_collect.off("click");
        Global.btnClickEvent(btn_collect, this.onClickCollect, this)
    },

    // 讲秒转换成对应格式的时间
    // formatTime(nVal){
    //     let day = Math.floor(nVal/(24*3600))
    //     let min = Math.floor(nVal%3600);
    //     let nHour = Math.floor(nVal/3600);
    //     let nMin = Math.floor(min/60);
    //     let nSec = min%60;
    //
    //     let strShow = "";
    //     if(day > 0){
    //         strShow += day + (day > 1 ? " days " : " day ")
    //     }
    //     if(nHour > 0){
    //         strShow += nHour + (nHour > 1 ? " hours " : " hour ")
    //     }
    //     if(nMin > 0){
    //         strShow += nMin + (nMin > 1 ? " mins" : " min")
    //     }
    //
    //     return strShow
    // },

    showCollectResult() {
        let self = this
        let endCall = function () {
            cc.vv.UserManager.AddCoin(self._addCoin, true);
            if (cc.vv.gameData) {
                cc.vv.gameData.RefushMyCoin()
            }
            self.node.destroy()
        };

        //如果在游戏内
        let toNode = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        if (cc.vv.gameData) {
            cc.vv.gameData.setCoins(cc.vv.UserManager.coin)
            toNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
        }

        if (toNode) {
            Global.FlyCoin(("spr_bg/lbl_coin", this.node), toNode, endCall, true)
        }

    },


    onClickCollect(event) {
        Global.playComEff("ch_collect");
        // event.node.getComponent(cc.Button).interactable = false;
        cc.find("spr_bg/btn_collect", this.node).getComponent(cc.Button).interactable = false;
        var req = { 'c': MsgId.REQ_COLLECT_OFFLINE_REWARD };
        req.uid = Global.playerData.uid;
        cc.vv.NetManager.send(req);

        StatisticsMgr.reqReport(StatisticsMgr.REQ_WELCOMEBACK_COLLECT)
    },

    onRcvGetReward(msg) {
        if (msg.code === 200) {
            this._addCoin = msg.addCoin;

            this.showCollectResult()
        }
    },

    // update (dt) {},
});
