cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _delegate: null,
        _cardInfo: null,
    },

    onLoad() {
        Global.onClick("btn_close", this.node, this.onClickClose, this)
        Global.onClick("item1/btn_go", this.node, this.onClickGoSpin, this)
        Global.onClick("item2/btn_go", this.node, this.onClickLuckyFlipcard, this)
        Global.onClick("item3/btn_go", this.node, this.onClickGoStore, this)
        Global.onClick("item4/btn_go", this.node, this.onClickSummon, this)
        Global.onClick("item5/btn_go", this.node, this.onClickAsk, this)

        if (cc.vv.gameData) {
            //如果在游戏内，则隐藏按钮
            for (let i = 1; i <= 3; i++) {
                let btnGo = cc.find("bg/item" + i + "/btn_go", this.node)
                if (btnGo) btnGo.active = false
            }
        }

        Global.playComEff("ch_popup_l2")
    },

    init(delegate, cardInfo, fromWhere) {
        this._delegate = delegate
        this._cardInfo = cardInfo
        this._fromWhere = fromWhere
        this.btnEnable()
    },

    btnEnable() {
        let flag = cc.vv.gameData ? false : true
        cc.find('btn_close', this.node).active = flag
        cc.find('item1/btn_go', this.node).active = flag
        cc.find('item2/btn_go', this.node).active = flag
        cc.find('item3/btn_go', this.node).active = flag
        cc.find('item4/btn_go', this.node).active = flag
        cc.find('item5/btn_go', this.node).active = flag

        // if(!cc.vv.gameData){
        //     let compCall = function(){
        //         Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI,112)
        //     }
        //     cc.vv.NewGuide.SetGuideTempData(112);
        //     cc.vv.NewGuide.ShowGuide(112,compCall)
        // }
    },

    onClickGoSpin() {
        Global.playComEff("ch_btn_click")
        if (!this._cardInfo) return

        let gameId = this._cardInfo.cfg.gameid
        let bLock = cc.vv.UserManager.isGameLock(gameId)
        if (bLock) {
            //是否
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_game_not_released);
            // cc.vv.FloatTip.show('Sorry,the game has not been released yet, so stay tuned.');
            return
        }
        if (this._delegate) {
            this._delegate.onGoSpin()
        }
        this.node.destroy()
    },

    onClickLuckyFlipcard() {
        if (this._delegate) {
            this._delegate.onGoFlipcard()
        }
        this.node.destroy()
    },

    onClickGoStore() {
        if (this._delegate) {
            this._delegate.onGoStore()
        }
        this.node.destroy()
    },

    onClickSummon() {
        if (this._delegate) {
            this._delegate.onGoSummon()
        }
        this.node.destroy()
    },

    onClickAsk() {
        if (this._delegate) {
            this._delegate.onGoFriend()
        }
        this.node.destroy()
    },

    // onClickGoRewards() {
    //     Global.playComEff("ch_btn_click")
    //     let self = this
    //     cc.loader.loadRes("CashHero/prefab/herocard/card_task",cc.Prefab, (err, prefab) => {
    //         if (!err) {
    //             let canvas = cc.find("Canvas")
    //             if(!cc.find('card_task', canvas)){
    //                 let node = cc.instantiate(prefab)
    //                 node.parent = canvas
    //                 node.getComponent("CH_Herocard_Task").init(self._delegate, self._cardInfo, self._fromWhere)
    //                 self.node.destroy()
    //             }
    //         }
    //     })

    //     //打卡
    //     StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_LEVEL_VIEWREWARDS,this._fromWhere+'|'+this._cardInfo.cardid)
    // },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.destroy()
    }

});
