//  - https://docs.cocos.com/creator/manual/en/scripting/class.html
// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _btn_backLobby: null,
        _btn_purchase: null,

        _btn_menu: null,
        _node_menu: null,

        _lbl_level: null,
        _progressBar: null,

        _node_buy: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this.registerEventListener();

        this._btn_backLobby = cc.find("btn_backLobby", this.node);
        Global.btnClickEvent(this._btn_backLobby, this.onBtnBackLobbyClicked, this);

        this.initMenu();

        this._btn_purchase = cc.find("btn_purchase", this.node);
        Global.btnClickEvent(this._btn_purchase, this.onBtnPurchaseClicked, this);
        this._node_buy = cc.find("node_buy",this.node);
        let _btn_buy = cc.find("btn_buy",this._node_buy);
        let _btn_sale = cc.find("btn_sale",this._node_buy);
        Global.btnClickEvent(_btn_buy, this.onBtnPurchaseClicked, this);
        Global.btnClickEvent(_btn_sale, this.onBtnSaleClicked, this);

        // this._lbl_coinNum = cc.find("playerCoins/lbl_coinsNum", this.node);
        this._lbl_level = cc.find("playerLevel/lbl_level", this.node);
        this._progressBar = cc.find("playerLevel/levelProgressBar", this.node);

        if (Global.isClosePurchase()) {
            this._btn_purchase.active = false;
            this._node_buy.active = false;
        }
        this.judgeLevelUpGift();

        this.showDoubleXPFlag();
    },

    initMenu () {
        //菜单按钮
        this._btn_menu = cc.find("btn_menu", this.node);
        Global.btnClickEvent(this._btn_menu, this.onBtnMenuClicked, this);
        
        //点击等级
        Global.btnClickEvent(cc.find("playerLevel", this.node), this.onLevelCompClicked, this);
    },

    start () {
        //更新余额
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_UPDATE_BALANCE);

        this.updateLvExp()
    },

    


    //CUSTOM LOGIC FUNCTIONS:

    registerEventListener () {
        // Global.registerEvent(cc.vv.gameData._EventId.SLOT_UPDATE_BALANCE,this.recvUpdateBalance,this);
       
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_START_MOVE, this.onEventStartMove, this);
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_STOP_MOVE,this.onEventStopMove,this);
        Global.registerEvent(EventId.REFUSH_LV_EXP,this.onEventRefushLvexp,this);
        Global.registerEvent(EventId.SHOW_LEVEL_UP_GIFT,this.onEventLevelUpGift,this);  //等级礼包
        Global.registerEvent(EventId.PULL_LV_UP,this.onEventExpLevelup,this);  //等级礼包
        
    },

    updateLabelText(node, str) {
        node.getComponent(cc.Label).string = str || "0";
    },


    //BUTTON BIND FUNCTIONS:

    onBtnBackLobbyClicked (event, customEventData) {
        let bFreeGame = cc.vv.gameData.isFreeTime()
        if(!bFreeGame){
            console.log(">>>> 返回大厅");
            cc.vv.gameData.requestExit();
        }
        else{
            console.log('>>>> 免费游戏中')
        }
        
    },

    onBtnPurchaseClicked (event, customEventData) {
        console.log(">>>> 弹出商城");
        let canvas = cc.find('Canvas');
        let _operateCmp = canvas.getComponent("SlotMachine_Operate");
        if(_operateCmp && _operateCmp.isNotEnoughCoin(true)){
            cc.vv.Shop.show(Global.SHOP_POS_ID.NOENOUGHMONEY);
        }else {
            cc.vv.Shop.show();
        }
    },

    onBtnMenuClicked (event, customEventData) {
        let self = this
        Global.playComEff("ch_btn_click");
        cc.loader.loadRes("slots_common/SlotRes/prefab/LMSlots_MenuNode",cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(self.node)) {
                let old = self.node.parent.getChildByName('LMSlots_MenuNode')
                if(!old){
                    let node = cc.instantiate(prefab)
                    Global.FixDesignScale(node)
                    node.name = 'LMSlots_MenuNode'
                    node.parent = self.node.parent //加到父节点
                    let lvNode = event.target
                    if(lvNode){
                        let pos = lvNode.convertToWorldSpaceAR(cc.Vec2(0,0))
                        let tipPos = self.node.parent.convertToNodeSpaceAR(pos)
                        node.position = cc.v2(tipPos.x - (node.width/2-lvNode.width/2-5)*node.scaleX, tipPos.y - (node.height/2-lvNode.height/2 - 5)*node.scaleY)
                    }
                    old = node
                    
                }
                
            }
        })
        
    },

    
    //刷新经验
    updateLvExp:function(bInit){
        let curLv = cc.vv.UserManager.getCurLv()
        this.updateLabelText(this._lbl_level, curLv);
        let pre = cc.vv.UserManager.getCurExp()/cc.vv.UserManager.getUpdateExp()
        if(pre < 0.1){ //平铺模式会有一条线
            pre = 0.1
        }
        if(pre > 1){
            pre = 1
        }
        let oldVal = Number(this._progressBar.getComponent(cc.ProgressBar).progress)
        let lightNode = cc.find('bar/light_mask/XINGEV2',this._progressBar)
        lightNode.active = false
        let dianNode = cc.find('bar/dian',this._progressBar)
        dianNode.active = false
        if(!bInit && pre > oldVal){
            cc.tween(this._progressBar.getComponent(cc.ProgressBar))
            .call(() => {
                lightNode.active = true
                dianNode.active = true
                lightNode.getComponent(cc.ParticleSystem).resetSystem()
                dianNode.getComponent(cc.ParticleSystem).resetSystem()
                let allps = lightNode.getComponentsInChildren(cc.ParticleSystem)
                for(let i = 0; i < allps.length; i++){
                    allps[i].resetSystem()
                }
            })
            .to(1,{progress:pre})
            .delay(2)
            .call(() => {
                lightNode.active = false
                dianNode.active = false
            })
            .start()
        }
        else{
            this._progressBar.getComponent(cc.ProgressBar).progress = pre;
        }
        
        //特效
        
        // let spineMask = this._progressBar.getChildByName('spine_mask')
        // spineMask.width = 400*pre
    },

    //显示升级界面
    onEventExpLevelup:function(){
        //是否等级提升了
        let levelupData = cc.vv.gameData.getLevelupExp()
        if(levelupData){
            this._showLvup(levelupData.totalCoin, levelupData.level,levelupData.coin,levelupData.reward,levelupData.vipexp,levelupData.maxbet)
        }
    },

    onEventStopMove:function(data){
        let bFreeGame = cc.vv.gameData.isFreeTime()
        let backBtn = this.node.getChildByName('btn_backLobby')
        backBtn.getComponent(cc.Button).interactable = !bFreeGame
    },

    onEventStartMove:function(data){
        

        let backBtn = this.node.getChildByName('btn_backLobby')
        backBtn.getComponent(cc.Button).interactable = false
        //按cash,只有自己关闭其它不能关
        //this._node_menu.active = false
    },

    onEventRefushLvexp:function(data){
        this.updateLvExp()
    },

    
    //显示升级详情
    onLevelCompClicked:function(){
        let self = this

        cc.loader.loadRes("common/prefab/level_up_tips",cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(self.node)) {
                let old = self.node.getChildByName('level_up_tips')
                let tipPos
                if(!old){
                    let node = cc.instantiate(prefab)
                    node.name = 'level_up_tips'
                    node.parent = self.node.parent
                    let lvNode = cc.find('playerLevel/lbl_level',self.node)
                    if(lvNode){
                        let pos = lvNode.convertToWorldSpaceAR(cc.Vec2(0,0))
                        tipPos = self.node.parent.convertToNodeSpaceAR(pos)
                        
                    }
                    old = node
                    
                }
                let script = old.getComponent('level_up_tips')
                let expNeed = cc.vv.UserManager.getUpdateExp() - cc.vv.UserManager.getCurExp()
                let nextReward = cc.vv.UserManager.getNextLvReward()
                script.setUIData(expNeed,nextReward,tipPos)
            }
        })
    },

    onBtnSaleClicked:function(){
        this.onShowLevelUpGift();
    },

    //判断等级礼包
    judgeLevelUpGift:function(){
        if (Global.isClosePurchase()) return;

        let levelgift = cc.vv.UserManager.getLevelGift();
        this._btn_purchase.active = levelgift <= 0;
        this._node_buy.active = levelgift > 0;

        if(levelgift > 0){
            this.unschedule(this.updateGiftTime);
            this.schedule(this.updateGiftTime,1)
        }
    },

    updateGiftTime : function() {
        let lbl_sale_time = cc.find('btn_sale/lbl',this._node_buy);
        let levelgift = cc.vv.UserManager.getLevelGift();
        lbl_sale_time.getComponent(cc.Label).string = Global.formatSec(levelgift);
        if(levelgift <= 0){
            this.unschedule(this.updateGiftTime);
            this._btn_purchase.active = true;
            this._node_buy.active = false;
        }
        --levelgift;
        cc.vv.UserManager.setLevelGift(levelgift);
    },

    onEventLevelUpGift:function () {
        this.judgeLevelUpGift();
        this.onShowLevelUpGift();
    },

    //等级礼包
    onShowLevelUpGift:function () {
        let self = this;
        cc.loader.loadRes("common/prefab/level_up_gift",cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(self.node)) {
                if(!self.node.getChildByName('level_up_gift')){
                    let node = cc.instantiate(prefab);
                    let cavas = cc.find("Canvas");
                    node.parent = cavas;
                    
                }
            }
            else{
                console.log('未找到资源')
            }
        });

        // cc.vv.PopUIMgr.popOneTimeOnly()
    },

    //doubleXP
    showDoubleXPFlag:function(){
        let self = this
        cc.loader.loadRes("common/prefab/booter_xp",cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(self.node)) {
                let tipPos
                let old = self.node.getChildByName('booter_xp')
                if(!old){
                    let node = cc.instantiate(prefab)
                    node.name = 'booter_xp'
                    node.parent = self.node
                    old = node
                    let lvNode = cc.find('playerLevel',self.node)
                    if(lvNode){
                        let pos = lvNode.convertToWorldSpaceAR(cc.Vec2(0,0))
                        tipPos = self.node.convertToNodeSpaceAR(pos)
                        
                    }
                    node.position = cc.v2(tipPos.x,tipPos.y-45)
                }
            }
        })
    },

    _showLvup(totalCoin,lv,lvCoin,bounsCoin,vipExp,maxbet){
        let self = this
        let endCall = function(){
            cc.vv.gameData.clearLevelupData()
            Global.dispatchEvent(EventId.REFUSH_LV_EXP)
            
        }
        //20级都用大弹窗
        if(cc.vv.UserManager.isShowBigLv(lv)){
            //出现大的升级框
            cc.loader.loadRes("common/prefab/level_up",cc.Prefab, (err, data) => {
                if (!err) {
                    let parNode = cc.find("Canvas")
                    if(cc.isValid(parNode)){
                        let old = parNode.getChildByName('level_up')
                        if(!old){
                            if(cc.isValid(data,true)){
                                let node = cc.instantiate(data)
                                node.name = 'level_up'
                                node.parent = parNode
                                let script = node.getComponent('level_up_exp')
                                script.setUIData(totalCoin,lv,lvCoin,bounsCoin,vipExp,endCall)
                            }
                            
                        }
                    }
                    
                    
                }
            })

            //lv完成打点
            cc.vv.PlatformApiMgr.KoSDKTrackEvent('af_level_achieved'+lv,JSON.stringify({af_level:lv}))
        }
        else{
            //出现小的升级框
            cc.loader.loadRes("common/prefab/level_up_small",cc.Prefab, (err, prefab) => {
                if (!err && cc.isValid(self.node)) {
                    let old = self.node.getChildByName('level_up_small')
                    if(!old){
                        let node = cc.instantiate(prefab)
                        node.name = 'level_up_small'
                        node.parent = self.node
                        let lvNode = cc.find('playerLevel/lbl_level',self.node)
                        if(lvNode){
                            let pos = lvNode.convertToWorldSpaceAR(cc.Vec2(0,0))
                            pos = self.node.convertToNodeSpaceAR(pos)
                            node.position = cc.v2(pos.x,pos.y - node.height/2 - 15)
                        }
                        let script = node.getComponent('level_up_small')
                        script.setUIData(totalCoin,lv,lvCoin,bounsCoin,vipExp,maxbet,endCall)
                    }
                    
                }

                Global.dispatchEvent(EventId.CLOSE_BIG_LV_UP)
            })
        }
        
    },

});
