cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {},

    onLoad() {
        let spinBtn = cc.find('spinBtn', this.node)
        Global.btnClickEvent(spinBtn, this.onClickSpinBtn, this)
        let close = cc.find('close', this.node)
        Global.btnClickEvent(close, this.onClickSpinBtn, this)
        this._coinNum = 0
    },

    start() {
        Global.FixDesignScale_V(this.node)
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CASHBACK_POP)
    },

    initCoin(num) {
        this._coinNum = num
        let coinLabel = cc.find('label', this.node)
        coinLabel.getComponent(cc.Label).string = Global.FormatNumToComma(num)
    },

    onClickSpinBtn() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CASHBACK_CLOSE)
        if (!this._coinNum) {
            Global.dispatchEvent(EventId.SHOW_CASHBACK)
        }
        cc.find('spinBtn', this.node).getComponent(cc.Button).interactable = false
        this.node.destroy()
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },

    update(dt) {
    },
});
