let RULE_CFG = [
    { text: 'Every 300 valid spins,your valid bet at least 100,000,000 coins', icon: 'rule_icon11', pt: 100, go: 'tab_slot' },
    { text: 'Wheel bonus for each play', icon: 'rule_icon1', pt: 10, go: 'tab_slot' },
    { text: 'Scratch bonus for each play', icon: 'rule_icon2', pt: 10, go: 'online_reward' },
    { text: 'Daily bonus for each collect', icon: 'rule_icon4', pt: 10, go: 'sign' },
    { text: 'Each complete daily mission', icon: 'rule_icon3', pt: 20, go: 'daily_mission' },
    { text: 'Lucky Flipcard for each play', icon: 'rule_icon5', pt: 20, go: 'flipcard' },
    // {text:'Each complete 9 cards',icon:'rule_icon6',pt:50,go:'bingo'},
    { text: 'Share rewards for each share', icon: 'rule_icon7', pt: 10, go: 'fb_share' },
    { text: 'Each smach a sliver egg', icon: 'rule_icon8', pt: 10, go: 'luckysmash' },
    { text: 'Each smach a gold egg', icon: 'rule_icon9', pt: 20, go: 'luckysmash' },
    { text: 'Each level ending with 0 or 5', icon: 'rule_icon10', pt: 100, go: 'tab_slot' },

]
let List = require('List')
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        listObj: List,
        spriteList: cc.SpriteAtlas,
        // arLuckycard: cc.SpriteFrame,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('btn_close', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)

        let toggplay = cc.find('node_tab/toggle1', this.node).getComponent(cc.Toggle)
        let toggstore = cc.find('node_tab/toggle2', this.node).getComponent(cc.Toggle)
        toggplay.node.on('toggle', this.onClickTogglePlay, this)
        toggstore.node.on('toggle', this.onClickToggleStore, this)

        //buy
        let btn_buy = cc.find('bg/node_store/btn_buy', this.node)
        Global.btnClickEvent(btn_buy, this.onClickBuy, this)

    },

    onDestroy() {
        Global.playComEff("ch_close");
    },

    start() {
        if (!this._curTab) {
            this.showTab(2)
        }


        Global.playComEff("ch_popup");
    },



    showTab: function (nTab) {
        this._curTab = nTab
        let toggplay = cc.find('node_tab/toggle1', this.node).getComponent(cc.Toggle)
        toggplay.isChecked = nTab == 1
        let toggstore = cc.find('node_tab/toggle2', this.node).getComponent(cc.Toggle)
        toggstore.isChecked = nTab == 2
        let play = cc.find('bg/node_play', this.node)
        let store = cc.find('bg/node_store', this.node)
        play.active = (nTab == 1)
        store.active = (nTab == 2)
        if (nTab == 1) {
            this.showPointList()
        }
    },

    showPointList: function () {
        if (this.listObj.numItems != RULE_CFG.length) {
            this.listObj.numItems = RULE_CFG.length
        }

    },

    OnListVRender(item, idx) {
        let self = this
        let data = RULE_CFG[idx]
        if (data) {
            item.active = true
            let icon = cc.find('icon', item)
            icon.getComponent(cc.Sprite).spriteFrame = this.spriteList.getSpriteFrame(data.icon)
            // let changeCall = function(){
            //     icon.getComponent(cc.Sprite).spriteFrame = (Global.language==Global.LANGUAGE.AR && (idx==5))?self.arLuckycard:self.spriteList.getSpriteFrame(data.icon)
            // }
            // I18N.setI18SpriteChangeCall(icon,changeCall)

            cc.find('scrath', item).active = idx == 2

            let text = cc.find('text', item)
            text.getComponent(cc.Label).string = data.text
            // let titlei18Scp = cc.find("lbl_title",this.node)



            let point = cc.find('lbl_point', item)
            point.getComponent(cc.Label).string = "+" + data.pt
            let onClickItem = function () {

                self.goBtn(data.go)
            }
            item.off('click')
            item.on('click', onClickItem, this)
        }
        else {
            item.active = false
        }
    },

    onClickClose: function () {
        if (cc.isValid(this.node)) {
            this.node.destroy()
        }

    },

    onClickTogglePlay: function () {
        Global.playComEff("ch_tab");
        if (this._curTab != 1) {
            this.showTab(1)

            StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_POINT_TAB_PLAY)
        }
    },

    onClickToggleStore: function () {
        Global.playComEff("ch_tab");
        if (this._curTab != 2) {
            this.showTab(2)

            StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_POINT_TAB_STORE)
        }
    },

    onClickBuy: function () {
        Global.playComEff("ch_btn_click");
        // cc.vv.UserManager.setEnterHallAction('Shop_Coin')
        // Global.dispatchEvent(EventId.GO_HALL_TAB,0)

        cc.vv.Shop.show('Shop_Coin')


        Global.dispatchEvent(EventId.HEROPALACE_CLOSE)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROPALACE_POINT_BUY)

        this.onClickClose()
    },

    goBtn: function (val) {
        let url
        let nodeName
        let script
        if (val == 'tab_slot') {
            Global.dispatchEvent(EventId.HEROPALACE_CLOSE)
            this.onClickClose()
        }
        else if (val == 'online_reward') {
            if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.DAILYFRIENZY)) {
                // url = 'common/prefab/online_rewards'
                // nodeName = 'online_rewards'
                //切换到bonus
                Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
                Global.dispatchEvent("BONUS_TAB", "Login")

                Global.dispatchEvent(EventId.HEROPALACE_CLOSE)
                this.onClickClose()

            }
            else {
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.DAILYFRIENZY));
                // cc.vv.FloatTip.show(cc.js.formatStr('UNLOCK AT LEVEL %s',Global.SYS_OPEN.DAILYFRIENZY));
            }
        }
        else if (val == 'sign') {
            if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.DAILYSIGN)) {
                // url = 'hall_prefab/SignIn'
                // nodeName = 'SignIn'
                //切换到bonus
                Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
                Global.dispatchEvent("BONUS_TAB", "Login")

                Global.dispatchEvent(EventId.HEROPALACE_CLOSE)
                this.onClickClose()
            }
            else {
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.DAILYSIGN));
                // cc.vv.FloatTip.show(cc.js.formatStr('UNLOCK AT LEVEL %s',Global.SYS_OPEN.DAILYSIGN));
            }
        }
        else if (val == 'daily_mission') {
            if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.DAILYTASK)) {
                url = 'CashHero/prefab/mission/mission_frame'
                nodeName = 'mission_frame'
            } else {
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.DAILYTASK));
                // cc.vv.FloatTip.show(cc.js.formatStr('UNLOCK AT LEVEL %s',Global.SYS_OPEN.DAILYTASK));
            }
        }
        else if (val == 'flipcard') {
            if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_CARD)) {
                url = 'CashHero/prefab/luck_card/CH_Luckycard'
                nodeName = 'CH_Luckycard'
            }
            else {
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.LUCKY_CARD));
                // cc.vv.FloatTip.show(cc.js.formatStr('UNLOCK AT LEVEL %s',Global.SYS_OPEN.LUCKY_CARD));
            }
        }
        else if (val == 'bingo') {
            if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)) {
                url = 'CashHero/prefab/bingo/bingo_main'
                nodeName = 'bingo_main'
            }
            else {
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock, Global.SYS_OPEN.BINGO));
                // cc.vv.FloatTip.show(cc.js.formatStr('UNLOCK AT LEVEL %s',Global.SYS_OPEN.BINGO));
            }
        }
        else if (val == 'luckysmash') {
            cc.vv.UserManager.goSystemUI('smash')
            // if(cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_SMASH)){
            //     url = 'CashHero/prefab/mission/mission_frame'
            //     nodeName = 'mission_frame'
            //     script = 'Mission_Frame'
            // }
            // else{
            //     cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_unlock,Global.SYS_OPEN.LUCKY_SMASH));
            //     // cc.vv.FloatTip.show(cc.js.formatStr('UNLOCK AT LEVEL %s',Global.SYS_OPEN.LUCKY_SMASH));
            // }
        }
        else if (val == 'fb_share') {
            // url = 'CashHero/prefab/fbShare/fbShareWheel'
            // nodeName = 'fbShareWheel'
            //切换到bonus
            Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
            Global.dispatchEvent("BONUS_TAB", "Login")

            Global.dispatchEvent(EventId.HEROPALACE_CLOSE)
            this.onClickClose()
        }

        if (url) {
            Global.playComEff("ch_btn_click");
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let canvas = cc.find("Canvas");
                    let old = cc.find(nodeName, canvas)
                    if (!old) {
                        let node = cc.instantiate(prefab)
                        node.parent = canvas
                        if (script == 'Mission_Frame') {
                            node.getComponent("Mission_Frame").onTabLuckyClick()//switchTab(2)
                        }
                    }

                    Global.dispatchEvent(EventId.HEROPALACE_CLOSE)
                    this.onClickClose()
                }
            });
        }
    }
    // update (dt) {},
});
