cc.Class({
    extends: cc.Component,

    properties: {

    },


    onLoad() {
        let btnClose = cc.find("content/top/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        let btnBuy1 = cc.find("content/list/view/content/item1/btn_buy", this.node)
        btnBuy1.on('click', this.onClickBuyBtn1, this)

        let btnBuy2 = cc.find("content/list/view/content/item2/btn_buy", this.node)
        btnBuy2.on('click', this.onClickBuyBtn2, this)

        let btnBuy3 = cc.find("content/list/view/content/item3/btn_buy", this.node)
        btnBuy3.on('click', this.onClickBuyBtn3, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP_EX, this.onRcvShopEx, this);
        cc.vv.NetManager.registerMsg(MsgId.JOURNEY_CNT_GIFT_BUYED, this.onRcvNetExploreCntBuyed, this)
        cc.vv.NetManager.registerMsg(MsgId.JOURNEY_COIN_GIFT_BUYED, this.onRcvNetExploreCoinBuyed, this)
        cc.vv.NetManager.registerMsg(MsgId.JOURNEY_STEP_GIFT_BUYED, this.onRcvNetExploreStepBuyed, this)

        // cc.vv.NetManager.registerMsg(MsgId.REQ_EXPLORE_INFO, this.onRcvNetExploreInfo, this)

        // Global.playComEff("ch_popup_l2")

        var req = { 'c': MsgId.REQ_SHOP_EX };
        req.uid = Global.playerData.uid;
        req.stype = "26,27,28";
        cc.vv.NetManager.send(req);
    },

    start() {
        Global.FixDesignScale_V(this.node)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP_EX, this.onRcvShopEx, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.JOURNEY_CNT_GIFT_BUYED, this.onRcvNetExploreCntBuyed, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.JOURNEY_COIN_GIFT_BUYED, this.onRcvNetExploreCoinBuyed, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.JOURNEY_STEP_GIFT_BUYED, this.onRcvNetExploreStepBuyed, false, this)
        // cc.vv.NetManager.unregisterMsg(MsgId.REQ_EXPLORE_INFO, this.onRcvNetExploreInfo, false, this)
    },

    showEndTime(buff, endTime, from) {
        let item1 = cc.find("content/list/view/content/item1", this.node)
        Global.setLabelString("daojishi_db/lbl_time", item1, Global.getTimeStr(endTime))
        this._from = from
        if ((buff & 0b100) == 0b100) {
            cc.find("btn_buy", item1).active = false;
            cc.find("daojishi_db", item1).active = true;
        } else {
            cc.find("btn_buy", item1).active = true;
            cc.find("daojishi_db", item1).active = false;
        }
    },

    refreshView() {
        let content = cc.find("content/list/view/content", this.node)
        if (this._shop1) {
            Global.setLabelString("item1/btn_buy/lbl_price", content, "$ " + this._shop1.amount)
            Global.setLabelString("item1/lbl_coin", content, Global.FormatNumToComma(this._shop1.count))
            //benifist
            let btn = cc.find("item1/btn_benifist", content)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._shop1.rewards, /*'1.99$'+cc.vv.UserManager.getBingoFrom()*/)
        }
        if (this._shop2) {
            Global.setLabelString("item2/btn_buy/lbl_price", content, "$ " + this._shop2.amount)
            Global.setLabelString("item2/lbl_coin", content, Global.FormatNumToComma(this._shop2.count))
            //benifist
            let btn = cc.find("item2/btn_benifist", content)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._shop2.rewards, /*'4.99$'+cc.vv.UserManager.getBingoFrom()*/)
        }
        if (this._shop3) {
            Global.setLabelString("item3/btn_buy/lbl_price", content, "$ " + this._shop3.amount)
            Global.setLabelString("item3/lbl_coin", content, Global.FormatNumToComma(this._shop3.count))
            //benifist
            let btn = cc.find("item3/btn_benifist", content)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._shop3.rewards, /*'4.99$'+cc.vv.UserManager.getBingoFrom()*/)
        }
    },

    onRcvShopEx(msg) {
        if (msg.code == 200) {
            this._shop1 = msg.shoplist["data26"][0]
            this._shop2 = msg.shoplist["data27"][0]
            this._shop3 = msg.shoplist["data28"][0]
            this.refreshView()
        }
    },

    addUserCoin(coin) {
        if (cc.vv.gameData) {
            cc.vv.gameData.AddCoin(coin, true)
        } else {
            cc.vv.UserManager.AddCoin(coin, true)
        }
    },


    onRcvNetExploreCntBuyed(msg) {
        if (msg.code == 200) {
            this.popBuyResult(1, msg);

            let item1 = cc.find("content/list/view/content/item1", this.node)
            cc.find("btn_buy", item1).active = false;
            cc.find("daojishi_db", item1).active = true;
        }
    },

    onRcvNetExploreCoinBuyed(msg) {
        if (msg.code == 200) {
            this.popBuyResult(2, msg);
        }
    },

    onRcvNetExploreStepBuyed(msg) {
        if (msg.code == 200) {
            this.popBuyResult(3, msg);
        }
    },

    popBuyResult(id, msg) {
        let parent = this.node
        let self = this;
        cc.loader.loadRes("CashHero/prefab/exploration/explore_pop", cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(parent) && parent.active == true && !parent.getChildByName("explore_pop")) {
                let node = cc.instantiate(prefab)
                node.parent = parent
                node.getComponent("Explore_Pop").popBuyResult(id, msg);
                self.refreshInfo();
            }
        })
    },

    refreshInfo() {
        let req = { c: MsgId.REQ_EXPLORE_INFO };
        cc.vv.NetManager.send(req);
    },

    onClickBuyBtn1() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_PAY_POINTONE, this._from)

        Global.playComEff("ch_btn_click")
        if (this._shop1) {
            cc.vv.PayMgr.reqPurchaseOrder(this._shop1.id)
        }
    },

    onClickBuyBtn2() {
        //打卡
        // StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_BUY_BUFF, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_btn_click")
        if (this._shop2) {
            cc.vv.PayMgr.reqPurchaseOrder(this._shop2.id)
        }
    },

    onClickBuyBtn3() {
        //打卡
        // StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_BUY_BUFF, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_btn_click")
        if (this._shop3) {
            cc.vv.PayMgr.reqPurchaseOrder(this._shop3.id)
        }
    },

    onClickClose() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_PAY_CLOSE, this._from)

        Global.playComEff("ch_btn_click");
        this.node.destroy()
    },
});
