    onListRenderItem: function (item, idx) {
        let cardInfo = this._listData[idx]
        if (cardInfo) {
            item.name = "item" + idx
            if (cardInfo == -1) {
                item.opacity = 0
            }
            else {
                item.opacity = 255
                item.getComponent('CH_Herocard_HallItem').init(cardInfo, this)
                // item.name = cardInfo.cardid+""
            }

            item.active = true

        }
        else {
            item.active = false
        }

        this.updateScrollviewsize()

    },

