    _showSelect: function (targetNode) {
        let pos = targetNode.getPosition()
        let node_five = cc.find('five', this.node)
        let selectSpine = cc.find('spine', node_five)
        selectSpine.active = true
        selectSpine.setPosition(cc.v2(pos.x - 1, pos.y + 3))
        selectSpine.scale = 0.59//this._selTab == CAMPID.ALL ? 1:0.8

        for (let i = 0; i < node_five.children.length; i++) {
            let item = node_five.children[i]
            if (item) {
                let mask = cc.find("mask", item)
                if (mask) {
                    mask.active = !(targetNode == item)
                }
            }
        }

        let _skeSpine = selectSpine.getComponent(sp.Skeleton)
        _skeSpine.setToSetupPose()
        _skeSpine.setAnimation(0, 'animation1', false)
        _skeSpine.addAnimation(0, 'animation2', true)

        Global.playComEff("ch_tab");
    },

