    //滚动到某一张牌
    scrollToCard: function (cardid) {
        if (this._listData) {
            // let idx = -1
            // for(let i = 0; i < this._listData.length; i++){
            //     if(this._listData[i] != -1){
            //         if(this._listData[i].cfg.cardid == cardid){
            //             idx = i
            //             break
            //         }
            //     }

            // }
            // if(idx > -1){
            //     this._scrollToIdx(-1,idx-1) //减1是因为头部有一张空牌
            // }

            let itemPos
            let node_view = cc.find('view', this._node_scv)
            let node_content = cc.find('content', node_view)
            let allChildren = node_content.children
            let itemIdx
            for (let i = 0; i < allChildren.length; i++) {
                let item = allChildren[i]
                let scp = item.getComponent('CH_Herocard_HallItem')
                let cardInfo = scp.getCardInfo()
                if (cardInfo && cardInfo != -1) {
                    if (cardid == cardInfo.cardid) {
                        itemPos = item.position
                        itemIdx = i
                        break
                    }
                }

            }
            //nodeselect节点的x坐标
            let offx = itemIdx == 1 ? 180 : 240
            this._node_scv.getComponent(cc.ScrollView).scrollToOffset(cc.v2(itemPos.x - offx, 0), 1)
            // this.listview.scrollTo(itemIdx,1)
            // this._scrollToIdx(-1,itemIdx)
        }
    },

