    //从某个序号的牌滚动到另一个序号的牌 fromIdx=-1 从当前滚动
    _scrollToIdx: function (fromIdx, toIdx) {
        let self = this
        let targetScr = self.listview.getComponent(cc.ScrollView)
        targetScr.stopAutoScroll()
        let scrollTime = 1.5

        let delayCall2 = function () {
            let nMaxOffSet = targetScr.getMaxScrollOffset().x
            let node_content = cc.find('view/content', this._node_scv)
            let itemW = node_content.children[0].width
            let itemSpace = node_content.getComponent(cc.Layout).spacingX
            let nOff = toIdx * (itemW + itemSpace)
            targetScr.scrollToPercentHorizontal(nOff / nMaxOffSet, scrollTime)//toIdx/nTotal
            self.setUpdateCardFlag(scrollTime)
            console.log("_scrollToIdx", fromIdx, toIdx, nMaxOffSet, nOff, nOff / nMaxOffSet)
        }
        let nTime2 = 0.2
        if (fromIdx > -1) {
            let delayCall1 = function () {
                let nTotal = self._listData.length
                targetScr.scrollToPercentHorizontal(fromIdx / nTotal, 0)
            }
            this.scheduleOnce(delayCall1, 0.1)
        }
        else {
            nTime2 = 0
            scrollTime = 1
        }

        this.scheduleOnce(delayCall2, nTime2)
    },

    setUpdateCardFlag(time) {
        let self = this
        this.node.stopAllActions()
        cc.tween(this.node)
            .delay(time)
            .call(() => {
                self._updateHeroCard = false
            })
            .start()
    },

    //更新卡片数据
    onCardUpate: function (data) {
        this._updateHeroCard = true
        let val = data.detail
        for (let i = 0; i < this._listData.length; i++) {
            if (val.cardid == this._listData[i].cardid) {
                this._listData[i] = val
            }
        }

        // if ((val.lv>0) && (val.star<1)) {
        //     this.sendCardAchieveStatus()
        // }

        this.showCampcards(this._selTab)
    },

