    updateScrollviewsize: function () {
        let node_view = cc.find('view', this._node_scv)
        let node_content = cc.find('content', node_view)
        let node_select = cc.find('node_select', node_view)
        let node_selectWdPos = node_select.convertToWorldSpaceAR(cc.v2(0, 0))

        let allChildren = node_content.children
        // let itemSpace = node_content.getComponent(cc.Layout).spacingX
        let nMinDif = 1000
        let selItem
        for (let i = 0; i < allChildren.length; i++) {
            let item = allChildren[i]

            let dif = Math.abs(item.convertToWorldSpaceAR(cc.v2(0, 0)).x - node_selectWdPos.x)
            if (nMinDif > dif) {
                nMinDif = dif
                selItem = item
            }
            let offset = (dif / 1500)
            if (offset > 1) {
                offset = 1
            }
            //170 是item.width
            let val = 170 * (1 - offset)

            item.width = val
            let scp = item.getComponent('CH_Herocard_HallItem')
            scp.showSelect(false)
            item.zIndex = 10000 - dif
            item.scale = 1


        }
        if (cc.isValid(selItem)) {
            let scp = selItem.getComponent('CH_Herocard_HallItem')
            scp.showSelect(true)
            selItem.zIndex = 10000
            selItem.scale = 1.1
            let curInfo = scp.getCardInfo()
            if (curInfo && this.selectCardInfo != curInfo) {
                this.selectCardInfo = curInfo
                if (!this._updateHeroCard) {
                    Global.playComEff("ch_btn_click");
                }
                this._changeCampBg(curInfo.cfg.campid)
                this._changeHeroAttr(curInfo);
            }
        }


        node_content.getComponent(cc.Layout).updateLayout()

    },



