    onEventCompleteNewGuide: function (data) {
        let val = data.detail
        // if(val == 55 || val == 58 || val == 26){
        //     this._checkSysOpenRed()
        // }
        if (val == 21) {
            //显示积累的卡包,如果没有卡包需要过掉
            let datas = cc.vv.HerocardManager.getHeroCardRedData()
            if (datas && datas.length == 0) {
                cc.vv.HerocardManager.clearLocalLock()
            }
        }
        else if (val == 59) {
            let bDone109 = cc.vv.NewGuide.ShowGuide(109)
            if (!bDone109) {
                cc.vv.NewGuide.SetGuideTempData(109)
            }
        }
    },

    onClickFight() {
        let url = 'CashHero/prefab/pvp/pvp_main'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.find('Canvas').getChildByName('pvp_main')
                if (!node) {
                    node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                }
            }
        });
    },

