
/**
 * 过渡动画
 */

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let testIpad = false
        if (testIpad || cc.sys.platform == cc.sys.IPAD) {
            let login = cc.find('mask_node/New Sprite/logo_ani', this.node)
            login.scale = 0.8

        }
        else {
            Global.FixDesignScale_V(this.node, true)
        }

    },

    start() {

    },

    //type:1退出 -1进入
    play: function (aniType, endCall) {
        this._playType = aniType
        this._playCall = endCall

        //
        if (aniType == 1) {
            cc.vv.UserManager.setEnterHallAction("ani_enter")
        }


        let aniName = (aniType == 1) ? "node_transion_exit" : "node_transion_enter"
        let aniNode = cc.find('mask_node', this.node)
        let aniCmp = aniNode.getComponent(cc.Animation)
        aniCmp.play(aniName)
        aniCmp.off('finished', this.onFinished, this);
        aniCmp.on('finished', this.onFinished, this);

        // cc.tween(this.node)
        // .delay(2)
        // .call(()=>{

        // })
        // .start()
    },

    onFinished: function (data) {
        if (this._playType == 1) {
            cc.vv.SceneMgr.enterScene(Global.SCENE_NAME.SLOT_BACKLOBBY);

        }
        else {
            this.node.active = false
        }

        if (this._playCall) {
            this._playCall()
        }


    },




});
