
/**
 * 好友弹窗内列表的item
 */
const ListItem = require('ListItem');
cc.Class({
    extends: ListItem,

    properties: {
        _itemData: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let addBtn = cc.find('btn_add', this.node)
        if (addBtn) {
            Global.btnClickEvent(addBtn, this.onClickAdd, this)
        }

        let selBtn = cc.find('select_bg', this.node)
        if (selBtn) {
            Global.btnClickEvent(selBtn, this.onClickSelect, this)
        }

        let headBtn = cc.find('node_head', this.node)
        Global.btnClickEvent(headBtn, this.onClickDetail, this)

        Global.registerEvent('SelectAllFriends', this.OnEventSelectChange, this);
        this._bSelect = false
    },

    // start () {

    // },

    showItemInfo(itemData) {
        this._itemData = itemData

        let self = this
        //设置头像
        var userHeadScript = cc.find("node_head", this.node).getComponent('UserHead');
        let setHeadCall = function (uid, spriteFrameval) {
            if (uid == self._itemData.uid) {
                userHeadScript.spr_head.spriteFrame = spriteFrameval
            }
        }
        userHeadScript.setHead(itemData.uid, itemData.usericon, setHeadCall);
        //昵称
        let name = itemData.playername
        if (this.getBLe(name) > 30) {
            name = itemData.playername.substring(0, 30) + ".."
        }
        cc.find("lblName", this.node).getComponent(cc.Label).string = name;
        //等级
        cc.find("node_lv/lbl_lv", this.node).getComponent(cc.Label).string = "LV." + itemData.level
        //coin
        cc.find("node_coin/lbl_coin", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(itemData.usercoin || itemData.coin || 0)
        //在线
        let sprOnline = cc.find('node_online/online', this.node)
        sprOnline.active = itemData.isonline
        let sproffline = cc.find('node_online/offline', this.node)
        sproffline.active = !itemData.isonline
        let des = cc.vv.Language.friend_offline//'offline'
        let color = new cc.Color(114, 145, 121);
        if (itemData.isonline) {
            des = cc.vv.Language.friend_online//'online'
            color = new cc.Color(7, 227, 55);
        }
        let lblonline = cc.find('node_online/lbl_des', this.node)
        lblonline.getComponent(cc.Label).string = des
        lblonline.color = color
        //fb
        cc.find("fb_icon", this.node).active = itemData.fb

        //标签
        this.showSelected(itemData.selected == 1);

        let lvNode = cc.find("img_head_lv/lblLv", this.node)
        if (lvNode) {
            lvNode.getComponent(cc.Label).string = "Lv." + itemData.level
        }
        let addBtn = cc.find('btn_add', this.node)
        if (addBtn) {
            addBtn.getComponent(cc.Button).interactable = true
        }

    },

    //是否选中
    showSelected(bShow) {
        if (this.selectedFlag) {
            this.selected = bShow
        }


    },

    OnEventSelectChange: function (data) {
        let val = data.detail
        this.showSelected(val)
    },

    //获取字符串长度
    getBLe: function (str) {
        if (str == null) return 0;
        if (typeof str != "string") {
            str += "";
        }
        return str.replace(/[^x00-xff]/g, "01").length;
    },

    onClickAdd: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_ADDFRIENDS_ADD)
        let self = this
        Global.playComEff("ch_btn_click");
        let addBtn = cc.find('btn_add', this.node)
        if (addBtn) {
            addBtn.getComponent(cc.Button).interactable = false
        }

        let delayCall1 = function () {
            let addBtn = cc.find('btn_add', self.node)
            if (addBtn) {
                addBtn.getComponent(cc.Button).interactable = true
            }
        }
        this.scheduleOnce(delayCall1, 0.5)

        let req = { c: MsgId.REQ_ADD_FRIENDS };
        req.frienduid = this._itemData.uid;
        req.act = 0;
        cc.vv.NetManager.send(req);
    },

    onClickSelect: function () {
        this._bSelect = !this._bSelect
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_DELFRIENDS_SELECT, this._bSelect ? 1 : 0)
        this.onClickThis()
    },

    onClickDetail: function () {
        // cc.loader.loadRes("CashHero/prefab/friend/CH_friend_detail",cc.Prefab, (err, prefab) => {
        //     if (!err) {
        //         let old = this.node.getChildByName('CH_friend_detail')
        //         if(!old){
        //             let node = cc.instantiate(prefab);
        //             node.parent = this.node;
        //             node.getComponent("CH_FriendsDetail").init(this._itemData.uid)
        //         }
        //     }
        // })



        let req = { c: MsgId.PERSIONAL_INFO };
        req.otheruid = this._itemData.uid
        req.act = 2
        cc.vv.NetManager.send(req);
    },

    // update (dt) {},
});
