/**
 * 翻卡活动主界面
 */
let STAGE_NUM = 20
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('bottom/btn_close', this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this);

        let btn_take = cc.find('node_reward/btn_take', this.node)
        Global.btnClickEvent(btn_take, this.onClickTake, this);

        let btn_buy = cc.find('bottom/spr_relife/btb_add', this.node)
        Global.btnClickEvent(btn_buy, this.onClickBuy, this);

        let btn_reset = cc.find('node_hastake/node_reset/buy_btn', this.node)
        Global.btnClickEvent(btn_reset, this.onClickReset, this);

        let card1 = cc.find('center/card1', this.node)
        Global.btnClickEvent(card1, this.onClickCard1, this);
        let card2 = cc.find('center/card2', this.node)
        Global.btnClickEvent(card2, this.onClickCard2, this);
        let card3 = cc.find('center/card3', this.node)
        Global.btnClickEvent(card3, this.onClickCard3, this);
        let card4 = cc.find('center/card4', this.node)
        Global.btnClickEvent(card4, this.onClickCard4, this);
        let card5 = cc.find('center/card5', this.node)
        Global.btnClickEvent(card5, this.onClickCard5, this);

        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYCARD_INFO, this.OnRcvActiveInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYCARD_ACTION, this.OnRcvFlipCard, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYCARD_TAKE, this.OnRcvTakeReward, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYCARD_RELIFE, this.OnRcvCardRelife, this);
        cc.vv.NetManager.registerMsg(MsgId.PULL_LUCKYCARD_BUYSUCCESS, this.OnRcvBuyCardRes, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYCARD_BUYLIST, this.OnRcvBuyList, this);
        cc.vv.NetManager.registerMsg(MsgId.PULL_LUCKYCARD_RESET, this.OnRcvRestTime, this);

        Global.registerEvent(EventId.COMM_ITEM_ADD, this.onEventItemChange, this)

        this._completeFlag = false
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYCARD_INFO, this.OnRcvActiveInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYCARD_ACTION, this.OnRcvFlipCard, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYCARD_TAKE, this.OnRcvTakeReward, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYCARD_RELIFE, this.OnRcvCardRelife, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PULL_LUCKYCARD_BUYSUCCESS, this.OnRcvBuyCardRes, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYCARD_BUYLIST, this.OnRcvBuyList, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PULL_LUCKYCARD_RESET, this.OnRcvRestTime, false, this);

        if (this._refushCall && this._activeData) {
            this._refushCall(this._activeData.cards)
        }
        Global.popBgm()
    },

    start() {
        cc.vv.NetManager.send({ c: MsgId.REQ_LUCKYCARD_INFO });

        Global.playBgm(Global.SOUNDS.bgm_luckycard);

        let compCall = function () {
            Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI, 26)
        }
        cc.vv.NewGuide.ShowGuide(26, compCall)

        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_POP)

        let bDone = cc.vv.NewGuide._isDoneGuide(21)
        if (!bDone) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_GUIDE)
        }
    },

    setRefushCall: function (refushCall) {
        this._refushCall = refushCall
    },

    onClickClose: function () {
        Global.playComEff("ch_btn_click");
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_CLOSE)

        if (this._completeFlag) {
            //通关
            Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
        }

        this.node.destroy()
    },

    onClickTake: function () {
        Global.playCashEff('luckycard/take_reward')
        let self = this
        let sureCall = function () {
            if (self._activeData) {
                self._completeFlag = true
                //领取
                cc.vv.NetManager.send({ c: MsgId.REQ_LUCKYCARD_TAKE });
            }
        }
        let cancelCall = function () {

        }
        let tipMsg = cc.js.formatStr("Your progress is %s/20, there are more rewads is waiting for you! take it right now?", this._activeData.lv)
        cc.vv.AlertView.show(tipMsg, sureCall, cancelCall, false, null, "TIPS")
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_TAKEREWARD)
    },

    onClickBuy: function () {

        cc.vv.NetManager.sendAndCache({ c: MsgId.REQ_LUCKYCARD_BUYLIST });

        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_HEART_BUY)
    },


    onClickCard1: function () {

        this._comClickCard(1)

        // let card1 = cc.find('center/card1',this.node)
        // this.doFlipCardAction(card1,'red')
    },
    onClickCard2: function () {
        this._comClickCard(2)

        // let card2 = cc.find('center/card2',this.node)
        // this.doFlipCardAction(card2,'gr')
    },
    onClickCard3: function () {
        this._comClickCard(3)

        // let card3 = cc.find('center/card3',this.node)
        // this.doFlipCardAction(card3,'bl')
    },
    onClickCard4: function () {
        this._comClickCard(4)

        // let card4 = cc.find('center/card4',this.node)
        // this.doFlipCardAction(card4,'yel')
    },
    onClickCard5: function () {
        this._comClickCard(5)

        // let card5 = cc.find('center/card5',this.node)
        // this.doFlipCardAction(card5,'org')
    },

    //牌的方位ID，正上方为1，顺时针1-5
    _comClickCard: function (pos) {
        if (this._activeData && this._activeData.status == 1) {//未结束
            Global.playCashEff('luckycard/flip_card')
            this.setClickCardEnable(false)
            let req = { c: MsgId.REQ_LUCKYCARD_ACTION }
            req.placeid = pos
            cc.vv.NetManager.send(req)
            this.showPickTip(false)

            //统计
            StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_FLIP, pos)
        }

    },

    //设置卡片是否可以点击
    setClickCardEnable: function (bEnable) {
        for (let i = 0; i < 5; i++) {
            let card = cc.find('center/card' + (i + 1), this.node)
            card.getComponent(cc.Button).interactable = bEnable
        }
    },



    //显示奖励信息
    showRewards: function () {
        let jackpot = this._activeData.jackpot

        let reward_layout = cc.find('node_reward/node_reward', this.node)
        reward_layout.removeAllChildren()
        let bShowSpine = this._activeData.status != 2
        let itemNode = cc.find('node_reward/node_reward_item', this.node)
        for (let i = 0; i < jackpot.length; i++) {
            let bShowAdd = (i != (jackpot.length - 1))
            let node = cc.instantiate(itemNode)
            node.active = true
            node.y = 0
            node.getComponent('CH_Luckycard_rewarditem').init(jackpot[i], false, bShowSpine)
            node.parent = reward_layout
        }
        this.showTakeBtnState(!(jackpot.length == 0) && (this._activeData.status == 1 || this._activeData.status == 3))
    },

    //更新奖励
    updateRewards: function (itemData) {
        let itemType = itemData.s
        let num = itemData.n
        let target = this.getRewardPoolItem(itemType)
        if (target && target.getComponent('CH_Luckycard_rewarditem').getItemType() == itemType) {
            //直接更新数量
            target.getComponent('CH_Luckycard_rewarditem').updateNum(num)
        }
        else {

            // if(target){
            //     target.getComponent('CH_Luckycard_rewarditem').showAdd(true)
            // }

            // //新增一个
            // let reward_layout = cc.find('node_reward/node_reward',this.node)
            // let itemNode = cc.find('node_reward/node_reward_item',this.node)
            // let node = cc.instantiate(itemNode)
            // node.active = true
            // node.y = 0
            // node.getComponent('CH_Luckycard_rewarditem').init(itemData, false)
            // node.parent = reward_layout
            this.showRewards()
        }
        //更新显示加号

        this.showTakeBtnState(true)

    },

    //显示当前的关卡
    showCurStage: function () {
        let curLv = this._activeData.lv
        for (let i = 0; i < STAGE_NUM; i++) {
            let node_stage = cc.find('bottom/spr_stage/node_stage' + (i + 1), this.node)
            node_stage.getComponent('CH_Luckcard_stageitem').init(curLv, i + 1)
        }


    },

    //底部基础信息显示
    showActionBaseInfo: function () {
        let lblrelife = cc.find('bottom/spr_relife/lbl_left', this.node)
        // lblrelife.getComponent(cc.Label).string = cc.js.formatStr('LEFT:%s',this._activeData.cards)
        I18N.setI18nLabel(lblrelife, cc.vv.Language.lefttime2, this._activeData.cards)

        //活动结束时间
        let lblfinishtime = cc.find('bottom/spr_time/lbl_time', this.node)
        lblfinishtime.getComponent(cc.Label).string = Global.formatSec(this._activeData.lefttime)
        let lblfinishtime2 = cc.find('node_hastake/next_time/lbl_time', this.node)
        lblfinishtime2.getComponent(cc.Label).string = Global.formatSec(this._activeData.lefttime)
        lblfinishtime.stopAllActions()
        cc.tween(lblfinishtime)
            .repeatForever(cc.tween()
                .delay(1)
                .call(() => {
                    this._activeData.lefttime -= 1
                    if (this._activeData.lefttime < 0) {
                        this._activeData.lefttime = 0
                    }
                    lblfinishtime.getComponent(cc.Label).string = Global.formatSec(this._activeData.lefttime)
                    lblfinishtime2.getComponent(cc.Label).string = Global.formatSec(this._activeData.lefttime)
                })
            )
            .start()
    },

    showTakeBtnState: function (bEnable) {
        let btn_take = cc.find('node_reward/btn_take', this.node)
        btn_take.getComponent(cc.Button).interactable = bEnable
    },

    //获取复活卡数量
    getReliftcard: function () {
        return this._activeData.cards
    },

    showFlipResult() {
        let place = this._resultData.placeid
        let cardTypes = ['red', 'gr', 'bl', 'yel', 'org']
        //设置奖励
        let item = cc.find('CH_flipui/reward', this.node)
        item.getComponent('CH_Luckycard_resultitem').init(this._resultData.result[place - 1][0])

        let card1 = cc.find('center/card' + place, this.node)
        this.doFlipCardAction(card1, cardTypes[place - 1])
    },

    //显示其他方位奖励
    _showOtherResult: function (selNode) {
        for (let i = 0; i < 5; i++) {
            let resultItem = cc.find('center/card' + (i + 1), this.node)
            let bSel = false
            if (resultItem == selNode) {
                bSel = true
            }
            resultItem.getComponent('CH_Luckycard_resultcard').showResult(this._resultData.result[i][0], bSel)
        }

        let self = this
        let delayCall = function () {
            if (self._resultData.lucky == 0) {
                //炸弹


            }
            else {
                if (self._resultData.next > STAGE_NUM) {
                    //已经通关了
                    this.showCurStage()

                }
                else {
                    Global.playCashEff('luckycard/next_stage')
                    this.showCurStage()
                    for (let i = 0; i < 5; i++) {
                        let resultItem = cc.find('center/card' + (i + 1), self.node)
                        cc.tween(resultItem)
                            .to(0.3, { scaleX: 0 })
                            .call(() => {
                                resultItem.getComponent('CH_Luckycard_resultcard').showIdle()
                            })
                            .to(0.3, { scaleX: 1 })
                            .call(() => {
                                resultItem.getComponent(cc.Button).interactable = true
                            })
                            .start()


                    }
                }

            }

        }
        this.scheduleOnce(delayCall, 3)
    },

    //翻牌动作
    doFlipCardAction(obj, nType) {
        let self = this
        this._toNode = obj
        let nodeFlip = cc.find('CH_flipui', this.node)
        nodeFlip.active = true
        let flipnode = cc.find('flipcard', nodeFlip)
        flipnode.active = false
        let spr_item = cc.find('reward', nodeFlip)
        spr_item.active = false
        let spr_bom = cc.find('bom', nodeFlip)
        spr_bom.active = false


        let copObj = cc.instantiate(obj)
        copObj.name = 'copyCard'


        copObj.scale = 1
        let toPos = nodeFlip.convertToNodeSpaceAR(obj.convertToWorldSpaceAR(cc.v2(0, 0)))
        copObj.position = toPos
        copObj.parent = nodeFlip
        obj.active = false

        let nSkin = nType //卡片的翻牌

        let playSpineAni = function playSpineAni() {

            copObj.getChildByName('spr_card').active = false
            let questMark = copObj.getChildByName('spine')
            cc.tween(questMark)
                .delay(0.2)
                .to(0.5, { opacity: 0 })
                .start()

            flipnode.active = true
            let ani = flipnode.getComponent(sp.Skeleton)
            ani.setSkin(nSkin)
            ani.setAnimation(0, 'idle1', false)
            ani.addAnimation(0, 'idle2', true)
            ani.setCompleteListener((track) => {

                let name = track.animation ? track.animation.name : "";
                if (name == 'idle2') {
                    ani.setCompleteListener(null)
                    self.clipCloseAni()


                }
            })
        };
        let nTime = Math.abs((toPos.sub(cc.v2(0, 0))).mag()) / 1000
        cc.tween(copObj)
            .to(nTime, { position: cc.v2(-5, 23) })
            .call(() => {
                playSpineAni()

            })
            .delay(1.5)
            .call(() => {
                copObj.active = false
                let showItem = spr_item
                let nTime = 0
                if (this._isBomb()) {
                    nTime = 0.6
                    showItem = spr_bom
                    spr_bom.getComponent(sp.Skeleton).setAnimation(0, 'animation', false)
                    spr_bom.getComponent(sp.Skeleton).paused = true
                    Global.playCashEff('luckycard/gameover')
                }
                else {
                    Global.playCashEff('luckycard/continue')
                }
                showItem.active = true
                showItem.opacity = 0
                cc.tween(showItem)
                    .to(1, { opacity: 255 })
                    .delay(nTime)
                    .call(() => {
                        spr_bom.getComponent(sp.Skeleton).setAnimation(0, 'animation', false)
                        spr_bom.getComponent(sp.Skeleton).paused = false
                    })
                    .start()



            })
            .start()

    },

    clipCloseAni: function (data) {
        //奖励飞到奖池，牌重新归位
        let nDelay = 0
        if (this._isBomb()) {
            nDelay = 0
        }
        this.scheduleOnce(() => {
            if (this._isBomb()) {
                let nodeFlip = cc.find('CH_flipui', this.node)
                nodeFlip.active = false

                this._toNode.active = true
                // 不显示其他方位的奖励，待会复活了还要继续抽此轮
                let i = this._resultData.over[0] - 1
                let resultItem = cc.find('center/card' + (i + 1), this.node)
                resultItem.getComponent('CH_Luckycard_resultcard').showResult(this._resultData.result[i][0], true)

                // this._showOtherResult(this._toNode)

                //弹出结束框
                this.showActiveStateUI(0)
                return
            }
            let nodeFlip = cc.find('CH_flipui', this.node)
            nodeFlip.active = false
            let toPos = this.node.convertToNodeSpaceAR(this._toNode.convertToWorldSpaceAR(cc.v2(0, 0)))
            let nTime = Math.abs((toPos.sub(cc.v2(0, 0))).mag()) / 1000

            let copyNode = cc.instantiate(cc.find('copyCard', nodeFlip))
            copyNode.parent = this.node
            copyNode.active = true
            cc.tween(copyNode)
                .show()
                .to(nTime, { position: toPos })
                .call(() => {
                    this._toNode.active = true
                    this._showOtherResult(this._toNode)
                    if (this._activeData.status != 1) { //未结束
                        this.showActiveStateUI(this._activeData.status)
                    }

                    // this.showCurStage()
                })
                .removeSelf()
                .start()

            //找到奖池中的物品位置
            let posReward
            let hitItemType = this._resultData.result[this._resultData.placeid - 1][0]
            let toRewardItem = this.getRewardPoolItem(hitItemType.s)
            if (!toRewardItem) {
                toRewardItem = cc.find('node_reward/node_reward_item', this.node)
                posReward = this.node.convertToNodeSpaceAR(toRewardItem.convertToWorldSpaceAR(cc.v2(0, 0)))
            }
            else {
                posReward = this.node.convertToNodeSpaceAR(toRewardItem.convertToWorldSpaceAR(cc.v2(0, 0)))
                if (toRewardItem.getComponent('CH_Luckycard_rewarditem').getItemType() == hitItemType.s) {

                }
                else {
                    //拼接到最后一个物品的后面
                    posReward.x += toRewardItem.width
                }
            }





            let spr_item = cc.find('reward/spr_item', nodeFlip)
            let copyreward = cc.instantiate(spr_item)
            copyreward.parent = this.node
            cc.tween(copyreward)
                .to(0.5, { position: posReward })
                .call(() => {
                    this.updateRewards(hitItemType)
                })
                .removeSelf()
                .start()
        }, nDelay)
    },

    //获取奖池中物品位置
    getRewardPoolItem: function (itemType) {
        let target
        let reward_layout = cc.find('node_reward/node_reward', this.node)
        let itemNodes = reward_layout.getComponentsInChildren('CH_Luckycard_rewarditem')
        let lastItem
        for (let i = 0; i < itemNodes.length; i++) {
            let item = itemNodes[i]
            lastItem = item.node
            if (item.getItemType() == itemType) {
                target = item.node
                break
            }
        }
        if (target) {
            return target
        }
        else {
            return lastItem
        }

    },

    //活动状态
    showActiveStateUI: function (activeState) {
        if (activeState == 0) {
            //gameover
            cc.vv.RedSys.clearRedTip(10)
            this.showPickTip(false)

            let url = 'CashHero/prefab/luck_card/CH_Luckycard_Finish'
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    node.getComponent('CH_Luckycard_gameover').init(this)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
            this.showTakeBtnState(false)

            //当前盘面的炸弹位置
            for (let i = 0; i < 5; i++) {
                let resultItem = cc.find('center/card' + (i + 1), this.node)
                if (i + 1 == this._activeData.over[0]) {
                    resultItem.getComponent(cc.Button).interactable = false
                    resultItem.getComponent('CH_Luckycard_resultcard').showResult({ s: Global.PROP_ID.LUCKY_BOM, n: 1 }, true)
                }
                else {
                    resultItem.getComponent(cc.Button).interactable = false
                    resultItem.getComponent('CH_Luckycard_resultcard').showIdle()
                }

            }


        }
        else if (activeState == 1) {
            this.showPickTip(true)
            let node_center = cc.find('center', this.node)
            node_center.active = true
            let node_take = cc.find('node_hastake', this.node)
            node_take.active = false
            let btn_take = cc.find('node_reward/btn_take', this.node)
            btn_take.active = true
            let spr_take = cc.find('node_reward/spr_take', this.node)
            spr_take.active = false
            //未结束
            for (let i = 0; i < 5; i++) {
                let resultItem = cc.find('center/card' + (i + 1), this.node)
                if (this._activeData.over && (this._activeData.over[0] == i + 1)) {
                    resultItem.getComponent(cc.Button).interactable = false
                    resultItem.getComponent('CH_Luckycard_resultcard').showResult({ s: Global.PROP_ID.LUCKY_BOM, n: 1 }, true)
                }
                else {
                    resultItem.getComponent(cc.Button).interactable = true
                    resultItem.getComponent('CH_Luckycard_resultcard').showIdle()
                }

            }
        }
        else if (activeState == 2) {
            //领取过奖励
            cc.vv.RedSys.clearRedTip(10)
            this.showPickTip(false)

            let node_center = cc.find('center', this.node)
            node_center.active = false
            let node_take = cc.find('node_hastake', this.node)
            node_take.active = true
            let btn_take = cc.find('node_reward/btn_take', this.node)
            btn_take.active = false
            let spr_take = cc.find('node_reward/spr_take', this.node)
            spr_take.active = true

            //设置重置信息
            let node_reset = cc.find('node_reset', node_take)
            node_reset.active = this._activeData.shopInfoList
            if (this._activeData.shopInfoList) {
                let lbl_price = cc.find('buy_btn/lbl_text', node_reset)
                // lbl_price.getComponent(cc.Label).string = 'ONLY $' + this._activeData.shopInfoList[0].amount
                I18N.setI18nLabel(lbl_price, cc.vv.Language.btn_only, this._activeData.shopInfoList[0].amount)

                // let timeStr = this._activeData.times>0?this._activeData.times + ' times' : this._activeData.times + ' time'
                // cc.find('lbl_totaltime',node_reset).getComponent(cc.Label).string = cc.js.formatStr('%s left today',timeStr)
                let lbltype = 'luckycard_lefttime1'
                if (this._activeData.times >= 2) {
                    lbltype = (Global.language == Global.LANGUAGE.AR && this._activeData.times == 2) ? 'luckycard_lefttime1' : 'luckycard_lefttime2'
                }
                I18N.setI18nLabel(cc.find('lbl_totaltime', node_reset), cc.vv.Language[lbltype], this._activeData.times)
            }

        }
        else if (activeState == 3) {
            Global.playCashEff('luckycard/take_reward')
            // this.onClickTake()

            let self = this
            let sureCall = function () {
                self._completeFlag = true
                //领取
                cc.vv.NetManager.send({ c: MsgId.REQ_LUCKYCARD_TAKE });
            }
            let tipMsg = "Congratulations you have passed all status, take your rewards right now!"
            cc.vv.AlertView.show(tipMsg, sureCall, null, false, null, "TIPS")

            cc.vv.RedSys.clearRedTip(10)
            this.showPickTip(false)
            // //通关了，但是未领取奖励
            // cc.vv.AlertView.showTips('Congratulations, you have passed and receive the reward immediately!', function () {

            // }.bind(this));
        }
    },

    showPickTip: function (bShow) {
        let tip = cc.find("center/lbl_tips", this.node)
        tip.active = bShow
        Global.blinkAction(tip)
    },

    //一个个弹出显示
    showPopReward: function (datas) {
        // let url = 'CashHero/prefab/luck_card/CH_Luckycard_reward'
        // cc.loader.loadRes(url,cc.Prefab, (err, prefab) => {
        //     if (!err) {
        //         let node = cc.instantiate(prefab)
        //         node.parent = cc.find('Canvas')
        //         node.getComponent('CH_Luckycard_takereward').init(this,datas,this._activeData.jackpot)
        //         this.showActiveStateUI(this._activeData.status)
        //     }
        //     else{
        //         console.log('未找到资源:'+url)
        //     }
        // });

        let self = this
        let pos = cc.find("node_reward", this.node).convertToWorldSpaceAR(cc.v2(0, 0))
        Global.RewardFly(datas, pos, () => {
            self.showActiveStateUI(self._activeData.status)

        })
    },

    OnRcvActiveInfo: function (msg) {
        if (msg.code == 200) {
            this._activeData = msg
            this.showCurStage()
            this.showActionBaseInfo()
            this.showRewards()

            this.showActiveStateUI(this._activeData.status)
        }
    },

    OnRcvFlipCard: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode == 0) {
                this._resultData = msg
                this._activeData.jackpot = msg.jackpot
                this._activeData.lv = msg.next
                this._activeData.over = msg.over
                //游戏状态TODO
                this._activeData.status = msg.status
                this.showFlipResult()
            }

        }
    },

    //领取奖励
    OnRcvTakeReward: function (msg) {
        if (msg.code == 200) {
            this._activeData.status = 2
            this._activeData.shopInfoList = msg.shopInfoList


            this.showPopReward(msg.rewards)

        }
    },

    _isBomb: function () {
        let resType = this._resultData.result[this._resultData.placeid - 1][0]
        if (resType && resType.s == Global.PROP_ID.LUCKY_BOM) {
            return true
        }
        return false
    },

    OnRcvCardRelife: function (msg) {
        if (msg.code == 200) {
            //更新状态并且刷新显示
            this._activeData.status = msg.status
            this._activeData.lv = msg.lv
            this._activeData.cards = msg.cards

            this.showCurStage()
            this.showActionBaseInfo()
            this.showRewards()
            this.showActiveStateUI(this._activeData.status)

        }
    },

    OnRcvBuyCardRes: function (msg) {
        if (msg.code == 200) {
            this._activeData.cards = msg.cards
            this.showActionBaseInfo()

            //添加金币
            cc.vv.UserManager.AddCoin(msg.add, true)
            //刷新
            cc.vv.NetManager.send({ c: MsgId.REQ_LUCKYCARD_INFO });

            cc.loader.loadRes("CashHero/prefab/buyRewardPop/buyRewardPop", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("buyRewardPop")) {
                    let node = cc.instantiate(prefab)
                    node.name = "buyRewardPop"
                    node.parent = canvas
                    node.getComponent("buyRewardPop").buyCard(msg)
                }
            })
        }
    },

    OnRcvBuyList: function (msg) {
        if (msg.code == 200) {
            let url = 'CashHero/prefab/luck_card/CH_Luckycard_buy'
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let par = cc.find('Canvas')
                    if (!cc.find('CH_Luckycard_buy', par)) {
                        let node = cc.instantiate(prefab)
                        node.parent = cc.find('Canvas')
                        node.getComponent('CH_Luckycard_buy').init(msg.shoplist)
                    }


                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        }
    },

    onEventItemChange: function (data) {
        let val = data.detail
        if (val && val.id == Global.PROP_ID.LUCKY_RESTART) {
            this._activeData.cards += val.num
            //刷新显示
            this.showActionBaseInfo()
        }
    },

    //点了重置
    onClickReset: function () {
        Global.playComEff("ch_btn_click");
        if (this._activeData.shopInfoList) {
            let pid = this._activeData.shopInfoList[0].id
            if (cc.sys.isBrowser) {
                cc.vv.NetManager.send({ c: 355, id: pid })

            }
            else {
                cc.vv.PayMgr.reqPurchaseOrder(pid);
            }
        }

    },

    //重置次数
    OnRcvRestTime: function (msg) {
        if (msg.code == 200) {
            this._activeData.status = 1
            this._activeData.jackpot = []
            this._activeData.lv = 1
            if (this._activeData.times) {
                this._activeData.times -= 1
            }
            else {
                this._activeData.times = 3
            }
            this.showCurStage()
            this.showActionBaseInfo()
            this.showRewards()

            this.showActiveStateUI(this._activeData.status)
        }
    },
    // update (dt) {},
});
