/**
 * 好友详情JPListitem
 * 
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    showItemInfo: function (info) {
        let gameId = info.gameid
        let gameCfg = cc.vv.HerocardManager.getCardCfgByGame(Number(gameId))
        if (gameCfg) {
            // //icon
            // let sprIcon = cc.find('game_icon',this.node)
            // let url = 'CashHero/slots/smalllogo/'+gameId
            // this._loadgameIcon(url,sprIcon,gameId)
            //ani
            cc.find('slot_icon', this.node).getComponent('CH_SlotIcon').setGameId(gameId, "animation2")
            //name
            let lblName = cc.find('lblName', this.node)
            // lblName.getComponent(cc.Label).string = gameCfg.title
            I18N.setI18nLabel(lblName, cc.vv.Language["cardname_" + gameCfg.cardid])

            //coin
            let lblJpCoin = cc.find('node_coin/lbl_coin', this.node)
            lblJpCoin.getComponent(cc.Label).string = Global.FormatNumToComma(info.coin || 0)

            let lblTime = cc.find('lbl_time', this.node)
            lblTime.getComponent(cc.Label).string = Global.getTimeStr(info.time, false)
        }
    },

    _loadgameIcon: function (url, obj, exData) {
        if (exData) {
            obj.userTag = exData
        }

        cc.loader.loadRes(url, cc.SpriteFrame, (err, res) => {
            if (!err) {
                if (obj) {
                    // let spriteFrameName = res.name
                    // console.log('资源名：'+spriteFrameName)
                    // console.log('资源URL：'+res.url)
                    if (obj.userTag) {
                        if (obj.userTag == res.name) {
                            obj.getComponent(cc.Sprite).spriteFrame = res
                        }
                    }
                    else {
                        obj.getComponent(cc.Sprite).spriteFrame = res
                    }

                }
            }
        })
    }

    // update (dt) {},
});
