cc.Class({
    extends: cc.Component,

    properties: {
        obj: cc.Node,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClickShowTip, this)
        this.tipFlag = false
    },

    start() {

    },

    onClickShowTip() {
        if (this.tipFlag && this.obj.active) {
            return
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MISSION_TIP)
        this.tipFlag = true
        this.obj.active = true
        this.obj.opacity = 0
        cc.tween(this.obj)
            .to(0.2, { opacity: 255 })
            .delay(3)
            .to(0.5, { opacity: 0 })
            .call(() => {
                this.tipFlag = false
            })
            .start()
    },


    // update (dt) {},
});
