//任务状态
let MISSION_STATUS = {
    LOCK_UNACTIVE: 0,     //锁住未激活
    UNENABLE_COLLECT: 1,   //未达成不可领取
    ENABLE_COLLECT: 2,     //已达成可领取
    HAD_COLLECTED: 3,      //已经领取
};

let COINSNUM = [
    380000,
    880000,
    1900000,
];

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _time: 0,
        _inter: 0,
        _taskId: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        //注册网络事件
        this.registerMsgEvent();

        this._btnClose = cc.find("closeBtn", this.node);
        Global.btnClickEvent(this._btnClose, this.onClickClose, this);
        this.setCloseBtnEnable(false)

        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }

        StatisticsMgr.reqReport(StatisticsMgr.REQ_LVUPPARTY_POP)
    },

    start() {
        Global.FixDesignScale_V(this.node)
        this.reqLevelUpPartyInfo()
        cc.find('levelNode', this.node).active = false
    },

    registerMsgEvent() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_LEVEL_UP_PARTY_INFO, this.onRcvNetLevelUpPartyInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_LEVEL_UP_PARTY_AWARD, this.onRcvNetCollectMissionPrize, this);
    },

    onDestroy() {
        cc.vv.QueueWinMrg.nextPop()
        cc.vv.gameData.ResumeSlot()
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LEVEL_UP_PARTY_INFO, this.onRcvNetLevelUpPartyInfo, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LEVEL_UP_PARTY_AWARD, this.onRcvNetCollectMissionPrize, this);
    },

    update(dt) {
        //倒计时刷新
        if (this._time > 0) {
            this._inter += dt
            if (this._inter >= 1) {
                this._time--
                this._inter = 0
                this.setTime()
            }
        }
    },

    reqLevelUpPartyInfo() {
        cc.vv.NetManager.send({ c: MsgId.REQ_LEVEL_UP_PARTY_INFO });
    },

    setTime() {
        if (this._time < 1) {
            Global.dispatchEvent(EventId.LEVELUPPARTY_CLOSE)
        }
        Global.setLabelString('time', cc.find('sand', this.node), Global.formatSec(this._time))
    },

    onRcvNetLevelUpPartyInfo(msgData) {
        if (msgData.code === 200) {
            this._time = msgData.leftTime;
            if (this._time > 0) {
                //发协议检测是否时间一样
                Global.dispatchEvent(EventId.LEVELUPPARTY_UPDATETIME, { time: this._time + 1 })
                this.setTime()
                this.initActivityPanel(msgData);
                Global.isExistLevelUpParty = true;
            }
        }
    },

    reqNetCollectPrize(taskidx) {
        cc.vv.NetManager.send({ c: MsgId.REQ_LEVEL_UP_PARTY_AWARD, taskidx: taskidx });
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LVUPPARTY_COLLECT)
    },

    onRcvNetCollectMissionPrize(msgData) {
        if (msgData.code === 200) {
            if (msgData.rewards) {
                this._taskIdx = msgData.taskidx
                this.scheduleOnce(() => {
                    this._showResultRewards(msgData.rewards)
                }, 0.5)

                if (this._taskIdx == 3) {
                    Global.dispatchEvent(EventId.LEVELUPPARTY_CLOSE)
                }
            }
        }
    },

    _showResultRewards(rewards) {
        let self = this
        // let coin = rewards[0].count
        // let toNode = cc.find(Global.INGAME_COIN_NODE_PATH)
        // cc.loader.loadRes("CashHero/prefab/fbShare/fbColloctReward",cc.Prefab, (err, prefab) => {
        //     if(!err){
        //         let objParent = cc.find('Canvas')
        //         if(!cc.find('fbColloctReward',objParent)){
        //             let endCall = function(){
        //                 cc.vv.gameData.AddCoin(coin, true)
        //                 self.setCloseBtnEnable(true)
        //                 self.nextStepFunc()
        //                 self.autoClose()
        //             }
        //             let node = cc.instantiate(prefab)
        //             node.name = 'fbColloctReward'
        //             node.parent = objParent
        //             let scp = node.getComponent('fbColloctReward')
        //             if(scp){
        //                 scp.setRd(rewards,false,true)
        //                 scp.setCoin(toNode,endCall)
        //             }
        //         }
        //     }
        // })

        let pos = cc.find(cc.js.formatStr("levelNode/level%s/item", this._taskIdx), this.node).convertToWorldSpaceAR(cc.v2(0, 0))
        Global.RewardFly(rewards, pos, () => {
            self.setCloseBtnEnable(true)
            self.nextStepFunc()
            self.autoClose()
        })

    },

    nextStepFunc() {
        //打勾
        this.setChoose(true)
        //是否解开下一个任务
        if (this._id < 3) {
            let _nextNode = cc.find(cc.js.formatStr("levelNode/level%s", this._id + 1), this.node)
            this.setLock(false, _nextNode)
        }
    },

    //自动关闭
    autoClose: function () {
        let self = this
        //是否需要自动关闭
        if (cc.vv.gameData) {
            let nextCall = function () {
                self.onClickClose()
            }
            cc.vv.gameData.checkAutoPlay(this.node, nextCall)
        }

    },

    setChoose(flag, i) {
        let _id = i ? i : this._id
        let _curNode = cc.find(cc.js.formatStr("levelNode/level%s", _id), this.node)
        cc.find('choose', _curNode).active = flag
    },

    setLock(flag, node) {
        //设置阴影状态
        cc.find('lock', node).active = flag
    },

    //初始化活动面板
    initActivityPanel(data) {
        //设置当前等级
        // Global.setLabelString('curLevelLabel', this.node, 'CURRENT LEVEL:'+cc.vv.UserManager.getCurLv())
        I18N.setI18nLabel(cc.find('curLevelLabel', this.node), cc.vv.Language.levelupparty_curlv, cc.vv.UserManager.getCurLv())

        let _canClick = true
        //任务详情
        for (let i = 1; i <= 3; i++) {
            let _curMissionType = data.tasks[i - 1].state
            let _curNode = cc.find(cc.js.formatStr("levelNode/level%s", i), this.node)
            let _canCollect = _curMissionType == MISSION_STATUS.ENABLE_COLLECT && !data.tasks[i - 1].award
            //设置等级
            // cc.find('item/label',_curNode).getComponent(cc.Label).string = 'REACH LEVEL '+data.tasks[i-1].targetLv
            I18N.setI18nLabel(cc.find('item/label', _curNode), cc.vv.Language.levelupparty_realv, data.tasks[i - 1].targetLv)
            //设置金币
            cc.find('item/layout/itemCoin/label', _curNode).getComponent(cc.Label).string = Global.convertNumToShort(data.tasks[i - 1].scale * COINSNUM[i - 1])

            //设置阴影状态 只要没领取就是锁住
            cc.find('lock', _curNode).active = _curMissionType == MISSION_STATUS.LOCK_UNACTIVE || (!_canClick && _curMissionType == MISSION_STATUS.UNENABLE_COLLECT)

            //设置选中
            this.setChoose(_curMissionType == MISSION_STATUS.HAD_COLLECTED || data.tasks[i - 1].award, i)

            //如果有可领取的奖励自动领取 不能点击 奖励弹完后才能点
            if (_canCollect) {
                _canClick = false
                //领取奖励-》打勾
                this.reqNetCollectPrize(i)
                this._id = i
            }
        }
        //初始化完显示 
        cc.find('levelNode', this.node).active = true
        this.setCloseBtnEnable(_canClick)

        if (_canClick) {
            //8秒自动关闭 弹出动作后调用
            this.scheduleOnce(() => {
                cc.tween(this.node)
                    .delay(7)
                    .call(() => {
                        this.onClickClose()
                    })
                    .start();
            }, 1)
        }
    },

    setCloseBtnEnable(flag) {
        this._clickEnableFlag = flag
        this._btnClose.getComponent(cc.Button).interactable = flag
    },

    onClickClose() {
        if (!this._clickEnableFlag) {
            return
        }
        this.node.destroy()
    },
});
