cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {},

    InitCommComponent: function () {
        this._super()
        let safeNode = cc.find('Canvas/safe_node')
        let slots = cc.find('Canvas/safe_node/slots')
        let stayKuang = slots.getComponentInChildren("Mulan_kuang")
        if (stayKuang) {
            cc.vv.gameData.setStayKuang(stayKuang)
        }
        let collect = slots.getComponentInChildren("Mulan_CollectNode")
        if (collect) {
            cc.vv.gameData.setCollectNode(collect)
        }
        let qiepin = safeNode.getComponentInChildren("Mulan_qiePin")
        if (qiepin) {
            cc.vv.gameData.setQiePin(qiepin)
        }
        let popWin = safeNode.getComponentInChildren("Mulan_Pop")
        if (popWin) {
            cc.vv.gameData.setPopWinManage(popWin)
        }
        let WheelNode = safeNode.getComponentInChildren("Mulan_WheelNode")
        if (WheelNode) {
            cc.vv.gameData.setWheelNode(WheelNode)
        }
    },
});
