const List = require('List');
let HEROLIST = {
    ALL: 0,
    GOLD: 1001,
    WOOD: 1002,
    WATER: 1003,
    FIRE: 1004,
    SOIL: 1005,
};

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        listview: List,
        scrollView: cc.ScrollView,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('askBtn', this.node), this.onClickAsk, this)
        Global.btnClickEvent(cc.find('closeBtn', this.node), this.onClickClose, this)
        this._chooseCardId = 0
        this.askBtnEnable(this._chooseCardId)
    },

    start() {
        Global.registerEvent(EventId.CARDGIFT_CHOOSE, this.onEventCardGiftChoose, this)
        this.onTabToALLClick()
    },

    setCallBack(callFunc, uid) {
        if (callFunc) {
            this._callFunc = callFunc
        }
        if (uid) {
            this._toUID = uid
        }
    },

    askBtnEnable(flag) {
        let askBtn = cc.find('askBtn', this.node)
        askBtn.getComponent(cc.Button).interactable = flag
        Global.showSpriteGray(cc.find('Background', askBtn), !flag)
    },

    onEventCardGiftChoose(data) {
        this._chooseCardId = data.detail
        this.askBtnEnable(this._chooseCardId)
    },

    onTabToALLClick() {
        Global.playComEff("ch_btn_click")
        this._listData = cc.vv.HerocardManager.getCardListByCamp(HEROLIST.ALL)
        this.showRankList()
    },

    onTabToFireClick() {
        Global.playComEff("ch_btn_click")
        this._listData = cc.vv.HerocardManager.getCardListByCamp(HEROLIST.FIRE)
        this.showRankList()
    },
    onTabToWoodClick() {
        Global.playComEff("ch_btn_click")
        this._listData = cc.vv.HerocardManager.getCardListByCamp(HEROLIST.WOOD)
        this.showRankList()
    },
    onTabToWaterClick() {
        Global.playComEff("ch_btn_click")
        this._listData = cc.vv.HerocardManager.getCardListByCamp(HEROLIST.WATER)
        this.showRankList()
    },
    onTabToGoldClick() {
        Global.playComEff("ch_btn_click")
        this._listData = cc.vv.HerocardManager.getCardListByCamp(HEROLIST.GOLD)
        this.showRankList()
    },
    onTabToSoilClick() {
        Global.playComEff("ch_btn_click")
        this._listData = cc.vv.HerocardManager.getCardListByCamp(HEROLIST.SOIL)
        this.showRankList()
    },

    showRankList() {
        this._listData.sort(function sortArray(a, b) {
            var value1 = a.chips
            var value2 = b.chips
            return value2 - value1
        })
        this.listview.numItems = this._listData.length > 0 ? this._listData.length : 0;
        this.listview.active = (this._listData.length > 0);

        this.scrollView.scrollToTop(0.1)
    },

    OnListVRender(item, idx) {
        if (this._listData[idx]) {
            item.getComponent('CH_FriendCardGiftItem').initData(this._listData[idx], this._chooseCardId)
        } else {
            if (item) {
                item.active = false
            }
        }
    },

    sendReq: function (cardid) {
        let req = {}
        req.c = MsgId.REQ_PRIVATE_SEND
        req.type = 2
        req.uid = Global.playerData.uid
        req.touid = this._toUID
        req.msg = cardid
        cc.vv.NetManager.send(req)
    },

    onClickAsk() {
        Global.playComEff("ch_btn_click")
        this.askBtnEnable(false)

        if (this._callFunc) {
            this._callFunc()
        }

        //告诉服务器
        this.sendReq(this._chooseCardId)

        this.node.destroy()
    },

    onClickClose() {
        this.node.destroy()
    },

    // update (dt) {},
});
