/**
 * 砸蛋slot机台中入口
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClickEntrance, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYSMASH_INFO, this.onRcvNetLucksmashInfo, this)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYSMASH_INFO, this.onRcvNetLucksmashInfo, false, this)
    },

    start() {
        this.checkActivityTips()
    },

    //检测是否显示活动提示
    checkActivityTips() {
        // if(this.isTaskOpen()){
        if (!cc.vv.UserManager.activityTipsInGame) {
            cc.vv.UserManager.activityTipsInGame = true
            let deskInfo = cc.vv.gameData.getDeskInfo()
            if (deskInfo && deskInfo.wday == 6 && cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_SMASH)) {   //周六提示砸蛋
                let tips = cc.find("activity_tips", this.node)
                let smachTip = cc.find('tip_smash', tips)
                smachTip.active = true
                tips.active = true
                tips.opacity = 0
                tips.runAction(cc.sequence(cc.fadeIn(0.25), cc.delayTime(3), cc.fadeOut(0.25)))
            }
        }
        // }

    },

    onClickEntrance: function () {
        let old = cc.find("Canvas/lucky_main")
        if (old) return
        let url = "CashHero/prefab/lucky_smash/lucky_main"
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.name = "lucky_main"
                node.parent = cc.find("Canvas")

            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    _showText: function (leftTime) {
        let showStr
        if (leftTime > 86400) {
            let day = Math.floor(leftTime / 86400)
            showStr = day > 1 ? cc.js.formatStr('In %s Days', day) : cc.js.formatStr('In %s Day', day)

        }
        else {
            showStr = "Lucky Day"
        }
        Global.setLabelString("text", this.node, showStr)

    },

    requestData() {
        // this._refresh = false
        let req = { c: MsgId.REQ_LUCKYSMASH_INFO };
        cc.vv.NetManager.send(req);
    },

    onRcvNetLucksmashInfo(msg) {
        if (msg.code == 200) {
            this._serverInfo = msg
            this._leftTime = this._serverInfo.end_time
            if (this._leftTime > 86400) {  //非砸蛋日
                this._status = 0
            } else {
                this._status = 1
            }
            this._showText(this._leftTime)
        }
    },

    // update (dt) {},
});
