
/**
 * shop tab页面中 weekCard monthCard
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _lblLeftTime: null,
        _btnBuy: null,
        _btnCollect: null,

        _data: null,

        _sumTime: 0,
        _restTime: 0,

        _stype: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._lblLeftTime = cc.find("lbl_leftTime", this.node);
        this._btnBuy = cc.find('buy_btn', this.node);
        this._btnCollect = cc.find('collect_btn', this.node);

        Global.btnClickEvent(cc.find("buy_btn", this.node), this.onClickBuy, this);
        Global.btnClickEvent(cc.find("collect_btn", this.node), this.onClickCollect, this);
    },

    start() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_COLLECT_WEEK_MONTH_CARD, this.onRcvNeCollectCoin, this);
        cc.vv.NetManager.registerMsg(MsgId.NOTICE_BUY_WEEK_MONTH_CARD_SUCCESS, this.onRcvNeBuySuccess, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_TRIAL_CARD, this.onRcvGetTrialCard, this);

        this._showUI(this._data)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_COLLECT_WEEK_MONTH_CARD, this.onRcvNeCollectCoin, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.NOTICE_BUY_WEEK_MONTH_CARD_SUCCESS, this.onRcvNeBuySuccess, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_TRIAL_CARD, this.onRcvGetTrialCard, false, this);
    },

    // update (dt) {
    //     this._sumTime += dt;
    //     if (this._sumTime >= 1) {
    //         this._sumTime -= 1;
    //         this._restTime -= 1;
    //         this.refreshRestTime();
    //
    //         if (this._restTime < 0) {
    //             // Todo ... 显示
    //         }
    //     }
    // },

    setShowData: function (data, stype) {
        this._data = data
        this._stype = stype;


    },

    _showUI: function (data) {
        let state = data.collect; //0只能购买 1需要收集了 2今日已收集过了

        this._lblLeftTime.getComponent(cc.Label).string = data.leftdays + " DAYS LEFT";
        let _lanStr = cc.vv.Language['lefttime3']
        if (data.leftdays >= 2) {
            _lanStr = (data.leftdays == 2 && Global.language == Global.LANGUAGE.AR) ? cc.vv.Language['lefttime3'] : cc.vv.Language['lefttime4']
        }
        // I18N.setI18nLabel(cc.find("img_timeout_bg/lbl_leftTime", this.node),_lanStr,data.leftdays)
        // cc.find("img_timeout_bg", this.node).active = state != 0;

        let lbl_total = cc.find('lbl_total', this.node)
        lbl_total.getComponent(cc.Label).string = Global.FormatNumToComma(data.total);

        let lbl_more = cc.find('more_mark/lbl_more', this.node);
        // lbl_more.getComponent(cc.Label).string = data.discount + "%\nMORE";
        I18N.setI18nLabel(lbl_more, cc.vv.Language.shop_weekormonth_800more, data.discount)

        let lbl_price = cc.find('buy_btn/lbl_price', this.node);
        // lbl_price.getComponent(cc.Label).string = "For $ " + data.amount;
        I18N.setI18nLabel(lbl_price, cc.vv.Language.btn_for, data.amount)

        let lbl_gold_num1 = cc.find("Item1/lbl_num", this.node);
        lbl_gold_num1.getComponent(cc.Label).string = Global.FormatNumToComma(data.count);

        let lbl_gold_num2 = cc.find("Item2/lbl_num", this.node);
        lbl_gold_num2.getComponent(cc.Label).string = Global.FormatNumToComma(data.countday);

        this._btnBuy.active = state == 0;
        this._btnCollect.active = state != 0;
        this._btnCollect.getComponent(cc.Button).interactable = state == 1;

        //月卡试用功能
        if (this._stype == 15) {
            let btnTrial = cc.find("btn_trial", this.node)
            if (btnTrial) {
                btnTrial.off("click")
                btnTrial.on("click", this.onClickTrail, this)

                //试用: -1:未开启 0:使用结束 1/2/3试用剩余天数  <100未领取 >100已领取
                let trial = data.trial
                btnTrial.active = (state == 0 && trial > 0)
                btnTrial.getComponent(cc.Button).interactable = ((trial >= 1 && trial <= 3))
                let tagTrial = cc.find("tag_trial", this.node)
                tagTrial.active = (state == 0 && trial > 0)
            }

        }
    },

    // refreshRestTime () {
    //     this._lblLeftTime.getComponent(cc.Label).string = this.getTimeStr(this._restTime);
    // },
    //
    // getTimeStr(a) {
    //     if (a > 3600*24) {
    //         return Math.ceil(a/(3600*24)) + " DAYS LEFT";
    //     }
    //     else {
    //         return Math.ceil(a/3600) + " HOURS LEFT";
    //     }
    // },

    onClickBuy: function () {
        if (this._data == null) return;

        // this._btnBuy.getComponent(cc.Button).interactable = false;

        // console.log('打开充值:'+this._data.id)
        cc.vv.PayMgr.reqPurchaseOrder(this._data.id);

        // cc.vv.NetManager.send({c:283, stype:this._stype}); //测试模拟购买周卡月卡接口
        if (this._stype == 15) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_MONTHCARD)
        }
        else {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_WEEKCARD)
        }

    },

    onClickCollect: function () {
        this._btnCollect.getComponent(cc.Button).interactable = false;
        cc.vv.NetManager.send({ c: MsgId.REQ_COLLECT_WEEK_MONTH_CARD, stype: this._stype });
        let redType = 22
        if (this._stype == 15) {
            redType = 23
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_MONTHCARD_COLLECT)
        }
        cc.vv.RedSys.clearRedTip(redType)
    },

    onClickTrail: function () {
        let trial = this._data.trial
        if (trial >= 1 && trial <= 3) { //开启
            cc.find("btn_trial", this.node).getComponent(cc.Button).interactable = false
            cc.vv.NetManager.send({ c: MsgId.REQ_GET_TRIAL_CARD, stype: this._stype })
        }
    },

    showCollectCoin(coin, addCoin) {
        cc.vv.UserManager.coin = coin;

        let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        if (cc.vv.gameData) {
            toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
        }

        let rollData = {}
        rollData.lblCoin = toLbl;
        rollData.addCoin = addCoin;
        rollData.begin = (coin - addCoin)
        let srcObj = cc.find("Item2/lbl_num", this.node);


        Global.FlyCoin(srcObj, endNode, () => { }, rollData, true)
    },

    onRcvNeCollectCoin(msg) {
        if (msg.stype != this._stype) return;

        if (msg.code === 200) {
            this._data.collect = 2;
            this._showUI(this._data);
            this.showCollectCoin(msg.coin, msg.addCoin)
        }
        else {
            let str = "";
            switch (msg.code) {
                case 210:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_invalid_parameter);
                    // str = "Invalid Parameter!";
                    break;
                case 496:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_had_collected);
                    // str = "Had Collected!";
                    break;
                default:
                    break;
            }
            // if (str) {
            //    cc.vv.FloatTip.show(str);
            // }

            this._btnCollect.getComponent(cc.Button).interactable = true;
        }
    },

    onRcvNeBuySuccess(msg) {
        if (msg.stype != this._stype) return;

        if (msg.code === 200) {
            this._data.collect = 1;
            this._showUI(this._data);
        }
        else {
            let str = "";
            switch (msg.code) {
                case 210:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_invalid_parameter);
                    // str = "Invalid Parameter!";
                    break;
                case 496:
                    // str = "Had Collected!";
                    break;
                default:
                    break;
            }
            // if (str) {
            // cc.vv.FloatTip.show(str);
            // }

            this._btnBuy.getComponent(cc.Button).interactable = true;
        }
    },

    onRcvGetTrialCard(msg) {
        if (msg.stype != this._stype) return;

        if (msg.code == 200) {
            this._data.trial = msg.trial
            this._showUI(this._data)
            this.showCollectCoin(msg.coin, msg.addCoin)
        } else {
            cc.vv.FloatTip.show("Had Collected!");
        }
    },

});
