require('GlobalVar');

Global.FlyAnimToPos = function (fromWordPos, toWordPos, parm) {
    let spriteFrame = parm.spriteFrame;
    let pool = parm.pool;
    let prefab = parm.prefab;
    let scale = parm.scale || 1;
    let endScale = parm.endScale || 1;
    let delay = parm.delay || 0;
    let onStart = parm.onStart;
    let onEnd = parm.onEnd;
    let onEndOne = parm.onEndOne;
    let count = parm.count || 20;
    let onInit = parm.onInit;
    let noBoom = parm.boom || false;
    let rangeX = parm.rangeX || 150;
    let rangeY = parm.rangeY || 150;

    if ((spriteFrame || prefab)) {
        let Canvas = cc.find("Canvas")
        // let fromWordPos = fromNode.convertToWorldSpaceAR(cc.v2(0, 0))
        // let toWordPos = toNode.convertToWorldSpaceAR(cc.v2(0, 0))
        // let fromNodePos = Canvas.convertToNodeSpaceAR(fromWordPos)
        // let toNodePos = Canvas.convertToNodeSpaceAR(toWordPos)

        let tempNodes = [];
        for (let i = 0; i < count; i++) {
            let flyNode = null;
            if (spriteFrame) {
                if (pool) flyNode = pool.get()
                if (!flyNode) {
                    flyNode = new cc.Node()
                    flyNode.addComponent(cc.Sprite)
                }
                flyNode.getComponent(cc.Sprite).spriteFrame = spriteFrame;
            } else if (prefab) {
                if (pool) flyNode = pool.get()
                if (!flyNode) flyNode = cc.instantiate(prefab)
            }
            flyNode.parent = Canvas;
            onInit && onInit(i, flyNode);
            flyNode.stopAllActions()
            flyNode.opacity = 255
            flyNode.scale = scale;
            flyNode.zIndex = 1000;
            flyNode.position = cc.v2(0, 0)
            flyNode.active = false;
            tempNodes.push(flyNode)
        }

        let isStart = false;
        let indexAnim = 0;
        // 给予动画
        for (let i = 0; i < tempNodes.length; i++) {
            const _node = tempNodes[i];
            let s = Global.FixDesignScale_V(_node)
            let fixEndScale = endScale * s
            _node.position = _node.parent.convertToNodeSpaceAR(fromWordPos)
            // 随机生成一个中间位置
            let tempPos = _node.parent.convertToNodeSpaceAR(fromWordPos).add(cc.v2(Math.random() * rangeX * 2 - rangeX, Math.random() * rangeY * 2 - rangeY));
            // 随机时间
            let animTime = 0.1 + Math.random() * 0.3;
            let delayTime = 0.3 + Math.random() * 0.3;
            let moveTime = 0.3 + Math.random() * 0.3;
            if (!noBoom) {
                cc.tween(_node)
                    .delay(delay)
                    .call(() => {
                        _node.active = true;
                        // 回调
                        if (!isStart) {
                            onStart && onStart();
                            isStart = true;
                        }
                    })
                    .to(animTime, { position: tempPos })
                    .delay(delayTime)
                    .to(moveTime, { position: _node.parent.convertToNodeSpaceAR(toWordPos), scale: fixEndScale })
                    .call(() => {
                        indexAnim++;
                        // if (tempNodes.indexOf(_node) >= tempNodes.length - 1) {
                        // }
                        if (indexAnim >= tempNodes.length) {
                            onEnd && onEnd(_node);
                        }
                        onEndOne && onEndOne(_node);
                        if (pool) pool.put(_node)
                        else _node.destroy()
                    })
                    .start();
            } else {
                _node.active = true;
                // 回调
                if (!isStart) {
                    onStart && onStart();
                    isStart = true;
                }
                _node.position = tempPos;
                cc.tween(_node)
                    .delay(delayTime)
                    .to(moveTime, { position: _node.parent.convertToNodeSpaceAR(toWordPos), scale: fixEndScale })
                    .call(() => {
                        indexAnim++;
                        // if (tempNodes.indexOf(_node) >= tempNodes.length - 1) {
                        // }
                        if (indexAnim >= tempNodes.length) {
                            onEnd && onEnd(_node);
                        }
                        onEndOne && onEndOne(_node);
                        if (pool) pool.put(_node)
                        else _node.destroy()
                    })
                    .start();

            }

        }
    }
}

//奖励收集动画（多个奖励）
Global.RewardFly = function (rewards, fromWorldPos, callback) {
    let flyNode = cc.find("Canvas/RewardFlyAnim");
    if (flyNode) {
        flyNode.active = true
        flyNode.getComponent("RewardFlyAnim").run(rewards, fromWorldPos, callback);
    } else {
        cc.loader.loadRes("CashHero/prefab/RewardFlyAnim", cc.Prefab, (err, prefab) => {
            if (err == null) {
                let node = cc.instantiate(prefab);
                node.parent = cc.find("Canvas")
                node.zIndex = 1000;
                node.position = cc.v2(0, 0);
                node.getComponent("RewardFlyAnim").scheduleOnce(() => {
                    node.getComponent("RewardFlyAnim").run(rewards, fromWorldPos, callback);
                })
                // node.getComponent("RewardFlyAnim").run(rewards, fromWorldPos);
            }
        });
    }
}

//奖励收集动画（单个奖励）
//propid: 物品ID
//count: 物品数量
Global.RewardPropFly = function (propid, count, fromWorldPos, callback) {
    let rewards = [{ type: propid, count: count }]
    return Global.RewardFly(rewards, fromWorldPos, callback)
}

//金币收集动画
//count：金币数量
Global.RewardCoinFly = function (count, fromWorldPos, callback) {
    return Global.RewardPropFly(Global.PROP_ID.COIN, count, fromWorldPos, callback)
}
