cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },

    onLoad() {
        let btnClose = cc.find('newSeason/closeBtn', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)

        let btnOk = cc.find('timeLeft/okBtn', this.node)
        Global.btnClickEvent(btnOk, this.onClickOkClose, this)
        let btnOkClose = cc.find('timeLeft/okCloseBtn', this.node)
        Global.btnClickEvent(btnOkClose, this.onClickOkClose, this)

        let btnEnjoy = cc.find('newSeason/enjoyBtn', this.node)
        Global.btnClickEvent(btnEnjoy, this.onClickEnjoy, this)

        let btnOkEnjoy = cc.find('newSeason/okSeasonBtn', this.node)
        Global.btnClickEvent(btnOkEnjoy, this.onClickClose, this)

        cc.find('timeLeft', this.node).active = false
        cc.find('newSeason', this.node).active = false

        this.countData = null
        this._inter = 0
        this._typeLeft = 1
        cc.vv.NetManager.registerMsg(MsgId.REQ_BINGO_INFO, this.onRcvNetBingoInfo, this)
    },

    start() {

    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_BINGO_INFO, this.onRcvNetBingoInfo, false, this)
    },

    onRcvNetBingoInfo() { },

    //最后10min/10sec
    leftTime(_data, count) {
        cc.find('timeLeft', this.node).active = true
        cc.find('newSeason', this.node).active = false
        this.data = _data
        this.countData = count
        let _str = Global.formatSec(this.countData)
        Global.setLabelString("timeLeft/clockTime", this.node, _str)

        if (count > 15) {
            this._typeLeft = 1
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_LEFT10M_POP, cc.vv.UserManager.getBingoFrom())
        } else {
            this._typeLeft = 2
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_LEFT10S_POP, cc.vv.UserManager.getBingoFrom())
        }

        let tips = "The Bingo will be finished soon"
        if (!this.countData) {
            tips = "The Bingo is finished, see you next time!"
        }
        this.setLeftLblText(tips)
    },

    //当天  type=1 子游戏过来
    firstDay(_data) {
        cc.find('timeLeft', this.node).active = false
        let seasonNode = cc.find('newSeason', this.node)
        seasonNode.active = true

        if (cc.vv.gameData) {
            if (this.node.parent.getChildByName('bingo_main')) {
                //main
                cc.find('enjoyBtn', seasonNode).active = true
                cc.find('okSeasonBtn', seasonNode).active = false
            } else {
                //子游戏
                cc.find('enjoyBtn', seasonNode).active = false
                cc.find('okSeasonBtn', seasonNode).active = true
            }
        } else {
            //大厅
            cc.find('enjoyBtn', seasonNode).active = true
            cc.find('okSeasonBtn', seasonNode).active = false
        }

        let data = _data
        let startData = new Date(data.startTime * 1000)
        var startDay = parseInt(startData.getDate())
        if (startDay < 10) {
            startDay = '0' + startDay
        }
        var startMon = startData.getMonth() + 1
        if (startMon < 10) {
            startMon = '0' + startMon
        }
        cc.find('newSeason/startTop', this.node).getComponent(cc.Label).string = startMon + '/' + startDay + '/' + startData.getFullYear()
        // cc.find('newSeason/startButton', this.node).getComponent(cc.Label).string = Global.getTimeStr(_data.startTime, true)

        let endData = new Date(data.endTime * 1000)
        var endDay = parseInt(endData.getDate())
        if (endDay < 10) {
            endDay = '0' + endDay
        }
        var endMon = endData.getMonth() + 1
        if (endMon < 10) {
            endMon = '0' + endMon
        }
        cc.find('newSeason/endTop', this.node).getComponent(cc.Label).string = endMon + '/' + endDay + '/' + endData.getFullYear()
        // cc.find('newSeason/endButton', this.node).getComponent(cc.Label).string = Global.getTimeStr(_data.endTime, true)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_NEWSEASON_POP)
    },

    onClickOkClose() {
        if (this.countData == 0) {
            //刷新活动
            cc.vv.UserManager.reqBingoExproseInfo()
        }

        this.node.destroy()
    },

    onClickClose() {
        //在main内 则关闭且刷新
        if (this.node.parent.getChildByName('bingo_main')) {
            //main
            this.onClickEnjoy()
            return
        }
        this.node.destroy()
    },

    onClickEnjoy() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_NEWSEASON_ENJOY)

        // this.sendInfo()
        Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
        Global.dispatchEvent("BONUS_TAB", "Activity")

        this.node.destroy()
    },

    sendInfo() {
        let req = { c: MsgId.REQ_BINGO_INFO }
        cc.vv.NetManager.send(req)
    },

    setLeftLblText(tips) {
        let lbl_node = cc.find("timeLeft/lbl_info", this.node)
        lbl_node.getComponent(cc.Label).string = tips
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1) {
            this._inter = 0
            if (this.countData > 0) {
                this.countData--
                Global.setLabelString("timeLeft/clockTime", this.node, Global.formatSec(this.countData))
                // if (this.countData == 0) {
                //     cc.find('timeLeft', this.node).active = false
                //     this.firstDay(this.data)
                //     this.sendInfo() 
                //     return
                // }
            }
        }
    },
});
