cc.Class({
    extends: cc.Component,

    properties: {
        kuangPrefab: {
            // ATTRIBUTES:
            default: null,        // The default value will be used only when the component attaching
            // to a node for the first time
            type: cc.Prefab, // optional, default is typeof default
            serializable: true,   // optional, default is true
        },
        _kuangList: [],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {},

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    showKuang(idx) {
        if (idx === 1 || idx === 3 || idx === 5) {
            return
        }
        if (!this._kuangList[idx]) {
            let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
            let row = cc.vv.gameData.GetSlotsScript()._row - Math.floor((idx - 1) / cc.vv.gameData.GetSlotsScript()._col) - 1
            let reel = cc.vv.gameData.GetSlotsScript()._reels[col]
            if (reel) {
                let holder = cc.find("mask", reel.node)
                let pos = holder.convertToWorldSpaceAR(cc.v2(0, 0))
                let nodePos = this.node.convertToNodeSpaceAR(pos)
                let tempNode = cc.instantiate(this.kuangPrefab)
                this._kuangList[idx] = tempNode
                if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
                    cc.find("kuang1", tempNode).active = true
                } else {
                    cc.find("kuang2", tempNode).active = true
                }
                cc.find("frame_sao", tempNode).active = true
                this.initKuang(tempNode)
                tempNode.position = nodePos
                tempNode.parent = this.node
                let positionY = (row + 0.5) * cc.vv.gameData.GetSlotsScript()._cfg.symbolSize.height
                tempNode.y += positionY
                this.updateKuang()
            }
        }
    },

    showKuangExFirst(idx) {
        if (idx === 1 || idx === 3 || idx === 5) {
            return
        }
        if (!this._kuangList[idx]) {
            let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
            let row = cc.vv.gameData.GetSlotsScript()._row - Math.floor((idx - 1) / cc.vv.gameData.GetSlotsScript()._col) - 1
            let reel = cc.vv.gameData.GetSlotsScript()._reels[col]
            if (reel) {
                let holder = cc.find("mask", reel.node)
                let pos = holder.convertToWorldSpaceAR(cc.v2(0, 0))
                let nodePos = this.node.convertToNodeSpaceAR(pos)
                let positionY = (row + 0.5) * cc.vv.gameData.GetSlotsScript()._cfg.symbolSize.height
                nodePos.y += positionY
                let tempNode = cc.instantiate(this.kuangPrefab)
                this._kuangList[idx] = tempNode
                this.initKuang(tempNode)
                tempNode.position = nodePos
                tempNode.parent = this.node
                this.updateKuang()
                if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
                    cc.find("kuang1", tempNode).active = true
                } else {
                    cc.find("kuang2", tempNode).active = true
                }
                cc.find("frame_sao", tempNode).active = true
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.random_frame)
                let effect = cc.instantiate(cc.vv.gameData.GetPrefabByName("effect"))
                let topAni = cc.find("Canvas/safe_node/slots/top_ani")
                effect.parent = topAni
                effect.position = nodePos
                let frame2 = cc.find("frame_02", effect)
                frame2.active = true
                let frame2Sp = frame2.getComponent(sp.Skeleton)
                frame2Sp.setAnimation(0, "animation", false)
                frame2Sp.setCompleteListener(() => {
                    effect.parent = null
                    frame2Sp.setCompleteListener(null)
                })
            }
        }
    },

    showKuangEx(lastIdx, idx) {
        return new Promise((sucess, falied) => {
            if (idx === 1 || idx === 3 || idx === 5) {
                sucess()
                return
            }
            if (!this._kuangList[idx]) {
                let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
                let row = cc.vv.gameData.GetSlotsScript()._row - Math.floor((idx - 1) / cc.vv.gameData.GetSlotsScript()._col) - 1
                let reel = cc.vv.gameData.GetSlotsScript()._reels[col]
                let nodePos = this.node.convertToNodeSpaceAR(cc.find("mask", reel.node).convertToWorldSpaceAR(cc.v2(0, 0)))
                nodePos.y += (row + 0.5) * cc.vv.gameData.GetSlotsScript()._cfg.symbolSize.height
                let lastcol = (lastIdx - 1) % cc.vv.gameData.GetSlotsScript()._col
                let lastrow = cc.vv.gameData.GetSlotsScript()._row - Math.floor((lastIdx - 1) / cc.vv.gameData.GetSlotsScript()._col) - 1
                let lastreel = cc.vv.gameData.GetSlotsScript()._reels[lastcol]
                let lastnodePos = this.node.convertToNodeSpaceAR(cc.find("mask", lastreel.node).convertToWorldSpaceAR(cc.v2(0, 0)))
                lastnodePos.y += (lastrow + 0.5) * cc.vv.gameData.GetSlotsScript()._cfg.symbolSize.height
                let effect = cc.instantiate(cc.vv.gameData.GetPrefabByName("effect"))
                let topAni = cc.find("Canvas/safe_node/slots/top_ani")
                effect.parent = topAni
                effect.position = lastnodePos
                cc.tween(effect).to(0.5, { position: nodePos }).start()
                let frame1 = cc.find("frame_01", effect)
                frame1.active = true
                let frame1Sp = frame1.getComponent(sp.Skeleton)
                frame1Sp.setAnimation(0, "animation", false)
                frame1Sp.setCompleteListener(() => {
                    frame1.active = false
                    frame1Sp.setCompleteListener(null)
                    let tempNode = cc.instantiate(this.kuangPrefab)
                    this._kuangList[idx] = tempNode
                    this.initKuang(tempNode)
                    tempNode.position = nodePos
                    tempNode.parent = this.node
                    this.updateKuang()
                    if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
                        cc.find("kuang1", tempNode).active = true
                    } else {
                        cc.find("kuang2", tempNode).active = true
                    }
                    cc.find("frame_sao", tempNode).active = true
                    let frame2 = cc.find("frame_02", effect)
                    frame2.active = true
                    let frame2Sp = frame2.getComponent(sp.Skeleton)
                    frame2Sp.setAnimation(0, "animation", false)
                    frame2Sp.setCompleteListener(() => {
                        effect.parent = null
                        frame2Sp.setCompleteListener(null)
                    })
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.random_frame)
                    let slots = cc.find('Canvas/safe_node/slots')
                    cc.tween(slots).to(0.1, { scale: 1.1 }).delay(0.1).to(0.2, { scale: 1 }).start()
                    sucess()
                })
            } else {
                sucess()
            }
        })
    },

    showSuperBonusListKuang(idxList) {
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.super_frame)
        for (let i = 0; i < idxList.length; i++) {
            const idx = idxList[i];
            if (idx === 1 || idx === 3 || idx === 5) {
                continue
            }
            if (!this._kuangList[idx]) {
                let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
                let row = cc.vv.gameData.GetSlotsScript()._row - Math.floor((idx - 1) / cc.vv.gameData.GetSlotsScript()._col) - 1
                let reel = cc.vv.gameData.GetSlotsScript()._reels[col]
                let holder = cc.find("mask", reel.node)
                let pos = holder.convertToWorldSpaceAR(cc.v2(0, 0))
                let nodePos = this.node.convertToNodeSpaceAR(pos)
                let positionY = (row + 0.5) * cc.vv.gameData.GetSlotsScript()._cfg.symbolSize.height
                nodePos.y += positionY
                let tempNode = cc.instantiate(this.kuangPrefab)
                this._kuangList[idx] = tempNode
                this.initKuang(tempNode)
                tempNode.position = nodePos
                tempNode.parent = this.node
                cc.find("kuang2", tempNode).active = true
                cc.find("frame_sao", tempNode).active = true
                let effect = cc.instantiate(cc.vv.gameData.GetPrefabByName("effect"))
                let topAni = cc.find("Canvas/safe_node/slots/top_ani")
                effect.parent = topAni
                let tempPos = this.node.convertToWorldSpaceAR(nodePos)
                effect.position = topAni.convertToNodeSpaceAR(tempPos)
                let lankuang = cc.find("lankuang", effect)
                lankuang.active = true
                let lankuangSp = lankuang.getComponent(sp.Skeleton)
                lankuangSp.setAnimation(0, "animation", false)
                lankuangSp.setCompleteListener(() => {
                    effect.parent = null
                    lankuangSp.setCompleteListener(null)
                })
            }
        }
        this.updateKuang()
    },

    hideKuang(idxList) {
        for (let i = 0; i < idxList.length; i++) {
            const idx = idxList[i];
            if (this._kuangList[idx]) {
                this._kuangList[idx].parent = null
                delete this._kuangList[idx]
            }
        }
        this.updateKuang()
    },

    findKuang(idx) {
        return this._kuangList[idx]
    },

    clearKuang() {
        for (const key in this._kuangList) {
            if (Object.hasOwnProperty.call(this._kuangList, key)) {
                const kuang = this._kuangList[key];
                kuang.parent = null
            }
        }
        this._kuangList = []
    },

    setKuang(idxList) {
        this.clearKuang()
        for (let i = 0; i < idxList.length; i++) {
            const idx = idxList[i];
            if (idx === 1 || idx === 3 || idx === 5) {
                continue
            }
            if (!this._kuangList[idx]) {
                let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
                let row = cc.vv.gameData.GetSlotsScript()._row - Math.floor((idx - 1) / cc.vv.gameData.GetSlotsScript()._col) - 1
                let reel = cc.vv.gameData.GetSlotsScript()._reels[col]
                let holder = cc.find("mask", reel.node)
                let pos = holder.convertToWorldSpaceAR(cc.v2(0, 0))
                let nodePos = this.node.convertToNodeSpaceAR(pos)
                let tempNode = cc.instantiate(this.kuangPrefab)
                this._kuangList[idx] = tempNode
                if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
                    cc.find("kuang1", tempNode).active = true
                } else {
                    cc.find("kuang2", tempNode).active = true
                }
                cc.find("frame_sao", tempNode).active = true
                this.initKuang(tempNode)
                tempNode.position = nodePos
                tempNode.parent = this.node
                let positionY = (row + 0.5) * cc.vv.gameData.GetSlotsScript()._cfg.symbolSize.height
                tempNode.y += positionY
            }
        }
        this.updateKuang()
    },

    initKuang(item) {
        cc.find("kuang1/right", item).active = true
        cc.find("kuang2/right", item).active = true
        cc.find("kuang1/left", item).active = true
        cc.find("kuang2/left", item).active = true
    },

    changeKuang(idx, type) {
        if (this._kuangList[idx]) {
            if (type === 2) {
                cc.find("kuang1", this._kuangList[idx]).active = false
                cc.find("kuang2", this._kuangList[idx]).active = true
            } else {
                cc.find("kuang1", this._kuangList[idx]).active = true
                cc.find("kuang2", this._kuangList[idx]).active = false
            }
        }
    },

    updateKuang() {
        for (let i = 0; i < this._kuangList.length; i++) {
            const element = this._kuangList[i];
            if (element) {
                this.updateKuangType(element, i)
            }
        }
    },

    updateKuangType(item, idx) {
        let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
        if (idx === 6 || idx === 11 || idx === 16 || idx === 21) {
            cc.find("kuang1/left", item).active = false
            cc.find("kuang2/left", item).active = false
        }
        if (idx === 6 || idx === 2 || idx === 4 || idx === 8 || idx === 10) {
            // cc.find("kuang1/top",item).active = false
            // cc.find("kuang2/top",item).active = false
        }
        if (idx === 10 || idx === 15 || idx === 20 || idx === 25) {
            cc.find("kuang1/right", item).active = false
            cc.find("kuang2/right", item).active = false
        }
        if (idx === 21 || idx === 23 || idx === 25 || idx === 22 || idx === 24) {
            // cc.find("kuang1/down",item).active = false
            // cc.find("kuang2/down",item).active = false
        }
        let downIdx = idx + 5
        let upIdx = idx - 5
        let leftIdx1 = idx - 4
        let leftIdx2 = idx + 1
        let rightIdx1 = idx - 1
        let rightIdx2 = idx - 6
        if (col % 2 === 1) {  //奇数列
            leftIdx1 = idx + 6
            rightIdx2 = idx + 4
        }
        if (this._kuangList[downIdx]) {
            // cc.find("kuang1/down",item).active = false
            // cc.find("kuang2/down",item).active = false
        }
        if (col === 0) {
            if (this._kuangList[leftIdx1] || this._kuangList[leftIdx2]) {
                cc.find("kuang1/right", item).active = true
                cc.find("kuang2/right", item).active = true
            } else {
                cc.find("kuang1/right", item).active = false
                cc.find("kuang2/right", item).active = false
            }
        } else if (col === 4) {
            if (this._kuangList[rightIdx1] || this._kuangList[rightIdx2]) {
                cc.find("kuang1/left", item).active = true
                cc.find("kuang2/left", item).active = true
            } else {
                cc.find("kuang1/left", item).active = false
                cc.find("kuang2/left", item).active = false
            }
        } else {
            if (this._kuangList[leftIdx1] || this._kuangList[leftIdx2]) {
                cc.find("kuang1/right", item).active = true
                cc.find("kuang2/right", item).active = true
            } else {
                cc.find("kuang1/right", item).active = false
                cc.find("kuang2/right", item).active = false
            }
            if (this._kuangList[rightIdx1] || this._kuangList[rightIdx2]) {
                cc.find("kuang1/left", item).active = true
                cc.find("kuang2/left", item).active = true
            } else {
                cc.find("kuang1/left", item).active = false
                cc.find("kuang2/left", item).active = false
            }
        }
    },

    getNeighbor(idx) {
        let col = (idx - 1) % cc.vv.gameData.GetSlotsScript()._col
        let downIdx = idx + 5
        let upIdx = idx - 5
        let leftIdx1 = idx - 4
        let leftIdx2 = idx + 1
        let rightIdx1 = idx - 1
        let rightIdx2 = idx - 6
        if (col % 2 === 1) {  //奇数列
            leftIdx1 = idx + 6
            rightIdx2 = idx + 4
        }
        if (col === 0) {  //这里命名写反了
            rightIdx1 = 0
            rightIdx2 = 0
        } else if (col === 4) {
            leftIdx1 = 0
            leftIdx2 = 0
        }
        return [downIdx, upIdx, leftIdx1, leftIdx2, rightIdx1, rightIdx2]
    },

    //wild裂变
    FissionWild(startIdxList) {
        return new Promise((sucess, falied) => {
            this.startFission(startIdxList, sucess)
        })
    },

    async startFission(startIdxList, sucess, isNotFirst) {
        let canFissionList = []
        let topEffectNode = cc.find("Canvas/safe_node/topEffectNode")
        for (let i = 0; i < startIdxList.length; i++) {
            const idx = startIdxList[i];
            if (this._kuangList[idx]) {
                let neighbor = this.getNeighbor(idx)
                let canFissionNeighbor = []
                for (let j = 0; j < neighbor.length; j++) {
                    const neighborIdx = neighbor[j];
                    if (this._kuangList[neighborIdx]) {   //需要有框
                        let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(neighborIdx)
                        if (symbol._id !== 1 && symbol._id !== 101) {  //节点不是wild
                            canFissionList.push(neighborIdx)
                            canFissionNeighbor.push(neighborIdx)
                        }
                    }
                }
                let tempstartPos = this._kuangList[idx].convertToWorldSpaceAR(cc.v2(0, 0))
                let startPos = topEffectNode.convertToNodeSpaceAR(tempstartPos)
                for (let i = 0; i < canFissionNeighbor.length; i++) {
                    const neighborIdx = canFissionNeighbor[i];
                    let wildLizi = cc.instantiate(cc.vv.gameData.GetPrefabByName("wildlizi"))
                    wildLizi.parent = topEffectNode
                    wildLizi.position = startPos
                    let tempendPos = this._kuangList[neighborIdx].convertToWorldSpaceAR(cc.v2(0, 0))
                    let endPos = topEffectNode.convertToNodeSpaceAR(tempendPos)
                    cc.tween(wildLizi).to(0.4, { position: endPos }).call(() => {
                        wildLizi.parent = null
                        let kuosan = cc.instantiate(cc.vv.gameData.GetPrefabByName("wild_kuosan"))
                        kuosan.parent = topEffectNode
                        kuosan.position = endPos
                        let kuosanSP = kuosan.getComponent(sp.Skeleton)
                        kuosanSP.setAnimation(0, "animation", false)
                        kuosanSP.setCompleteListener(() => {
                            kuosan.parent = null
                            kuosanSP.setCompleteListener(null)
                        })
                    }).start()
                }
            }
        }
        if (canFissionList.length > 0) {
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wild_explode)
            await this.awaitTime(0.4)
            for (let i = 0; i < canFissionList.length; i++) {
                const idx = canFissionList[i];
                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                if (symbol) {
                    symbol.changeWildEx()
                }
            }
            this.startFission(canFissionList, sucess, true)
        } else {
            if (isNotFirst) {
                await this.awaitTime(1)
            }
            if (sucess) {
                sucess()
            }
        }
    },

    FissionWildFast(startIdxList) {
        let canFissionList = []
        for (let i = 0; i < startIdxList.length; i++) {
            const idx = startIdxList[i];
            if (this._kuangList[idx]) {
                let neighbor = this.getNeighbor(idx)
                let canFissionNeighbor = []
                for (let j = 0; j < neighbor.length; j++) {
                    const neighborIdx = neighbor[j];
                    if (this._kuangList[neighborIdx]) {   //需要有框
                        let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(neighborIdx)
                        if (symbol._id !== 1 && symbol._id !== 101) {  //节点不是wild
                            canFissionList.push(neighborIdx)
                            canFissionNeighbor.push(neighborIdx)
                        }
                    }
                }
            }
        }
        if (canFissionList.length > 0) {
            for (let i = 0; i < canFissionList.length; i++) {
                const idx = canFissionList[i];
                let symbol = cc.vv.gameData.GetSlotsScript().GetSymbolByIdx(idx)
                if (symbol) {
                    symbol.changeWildExFast()
                }
            }
            this.FissionWildFast(canFissionList)
        }
    },

    playJiLiDonghua(colIdx) {
        let playSuccess = false
        for (let i = 0; i < this._kuangList.length; i++) {
            const kuang = this._kuangList[i];
            let col = (i - 1) % cc.vv.gameData.GetSlotsScript()._col
            if (col == colIdx) {
                if (kuang) {
                    cc.find("jili", kuang).active = true
                    playSuccess = true
                }
            }
        }
        return playSuccess
    },

    stopJiLiDonghua(colIdx) {
        for (let i = 0; i < this._kuangList.length; i++) {
            const kuang = this._kuangList[i];
            let col = (i - 1) % cc.vv.gameData.GetSlotsScript()._col
            if (col == colIdx) {
                if (kuang) {
                    cc.find("jili", kuang).active = false
                }
            }
        }
    },

    // update (dt) {},
});
