/**
 * 卡牌
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _cardInfo: null,
    },

    init(cardInfo) {
        Global.registerEvent("HEROCARD_UPDATED", this.onCardUpate, this)
        this.showCard(cardInfo)

    },

    showCard: function (cardInfo) {
        this._cardInfo = cardInfo;
        let chip_node = cc.find('spr_chipicon', this.node)
        let lblName = this.node.getChildByName("lbl_name")
        let nodeLock = this.node.getChildByName("locker")
        let sprLock = cc.find('icon_locker', nodeLock)
        let spr_namebg = cc.find('hero_name_bg', this.node)
        let btnunlock = cc.find('btn_unlock', this.node)
        let sprStany = cc.find('spr_stany', this.node)
        let cardicon = this.node.getChildByName("icon")
        let cardbg = this.node.getChildByName("icon_bg")
        if (!this._cardInfo) {
            sprStany.active = true
            chip_node.active = false
            lblName.active = false
            nodeLock.active = true
            sprLock.active = false
            spr_namebg.active = false
            btnunlock.active = false
            cardicon.active = false
            cardbg.active = false
            return
        }
        this._bUnlock = (cardInfo.lv > 0)

        sprStany.active = false
        spr_namebg.active = true
        lblName.active = true
        // lblName.getComponent(cc.Label).string = cardInfo.cfg.name;
        I18N.setI18nLabel(lblName, cc.vv.Language["cardname_" + cardInfo.cardid])

        nodeLock.active = !this._bUnlock;//大于0表示已解锁
        sprLock.active = !this._bUnlock;

        chip_node.active = !this._bUnlock;
        let chips = chip_node.getChildByName("chips");
        chips.getComponent(cc.Label).string = cardInfo.chips + "/" + cardInfo.cfg.unlock_chips;

        let bCanUnlock = !this._bUnlock && cardInfo.chips >= cardInfo.cfg.unlock_chips
        btnunlock.active = bCanUnlock
        btnunlock.on("click", this.onClickUnclock, this)
        this.loadCardTips(bCanUnlock)

        this.node.on("click", this.onClick, this);

        cardbg.active = true
        cc.vv.HerocardManager.loadCampChipBg(cardbg, cardInfo.cfg.campid)
        cardicon.active = true
        cc.vv.HerocardManager.loadChipHero(cardicon, cardInfo.cfg.cardid)
    },

    onClick() {
        Global.playComEff("ch_btn_click");
        if (!this._cardInfo) {
            return
        }
        if (this._bUnlock) {
            cc.loader.loadRes("CashHero/prefab/herocard/card_detail", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let parObj = cc.find("Canvas");
                    let old = cc.find('card_detail', parObj)
                    if (!old) {
                        let node = cc.instantiate(prefab);
                        node.parent = parObj
                        node.getComponent("CH_Herocard_Detail").init(this._cardInfo, true, this._cardInfo.cfg.campid);
                    }
                    //统计
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROCARD_CLICKUNLOCKCARD, this._cardInfo.cardid)
                }
            })
        }
        else {
            //未解锁
            cc.loader.loadRes("CashHero/prefab/herocard/card_unlock_tip", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let parObj = cc.find("Canvas");
                    let old = cc.find('card_unlock_tip', parObj)
                    if (!old) {
                        let node = cc.instantiate(prefab);
                        node.getComponent("CH_Herocard_unlocktip").init(this._cardInfo);
                        node.parent = parObj
                    }

                    //统计
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_HEROCARD_CLICKLOCKCARD, this._cardInfo.cardid)
                }
            })


        }

    },

    //可以解锁
    onClickUnclock() {
        Global.playComEff("ch_btn_click");
        if (this._bSend) return
        this._bSend = true
        cc.vv.HerocardManager.reqCardUnlock(this._cardInfo.cfg.cardid)
    },

    //卡牌更新
    onCardUpate(data) {
        let val = data.detail
        if (val && this._cardInfo && val.cardid == this._cardInfo.cardid) {
            this.showCard(val)
        }
    },

    getCardInfo: function () {
        return this._cardInfo
    },

    loadCardTips: function (bShow) {
        if (bShow) {
            cc.loader.loadRes("CashHero/prefab/herocard/card_tips", cc.Prefab, (err, prefab) => {
                let old = cc.find('card_tips', this.node)
                if (!old) {
                    let node = cc.instantiate(prefab);
                    node.parent = this.node;
                }

            })
        }
        else {
            let old = cc.find('card_tips', this.node)
            if (old) {
                old.destroy()
            }
        }

    },

    clear: function () {
        this._cardInfo = null

    },


});
