        cc.find('fiveIcon', uiNode).getComponent(cc.Sprite).spriteFrame = this.atlas.getSpriteFrame('campIcon_' + cardInfo.cfg.campid)

        //是否锁住状态
        cc.find('lock', uiNode).active = this._iconType == ICONTYPE.LOCK

        //等级
        let _lvNode = cc.find('lv', uiNode)
        _lvNode.active = this._iconType != ICONTYPE.LOCK
        if (_lvNode.active) {
            _lvNode.getComponent(cc.Label).string = 'Lv.' + this._cardInfo.lv
        }

