        let sprReddot = cc.find('ui/reddot', this.node)
        sprReddot.active = false
        // let spinTip = cc.find('ui/spine',this.node)
        // spinTip.active = false

        //是否可以解锁
        let bCanUnlock = cc.vv.HerocardManager.isCardCanUnlock(this._cardInfo)
        //是否可以升级
        let bCanUpper = cc.vv.HerocardManager.isCardCanAddStar(this._cardInfo)
        //是否有成就可以领取
        let bAcviment = cc.vv.HerocardManager.isCardHasAcviment(this._cardInfo)

        let bAreadyUnlock = (cc.vv.HerocardManager.getChipLv(this._cardInfo) > 0)

        sprReddot.active = bCanUnlock || bCanUpper || (bAcviment && bAreadyUnlock)

