    onClickBtnDetail: function () {
        //点击detail按钮
        Global.playComEff("ch_btn_click");

        let self = this;
        cc.loader.loadRes("CashHero/prefab/herocard/card_detail", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let old = cc.find('card_detail', parObj)
                if (!old) {
                    let node = cc.instantiate(prefab);
                    node.parent = parObj
                    let cardInfo = self._cardInfo
                    let campId = 0
                    node.getComponent("CH_Herocard_Detail").init(cardInfo, true, campId);
                }

            }
        })

        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL, this._cardInfo.cardid)
    },

