/**
 * 下注界面的item
 */
let BET_CFG = [
    0,
    100000,
    150000,
    300000,
    500000,
    600000,
    800000,
    1000000,
    1200000,
    1500000,
    2000000,
    5000000,
    10000000,
    20000000,
    50000000,
    100000000,
]
cc.Class({
    extends: cc.Component,

    properties: {
        my_bg: cc.SpriteFrame,
        other_bg: cc.SpriteFrame,
        _defaultIdx: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_add = cc.find('spr_coin_bg/btn_add', this.node)
        Global.btnClickEvent(btn_add, this.onClickAdd, this)
        let btn_minus = cc.find('spr_coin_bg/btn_minus', this.node)
        Global.btnClickEvent(btn_minus, this.onClickMinus, this)

        Global.registerEvent(EventId.CHAT_RANK_BET_CONFIRM, this.onEventBetConfirm, this)
    },

    start() {

    },
    init: function (betdata, odds, rankinfo, bCan, bOpenPalace, mainScp) {
        this._bOpenPalace = bOpenPalace
        this._rankinfo = rankinfo
        this._mainScp = mainScp
        this._defaultIdx = 0

        //rank
        let lbl_rank = cc.find('lbl_rank', this.node)
        lbl_rank.getComponent(cc.Label).string = rankinfo.rank
        //odds
        let lbl_odds = cc.find('lbl_odd', this.node)
        lbl_odds.getComponent(cc.Label).string = cc.js.formatStr('1:%s', odds)

        let lblName = cc.find('node_player/lbl_name', this.node)
        let strName
        //是否是others
        let bOther = rankinfo.uid == 2
        if (bOther) {
            cc.find("node_player/node_head", this.node).active = false
            strName = 'Other Players'
            lblName.getComponent(cc.Label).enableBold = true
            lblName.color = cc.Color.YELLOW
        }
        else {
            //设置头像
            var userHeadScript = cc.find("node_player/node_head", this.node).getComponent('UserHead');
            userHeadScript.setHead(rankinfo.uid, rankinfo.usericon);
            //设置名字
            strName = rankinfo.playername

        }

        lblName.getComponent(cc.Label).string = strName

        //是否可以下注
        this._setBetBtn(bCan)
        let coinVal = 0
        if (!bCan) {
            if (betdata) {
                coinVal = betdata.coin
            }
        }
        let lbl_coin = cc.find('spr_coin_bg/lbl_coin', this.node)
        lbl_coin.getComponent(cc.Label).string = Global.formatNumShort(coinVal, 1)
        this._curVal = coinVal
        //bg
        let spriteVal = this.other_bg
        if (rankinfo.uid == Global.playerData.uid) {
            spriteVal = this.my_bg
        }
        let bgNode = cc.find('bg', this.node)
        bgNode.getComponent(cc.Sprite).spriteFrame = spriteVal

        this._checkBtnEnable()
    },

    _setBetBtn: function (bCan) {
        let btn_add = cc.find('spr_coin_bg/btn_add', this.node)
        btn_add.active = bCan
        let btn_minus = cc.find('spr_coin_bg/btn_minus', this.node)
        btn_minus.active = bCan
    },

    _showBetVal: function () {
        let val = BET_CFG[this._defaultIdx] * cc.vv.HerocardManager.getCoinLS()
        let bet = cc.find('spr_coin_bg/lbl_coin', this.node)
        bet.getComponent(cc.Label).string = Global.formatNumShort(val, 1)

        this._curVal = val

        let betData = {
            uid: this._rankinfo.uid,
            idx: this._defaultIdx,
            betval: val,
        }
        Global.dispatchEvent(EventId.CHAT_RANK_BET, betData)
        this._checkBtnEnable()
    },

    onClickAdd: function () {
        let self = this
        //金币是否足够
        let bCanAdd = false
        let nRmind = this._mainScp._getTempRemindCoin()
        if (nRmind > BET_CFG[this._defaultIdx + 1]) {
            bCanAdd = true
        }
        if (bCanAdd) {
            this._defaultIdx += 1
            this._showBetVal()
        }
        else {
            //提示金币不足

            let sureCall = function () {
                cc.vv.UserManager.setEnterHallAction('Shop_Coin')
                Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
                self._mainScp.onClickClose()
            }
            let cancelCall = function () {

            }
            let msg = "Your coins are insufficient, do you go to recharge？"
            cc.vv.AlertView.showSimple(msg, sureCall, cancelCall)
        }

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_RANKQUIZ_ADD, 'ADD:' + this._rankinfo.rank + '|' + this._curVal)
    },
    onClickMinus: function () {
        if (this._defaultIdx == -1) {
            this._defaultIdx = 1
        }
        this._defaultIdx -= 1
        this._showBetVal()

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_RANKQUIZ_REDUCE, 'REDUCE:' + this._rankinfo.rank + '|' + this._curVal)
    },

    _checkBtnEnable: function () {
        let idxMax = 11
        if (this._bOpenPalace) {
            idxMax = 16
        }
        let btn_add = cc.find('spr_coin_bg/btn_add', this.node)
        btn_add.getComponent(cc.Button).interactable = (this._defaultIdx < idxMax - 1)

        let btn_minus = cc.find('spr_coin_bg/btn_minus', this.node)
        btn_minus.getComponent(cc.Button).interactable = (this._defaultIdx > 0)
    },

    onEventBetConfirm: function () {
        this._setBetBtn(false)
    }
    // update (dt) {},
});
