/**
 * 玩家经验升级了
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _levelUpNode: null,
        _btn_cliam: null,
        _lbl_lvCoin: null,
    },

    onLoad() {
        this._levelUpNode = this.node.getChildByName('levelup')
        this._btn_cliam = this._levelUpNode.getChildByName('btn_claim')
        this._lbl_lvCoin = this._levelUpNode.getChildByName('lbl_coin')
        Global.btnClickEvent(this._btn_cliam, this.clickClose, this)
    },

    onDestroy() {
        cc.vv.gameData.ResumeSlot()
        Global.dispatchEvent(EventId.CLOSE_BIG_LV_UP)
    },

    start() {
        cc.vv.gameData.PauseSlot()
        Global.playEff(Global.SOUNDS.sound_level_up)
        Global.playComEff("ch_popup_reward");
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LVUPEXP_POP)
    },

    //设置数据
    setUIData: function (totalCoin, lv, lvCoin, bonusCoin, vipExp, endCall) {
        this._endCall = endCall
        this._totalCoin = totalCoin
        this._addCoin = lvCoin + bonusCoin
        if (cc.vv.gameData && cc.vv.gameData.AddCoin) {
            cc.vv.gameData.AddCoin(this._addCoin)
        }
        let lbl_lv = this._levelUpNode.getChildByName('lbl_lv')
        lbl_lv.getComponent(cc.Label).string = lv
        this._lbl_lvCoin.getComponent(cc.Label).string = Global.FormatNumToComma(lvCoin)
        let lbl_vipexp = cc.find("bg/lbl_vipPoints", this._levelUpNode)
        lbl_vipexp.getComponent(cc.Label).string = '+' + vipExp
        console.log('>>>> 1vipExp', vipExp);
        this.starAniShow()
    },

    //开始动画播放
    starAniShow: function () {
        let spineCom = this._levelUpNode.getComponent(sp.Skeleton);
        spineCom.setAnimation(0, "animation_1", false);
        cc.tween(this._levelUpNode)
            .delay(0.8)
            .call(() => {
                this.setFirstNodeVisible(true)
            })
            .delay(0.2)
            .call(() => {
                this.setSecondNodeVisible(true)
            })
            .delay(0.5)
            .call(() => {
                cc.find("btn_claim", this._levelUpNode).active = true
                spineCom.setAnimation(0, "animation_2", true);
            })
            .delay(1)
            .call(() => {
                this.clickClose()
            })
            .start()
    },

    setFirstNodeVisible(visible) {
        let arr = [
            cc.find("lbl_coin", this._levelUpNode),
            cc.find("lbl_lv", this._levelUpNode),
        ]
        if (visible) {
            for (const iterator of arr) {
                iterator.opacity = 0
                iterator.active = visible
                iterator.runAction(cc.fadeIn(0.2))
            }
        } else {
            for (const iterator of arr) {
                iterator.active = visible
            }
        }
    },

    setSecondNodeVisible(visible) {
        let arr = [
            cc.find("bg", this._levelUpNode)
        ]
        if (visible) {
            for (const iterator of arr) {
                iterator.opacity = 0
                iterator.active = visible
                iterator.runAction(cc.fadeIn(0.2))
            }
        } else {
            for (const iterator of arr) {
                iterator.active = visible
            }
            cc.find("btn_claim", this._levelUpNode).active = visible
        }
    },

    //关闭界面
    closeUIAni: function () {
        cc.vv.AudioManager.stopEffectByName('levelup_collect')
        if (cc.isValid(this._levelUpNode)) {
            this._levelUpNode.stopAllActions();
            if (this._endCall) {
                this._endCall()
            }
            this.node.destroy()
        }
    },

    clickClose: function () {
        let self = this
        //是否已经播放了
        if (!this._btn_cliam.getComponent(cc.Button).interactable) {
            return
        }
        this._btn_cliam.getComponent(cc.Button).interactable = false
        //执行飞金币
        let endCall = function () {
            if (cc.vv.gameData && cc.vv.gameData._EventId) {
                Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_UPDATE_BALANCE);
            }
            self.closeUIAni()
        }
        this.flyCoin(endCall)
        Global.playComEff("ch_close");
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LVUPEXP_POP)
    },

    flyCoin: function (endCall) {
        //飞金币
        //执行飞金币
        let rollData = {}
        rollData.lblCoin = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH);
        rollData.addCoin = this._addCoin
        //飞金币
        let srcObj = this._lbl_lvCoin
        let endNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH);
        let flyCoinEnd = function () {
            endCall()
        }
        let completeCall = function () {
            if (flyCoinEnd) flyCoinEnd()
            //刷新金币
            if (cc.vv.gameData) {
                cc.vv.gameData.AddCoin(rollData.addCoin, true)
            }
        }
        Global.FlyCoin(srcObj, endNode, completeCall, rollData, true)
        // let node_fly = this._levelUpNode.getChildByName('flycoins')
        // if (node_fly) {
        //     let script = node_fly.getComponent('FlyCoins')
        //     if (script) {
        //         let rollData = {}
        //         let rollLbl = cc.find("Canvas/LMSlots_Top/playerCoins/lbl_coinsNum");
        //         if (rollLbl) {
        //             rollData.lblCoin = rollLbl
        //             rollData.addCoin = this._addCoin
        //         }
        //         else {
        //             rollData = null
        //         }
        //         let srcObj = cc.find('lbl_coin', this._levelUpNode)
        //         let fromPos = this.node.convertToNodeSpaceAR(srcObj.convertToWorldSpaceAR(cc.v2(0, 0)))
        //         let endNode = cc.find("Canvas/LMSlots_Top/playerCoins/icon_coin");
        //         if (endNode) {
        //             let endPos = this.node.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0, 0)));
        //             script.showFlyCoins(fromPos, endPos, 12, endCall, rollData)
        //         }
        //         else {
        //             //不执行飞金币
        //             endCall()
        //         }
        //     }
        // }
    }
});
