cc.Class({
    extends: cc.Component,

    properties: {
        character: sp.Skeleton,
        extraBall: sp.Skeleton,
        effect: sp.Skeleton,
        _isOpenExtraBall: false,
    },

    onLoad() {
        this.extraBall.node.on(cc.Node.EventType.TOUCH_END, () => {
            if (this._isOpenExtraBall) {
                return;
            }
            // 如果spin不可点击 返回
            if (!SlotsFacade.bottomCmp.GetSpinBtnState()) {
                return;
            }
            let betList = SlotsFacade.dm.GetBetMults();
            let needBet = SlotsFacade.dm.getDeskInfo().needBet + 1;
            // 金币不足
            if (needBet > betList.length) {
                return;
            }
            SlotsFacade.dm.SetBetIdx(needBet);
            SlotsFacade.bottomCmp.ShowBetCoin();
            let nTotal = cc.vv.gameData.GetTotalBet()
            Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, nTotal)
        }, this);
    },

    start() {
        this.showExtraBall(true);
    },

    /**
     * 转到普通状态
     */
    toNormalState() {
        // this.node.y = 183;
        this.extraBall.node.active = true;
    },

    /**
     * 转到免费状态
     */
    toFreeState() {
        // this.node.y = 150;
        if (SlotsFacade.dm.energyData.state == 2) {
            this.extraBall.node.active = false;
        } else {
            this.extraBall.node.active = true;
        }
    },

    /**
     * 显示扩展能量球
     * @param init
     */
    showExtraBall(isInit) {
        let boo = SlotsFacade.dm.canExtraBall();
        if (boo) {
            if (isInit) {
                this.extraBall.setAnimation(0, "animation", true);
            } else {
                if (!this._isOpenExtraBall) {
                    SlotsFacade.soundMgr.playEffect("balls_unlock");
                    this.extraBall.setAnimation(0, "animation4", false);
                    this.extraBall.addAnimation(0, "animation", true);
                }
            }
        } else {
            if (isInit) {
                this.extraBall.setAnimation(0, "animation3", true);
            } else {
                if (this._isOpenExtraBall) {
                    SlotsFacade.soundMgr.playEffect("balls_lock");
                    this.extraBall.setAnimation(0, "animation2", false);
                    this.extraBall.addAnimation(0, "animation3", true);
                }
            }
        }
        this._isOpenExtraBall = boo;
    },

    /**
     * 播放添加能量球动画
     * @returns {Promise<void>}
     */
    async playExtraBonusEff() {
        this.effect.node.active = true;
        this.effect.setAnimation(0, "animation2", false);
        SlotsFacade.soundMgr.playEffect("frog");
        SlotsFacade.soundMgr.playEffect("random_bonus");
        await new Promise(res => {
            this.effect.setCompleteListener(() => {
                this.effect.setCompleteListener(null);
                res();
            })
        })
        this.character.setAnimation(0, "animation1", false);
        this.character.addAnimation(0, "animation", true);
        this.effect.setAnimation(0, "animation", false);
        await new Promise(res => {
            this.effect.setCompleteListener(() => {
                this.effect.setCompleteListener(null);
                this.effect.node.active = false;
                res();
            })
        })
    }
});
