/**
 * 缩小版的聊天入口
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _lastid: 0,
        _playIdx: 0,
        _listData: [],
        _nInter: 0
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_WORLD_CHAT, this.onRcvChat, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_WORLD_CHAT, this.onRcvChat, false, this);
    },

    start() {

    },

    onRcvChat(msg) {
        if (msg.code == 200) {
            if (this._listData == null) {
                this._listData = []
            }
            let maxid = 0

            let cnt = msg.data.items.length
            let addCount = 0
            for (let i = 0; i < cnt; i++) {
                let data = msg.data.items[i]
                if (data.id > this._lastid) {
                    addCount++
                    this._listData.push(data)
                    maxid = Math.max(maxid, data.id)
                }
            }

            this._lastid = Math.max(this._lastid, maxid)
            if (addCount == 0) {
                //没有新消息
                this.playNextMsg()

            }
            else {
                //有新消息
                this._playIdx = this._listData.length - 1
                this.showPlayMsg(this._playIdx)
            }


        }
    },

    //显示当前播放的消息
    showPlayMsg: function (idx) {
        let data = this._listData[idx]
        if (data) {
            let item_node = cc.find("item_msg", this.node)
            //头像
            // let node_head = cc.find("node_head",item_node)
            // node_head.active = false
            // let headpic = data.avatar || data.usericon
            // if(headpic){
            //     node_head.getComponent('UserHead').setHead(data.uid, headpic)
            //     node_head.active = true
            // }
            // else{
            //     node_head.active = false
            // }

            //内容
            let msgType = data.stype
            let showStr = data.content
            switch (msgType) {
                case 1:

                    break;
                case 2:
                    // showStr = "Add Me"
                    break;
                case 3:
                    showStr = "Share card gift with everyone!"
                    break;
                case 4:
                    showStr = "Ranklist is comming,guess who's big winner!"
                    break;
                case 5:
                    showStr = "[NOTICE] from CashHero"
                    break;
                case 6:
                    showStr = "Chips Ranklist is comming,check it out!"
                default:
                    break;
            }
            Global.setLabelString("lbl_chat", item_node, showStr)
        }
    },

    playNextMsg() {
        this._playIdx -= 1
        if (this._playIdx < 0) {
            this._playIdx = this._listData.length - 1
        }
        this.showPlayMsg(this._playIdx)
    },

    update(dt) {
        this._nInter += dt
        if (this._nInter > 1.5) {
            this._nInter = 0
            this.playNextMsg()
        }
    },
});
