cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    coinBackInit(data, status) {
        I18N.setI18nLabel(cc.find('des/lbl', this.node), cc.vv.Language.herocard_task_des2, data.percent)
        // cc.find('des/percent', this.node).getComponent(cc.Label).string = data.percent+'%'
        if (status > 1) {
            cc.find('coinBg', this.node).active = false
        } else {
            // let numNode = cc.find('coinBg/num', this.node)
            cc.find('coinBg/num', this.node).getComponent(cc.Label).string = Global.FormatNumToComma(data.count)
            // cc.find('sprCoin', numNode).x = -numNode.width/2 - 150
        }
    },


    // update (dt) {},
});
