/**
 * 转盘
 */

//轮盘特效
let SkeletonCfg = {
    // freePointer:'animation2_1', //免费转盘停止后指针效果
    payPointer: 'animation1_1',    //付费转盘停止后指针效果  
    paySpin: 'animation3',         //点击spin按钮效果        
    payMarquee: 'animation1_3',      //转盘外围跑马灯效果    
    // payX20:'animation1_2',      //X20
};

cc.Class({
    extends: cc.Component,

    properties: {

        buyPointSpine: {    //payPointerSpine
            default: null,
            type: sp.Skeleton,
        },

        buyWheelSpine: {    //payWheelSpine
            default: null,
            type: sp.Skeleton,
        },

        prefab_coin: {     //flycoins
            default: null,
            type: cc.Prefab,
        },

        newPayblack: { //newPayBlack
            default: null,
            type: cc.Node
        },

        newWheelNumFontNor: {  //new_wheelBlue
            default: null,
            type: cc.BitmapFont
        },

        newWheelNumFontVip: {  //new_wheelGold
            default: null,
            type: cc.BitmapFont
        },

        _buyItemList: [],      //非免费转盘item列表
        _buyPrizeData: [],     //非免费转盘配置
        _buyResultIdx: null,   //非免费转盘结果
        _isBuySpinBtn: false,    //购买非免费转盘机会
        _hasClickSure: false,

        _purchaseData: null,  //充值数据
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SPINE_CONF, this.onRcvGetWheelSpineConf, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SPINE_RESULT, this.onRcvGetSpineResult, this);
        //注册sdk支付回调
        cc.vv.NetManager.registerMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, this);
        Global.registerEvent(EventId.PAY_RESULT, this.OnEventPayResult, this)
        this._node_sure = cc.find('node_sure', this.node)
        this._node_sure.active = false;
        Global.btnClickEvent(cc.find('node_lunpan/btn_spin', this.node), this.onClickSpin, this)
        Global.btnClickEvent(cc.find('btn_close', this.node), this.onShowSureNode, this)
        Global.btnClickEvent(cc.find('node_sure/btn_close', this.node), this.onClickCloseSure, this)
        Global.btnClickEvent(cc.find('node_sure/bg/lbl_spin', this.node), this.onClickSpin, this)
        Global.btnClickEvent(cc.find('skipBtn', this.node), this.onClickSkip, this)
        this.skipBtnEnable(false)
    },

    start() {
        Global.FixDesignScale_V(this.node)
        this.setSpinEnabled(false)
        //发付费协议更新数据
        this.sendGetSpineConfReq(2);
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_WHEEL_POP)
        //付费转盘加载完后把免费转盘销毁
        if (this._callback) {
            this._callback()
        }
    },

    setCallBack(callback) {
        if (callback) {
            this._callback = callback
        }
    },

    setSpinEnabled: function (bEnable) {
        console.log(">>>> setSpinEnabled: ", bEnable)
        let btn = cc.find('node_lunpan/btn_spin', this.node)
        btn.getComponent(cc.Button).interactable = bEnable
    },

    //发送获取转盘配置协议
    //@param rtype  1-免费转盘 2-收费转盘
    sendGetSpineConfReq: function (rtype) {
        var req = { 'c': MsgId.REQ_GET_SPINE_CONF };
        req.uid = Global.playerData.uid;
        req.rtype = rtype;
        cc.vv.NetManager.send(req);
    },

    //发送领取转盘奖励协议
    //@param rtype  1.收集金币 2免费转盘 3收费转盘
    sendGetSpineResultReq: function (rtype) {
        var req = { 'c': MsgId.REQ_GET_SPINE_RESULT };
        req.uid = Global.playerData.uid;
        req.rtype = rtype;
        cc.vv.NetManager.send(req);
    },

    //刷新转盘状态
    // sendTurntableStateReq:function () {
    //     var req = {'c': MsgId.REQ_GET_TURNTABLE_STATE};
    //     req.uid = Global.playerData.uid;
    //     cc.vv.NetManager.send(req);
    // },

    _loadeX20Spine() {
        let url = 'CashHero/prefab/prize_wheel/prize_wheel_pop'
        let self = this
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')

                let callback = () => {
                    self.setSpinEnabled(true)
                }
                node.getComponent('prize_wheel_pop').initPop(callback)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    //初始化非免费转盘
    initBuyWheel: function () {
        //加载动画 动画关闭后允许点击
        this._loadeX20Spine()

        let prize_item = cc.find('node_lunpan/wheel/di1/item', this.node);
        this._buyItemList.push(prize_item);
        for (let i = 1; i < this._buyPrizeData.length; i++) {
            let item = cc.instantiate(prize_item);
            item.angle = i * 360 / this._buyPrizeData.length + prize_item.angle;
            item.parent = prize_item.parent;
            this._buyItemList.push(item);
        }
        for (let i = 0; i < this._buyItemList.length; i++) {
            let lbl_coin = this._buyItemList[i].getChildByName('lbl');
            lbl_coin.getComponent(cc.Label).string = Global.convertNumToShort(this._buyPrizeData[i], 1000, 2);
            //hy    数字字体切换
            lbl_coin.getComponent(cc.Label).font = (i % 2 == 1) ? this.newWheelNumFontNor : this.newWheelNumFontVip
        }
        //hy    免费遮罩隐藏
        this.newPayblack.active = false

        let _btn_spin = cc.find('node_lunpan/btn_spin', this.node);
        _btn_spin.getComponent(cc.Button).interactable = true;

        let lbl_money = _btn_spin.getChildByName('lbl_money');
        lbl_money.getComponent(cc.Label).string = cc.js.formatStr('$%s', this._price);

        this.lbl_fortune = cc.find('node_fortune/lbl', this.node);
        this.lbl_fortune.getComponent(cc.Label).string = Global.FormatNumToComma(this._fortuneCoin);

        let lbl_coin_sure = cc.find('bg/lbl_coin', this._node_sure);
        lbl_coin_sure.getComponent(cc.Label).string = Global.FormatNumToComma(this._showCoin);
        let lbl_money_sure = cc.find('bg/lbl_money', this._node_sure);
        lbl_money_sure.getComponent(cc.Label).string = cc.js.formatStr('FOR ONLY $%s', this._price);

        //benifist
        let btn = cc.find("node_sure/btn_benifist", this.node)
        btn.getComponent('CH_Benifist_Btn').showBenifist(this._buyRewards, '转盘权益')
    },

    skipBtnEnable(flag) {
        let skipBtn = cc.find('skipBtn', this.node)
        skipBtn.active = flag
    },
    //点击开始转动按钮
    onClickSpin: function (event) {
        Global.playEff(Global.SOUNDS.sound_wheel_spin);

        if (this._node_sure.active) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_BUYWHEEL_SURESPIN)
        }

        this.setBuyBtnEnable(false)
        this._node_sure.active = false;

        this.sendGetSpineResultReq(3);

        //遮布隐藏
        this.newPayblack.active = false
        cc.find('X20Spine', this.node).active = false

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_BUYWHEEL_BUY)
    },

    onRcvMsgCheckOrder: function (msg) {
        if (msg.code === 200) {
            this.sendGetSpineResultReq(3);

            // 购买成功,隐藏close按钮
            this.showCloseBtnState(false);
        }
    },

    stopRunAction: function () {
        let _objLun = cc.find('node_lunpan/wheel/di1', this.node)
        _objLun.stopAllActions()
        _objLun.angle = this._targetAngle
        this._showResultEff()
        cc.director.getCollisionManager().enabled = false
        this._buyWheelResult()
    },

    onClickSkip() {
        //点击 即刻消失
        this.skipBtnEnable(false)
        this.stopRunAction()
    },

    //轮盘转动
    _lunpanMove: function () {
        cc.director.getCollisionManager().enabled = true;

        //显示skip按钮
        this.skipBtnEnable(true)
        this.showCloseBtnState(false)

        let objLun;     //转盘
        let nCir = 4;   //圈数
        let nTotal;     //转盘总转动角度

        this.buyWheelSpine.node.active = true
        this.buyWheelSpine.setAnimation(0, SkeletonCfg.paySpin, false);
        this.buyWheelSpine.addAnimation(1, SkeletonCfg.payMarquee, true);

        objLun = cc.find('node_lunpan/wheel/di1', this.node);           //付费转盘角度修改
        nTotal = (this._buyResultIdx) * (360 / this._buyPrizeData.length) + nCir * 360 //+ (360/this._buyPrizeData.length)/2;

        this._targetAngle = -nTotal

        let self = this;
        objLun.angle = 0
        cc.tween(objLun)
            .by(8, { angle: -nTotal }, { easing: 'quadInOut' })
            .call(() => {
                self._showResultEff();
                cc.director.getCollisionManager().enabled = false;
                self.skipBtnEnable(false)
            })
            .delay(1.5)
            .call(() => { self._buyWheelResult() })
            .start();
    },

    //显示转盘转完特效
    _showResultEff: function () {
        Global.playEff(Global.SOUNDS.sound_wheel_result);

        this.buyWheelSpine.clearTracks();
        this.buyWheelSpine.node.active = false;
        this.buyPointSpine.node.active = true
        this.buyPointSpine.setAnimation(0, SkeletonCfg.payPointer, true);
        //    遮罩显示
        this.newPayblack.active = true
    },

    //非免费转盘奖励
    _buyWheelResult: function () {
        this.updateFortuneCoin();

        this.setBuyBtnEnable(false)
        // 旋转结束，显示关闭按钮
        // this.showCloseBtnState(true);
    },

    //更新FORTUNE WHEEL金币
    updateFortuneCoin: function () {
        this.fortuneEndNum = this._addCoin;
        let self = this;

        let hideCoinNode = function () {
            Global.dispatchEvent(EventId.UPATE_COINS)
            // let coinNode = self.node.getChildByName('spr_coin');
            // coinNode.active = false;

            //付费购买后，旋转完就关闭
            self.onClickClose()
        };
        let callFunc = function () {
            let startPos = self.node.convertToNodeSpaceAR(self.lbl_fortune.convertToWorldSpaceAR(cc.v2(0, 0)));
            self.showHallCoin(startPos, hideCoinNode);
        };
        this.updateNums(this.lbl_fortune, this.fortuneEndNum, true, callFunc);
    },

    updateNums: function (node, coins, bAction = false, callFunc) {
        let lbl = node.getComponent(cc.Label);
        let curCoin = Global.FormatCommaNumToNum(lbl.string);
        if (bAction && coins >= curCoin) {
            let addCoin = (coins - curCoin) / 100.0;
            node.runAction(cc.repeatForever(cc.sequence(cc.delayTime(0.02), cc.callFunc(() => {
                curCoin += addCoin;
                curCoin = Math.min(curCoin, coins);
                lbl.string = Global.FormatNumToComma(Math.floor(curCoin));
                if (curCoin >= coins) {
                    node.stopAllActions();

                    if (callFunc) callFunc();

                }
            }))));
        }
        else {
            lbl.string = Global.FormatNumToComma(Math.floor(coins));

            node.stopAllActions();
            if (callFunc) callFunc();
        }
    },

    //显示大厅的coin节点，显示飞金币动画
    showHallCoin: function (startPos, callFunc) {
        // let coinNode;
        // if(this.node.getChildByName('spr_coin')){
        //     coinNode = this.node.getChildByName('spr_coin');
        //     coinNode.active = true;
        // }else {
        //     let hall_spr_coin = cc.vv.gameData? cc.find(Global.INGAME_COIN_NODE_PATH):cc.find(Global.HALL_COIN_NODE_PATH);
        //     hall_spr_coin = hall_spr_coin.parent
        //     if (!hall_spr_coin) {
        //         hall_spr_coin = cc.find("Canvas/LMSlots_Top/playerCoins");
        //     }
        //     let spr_coin_pos = this.node.convertToNodeSpaceAR(hall_spr_coin.convertToWorldSpaceAR(cc.v2(0,0)));

        //     coinNode = cc.instantiate(hall_spr_coin);
        //     coinNode.name = 'spr_coin'
        //     coinNode.parent = this.node;
        //     coinNode.position = spr_coin_pos;
        // }

        // let imgCoin = coinNode.getChildByName('spr_coin');
        // let endPos = cc.v2(coinNode.x + imgCoin.x,coinNode.y + imgCoin.y);
        // let lblCoin = coinNode.getChildByName('lbl_coin');

        // let coinPre = cc.instantiate(this.prefab_coin);
        // coinPre.parent = this.node;
        // coinPre.position = cc.v2(0,0);
        // let flyCoins = coinPre.getComponent("FlyCoins");
        // if(flyCoins){
        //     this.updateNums(lblCoin,this._userCoin, true);
        //     flyCoins.showFlyCoins(startPos,endPos,20,callFunc);
        // }
        let self = this

        // this.updateNums(this.lbl_fortune,this._addCoin, true);
        let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        if (cc.vv.gameData) {
            toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
        }

        // let lbl = this.lbl_fortune.getComponent(cc.Label);
        // let curCoin = Global.FormatCommaNumToNum(lbl.string);
        let rollData = {}
        rollData.lblCoin = toLbl
        rollData.addCoin = this._addCoin

        Global.FlyCoin(this.lbl_fortune, endNode, () => {
            if (cc.vv.gameData) {
                cc.vv.gameData.AddCoin(self._addCoin)
                cc.vv.gameData.RefushMyCoin()
            } else {
                cc.vv.UserManager.AddCoin(self._addCoin, true)
            }
            //金币飞完再出现关闭按钮 回调函数里转完自动关闭
            callFunc()
        }, rollData, true)
    },

    //获取转盘配置
    onRcvGetWheelSpineConf: function (msg) {
        if (msg.code === 200) {
            this._buyPrizeData = msg.conf;
            this._price = msg.price;
            this._fortuneCoin = msg.coin;
            this._showCoin = msg.show_coin
            this._buyRewards = msg.shopList[0].rewards

            this.initBuyWheel();

            this._purchaseData = msg.shopList;
        }
    },

    //获取转盘结果
    onRcvGetSpineResult: function (msg) {
        if (!cc.isValid(this.node)) {
            return
        }

        if (msg.code === 200) {
            this._buyResultIdx = msg.idx - 1;
            this._isBuySpinBtn = true;

            this._nextType = msg.nextType;
            this._nextTime = msg.nextTime;
            this._userCoin = msg.user.coin;
            cc.vv.UserManager.coin = this._userCoin

            if (msg.addCoin) {
                this._addCoin = msg.addCoin;
            }
            if (msg.type2_vip) {
                this._type2_vip = msg.type2_vip;
            }
            if (msg.rank_benefit) {
                this._rank_benefit = msg.rank_benefit;
            }

            this._lunpanMove();
        }

        else if (msg.code === 399) {
            if (this._purchaseData) {
                let productid = this._purchaseData[0].id;
                cc.vv.PayMgr.reqPurchaseOrder(productid);


            }
            else {
                console.log("没有充值数据");
            }
        }
    },

    //关闭前显示确认面板
    onShowSureNode: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_BUYWHEEL_CLOSE)

        if (this._isBuySpinBtn || this._hasClickSure) {

            this.onClickClose();
            return;
        }
        Global.playComEff("ch_notification");
        if (cc.isValid(this._node_sure, true)) {
            this._node_sure.active = true;
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_BUYWHEEL_SUREPOP)

            let bgShark = cc.find("bgShark", this._node_sure)
            bgShark.scale = 0.2
            cc.tween(bgShark)
                .to(0.2, { scale: 1 })
                .repeatForever(
                    cc.tween()
                        .by(2.5, { angle: 540 })
                )
                .start()
        }

    },

    //关闭
    onClickClose: function () {

        // this.sendTurntableStateReq();
        Global.playComEff("ch_close");
        this.node.destroy();
    },

    onClickCloseSure: function () {
        this._hasClickSure = true
        this._node_sure.active = false
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_BUYWHEEL_SURECLOSE)
        this.onClickClose()
    },


    showCloseBtnState(bShow) {
        // Global.playComEff("ch_close");
        cc.find("btn_close", this.node).active = bShow;
    },

    OnEventPayResult: function (data) {
        if (!data) {//支付失败
            this.setBuyBtnEnable(true)
        }

    },

    setBuyBtnEnable: function (bEnable) {
        let btnSpin = cc.find('node_lunpan/btn_spin', this.node)
        btnSpin.getComponent(cc.Button).interactable = bEnable
        if (bEnable) {
            this._node_sure.active = true
        }
    },


    onDestroy() {
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI)
        Global.popBgm()
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SPINE_CONF, this.onRcvGetWheelSpineConf, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SPINE_RESULT, this.onRcvGetSpineResult, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, false, this);
    },

    // update (dt) {},
});
