cc.Class({
    extends: cc.Component,

    properties: {
        itemAtlas: {
            default: null,
            type: cc.SpriteAtlas,
        },

        pointSpine: {
            default: null,
            type: sp.Skeleton,
        },

    },

    onLoad() {
        this.distanceX = 95
        this.itemGiftPrefab = cc.find('list/item', this.node)
    },

    initItem(data) {
        this._rd = data



    },

    showRewards: function () {
        if (this._bCreater) return
        this._bCreater = true
        let data = this._rd
        this.setData(this.itemGiftPrefab, data[0].type, data[0].count, 0)
        var itemNode = null
        //初始化礼包数据
        for (let index = 1; index < data.length; index++) {
            itemNode = cc.instantiate(this.itemGiftPrefab);
            this.setData(itemNode, data[index].type, data[index].count, index)
            itemNode.parent = this.itemGiftPrefab.parent;
        }
    },

    setData(itemNode, id, count, posX) {
        if (id == 1) {
            id = 5
        }

        let url = 'common/rewarditem/' + id
        cc.loader.loadRes(url, cc.SpriteFrame, (err, data) => {
            if (!err) {
                itemNode.getComponent(cc.Sprite).spriteFrame = data
            }
        })

        let num = 0
        if (id == 5) {
            num = Global.convertNumToShort(count, 1000, 2)
        } else if (id == 3) {
            num = (count / 3600).toFixed(0) + "H"
        } else {
            num = count
        }
        cc.find('num', itemNode).getComponent(cc.Label).string = num
        itemNode.x = (posX == 0) ? -this.distanceX : this.distanceX * (posX - 1)
    },

    setCanGetGift(flag) {
        this.isCan = flag
        if (flag) {
            this.setAnimaTwo()
        }
        else {
            this.setAnimaOne()
        }

    },

    onClickGiftBtn(event, customEventData) {
        Global.playComEff("ch_btn_click");
        // if (this.isCan) {
        //     this.isCan = false
        //     //发送消息 需要领取
        //     let canvas = cc.find("Canvas");
        //     let signNode = cc.find('SignIn',canvas)
        //     signNode.getComponent('Signin').sendGetSignGift(customEventData)
        // }else {
        this.showRewards()
        //点击了礼包按钮
        let num = this.getCount(customEventData)
        let parentNode = this.node.parent
        if (parentNode) {
            for (let i = 0; i < parentNode.children.length; i++) {
                if (num == (i + 1)) {
                    let listNode = cc.find('list', parentNode.children[i])
                    listNode.active = true
                    listNode.runAction(cc.sequence(
                        cc.delayTime(2),
                        cc.callFunc(function () {
                            listNode.active = false
                        }, this)
                    )
                    )
                } else {
                    let listOtherNode = cc.find('list', parentNode.children[i])
                    listOtherNode.active = false
                    listOtherNode.stopAllActions()
                }
            }
        }
        // }
    },

    getCount(eventData) {
        if (eventData == 8) {
            return 1
        } else if (eventData == 15) {
            return 2
        } else if (eventData == 22) {
            return 3
        } else if (eventData == 30) {
            return 4
        }
    },


    setAnimaTwo() {
        this.pointSpine.setAnimation(0, 'animation2', true);
    },

    setAnimaOne() {
        this.pointSpine.setAnimation(0, 'animation', true);
    },

    start() {

    },

    // update (dt) {},
});
