/**
 * FB绑定成功提示
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _coin: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn = cc.find('spr_bg/btn_confirm', this.node)
        Global.btnClickEvent(btn, this.onClickConfirm, this)
    },

    start() {

    },

    //设置奖励
    //TODO
    ShowReward: function (nCoin) {
        let lbl_coin = cc.find("spr_bg/coin_bg/lbl_coin", this.node)
        if (nCoin) {
            this._coin = nCoin;
            lbl_coin.getComponent(cc.Label).string = nCoin;
        }
    },

    //点击确认
    onClickConfirm: function () {
        //加钱TODO
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
        rollData.addCoin = this._coin
        let coinNode = cc.find("spr_bg/coin_bg/lbl_coin", this.node)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        let endCall = function () {
            if (cc.isValid(this.node)) this.node.destroy();

        }.bind(this)
        cc.vv.UserManager.AddCoin(this._coin, false)
        Global.FlyCoin(coinNode, endNode, endCall, rollData, true)
    },

    // update (dt) {},
});
