
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        lbl_name: cc.Label,
        lbl_level: cc.Label,
        lbl_vip: cc.Label,
        lbl_coin: cc.Label,
        lbl_diam: cc.Label,
        userHead: cc.Node,
        btn_fb: cc.Node,
        lbl_uid: cc.Label,
        vip_icon: cc.Node,
        editBox: cc.EditBox,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        //判断是否是fb绑定用户
        cc.find('spr_ui_bg/node_info/fbPng', this.node).active = cc.vv.UserManager.isBindFb() ? true : false
        Global.registerEvent(EventId.CHANGE_USER_HEAD, this.onEventChangeHead, this);  //修改头像
        let modifyBtn = cc.find("spr_ui_bg/node_info/img_bg_name/modifyBtn", this.node);
        Global.btnClickEvent(modifyBtn, this.onClickModifyBtn, this);
        // let sendGiftBtn = cc.find("spr_ui_bg/node_info/btn_send_gift", this.node);
        // Global.btnClickEvent(sendGiftBtn,this.onClickSendGiftBtn,this);
        // let receiveGiftBtn = cc.find("spr_ui_bg/node_info/btn_receive_gift", this.node);
        // Global.btnClickEvent(receiveGiftBtn,this.onClickReceiveGiftBtn,this);
        this.editBox.node.active = false
        this.lblName = cc.find("spr_ui_bg/node_info/img_bg_name/lbl_name", this.node)
        this.lblName.active = true
        Global.playComEff("ch_popup");
        this.changeName = ''
    },

    registerMsg() {
        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonalInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_CHANGE_USER_HEAD, this.onRcvChangeName, this);
    },
    // cc.vv.NetManager.registerMsg(MsgId.REQ_BIND_FACEBOOK, this.onRcvBindFacebook, this);

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonalInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_CHANGE_USER_HEAD, this.onRcvChangeName, false, this);
    },
    // cc.vv.NetManager.unregisterMsg(MsgId.REQ_BIND_FACEBOOK, this.onRcvBindFacebook, false, this);

    onRcvChangeName() { },

    registEditBox() {
        ;
        this.editBox.node.on('editing-did-ended', this.editingEnded, this);
    },

    editingEnded(editbox) {
        if (editbox.string) {
            if (editbox.string.search(' ') >= 0) {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_name_incorrect);
                // cc.vv.FloatTip.show('Name is incorrect,please enter your new name.')
            } else {
                this.changeName = editbox.string
                this.lblName.getComponent(cc.Label).string = editbox.string
            }
        } else {
            //空字符    显示系统提示
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_name_null);
            // cc.vv.FloatTip.show('Name is null,please enter your new name.')
        }
        this.editBox.node.active = false
        this.lblName.active = true
        // cc.vv.NewGuide.ShowGuide(52)
    },

    start() {
        this.init()
        this.registerMsg();
        this.reqPersonalInfo();
        this.registEditBox()
        //头像红点控制
        Global.saveLocal("clickHead", 1)
        Global.dispatchEvent(EventId.REFUSH_RED_TIPS)
        // cc.vv.NewGuide.ShowGuide(51)
    },

    // init (playerInfo){
    init() {
        // this._player_data = playerInfo;
        // this.lbl_name.string = playerInfo.playername;
        this.lbl_name.string = cc.vv.UserManager.nickName
        // this.lbl_level.string = playerInfo.level;
        this.lbl_level.string = cc.vv.UserManager.level
        // this.lbl_vip.string = playerInfo.svip;
        this.lbl_vip.string = cc.vv.UserManager.svip
        // this.lbl_coin.string = Global.FormatNumToComma(playerInfo.coin).toString();
        this.lbl_coin.string = Global.FormatNumToComma(cc.vv.UserManager.coin).toString();
        this.lbl_diam.string = Global.FormatNumToComma(cc.vv.UserManager.getDiamond()).toString();
        // this.lbl_uid.string = playerInfo.uid
        this.lbl_uid.string = cc.vv.UserManager.uid
        // let icon = playerInfo.icon || playerInfo.userIcon || playerInfo.usericon;
        let icon = cc.vv.UserManager.userIcon
        if (icon) {
            this.userHead.getComponent('UserHead').setHead(cc.vv.UserManager.uid, icon);
        }
        this.btn_fb.active = !cc.vv.UserManager.isBindFb() && Global.isAndroidReview;
        if (Global.appId == Global.APPID.SouthAmerica || Global.appId == Global.APPID.HuaweiDRM) {
            this.btn_fb.active = false
        }
        cc.find('spr_ui_bg/node_info/btn_connectus', this.node).active = Global.isAndroidReview
        // let bGuest = cc.vv.UserManager.getLoginType() == Global.LoginType.Guest;
        // cc.find("spr_ui_bg/node_info/btn_change", this.node).active = bGuest;
        // this._picid = playerInfo.picid;
    },

    //修改头像
    onEventChangeHead(data) {
        data = data.detail;
        let uid = cc.vv.UserManager.uid
        let headIcon = cc.vv.UserManager.userIcon
        this.userHead.getComponent('UserHead').setHead(uid, headIcon)
        if (data.picid) {
            this._picid = data.picid;
        }
    },

    reqPersonalInfo() {
        let req = { c: MsgId.PERSIONAL_INFO };
        req.otheruid = Global.playerData.uid;
        cc.vv.NetManager.sendAndCache(req);
    },

    onRcvPersonalInfo(retData) {
        if (retData.code === 200) {
            let playerInfo = retData.playerInfo;
            if (playerInfo) {
                // this.init(playerInfo);
                this._picid = playerInfo.picid;
            }
        }
    },

    // onRcvBindFacebook (retData) {
    //     if (retData.code === 200) {
    //         cc.vv.UserManager.setIsBindFb(true);
    //         cc.vv.AlertView.showTips("Facebook Account Bind Success!");
    //         this.btn_fb.active = false;
    //     }
    // },

    onFbClick() {
        Global.playComEff("ch_btn_click");
        let self = this
        // cc.vv.PlatformApiMgr.fbLoginOut();
        cc.vv.PlatformApiMgr.fbLogin((cbData) => {
            console.log("=======LMSlots--FbAuth=========:  " + JSON.stringify(cbData));
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = { c: MsgId.REQ_BIND_FACEBOOK };
                req.accesstoken = cbData.token;
                req.user = cbData.uid;
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req);
                //关闭界面
                self.onCloseClick()
            }
            else {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
            }
        });
    },

    onGoogleClick() {
        Global.playComEff("ch_btn_click");
        let self = this
        cc.vv.PlatformApiMgr.startGoogleLogin((cbData) => {
            let result = parseInt(cbData.result);
            if (result) {
                let userInfo = cbData.userInfo;
                let req = { c: MsgId.REQ_BIND_FACEBOOK };
                req.accesstoken = userInfo.id_token;
                req.user = userInfo.email;
                req.type = Global.LoginType.GOOGLE_LOGIN
                cc.vv.NetManager.send(req);
                self.onCloseClick()
                // let userInfo = cbData.userInfo;
                // cc.vv.GameManager.reqLogin(userInfo.email, "", Global.LoginType.GOOGLE_LOGIN, "", {nick:userInfo.name, img:userInfo.img}, userInfo.id_token);
            }
            else {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_google_bind_failed);
                // cc.vv.FloatTip.show("Google Account Bind Failed!");
            }
        });
    },

    //点击礼物记录
    onClickConnectus() {
        Global.playComEff("ch_btn_click");
        cc.vv.RedSys.clearRedTip(26)
        cc.loader.loadRes("CashHero/prefab/gift/gift_detail", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let node = cc.find('gift_detail', parObj)
                if (!node) {
                    node = cc.instantiate(prefab);
                    node.parent = parObj
                }
            }
        })
        this.node.destroy()
    },

    onRechargeClick() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_PERSONALINFO_COIN)
        cc.vv.UserManager.setEnterHallAction('Shop_Coin')
        Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
        this.node.destroy()
    },

    onRechargeDiamond() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_PERSONALINFO_DIA)
        cc.vv.UserManager.setEnterHallAction('Shop_Diamond')
        Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
        this.node.destroy()
    },

    onCloseClick() {
        Global.playComEff("ch_close");
        if (this.changeName) {
            this.sendChangeName()
        }
        if (cc.isValid(this.node)) {
            this.node.destroy();
        }
    },

    sendChangeName() {
        let req = { c: MsgId.REQ_CHANGE_USER_HEAD };
        req.uid = Global.playerData.uid;
        req.rtype = 2
        req.playername = this.changeName
        cc.vv.NetManager.send(req);
        cc.vv.UserManager.setNickName(this.changeName)
    },

    // 更换头像
    onChangeHead() {
        let self = this;
        cc.loader.loadRes("hall_prefab/ChangeHead", cc.Prefab, (err, prefab) => {
            if (!cc.find("ChangeHead", self.node)) {
                let node = cc.instantiate(prefab)
                node.parent = self.node;
                node.getComponent("ChangeUserHead").initShow(this._picid);
            }
        })
    },

    onClickModifyBtn() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_PERSONALINFO_EDITNAME)
        this.editBox._impl.beginEditing()
        this.editBox.node.active = true
        this.lblName.active = false
    },

    // // 赠送礼物详情
    // onClickSendGiftBtn:function(){
    //     cc.loader.loadRes("CashHero/prefab/gift/gift_detail",cc.Prefab, (err, prefab) => {
    //         if (!err) {
    //             let parObj = cc.find("Canvas");
    //             let node = cc.find('gift_detail',parObj)
    //             if(!node){
    //                 node = cc.instantiate(prefab);
    //                 node.parent = parObj
    //             }
    //             node.getComponent("gift_detail").showInfo(true);
    //         }
    //     })
    // },

    // // 收取礼物详情
    // onClickReceiveGiftBtn:function(){
    //     cc.loader.loadRes("CashHero/prefab/gift/gift_detail",cc.Prefab, (err, prefab) => {
    //         if (!err) {
    //             let parObj = cc.find("Canvas");
    //             let node = cc.find('gift_detail',parObj)
    //             if(!node){
    //                 node = cc.instantiate(prefab);
    //                 node.parent = parObj
    //             }
    //             node.getComponent("gift_detail").showInfo(false);
    //         }
    //     })
    // },

    // update (dt) {},
});
