cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    onLoad() {
        window.SlotsFacade = this; // 创建个全局变量，以便子模块方便访问
        this.dm = cc.vv.gameData;
        this.mainPanel = cc.find("safe_node", this.node).addComponent("MagicFrog_MainPanel");
        this.soundMgr = this.addComponent("MagicFrog_Sound");
        this.InitCommComponent();

        this.flowCtrl = this.addComponent("MagicFrog_FlowCtrl");
        this.popup = this.mainPanel.popup_node.addComponent("MagicFrog_Popup");
        this.collectProgress = this.mainPanel.collect_progress.getComponent("MagicFrog_CollectProgress");
        this.map = this.mainPanel.map_node.addComponent("MagicFrog_Map");
        this.respinGame = this.mainPanel.respin_game_node.getComponent("MagicFrog_RespinGame");
        this.slots777 = this.mainPanel.slots777.getComponent("LMSlots_Subgame777");
        this.wildGame = this.mainPanel.wild_game.getComponent("MagicFrog_WildGame");
        this.respinWheelGame = this.mainPanel.wheel_game_node.getComponent("MagicFrog_RespinWheelGame");
        this.character = this.mainPanel.character_node.getComponent("MagicFrog_Character");
        this.extraBonusGame = this.mainPanel.extra_bonus_node.getComponent("MagicFrog_ExtraBonusGame");
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, () => {
            this.collectProgress.showCollect();
            this.character.showExtraBall();
        }, this);

        // 设置基类快捷索引
        this.topCmp = cc.vv.gameData.GetTopScript();
        this.bottomCmp = cc.vv.gameData.GetBottomScript();
        this.slots = cc.vv.gameData.GetSlotsScript();
    },

    onDestroy() {
        window.SlotsFacade = null;
        this.dm = null;
    },

    delayTime(time) {
        return new Promise((res, rej) => {
            this.scheduleOnce(() => { res() }, time);
        });
    },
});
