/**
 * 成长基金
 */
const List = require('List');
cc.Class({
    extends: cc.Component,

    properties: {
        listview: List,
        prize_rewards: cc.Prefab,
        // _fund_items:[],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() { },

    start() {
        this.registerMsg();
    },

    registerMsg() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_COLLECT_GROWTH_FUND, this.onRcvCollectFund, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_COLLECT_GROWTH_FUND, this.onRcvCollectFund, false, this);
    },

    initShow(data) {
        this._listData = data.detail;
        this._canbuy = data.canbuy
        this._id = data.id
        //if (data.timeout) {
        //    Global.setLabelString("time_bg/lbl_time", this.node, data.timeout+" DAYS LEFT")
        //}
        this.showList();
        let btn_purchased = cc.find("btn_purchased", this.node);
        cc.find("lbl_purchased", btn_purchased).active = !data.canbuy;
        let lbl_price_normal = cc.find("lbl_price", btn_purchased)
        // lbl_price_normal.active = data.canbuy;
        // cc.find("lbl_price", btn_purchased).getComponent(cc.Label).string = cc.js.formatStr(cc.vv.Language.btn_only, data.amount);
        I18N.setI18nLabel(cc.find("lbl_price", btn_purchased), cc.vv.Language.btn_only, data.amount)
        let bDiscount = data.timeout ? true : false
        let node_discount = cc.find('dis_node_tag', this.node)
        node_discount.active = bDiscount
        let node_price_dis = cc.find('dis_node', btn_purchased)
        node_price_dis.active = bDiscount
        lbl_price_normal.active = !bDiscount && data.canbuy
        if (bDiscount) {
            // cc.find("lbl_old",node_price_dis).getComponent(cc.Label).string = cc.js.formatStr(cc.vv.Language.shop_fund_btn_was, data.oamount);
            // cc.find("lbl_dis",node_price_dis).getComponent(cc.Label).string = cc.js.formatStr(cc.vv.Language.btn_only, data.amount);
            I18N.setI18nLabel(cc.find("lbl_dis", node_price_dis), cc.vv.Language.btn_only, data.amount)
            I18N.setI18nLabel(cc.find("lbl_old", node_price_dis), cc.vv.Language.shop_fund_btn_was, data.amount)
            let lbl_time = cc.find('time_bg/lbl_time', node_discount)
            // lbl_time.getComponent(cc.Label).string = Global.formatSec(data.timeout) + " LEFT"
            I18N.setI18nLabel(lbl_time, cc.vv.Language.lefttime1, Global.formatSec(data.timeout))
            lbl_time.stopAllActions()
            cc.tween(lbl_time)
                .repeatForever(
                    cc.tween()
                        .delay(1)
                        .call(() => {
                            data.timeout -= 1
                            if (data.timeout < 0) {
                                data.timeout = 0
                                //刷新列表
                                this.reqPurchaseList()
                            }
                            lbl_time.getComponent(cc.Label).string = Global.formatSec(data.timeout) + " LEFT"
                            I18N.setI18nLabel(lbl_time, cc.vv.Language.lefttime1, Global.formatSec(data.timeout))
                        })
                )
                .start()
        }
        if (data.canbuy) {
            btn_purchased.getComponent(cc.Button).interactable = true;
            btn_purchased.on("click", () => {
                StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_GROWTHFUND)
                cc.vv.PayMgr.reqPurchaseOrder(data.id);
            })
        } else {
            btn_purchased.getComponent(cc.Button).interactable = false
            Global.showSpriteGray(cc.find("Background", btn_purchased), true);
        }
    },

    showList() {
        let centre = cc.find("centre", this.node);
        let winCoin = 0
        let cardCount = 0
        let richCount = 0
        for (let i = 0; i < centre.childrenCount; i++) {
            this.showItem(centre.children[i], this._listData[i])
            let rewards = this._listData[i].rewards
            for (let i = 0; i < rewards.length; i++) {
                let reward = rewards[i]
                if (reward.type == Global.PROP_ID.COIN) {
                    winCoin += reward.count
                } else if (reward.type == Global.PROP_ID.RICH_POINT) {
                    richCount += reward.count
                } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                    cardCount += reward.count
                }
            }
        }
        Global.setLabelString("info_bg/lbl_total_coin", this.node, Global.FormatNumToComma(winCoin))
        Global.setLabelString("info_bg/item1/lbl_num", this.node, "" + cardCount)
        Global.setLabelString("info_bg/item2/lbl_num", this.node, "" + richCount)
    },

    showItem(node, data) {
        if (node) {
            let str_tit0 = "Purchase Return";
            let str_tit1 = cc.js.formatStr(cc.vv.Language.shop_fund_lvReturn, data.lv);
            if (data.lv > 1) {
                I18N.setI18nLabel(cc.find("lbl_tit", node), cc.vv.Language.shop_fund_lvReturn, data.lv)
            }
            // cc.find("lbl_tit", node).getComponent(cc.Label).string = data.lv>1 ? str_tit1 : str_tit0;
            node.name = data.fundid + "";
            //进度
            if (data.lv > 1) {
                let lv = Math.min(cc.vv.UserManager.getCurLv(), data.lv)
                cc.find("progress", node).getComponent(cc.ProgressBar).progress = lv / data.lv
                Global.setLabelString("progress/lbl_prog", node, lv + "/" + data.lv)
            }
            //收集状态
            this.showCollectState(node, data);
            //奖励
            this.showPrizeItem(node, data.rewards)
        }
    },

    // 收集状态
    showCollectState(node, data) {
        let spr_gou = cc.find("spr_gou", node);
        let btn = cc.find("btn", node);
        let locker = cc.find("locker", btn)
        let lv = cc.vv.UserManager.getCurLv()
        locker.active = false
        spr_gou.active = false;
        btn.active = false;
        btn.off("click");
        if (data.collect == 0) {  // 等待收集
            btn.active = true;
            btn.getComponent(cc.Button).interactable = true
            cc.find("lbl_collect", btn).getComponent(cc.LabelOutline).color = cc.Color(27, 79, 17)
            Global.btnClickEvent(btn, this.OnClickCollect, this)
        } else if (data.collect == 1) {   // 已经收集
            spr_gou.active = true;
        } else if (data.collect == 2) {   //不能收集
            btn.active = true;
            if (this._canbuy == 1) { //未购买
                if (lv < data.lv) { //等级不够
                    locker.active = false
                    btn.getComponent(cc.Button).interactable = false
                    cc.find("lbl_collect", btn).getComponent(cc.LabelOutline).color = cc.Color(64, 64, 64)
                } else {
                    locker.active = true
                    btn.getComponent(cc.Button).interactable = true
                    cc.find("lbl_collect", btn).getComponent(cc.LabelOutline).color = cc.Color(27, 79, 17)
                    Global.btnClickEvent(btn, this.OnClickPurchase, this)
                }
            } else { //已购买，等级不够
                locker.active = false
                btn.getComponent(cc.Button).interactable = false
                cc.find("lbl_collect", btn).getComponent(cc.LabelOutline).color = cc.Color(64, 64, 64)
            }
        }
    },

    convertNumToShort(num) {
        if (num >= 100000000) {
            return Global.FormatNumToComma(Math.floor(num / 1000000)) + 'M'
        } else if (num >= 1000000) {
            return Global.FormatNumToComma(Math.floor(num / 1000)) + 'K'
        } else {
            return Global.FormatNumToComma(num)
        }
    },

    // 奖励图标
    showPrizeItem(node, rewards) {
        let items = []
        for (let i = 1; i <= 3; i++) {
            let item = cc.find("prize_item_" + i, node)
            item.active = false
            items.push(item)
        }
        let winCoin = 0
        let cardCount = 0
        let richCount = 0
        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            if (reward.type == Global.PROP_ID.COIN) {
                winCoin += reward.count
            } else if (reward.type == Global.PROP_ID.RICH_POINT) {
                richCount += reward.count
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                cardCount += reward.count
            }
        }
        if (winCoin > 0) {
            items[0].active = true
            Global.setLabelString("lblNum", items[0], Global.FormatNumToComma(winCoin))
        }
        if (cardCount > 0) {
            items[1].active = true
            Global.setLabelString("lblNum", items[1], "" + cardCount)
        }
        if (richCount > 0) {
            items[2].active = true
            Global.setLabelString("lblNum", items[2], "x" + richCount)
        }
    },

    OnClickCollect(event) {
        Global.playComEff("ch_collect")
        let item = event.node.parent;
        this._clickFundId = Number(item.name);
        let req = { c: MsgId.REQ_COLLECT_GROWTH_FUND };
        req.uid = Global.playerData.uid;
        req.fundid = this._clickFundId;
        cc.vv.NetManager.send(req);
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_GROWTHFUND_COLLECT, this._clickFundId)
    },

    OnClickPurchase(event) {
        Global.playComEff("ch_btn_click");
        Global.delayInteractable(event.node)
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_GROWTHFUND)
        cc.vv.PayMgr.reqPurchaseOrder(this._id)
    },

    onRcvCollectFund(msg) {
        if (msg.code === 200) {
            this.showPrizeRewards(msg.rewards)
        }
    },

    // async showDropCard(cardid, count) {
    //     return new Promise((sucess, failed)=>{
    //         cc.vv.HerocardManager.showDropUI(cardid, count, sucess, false)
    //     });  
    // },

    async closePrize(rewards) {
        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            if (reward.type == Global.PROP_ID.COIN) {
                cc.vv.UserManager.AddCoin(reward.count, true)
            } else if (reward.type == Global.PROP_ID.RICH_POINT) {
                cc.vv.UserManager.addRichPoint(reward.count)
            }
        }
        Global.dispatchEvent(EventId.REFRESH_SHOP_COIN);
        cc.vv.NetManager.send({ c: MsgId.SYNC_COIN });
        this._canbuy = 0
        for (let i = 0; i < this._listData.length; i++) {
            if (this._clickFundId === this._listData[i].fundid) {
                this._listData[i].collect = 1;
                this.showList();
                break;
            }
        }
        cc.vv.UserManager.setHeroData(rewards)
        //显示获得的卡牌
        // for (let i=0; i<rewards.length; i++) {
        //     let reward = rewards[i]
        //     if (reward.type == Global.PROP_ID.HERO_CARD) {
        //         if (reward.cardInfo) {
        //             cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
        //             Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
        //         }
        //         await this.showDropCard(reward.cardID, reward.count)
        //     }
        // }
        this._showHeroCard(rewards)
        cc.vv.UserManager.clearHeroData()
    },

    _showHeroCard(rdArray) {
        let self = this
        let nextCall = function () {
        }
        cc.vv.UserManager.loadPopReward(rdArray, nextCall)
    },

    // 领取结果
    showPrizeRewards(rewards) {
        let prize = cc.instantiate(this.prize_rewards);
        prize.parent = cc.find("Canvas");
        let spr_bg = cc.find("spr_bg", prize);
        this.showPrizeItem(cc.find("spr_bg/layout", prize), rewards);
        Global.playCashEff('fbshare/boom')
        spr_bg.setScale(0)
        cc.tween(spr_bg)
            .to(0.5, { scale: 1 }, { easing: "backOut" })
            .call(() => {
                let closeBtn = cc.find("closeBtn", prize);
                closeBtn.on("click", async () => {
                    closeBtn.off("click")
                    this.closePrize(rewards)
                    prize.destroy()
                })
            })
            .start()
    },

    onClickClose: function () {
        this.node.destroy()
    },

    // update (dt) {},
});
