/**
 * 转盘
 */
//轮盘特效
let SkeletonCfg = {
    freePointer: 'animation2_1', //免费转盘停止后指针效果
    payPointer: 'animation1_1',    //付费转盘停止后指针效果
    paySpin: 'animation3',         //点击spin按钮效果
    payMarquee: 'animation1_3',      //转盘外围跑马灯效果
    // payX20:'animation1_2',      //X20
};



cc.Class({
    extends: cc.Component,

    properties: {
        freePointSpine: {
            default: null,
            type: sp.Skeleton,
        },

        prefab_coin: {
            default: null,
            type: cc.Prefab,
        },
        newFreeblack: {
            default: null,
            type: cc.Node
        },
        newWheelNumFontNor: {
            default: null,
            type: cc.BitmapFont
        },
        newWheelNumFontVip: {
            default: null,
            type: cc.BitmapFont
        },

        _freeItemList: [],     //免费转盘item列表
        _freePrizeData: [],    //免费转盘配置
        _freeResultIdx: null,  //免费转盘结果
        _vipMultData: [],      //vip配置
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SPINE_CONF, this.onRcvGetFreeSpineConf, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SPINE_RESULT, this.onRcvGetSpineResult, this);

        Global.playBgm(Global.SOUNDS.bgm_hall_wheel)

        Global.btnClickEvent(cc.find('skipBtn', this.node), this.onClickSkip, this)
        this.skipBtnEnable(false)
    },

    start() {
        Global.FixDesignScale_V(this.node)

        this.setSpinEnabled(false)
        this.sendGetSpineConfReq(1);

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_WHEEL_POP)
    },

    setSpinEnabled: function (bEnable) {
        let btn = cc.find('node_lunpan/btn_spin', this.node)
        btn.getComponent(cc.Button).interactable = bEnable
    },


    //获取收费转盘配置
    onRcvGetBuySpineConf: function () {
        this.sendGetSpineConfReq(2);
    },

    //发送获取转盘配置协议
    //@param rtype  1-免费转盘 2-收费转盘
    sendGetSpineConfReq: function (rtype) {
        var req = { 'c': MsgId.REQ_GET_SPINE_CONF };
        req.uid = Global.playerData.uid;
        req.rtype = rtype;
        cc.vv.NetManager.send(req);
    },

    //发送领取转盘奖励协议
    //@param rtype  1.收集金币 2免费转盘 3收费转盘
    sendGetSpineResultReq: function (rtype) {
        var req = { 'c': MsgId.REQ_GET_SPINE_RESULT };
        req.uid = Global.playerData.uid;
        req.rtype = rtype;
        cc.vv.NetManager.send(req);
    },



    //初始化vip面板
    initVipNode: function () {
        let vipNode = cc.find('node_vip', this.node);

        let layout = vipNode.getChildByName('layout');
        for (let i = 0; i < this._vipMultData.length; i++) {
            let item = layout.getChildByName('item_' + (i + 1));
            let bg = item.getChildByName('bg');
            let red = item.getChildByName('red');
            let lbl_glod = item.getChildByName('lbl_glod');
            let blue = item.getChildByName('blue');
            let lbl_blue = item.getChildByName('lbl_blue');
            //hy    调整新版本vip显示
            if (this._vipMultData[i] === this._vipMult) {
                bg.active = true;
                red.active = true;
                lbl_glod.active = true;
                blue.active = false;
                lbl_blue.active = false;
                this.node_vip_mult = lbl_glod;
            } else {
                bg.active = false;
                red.active = false;
                lbl_glod.active = false;
            }
        }
    },

    //初始化免费转盘
    initFreeWheel: function () {
        this.setSpinEnabled(true)

        this._freeItemList = []
        let prize_item = cc.find('node_lunpan/wheel/di1/item', this.node);
        if (!cc.isValid(prize_item)) return;

        this._freeItemList.push(prize_item);
        for (let i = 1; i < this._freePrizeData.length; i++) {
            let item = cc.instantiate(prize_item);
            item.angle = i * 360 / this._freePrizeData.length;
            item.parent = prize_item.parent;
            this._freeItemList.push(item);
        }
        for (let i = 0; i < this._freeItemList.length; i++) {
            let lbl_coin = this._freeItemList[i].getChildByName('lbl');
            lbl_coin.getComponent(cc.Label).string = Global.convertNumToShort(this._freePrizeData[i], 1000, 2);
            //hy    数字字体切换
            lbl_coin.getComponent(cc.Label).font = (i % 2 == 1) ? this.newWheelNumFontVip : this.newWheelNumFontNor
        }
        //hy    免费遮罩隐藏
        this.newFreeblack.active = false

        let _btn_spin = cc.find('node_lunpan/btn_spin', this.node);
        _btn_spin.getComponent(cc.Button).interactable = true;
        this._node_rewards = cc.find('node_rewards', this.node);
        this._node_rewards.active = false;

    },

    skipBtnEnable(flag) {
        let skipBtn = cc.find('skipBtn', this.node)
        skipBtn.active = flag
    },

    //点击开始转动按钮
    onClickSpin: function (event) {
        Global.playEff(Global.SOUNDS.sound_wheel_spin);

        //点击免费后，弹窗数据修改成付费的
        cc.vv.UserManager.updatePopParams({ "20": 3 })
        //显示skip按钮
        this.skipBtnEnable(true)

        let node = event.target;
        node.getComponent(cc.Button).interactable = false;
        this.sendGetSpineResultReq(2);

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_WHEEL_SPIN)
    },

    stopRunAction: function () {
        let _objLun = cc.find('node_lunpan/wheel/di1', this.node)
        _objLun.stopAllActions()
        _objLun.angle = this._targetAngle
        this._showResultEff()
        cc.director.getCollisionManager().enabled = false
        this._freeWheelResult()
    },

    //轮盘转动
    _lunpanMove: function () {
        cc.director.getCollisionManager().enabled = true;

        let objLun;     //转盘
        let nCir = 4;   //圈数
        let nTotal;     //转盘总转动角度

        objLun = cc.find('node_lunpan/wheel/di1', this.node);
        nTotal = (this._freeResultIdx) * (360 / this._freePrizeData.length) + nCir * 360;

        this._targetAngle = -nTotal

        let self = this;
        objLun.angle = 0
        cc.tween(objLun)
            .by(8, { angle: -nTotal }, { easing: 'quadInOut' })
            .call(() => {
                self._showResultEff();
                cc.director.getCollisionManager().enabled = false;
                self.skipBtnEnable(false)
            })
            .delay(1.5)
            .call(() => { self._freeWheelResult() })
            .start();
    },

    //显示转盘转完特效
    _showResultEff: function () {
        Global.playEff(Global.SOUNDS.sound_wheel_result);

        this.freePointSpine.node.active = true
        this.freePointSpine.setAnimation(0, SkeletonCfg.freePointer, true);
        //    遮罩显示
        this.newFreeblack.active = true
    },

    //免费转盘奖励
    _freeWheelResult: function () {
        this._node_rewards.active = true;

        let _lbl_mega = cc.find('lbl_mega_bonus/lbl', this._node_rewards);
        let _lbl_vip = cc.find('lbl_vip_bonus/lbl', this._node_rewards);
        let _lbl_total = cc.find('lbl_total_bonus/lbl', this._node_rewards);
        let _lbl_rank = cc.find('lbl_rank_bonus/lbl', this._node_rewards);
        let _btn_collect = cc.find('btn_collect', this._node_rewards)

        _lbl_mega.getComponent(cc.Label).string = '';
        _lbl_vip.getComponent(cc.Label).string = '';
        _lbl_total.getComponent(cc.Label).string = '';
        _lbl_rank.getComponent(cc.Label).string = this._rank_benefit;

        let _lbl_fly = this.node.getChildByName('lbl_fly');
        let lbl = _lbl_fly.getChildByName('lbl');
        let lbl_wheelItem = this._freeItemList[this._freeResultIdx].getChildByName('lbl');
        let startPos_item = this.node.convertToNodeSpaceAR(lbl_wheelItem.convertToWorldSpaceAR(cc.v2(0, 0)));
        let startAng_item = lbl_wheelItem.angle;
        let endPos_item = this.node.convertToNodeSpaceAR(_lbl_mega.convertToWorldSpaceAR(cc.v2(0, 0)));
        let endAng_item = _lbl_mega.angle;

        if (!cc.isValid(this.node_vip_mult)) {
            console.log('轮盘未找到VIP配置')
            return
        }
        let startPos_vip = this.node.convertToNodeSpaceAR(this.node_vip_mult.convertToWorldSpaceAR(cc.v2(0, 0)));
        let startAng_vip = this.node_vip_mult.angle;
        let endPos_vip = this.node.convertToNodeSpaceAR(_lbl_vip.convertToWorldSpaceAR(cc.v2(0, 0)));
        let endAng_vip = _lbl_vip.angle;

        _lbl_fly.active = true;
        let megaData = this._freePrizeData[this._freeResultIdx]
        lbl.getComponent(cc.Label).string = megaData;

        let self = this;
        let mult = self._type2_vip;
        let vipLblFlyFunc = function () {
            _lbl_fly.active = false;
            _lbl_vip.getComponent(cc.Label).string = mult;
            _lbl_total.getComponent(cc.Label).string = Global.FormatNumToComma(self._addCoin);

            _btn_collect.active = true
        };
        let itemLblFlyFunc = function () {
            _lbl_mega.getComponent(cc.Label).string = Global.FormatNumToComma(megaData);
            lbl.getComponent(cc.Label).string = mult;
            self._moveLbl(_lbl_fly, startPos_vip, endPos_vip, startAng_vip, endAng_vip, vipLblFlyFunc);
        };
        this._moveLbl(_lbl_fly, startPos_item, endPos_item, startAng_item, endAng_item, itemLblFlyFunc);
    },

    //移动文本动画
    _moveLbl: function (node, startPos, endPos, startAng, endAng, callback) {
        if (node) {
            if (startPos && endPos) {
                let delta = endPos.sub(startPos);
                let d = delta.mag();

                startAng = (startAng != null) ? startAng : node.angle;
                endAng = (endAng != null) ? endAng : startAng;
                node.position = startPos;
                node.angle = startAng;

                cc.tween(node)
                    .to(d / 1600, { position: endPos, angle: endAng })
                    .call(() => {
                        if (callback) callback();
                    })
                    .start()
            }
        }
    },

    onClickSkip() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_WHEEL_SKIP)
        //点击 即刻消失
        this.skipBtnEnable(false)
        this.stopRunAction()
    },

    //免费转盘出现结果 点击领取奖励
    onClickCollect: function (event) {
        Global.playComEff("ch_collect");
        let self = this;
        event.target.getComponent(cc.Button).interactable = false;
        let callFunc = function () {
            self.freePointSpine.clearTracks();
            self.freePointSpine.node.active = false;

            // let coinNode = self.node.getChildByName('spr_coin');
            // coinNode.active = false;
            //更新大厅金币
            Global.dispatchEvent(EventId.UPATE_COINS)

            // //加载付费转盘
            self._loadBuyWheel()
            // self.node.destroy()

            //打点
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_BUYWHEEL_POP)
        };
        let startPos = this.node.convertToNodeSpaceAR(event.target.convertToWorldSpaceAR(cc.v2(0, 0)));
        this.showHallCoin(startPos, callFunc);

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HALL_WHEEL_COLLECT)
    },

    updateNums: function (node, coins, bAction = false, callFunc) {
        let lbl = node.getComponent(cc.Label);
        let curCoin = Global.FormatCommaNumToNum(lbl.string);
        if (bAction && coins >= curCoin) {
            let addCoin = (coins - curCoin) / 100.0;
            node.runAction(cc.repeatForever(cc.sequence(cc.delayTime(0.02), cc.callFunc(() => {
                curCoin += addCoin;
                curCoin = Math.min(curCoin, coins);
                lbl.string = Global.FormatNumToComma(Math.floor(curCoin));
                if (curCoin >= coins) {
                    node.stopAllActions();

                    if (callFunc) callFunc();

                }
            }))));
        }
        else {
            lbl.string = Global.FormatNumToComma(Math.floor(coins));

            node.stopAllActions();
            if (callFunc) callFunc();
        }
    },

    //显示大厅的coin节点，显示飞金币动画
    showHallCoin: function (startPos, callFunc) {
        // let coinNode;
        // if(this.node.getChildByName('spr_coin')){
        //     coinNode = this.node.getChildByName('spr_coin');
        //     coinNode.active = true;
        // }else {
        //     let hall_spr_coin = cc.vv.gameData? cc.find(Global.INGAME_COIN_NODE_PATH):cc.find(Global.HALL_COIN_NODE_PATH);
        //     hall_spr_coin = hall_spr_coin.parent
        //     if (!hall_spr_coin) {
        //         hall_spr_coin = cc.find("Canvas/LMSlots_Top/playerCoins");
        //     }
        //     let spr_coin_pos = this.node.convertToNodeSpaceAR(hall_spr_coin.convertToWorldSpaceAR(cc.v2(0,0)));

        //     coinNode = cc.instantiate(hall_spr_coin);
        //     coinNode.name = 'spr_coin'
        //     coinNode.parent = this.node;
        //     coinNode.position = spr_coin_pos;
        // }

        // let imgCoin = coinNode.getChildByName('spr_coin');
        // let endPos = cc.v2(coinNode.x + imgCoin.x,coinNode.y + imgCoin.y);
        // let lblCoin = coinNode.getChildByName('lbl_coin');

        // let coinPre = cc.instantiate(this.prefab_coin);
        // coinPre.parent = this.node;
        // coinPre.position = cc.v2(0,0);
        // let flyCoins = coinPre.getComponent("FlyCoins");
        // if(flyCoins){
        //     this.updateNums(lblCoin,this._userCoin, true);
        //     flyCoins.showFlyCoins(startPos,endPos,20,callFunc);
        // }
        let starNode = cc.find('lbl_total_bonus', this._node_rewards)
        // this.updateNums(starNode,this._addCoin, true)

        let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        if (cc.vv.gameData) {
            toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
        }

        // let lbl = starNode.getComponent(cc.Label);
        // let curCoin = Global.FormatCommaNumToNum(lbl.string);
        let rollData = {}
        rollData.lblCoin = toLbl
        rollData.addCoin = this._addCoin

        Global.FlyCoin(starNode, endNode, () => {
            if (cc.vv.gameData) {
                cc.vv.gameData.setCoins(this._userCoin, true)

            } else {
                cc.vv.UserManager.AddCoin(this._addCoin, true)
            }
            callFunc()
        }, rollData, true)
    },

    //获取转盘配置
    onRcvGetFreeSpineConf: function (msg) {
        if (msg.code === 200) {
            this._freePrizeData = msg.conf;
            this._vipMultData = msg.vip;
            this._vipMult = msg.vipMult;
            this.initVipNode()
            this.initFreeWheel();
        }
    },

    _loadBuyWheel() {
        let self = this
        let url = 'CashHero/prefab/prize_wheel/prize_wheel_buy'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                let callback = () => {
                    if (cc.isValid(self.node)) {
                        self.node.destroy()
                    }
                }
                node.getComponent('prize_wheel_buy').setCallBack(callback)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },


    //获取转盘结果
    onRcvGetSpineResult: function (msg) {
        if (!cc.isValid(this.node)) {
            return
        }
        if (msg.code === 200) {
            this._freeResultIdx = msg.idx - 1;

            this._nextType = msg.nextType;
            this._nextTime = msg.nextTime;
            this._userCoin = msg.user.coin;
            cc.vv.UserManager.coin = this._userCoin
            if (cc.vv.gameData) {
                cc.vv.gameData.setCoins(this._userCoin)

            }
            if (msg.addCoin) {
                this._addCoin = msg.addCoin;
            }
            if (msg.type2_vip) {
                this._type2_vip = msg.type2_vip;
            }
            if (msg.rank_benefit) {
                this._rank_benefit = msg.rank_benefit;
            }

            this._lunpanMove();
        }

    },

    onDestroy() {
        // cc.vv.EventManager.emit(EventId.NEXT_POP_UI)
        Global.popBgm()
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SPINE_CONF, this.onRcvGetFreeSpineConf, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SPINE_RESULT, this.onRcvGetSpineResult, false, this);
    },

    // update (dt) {},
});
