/**
 * 购买金币成功
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.lblCoin = cc.find('spr_ui_bg/lblCoinNum', this.node)
        let closeBtn = cc.find('spr_ui_bg/btnCollect', this.node)
        Global.btnClickEvent(closeBtn, this.OnClickCollect, this)


    },

    start() {
        Global.playComEff("ch_popup");
    },

    ShowInfo: function (nCoin, bDiamond) {
        this._addCoin = nCoin
        this._bDiamond = bDiamond
        this.lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(nCoin)
        //背景
        let spr_coin = cc.find('spr_ui_bg/spr_coin', this.node)
        spr_coin.active = !bDiamond
        let spr_dia = cc.find('spr_ui_bg/spr_diamond', this.node)
        spr_dia.active = bDiamond

    },

    OnClickCollect: function () {
        let self = this
        Global.playComEff("ch_collect");
        if (this._isPlay) return
        this._isPlay = true
        let callback = function () {
            self.node.destroy()
        }

        if (this._bDiamond) {
            callback()
        }
        else {
            let toNode = cc.find(Global.HALL_COIN_NODE_PATH)
            let lbladd = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
            if (cc.vv.gameData) {
                toNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
                lbladd = toNode
            }
            let rollData = {}
            rollData.lblCoin = lbladd
            rollData.addCoin = this._addCoin
            rollData.begin = cc.vv.UserManager.coin - this._addCoin
            Global.FlyCoin(cc.find("spr_ui_bg/lblCoinNum", this.node), toNode, callback, rollData, true)
        }

    }

    // update (dt) {},
});
