
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find("btn_close", this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)

        let addExp1 = cc.find("btn1", this.node);
        addExp1.on("click", this.onBtnAddExp1, this);
        let addExp2 = cc.find("btn2", this.node);
        addExp2.on("click", this.onBtnAddExp2, this);

        Global.playComEff("ch_popup");
        cc.vv.NetManager.registerMsg(MsgId.REQ_HEROCARD_LEVEL_UP, this.onRcvHeroCardLevelUp, this);//英雄升级
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HEROCARD_LEVEL_UP, this.onRcvHeroCardLevelUp, false, this);
    },

    start() {

    },

    Init: function (cardInfo) {
        this._cardInfo = cardInfo;
        this.showInfo()

        this._bDone117 = true;
        if (cc.vv.NewGuide.GetGuideTempData() == 116) {
            this._bDone117 = cc.vv.NewGuide.ShowGuide(117)
        }
    },

    showInfo: function (cardInfo) {

        cc.find("total", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.HerocardManager.getRemainExp());
        cc.find("lbl_before", this.node).getComponent(cc.Label).string = "Lv." + this._cardInfo.lv;
        cc.find("lbl_after", this.node).getComponent(cc.Label).string = "Lv." + (this._cardInfo.lv + 1);
        cc.find("btn1/lbl_need", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(this._cardInfo.need_exp - this._cardInfo.exp);
        let per = (this._cardInfo.need_exp > 0) ? this._cardInfo.exp / this._cardInfo.need_exp : (this._cardInfo.lv > 0 ? 1 : 0);
        cc.find("ProgressBar", this.node).getComponent(cc.ProgressBar).progress = per;
    },


    onClickClose: function () {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_PLUSEXP_CLOSE, '升级关闭')
        Global.playComEff("ch_close");
        this.node.destroy()
    },

    onBtnAddExp1: function () {
        Global.playComEff("ch_btn_click");
        this._sendAddExpReq()

    },

    onBtnAddExp2: function () {
        Global.playComEff("ch_btn_click");
        this._sendAddExpReq(true)
    },

    _sendAddExpReq: function (bFull) {
        let nHave = cc.vv.HerocardManager.getRemainExp()
        if (nHave > 0) {
            let req = {
                c: MsgId.REQ_HEROCARD_LEVEL_UP,
                cardid: this._cardInfo.cardid,

            };
            if (bFull) {
                req.fullup = 1
            }
            cc.vv.NetManager.send(req);
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_PLUSEXP_ADD1, '升级按钮1')
        }
        else {
            let gameId = this._cardInfo.cfg.gameid
            this.node.destroy()
            //提示
            if (!cc.vv.gameData) {
                let sureCall = function () {
                    cc.vv.UserManager.goSystemUI('entergame', gameId)
                }
                let cancelCall = function () {

                }
                cc.vv.AlertView.show("You don't have encough card exp, go and get more?", sureCall, cancelCall)
            }
            else {
                let sureCall = function () {

                }
                cc.vv.AlertView.showSimple("You don't have encough card exp, spin can get more exp!", sureCall)
            }


        }
    },

    onRcvHeroCardLevelUp: function (msg) {
        if (msg.code == 200) {
            let cardInfo = msg.cardInfo;
            cc.vv.HerocardManager.updateCardInfo(cardInfo);
            this._cardInfo = cc.vv.HerocardManager.getCardInfo(cardInfo.cardid);
            cc.vv.HerocardManager.setRemainExp(msg.remainExp);
            cc.vv.UserManager.setPvpCardExp(msg.remainExp);
            Global.dispatchEvent("HEROCARD_UPDATED", this._cardInfo);

            this.showInfo(cardInfo);

            if (!this._bDone117) {
                Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI, 117);
                this.node.destroy()
                return
            }

            if (cardInfo.exp == 0) {// 升级成功
                // 满级
                if (this._cardInfo.need_exp == 0 && this._cardInfo.lv > 0) {
                    this.node.destroy()
                }
            } else {
                cc.vv.FloatTip.show(cc.vv.Language.herocard_upGrade);//"Not enough experience, need more experience"
                this.node.destroy()
            }
        }
    },

    // update (dt) {},
});
