/**
 * 好友详情
 */
const List = require('CH_List');

let giftSpine = {
    "gift_car": { name: "animation2", scale: 0.2 },
    "gift_evil": { name: "ermodaiji", name2: "ermobao", scale: 1, yOff: -18 },
    "gift_ice": { name: "animation1" },
    "gift_kiss": { name: "animation" },
    "gift_money": { name: "animation2", scale: 0.2 },
    "gift_poker": { name: "animation2" },
    "gift_ring": { name: "animation" },
    "gift_tower": { name: "animation", scale: 0.4, yOff: 18 },
};

cc.Class({
    extends: require('UI_popwin_interface'),


    properties: {
        JPList: List,
        _listdata: [],
        giftAtlas: cc.SpriteAtlas,
        _giftBtnList: [],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('btn_close', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)

        let btnAdd = cc.find('node_recom/playerinfo/btn_add', this.node)
        Global.btnClickEvent(btnAdd, this.onClickAdd, this)

        let btnGift = cc.find('node_recom/tabs/btn_gift', this.node)
        Global.btnClickEvent(btnGift, this.onClickGiftTab, this)
        let btnJackpot = cc.find('node_recom/tabs/btn_jackpot', this.node)
        Global.btnClickEvent(btnJackpot, this.onClickJackpotTab, this)

        for (let i = 1; i <= 8; i++) {
            let btn = cc.find("node_recom/giftList/btn" + i, this.node);
            Global.btnClickEvent(btn, this.onClickGiftBtn, this)
        }

        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvFriendInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GIFT_SEND, this.onRcvGiftSend, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvFriendInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GIFT_SEND, this.onRcvGiftSend, false, this);
    },

    start() {
        // let req = { c: MsgId.PERSIONAL_INFO };
        // req.otheruid = this._otherUid
        // cc.vv.NetManager.send(req);

        this.showDetails(this.itemData)
        this.showJPList(this._listdata)


        this.setNodeActive(this.itemData.uid == cc.vv.UserManager.uid)
        if (this.itemData.uid != cc.vv.UserManager.uid) {
            this.showTab(0);
            this.showGiftNode();
        } else {
        }
    },

    init: function (friendid, msg, target) {
        this._otherUid = friendid
        this.itemData = msg.playerInfo
        this._listdata = msg.jackpotlist
        this._target = target
        // if(msg){


        // }
    },

    showDetails: function (itemData) {
        let self = this
        let nodeInfo = cc.find('node_recom/playerinfo', this.node)
        //设置头像
        var userHeadScript = cc.find("node_head", nodeInfo).getComponent('UserHead');
        let setHeadCall = function (uid, spriteFrameval) {
            if (uid == self._otherUid) {
                userHeadScript.spr_head.spriteFrame = spriteFrameval
            }
        }
        userHeadScript.setHead(itemData.uid, itemData.usericon, setHeadCall);
        //昵称
        let name = itemData.playername
        // if(this.getBLe(name) > 30){
        //     name = itemData.playername.substring(0,30) + ".."
        // }
        cc.find("lblName", nodeInfo).getComponent(cc.Label).string = name;
        //等级
        cc.find("lbl_lv", nodeInfo).getComponent(cc.Label).string = "LV." + itemData.level
        //coin
        cc.find("node_coin/lbl_coin", nodeInfo).getComponent(cc.Label).string = Global.FormatNumToComma(itemData.usercoin || itemData.coin || 0)
        //在线
        let sprOnline = cc.find('node_online/online', nodeInfo)
        sprOnline.active = itemData.isonline
        let sproffline = cc.find('node_online/offline', nodeInfo)
        sproffline.active = !itemData.isonline
        // let des = cc.vv.Language.friend_offline//'offline'
        // let color = new cc.Color(114,145,121);
        // if(itemData.isonline){
        //     des = cc.vv.Language.friend_online//'online'
        //     color = new cc.Color(7,227,55); 
        // }
        // let lblonline = cc.find('node_online/lbl_des',nodeInfo)
        // lblonline.getComponent(cc.Label).string = des
        // lblonline.color = color
        //fb
        cc.find("fb_icon", nodeInfo).active = itemData.fb

        //是否可以加好友
        let btnAdd = cc.find('btn_add', nodeInfo)
        btnAdd.active = !(itemData.friend == 2)
        if (this._otherUid == cc.vv.UserManager.uid) {
            btnAdd.active = false
        }
    },

    showJPList: function (jpdata) {
        this.JPList.numItems = jpdata.length
    },


    onRenderRecomListItem: function (node, itemdata) {
        let data = this._listdata[itemdata]
        if (data) {
            node.active = true
            node.getComponent('CH_FriendsJPListitem').showItemInfo(data)
        }
        else {
            node.active = false
        }
    },

    onRcvFriendInfo: function (msg) {
        if (msg.code == 200) {
            this.itemData = msg.playerInfo
            this._jpList = msg.jackpotlist
            this.showDetails(this.itemData)
            this.showJPList(this._jpList)

            this.setNodeActive(this.itemData.uid == cc.vv.UserManager.uid)
            if (this.itemData.uid != cc.vv.UserManager.uid) {
                this.showTab(0);
                this.showGiftNode();
            } else {
            }
        }
    },

    onClickClose: function () {
        Global.playComEff("ch_btn_click");
        this.node.destroy()
    },

    onClickAdd: function () {
        Global.playComEff("ch_btn_click");
        let btnAdd = cc.find('node_recom/playerinfo/btn_add', this.node)
        btnAdd.active = false

        let req = { c: MsgId.REQ_ADD_FRIENDS };
        req.frienduid = this.itemData.uid;
        req.act = 0;
        cc.vv.NetManager.send(req);
    },

    setNodeActive(bSelf) {
        // cc.find("node_recom/spr_tit",this.node).active = bSelf;
        cc.find("node_recom/tabs", this.node).active = !bSelf;
        cc.find("node_recom/giftList", this.node).active = !bSelf;
    },

    showTab(id = 0) {
        cc.find("node_recom/giftList", this.node).active = id == 0;
        cc.find("node_recom/listview", this.node).active = id == 1;

        cc.find('node_recom/tabs/btn_gift', this.node).getComponent(cc.Button).interactable = id != 0;
        cc.find('node_recom/tabs/btn_gift/Label', this.node).getComponent(cc.LabelOutline).color = id == 0 ? cc.color("#5F0126") : cc.color("#000000");
        cc.find('node_recom/tabs/btn_jackpot', this.node).getComponent(cc.Button).interactable = id != 1;
        cc.find('node_recom/tabs/btn_jackpot/Label', this.node).getComponent(cc.LabelOutline).color = id == 1 ? cc.color("#5F0126") : cc.color("#000000");
    },

    showGiftNode() {
        let charmList = cc.vv.UserManager.getCharmList();

        for (let i = 1; i <= 8; i++) {
            let giftInfo = charmList[i - 1]
            let btn = cc.find("node_recom/giftList/btn" + i, this.node)
            let gift = cc.find("gift", btn);
            // let lbl = cc.find("lbl", btn);
            let id = Global.PROP_ID.COIN
            if (giftInfo.type == 25) {
                id = Global.PROP_ID.DIAMOND
            }
            let coin = cc.find("lay/coin", btn);
            let rewarditem = coin.getComponent("CH_RewardItem")
            if (rewarditem) {
                rewarditem.init(id, giftInfo.count)
            }
            let url = "CashHero/gift/spine/" + giftInfo.img + "/spine"
            Global.loadSpine(url, gift, giftSpine[giftInfo.img].name, true)
            gift.scale = giftSpine[giftInfo.img].scale ? giftSpine[giftInfo.img].scale : 0.3
            let yOff = giftSpine[giftInfo.img].yOff ? giftSpine[giftInfo.img].yOff : 0
            gift.y = 5.6 + yOff
            // gift.getComponent(cc.Sprite).spriteFrame = this.giftAtlas.getSpriteFrame(charmList[i-1].img);
            // lbl.getComponent(cc.Label).string = Global.FormatNumToComma(charmList[i-1].count);
            // coin.active = charmList[i-1].type == 1; //1-金币 25-钻石
            Global.setLabelString('lbl_charm', btn, "+" + giftInfo.charm)

            let bHasTicket = giftInfo.ticket
            coin.active = !bHasTicket
            let lblNum = cc.find("lay/lbl", btn)
            lblNum.x = bHasTicket ? 0 : 17
            let btnText = bHasTicket ? "SEND" : "BUY ONE"
            Global.setLabelString('btn_buy/New Label', btn, btnText)

            if (bHasTicket) {
                lblNum.getComponent(cc.Label).string = "x" + bHasTicket
            }


        }
    },

    onClickGiftTab: function () {
        Global.playComEff("ch_tab");
        this.showTab(0);
    },

    onClickJackpotTab: function () {
        Global.playComEff("ch_tab");
        this.showTab(1);
    },

    onClickGiftBtn: function (event) {
        let self = this
        Global.playComEff("ch_btn_click");
        let node = event.node;
        let btnIdx = node.name.substr(node.name.length - 1, 1);

        let charmList = cc.vv.UserManager.getCharmList();
        this._charmInfo = charmList[btnIdx - 1];
        if (this._charmInfo.ticket > 0) {//有券直接使用，不做二次确认
            let req = {
                c: MsgId.REQ_GIFT_SEND,
                friendid: self.itemData.uid,   //好友uid
                id: self._charmInfo.id,   //道具id
            };
            cc.vv.NetManager.send(req);


        }
        else {
            let bEncough = this._charmInfo.count <= cc.vv.UserManager.coin
            if (bEncough) {
                //确认提示
                cc.vv.AlertView.show(cc.js.formatStr("Send the gift for %s coins right now?", Global.FormatNumToComma(this._charmInfo.count)), () => {
                    let req = {
                        c: MsgId.REQ_GIFT_SEND,
                        friendid: self.itemData.uid,   //好友uid
                        id: self._charmInfo.id,   //道具id
                    };
                    cc.vv.NetManager.send(req);
                    // self.node.destroy()
                }, () => {

                }, false, null, "TIPS")
            }
            else {
                //金币不足

                cc.vv.AlertView.showTips("You don't have enough coins!", () => {
                    self.node.destroy()
                    if (self._target) {
                        self._target.node.destroy()
                    }
                    cc.vv.UserManager.goSystemUI("TabShop", "Coin")
                })
            }

        }


    },

    onRcvGiftSend: function (msg) {
        let self = this
        if (msg.code === 200) {
            if (msg.spcode) {
                if (msg.spcode === 950) {
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_prop_not_exist);
                    // cc.vv.FloatTip.show('prop does not exist');
                } else if (msg.spcode === 804) {
                    // cc.vv.FloatTip.show(cc.vv.Language.float_tip_insufficient_coins);

                    cc.vv.AlertView.show(cc.vv.Language.float_tip_insufficient_coins, () => {
                        this.onClickClose()
                        cc.vv.Shop.show("Shop_Coin");
                    }, () => {

                    })

                } else if (msg.spcode === 819) {
                    cc.vv.AlertView.show(cc.vv.Language.pvp_des5, () => {
                        this.onClickClose()
                        cc.vv.Shop.show("Shop_Diamond");
                    }, () => {

                    })

                }
            } else {
                //成功
                Global.dispatchEvent(EventId.UPATE_DIAMOND);
                Global.dispatchEvent(EventId.UPATE_COINS);

                cc.vv.UserManager.updateCharmlist(msg.ticket)

                self.node.destroy()

            }
        }
    },


    // update (dt) {},
});
