cc.Class({
    extends: cc.Component,

    properties: {
        _data: null,
        _game: null,
        _level: null
    },

    onLoad() {
        Global.FixDesignScale_V(this.node)

        let btnClose = cc.find("top_bg/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        let itemPackage = cc.find("level/top/reward/item_package", this.node)
        itemPackage.on('click', this.showTips, this)

        this._game = cc.find("game", this.node)
        this._level = cc.find("level", this.node)

        cc.vv.NetManager.registerMsg(MsgId.REQ_BINGO_INFO, this.onRcvNetBingoInfo, this)

        let req = { c: MsgId.REQ_BINGO_INFO }
        cc.vv.NetManager.send(req)

        if (cc.vv.gameData && Global.SlotsSoundMgr) {
            Global.SlotsSoundMgr.stopBgm()
        }

        Global.playBgm({ path: 'CashHero/', filename: 'bingo/bgm', common: true })
        if (cc.vv.gameData) cc.vv.gameData.PauseSlot()

        cc.vv.RedSys.clearRedTip(11)

        this._inter = 0             //时间间隔
        this.countData = null    //倒计时数据

        this._curLevel = '1_1'  //当前第几关

        Global.registerEvent(EventId.NEWGUIDE_PRO_UI, this.onEventRefushGuideComp, this)
        Global.registerEvent(EventId.CHANGE_BINGO_EXPLORE, this.onEventBingoChange, this)
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.AudioManager.stopBgm()
            cc.vv.gameData.ResumeSlot()
            cc.vv.QueueWinMrg.startPop()
        } else {
            Global.popBgm()
        }

        cc.vv.NetManager.unregisterMsg(MsgId.REQ_BINGO_INFO, this.onRcvNetBingoInfo, false, this)
    },

    showGameView(data) {
        if (data) {
            cc.vv.UserManager.setBingoFrom(data)
        }
        cc.find("level", this.node).active = false
        cc.find("game", this.node).active = true
    },

    showLevelView(data) {
        if (data) {
            cc.vv.UserManager.setBingoFrom(data)
        }
        cc.find("game", this.node).active = false
        cc.find("level", this.node).active = true
        this.showTips()
    },

    showTips() {
        let tips = cc.find("level/top/tips", this.node)
        tips.stopAllActions()
        tips.runAction(cc.sequence(cc.fadeIn(0.2), cc.delayTime(1.8), cc.fadeOut(0.2)))
    },

    setLabelString(route, node, str) {
        let label = cc.find(route, node)
        if (label) {
            label.getComponent(cc.Label).string = str
        }
    },

    refreshView() {
        let data = this._data
        let difTime = (data.endTime * 1000) - new Date().getTime()
        let leftTime = parseInt(difTime / (24 * 60 * 60 * 1000))
        if (leftTime > 0) {
            let _lanStr = cc.vv.Language['lefttime3']
            if (leftTime >= 2) {
                _lanStr = (leftTime == 2 && Global.language == Global.LANGUAGE.AR) ? cc.vv.Language['lefttime3'] : cc.vv.Language['lefttime4']
            }
            I18N.setI18nLabel(cc.find("top_bg/lbl_time", this.node), _lanStr, leftTime)
            // Global.setLabelString("top_bg/lbl_time", this.node, leftTime+" DAYS LEFT")
        } else {
            let _str = Global.formatSec(difTime / 1000)
            this.countData = Math.floor(difTime / 1000)
            Global.setLabelString("top_bg/lbl_time", this.node, _str)
        }

        //关卡信息
        this.initLevel(data)
        //游戏信息
        this._game.getComponent("Bingo_Game").init(data)
    },

    onRcvNetBingoInfo(msg) {
        if (msg.code == 200) {
            if (msg.isOver == 1) {
                cc.vv.AlertView.showTips("Oops, the game was over", () => {
                    //活动已结束
                    Global.dispatchEvent("BINGO_UPDATED", { isOver: true }) //同步给浮窗
                    this.node.destroy()
                })
            } else {
                this._data = msg
                this.refreshView()
            }
        } else {
            this.node.destroy()
        }
    },

    setStatus(node, status) {
        cc.find("end", node).active = (status == "end")
        cc.find("on", node).active = (status == "on")
        cc.find("locked", node).active = (status == "locked")
    },

    //初始化关卡信息
    initLevel(data) {
        //轮次
        let round = "1ST"
        if (data.roundId == 2) {
            round = "2ND"
        } else if (data.roundId > 2) {
            round = data.roundId + "TH"
        }
        Global.setLabelString("top/lbl_round", this._level, round)

        //奖励信息
        let node = cc.find("top/reward", this._level)
        for (let i = 0; i < data.superReward.length; i++) {
            let reward = data.superReward[i]
            if (reward.type == Global.PROP_ID.COIN) {
                Global.setLabelString("item_coin/lbl_count", node, Global.FormatNumToComma(reward.count))
            } else if (reward.type == Global.PROP_ID.VIP_POINT) {
                Global.setLabelString("item_vip/lbl_count", node, "" + reward.count)
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                Global.setLabelString("item_package/lbl_count", node, "X" + reward.count)
            } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                Global.setLabelString("item_exp/lbl_count", node, reward.count / 3600 + "H")
            }
        }
        //关卡信息
        let content = cc.find("list/view/content", this._level)
        for (let level = 1; level <= 3; level++) {
            let item = cc.find("level" + level, content)
            cc.find("icon/gray", item).active = data.sectionId < level
            cc.find("text_complete", item).active = data.sectionId > level
            cc.find("reward", item).active = data.sectionId <= level
            cc.find("btn_completed", item).active = data.sectionId > level
            cc.find("btn_play", item).active = data.sectionId == level
            cc.find("btn_lock", item).active = data.sectionId < level
            //奖励
            let coin_count = 0
            let package_count = 0
            let vip_count = 0
            let exp_count = 0
            for (let i = 0; i < data.rewards[level - 1].length; i++) {
                let rewards = data.rewards[level - 1][i]
                for (let j = 0; j < rewards.length; j++) {
                    let reward = rewards[j]
                    if (reward.type == Global.PROP_ID.COIN) {
                        coin_count += reward.count
                    } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                        package_count += reward.count
                    } else if (reward.type == Global.PROP_ID.VIP_POINT) {
                        vip_count += reward.count
                    } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                        exp_count += reward.count / 3600
                    }
                }
            }
            Global.setLabelString("reward/item_coin/lbl_count", item, Global.formatNumShort(coin_count, 0))
            Global.setLabelString("reward/item_package/lbl_count", item, "X" + package_count)
            Global.setLabelString("reward/item_exp/lbl_count", item, exp_count + "H")
            Global.setLabelString("reward/item_vip/lbl_count", item, "" + vip_count)
            //小关状态
            if (data.sectionId > level) {
                for (let sub = 1; sub <= 3; sub++) {
                    this.setStatus(cc.find("status/status" + sub, item), "end")
                }
            } else if (data.sectionId == level) {
                Global.setLabelString("btn_play/lbl_count", item, "PLAY TIMES: " + data.point)
                let btnPlay = cc.find("btn_play", item)
                btnPlay.off('click')
                btnPlay.on('click', this.onClickPlay, this)
                for (let sub = 1; sub <= 3; sub++) {
                    if (data.orderId > sub) {
                        this.setStatus(cc.find("status/status" + sub, item), "end")
                    } else if (data.orderId == sub) {
                        this.setStatus(cc.find("status/status" + sub, item), "on")
                        this._curLevel = level + '_' + sub
                    } else {
                        this.setStatus(cc.find("status/status" + sub, item), "locked")
                    }
                }
            } else {
                for (let sub = 1; sub <= 3; sub++) {
                    this.setStatus(cc.find("status/status" + sub, item), "locked")
                }
            }

        }
    },

    nextLevel() {
        this.showLevelView()
        this.refreshView()
    },

    onClickPlay() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_LEVEL_PLAY, cc.vv.UserManager.getBingoFrom() + '|' + this._curLevel)

        Global.playComEff("ch_btn_click")
        this.showGameView()
    },

    onClickClose() {
        Global.playComEff("ch_close")
        if (!this._data) {
            this.node.destroy()
            return
        }
        if (this._game.active == true) {
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_GAME_BACK, cc.vv.UserManager.getBingoFrom())

            this.showLevelView()
            //刷新一下显示次数
            Global.setLabelString("list/view/content/level" + this._data.sectionId + "/btn_play/lbl_count",
                this._level, "PLAY TIMES: " + this._data.point)
        } else {
            Global.dispatchEvent("BINGO_UPDATED", { point: this._data.point, percent: this._data.percent }) //同步给浮窗

            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_LEVEL_BACK, cc.vv.UserManager.getBingoFrom())

            this.node.destroy()
        }

        //从bonus进来
        let _bingoFrom = cc.vv.UserManager.getBingoFrom()
        if (_bingoFrom == 2) {
            Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
        }
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1) {
            this._inter = 0
            if (this.countData > 0) {
                this.countData--
                if (this.countData == 60 || this.countData == 11) {
                    let canvas = cc.find('Canvas')
                    let flag = canvas.getChildByName("bingo_pop")
                    if (!flag) {
                        this.getBingoPop(1)
                    }
                }
                let str = Global.formatSec(this.countData)
                Global.setLabelString("top_bg/lbl_time", this.node, str)

            }
        }
    },

    getBingoPop(flag) {
        cc.loader.loadRes("CashHero/prefab/bingo/bingo_pop", cc.Prefab, (err, prefab) => {
            let canvas = cc.find("Canvas")
            if (!err && !canvas.getChildByName("bingo_pop")) {
                let old = this.node.getChildByName('bingo_pop')
                if (!old) {
                    let node = cc.instantiate(prefab)
                    node.parent = canvas
                    if (flag == 1) {
                        node.getComponent('Bingo_Pop').leftTime(this._data, this.countData)
                    }
                }
            }
        })
    },

    onEventRefushGuideComp: function (data) {
        let val = data.detail
        if (val == 29) {
            Global.dispatchEvent("BINGO_UPDATED", { point: this._data.point, percent: this._data.percent }) //同步给浮窗
            this.node.destroy()
        }
    },

    onEventBingoChange: function () {
        this.node.destroy()
    }
});
