/**
 * 商店-limittime
 */

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        // let _lbl_limit_gift_time = cc.find("timer_bg/lbl_time", this.node).getComponent(cc.Label);
        // _lbl_limit_gift_time.active = false;
        Global.btnClickEvent(this.node, this.onClickGiftLimit, this);
    },

    start() {

    },

    initData: function (data) {
        let self = this
        this._limittime_data = data
        this.discountTime = data.discountTime;

        cc.find("lbl_num", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(data.count);
        // cc.find("lbl_price", this.node).getComponent(cc.Label).string = "Only  $ "+data.amount;
        I18N.setI18nLabel(cc.find("lbl_price", this.node), cc.vv.Language.btn_only, data.amount)
        cc.find("spr_more/lbl_discount", this.node).getComponent(cc.Label).string = data.discount + "%"
        cc.find("lbl_wascoin", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(data.count * 100 / data.discount)

        this._lbl_clock = cc.find("timer_bg/lbl_time", this.node);
        Global.breathNode(this._lbl_clock)
        this.callback = function () {
            self._lbl_clock.getComponent(cc.Label).string = Global.formatSec(this.discountTime);
            if (self.discountTime <= 0) {
                this.unschedule(this.callback);
                //关闭这个活动todo
                Global.dispatchEvent(EventId.CLOSE_LIMIT_TIME_PACK)
            }
            --self.discountTime;
        };
        this.schedule(this.callback, 1)
        self._lbl_clock.getComponent(cc.Label).string = Global.formatSec(this.discountTime);


    },

    //限时优惠
    onClickGiftLimit() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_INBOX_COIN)
        //直接购买
        if (this._limittime_data) {
            let productid = this._limittime_data.id;
            cc.vv.PayMgr.reqPurchaseOrder(productid);
        }

    },

    // update (dt) {},
});
