/**
 * cash hero缓存数据模块
 */
cc.Class({
    extends: require("NetCacheMgr"),

    properties: {
        _cacheBaseList: [],//进入大厅前的缓存数据，少而精。兼顾进入大厅的等待时间

        _popList: [],     //需要弹出断网提示的协议
        _startBaseId: 0,
    },


    init: function () {
        this._curLv = Global.getLocal('userlv', 1) //可能协议2都还没返回
        //初始化基础阶段需要拉取的协议
        this._initBaseList()

        //初始化需要提示断网操作的协议
        this._initPopList()

        //初始化后台慢慢请求的协议
        this._initNormalList()


    },

    //这里配置的协议需要配合逻辑sendAndCache的方式发送协议
    _initBaseList: function () {
        //大厅top3
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.HALL_RANK)
        if (bOpen) {
            let req = { c: MsgId.REQ_HALL_RANKTOP3 };
            req.limit = 3;
            req.sendType = 1 //自己逻辑中有全局的缓存。可以直接发
            this._cacheBaseList.push(req)
        }


        //同步大厅金币
        this._cacheBaseList.push({ c: MsgId.REQ_SYNC_HALLINFO })

        //卡牌列表
        this._cacheBaseList.push({ c: MsgId.REQ_HEROCARD_LIST })

        //获取转盘状态
        this._cacheBaseList.push({ c: MsgId.REQ_GET_TURNTABLE_STATE })

        //好友列表
        this._cacheBaseList.push({ c: MsgId.REQ_FRIENDS_LIST, curPage: 1, recommends: 0 })
        //推荐列表
        this._cacheBaseList.push({ c: MsgId.REQ_RECOMMENDLIST })

        let curLv = this._curLv

        //商品列表
        if (true) {
            var req = { 'c': MsgId.REQ_SHOP_EX };
            req.platform = Global.isIOS() ? 2 : 1
            req.gameid = 0;
            req.posid = Global.SHOP_POS_ID.HALL;
            let reqStr = "1,2,8,14,15,16,25"; //(1商城 2限时优惠one_time_pass 3转盘 4激励礼包 5等级礼包special_offer 6签到 7首充礼包 8onetimeonly 9排行榜时榜 10金猪money_bank 13成长基金 14周卡 15月卡,16春季礼包)，17每日礼包，25钻石 多个类型用逗号隔开

            if (curLv >= (Global.SYS_OPEN.PIG_BANK)) {
                reqStr += ',10'
            }
            if (curLv >= (Global.SYS_OPEN.LUCKY_SMASH)) {
                reqStr += ',17'
            }
            // //目前成长基金先80级开启
            // if(cc.vv.UserManager.isOpen(80)){
            //     reqStr += ',13'
            // }
            req.stype = reqStr

            this._cacheBaseList.push(req)
        }

        //bouns列表
        this._cacheBaseList.push({ c: MsgId.REQ_HALL_TAB_BONUS, online: 1, fb: 1, luckcard: 1, bingo: 1, journey: 1, sign: 1, gametask: 1 })


        //poker
        if (curLv >= Global.SYS_OPEN.HERO_CARD) {
            // this._cacheBaseList.push({c:MsgId.REQ_CARD_ACHIEVE_STATUS})
            this._cacheBaseList.push({ c: MsgId.REQ_HEROCARD_SUMMON })
        }
    },

    _initPopList: function () {
        //领取签到奖励
        this._popList.push(MsgId.REQ_GET_SIGN_ACTION)
        //领取大转盘奖励
        this._popList.push(MsgId.REQ_GET_SPINE_RESULT)
        //领取富豪庭奖励券
        this._popList.push(MsgId.REQ_HEROPALACE_TICKET)
        //领取邮件附件
        this._popList.push(MsgId.REQ_GET_MAIL_ATTACH)
        //一键领取
        this._popList.push(MsgId.REQ_GET_ALL_MALL_ATTACH)
        //支付下单
        this._popList.push(MsgId.PURCHASE_GET_ORDER)
        //抽卡
        this._popList.push(MsgId.REQ_HEROCARD_SUMMON_DIAMOND)
        //离线奖励
        this._popList.push(MsgId.REQ_COLLECT_OFFLINE_REWARD)
        //bonus红点奖励
        this._popList.push(MsgId.REQ_BONUS_REDDOT_REWARDS)
        //



    },

    _initNormalList: function () {
        //排行榜列表
        this._cacheNormalList.push({ c: MsgId.REQ_RANK, type: 6 })
        this._cacheNormalList.push({ c: MsgId.REQ_RANK, type: 1 })
        this._cacheNormalList.push({ c: MsgId.REQ_RANK, type: 2 })
        this._cacheNormalList.push({ c: MsgId.REQ_RANK, type: 3 })
        this._cacheNormalList.push({ c: MsgId.REQ_RANK, type: 7 })
        this._cacheNormalList.push({ c: MsgId.REQ_RANK, type: 5 })
        //Hallpalace
        this._cacheNormalList.push({ c: MsgId.REQ_HEROPALACE })
        //首冲礼包
        this._cacheNormalList.push({ c: MsgId.REQ_SEND_FIRSTGIFT_COLLECT, rtype: 1 })
        //邮件列表
        this._cacheNormalList.push({ c: MsgId.REQ_MAIL_LIST })
        //vip列表
        this._cacheNormalList.push({ c: MsgId.REQ_GET_VIP_INFO })
        //个人信息
        this._cacheNormalList.push({ c: MsgId.PERSIONAL_INFO, otheruid: Global.playerData.uid })
        //每日任务
        if (this._curLv >= Global.SYS_OPEN.DAILYTASK) {
            this._cacheNormalList.push({ c: MsgId.REQ_GET_MISSION_INFO })
        }

        //bouns-主线任务
        this._cacheNormalList.push({ c: MsgId.REQ_BONUS_MAINLISTINFO })


    },

    //overwrite
    isPlayingGame: function () {
        if (cc.vv.gameData) {
            return true
        }
        return false

    },

    //overwrite
    isMsgIdInCacheList: function (msgid) {
        let bIn = false
        for (let i = 0; i < this._cacheBaseList.length; i++) {
            if (this._cacheBaseList[i].c == msgid) {
                bIn = true
                break
            }
        }
        if (!bIn) {
            for (let i = 0; i < this._cacheNormalList.length; i++) {
                if (this._cacheNormalList[i].c == msgid) {
                    bIn = true
                    break
                }
            }
        }
        return bIn
    },

    //overwrite
    isMsgIdNeedPop: function (msgid) {
        let bIn = false
        if (msgid) {
            for (let i = 0; i < this._popList.length; i++) {
                let item = this._popList[i]
                if (item == msgid) {
                    bIn = true
                    break
                }
            }
        }

        return bIn
    },

    /**
     * 大厅的基础消息，需要等消息返回了才能进行下一步（进入大厅）
     */
    loadBasicMsg: function () {
        cc.vv.NetManager.registerNotify(this.onNetBack.bind(this))
        this._startBaseId = 0
        this._sendBase(this._startBaseId)
    },


    loadNormalMsg: function () {

    },

    _sendBase: function (idx) {
        let sendItem = this._cacheBaseList[this._startBaseId]
        if (sendItem) {
            sendItem.cache = 1//区别是提前拉的消息
            let sendType = sendItem.sendType
            delete sendItem.sendType //客户端自己添加的，发消息之前抹掉
            if (sendType == 1) {
                //直接发
                cc.vv.NetManager.send(sendItem, true)
            }
            else {
                cc.vv.NetManager.sendAndCache(sendItem)
            }
        }
        else {
            //告诉大厅的基础数据已经加载完成
            this.setCacheHall(true)
            //已经发送完成
            this.loadNormalMsg()
        }
    },

    onNetBack: function (msgId) {
        let sendItem = this._cacheBaseList[this._startBaseId]
        if (sendItem) {
            if (sendItem.c == msgId) {
                //可以发送下一个
                this._startBaseId++
                this._sendBase(this._startBaseId)
            }
        }
    }


    // update (dt) {},
});
