/**
 * 引导效果控制
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _nodeContent:null,//内容节点
        _nodeRole:null, //角色
        _nodeFinger:null,//手指
        _nodeTouch:null,//屏蔽点击层
        _nodeLayGray:null,//灰色背景
        _nodeLbl:null,//引导文字
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        //文字类型
        this._nodeContentTypeText = cc.find('node_content_text',this.node)
        this._nodeContentTypeText.active = false
        //role+文字
        this._nodeContent = cc.find('node_content',this.node)
        this._nodeContent.active = false

        this._nodeFinger = cc.find('node_finger',this.node)
        this._nodeFinger.active = false

        this._nodeTouch = cc.find('node_touch',this.node)
        Global.btnClickEvent(this._nodeTouch,this.onClickAllScreen,this)
        // this._nodeTouch.active = false

        //跳过按钮
        this._btnSkip = cc.find('btn_skip',this.node)
        this._btnSkip.active = false
        Global.btnClickEvent(this._btnSkip,this.onClickSkip,this)

        this._nodeLayGray = cc.find('lay_bg',this.node)
        this._nodeLayGray.active = false
        this._nodeRole = cc.find('node_role',this._nodeContent)
        this._nodeLbl = cc.find('node_text/text_lbl',this._nodeContent)

        Global.FixDesignScale_V(this.node)
    },

    start () {
        
    },

    init:function(id,cfg){
        this._guideId = id
        this._curCfg = cfg

    },

     ShowUI(){
        let self = this

        let cfg = this._curCfg
        let guideType = cfg.type || 1
        
        
        let nodeCopy = null
        if(cfg.nodePath){ //是否有复制节点
            let copyNodesFirst = cfg.nodePath
            if(Array.isArray(cfg.nodePath)){
                copyNodesFirst = cfg.nodePath[0]
            }

            nodeCopy = cc.find("Canvas/"+copyNodesFirst)
            if(cfg.roleOffset && nodeCopy){
                let copyPos = this._nodeTouch.convertToNodeSpaceAR(nodeCopy.convertToWorldSpaceAR(cc.v2(0,0)))
                if(cfg.roleOffset.x == 0){
                    this._nodeContent.y = copyPos.y + (cfg.roleOffset.y)
                }
                else{
                    this._nodeContent.position = copyPos.add(cfg.roleOffset)
                }
            }
            else if (cfg.roleOffset && !nodeCopy) {
                console.log(">>>> node path not exist: "+cfg.nodePath)
            }
        }
        //引导出现音效
        Global.playCashEff("newguide/guide_show");

        //灰色蒙板
        let bBlockInput =!Global.isBoolean(cfg.blockinput)
        this._nodeLayGray.active = bBlockInput
        let toOpacity = 180
        if(cc.js.isNumber((cfg.opacity))){
            toOpacity = Number(cfg.opacity)
        }
        this._nodeLayGray.opacity = toOpacity
        if(bBlockInput){ //是否屏蔽点击
            this._nodeLayGray.active = true
        }
        else{
            this._nodeTouch.getComponent(cc.Button).enabled = false
            
        }
        //跳过引导
        let bSkip = cfg.skipguides
        this._btnSkip.active = bSkip

        
        if(guideType == 1){ //role+text类型
            let dir = cfg.roleDir || 1
            let lblStr = cc.vv.Language[cfg.lbl]
            if(lblStr){
                I18N.setI18nLabel(this._nodeLbl,cc.vv.Language[cfg.lbl],cfg.lblParm)
            }
            else{
                this._nodeLbl.getComponent(cc.RichText).string = cfg.lbl
            }
            
            this._nodeLbl.scaleX = dir
            this._nodeContent.scaleX = dir
            this._nodeContent.active = true
            //动画出现
            this._rolePos = this._nodeRole.position
            this._nodeRole.x = this._rolePos.x - 300
            cc.tween(this._nodeRole)
            .to(0.3,{position:this._rolePos})
            .start()
            
    
            
            cc.find('node_text/tipbg',this._nodeContent).active = !bBlockInput
            if(bBlockInput){ //是否屏蔽点击
                this._nodeLayGray.opacity = 0
                cc.tween(this._nodeLayGray)
                .to(0.4,{opacity:toOpacity})
                .start()
                
            }
            
            
            //文字提示的背景
            let textBg = cfg.textBg || 1
            cc.find('node_text/bg1',this._nodeContent).active = (textBg == 1)
            cc.find('node_text/bg2',this._nodeContent).active = (textBg == 2)
            
            this._nodeContent.opacity = 0
            cc.tween(this._nodeContent)
            .to(0.4,{opacity:255})
            .start()
        }
        else if(guideType == 2){//文字类型
            this._nodeContentTypeText.active = true
            if(this._curCfg.lblcontentposbasenode){
                let basenode = cc.find('Canvas/'+ this._curCfg.lblcontentposbasenode)
                let copyPos = this.node.convertToNodeSpaceAR(basenode.convertToWorldSpaceAR(cc.v2(0,0)))
                this._nodeContentTypeText.x =copyPos.x + this._curCfg.lblcontentpos.x
                this._nodeContentTypeText.y =copyPos.y + this._curCfg.lblcontentpos.y
            }
            let node_text = cc.find('node_text',this._nodeContentTypeText)
            let lblRich = cc.find('text_lbl',node_text)
            let nmaxW = cfg.lblmaxwidth || 450
            lblRich.getComponent(cc.RichText).maxWidth = nmaxW
            let addBr = ''
            let brNum = this._curCfg.lblcontenbr || 2
            for(let i = 0; i < brNum; i++){
                addBr += '<br/>' 
            }

            let lblStr = cc.vv.Language[cfg.lbl]
            if(lblStr){
                I18N.setI18nLabel(lblRich,cc.vv.Language[cfg.lbl],cfg.lblParm)
            }
            else{
                lblRich.getComponent(cc.RichText).string = cfg.lbl
            }
            lblRich.getComponent(cc.RichText).string = lblRich.getComponent(cc.RichText).string+addBr
            node_text.getComponent(cc.Layout).updateLayout()
            //btnnext
            let btnNext = cc.find('btn_next',this._nodeContentTypeText)
            let nextPos = cc.v2(node_text.x+node_text.width/2,node_text.y-node_text.height/2)
            btnNext.x = nextPos.x-btnNext.width/2 - 15
            btnNext.y = nextPos.y+btnNext.height/2 + 15
            btnNext.active = true
            btnNext.opacity = 0
            cc.tween(btnNext)
            .delay(0.7)
            .to(0.3,{opacity:255})
            .start()
            btnNext.on('click',this.onClickNext,this)
            //arrow箭头显示
            let arrowDirVal = this._curCfg.lblarrowdir
            if(arrowDirVal){
                let sprArrow = cc.find('spr_arrow_'+arrowDirVal,this._nodeContentTypeText)
                sprArrow.active = true
                let xOffset = this._curCfg.lblarrowOffset ? this._curCfg.lblarrowOffset.x : 0
                let yOffset = this._curCfg.lblarrowOffset ? this._curCfg.lblarrowOffset.y : 0
                if(arrowDirVal == "T" || arrowDirVal == "B"){
                    sprArrow.x = node_text.x + xOffset
                    if(arrowDirVal == "T"){
                        sprArrow.y = node_text.y+node_text.height/2 + 13 + yOffset
                    }
                    else{
                        sprArrow.y = node_text.y-node_text.height/2 - 13 + yOffset
                    }
                    
                }
                else{
                    sprArrow.y = node_text.y + yOffset
                    if(arrowDirVal == "R"){
                        sprArrow.x = node_text.x+node_text.width/2 + 15 + xOffset
                    }
                    else{
                        sprArrow.x = node_text.x-node_text.width/2 - 14 + xOffset
                    }
                }
                
                
            }
            
        }
        
        

        if(nodeCopy){ //是否有复制节点
            let copyDelayTime = 0.5
            if(cfg.copyDelayTime){
                copyDelayTime = cfg.copyDelayTime
            }
            cc.tween(this.node)
            .delay(copyDelayTime)
            .call(() =>{
                cc.vv.NewGuide.SetIsLoadingGuide(false)
                let copyNodes = cfg.nodePath
                if(!Array.isArray(cfg.nodePath)){
                    copyNodes = []
                    copyNodes.push(cfg.nodePath)
                }
                for(let i = 0; i < copyNodes.length; i++){
                    //第一个过掉，因为就是nodeCopy
                    if(i > 0){
                        let baseCopy = cc.find("Canvas/"+copyNodes[i])
                        this.copNode(baseCopy)
                        
                        
                    }
                }
                //复制第一个节点，且只有第一个节点是可以点击的
                let copyPos = this._nodeTouch.convertToNodeSpaceAR(nodeCopy.convertToWorldSpaceAR(cc.v2(0,0)))
                let node = this.copNode(nodeCopy)
                
                
                //在复制的节点最上层加一个节点
                if(!cfg.clickall){
                    let newTouchNode = new cc.Node('guideTouchNode')
                    let copyPos = this._nodeTouch.convertToNodeSpaceAR(nodeCopy.convertToWorldSpaceAR(cc.v2(0,0)))
                    newTouchNode.width = node.width
                    newTouchNode.height = node.height
                    newTouchNode.parent = this._nodeTouch
                    newTouchNode.setAnchorPoint(node.getAnchorPoint())
                    newTouchNode.position = copyPos
                    
    
                    // // 测试点击区域
                    // let url = 'common/rewarditem/1'
                    // let sprCm = newTouchNode.addComponent(cc.Sprite)
                    // sprCm.sizeMode = cc.Sprite.SizeMode.CUSTOM
                    // cc.vv.HerocardManager._comloadsprite(url,newTouchNode)
                    
                   
                    
    
                    newTouchNode.once(cc.Node.EventType.TOUCH_END,(event)=>{
                        let eType = cfg.eventType
    
                        node.emit(eType || cc.Node.EventType.TOUCH_END,event)
                        
                        if(eType){
                            let eventNode = nodeCopy
                            if(cfg.eventNode){
                                eventNode = cc.find(cfg.eventNode,nodeCopy)
                                if(!eventNode){
                                    eventNode = cc.find("Canvas/"+cfg.eventNode)
                                }
                            }
                            eventNode.emit(eType,event)
                        }
                        // 通知完成引导
                        cc.vv.NewGuide.SaveCompleteGuide(self._guideId)
                    })
                    // newTouchNode._touchListener.setSwallowTouches(false);
    
                }
                
                //延迟显示手指
                let bShowFinger = cfg.showfinger
                if(!Global.isBoolean(bShowFinger)){
                    bShowFinger = true
                }
                if(bShowFinger){

                    if(cfg.fingerDir == 1 || cfg.fingerDir == -1){
                        this._nodeFinger.scaleX = cfg.fingerDir
                    }
                    else if(cfg.fingerDir == 2 || cfg.fingerDir == -2){
                        this._nodeFinger.angle = cfg.fingerDir*45
                    }
                    else{
                        this._nodeFinger.scaleX = 1
                    }
                    

                    cc.tween(this.node)
                    .delay(0.3)
                    .call(()=>{
                        this._nodeFinger.position =  copyPos.add(cfg.fingerOffset || cc.Vec2.ZERO)
                        this._nodeFinger.active = true
                        
                    })
                    .start()
                }
                
                
            })
            .start()
        }
        else{
            cc.vv.NewGuide.SetIsLoadingGuide(false)
        }

        if(cfg.autoCloseTime){
            cc.tween(this.node)
            .delay(cfg.autoCloseTime)
            .call(() => {
                // 通知完成引导
                cc.vv.NewGuide.SaveCompleteGuide(self._guideId)
            })
            .start()
        }
    },

    copNode:function(baseCopy){
        if(baseCopy){
            let cfg = this._curCfg

            let node = cc.instantiate(baseCopy)
            node.parent = this._nodeTouch
            let copyPos = this._nodeTouch.convertToNodeSpaceAR(baseCopy.convertToWorldSpaceAR(cc.v2(0,0)))
            node.position = copyPos

            if(!cfg.unPlaySpine){//默认都是false,都会播放动画。除非主动设置了
                let spineCmp = node.getComponentsInChildren(sp.Skeleton)
                for(let i = 0; i < spineCmp.length; i++){
                    if(spineCmp[i].findAnimation('animation')){
                        spineCmp[i].setAnimation(1,'animation',true)
                    }
                    
                }
            }
            
            if(cfg.bFitScale){
                node.scale = (node.scale/Global.FixDesignScale_V())/Global.FixDesignScale_V()
            }

            if(cfg.clickall){
                this.unEnableNodeBtnCmp(node)
                
            }

            return node
        }
        else{
            console.log('未找到引导节点：'+copyNodes[i])
        }
    },

    unEnableNodeBtnCmp:function(node){
        let cmps = node.getComponentsInChildren(cc.Button)
        for(let i = 0; i < cmps.length; i++){
            cmps[i].enabled = false
        }

        let blockcmps = node.getComponentsInChildren(cc.BlockInputEvents)
        for(let i = 0; i < blockcmps.length; i++){
            blockcmps[i].enabled = false
        }
    },

    onClickAllScreen:function(){
        if(this._curCfg.clickall){
            // 通知完成引导
            cc.vv.NewGuide.SaveCompleteGuide(this._guideId)
        }
        
    },

    onClickSkip:function(){
        //跳过引导
        cc.vv.NewGuide.SkipTheGuide(this._curCfg.skipguides)
        Global.dispatchEvent(EventId.NEWGUIDE_CLICK_SKIP,this._guideId)
        
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_GUIDE_SKIP,this._guideId)
        
    },

    onClickNext:function(){
        // 通知完成引导
        cc.vv.NewGuide.SaveCompleteGuide(this._guideId)
    },

    CloseUI:function(){
        this.node.destroy()
    },

    update (dt) {
        this._nCount = this._nCount || 0
        this._nCount++
        if(this._nCount == 2){
            this.ShowUI()
        }
    },
});
