
cc.Class({
    extends: cc.Component,

    properties: {
        _bonusId:3,
        _greenId:301,
    },

    Init () {
        this._bonusId = 3;
        this._greenId = 301;

        this._node_bonus = cc.find("safe_node/node_bonus", this.node);
        this._node_bonus.active = false;

        this._topSlotsScript = cc.find('slots_top',this._node_bonus).addComponent('NewMulan_BonusSlots');
        this._bottomSlotsScript = cc.find('slots',this._node_bonus).addComponent('NewMulan_BonusSlots');
        this._topType = 1;
        this._bottomType = 2;
        this._topSlotsScript.Init(this._topType);
        this._bottomSlotsScript.Init(this._bottomType);

        this._slots_top = cc.find("slots_top", this._node_bonus);
        this._slots_bottom = cc.find("slots", this._node_bonus);
        this._node_winKuang = cc.find("node_winKuang", this._node_bonus);
        this._node_top = cc.find("node_top", this._node_bonus);
        this._flyNode = cc.find("flyNode", this._node_bonus);
        this._flyNode.active = false;

        this._poolList = [];
        this._poolList.push(cc.find("LMSlots_PrizePool_1/prizePool_Major", this._node_bonus));
        this._poolList.push(cc.find("LMSlots_PrizePool_1/prizePool_Minor", this._node_bonus));
        this._poolList.push(cc.find("LMSlots_PrizePool_1/prizePool_Mini", this._node_bonus));

        if(!this._symbolTemplete){
            this._symbolTemplete = cc.vv.gameData.GetPrefabByName("bonus_Symbol");
            if(this._symbolTemplete){
                this._symbolTemplete.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE
            }
        }
    },

    // 断线回到bonus游戏
    async showBonusGame(bonusdata, bTri){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playBgm("bgbgm");
            cc.vv.gameData.setIsBonusGame(true);

            cc.find("spr_bg_bonus/BG_BeiJIngLan", this._node_bonus).active = false;
            this.setCurCnt();

            this._subGameData = bonusdata;
            // let state = bonusdata.state;
            if (this._subGameData.state === 1) {  //1代表是商店触发的，需要选择bonus游戏的次数和数量
                await cc.vv.gameData.getPopupScript().showBonusGamePickOneUI();
                this._subGameData = cc.vv.gameData.getBonusGame();

                await cc.vv.gameData.getPopupScript().showBonusStartUI(this._subGameData.type);
                // cc.vv.gameData.getPopupScript().playBonusQPAnim();
                await cc.vv.gameData.awaitTime(0.5);
                cc.vv.gameData.GetBottomScript().SetWin(0);
                await this.showBonusGameUI( bTri);
            } else if (this._subGameData.state === 2) { //2: spin完之后，选择额外spin次数
                await this.showBonusGameUI( bTri);

                await cc.vv.gameData.getPopupScript().showBonusAddSpinsUI();
                this._subGameData = cc.vv.gameData.getBonusGame();

                this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
                this._totalCnt = this._subGameData.totalSpinCnt;

            } else if (this._subGameData.state === 0) { //0: 正常bonus游戏,
                await this.showBonusGameUI( bTri);
            }

            // 开始旋转
            this.reqSpine();

            this._callBack = success;
        })
    },

    // 结束bonus游戏
    async endBonusGame(){
        Global.SlotsSoundMgr.playEffect("bgend");
        await cc.vv.gameData.awaitTime(0.5);

        AppLog.log('###bonus游戏结束');

        cc.find("spr_bg_bonus/BG_BeiJIngLan", this._node_bonus).active = true;
        this.setCurCnt();
        this.setSettleNum();
        await cc.vv.gameData.awaitTime(1);

        await this.showBonusSettlement();
        await cc.vv.gameData.getPopupScript().showGameWinUI(this._subGameData.winCoin, true);

        // cc.vv.gameData.GetBottomScript().ShowFreeModel(false)
        this._node_bonus.active = false;
        this.playJackpotAnim(false);

        await cc.vv.gameData.awaitTime(1);

        // 赢钱
        await new Promise((sucess, failed)=> {
            let nWin = this._subGameData.winCoin;
            let nTotal = this._subGameData.winCoin;
            if ( cc.vv.gameData.isFreeGame() ) {
                nTotal = cc.vv.gameData.getFreeWinCoin() + this._subGameData.winCoin

                cc.vv.gameData.setFreeWinCoin(nTotal)
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin, nTotal, false, function () {
                    sucess()
                });
            } else {
                cc.vv.gameData.AddCoin(this._subGameData.winCoin);
                cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin, nTotal, true, function () {
                    sucess()
                });
            }
        });

        if(this._callBack){
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.gameData.setIsBonusGame(false);

            this._callBack();
            this._callBack = null;
            this._subGameData = null;
        }

        if(cc.vv.gameData.isBoxGame() && !cc.vv.gameData.isFreeGame()){
            cc.vv.gameData.getBoxScript().openStorePage();
            cc.vv.gameData.setIsBoxGame(false)
        }
    },

    // 显示bonus游戏  bTri-触发
    async showBonusGameUI( bTri){
        return new Promise(async(success, failed)=>{
            this._node_bonus.active = true;
            this.lockJackpot(this._subGameData.jackpotValues);
            this.playJackpotAnim(true);

            this._totalCnt = this._subGameData.totalSpinCnt;
            this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
            // cc.vv.gameData.GetBottomScript().ShowFreeModel(true,this._curCnt,this._totalCnt)

            await cc.vv.gameData.awaitTime(0);
            this._bonusType = this._subGameData.type;

            if(bTri){   // 触发 --触发动画
                // await this.showTriAnim(this._bonusType);
                this.setCurCnt();
                this.setTriggerNum();
                this.setSlotsLockSpr(false);
                if(this._bonusType == 2){
                    await this.playDoubleTriAnim();
                } else {
                    await this.playOneTriAnim();
                }
                this.setCurCnt(this._curCnt, this._totalCnt);

                await cc.vv.gameData.awaitTime(1);
            } else {
                this.setCurCnt(this._curCnt,this._totalCnt);
                this.setTriggerNum(this._subGameData.baseCoin);
                this.setSlotsLockSpr(this._bonusType == 1);
                await this.showBonusSlotsUI();
            }

            success();
        })
    },

    // 两个卷轴的触发动画
    async playDoubleTriAnim(){
        return new Promise(async(success, failed) => {
            // this._slots_top.position = this._slots_bottom.position;
            this._bottomSlotsScript.setAllSymbolNull();
            this._topSlotsScript.setAllSymbolNull();

            this._node_winKuang.position = this._slots_top.position;
            this._node_winKuang.active = true;

            let kuang1 = cc.find("NG_BG_panmian", this._slots_top).getComponent(sp.Skeleton);
            let reelback = cc.find("node_reelback", this._slots_top);
            let kuang2 = cc.find("NG_BG_panmian", this._slots_bottom).getComponent(sp.Skeleton);
            kuang1.node.active = false;
            reelback.active = false;
            kuang2.setAnimation(0,"NG_panmian",false);
            Global.SlotsSoundMgr.playEffect("bgaddselect");

            await cc.vv.gameData.awaitTime(1);
            await this.playStartSymbolAnim(this._subGameData.slots[1].bonusItems,false);

            // this.playSettleTriSymbol();
            await this.collectSlotsCoin(false, this._bottomType,0);

            kuang1.node.active = true;
            kuang2.setAnimation(0,"NG_panmian2",false);
            kuang1.setAnimation(0,"BG_panmian_intro",false);
            cc.tween(this._node_winKuang).to(1, {position:cc.find("pos_settle",this._node_bonus).position}).start();

            await cc.vv.gameData.awaitTime(1);
            reelback.active = true;

            await this.playStartSymbolAnim(this._subGameData.slots[0].bonusItems, true);

            success();
        });
    },

    // 一个卷轴的触发动画
    async playOneTriAnim(){
        return new Promise(async(success, failed) => {
            // this._slots_top.position = this._slots_bottom.position;
            this.setSlotsLockSpr(false);
            this._bottomSlotsScript.setAllSymbolNull();
            this._topSlotsScript.setAllSymbolNull();
            this._subGameData.slots[1].bonusItems.forEach(item=>{
                this.showSymbolNormalAnim(item, false);
            })

            this._node_winKuang.position = this._slots_top.position;
            this._node_winKuang.active = true;

            let kuang1 = cc.find("NG_BG_panmian", this._slots_top).getComponent(sp.Skeleton);
            let reelback = cc.find("node_reelback", this._slots_top);
            let kuang2 = cc.find("NG_BG_panmian", this._slots_bottom).getComponent(sp.Skeleton);
            kuang1.node.active = false;
            reelback.active = false;
            kuang2.setAnimation(0,"NG_panmian",false);

            await cc.vv.gameData.awaitTime(0.5);

            kuang1.node.active = true;
            kuang2.setAnimation(0,"NG_panmian2",false);
            kuang1.setAnimation(0,"BG_panmian_intro",false);
            cc.tween(this._node_winKuang).to(1, {position:cc.find("pos_settle",this._node_bonus).position}).start();
            Global.SlotsSoundMgr.playEffect("bgaddselect");

            await cc.vv.gameData.awaitTime(1);
            this.setSlotsLockSpr(true);
            await this.collectSlotsCoin(false, this._bottomType,0);

            await cc.vv.gameData.awaitTime(0.5);
            reelback.active = true;

            success();
        });
    },

    // 初始显示slots
    async showBonusSlotsUI(){
        return new Promise(async(success, failed) => {
            this._bottomSlotsScript.setAllSymbolNull();
            this._topSlotsScript.setAllSymbolNull();


            this._node_winKuang.position = cc.find("pos_settle",this._node_bonus).position;
            this._subGameData.slots[1].bonusItems.forEach(item=>{
                this.showSymbolNormalAnim(item, false);
            })
            if(this._bonusType == 2) {
                this._subGameData.slots[0].bonusItems.forEach(item => {
                    this.showSymbolNormalAnim(item, true);
                })
            }

            await cc.vv.gameData.awaitTime(2);

            success();
        });
    },

    // 显示symbol
    showSymbolNormalAnim(data, isTop){
        let slots = isTop ? this._topSlotsScript : this._bottomSlotsScript;
        let symbol = slots.GetSymbolByIdx(data.idx);
        symbol.ShowById(data.super?this._greenId:this._bonusId, {bonus:data});
        symbol.playBonusIdleAnim(true);
    },

    // 商店获得的bonus游戏，bonus节点放置到顶层时的触发动画   isTop-是否是上面卷轴
    playStartSymbolAnim(bonusItems,isTop) {
        return new Promise(async (success, failed) => {
            bonusItems = this.sortItems(bonusItems);

            for (let i = 0; i < bonusItems.length; i++) {
                let col = bonusItems[i].idx - 1;
                let coin = bonusItems[i].coin;
                let jp = bonusItems[i].jackpot;

                if(isTop){
                    let symbol = this._topSlotsScript.GetSymbolByIdx(bonusItems[i].idx)

                    let flyNode = cc.instantiate(this._flyNode);
                    flyNode.parent = this._node_top;
                    flyNode.active = true;

                    let startNode = this._bottomSlotsScript.GetSymbolByIdx(bonusItems[i].idx).node;
                    flyNode.position = this._node_top.convertToNodeSpaceAR(startNode.convertToWorldSpaceAR(cc.v2(0,0)));
                    // let endPos = this._node_top.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));

                    Global.SlotsSoundMgr.playEffect("chipadd");
                    flyNode.getComponent(sp.Skeleton).setAnimation(0, "Coin_fly", false);
                    flyNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
                        flyNode.destroy();
                    });
                    cc.tween(flyNode)
                        .delay(1.6)
                        .call(()=>{
                            symbol.ShowById(bonusItems[i].super?this._greenId:this._bonusId, {bonus:bonusItems[i]});
                            symbol.playBonusStopAnim();
                        })
                        .start();

                }else {
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(bonusItems[i].idx)
                    symbol.ShowById(bonusItems[i].super?this._greenId:this._bonusId, {bonus:bonusItems[i]});
                    // symbol.playBonusQuanAnim(true);
                    // symbol.playBonusZoomAnim(true);
                    symbol.playBonusStopAnim();
                }

                await cc.vv.gameData.awaitTime(0.2);
            }

            await cc.vv.gameData.awaitTime(isTop?2:0.5);
            success();
        })
    },


    // 获得新的绿色宝石
    gainNewGreenGem() {
        return new Promise(async (success, failed) => {
            let spine_fire = cc.find("path_fire", this._node_bonus);
            for (let i = 0; i <= 1; i++){
                let items = this._subGameData.slots[i].bonusItems;
                let slots = i===0 ? this._topSlotsScript : this._bottomSlotsScript;
                for (let j = 0; j < items.length; j++){
                    let symbol = slots.GetSymbolByIdx(items[j].idx);
                    if(items[j].super && !symbol.GetData().bonus){

                        let sPos = this._node_bonus.convertToNodeSpaceAR(this._node_winKuang.convertToWorldSpaceAR(cc.v2(0,0)));
                        let ePos = this._node_bonus.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));

                        this.playFireSpine(spine_fire, sPos, ePos);

                        await cc.vv.gameData.awaitTime(0.5);
                        symbol.ShowById(this._greenId, {bonus:items[j]});
                        symbol.playBonusIdleAnim(true);
                    }
                }
            }

            success()
        })
    },

    // 触发框
    setTriggerNum(num){
        cc.find("settle", this._node_winKuang).active = false;
        cc.find("trigger", this._node_winKuang).active = true;
        cc.find("trigger/lbl_win", this._node_winKuang).getComponent(cc.Label).string = num?Global.FormatNumToComma(num):"";
    },

    // 结算框
    setSettleNum(num){
        cc.find("trigger", this._node_winKuang).active = false;
        cc.find("settle", this._node_winKuang).active = true;
        cc.find("settle/lbl_win", this._node_winKuang).getComponent(cc.Label).string = num?Global.FormatNumToComma(num):"";
    },
    getCurSettleNum(){
        let str = cc.find("settle/lbl_win", this._node_winKuang).getComponent(cc.Label).string;
        return Global.FormatCommaNumToNum(str);
    },

    playWinEff(bPlay){
        let node = cc.find("BG_JinBiTiShi", this._node_winKuang);
        if(bPlay){
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0,"BG_JinBiTiShi",false);
            node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                node.active = false;
            })
        } else {
            node.active = false;
        }
    },

    // 当前局次
    setCurCnt(cur, total){
        let node = cc.find("InfoBackground1", this._node_winKuang);
        if(total){
            node.active = true;
            cc.find("cur", node).getComponent(cc.Label).string = cur;
            cc.find("total", node).getComponent(cc.Label).string = total;
        } else {
            node.active = false;
        }
    },

    setSlotsLockSpr(bShow){
        cc.find('DiJieSuo',this._node_bonus).active = bShow;
    },

    playFireSpine(node, sPos, ePos){
        Global.SlotsSoundMgr.playEffect("collectprize");
        let temp = cc.v2(sPos.x, sPos.y).sub(cc.v2(ePos.x, ePos.y));
        let length = temp.mag();
        let angle = temp.signAngle(cc.v2(1, 0));
        node.position = sPos;
        node.scale = length > 400 ? length/610 : length/280;
        node.angle = -angle * cc.macro.DEG + 90;
        node.getComponent(sp.Skeleton).setAnimation(0,length > 400 ? "b_fire" : "s_fire",false);
    },

    //展示bonus结算coin效果
    showBonusSettlement(){
        return new Promise(async (success, failed) => {
            let slots = this._subGameData.slots;
            let curtotal = 0;
            if(this._subGameData.type == 2){
                await this.collectSlotsCoin(true,this._topType,curtotal);
                curtotal = this.getCurSettleNum();
            }
            await this.collectSlotsCoin(true,this._bottomType,curtotal);
            await cc.vv.gameData.awaitTime(1);

            success();
        });
    },

    //收集一个slots的当前金币
    // bSettle-是否最终结算 s_type-slot curtotal-当前已有的金币
    collectSlotsCoin(bSettle, s_type, curtotal){
        return new Promise(async(success)=> {
            let slots = s_type === 1 ? this._topSlotsScript : this._bottomSlotsScript;
            let items = this.sortItems(this._subGameData.slots[s_type-1].bonusItems);
            let isDouble = items.length === 15;// 集满了，需要飞特效两次，结果为双倍

            let spine_fire = cc.find("path_fire", this._node_bonus);
            let spine_fire_2 = cc.find("path_fire_2", this._node_bonus);
            spine_fire_2.active = false;

            for (let i = 0; i < items.length; i++){
                let idx = items[i].idx;
                let symbol = slots.GetSymbolByIdx(idx);

                let sPos = this._node_bonus.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                let ePos = this._node_bonus.convertToNodeSpaceAR(this._node_winKuang.convertToWorldSpaceAR(cc.v2(0,0)));

                this.playFireSpine(spine_fire, sPos, ePos);
                if(isDouble){   // 集满，双倍，飞两次
                    await cc.vv.gameData.awaitTime(0.2);
                    spine_fire_2.active = true;
                    this.playFireSpine(spine_fire_2, sPos, ePos);
                }

                if(bSettle){
                    symbol.playBonusEndAnim();  // 结算-清楚图标上光效

                    // 结算金币
                    if(items[i].coin){
                        curtotal += items[i].coin;
                    } else if(items[i].jackpot){
                        curtotal += items[i].jackpot.value;
                        Global.SlotsSoundMgr.playEffect("JPcount");
                    }

                    if(isDouble){
                        await cc.vv.gameData.awaitTime(0.3);
                        this.setSettleNum(curtotal);
                        if(items[i].coin){
                            curtotal += items[i].coin;
                        } else if(items[i].jackpot){
                            curtotal += items[i].jackpot.value;
                        }
                        await cc.vv.gameData.awaitTime(0.2);
                    } else {
                        await cc.vv.gameData.awaitTime(0.5);
                    }

                    this.setSettleNum(curtotal);
                    this.playWinEff(true);
                    await cc.vv.gameData.awaitTime(0.5);
                    if(items[i].jackpot){
                        await cc.vv.gameData.getPopupScript().showWinJpUI(items[i].jackpot.id,items[i].jackpot.value)
                    }
                } else {
                    // 结算金币
                    if(items[i].coin){
                        curtotal += items[i].coin;
                    } else if(items[i].jackpot){
                        curtotal += items[i].jackpot.value;
                    }
                    await cc.vv.gameData.awaitTime(0.5);
                    this.setTriggerNum(curtotal);
                    this.playWinEff(true);
                    await cc.vv.gameData.awaitTime(0.5);
                }
            }

            success();
        });
    },

    //奖池锁定(停止滚动)
    lockJackpot(jackpotvalus){
        let prizepool = cc.find('LMSlots_PrizePool_1',this._node_bonus).getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:jackpotvalus[0]},{prizeType:1,pauseNum:jackpotvalus[1]},
            {prizeType:2,pauseNum:jackpotvalus[2]},{prizeType:3,pauseNum:jackpotvalus[3]}]);
    },


    // 奖池动画
    playJackpotAnim(bPlay){
        let moveT = 0.8;
        let delayT = 2.5;
        for (let i = 0; i < this._poolList.length; i++){
            if(bPlay){
                this._poolList[i].opacity = 0;
                cc.tween(this._poolList[i])
                    .delay(i*(2*moveT + delayT))
                    .repeatForever(cc.tween()
                        .to(moveT, {opacity:255})
                        .delay(delayT)
                        .to(moveT, {opacity:0})
                        .delay((2*moveT + delayT) *2)
                    )
                    .start()
            }
            else {
                this._poolList[i].stopAllActions();
                this._poolList[i].opacity = 0;
            }
        }
    },

    //点击开始移动
    startSpin(){

    },

    //显示结果
    showSpinResult(){

    },

    //旋转停止
    spinEnd(){
        
    },

    //bonus游戏旋转结果请求
    async reqSpine(){
        cc.log(cc.js.formatStr("startMove:%s, %s", this._curCnt, this._totalCnt));

        this._curCnt += 1
        this.setCurCnt(this._curCnt,this._totalCnt);

        if(this._bonusType == 2){
            this._topSlotsScript.StartMove(this._subGameData.slots[0].bonusIdxs);
        }
        this._bottomSlotsScript.StartMove(this._subGameData.slots[1].bonusIdxs);

        await cc.vv.gameData.awaitTime(1);
        let reqdata = {rtype:3};
        let msg = await cc.vv.gameData.reqSubGame(reqdata);
        if(msg.code === 200 && !msg.spcode){
            this._subGameData = msg.data.bonusGame;
            cc.vv.gameData.setBonusGame(this._subGameData);

            this._bottomSlotsScript.setSpinResult(this._subGameData.slots[1].bonusIdxs, this._subGameData.slots[1].bonusItems);
            if(this._bonusType == 2){
                this._topSlotsScript.setSpinResult(this._subGameData.slots[0].bonusIdxs, this._subGameData.slots[0].bonusItems);
            }
        }
    },

    //点击停止按钮调用
    StopMove:function(){
        if(this._bonusType == 2) {
            this._topSlotsScript.StopMove();
        }
        this._bottomSlotsScript.StopMove();
    },

    async OnSpinEnd(){
        cc.log("OnSpinEnd")

        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");

        // 有新的绿色宝石
        await this.gainNewGreenGem();

        await cc.vv.gameData.awaitTime(1);
        if(this._subGameData.state == 2){
            //state未表示需要添加spin界面
            await cc.vv.gameData.getPopupScript().showBonusAddSpinsUI();
            this._subGameData = cc.vv.gameData.getBonusGame();

            this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
            this._totalCnt = this._subGameData.totalSpinCnt;
            this.reqSpine();
        }else{
            //此处进入bonus游戏后 不会调用
            if(this._subGameData.spinCnt > 0){
                cc.vv.gameData.awaitTime(1);
                this.reqSpine();
            }else{
               this.endBonusGame();
            }
        }
    },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        let topEndIdx = this._topSlotsScript.GetLastStopReelIdx();
        let bottomEndIdx = this._bottomSlotsScript.GetLastStopReelIdx();

        let lastIdx = bottomEndIdx;
        let stopType = this._bottomType;
        if(this._bonusType == 2){   // 2个卷轴
            lastIdx = bottomEndIdx ? bottomEndIdx : topEndIdx;
            stopType = bottomEndIdx ? this._bottomType : this._topType;
        }

        return {slotType:stopType, reelIdx:lastIdx};
    },

    getMaxReelIdx(type, col){
        let reelList = type == this._topType ? this._topSlotsScript.getLastStopReel() : this._bottomSlotsScript.getLastStopReel();
        return reelList[col];
    },


    // 按上->下，左->右的顺序排序
    sortItems(items){
        items.sort(function (a, b) {
            return a.idx / 5 - b.idx / 5
        }).sort(function (a, b) {
            return (a.idx - 1) % 5 - (b.idx - 1) % 5
        });

        return items;
    },


    getBonusType(){
        return this._bonusType;
    },

});
