/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _topMoveNode: null,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() { },

    ShowById: function (id, data) {
        this._super(id, data)
        this.clearTopMoveNode()
    },

    SetSymbolIdx: function (idx) {
        this._symbolIdx = idx;
        if (this._id === 2) {
            this.node.zIndex = 150 - idx;
        } else {
            this.node.zIndex = 100 - idx;
        }
    },

    showTopMove() {
        if (this._id === 3) {
            this._topMoveNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("queenTopMove"))
            let worldpos = this.node.convertToWorldSpaceAR(cc.v2(0, 0))
            let localpos = cc.vv.gameData.GetSlotsScript()._topMove.convertToNodeSpaceAR(worldpos)
            this._topMoveNode.position = localpos
            this._topMoveNode.parent = cc.vv.gameData.GetSlotsScript()._topMove
            for (let i = 0; i < this._topMoveNode.children.length; i++) {
                const child = this._topMoveNode.children[i];
                child.active = false
            }
            cc.find("s14", this._topMoveNode).active = true
            cc.find("fire", this._topMoveNode).active = true
        }
    },

    update(dt) {
        if (this._topMoveNode) {
            let worldpos = this.node.convertToWorldSpaceAR(cc.v2(0, 0))
            let localpos = cc.vv.gameData.GetSlotsScript()._topMove.convertToNodeSpaceAR(worldpos)
            this._topMoveNode.position = localpos
        }
    },

    clearTopMoveNode() {
        if (cc.isValid(this._topMoveNode)) {
            this._topMoveNode.parent = null
            this._topMoveNode = null
        }
    },

    //开始回弹动作之前
    StopMoveBefore() {
        this.clearTopMoveNode()
    },

    StartMove: function () {
        this._super()
        this.clearTopMoveNode()
        this.stayKuang()
        this.clearKuang()
    },

    clearKuang() {
        let id = this._id
        if (id !== 1 && id !== 101) {
            return
        }
        if (this._symbolIdx > 4) {  //大于4是多出来的节点
            return
        }
        let cfg = cc.vv.gameData.getGameCfg()
        let idx = (cfg.row - this._symbolIdx - 1) * cfg.col + this._reelIdx + 1
        if (cc.vv.gameData.GetSlotsScript().isStaticKuang(idx)) {
            return
        }
        cc.vv.gameData.getStayKuang().hideKuang([idx])
    },

    //将框留在卷轴上
    stayKuang() {
        if (this._id !== 3) {
            return
        }
        if (this._symbolIdx > 4) {  //大于4是多出来的节点
            return
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        let idx = (cfg.row - this._symbolIdx - 1) * cfg.col + this._reelIdx + 1
        if (cc.vv.gameData.getStayKuang().findKuang(idx)) {
            return
        }
        if (idx === 1 || idx === 3 || idx === 5) {
            return
        }
        cc.vv.gameData.GetSlotsScript().playFrameAppear()
        let cloneNode = cc.instantiate(cc.vv.gameData.GetPrefabByName("queenTopMove"))
        let wordPos = this.node.convertToWorldSpaceAR(cc.v2(0.0));
        cloneNode.parent = this._topAniNode
        cloneNode.position = this._topAniNode.convertToNodeSpaceAR(wordPos)
        for (let i = 0; i < cloneNode.children.length; i++) {
            const element = cloneNode.children[i];
            element.active = false
        }
        if (cfg.symbol[id] && cfg.symbol[id].changekuang_ani) {
            let animationNode = cc.find(cfg.symbol[id].win_node, cloneNode)
            animationNode.active = true
            let animationNodeSp = animationNode.getComponent(sp.Skeleton)
            animationNodeSp.setAnimation(0, cfg.symbol[id].changekuang_ani.name, false)
            animationNodeSp.setCompleteListener(() => {
                cloneNode.parent = null
                animationNodeSp.setCompleteListener(null)
            })
            cc.vv.gameData.getStayKuang().showKuang(idx)
        }
    },

    //女皇变wild
    changeWild() {
        if (this._id !== 3) {
            return
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (this._showNode) {
            this._showNode.active = false
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
            if (cfg.symbol[id] && cfg.symbol[id].changewild1_ani) {
                let animationNode = cc.find(cfg.symbol[id].win_node, aniNode)
                animationNode.active = true
                let animationNodeSp = animationNode.getComponent(sp.Skeleton)
                animationNodeSp.setAnimation(0, cfg.symbol[id].changewild1_ani.name, false)
                animationNodeSp.addAnimation(0, cfg.symbol[id].changewild1_ani.name2, false)
                let num = 0
                animationNodeSp.setCompleteListener(() => {
                    num++
                    if (num === 2) {
                        this.setAnimationToTop(false)
                        this.ShowById(1)
                        let tempNode = this.setAnimationToTop(true)
                        tempNode.active = true
                        animationNodeSp.setCompleteListener(null)
                    }
                })
            }
        } else {
            if (cfg.symbol[id] && cfg.symbol[id].changewild2_ani) {
                let animationNode = cc.find(cfg.symbol[id].win_node, aniNode)
                animationNode.active = true
                let animationNodeSp = animationNode.getComponent(sp.Skeleton)
                animationNodeSp.setAnimation(0, cfg.symbol[id].changewild2_ani.name, false)
                animationNodeSp.addAnimation(0, cfg.symbol[id].changewild2_ani.name2, false)
                let num = 0
                animationNodeSp.setCompleteListener(() => {
                    num++
                    if (num === 2) {
                        this.setAnimationToTop(false)
                        this.ShowById(101)
                        let tempNode = this.setAnimationToTop(true)
                        tempNode.active = true
                        animationNodeSp.setCompleteListener(null)
                    }
                })
            }
        }
    },

    //裂变wild
    changeWildEx() {
        if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
            this.ShowById(1)
        } else {
            this.ShowById(101)
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani) {
            this._state = "stop";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true

            if (cfg.symbol[id].stop_ani.name != "") {
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].stop_ani.name, false)
                    nodeSp.setCompleteListener(() => {
                        nodeSp.setCompleteListener(null)
                    })
                }
            }
        }
    },

    changeWildFast() {
        if (this._id !== 3) {
            return
        }
        if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
            this.ShowById(1)

        } else {
            this.ShowById(101)
        }
        let tempNode = this.setAnimationToTop(true)
        tempNode.active = true
    },

    changeWildExFast() {
        if (!cc.vv.gameData.GetSlotsScript()._isSuperBonusGame) {  //判断是不是收集游戏
            this.ShowById(1)

        } else {
            this.ShowById(101)
        }
        let tempNode = this.setAnimationToTop(true)
        tempNode.active = true
    },

    //停止回弹之后
    StopMoveEnd() {
        if (this._id !== 2) {
            return
        }
        if (this._symbolIdx > 4) {  //大于4是多出来的节点
            return
        }
        let cfg = cc.vv.gameData.getGameCfg()
        let idx = (cfg.row - this._symbolIdx - 1) * cfg.col + this._reelIdx + 1
        if (idx === 1 || idx === 3 || idx === 5) {
            return
        }
        if (cc.vv.gameData.getStayKuang().findKuang(idx)) {
            cc.vv.gameData.GetSlotsScript().playScatterLanding()
            this.playStopAnimation()
        }
    },

    //重写
    //停止动画
    playStopAnimation() {
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani) {
            this._state = "stop";
            if (this._showNode) {
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
            topShowNode.active = true
            if (cfg.symbol[id].stop_ani.name != "") {
                aniNode.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if (nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].stop_ani.name, false)
                }
            }
        }
    },

    //显示随机符号
    ShowRandomSymbol_scatter: function () {
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1, cfg.randomSymbols_scatter.length)
        let randVal = cfg.randomSymbols_scatter[randIdx - 1]
        this.ShowById(randVal)
    },
    
    //显示随机符号
    ShowRandomSymbol_bonus: function () {
        let cfg = cc.vv.gameData.getGameCfg()
        let randIdx = Global.random(1, cfg.randomSymbols_bonus.length)
        let randVal = cfg.randomSymbols_bonus[randIdx - 1]
        this.ShowById(randVal)
    },
});
