/**
 * benifist 按钮
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _rewardDatas: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

        Global.btnClickEvent(this.node, this.onClickBtn, this)
    },

    start() {

    },

    showBenifist: function (reward, msg) {
        this._rewardDatas = reward

        this._msg = msg ? msg : ''
    },

    onClickBtn: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BENEFITS_CLICK, this._msg)

        if (this._rewardDatas) {
            cc.loader.loadRes("CashHero/prefab/benifits_pop", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let canvas = cc.find("Canvas");
                    if (canvas && !canvas.getChildByName('benifits_pop')) {
                        let node = cc.instantiate(prefab);
                        node.parent = canvas;
                        node.getComponent('CH_Benifits_pop').showBenifist(this._rewardDatas, this._msg)
                    }
                }
                else {
                    console.log('未找到资源')

                }
            });
        }

    },

    // update (dt) {},
});
