/**
 * 等级礼包
 */
cc.Class({
    extends: require('UI_popwin_interface'),


    properties: {
        _purchaseData: null,  //充值数据
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, this);
        cc.vv.NetManager.registerMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, this);
        // //横竖屏适配
        // let canvasNode = cc.find('Canvas');
        // if (canvasNode) {
        //     let width = canvasNode.width;
        //     let ui = this.node.getChildByName("node_center");
        //     let ui_width = ui.width + 60;
        //     if (width < ui_width) {
        //         ui.setScale(width/ui_width);
        //     }
        // }
        // Global.FixDesignScale_V(this.node)
        Global.playComEff("ch_popup_l2");
    },

    start() {
        //请求协议
        var req = { 'c': MsgId.REQ_SHOP };
        req.uid = Global.playerData.uid;
        req.stype = 5
        cc.vv.NetManager.send(req);
        // Global.showAlertAction(this.node,true,0.1,this.node.scale,null)
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SPECIALOFFER_POP)
    },

    // getDesignSpaceX() {
    //     return 180;
    // },

    initShow: function (data) {
        let _lbl_coin_was = cc.find('node_center/node_was/lbl_coin_was', this.node);
        let _lbl_coin_now = cc.find('node_center/node_coin/lbl_coin_now', this.node);
        let _lbl_value = cc.find('node_center/spr_money/lbl_value', this.node);
        this._lbl_clock = cc.find('node_center/node_clock/lbl_clock', this.node);
        let _lbl_discount = cc.find('node_center/node_discount/lbl_discount', this.node);
        _lbl_coin_was.getComponent(cc.Label).string = cc.js.formatStr('%s', Global.formatMoney(data.precount));
        _lbl_coin_now.getComponent(cc.Label).string = cc.js.formatStr('%s', Global.formatMoney(data.count));
        // _lbl_value.getComponent(cc.Label).string = cc.js.formatStr('FOR $%s',data.amount);
        I18N.setI18nLabel(_lbl_value, cc.vv.Language.btn_for, data.amount)
        _lbl_discount.getComponent(cc.Label).string = cc.js.formatStr('%s%', data.discount);
        this.discountTime = cc.vv.UserManager.getLevelGift();
        this.showDiscountTime();
        //benifist
        let btn = cc.find("node_center/btn_benifist", this.node)
        btn.getComponent('CH_Benifist_Btn').showBenifist(data.rewards, '等级礼包权益')
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
    },

    onRcvShopDetail: function (msg) {
        let self = this
        if (msg.code === 200) {
            if (msg.stype == 5) {
                this._purchaseData = msg.shoplist;
                cc.vv.UserManager.setLevelGift(msg.timeout)
                self.initShow(msg.shoplist[0]);
            }
        }
    },

    //显示倒计时
    showDiscountTime: function () {
        var self = this;
        this.callback = function () {
            self._lbl_clock.getComponent(cc.Label).string = Global.formatSec(this.discountTime);
            if (self.discountTime <= 0) {
                this.unschedule(this.callback);
                // this.onClickClose();
            }
            --self.discountTime;
            cc.vv.UserManager.setLevelGift(self.discountTime);
        };
        this.schedule(this.callback, 1)
    },

    //购买
    onClickPurchase: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SPECIALOFFER_BUY)
        if (this._purchaseData) {
            let productid = this._purchaseData[0].id;
            cc.vv.PayMgr.reqPurchaseOrder(productid);
        }
        else {
            console.log("没有充值数据");
        }
    },

    //关闭
    onClickClose: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SPECIALOFFER_CLOSE)
        Global.playComEff("ch_close");
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
        this.node.destroy();
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, false, this);
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
    },

    //监听支付成功回调
    //支付校验成功
    onRcvMsgCheckOrder: function (msg) {
        if (msg.code === 200) {
            this.onClickClose();
        }
    },

});
