const SILVER_EGG = 1
const GOLD_EGG = 2

cc.Class({
    extends: cc.Component,

    properties: {
        _stype: "",
        _luckymain: null,
        _leftTime: 0,
        _hummerCnt: 0,
        _crushing: false,
        _eggInfo: [],
        _eggs: [],
    },


    onLoad() {
        this._lblTime = cc.find("lbl_time", this.node).getComponent(cc.Label)

        let btnBack = cc.find("btn_back", this.node)
        btnBack.on('click', this.onClickBack, this)

        let btnHummer = cc.find("hummer", this.node)
        btnHummer.on('click', this.onClickHummer, this)

        for (let i = 1; i <= 7; i++) {
            let egg = cc.find("eggs/egg" + i, this.node)
            this._eggs.push(egg)
            egg.on('click', this.onClickEgg, this)
        }

        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYSMASH_RECORD, this.onRcvNetLucksmashRecord, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYSMASH_CRUSH, this.onRcvNetLucksmashCrush, this)
        cc.vv.NetManager.registerMsg(MsgId.NOTIFY_BUY_HUMMER, this.onRcvNeBuyHummer, this)

        this.requestData()
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYSMASH_RECORD, this.onRcvNetLucksmashRecord, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYSMASH_CRUSH, this.onRcvNetLucksmashCrush, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.NOTIFY_BUY_HUMMER, this.onRcvNeBuyHummer, false, this)
    },

    init(stype, luckymain) {
        this._stype = stype
        this._luckymain = luckymain

        //剩余时间
        this._leftTime = luckymain.getLeftTime()
        cc.find("lbl_time", this.node).getComponent(cc.Label).string = Global.formatSec(this._leftTime)
        let cnt = luckymain.getHummer(stype)
        this.setHummer(cnt)

        //奖励列表
        let rewardsNode = cc.find("rewards_bg/rewards_list", this.node)
        luckymain.showRewardList(rewardsNode, luckymain.getRewards(stype))
    },

    setHummer(hummerCnt, sync = false) {
        this._hummerCnt = hummerCnt
        cc.find("hummer/lbl_count", this.node).getComponent(cc.Label).string = "X" + this._hummerCnt
        if (sync) {
            this._luckymain.setHummer(this._stype, this._hummerCnt)
        }
    },

    requestData() {
        let req = {
            c: MsgId.REQ_LUCKYSMASH_RECORD,
            stype: this._stype
        };
        cc.vv.NetManager.send(req);
    },

    //设置蛋的动画
    //unopen: 未开启
    //opened: 已开启
    //opening1: 开启未中奖
    //opening2: 开启中奖
    setEggAni(idx, state) {
        let spine = cc.find("eggs/egg" + idx + "/spine", this.node)
        let ske = spine.getComponent(sp.Skeleton)
        if (state == 'unopen') {
            ske.setAnimation(0, 'animation1', true)
        } else if (state == 'opened') {
            ske.setAnimation(0, 'animation4', false)
        } else if (state == 'opening1') {
            ske.setAnimation(0, 'animation3', false)
            ske.addAnimation(0, 'animation4', false)
        } else if (state == 'opening2') {
            ske.setAnimation(0, 'animation5', false)
            ske.addAnimation(0, 'animation6', false)
        }
    },


    onRcvNetLucksmashRecord(msg) {
        if (msg.code == 200) {
            //锤子获取情况
            for (let i = 0; i < msg.hammerInfo.length && i < 6; i++) {
                let idx = i + 1
                cc.find("week/day" + idx + "/missed", this.node).active = (msg.hammerInfo[i] == 0)
                cc.find("week/day" + idx + "/hummer", this.node).active = (msg.hammerInfo[i] != 0)
            }
            //蛋情况
            this._eggInfo = msg.eggInfo
            for (let i = 0; i < msg.eggInfo.length; i++) {
                let idx = i + 1
                if (msg.eggInfo[i] != 1) {
                    this.setEggAni(idx, 'opened')
                } else {
                    this.setEggAni(idx, 'unopen')
                }
            }
        }
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    showRewards(data) {
        return new Promise((success, failed) => {
            cc.loader.loadRes("CashHero/prefab/lucky_smash/lucky_reward", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("lucky_reward")) {
                    let node = cc.instantiate(prefab)
                    node.name = "lucky_reward"
                    node.parent = canvas
                    node.getComponent("LuckySmash_Reward").show(this._stype, data, success)
                } else {
                    success()
                }
            })
        })
    },

    async openEgg(data) {
        this.setHummer(this._hummerCnt - 1)
        if (data.isWin) {  //砸中大奖
            Global.playCashEff("luckysmash/smash2")
            this.setEggAni(data.eggIdx, "opening2")
            await this.awaitTime(1.5)
        } else {
            Global.playCashEff("luckysmash/smash1")
            this.setEggAni(data.eggIdx, "opening1")
            await this.awaitTime(1)
        }
        this._eggInfo[data.eggIdx - 1] = 0

        if (data.rewards.length > 0 || data.failCoin > 0) {  //有奖励
            await this.showRewards(data)
        }
        this.setHummer(data.hammerCnt, true)

        this._crushing = false

        if (data.isWin) {
            this._luckymain.setEnd(this._stype, true)
            this.node.destroy()
        }
    },

    onRcvNetLucksmashCrush(msg) {
        if (msg.code == 200) {
            this.openEgg(msg)
        }
    },

    onRcvNeBuyHummer(msg) {
        if (msg.code == 200 && msg.stype == this._stype) {
            if (msg.stype == this._stype) {
                this.setHummer(msg.hammer)
            }
            this._luckymain.setHummer(msg.stype, msg.hammer)
        }
    },

    onClickBack() {
        Global.playComEff("ch_btn_click")
        this.node.destroy();
    },

    onClickHummer() {
        Global.playComEff("ch_btn_click")
        if (this._hummerCnt <= 0) {
            this.showBuyHummer()
        }
    },

    showBuyHummer() {
        let cnt = 0 //剩余蛋数
        for (let i = 0; i < this._eggInfo.length; i++) {
            if (this._eggInfo[i] == 1) {
                cnt += 1
            }
        }
        if (cnt > 0) {
            let counts = []
            counts.push(1)
            if (cnt >= 7) {
                counts.push(7)
            } else if (cnt >= 5) {
                counts.push(5)
            } else if (cnt >= 2) {
                counts.push(3)
            }

            cc.loader.loadRes("CashHero/prefab/lucky_smash/lucky_buy", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("lucky_buy")) {
                    let node = cc.instantiate(prefab)
                    node.name = "lucky_buy"
                    node.parent = canvas
                    node.getComponent("LuckySmash_Buy").init(this._stype, counts)

                    if (this._stype == 1) {
                        StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_SLIVER_BUY_POP)
                    }
                    else {
                        StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_GOLD_BUY_POP)
                    }
                }
            })
        }
    },

    onClickEgg(event) {
        let idx = 0
        for (let i = 0; i < this._eggs.length; i++) {
            if (event.node == this._eggs[i]) {
                idx = i + 1
                break
            }
        }
        console.log("click egg", idx)
        /*
        //test
        this.openEgg({
            eggIdx:idx,
            rewards:[{type:1, count:100000},{type:2,count:10},{type:3,count:1000},{type:8,cardID:1037,count:1}],
            failCoin:1000,
            isWin:false,
            remainInfo:{cnt:1,coin:0},
            hammerCnt:this._hummerCnt-1
        })
        return
        */

        if (this._crushing) return
        if (this._eggInfo[idx - 1] != 1) return
        if (this._hummerCnt <= 0) {
            this.showBuyHummer()
            return
        }

        this._crushing = true
        Global.playComEff("ch_btn_click")
        let req = {
            c: MsgId.REQ_LUCKYSMASH_CRUSH,
            stype: this._stype,
            eggIdx: idx
        };
        cc.vv.NetManager.send(req);

        if (this._stype == 1) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_SLIVER_SMAH)
        }
        else {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_GOLD_SMAH)
        }

    },

    update(dt) {
        if (this._leftTime > 0) {
            this._leftTime -= dt
            if (this._leftTime <= 0) {
                //活动结束
                this.node.destroy()
            } else {
                this._lblTime.string = Global.formatSec(this._leftTime)
                // I18N.setI18nLabel(this._lblTime,cc.vv.Language.leftType,this._leftTime)
            }
        }
    },

});
