cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _inter: 0,
        _time: 2,
    },

    onLoad() {
        let collectBtn = cc.find('collectBtn', this.node)
        Global.btnClickEvent(collectBtn, this.onClickCollectBtn, this)
        this._autoModel = false
    },

    start() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_CASHBACK_REWARDS, this.OnRcvNetGetCashBackRewards, this)
        if (cc.vv.gameData) {
            this._autoModel = cc.vv.gameData.GetAutoModelTime()
            cc.vv.gameData.PauseSlot()
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CASHBACK_TOMORROW_POP)
    },

    initCoin(num) {
        if (cc.isValid(num)) {
            this._num = num
            cc.find('label', this.node).getComponent(cc.Label).string = Global.FormatNumToComma(num)
        }
    },

    sendReqGetRewards() {
        let req = { c: MsgId.REQ_GET_CASHBACK_REWARDS };
        cc.vv.NetManager.send(req);
    },

    OnRcvNetGetCashBackRewards(msg) {
        if (msg.code == 200) {
            let rd = msg.rewards[0].count
            if (!cc.isValid(rd)) {
                rd = this._num
            }
            //飞金币关闭界面
            let toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            let endNode = cc.find(Global.INGAME_COIN_NODE_PATH)
            let rollData = {}
            rollData.lblCoin = toLbl
            rollData.addCoin = rd
            let srcObj = cc.find("label", this.node)
            if (!cc.isValid(srcObj)) {
                srcObj = this.node
            }
            Global.FlyCoin(srcObj, endNode, () => {
                cc.vv.gameData.AddCoin(rd, true)
                Global.dispatchEvent(EventId.CLOSE_CASHBACK)
                this.node.destroy()
            }, rollData, true)
        }
    },

    onClickCollectBtn() {
        if (cc.isValid(this.node) && this._autoModel) {
            this._autoModel = false
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CASHBACK_TOMORROW_COLLECT)
        cc.find('collectBtn', this.node).getComponent(cc.Button).interactable = false
        this.sendReqGetRewards()
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
        cc.vv.QueueWinMrg.nextPop()
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_CASHBACK_REWARDS, this.OnRcvNetGetCashBackRewards, false, this)
    },

    update(dt) {
        if (this._time && this._autoModel) {
            this._inter += dt
            if (this._inter >= 1) {
                this._inter = 0
                this._time--
                if (this._time < 1) {
                    this.onClickCollectBtn()
                }
            }
        }
    },
});
