    //异常捕获
    getGameJsError: function () {
        let handleError = function (...args) {
            let data = { args }
            //console.log(JSON.stringify(data))
            cc.loader.loadRes("common/prefab/ErrorReport", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let parNode = cc.director.getScene()
                    if (!parNode.getChildByName('ErrorReport')) {
                        let node = cc.instantiate(prefab);
                        node.parent = parNode;
                        node.zIndex = 10000
                        node.getComponent("ShowErrorReport").setMsg(JSON.stringify(data))
                    }
                }
            });
        }
        if (cc.sys.isNative) {
            let __handler
            if (window['__errorHandler']) {
                __handler = window['__errorHandler']
            }
            window['__errorHandler'] = function (...args) {
                handleError(...args)
                if (__handler) {
                    __handler(...args)
                }
            }
        }
        if (cc.sys.isBrowser) {
            let __handler;
            if (window.onerror) {
                __handler = window.onerror
            }
            window.onerror = function (...args) {
                handleError(...args)
                if (__handler) {
                    __handler(...args)
                }
            }
        }
    },

