    update(dt) {
        this._nIterval += dt
        if (this._bAready == 0 && this._sendState) {
            if (this._nIterval > 6) { //5s超时，再次确认
                this._nIterval = 0
                let showStr = "Nice to see you，thank you for waiting."
                this.setTipText(showStr)
                this.reqStateInfo()
            }
        }
        //显示一个假的进度条
        if (this._bStopUpdate) return
        this._curPro = this._curPro || 0
        this._timeInter = this._timeInter || 0
        this._timeInter += dt
        if (this._timeInter > 0.05) {
            this._curPro += 0.01
            this._timeInter = 0
            if (this._curPro > this._launProMax) {
                this._bStopUpdate = true
            }
            else {
                this.setProgress(this._curPro)
            }
        }
    },

    loadNextScene: function () {
        if (!cc.vv.NetCacheMgr) {
            let scp = require("CH_NetCacheMgr")
            cc.vv.NetCacheMgr = new scp()
            cc.vv.NetCacheMgr.init()
        }
        // 淡出动画
        let val = Global.isIOSReview()
        // console.log(">>>> 是否iOS提审: ", val)
        if (Global.isNative() && Global.openUpdate) { // Android/iOS需要检查热更新
            console.log(">>>> iOS / Android Need Check Update")
            if (!this.isHotupdateRestart()) {
                if (!val) {
                    console.log('>>>> 准备进入热更流程')
                    this.startHotupdate()
                }
                else {
                    // 提审
                    console.log(">>>> Apps Store提审期间, 直接进入登录界面")
                    cc.vv.SceneMgr.enterScene(Global.SCENE_NAME.LOGIN)
                }
            }
            else {
                cc.vv.GameManager.nativeSkipHotupdate()
            }
        }
        else { // H5不需要热更新
            // console.log('>>>> 浏览器自动登陆')
            let autoLoginReq = Global.getLocal(Global.SAVE_KEY_REQ_LOGIN, '')
            if (autoLoginReq && Global.openAutoLogin) {
                // 直接自动登陆
                cc.vv.GameManager.reqReLogin(true)
            }
            else {
                // 游客自动登录
                cc.vv.GameManager.autoTravellerLogin()
            }
        }
    },

