    startHotupdate: function () {
        let scriptHotupdateNode = cc.find('script_hotupdate', this.node)
        if (scriptHotupdateNode) {
            scriptHotupdateNode.active = true
            let scp = scriptHotupdateNode.getComponent('CH_Hotupdate')
            if (scp) {
                // this._curPro = this._launProMax
                scp.startUpdate()
            }
        }
    },

    setProgress: function (val) {
        val = (val < 0.01) ? 0.01 : val
        let hotScp = cc.find('script_hotupdate', this.node).getComponent('CH_Hotupdate')
        if (hotScp) {
            let bStart = hotScp.isStartHotupdate()
            if (bStart) {
                //已经开始热更了，这里就不再更新进度了
                return
            }
        }
        let pro = cc.find('progress_update', this.node)
        let oldVal = pro.getComponent(cc.ProgressBar).progress
        if (oldVal < val) {
            pro.getComponent(cc.ProgressBar).progress = val
            this.setTipText(Math.floor(val * 100) + '%')
            if (cc.vv && cc.vv.AppData && cc.vv.AppData.setLaunchProgress) {
                cc.vv.AppData.setLaunchProgress(val)
            }
        }
    },

    setTipText: function (str) {
        let lbl = cc.find('lbl_tips', this.node)
        lbl.getComponent(cc.Label).string = str
    },

