const daily_rewards = [
    { rank: "1", rewards: [{ type: 1, count: 400000 }, { type: 8, count: 3 }] },
    { rank: "2", rewards: [{ type: 1, count: 300000 }, { type: 8, count: 2 }] },
    { rank: "3", rewards: [{ type: 1, count: 250000 }, { type: 8, count: 2 }] },
    { rank: "4", rewards: [{ type: 1, count: 200000 }, { type: 8, count: 2 }] },
    { rank: "5", rewards: [{ type: 1, count: 150000 }, { type: 8, count: 2 }] },
    { rank: "6-10", rewards: [{ type: 1, count: 120000 }, { type: 8, count: 1 }] },
    { rank: "11-20", rewards: [{ type: 1, count: 100000 }, { type: 8, count: 1 }] },
]

const season_rewards = [
    { rank: "1", rewards: [{ type: 1, count: 4000000 }, { type: 8, count: 10 }, { type: 2, count: 100 }] },
    { rank: "2", rewards: [{ type: 1, count: 3500000 }, { type: 8, count: 9 }, { type: 2, count: 90 }] },
    { rank: "3", rewards: [{ type: 1, count: 3000000 }, { type: 8, count: 8 }, { type: 2, count: 80 }] },
    { rank: "4", rewards: [{ type: 1, count: 2500000 }, { type: 8, count: 7 }, { type: 2, count: 70 }] },
    { rank: "5", rewards: [{ type: 1, count: 2000000 }, { type: 8, count: 6 }, { type: 2, count: 60 }] },
    { rank: "6-10", rewards: [{ type: 1, count: 1800000 }, { type: 8, count: 5 }, { type: 2, count: 50 }] },
    { rank: "11-20", rewards: [{ type: 1, count: 1500000 }, { type: 8, count: 4 }, { type: 2, count: 30 }] },
    { rank: "21-30", rewards: [{ type: 1, count: 1200000 }, { type: 8, count: 3 }, { type: 2, count: 20 }] },
    { rank: "31-40", rewards: [{ type: 1, count: 900000 }, { type: 8, count: 2 }, { type: 2, count: 10 }] },
    { rank: "41-50", rewards: [{ type: 1, count: 600000 }, { type: 8, count: 1 }, { type: 2, count: 5 }] },
]

cc.Class({
    extends: cc.Component,

    properties: {
        rankIcons: {
            default: [],
            type: cc.SpriteFrame
        }
    },

    onLoad() {
        Global.onClick("btn_close", this.node, this.onClickClose, this)
        Global.showAlertAction(this.node, true, 0.01, 1, null)
        Global.playComEff("ch_popup_l2")
        let itemTemp = cc.find("bg/item_template", this.node)
        this.initList("daily_rewards", itemTemp, daily_rewards)
        this.initList("season_rewards", itemTemp, season_rewards)
        for (let i = 1; i <= 3; i++) {
            let toggle = cc.find("bg/toggles/toggle" + i, this.node)
            toggle.on('toggle', this.onClickToggle, this)
        }
    },

    initList(type, itemTemp, rewardsCfg) {
        let content = cc.find("bg/" + type + "/ScrollView/view/content", this.node)
        let scale = cc.vv.HerocardManager.getCoinLS()
        for (let i = 0; i < rewardsCfg.length; i++) {
            let cfg = rewardsCfg[i]
            let item = cc.instantiate(itemTemp)
            content.addChild(item)
            item.active = true
            let sprRank = cc.find("rank", item)
            let lblRank = cc.find("lbl_rank", item)
            sprRank.active = i < 3
            lblRank.active = i >= 3
            if (i < 3) sprRank.getComponent(cc.Sprite).spriteFrame = this.rankIcons[i]
            else lblRank.getComponent(cc.Label).string = cfg.rank
            for (let reward of cfg.rewards) {
                let it = cc.find("item_" + reward.type, item)
                if (it) {
                    it.active = true
                    let count = reward.count
                    if (reward.type == 1) count *= scale
                    Global.setLabelString("count", it, Global.convertNumToShort(count))
                }
            }
        }
    },

    onClickToggle() {
        let pages = ["instructions", "daily_rewards", "season_rewards"]
        let toggleContainer = cc.find("bg/toggles", this.node).getComponent(cc.ToggleContainer)
        for (let i = 0; i < toggleContainer.toggleItems.length; i++) {
            let toggle = toggleContainer.toggleItems[i].getComponent(cc.Toggle)
            cc.find("bg/" + pages[i], this.node).active = toggle.isChecked
        }
    },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.destroy()
    }


});
