/**
 * 主场景资源
 */

cc.Class({
    extends: cc.Component,

    properties: {
        panel: cc.Node,
        logo: cc.Node,
        remaining_tips: cc.Node,
        reels_node: cc.Node,
        wheel_result: cc.Node,
        bonus_result: cc.Node,
        top_ani: cc.Node,
        bonus_node: cc.Node,
        lock_node: cc.Node,
        particleArr: [cc.ParticleSystem],
        fullSpine: [sp.Skeleton],
        spine_start_wheel: sp.Skeleton,

        _reels: [],   // 所有卷轴
        _canMoveReels: [], // 可移动卷轴
        _data: null,
        _callBack: null,
        _bonusItems: [],
        _currRoundBonus: [], // 当前轮次bonus
        _symbolTemplete: null,   //符号节点
    },

    onLoad() {
        this._symbolTemplete = cc.vv.gameData.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplete.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
        this._initData();
        this._initReels();
    },

    /**
     * 初始化数据
     */
    _initData() {
        this._data = {
            stoppedReelCnt: 0,   // 2停止的reel数量
            respData: null,   // 请求响应数据
            slotsInfo: [
                // id:0-上方slots 1-下方slots isFull:是否已经满了  resultId:wheel gameId
                { id: 0, isFull: false, resultId: 0 },
                { id: 1, isFull: false, resultId: 0 }
            ],
        };
    },

    /**
     * 初始化卷轴
     */
    _initReels() {
        this._reels = [];
        for (let i = 0; i < 30; i++) {
            let cmp = cc.find(`reel${i + 1}`, this.reels_node).addComponent("MagicFrog_RespinReel");
            cmp.Init(i, 1, this.top_ani);
            cmp.setHandler(this._onReelChange.bind(this));
            this._reels.push(cmp);
        }
    },

    /**
     * 卷轴事件处理
     * @param {*} evt 
     */
    _onReelChange(evt) {
        if (evt.evtName == "reel_spin_end") {
            SlotsFacade.soundMgr.playEffect("reel_stop");
            this._data.stoppedReelCnt++;
            let reelIdx = evt.data;
            let bonusId = SlotsFacade.dm.getGameCfg().bonusId;
            let symbol = this._reels[reelIdx].GetSymbolByRow(0);
            if (symbol.GetShowId() == bonusId) {
                SlotsFacade.soundMgr.playEffect("symbol_bonus");
                let idx = reelIdx + 1;
                let index = this._data.respData.bonusIdxs.indexOf(idx);
                if (index != -1) {
                    symbol.hide();
                    let data = {};
                    let bonusData = this._data.respData.bonusItems[index];
                    if (bonusData.coin) {
                        data.coin = bonusData.coin;
                    } else {
                        data.jp = bonusData.jackpot.id;
                    }
                    let bonusSymbol = this.genABonusItem(idx, data);
                    bonusSymbol.finalIdx = this._data.respData.convertIdxs[index];
                    this._currRoundBonus.push(bonusSymbol);
                } else {
                    console.log("数据错误找不到bonus", idx, this._data.respData);
                }
            }
            if (this._data.stoppedReelCnt == this._canMoveReels.length) {
                this.spinEnd();
            }
        }
    },

    /**
     * 初始化ui
     * @param {*} isReconnect 
     */
    _initView() {
        let respinData = SlotsFacade.dm.respinData;
        this.remaining_tips.active = true;
        this.showRestCnt(respinData.restCnt, true);
        this._hideWheelResult();
        this.bonus_result.active = false;
        this.logo.scale = 1.5;
        this.fullSpine.forEach((element) => {
            element.node.active = false;
        })
        this.spine_start_wheel.node.active = false;
        // 显示锁定
        cc.find("lock1", this.lock_node).active = respinData.locked == 1;
        cc.find("lock2", this.lock_node).active = respinData.locked == 2;
        // 显示图标
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i];
            let symbol = item.getFirstSymbol();
            let canShow = true;
            if (respinData.locked == 1) {
                canShow = i >= 15;
            } else if (respinData.locked == 2) {
                canShow = i < 15;
            }
            if (canShow) {
                symbol.StartMove();
                symbol.ShowById(this._getRandomSymbol());
            } else {
                symbol.hide();
            }
        }

        this._adjustPos(false);
    },

    /**
     * 调整 剩余次数和logo的位置
     * @param hasWheelResult 是否有wheel结果
     * @private
     */
    _adjustPos(hasWheelResult) {
        if (hasWheelResult) {
            this.logo.getChildByName("bonus_logo2").y = 30;
            this.remaining_tips.y = 370;
        } else {
            this.logo.getChildByName("bonus_logo2").y = 0;
            this.remaining_tips.y = 314;
        }
    },

    /**
     * 设置剩余次数
     * @param {*} cnt 
     * @param {*} isInit 
     */
    showRestCnt(cnt, isInit) {
        let tips = this.remaining_tips.getChildByName("tips").getComponent("ImgSwitchCmp");
        if (cnt == 3) {
            tips.setIndex(2);
        } else if (cnt == 2) {
            tips.setIndex(2);
        } else if (cnt == 1) {
            tips.setIndex(1);
        } else {
            tips.setIndex(0);
        }

        let label = this.remaining_tips.getChildByName("label").getComponent(cc.Label);
        if (cnt > 0) {
            tips.node.x = 16;
            label.node.active = true;
            label.string = `${cnt}`;
            if (cnt == 3 && !isInit) {
                SlotsFacade.soundMgr.playEffect("change");
                let spine = this.remaining_tips.getChildByName("spine").getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.setAnimation(0, "animation", false);
                spine.setCompleteListener(() => {
                    spine.setCompleteListener(null);
                    spine.node.active = false;
                });
            }
        } else {
            tips.node.x = 0;
            label.node.active = false;
        }
    },

    /**
     * 开始旋转
     */
    startMove() {
        this._data.stoppedReelCnt = 0;
        this._canMoveReels = [];
        let respinData = SlotsFacade.dm.respinData;
        for (let i = 0; i < this._reels.length; i++) {
            let canShow = true;
            if (respinData.locked == 1) {
                canShow = i >= 15;
            } else if (respinData.locked == 2) {
                canShow = i < 15;
            }
            if (!canShow) {
                continue;
            }
            if (!respinData.bonusIdxs.includes(i + 1)) {
                let item = this._reels[i];
                item.StartMove();
                this._canMoveReels.push(item);
            }
        }
    },

    /**
     * 收到respin消息
     * @param {*} msg 
     */
    async onRecSpinData(msg) {
        this._data.respData = msg.data;
        SlotsFacade.dm.respinData = msg.data.bonusGame;
        if (SlotsFacade.dm.respinData.state == 2) {
            for (let i = 0; i < this._data.slotsInfo.length; i++) {
                let slotsInfo = this._data.slotsInfo[i];
                if (slotsInfo.isFull || slotsInfo.resultId) {
                    continue;
                }
                let boo = true;
                for (let j = i * 15; j < (i + 1) * 15; j++) {
                    let idx = j + 1;
                    if (!SlotsFacade.dm.respinData.bonusIdxs.includes(idx)) {
                        boo = false;
                        break;
                    }
                }
                slotsInfo.isFull = boo;
            }
        }
        await SlotsFacade.delayTime(1);
        // 设置结果
        this.setSlotsResult();
        // 设置列停止间隔
        let reelStopInterv = 0.2;
        for (let i = 0; i < this._canMoveReels.length; i++) {
            let item = this._canMoveReels[i];
            let idx = item.GetReelIdx();
            let col = idx % 15 % 5;
            item.StopMove(col * reelStopInterv);
        }
    },

    /**
     * 设置卷轴结果
     */
    setSlotsResult() {
        let bonusIdxs = this._data.respData.bonusIdxs;

        let bonusItems = this._data.respData.bonusItems;
        for (let i = 0; i < this._canMoveReels.length; i++) {
            let item = this._canMoveReels[i];
            let idx = item.GetReelIdx();
            let bi = Array.isArray(bonusIdxs) ? bonusIdxs : []
            let index = bi.indexOf(idx + 1);
            if (index != -1) {
                let data = { sid: SlotsFacade.dm.getGameCfg().bonusId, data: {} };
                if (bonusItems[index].coin) {
                    data.data.coin = bonusItems[index].coin;
                } else {
                    data.data.jp = bonusItems[index].jackpot.id;
                }
                item.SetResult([data]);
            } else {
                item.SetResult([{ sid: this._getRandomSymbol() }]);
            }
        }
    },

    /**
     * 随机symbol id 无bonus图标
     */
    _getRandomSymbol() {
        let randomSymbols = [1, 2, 4, 5, 6, 7, 8, 9, 10, 11, 12];
        let randIdx = Global.random(1, randomSymbols.length);
        let randVal = randomSymbols[randIdx - 1];
        return randVal;
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        this.showRestCnt(SlotsFacade.dm.respinData.restCnt);
        await this.putInOrderBonusItems();
        await SlotsFacade.delayTime(0.5);
        await this.enterWheelGame();
        if (!SlotsFacade.dm.respinData.isEnd && SlotsFacade.dm.respinData.restCnt > 0) {
            // todo recover
            this.run();
        } else {
            await this.startSettlement();
        }
    },

    /**
     * 进入wheel game
     * @returns {Promise<void>}
     */
    async enterWheelGame() {
        let respinData = SlotsFacade.dm.respinData;
        if (respinData.state != 2) {
            return;
        }
        for (let i = 0; i < this._data.slotsInfo.length; i++) {
            let slotsInfo = this._data.slotsInfo[i];
            if (slotsInfo.isFull && slotsInfo.resultId == 0) {
                // 显示金框
                await new Promise(res => {
                    SlotsFacade.soundMgr.playEffect("board_full");
                    let spine = this.fullSpine[slotsInfo.id];
                    spine.node.active = true;
                    spine.setAnimation(0, "animation", false);
                    spine.setCompleteListener(() => {
                        spine.setCompleteListener(null);
                        spine.node.active = false;
                        res();
                    });
                });
                await SlotsFacade.delayTime(0.5);
                // 显示 进入动画
                await new Promise(res => {
                    SlotsFacade.soundMgr.playEffect("wheel_start_show");
                    this.spine_start_wheel.node.active = true;
                    this.spine_start_wheel.setAnimation(0, "animation2", false);
                    this.spine_start_wheel.setCompleteListener(() => {
                        this.spine_start_wheel.setCompleteListener(null);
                        this.spine_start_wheel.node.active = false;
                        res();
                    })
                });
                slotsInfo.resultId = await new Promise(res => {
                    return SlotsFacade.respinWheelGame.open((resultId) => {
                        res(resultId);
                    });
                });
                this._adjustPos(true);
                await this._showWheelResult(slotsInfo);
            }
        }
    },

    /**
     * 开始新一轮运行
     */
    async run() {
        this._currRoundBonus = [];
        let respinData = SlotsFacade.dm.respinData;
        // 更新次数
        this.showRestCnt(respinData.restCnt - 1);
        // 开始转动
        this.startMove();
        // 请求消息
        // todo recover
        SlotsFacade.dm.reqSubGame({ rtype: 2 });
    },

    /**
     * 进入游戏
     * @param {*} callBack 
     * @param {*} isReconnect 
     * @param {*} initBonusInfo bonusIdxs
     */
    async enterGame(callBack, isReconnect) {
        this._callBack = callBack;

        if (!isReconnect) {
            await SlotsFacade.mainPanel.showSceneTransition(2);
        }
        SlotsFacade.soundMgr.playBgm("bonus_bgm");
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.mainPanel.slots.active = false;
        this.panel.active = true;
        SlotsFacade.mainPanel.jpNode.active = false;
        this._initData();
        this._initView(isReconnect);
        this.initBonusItems();
        await SlotsFacade.delayTime(1.5);
        SlotsFacade.bottomCmp.DoHideWinAction();
        await this.putInOrderBonusItems();

        if (isReconnect && SlotsFacade.dm.respinData && SlotsFacade.dm.respinData.state == 2) {
            // 断线重连时是集满的转盘状态
            for (let i = 0; i < this._data.slotsInfo.length; i++) {
                let slotsInfo = this._data.slotsInfo[i];
                if (slotsInfo.isFull || slotsInfo.resultId) {
                    continue;
                }
                let boo = true;
                for (let j = i * 15; j < (i + 1) * 15; j++) {
                    let idx = j + 1;
                    if (!SlotsFacade.dm.respinData.bonusIdxs.includes(idx)) {
                        boo = false;
                        break;
                    }
                }
                slotsInfo.isFull = boo;
            }

            await this.enterWheelGame();
            await this.startSettlement();
        } else {
            // todo recover
            this.run();
        }
    },

    /**
     * 退出游戏
     */
    async exitGame(coin) {
        await SlotsFacade.mainPanel.showSceneTransition(2);
        this.clearBonusItem();
        let isFree = cc.vv.gameData.hasFree();
        SlotsFacade.mainPanel.showBg(isFree ? 2 : 0);
        SlotsFacade.mainPanel.slots.active = true;
        this.panel.active = false;
        SlotsFacade.mainPanel.jpNode.active = true;
        if (this._callBack) {
            this._callBack(coin);
        }
    },

    //////////////////////bonus相关///////////////////////////
    clearBonusItem() {
        this.bonus_node.removeAllChildren();
        this._currRoundBonus = [];
        this._bonusItems = [];
    },

    initBonusItems() {
        let bonusSymbolArr = [];
        let respinData = SlotsFacade.dm.respinData;
        let bonusInfo = null;
        if (SlotsFacade.dm.getSpinData()) {
            bonusInfo = SlotsFacade.dm.getSpinData().BonusInfo;
        }
        if (bonusInfo) {
            for (let i = 0; i < bonusInfo.triggerBonusIdx.length; i++) {
                let idx = bonusInfo.triggerBonusIdx[i];
                let bonusItemData = bonusInfo.triggerBonusItems[i];
                let data = {};
                if (bonusItemData.coin) {
                    data.coin = bonusItemData.coin;
                } else {
                    data.jp = bonusItemData.jackpot.id;
                }
                let symbol = this.genABonusItem(idx, data);
                bonusSymbolArr.push(symbol);
                this._reels[idx - 1].getFirstSymbol().hide();
                symbol.finalIdx = bonusInfo.convertBonusIdxs[i];
            }
        } else { // 重连
            for (let i = 0; i < respinData.bonusIdxs.length; i++) {
                let idx = respinData.bonusIdxs[i];
                let bonusItemData = respinData.bonusItems[i];
                let data = {};
                if (bonusItemData.coin) {
                    data.coin = bonusItemData.coin;
                } else {
                    data.jp = bonusItemData.jackpot.id;
                }
                let symbol = this.genABonusItem(idx, data);
                bonusSymbolArr.push(symbol);
                this._reels[idx - 1].getFirstSymbol().hide();
                symbol.finalIdx = idx;
            }
        }
        this._currRoundBonus = bonusSymbolArr;
        this._bonusItems = [];
    },

    /**
     * 生成一个bonus图标
     * @param {*} idx 
     * @param {*} data
     */
    genABonusItem(idx, data) {
        let cfg = SlotsFacade.dm.getGameCfg();
        let node = cc.instantiate(this._symbolTemplete)
        node.parent = this.bonus_node;
        let scp = node.addComponent(cfg.scripts.Symbols)
        scp.SetSymbolReelIdx(this._reelIdx)
        scp.Init(0, this.top_ani);
        scp.ShowById(cfg.bonusId, data);
        scp.playBonusIdleAni();
        let pos = this._reels[idx - 1].node.getPosition();
        node.setPosition(pos);
        return scp;
    },

    /**
     * 整理bonus
     */
    async putInOrderBonusItems() {
        this._bonusItems = this._bonusItems.concat(this._currRoundBonus);
        for (let i = 0; i < this._currRoundBonus.length; i++) {
            let symbol = this._currRoundBonus[i];
            let endPos = this._reels[symbol.finalIdx - 1].node.getPosition();
            cc.tween(symbol.node)
                .to(0.3, { x: endPos.x, y: endPos.y })
                .start();
        }
        if (this._currRoundBonus.length > 0) {
            SlotsFacade.soundMgr.playEffect("bonus_fall");
        }
        await SlotsFacade.delayTime(0.3);
    },

    /**
     * 开始结算
     */
    async startSettlement() {
        cc.tween(this.logo)
            .to(0.4, { scale: 0 }, { easing: "backIn" })
            .start();
        this.remaining_tips.active = false;
        this.bonus_result.active = true;
        this.bonus_result.scale = 0;
        this.bonus_result.getChildByName("label").getComponent(cc.Label).string = "";
        cc.tween(this.bonus_result)
            .delay(0.4)
            .call(() => {
                SlotsFacade.soundMgr.playEffect("respin_collect");
            })
            .to(0.4, { scale: 1 }, { easing: "backOut" })
            .start();
        await SlotsFacade.delayTime(0.8);
        // 结算symbol
        let sum = await this.settlementNumb();
        // 结算 wheel game
        for (let i = 0; i < this._data.slotsInfo.length; i++) {
            let slotsInfo = this._data.slotsInfo[i];
            if (slotsInfo.isFull && slotsInfo.resultId > 0) {
                sum = await this._collectWheelResult(sum, this._data.slotsInfo[i]);
            }
        }

        // 再次设置金币 防止显示不一致
        let winCoin = SlotsFacade.dm.respinData.winCoin;
        let label = this.bonus_result.getChildByName("label").getComponent("LabelRollCmp");
        label.startRoll(winCoin, winCoin, 0.1);
        SlotsFacade.bottomCmp.SetWin(winCoin);
        if (sum != winCoin) {
            console.log("#err结算金币不一致：", sum, winCoin, this._data.respData);
        }
        Global.SlotsSoundMgr.stopBgm();
        await SlotsFacade.popup.showWinRespinCoin(winCoin);
        this.exitGame(winCoin);
    },

    /**
     * 添加收集金币
     * @param {*} startVal 
     * @param {*} endVal 
     */
    async addCollectNumb(startVal, endVal) {
        let spine = this.bonus_result.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(() => {
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
        let label = this.bonus_result.getChildByName("label").getComponent("LabelRollCmp");
        label.startRoll(startVal, endVal, 0.5);
        SlotsFacade.bottomCmp.SetWin(endVal);
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 显示wheel game 的结果
     * @returns {Promise<void>}
     * @private
     */
    async _showWheelResult(slotsInfo) {
        SlotsFacade.soundMgr.playEffect("award_show");
        this.wheel_result.active = true;
        let resultNode = cc.find(`result${slotsInfo.id + 1}`, this.wheel_result);
        resultNode.active = true;
        let spineBg = cc.find("spine_bg", resultNode).getComponent(sp.Skeleton);
        spineBg.node.active = true;
        spineBg.setAnimation(0, "animation1", false);
        spineBg.addAnimation(0, "animation2", true);
        let wheelCfgItem = SlotsFacade.dm.getGameCfg().WheelGameConfig[slotsInfo.resultId - 1];
        let valueNode = null;
        if (wheelCfgItem.mult) {
            let label = cc.find("label", resultNode).getComponent(cc.Label);
            label.node.active = true;
            label.string = Global.FormatNumToComma(SlotsFacade.dm.GetTotalBet() * wheelCfgItem.mult);
            valueNode = label.node;
        } else {
            let iconCmp = cc.find("icon", resultNode).getComponent("ImgSwitchCmp");
            iconCmp.node.active = true;
            iconCmp.setIndex(wheelCfgItem.resultIconIdx);
            valueNode = iconCmp.node;
        }
        valueNode.scale = 0;
        cc.tween(valueNode).to(0.7, { scale: 1 }, { easing: "backOut" }).start();
        await SlotsFacade.delayTime(1);
    },

    /**
     * 收集wheel game 结果金币
     * @returns {Promise<void>}
     * @private
     */
    async _collectWheelResult(startCoin, slotsInfo) {
        SlotsFacade.soundMgr.playEffect("award_choose");
        this.wheel_result.zIndex = this.bonus_result.zIndex + 1;
        let resultItem = cc.find(`result${slotsInfo.id + 1}`, this.wheel_result);
        // 播放背景动画
        let bgSpine = resultItem.getChildByName("spine_bg").getComponent(sp.Skeleton);
        bgSpine.setAnimation(0, "animation3", false);
        bgSpine.addAnimation(0, "animation2", true);
        await new Promise(res => {
            bgSpine.setCompleteListener(() => {
                bgSpine.setCompleteListener(null);
                res()
            })
        })
        // 播放收集光效
        SlotsFacade.soundMgr.playEffect("bonus_collect2");
        let spine_collect = resultItem.getChildByName("spine_collect").getComponent(sp.Skeleton);
        spine_collect.node.active = true;
        spine_collect.setAnimation(0, `animation${1 + Math.floor(Math.random() * 3)}`, false);
        await new Promise(res => {
            spine_collect.setCompleteListener(() => {
                spine_collect.setCompleteListener(null);
                spine_collect.node.active = false;
                res();
            })
        });
        let wheelCfgItem = SlotsFacade.dm.getGameCfg().WheelGameConfig[slotsInfo.resultId - 1];

        let sum = startCoin;
        let gold = 0;
        // 播放jackpot弹框
        if (wheelCfgItem.hasOwnProperty("jackpotId") && SlotsFacade.respinData && SlotsFacade.respinData.jackpotValues) { // By JerryWong
            console.log(">>>> MagicFrog 这里能正常跑了 ...")
            gold = SlotsFacade.respinData.jackpotValues[wheelCfgItem.jackpotId] || 0;
            sum += gold;
            await SlotsFacade.popup.showWinJPGold(wheelCfgItem.jackpotId + 1, gold);
        } else if (wheelCfgItem.hasOwnProperty("allWinMult")) {
            gold = startCoin * wheelCfgItem.allWinMult;
            sum = gold;
        } else if (wheelCfgItem.hasOwnProperty("mult")) {
            gold = SlotsFacade.dm.GetTotalBet() * wheelCfgItem.mult;
            sum += gold;
        }
        // 播放数字动画
        await this.addCollectNumb(startCoin, sum);
        return sum;
    },

    /**
     * 隐藏wheel result
     * @private
     */
    _hideWheelResult() {
        this.wheel_result.active = false;
        for (let i = 0; i < 2; i++) {
            cc.find(`result${i + 1}`, this.wheel_result).active = false;
            cc.find(`result${i + 1}/spine_bg`, this.wheel_result).active = false;
            cc.find(`result${i + 1}/icon`, this.wheel_result).active = false;
            cc.find(`result${i + 1}/label`, this.wheel_result).active = false;
            cc.find(`result${i + 1}/spine_collect`, this.wheel_result).active = false;
        }
    },

    /**
     * 结算数字
     */
    async settlementNumb() {
        this.wheel_result.zIndex = this.bonus_result.zIndex - 1;
        let arr = [];
        this._bonusItems.sort((a, b) => { return a.finalIdx - b.finalIdx });
        this._bonusItems.forEach(element => {
            let idx = element.finalIdx - 1;
            let col = Math.floor(idx / 15) * 5 + idx % 5;
            if (!arr[col]) {
                arr[col] = [];
            }
            arr[col].push(element);
        });
        let sum = 0;
        for (let i = 0; i < arr.length; i++) {
            let colArr = arr[i];
            if (!colArr || colArr.length < 1) {
                continue;
            }
            for (let j = 0; j < colArr.length; j++) {
                let symbol = colArr[j];
                symbol.ShowById(SlotsFacade.dm.getGameCfg().bonusId, symbol._data);
                let idx = symbol.finalIdx;
                let pos = this._reels[idx - 1].node.convertToWorldSpaceAR(cc.v2(0, 0));
                pos = this.bonus_result.convertToNodeSpaceAR(pos);
                let lzNode = this.particleArr[0].node;
                if (symbol.GetData().jp) {
                    if (symbol.GetData().jp == 1) {
                        lzNode = this.particleArr[1].node;
                    } else {
                        lzNode = this.particleArr[2].node;
                    }
                }
                let lz = cc.instantiate(lzNode).getComponent(cc.ParticleSystem);
                lz.node.parent = this.bonus_result;
                lz.node.setPosition(pos);
                lz.node.active = true;
                lz.resetSystem();
                cc.tween(lz.node)
                    .to(0.3, { x: 0, y: 0 })
                    .call(() => {
                        lz.node.removeFromParent();
                    })
                    .start();
                SlotsFacade.soundMgr.playEffect("bonus_collect");
                await SlotsFacade.delayTime(0.4);
                let startVal = sum;
                let symbolVal = 0;
                if (symbol.GetData().coin) {
                    symbolVal = symbol.GetData().coin;
                } else {
                    symbolVal = SlotsFacade.dm.respinData.jackpotValues[symbol.GetData().jp - 1];
                }
                sum += symbolVal;
                await this.addCollectNumb(startVal, sum);
            }
        }
        return sum;
    },
})