    setButtonCFG(flag) {
        this.disEnabled(true)

        let spr_box = cc.find('spr_box', this._btn);
        let label = cc.find('label', this._btn)
        label.active = false
        this._btn.off("click");
        let _btnInterFlag = !((flag == BUTTON_TYPE.COLLECT || spr_box.active) && this._data.btnState === "gray")
        this._btn.getComponent(cc.Button).interactable = _btnInterFlag

        let btn_str_cfg = 'btn_collect'
        if (flag == BUTTON_TYPE.COLLECT || spr_box.active) {
            Global.btnClickEvent(this._btn, this.OnClickCollect, this)
        } else if (flag == BUTTON_TYPE.GO_SPIN) {
            btn_str_cfg = 'btn_gospin'
            Global.btnClickEvent(this._btn, this.OnClickGoSpin, this)
        } else if (flag == BUTTON_TYPE.GO_CLAIM) {
            btn_str_cfg = 'btn_goclaim'
            Global.btnClickEvent(this._btn, this.OnClickGoClaim, this)
        } else if (flag == BUTTON_TYPE.GO) {
            btn_str_cfg = 'btn_go'
            Global.btnClickEvent(this._btn, this.OnClickGoVip, this)
        } else if (flag == BUTTON_TYPE.CONNECT) {
            btn_str_cfg = 'btn_connect'
            Global.btnClickEvent(this._btn, this.fbConnect, this)
        } else if (flag == BUTTON_TYPE.REDEEM) {
            btn_str_cfg = 'btn_redeem'
            Global.btnClickEvent(this._btn, this.OnClickRedeem, this)
        }

        if (flag == BUTTON_TYPE.BOX) {
            return
        }
        let cfg = BUTTON_CFG[flag]
        // let label = cc.find('label', this._btn)
        label.active = true
        // label.getComponent(cc.Label).string = cfg.str
        //设置key 刷新
        let btni18Scp = label.getComponent("LanguageLabel")
        btni18Scp.id = btn_str_cfg
        btni18Scp.updateLabel()

        label.y = cfg.posY + 5
        // console.log('label.y',label.y)
        label.getComponent(cc.LabelOutline).color = cc.Color(cfg.color[0], cfg.color[1], cfg.color[2], cfg.color[3])

        let btn_type = cc.find(cfg.type, this._btn)
        if (this._data.type != MailType.vip_mail) {
            Global.showSpriteGray(btn_type, !_btnInterFlag)
        }
        // label.parent = btn_type
        btn_type.y = cfg.posY
        btn_type.active = true
    },

