    refrushPrize(rd) {
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.COIN) {
                cc.vv.UserManager.AddCoin(rd[i].count, true)
            } else if (rd[i].type == Global.PROP_ID.DIAMOND) {
                cc.vv.UserManager.AddDiamond(rd[i].count, true)
            }
        }
    },

