    // 读邮件
    OnRcvNetMailDetail: function (msg) {
        if (msg.mail_info.mailid != this._data.mailid) {
            return
        }

        let _openVipFlag = false
        if (this._data.type == MailType.vip_mail) {
            let _active = cc.find("bg_coin", this.node).active
            _openVipFlag = !_active
        }


        this._hasDetailFlag = true
        let self = this
        if (msg.code == 200) {
            let url = "CashHero/prefab/mail/hall_mailDetail"
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')

                    let endCall = function () {
                        self._hasDetailFlag = false
                    }
                    node.getComponent('CH_MailDetail').setData(msg.mail_info, endCall, this._boxType, _openVipFlag)
                    cc.find('popBtn', this.node).getComponent(cc.Button).interactable = true
                }
                else {
                    console.log('未找到资源:' + url)
                }
            })
        }
    },


