cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        itemAtlas: {
            default: null,
            type: cc.SpriteAtlas,
        },
        pointSpine: {
            default: null,
            type: sp.Skeleton,
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('spr_bg/btn_confirm', this.node), this.onClickConfirm, this);
        Global.playComEff("ch_popup_l2");

        this.midNode = cc.find('mid', this.node)
        this.itemPrefab = cc.find('item1', this.midNode)
        this.coinItem = null
        this.offX = 250
    },

    start() {
        Global.FixDesignScale_V(this.node)
    },

    setRd(msg) {
        if (msg) {
            this.msgData = msg
            let msgStatic = msg
            //初始化
            this.initReward(msgStatic)
            //奖励效果
            this.setRewards(msgStatic)

            this.setSpine()
        }
    },

    setSpine() {
        this.pointSpine.setAnimation(0, 'animation2', true)
    },

    setPos() {
        cc.find('plus', this.node).active = false
        let child = this.midNode.children
        for (let i = 0; i < child.length; i++) {
            child[i].x = i * this.offX - this.offX
        }
    },

    //数据清洗 卡牌8 全部靠后 金币第一
    dataSort(data) {
        let sorFunc = function (a, b) {
            let aVal = 0
            if (a.type == Global.PROP_ID.COIN) {
                aVal = 1
            }
            let bVal = 0
            if (b.type == Global.PROP_ID.COIN) {
                bVal = 1
            }

            if (aVal != bVal) {
                return bVal - aVal
            }
            else {
                aVal = 0
                if (a.type == Global.PROP_ID.HERO_CARD) {
                    aVal = 1
                }
                bVal = 0
                if (b.type == Global.PROP_ID.HERO_CARD) {
                    bVal = 1
                }
                if (aVal != bVal) {
                    return aVal - bVal
                }
                else {
                    return a.type < b.type
                }
            }

        }
        data.sort(sorFunc)
        return data;
    },


    initReward(msg) {
        let sortMsg = this.dataSort(msg.rewards)
        let cardCount = this.cardNum(sortMsg)

        if (msg.curSignCount == 7) {
            var itemNode = cc.instantiate(this.itemPrefab)
            itemNode.parent = this.itemPrefab.parent;
            this.setPos()
        }

        let childNode = this.midNode.children
        var count = 0
        for (let i = 0; i < childNode.length; i++) {
            if (sortMsg[i].type == Global.PROP_ID.HERO_CARD) {
                count = cardCount
            } else {
                count = sortMsg[i].count
            }
            cc.find('num', childNode[i]).getComponent(cc.Label).string = this.getNum(count, sortMsg[i].type)
            this.setItem(sortMsg[i].type, childNode[i])
        }
    },

    cardNum(sortMsg) {
        var count = 0
        for (let i = 0; i < sortMsg.length; i++) {
            if (sortMsg[i].type == Global.PROP_ID.HERO_CARD) {
                count += sortMsg[i].count
            }
        }
        return count
    },

    setItem(id, itemNode) {
        id = (id == 1) ? 5 : id

        let url = 'common/rewarditem/' + id
        cc.loader.loadRes(url, cc.SpriteFrame, (err, data) => {
            if (!err) {
                itemNode.getComponent(cc.Sprite).spriteFrame = data
            }
        })

    },

    getNum(count, id) {
        let num = 0
        if (id == 1) {
            num = Global.convertNumToShort(count, 1000, 2)
        } else if (id == 3) {
            num = (count / 3600).toFixed(0) + "H"
        } else {
            num = count
        }
        return num
    },

    getMsg() {
        if (this.msgData) {
            return this.msgData
        }
        return null
    },

    setRewards(msg) {
        //重做奖励数组
        let self = this
        let flyEndCall = function () {
            self.node.runAction(cc.sequence(cc.delayTime(0.5),
                cc.callFunc(function () {
                    self.popReward(self.getMsg())
                    // cc.vv.UserManager.AddCoin(this.msgData.rewardCoin,true)
                    if (cc.vv.gameData) {
                        cc.vv.gameData.AddCoin(this.msgData.rewardCoin, true)
                    } else {
                        cc.vv.UserManager.AddCoin(this.msgData.rewardCoin, true)
                    }
                }, self)
            ))
        }

        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH) || cc.find(Global.INGAME_COIN_LABEL_NODE_PATH);
        rollData.addCoin = msg.rewardCoin
        let numNode = cc.find('num', this.itemPrefab)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH)
        this.node.runAction(cc.sequence(cc.delayTime(0.5),
            cc.callFunc(function () {
                Global.FlyCoin(numNode, endNode, flyEndCall, rollData, true)
            }, this)
        ))
    },

    //弹出小奖励
    popReward(msg) {
        this.node.active = false

        let rd = msg.rewards
        let rewardArray = []
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.COIN) {
                continue
            } else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD) {
                rewardArray.push(rd[i])
            } else {
                Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: rd[i].type, num: rd[i].count })
            }
        }

        let url = 'CashHero/prefab/pop_reward'
        let self = this
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                let endCall = function () {
                    self.canOpenGift()
                }
                node.getComponent('CH_popreward').showRewards(rewardArray, endCall)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    //检测礼包
    canOpenGift() {
        if (cc.isValid(this.node)) {
            let signinNode = this.node.parent.getChildByName('SignIn')
            if (signinNode) {
                signinNode.getComponent('Signin').sendGetSignGift()
                this.nodeDestroy()
            }

        }

    },

    nodeDestroy() {
        Global.playComEff("ch_close");
        this.node.destroy()
    },
    // update (dt) {},
});
