cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        Global.btnClickEvent(cc.find("bg/btn_close", this.node), this.onBtnCloseClicked, this);
        let btn_logout = cc.find("bg/btn_logout", this.node)
        Global.btnClickEvent(btn_logout, this.onBtnLogoutClicked, this);
        // Global.btnClickEvent(cc.find("bg/Node_FB_RATE_US/btn_rateUs", this.node), this.onBtnRateUsClicked, this);
        let btn_service = cc.find("bg/node_service", this.node)
        
        Global.btnClickEvent(cc.find("btn", btn_service), this.onBtnContactUsClicked, this);
        let btn_privacy = cc.find("bg/node_resvision/btn_PrivacyPolicy", this.node)
        Global.btnClickEvent(btn_privacy, this.onBtnPrivacyPolicyClicked, this);
        Global.btnClickEvent(cc.find("bg/node_repcode/btn", this.node), this.onBtnRepCodeClicked, this);
        Global.btnClickEvent(cc.find("bg/btn_TermsOfService", this.node), this.onBtnServiceInfoClicked, this);
        Global.btnClickEvent(cc.find("bg/Node_FansPage/btn_FansPage", this.node), this.onBtnFansPageClicked, this);
        Global.btnClickEvent(cc.find("bg/Node_DelAccount/btn_delAccount", this.node), this.onDelAccount, this);
        let btn_fbbind = cc.find("bg/btn_layout/btn_fbbind",this.node)
        Global.btnClickEvent(btn_fbbind,this.onBtnFBBindClicked,this)
        let btn_ggbind = cc.find("bg/btn_layout/btn_googlebind",this.node)
        Global.btnClickEvent(btn_ggbind,this.onBtnGoogleBindClicked,this)

        let bFbLogin = cc.vv.UserManager.getLoginType() == Global.LoginType.FB
        
        let bGoogleLogin = (cc.vv.UserManager.getLoginType() == Global.LoginType.GOOGLE_LOGIN) 
        let bApple =  cc.vv.UserManager.getLoginType() == Global.LoginType.APPLE_LOGIN
        
        btn_fbbind.active = !cc.vv.UserManager.isBindFb()
        // //华为的不显示fb
        // if(Global.appId == Global.APPID.SouthAmerica || Global.appId == Global.APPID.HuaweiDRM){
        //     btn_fbbind.active = false
        // }
        //google 先关闭
        btn_ggbind.active = (!cc.vv.UserManager.isBindFb() && !cc.vv.UserManager.getIsBindGoogle()) && Global.isAndroid() && cc.vv.UserManager.isSupperGoogleSign()

        let bInGame = cc.vv.AppData.getIsInGame() && cc.vv.gameData
        if(bInGame){ //游戏内就不显示登出/绑定按钮了
            btn_fbbind.active = false
            btn_logout.active = false
            btn_privacy.active = false
            btn_ggbind.active = false
            btn_service.active = true
        }
        else{
            btn_logout.active = true
            btn_service.active = false
        }

        //音效开关
        let btn_sound = cc.find("bg/Node_Sound/btn_sound", this.node);
        Global.btnClickEvent(btn_sound, this.onBtnSoundsClicked, this);

        //音乐开关
        let btn_music = cc.find("bg/Node_Music/btn_music", this.node);
        Global.btnClickEvent(btn_music, this.onBtnMusicClicked, this);

        //uid
        let lbl_uid = cc.find('bg/Node_Player/lblPlayerId',this.node).getComponent(cc.Label);
        lbl_uid.string = Global.playerData.uid;

        // this.node_userAgreement = cc.find('node_userAgreement',this.node);
        // this.node_userAgreement.active = false;
        // Global.btnClickEvent(this.node_userAgreement, this.onHideAgreement, this);
        
        // let bg = cc.find("bg", this.node);
        // let curCanvas = cc.find('Canvas').getComponent(cc.Canvas)
        // let scaleX = curCanvas.designResolution.width / 1080;
        // let scaleY = curCanvas.designResolution.height / 1920;
        // let min = (scaleX>scaleY?scaleY:scaleX);
        // bg.scale = bg.scale * min

        let iosReview = Global.isIOSReview();
        cc.find("bg/Node_DelAccount", this.node).active = iosReview;  //审核显示删除账号，否则显示兑换码
        cc.find("bg/node_repcode", this.node).active = !iosReview;
        
        Global.FixDesignScale_V(this.node)

        // this.onShowFanpages()

        let ver = cc.find('bg/node_resvision/ver_txt',this.node)
        ver.getComponent(cc.Label).string = "V"+Global.resVersion;
    },

    onDestroy(){
        if(!cc.vv.gameData){
            Global.dispatchEvent(EventId.HIDE_HALL_MENU);
        }
        
    },

    onEnable(){
        if(cc.vv.gameData){
            cc.vv.gameData.PauseSlot()
        }
        

        let scale = this.node.scale
        Global.showAlertAction(this.node,true,0.1,scale,null)
        //音效开关
        let btn_sound = cc.find("bg/Node_Sound/btn_sound", this.node);
        btn_sound.getChildByName("on").active = cc.vv.AudioManager.getEffVolume()>0;
        btn_sound.getChildByName("off").active = !btn_sound.getChildByName("on").active;

        //音乐开关
        let btn_music = cc.find("bg/Node_Music/btn_music", this.node);
        btn_music.getChildByName("on").active = cc.vv.AudioManager.getBgmVolume()>0;
        btn_music.getChildByName("off").active = !btn_music.getChildByName("on").active;
        
        Global.playComEff("ch_popup_setting");
    },

    start () {
        this._checkLanguageVal()
       
    },

    // update (dt) {},

    // BOTTON BIND CALLBACKS:

    //关闭按钮
    onBtnCloseClicked (event, customEventData) {
        Global.playComEff("ch_close_setting");
        if(cc.vv.gameData){
            cc.vv.gameData.ResumeSlot()
        }
        
        // this.node.active = false;
        this.node.destroy()
    },

    //登出Logout按钮
    onBtnLogoutClicked (event, customEventData) {
        cc.vv.GameManager.GameLogoout()
    },

    //声音按钮
    onBtnSoundsClicked (event, customEventData) {
        let btn_sound = cc.find("bg/Node_Sound/btn_sound", this.node);
        btn_sound.getChildByName("on").active = !btn_sound.getChildByName("on").active;
        btn_sound.getChildByName("off").active = !btn_sound.getChildByName("on").active;

        let volume = btn_sound.getChildByName("on").active?1:0;
        cc.vv.AudioManager.setEffVolume(volume);

        //打点
        let evt = StatisticsMgr.REQ_SETTING_EFFECT_CLOSE
        if(volume){
            evt = StatisticsMgr.REQ_SETTING_EFFECT_OPEN
        }
        StatisticsMgr.reqReport(evt);
        Global.playComEff("ch_tab");
    },

    onBtnMusicClicked:function(){
        let btn_music = cc.find("bg/Node_Music/btn_music", this.node);
        btn_music.getChildByName("on").active = !btn_music.getChildByName("on").active;
        btn_music.getChildByName("off").active = !btn_music.getChildByName("on").active;

        let volume = btn_music.getChildByName("on").active?1:0;
        cc.vv.AudioManager.setBgmVolume(volume);

        //打点
        let evt = StatisticsMgr.REQ_SETTING_BGM_CLOSE
        if(volume){
            evt = StatisticsMgr.REQ_SETTING_BGM_OPEN
        }
        StatisticsMgr.reqReport(evt);
        Global.playComEff("ch_tab");
    },

    // //评分按钮
    // onBtnRateUsClicked (event, customEventData) {
    //     console.log("评分");
        
    // },

    //联系我们按钮
    onBtnContactUsClicked (event, customEventData) {
        console.log("联系我们");
        cc.vv.PlatformApiMgr.openURL(Global.whatapplink);
    },

    //隐私政策按钮
    onBtnPrivacyPolicyClicked (event, customEventData) {
        console.log("隐私政策");
        this.onShowAgreement();
       
    },

    //服务条款按钮
    onBtnServiceInfoClicked (event, customEventData) {
        console.log("服务条款");
        
    },

    //粉丝页按钮
    onBtnFansPageClicked (event, customEventData) {
        console.log("粉丝页");
        cc.vv.PlatformApiMgr.openURL(Global.fackbookLink);

    },

    //显示隐私协议
    onShowAgreement(){
        let url = 'https://global.rummyslot.com/privacy-policy/'
        cc.sys.openURL(url)
    },

    // //是否需要显示粉丝页
    // onShowFanpages(){
    //     let bShow = Global.fackbookLink?true:false
    //     cc.find('bg/Node_FB_ContactUs',this.node).active = bShow
    //     cc.find('bg/Node_FansPage',this.node).active = bShow
    //     Global.playComEff("ch_tab");
    // },

    //游客fb绑定
    onBtnFBBindClicked(){
        let self = this
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SETTING_FBBIND)
        cc.vv.PlatformApiMgr.fbLogin((cbData)=>{
            
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = {c:MsgId.REQ_BIND_FACEBOOK};
                req.accesstoken = cbData.token;
                req.user = cbData.uid;
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req);
            }
            else {
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
            }

            self.node.destroy()
        });
    },

    //绑定google
    onBtnGoogleBindClicked(){
        
        let self = this
        cc.vv.PlatformApiMgr.startGoogleLogin((cbData)=>{
            
            let result = parseInt(cbData.result);
            if (result) {
                let userInfo = cbData.userInfo;
                let req = {c:MsgId.REQ_BIND_FACEBOOK};
                req.accesstoken = userInfo.id_token;
                req.user = userInfo.email;
                req.type = Global.LoginType.GOOGLE_LOGIN
                cc.vv.NetManager.send(req);
                self.node.active = false;
                // let userInfo = cbData.userInfo;
                // cc.vv.GameManager.reqLogin(userInfo.email, "", Global.LoginType.GOOGLE_LOGIN, "", {nick:userInfo.name, img:userInfo.img}, userInfo.id_token);
            }
            else {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_google_bind_failed);
                // cc.vv.FloatTip.show("Google Account Bind Failed!");
            }
        });
    },

    _checkLanguageVal(){
        //语言
        let tog_en = cc.find("bg/node_language/ToggleContainer/toggle1",this.node)
        tog_en.on("toggle",this.onCheckEN,this)
        let tog_ar = cc.find("bg/node_language/ToggleContainer/toggle2",this.node)
        tog_ar.on("toggle",this.onCheckAR,this)
        if(Global.language == Global.LANGUAGE.EN){
            tog_en.getComponent(cc.Toggle).check()
        }
        if(Global.language == Global.LANGUAGE.AR){
            tog_ar.getComponent(cc.Toggle).check()
        }
    },

    onCheckEN:function(tog){
        if(Global.language == Global.LANGUAGE.EN){
            return
        }
        Global.language = Global.LANGUAGE.EN
        //刷新界面
        Global.dispatchEvent(EventId.SYS_CHANGE_LANGUAGE,Global.language)
    },

    onCheckAR:function(tog){
        if(Global.language == Global.LANGUAGE.AR){
            return
        }
        Global.language = Global.LANGUAGE.AR
        //刷新界面
        Global.dispatchEvent(EventId.SYS_CHANGE_LANGUAGE,Global.language)
    },

    onBtnRepCodeClicked:function(){
        this.node.destroy()
        cc.loader.loadRes("CashHero/prefab/cdkey/cdkey",cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find("Canvas")
            }
        })
    },

    onDelAccount:function(){
        cc.vv.AlertView.show("Data cannot be retrieved after account cancellation. Do you want to continue？", ()=>{
            cc.vv.GameManager.doAccountDelete()
        }, ()=>{})
    },

    // //隐藏
    // onHideAgreement(){
    //     this.node_userAgreement.active = false;
    // },
});
