    loadPopReward(rdArr, typeWhere) {

        cc.vv.NewGuide.SetIsLoadingGuide(false)
        let self = this
        let nextCall = function () {
            if (typeWhere != 2) {
                self.checkDaiyActiveRewards()
            }
        }
        cc.vv.UserManager.loadPopReward(rdArr, nextCall)
    },

    checkDaiyActiveRewards: function () {

        //更新任务列表
        this.showTaskList()
        //更新活跃度
        let actData = this._getAcData()
        actData.activity += 10//每个任务固定10点活跃度
        if (actData.activity % 20 == 0) {
            actData.obtain_rewards.push(actData.activity / 20)//每20个活跃度设置一个奖励
        }

        //top
        if (cc.isValid(actData)) {
            this.showTaskTopInfo(this._showType, true, () => {
                // this._setTouch(false)
                if (this._activityRewards && this._activityRewards.length > 0) {
                    //this._showItemRewards(this._activityRewards,2)
                    let point = cc.find('top/point', this.node)
                    let pos = point.convertToWorldSpaceAR(cc.v2(0, 0))
                    Global.RewardFly(this._activityRewards, pos)
                }
                cc.vv.NewGuide.SetIsLoadingGuide(false)

            })
        }
        else {
            cc.vv.NewGuide.SetIsLoadingGuide(false)
        }

    },

    getTaskItemByquestid: function (id) {
        let allItems = this._listData
        for (let i = 0; i < allItems.length; i++) {
            let item = allItems[i]
            if (item.id == id) {
                return i
            }
        }
        return 0
    },

