
/**
 * 下载条幅
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_node = this.node
        Global.btnClickEvent(btn_node, this.onClickBtn, this)
    },

    start() {

    },

    onClickBtn: function () {
        Global.playComEff("ch_btn_click");
        let callbacks = function (prefab) {
            let canvas = cc.find("Canvas");
            let old = cc.find('Game_Invite', canvas)
            if (!old) {
                let node = cc.instantiate(prefab)
                node.name = 'Game_Invite'
                node.parent = canvas

            }
            else {
                old.active = true
            }
        }
        this._loadPrefab('CashHero/prefab/Game_Invite', callbacks)
    },

    _loadPrefab: function (url, callbacks) {
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                callbacks(prefab)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    // update (dt) {},
});
