/**
 * 升级提示
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _btnLevelUpParty: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClickClose, this)

        let nodeTip = cc.find('node_tip', this.node)
        Global.FixDesignScale(nodeTip)
    },

    setUIData: function (exp, coin, tipPos) {
        Global.playComEff("ch_notification");
        let self = this
        let nodeTip = cc.find('node_tip', this.node)
        if (tipPos) {
            nodeTip.position = cc.v2(tipPos.x, tipPos.y - nodeTip.scale * nodeTip.height / 2 - 10)
        }
        this.setLabelVal('node_tip/lbl_exp_req', exp)
        this.setLabelVal('node_tip/lbl_reward_next', coin)
        this.node.stopAllActions()
        this.node.active = true
        this.node.opacity = 50
        cc.tween(this.node)
            .to(0.3, { opacity: 255 })
            .delay(2)
            .to(0.5, { opacity: 0 })
            .call(() => {
                self.node.active = false
            })
            .start()
        this.setBtnLevelUpPartyVisible(Global.isExistLevelUpParty);
    },

    setLabelVal: function (lblName, val) {
        let lbl = cc.find(cc.js.formatStr('%s/lbl_val', lblName), this.node)
        if (lbl) {
            lbl.getComponent(cc.Label).string = Global.FormatNumToComma(val)
        }
    },

    onClickClose: function () {
        this.node.active = false
    },

    setBtnLevelUpPartyVisible(isVisible) {
        if (!this._btnLevelUpParty) { return; }
        this._btnLevelUpParty.active = isVisible;
        let spr_bg = cc.find('node_tip/spr_bg', this.node);
        spr_bg.height = isVisible ? 320 : 260;
    },
});
