
cc.Class({
    extends: cc.Component,

    properties: {
        uiAtlas: cc.SpriteAtlas
    },

    onLoad() {
        Global.onClick("mask", this.node, this.onClickClose, this)
        Global.playComEff("ch_popup_l2")
    },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.destroy()
    },

    init(players, data) {
        let content = cc.find("ui/list/view/content", this.node)
        let attacker = content.getChildByName("attacker")
        let defender = content.getChildByName("defender")
        Global.setLabelString("playername", attacker, players[0].playername)
        Global.setLabelString("playername", defender, players[1].playername)
        if (data.res == 1) { //攻击者胜利
            Global.setSpriteFrame("res_bg", attacker, this.uiAtlas.getSpriteFrame("stat_victory"))
            Global.setSpriteFrame("res_desc", attacker, this.uiAtlas.getSpriteFrame("txt_victory"))
            Global.setSpriteFrame("res_bg", defender, this.uiAtlas.getSpriteFrame("stat_defeat"))
            Global.setSpriteFrame("res_desc", defender, this.uiAtlas.getSpriteFrame("txt_defeat"))
        } else {
            Global.setSpriteFrame("res_bg", attacker, this.uiAtlas.getSpriteFrame("stat_defeat"))
            Global.setSpriteFrame("res_desc", attacker, this.uiAtlas.getSpriteFrame("txt_defeat"))
            Global.setSpriteFrame("res_bg", defender, this.uiAtlas.getSpriteFrame("stat_victory"))
            Global.setSpriteFrame("res_desc", defender, this.uiAtlas.getSpriteFrame("txt_victory"))
        }
        let roles = []
        for (let i = 0; i < data.formation.length; i++) {
            let roleInfo = data.formation[i]
            let pos = roleInfo.pos
            roles[pos] = { cardid: roleInfo.cardid, atk: 0, def: 0 }
        }
        for (let i = 0; i < data.rounds.length; i++) {
            let round = data.rounds[i]
            let atker = roles[round.ak.pos]
            for (let i = 0; i < round.rs.length; i++) {
                let rs = round.rs[i]
                let defer = roles[rs.pos]
                atker.atk += rs.dmg
                defer.def += rs.dmg
            }
        }
        let maxAtk = 0
        let maxDef = 0
        for (let i = 1; i <= 10; i++) {
            if (roles[i]) {
                maxAtk = Math.max(maxAtk, roles[i].atk)
                maxDef = Math.max(maxDef, roles[i].def)
            }
        }
        for (let i = 1; i <= 10; i++) {
            let item = content.getChildByName("item" + i)
            if (roles[i]) {
                let head = cc.find("head_bg/head", item)
                cc.vv.HerocardManager.loadHeroCircleHead(head, roles[i].cardid)
                Global.setLabelString("lbl_atk", item, Global.FormatNumToComma(roles[i].atk))
                Global.setLabelString("lbl_def", item, Global.FormatNumToComma(roles[i].def))
                Global.setProgress("prog_atk", item, roles[i].atk / maxAtk)
                Global.setProgress("prog_def", item, roles[i].def / maxDef)
            } else {
                item.active = false
            }
        }
    },

});
