
cc.Class({
    extends: cc.Component,

    properties: {
        _delegate: null,
        _rewards: null
    },

    onLoad() {
        Global.onClick("mask", this.node, this.onClickClose, this)
        Global.onClick("ui/win/btn_collect", this.node, this.onClickClose, this)
        Global.onClick("ui/btn_stat", this.node, this.onClickStat, this)

        let ui = cc.find("ui", this.node)
        ui.opacity = 0
        cc.tween(ui)
            .delay(0.6)
            .to(0.6, { opacity: 255 }, { easing: "sineOut" })
            .start()
    },

    init(delegate, players, result, data) {
        this._delegate = delegate
        this._players = players
        this._data = data

        let spine = cc.find("spine", this.node).getComponent(sp.Skeleton)
        if (result.res == 1) {
            spine.setSkin("Victory")
        } else {
            spine.setSkin("Defeat")
        }
        spine.setAnimation(0, "animation2", false)
        spine.addAnimation(0, "animation", true)

        let ui = cc.find("ui", this.node)
        cc.find("win", ui).active = (result.res == 1)
        cc.find("lose", ui).active = (result.res != 1)

        Global.setLabelString("lbl_rank1", ui, result.beforeRank)
        Global.setLabelString("lbl_rank2", ui, result.curRank)
        let addscore = result.addScore > 0 ? "+" + result.addScore : "" + result.addScore
        let scoreText = Global.formatString("<color=#ffffff>{0}</c> <color=#ffff00>{1}</c>", result.curScore, addscore)
        Global.setRichTextString("lbl_point", ui, scoreText)

        ui.getComponentInChildren("UserHead").setHead(cc.vv.UserManager.uid, cc.vv.UserManager.userIcon)

        if (result.res == 1) {
            this._rewards = result.rewards
            Global.playCashEff("pvp/pk_victory")
            Global.setLabelString("win/win_coin/lbl_coin", ui, Global.FormatNumToComma(result.rewards[0].count))
        } else {
            Global.playCashEff("pvp/pk_lose")
        }

        if (result.curRank != result.beforeRank && result.curRank <= 30) {
            Global.dispatchEvent("pvp_rank_refresh")
        }
    },

    showRewards(rewards) {
        return new Promise((resolve) => {
            let url = 'CashHero/prefab/pop_reward'
            let self = this
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    node.getComponent('CH_popreward').showRewards(rewards, () => {
                        resolve()
                    })
                } else {
                    resolve()
                }
            })
        })
    },

    async onClickClose() {
        if (this._closing) return
        this._closing = true
        if (this._rewards) {
            await this.showRewards(this._rewards)
        }
        this._delegate.onClose()
    },

    onClickStat() {
        let url = 'CashHero/prefab/pvp/pvp_stat'
        let self = this
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                node.getComponent('Pvp_Stat').init(self._players, self._data)
            }
        })
    }

});
