/**
 * luckycard gameover
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_giveup = cc.find('ui/btn_giveup', this.node)
        Global.btnClickEvent(btn_giveup, this.onClickGiveup, this);
        let btn_use = cc.find('ui/btn_use', this.node)
        Global.btnClickEvent(btn_use, this.onClickUse, this);

        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYCARD_RELIFE, this.OnRcvUseRelife, this);
        cc.vv.NetManager.registerMsg(MsgId.PULL_LUCKYCARD_BUYSUCCESS, this.OnRcvBuyCardRes, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYCARD_RELIFE, this.OnRcvUseRelife, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PULL_LUCKYCARD_BUYSUCCESS, this.OnRcvBuyCardRes, false, this);
    },

    start() {
        //清理红点
        cc.vv.RedSys.clearRedTip(10)

        let final = cc.find("ui", this.node)
        Global.showAlertAction(final, true, 0.1, 1)

        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_GAMEOVER)
    },

    init(mainScp) {
        this._mainScript = mainScp

        let nCard = mainScp.getReliftcard()
        this._refushUI(nCard)

    },

    _refushUI: function (nCard) {
        let lbl = cc.find('ui/spr_relife/lbl_left', this.node)
        lbl.getComponent(cc.Label).string = cc.js.formatStr('LEFT:%s', nCard)

        let btnLbl = cc.find('ui/btn_use/Background/Label', this.node)
        if (nCard) {
            btnLbl.getComponent(cc.Label).string = 'USE'
        }
        else {
            btnLbl.getComponent(cc.Label).string = 'BUY'
        }
    },

    onClickGiveup: function () {
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_GIVEUP)

        Global.playComEff("ch_btn_click");
        this._mainScript.onClickClose()
        this.node.destroy()
    },

    onClickUse: function () {


        Global.playComEff("ch_btn_click");
        let nCard = this._mainScript.getReliftcard()
        if (nCard) {
            //使用
            cc.vv.NetManager.send({ c: MsgId.REQ_LUCKYCARD_RELIFE });

            //统计
            StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_USE)
        }
        else {
            //购买
            cc.vv.NetManager.sendAndCache({ c: MsgId.REQ_LUCKYCARD_BUYLIST });

            //统计
            StatisticsMgr.reqReport(StatisticsMgr.REQ_LUCKYCARD_GAMEOVER_BUY)
        }
    },

    OnRcvUseRelife: function (msg) {
        if (msg.code == 200) {
            this.node.destroy()
        }
    },
    OnRcvBuyCardRes: function (msg) {
        if (msg.code == 200) {
            let nCard = msg.cards
            this._refushUI(nCard)
        }
    }

    // update (dt) {},
});
