/**
 * 好友搜索
 */

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        editBox: cc.EditBox,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_search = cc.find("btn_search", this.node)
        Global.btnClickEvent(btn_search, this.onClickSearch, this)


        let btn_close = cc.find("btn_close", this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)

        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, false, this);
    },

    start() {

    },

    onClickSearch: function () {
        Global.playComEff("ch_btn_click");

        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_ADDFRIENDS_SEARCH_OUT)

        if (this.editBox.string && this.editBox.string.length > 0) {
            if (parseInt(this.editBox.string) == Global.playerData.uid) {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_not_add_self);
                // cc.vv.FloatTip.show("Can not add yourself!");
                return;
            }

            let req = { c: MsgId.PERSIONAL_INFO };
            req.otheruid = this.editBox.string
            req.act = 1 //标识来自好友搜索
            cc.vv.NetManager.send(req);

        }
        else {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_enter_userID);
            // cc.vv.FloatTip.show("Please Enter User ID!");
        }
    },

    onRcvPersonInfo: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode) {
                this.editBox.string = ""
                return
            }
            if (msg.act == 1) {
                this.node.destroy()
            }
        }
    },

    onClickClose: function () {
        this.node.destroy()
    }

    // update (dt) {},
});
