/**
 * 大厅转盘
 */
cc.Class({
    extends: cc.Component,

    properties: {
        // prefab_coin : cc.Prefab,

        _nextTime: 0,    //距下次奖励时间
        _nextType: 1,    //下次奖励类型： 1收集金币 2免费大转盘 3命运大转盘
        _nowType: 1,     //当前奖励类型： 1收集金币 2免费大转盘 3命运大转盘
        _userCoin: 0,    //玩家金币
    },

    // LIFE-CYCLE CALLBACKS:

    start() {
        // this.sendTurntableStateReq();
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_TURNTABLE_STATE, this.onRcvNetWheelState, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SPINE_RESULT, this.onRcvGetSpineResult, this);
        cc.vv.NetManager.registerMsg(MsgId.PULL_RED_NOTICE, this.onRcvGetCanShowWheel, this);
        Global.registerEvent(EventId.CHANGE_HALLTAB, this.OnEventChangeHallTab, this)
        // cc.game.on(cc.game.EVENT_SHOW, this.onEnterFront, this);
        // this.btn_collect = this.node.getChildByName('btn_collect');
        // // this.btn_collect.getComponent(cc.Button).interactable = true;
        // this.node.getComponent(cc.Button).interactable = false;
    },

    // //切回前台
    // onEnterFront:function(){
    //     this.sendTurntableStateReq()
    // },

    //刷新转盘状态
    sendTurntableStateReq: function () {
        var req = { 'c': MsgId.REQ_GET_TURNTABLE_STATE };
        req.uid = Global.playerData.uid;
        cc.vv.NetManager.sendAndCache(req, true);
    },

    //收到大厅转盘状态
    onRcvNetWheelState: function (msg) {
        if (msg.code == 200) {
            //hy
            // msg.data.time = 0
            // msg.data.nextType = 2
            if (msg.data) {
                let data = msg.data;
                this._lastMsg = msg
                this._nextTime = data.time;
                // this._nextType = data.nextType;
                // this._nowType = this._nextType;
                this._coinrewsard = data.coin || 0;
                this.showWheelUI();
                // this.unschedule(this.showDiscountTime);
            }
        }
    },

    //获取转盘结果
    onRcvGetSpineResult: function (msg) {
        if (!cc.isValid(this.node)) {
            return
        }
        if (msg.code === 200) {
            if (msg.spcode && msg.spcode === 450) {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_eligible_receive);
                // cc.vv.FloatTip.show('Not eligible to receive');
            }
            else {
                this._nextTime = msg.nextTime;
                // this._nextType = msg.nextType;
                this._userCoin = msg.user.coin;
                this._addCoin = msg.addCoin
                cc.vv.UserManager.coin = this._userCoin
                // if(this._nowType === 1){
                // this._nowType = this._nextType;
                this.showCollectResult();
                // }
            }
        }
    },

    //显示转盘ui
    showWheelUI() {
        let self = this
        // self.bCanShow = true
        self._bDoing = null
        let node_wheel = cc.find('hallWheel', this.node)
        if (!node_wheel) {
            cc.loader.loadRes('CashHero/prefab/hallWheel', cc.Prefab, (err, asset) => {
                if (!err) {
                    let curTab = cc.vv.UserManager.getHallTab()
                    if (curTab == 2) {
                        let old = cc.find('hallWheel', self.node)
                        if (!old) {
                            node_wheel = cc.instantiate(asset)
                            node_wheel.parent = self.node
                            node_wheel.active = true
                            self.showByTime(node_wheel)
                        }
                    }
                }
            })
        }
        else {
            let curTab = cc.vv.UserManager.getHallTab()
            if (curTab == 2) {
                node_wheel.active = true
                self.showByTime(node_wheel)
            }
        }
        // let img_wheel = this.node.getChildByName('img_wheel');
        // let timg_bg = this.node.getChildByName('time_bg');
        // let lbl_time = this.node.getChildByName('lbl_time');
        // lbl_time.getComponent(cc.RichText).string = '';
        // // lottery.getComponent(cc.Button).interactable = false;
        // cc.tween(img_wheel)
        //     .repeatForever(cc.tween().by(3, {angle:360}))
        //     .start();
        // if(this._nextTime === 0){//可以抽奖
        //     timg_bg.active = false;
        //     lbl_time.active = false;
        //     this.btn_collect.active = true;
        //     // this.btn_collect.getComponent(cc.Button).interactable = true;
        //     this.node.getComponent(cc.Button).interactable = true;
        // }
        // else {
        //     timg_bg.active = true;
        //     lbl_time.active = true;
        //     this.btn_collect.active = false;
        //     this.node.getComponent(cc.Button).interactable = false;
        //     this.schedule(this.showDiscountTime,1)
        // }
    },

    showByTime: function (nodeWheel) {
        let bigWheel = cc.find('wheel', nodeWheel)
        let smallWheel = cc.find('node_cd', nodeWheel)
        if (this._nextTime == 0) {
            //可以领取
            bigWheel.active = true
            smallWheel.active = false
            this.btn_collect = bigWheel.getChildByName('btn_collect');
            this.btn_collect.getComponent(cc.Button).interactable = true;
            this.btn_collect.off('click', this.onClickLottery, this)
            Global.btnClickEvent(this.btn_collect, this.onClickLottery, this)
            this.showCanCollectFreeCoin()
        }
        else {
            //倒计时
            bigWheel.active = false
            smallWheel.active = true
            this.showDiscountTime()
            this.unschedule(this.showDiscountTime, this)
            this.schedule(this.showDiscountTime, 1)
        }
    },

    //可以领取免费金币的时候，有个collect和金币切换的动画
    showCanCollectFreeCoin: function () {
        let bShowCoin = false
        if (this._coinrewsard) {
            bShowCoin = true
        }
        let aniCollect = cc.find('btn_ani/ani_collect', this.btn_collect)
        let coin = cc.find('btn_ani/coin', this.btn_collect)
        aniCollect.active = true
        aniCollect.opacity = 255
        coin.active = false
        coin.opacity = 255
        if (!bShowCoin) {
            return
        }
        let val = cc.find('lbl_val', coin)
        val.getComponent(cc.Label).string = Global.FormatNumToComma(this._coinrewsard)
        this.btn_collect.stopAllActions()
        cc.tween(this.btn_collect)
            .repeatForever(
                cc.tween()
                    .call(() => {
                        aniCollect.opacity = 0
                        cc.tween(aniCollect)
                            .to(0.2, { opacity: 255 })
                            .start()
                        coin.opacity = 255
                        coin.active = true
                        cc.tween(coin)
                            .to(0.2, { opacity: 0 })
                            .start()
                    })
                    .delay(3)
                    .call(() => {
                        aniCollect.opacity = 255
                        cc.tween(aniCollect)
                            .to(0.2, { opacity: 0 })
                            .start()
                        coin.opacity = 0
                        cc.tween(coin)
                            .to(0.2, { opacity: 255 })
                            .start()
                    })
                    .delay(3)
            )
            .start()
    },

    // //显示倒计时
    // showCDUI:function(bShow){
    //     let node_wheel = cc.find('hallWheel',this.node)
    //     let bigWheel = cc.find('wheel',node_wheel)
    //     bigWheel.active = false
    //     let node_cd = cc.find('hallWheel/node_cd',this.node)
    //     if(node_cd){
    //         node_cd.active = bShow
    //     }
    //     if(bShow){
    //         node_wheel.active = true
    //         this.schedule(this.showDiscountTime.bind(this),1)
    //     }
    //     else{
    //         this.unschedule(this.showDiscountTime,this)
    //     }
    // },

    //显示倒计时
    showDiscountTime: function () {
        let node_cd = cc.find('hallWheel/node_cd', this.node)
        if (cc.isValid(node_cd, true)) {
            let lblTime = cc.find('lbl_text', node_cd)
            if (cc.isValid(lblTime, true)) {
                lblTime.getComponent(cc.Label).string = Global.formatSec(this._nextTime)
                --this._nextTime
                if (this._nextTime < 0) {
                    this.unschedule(this.showDiscountTime, this)
                    this.sendTurntableStateReq()
                }
            }
        }
        // let timg_bg = this.node.getChildByName('time_bg');
        // let lbl_time = this.node.getChildByName('lbl_time');
        // lbl_time.getComponent(cc.RichText).string = cc.js.formatStr('NEXT IN <color=#ffff00>%s</color>',Global.formatSec(this._nextTime));
        // if (this._nextTime <= 0){
        //     this.unschedule(this.showDiscountTime);
        //     timg_bg.active = false;
        //     lbl_time.active = false;
        //     this.btn_collect.active = true;
        //     // this.btn_collect.getComponent(cc.Button).interactable = true;
        //     this.node.getComponent(cc.Button).interactable = true;
        // }
        // --this._nextTime;
    },

    //转盘
    onClickLottery(event) {
        Global.playComEff("ch_btn_click");
        //新手礼包领取了才能点
        if (cc.vv.UserManager.initgift) {
            return
        }
        this.btn_collect.getComponent(cc.Button).interactable = false;
        // this.btn_collect.getChildByName('btn_ani').active = false
        if (this._bDoing) return
        this._lastMsg = null
        this._bDoing = true
        // console.log('this._nextType:',this._nextType)
        // if(this._nextType === 1){//收集金币
        // this.sendGetReq(this._nextType);
        //大厅仅收集金币
        this.sendGetReq(1);
        // } 
        // else if(this._nextType === 2){//免费转盘
        //     let self = this;
        //     let fatherNode = this.node.parent;
        //     cc.loader.loadRes("CashHero/prefab/prize_wheel/prize_wheel",cc.Prefab, (err, prefab) => {
        //         if (!err) {
        //             if(!fatherNode.getChildByName('prize_wheel')){
        //                 let node = cc.instantiate(prefab);
        //                 node.parent = fatherNode
        //             }
        //             self.showWheelNode(false)
        //             // self.bCanShow = false
        //         }
        //         else{
        //             console.log('未找到资源')
        //         }
        //     });
        // }
    },

    //显示领取结果
    showCollectResult: function () {
        // let hall = cc.find('Canvas').getComponent('hall');
        // if(hall){
        //     hall.updateCoin(this._userCoin, true);
        // }
        let self = this;
        let endCall = function () {
            self._bDoing = null
            self.showWheelNode(false)
            // self.bCanShow = false
            Global.dispatchEvent(EventId.UPATE_COINS)
            self.sendTurntableStateReq()
            //引导进入游戏
            cc.vv.NewGuide.ShowGuide(1)
        }
        let pos = this.btn_collect.convertToWorldSpaceAR(cc.v2(0, 0))
        Global.RewardCoinFly(self._addCoin, pos, endCall)
        // let srcObj = this.btn_collect
        // let endNode = cc.find(Global.HALL_COIN_NODE_PATH); 
        // let rollLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        // let rollData={lblCoin:rollLbl, addCoin:self._addCoin}
        // Global.FlyCoin(srcObj,endNode,endCall,rollData, true)
        // let coinPre = cc.find('Canvas/node_lobby/flycoins');
        // let endNode = cc.find("Canvas/node_lobby/node_top/spr_bg/spr_coin/img_coin");
        // let endPos = coinPre.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0,0)));
        // let startPos = coinPre.convertToNodeSpaceAR(this.btn_collect.convertToWorldSpaceAR(cc.v2(0,0)));
        // let flyCoins = coinPre.getComponent("FlyCoins")
        // if(flyCoins){
        //     flyCoins.showFlyCoins(startPos,endPos,20,endCall);
        // }
    },

    //
    onRcvGetCanShowWheel: function (msg) {
        if (msg.code == 200) {
            if (msg.turntable == 1) {
                this.showWheelUI()
            }
        }
    },

    showWheelNode: function (bShow) {
        let node = cc.find('hallWheel', this.node)
        if (node && node.active != bShow) {
            node.active = bShow
            let collect_btn = cc.find('wheel/btn_collect', node)
            if (collect_btn) {
                collect_btn.getComponent(cc.Button).interactable = true
                collect_btn.getChildByName('btn_ani').active = true
            }
        }
    },

    //发送领取转盘奖励协议
    //@param rtype  1.收集金币 2免费转盘 3收费转盘
    sendGetReq: function (rtype) {
        var req = { 'c': MsgId.REQ_GET_SPINE_RESULT };
        req.uid = Global.playerData.uid;
        req.rtype = rtype;
        cc.vv.NetManager.send(req);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_TURNTABLE_STATE, this.onRcvNetWheelState, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SPINE_RESULT, this.onRcvGetSpineResult, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PULL_RED_NOTICE, this.onRcvGetCanShowWheel, false, this)
    },

    OnEventChangeHallTab: function (data) {
        let val = data.detail
        if (val == 2) {
            if (this._lastMsg && this._nextTime == 0) {
                //没领取的，直接领取
                this.onRcvNetWheelState(this._lastMsg)
            }
            else {
                this.sendTurntableStateReq()
            }
        }
        else {
            this.showWheelNode(false)
        }
    }

    // update (dt) {},
});
