cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        pointSpine: {
            default: null,
            type: sp.Skeleton,
        },

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnCollect = cc.find('btnCollect', this.node)
        Global.btnClickEvent(btnCollect, this.onClickCollect, this)

        Global.btnClickEvent(cc.find('spr_bg/btn_confirm', this.node), this.onClickConfirm, this);
        Global.playComEff("ch_popup_l2");

        this.boxNode = cc.find('box', this.node)

        this.msgData = null
        this.msgCoin = null
        this._clickFlag = true
    },

    start() {
        Global.FixDesignScale_V(this.node)
    },

    setRd(msg) {
        if (msg) {
            this.msgCoin = msg.rewardCoin
            this.msgData = this.dataAllSort(msg.rewards)
            //初始化
            this.initReward(this.msgData)
            //设置动画
            this.setSpine()
        }
    },

    setSpine() {
        let track = this.pointSpine.setAnimation(0, 'animation2', false);
        if (track) {
            this.pointSpine.setCompleteListener((trackEntry, loopCount) => {
                let name = trackEntry.animation ? trackEntry.animation.name : '';
                if (name === 'animation2') {
                    this.pointSpine.active = false
                }
            });
        }
        this.node.runAction(cc.sequence(cc.delayTime(0.7),
            cc.callFunc(function () {
                this.boxNode.active = true
            }, this)
        ))
    },

    //数据清洗 卡牌8 全部靠后 金币第一
    dataAllSort(data) {
        let sorFunc = function (a, b) {
            let aVal = 0
            if (a.type == Global.PROP_ID.COIN) {
                aVal = 1
            }
            let bVal = 0
            if (b.type == Global.PROP_ID.COIN) {
                bVal = 1
            }

            if (aVal != bVal) {
                return bVal - aVal
            }
            else {
                aVal = 0
                if (a.type == Global.PROP_ID.HERO_CARD) {
                    aVal = 1
                }
                bVal = 0
                if (b.type == Global.PROP_ID.HERO_CARD) {
                    bVal = 1
                }
                if (aVal != bVal) {
                    return aVal - bVal
                }
                else {
                    return a.type < b.type
                }
            }

        }
        data.sort(sorFunc)
        return data;
    },

    getCardNum(rds) {
        let count = 0
        for (let i = 0; i < rds.length; i++) {
            if (rds[i].type == Global.PROP_ID.HERO_CARD) {
                count += rds[i].count
            }
        }
        return count
    },

    initReward(msg) {
        let cardNum = this.getCardNum(msg)
        let children = this.boxNode.children
        for (let i = 0; i < children.length; i++) {
            children[i].active = false
            if (msg[i]) {
                children[i].active = true
                // let _type = msg[i].type == Global.PROP_ID.COIN? 5:msg[i].type
                let _count = msg[i].type == Global.PROP_ID.HERO_CARD ? cardNum : msg[i].count
                children[i].getComponent("CH_RewardItem").init(msg[i].type, _count, true, true)
            }
        }
    },

    getMsg() {
        if (this.msgData) {
            return this.msgData
        }
        return null
    },

    //去除id = 1
    dataSort(data) {
        var rewardArray = []
        for (let index = 0; index < data.length; index++) {
            if (data[index].type == Global.PROP_ID.COIN) {
                continue
            }
            rewardArray.push(data[index])
        }
        return rewardArray
    },

    //弹出小奖励
    popReward(msg) {
        this.node.active = false
        //清洗数据
        // let rewardArray = this.dataSort(msg)
        let rd = msg
        let rdArray = []
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.COIN) {
                continue
            } else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD) {
                rdArray.push(rd[i])
            } else {
                Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: rd[i].type, num: rd[i].count })
            }
        }

        if (rdArray.length > 0) {
            let url = 'CashHero/prefab/pop_reward'
            let self = this
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    let endCall = function () {
                        node.destroy()
                        self.closeDailyBonus()
                    }
                    node.getComponent('CH_popreward').showRewards(rdArray, endCall)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        } else {
            this.closeDailyBonus()
        }
    },

    //关闭bonus
    closeDailyBonus() {
        this.nodeDestroy()
    },

    onClickCollect() {
        if (!this._clickFlag) {
            return
        }
        cc.find('btnCollect', this.node).getComponent(cc.Button).interactable = false
        this._clickFlag = false


        let self = this
        let flyEndCall = function () {
            self.popReward(self.getMsg())
        }
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH) || cc.find(Global.INGAME_COIN_LABEL_NODE_PATH);
        rollData.addCoin = this.msgCoin

        let toNode = cc.find(Global.HALL_COIN_NODE_PATH)
        if (!toNode) {
            toNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
        }

        Global.FlyCoin(cc.find('item1/bottom/label', this.boxNode), toNode, flyEndCall, rollData, true)
    },

    nodeDestroy() {
        Global.playComEff("ch_close");
        this.node.destroy()
    },
    // update (dt) {},
});
