/**
 * 引导模式显示的提示框
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _curGuideId:null,
        _curGuideCfg:null,
        _nodeRole:null,
        _nodeText:null,
        _bCanNext:null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._nodeRole = cc.find('node_content/node_role',this.node)
        this._nodeText = cc.find('node_content/node_text/bg1/text_lbl',this.node)
        let node_bg = cc.find('lay_bg',this.node)
        Global.btnClickEvent(node_bg,this.onClickEmpty,this)
        Global.FixDesignScale_V(this.node);
    },

    start () {
        this._showUI()
    },

    ShowMsg:function(id,guideCfg){
        this._curGuideId = id
        this._curGuideCfg = guideCfg
        
        I18N.setI18nLabel(this._nodeText,cc.vv.Language[guideCfg.lbl],guideCfg.lblParm)
        // this._nodeText.getComponent(cc.RichText).string = cc.vv.Language[guideCfg.lbl]
        
    },

    ShowStr:function(str,endCall){
        this._nodeText.getComponent(cc.RichText).string = str
        this._endCall = endCall
    },

    onClickEmpty:function(){
        Global.playComEff("ch_btn_click");
        if(this._bCanNext){
            if(this._curGuideId){
                cc.vv.NewGuide.SaveCompleteGuide(this._curGuideId)
            }
            if(this._endCall){
                this._endCall()
            }
            this.node.destroy()
            
        }
    },

    _showUI:function(){
        this._rolePos = this._nodeRole.position
        this._nodeRole.x = this._rolePos.x - 300
        cc.tween(this._nodeRole)
        .to(0.3,{position:this._rolePos})
        .start()

        this._nodeText.opacity = 0
        cc.tween(this._nodeText)
        .to(0.4,{opacity:255})
        .call(()=>{
            this._bCanNext = true
            cc.vv.NewGuide.SetIsLoadingGuide(false)
        })
        .start()


    },

    // update (dt) {},
});
