        //this._node_gift_welcome.active = this._welcome_gift_time > 0;
        Global.btnClickEvent(this._node_gift_welcome.getChildByName("content"), this.onClickGiftWelcome, this);

        //Money Bank
        this._node_pig_bank = cc.find("gift_bank", content)


