    //每日礼包
    initDailyGift(data) {
        let bHas = cc.vv.UserManager.isHaveSliverHarm()
        // cc.vv.UserManager.setSliverHarm(data.status)
        if (!bHas) {
            this._node_daily_gift.active = false
        } else {
            // this._node_daily_gift.active = true
            let t = 0.04
            let pack_icon = cc.find("titlebg/icon", this._node_daily_gift)
            pack_icon.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(1.5, 1.25), cc.rotateTo(t, 15), cc.rotateTo(t * 2, -15), cc.rotateTo(t * 2, 15), cc.rotateTo(t * 2, -15), cc.rotateTo(t * 2, 15), cc.rotateTo(t, 0), cc.scaleTo(0.75, 1))))

            //total coin
            Global.setLabelString('content/rewards/lbl_num', this._node_daily_gift, Global.FormatNumToComma(data.coin + data.vipCoin))
            let x_arrow = cc.find("content/guang2", this._node_daily_gift)
            Global.ArrowAction(x_arrow, cc.v2(-10, 0), 0.5)
            let lv = cc.vv.UserManager.getVipLevel()
            //vip current
            let node_cur = cc.find("content/vip_cur", this._node_daily_gift)
            cc.find("vip", node_cur).getComponent("CH_Vipicon").showVip(lv)
            Global.setLabelString("lbl_add", node_cur, cc.js.formatStr("+%s% Coins", Global.VIP_INFO[lv].store * 100))

            //vip next
            let node_next = cc.find("content/vip_next", this._node_daily_gift)
            if (lv > 7) {
                //超出vip max
                node_next.active = false
                return
            }
            cc.find("vip", node_next).getComponent("CH_Vipicon").showVip(lv + 1)
            Global.setLabelString("lbl_add", node_next, cc.js.formatStr("+%s% Coins", Global.VIP_INFO[lv + 1].store * 100))

        }
    },

