    //初始化钻石
    initDiamond(data) {
        let self = this
        if (data) {
            this._diamondData = data
            this._diamondData.sort((a, b) => { return a.amount - b.amount; });
            let label_0 = ["200%", "200%", "200%", "200%", "200%", "200%"];
            for (let i = 0; i < 6; i++) {
                let item = cc.find('gold/gold_item' + (i + 1), this._node_diamond)
                let itemData = data[i]
                if (!itemData) {
                    continue;
                }
                let bFree = itemData.free

                let bfirst = (itemData.type === 2)
                let count = bfirst ? Math.round(itemData.count / 2) : itemData.count;
                let lbl_coin = cc.find("card/lbl_num", item)
                lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(count);
                lbl_coin.y = bfirst ? -219 : -260

                let lbl_price = cc.find("card/lbl_price", item)
                lbl_price.active = true
                let lbl_freetime = cc.find("card/lbl_freetime", item)
                if (lbl_freetime) {
                    lbl_freetime.active = false
                }

                let bIconGray = false
                let priceStr = "$ " + itemData.amount
                if (bFree) {
                    priceStr = "Free"
                    if (itemData.timeout) {
                        bIconGray = true
                        //有免费冷却时间
                        lbl_price.active = false
                        if (lbl_freetime) {
                            lbl_freetime.active = true
                            lbl_freetime.getComponent("ReTimer").setReTimer(itemData.timeout, 1, () => {
                                self.reqPurchaseList()
                            })
                        }


                    }
                }
                lbl_price.getComponent(cc.Label).string = priceStr;
                Global.showSpriteGray(cc.find("card/icon", item), bIconGray)

                cc.find("card/text_extra", item).active = bfirst
                let lbl_extra_val = cc.find("card/lbl_extra_num", item)
                lbl_extra_val.active = bfirst
                if (bfirst) {
                    lbl_extra_val.getComponent(cc.Label).string = Global.FormatNumToComma(count);
                }

                let spr_tag = cc.find("card/spr_tag", item)
                spr_tag.active = bfirst && !bFree
                let val = cc.find('lbl_val', spr_tag)
                if (val) {
                    val.getComponent(cc.Label).string = label_0[i]
                }


                cc.find('card/vip_bg', item).active = !bFree
                if (!bFree) {
                    //奖励列表
                    for (let j = 0; j < 3; j++) {
                        let rewardItem = cc.find('card/vip_bg/vip_icon' + j, item)
                        rewardItem.getComponent('CH_RewardItem').init(itemData.rewards[j].type, itemData.rewards[j].count, true)
                    }


                    let benifistBtn = cc.find('card/vip_bg/btn_quest', item)
                    benifistBtn.getComponent('CH_Benifist_Btn').showBenifist(itemData.rewards, 'diamond:' + i)
                }


                item.off('click', this.onClickDiamondItem, this)
                item.on('click', this.onClickDiamondItem, this)

            }

        }

    },

