    //1 金币节点晃动
    playSwingAnim(nType = 1) {
        for (let i = 0; i < 6; i++) {
            let obj = this._gold_items[i]
            if (nType == 2) {
                obj = cc.find('gold/gold_item' + (i + 1), this._node_diamond)
            }

            let card = obj.getChildByName("card");
            card.stopAllActions();
            card.angle = 2.5;
            let dt = 0.02;
            card.runAction(cc.sequence(cc.rotateTo(dt * 10, 5).easing(cc.easeSineInOut()),
                cc.rotateTo(dt * 10, -3).easing(cc.easeSineInOut()),
                cc.rotateTo(dt * 9, 2).easing(cc.easeSineInOut()),
                cc.rotateTo(dt * 8, -1).easing(cc.easeSineInOut()),
                cc.rotateTo(dt * 7, 0).easing(cc.easeSineIn())));
        }
    },

    reqPurchaseList(sType) {


        var req = { 'c': MsgId.REQ_SHOP_EX };
        req.platform = 1;
        if (Global.isIOS()) {
            req.platform = 2
        }
        req.gameid = 0;
        req.posid = Global.SHOP_POS_ID.HALL;
        let reqStr = "1,2,8,14,15,16,25"; //(1商城 2限时优惠one_time_pass 3转盘 4激励礼包 5等级礼包special_offer 6签到 7首充礼包 8onetimeonly 9排行榜时榜 10金猪money_bank 13成长基金 14周卡 15月卡,16春季礼包)，17每日礼包，25钻石 多个类型用逗号隔开
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.PIG_BANK)) {
            reqStr += ',10'
        }
        if (cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_SMASH)) {
            reqStr += ',17'
        }
        // //目前成长基金先关闭
        // if(cc.vv.UserManager.isOpen(80)){
        //     reqStr += ',13'
        // }

        req.stype = reqStr
        if (sType) {
            req.stype = sType
        }
        if (this._bRefushReq) {
            this._bRefushReq = null
            cc.vv.NetManager.send(req, true)
        }
        else {
            cc.vv.NetManager.sendAndCache(req, true);
        }

    },

