    onRcvShopList(msg) {
        if (msg.code === 200) {
            if (!msg.type) {
                return
            }
            this._bHasinit = true
            this._tabCoin = []
            this._tabSale = []
            this._tabDiamond = []

            if (msg.shoplist["data13"]) {
                this._tabSale.push(this._node_gift_fund)
                this.initGiftFund(msg.shoplist["data13"][0])
            } else {
                this._node_gift_fund.active = false;
            }

            if (msg.shoplist["data1"]) { //金币
                this._tabCoin.push(this._node_goldcoin)
                this._gold_data = msg.shoplist["data1"];
                this._gold_data.sort((a, b) => { return a.amount - b.amount; });
                this.initShopList();
            }
            if (msg.shoplist["data2"]) {  //限时优惠
                this._tabSale.push(this._node_gift_limit)
                this.initGiftLimit(msg.shoplist["data2"][0]);
            } else {
                this._node_gift_limit.active = false;
            }
            if (msg.shoplist["data8"]) { //one time only
                this._tabSale.push(this._node_gift_welcome)
                this.initGiftWelcome(msg.shoplist["data8"][0]);
            }
            else {
                this._node_gift_welcome.active = false;
            }
            if (msg.shoplist["data10"] && cc.vv.UserManager.isOpen(Global.SYS_OPEN.PIG_BANK)) {
                this._tabSale.push(this._node_pig_bank)
                this.initPigBank(msg.shoplist["data10"][0])
            }
            else {
                this._node_pig_bank.active = false
            }
            if (msg.shoplist["data" + Stype.WEEK_CARD]) { //week card
                this._tabSale.push(this._node_week_card)
                this.initWeekCard(msg.shoplist["data" + Stype.WEEK_CARD][0]);
            }
            else {
                this._node_week_card.active = false
            }
            if (msg.shoplist["data" + Stype.MONTH_CARD]) { //month card
                this._tabSale.push(this._node_month_card)
                this.initMonthCard(msg.shoplist["data" + Stype.MONTH_CARD][0]);
            }
            else {
                this._node_month_card.active = false
            }

            if (msg.shoplist["data16"]) {
                this._tabSale.push(this._node_spring_gift)
                this.initSpringGift(msg.shoplist["data16"])
            }
            else {
                this._node_spring_gift.active = false
            }
            let bHasHummer = cc.vv.UserManager.isHaveSliverHarm()
            if (msg.shoplist["data17"] && bHasHummer) {
                this._tabSale.push(this._node_daily_gift)
                this.initDailyGift(msg.shoplist["data17"])
            } else {
                this._node_daily_gift.active = false
            }
            // if(msg.shoplist["data5"]){//if (this._grade_gift_time > 0) {
            //     this._tabSale.push(this._node_gift_grade)
            //     this.initGiftGrade(msg.shoplist["data5"][0])
            // }
            // else{
            //     this._node_gift_grade.active = false
            // }
            if (msg.shoplist["data25"]) {
                this._tabDiamond.push(this._node_diamond)
                this.initDiamond(msg.shoplist["data25"])
            }
            else {
                this._node_diamond.active = false
            }
            if (!this._curTab) {
                let showTab = cc.vv.UserManager.getEnterHallAction()
                if (showTab == 'Shop_Coin') {
                    //显示Coin页面
                    this.onShowTab("Sale", false)
                    this.onShowTab("Diamond", false)
                    this.onShowTab("Coin", true)
                    cc.vv.UserManager.setEnterHallAction(null)
                    let scroll = cc.find("list_shop", this.node).getComponent(cc.ScrollView)
                    scroll.stopAutoScroll()
                    scroll.scrollToBottom(1.5)
                    this.playSwingAnim();
                }
                else if (showTab == 'Shop_Diamond') {

                    this.onShowTab("Sale", false)
                    this.onShowTab("Coin", false)
                    this.onShowTab("Diamond", true)
                    cc.vv.UserManager.setEnterHallAction(null)
                    let scroll = cc.find("list_shop", this.node).getComponent(cc.ScrollView)
                    scroll.stopAutoScroll()
                    scroll.scrollToBottom(1.5)
                    this.playSwingAnim(2)
                }
                else {
                    this.onShowTab("Coin", false)
                    this.onShowTab("Diamond", false)
                    this.onShowTab("Sale", true)
                }
            }


        }
    },

