    onShowTab: function (tab, bShow) {
        let tarNode
        if (tab == "Sale") {
            tarNode = this._togSale
            this._bSelSale = bShow
            this._onClickToggle(tab, this._bSelSale)
        }
        if (tab == "Coin") {
            tarNode = this._togCoin
            this._bSelCoin = bShow
            this._onClickToggle(tab, this._bSelCoin)
        }
        if (tab == "Diamond") {
            tarNode = this._togDiamond
            this._bSelDiamond = bShow
            this._onClickToggle(tab, this._bSelDiamond)
        }
        let nodeArr = cc.find('node_arrow', tarNode)
        cc.tween(nodeArr)
            .to(0.2, { angle: bShow ? -90 : 0 })
            .start()
    },

    onClickToggleSale: function () {
        this._bSelSale = !this._bSelSale
        Global.playComEff("ch_tab");
        this.onShowTab("Sale", this._bSelSale)

        if (this._bSelSale) {
            this._scrollToObj(this._togSale)
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_TABSALE)
        }
    },

    onClickToggleCoin: function () {
        this._bSelCoin = !this._bSelCoin
        Global.playComEff("ch_tab");
        this.onShowTab("Coin", this._bSelCoin)

        if (this._bSelCoin) {
            this.playSwingAnim();
            this._scrollToObj(this._togCoin)

            StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_TABCOIN)
        }

    },

    onClickDiamond: function () {
        this._bSelDiamond = !this._bSelDiamond
        Global.playComEff("ch_tab");

        this.onShowTab("Diamond", this._bSelDiamond)

        if (this._bSelDiamond) {
            this.playSwingAnim(2);
            this._scrollToObj(this._togDiamond)

            StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_TABDIAMOND)
        }
    },

    _scrollToObj: function (obj) {
        this._togCoin.parent.getComponent(cc.Layout).updateLayout()
        let scroll = cc.find("list_shop", this.node).getComponent(cc.ScrollView)
        scroll.stopAutoScroll()
        //-200是为了停留在一个合适的点击位置
        scroll.scrollToOffset(cc.v2(0, -obj.y - 200), 1)
    },

    _onClickToggle: function (tabVal, bShow) {

        if (bShow) {
            this._curTab = tabVal
        }

        let arr
        if (tabVal == "Sale") {
            arr = this._tabSale
        }
        if (tabVal == "Coin") {
            arr = this._tabCoin
        }
        if (tabVal == "Diamond") {
            arr = this._tabDiamond
        }
        for (let i = 0; i < arr.length; i++) {
            let item = arr[i]
            item.active = bShow
        }


    },

