    onRcvNetFreeShopReward: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode) {
                cc.vv.FloatTip.show("Rewards received today!");
                return
            }
            let id = msg.id
            if (msg.addCoin) {
                //免费金币
                let tar = cc.find("gold/gold_item1", this._node_goldcoin)
                let pos = tar.convertToWorldSpaceAR(cc.v2(0, 0))
                Global.RewardCoinFly(msg.addCoin, pos, () => {
                    cc.vv.UserManager.SetCoin(msg.coin)
                })

            }
            else {
                //免费钻石
                let tar = cc.find("gold/gold_item1", this._node_diamond)
                let pos = tar.convertToWorldSpaceAR(cc.v2(0, 0))
                Global.RewardPropFly(Global.PROP_ID.DIAMOND, msg.addDiamond, pos, () => {
                    //
                    cc.vv.UserManager.setDiamond(msg.diamond)
                })
            }

            this.reqPurchaseList()
        }
    }


