const List = require('List');
let CardTaskType = {
    Unlock: 1,  // 解锁卡牌
    StarLevel: 2,  // 卡牌升星
    CardLevel: 3,  // 卡牌等级
    UnlockSlots: 4, //解锁游戏
}

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _delegate: null,
        _cardInfo: null,
        _tasks: null,
        listview: List,
        _allCompletedFlag: false
    },

    onLoad() {
        Global.onClick("bg/btn_close", this.node, this.onClickClose, this)
        Global.onClick("bg/btn_collectall", this.node, this.onClickCollectAll, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_CARD_TASK_INFO, this.onRcvCardTaskInfo, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_CARD_TASK_REWARD, this.onRcvCardTaskReward, this)

        Global.playComEff("ch_popup_l2")
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_CARD_TASK_INFO, this.onRcvCardTaskInfo, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_CARD_TASK_REWARD, this.onRcvCardTaskReward, false, this)

        Global.dispatchEvent('Herocard_Task_Close')
    },

    start() {

    },

    init(delegate, cardInfo, fromWhere) {
        this._delegate = delegate
        this._cardInfo = cardInfo
        this._fromWhere = fromWhere

        let req = { c: MsgId.REQ_CARD_TASK_INFO, cardid: cardInfo.cardid }
        cc.vv.NetManager.send(req)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_REWARDS_POP, this._fromWhere + '|' + this._cardInfo.cardid)
    },

    initTaskItem(item, task) {
        /*
            id=1,
            type= CardTaskType,
            cnt=1, 
            currCnt = 1,  // 当前完成的进度
            rewards={}, 
            status=0 -- 0: 未完成, 1: 已完成, 2: 已领取
            */
        item.name = "" + task.id
        cc.find("icon_gou", item).active = (task.status == 2)
        let btnGo = cc.find("btn_go", item)
        btnGo.active = (task.status != 2)
        btnGo.off("click")
        if (task.status == 0) {
            Global.setLabelString("lbl_desc", btnGo, cc.vv.Language.btn_go/*"GO"*/)
            btnGo.on("click", this.onClickGo, this)
        } else if (task.status == 1) {
            Global.setLabelString("lbl_desc", btnGo, cc.vv.Language.btn_collect/*"COLLECT"*/)
            btnGo.on("click", this.onClickCollect, this)
        }
        Global.setLabelString("lbl_prog", btnGo, task.currCnt + "/" + task.cnt)

        //初始化
        this._initNode(item)

        let str = ""
        let args = ""
        if (task.type == CardTaskType.Unlock) {
            str = cc.vv.Language.herocard_task_tit2 // "UNLOCK HERO"
            this._setRewards(item, task)
        } else if (task.type == CardTaskType.StarLevel) {
            str = cc.vv.Language.herocard_task_tit3 //"EVOLVE TO STAR."+task.cnt
            args = task.cnt
            if (task.rewards.length > 1) {
                this._setRewards(item, task)
            } else {
                this._evolveReward(item, task)
            }
        } else if (task.type == CardTaskType.CardLevel) {
            str = cc.vv.Language.herocard_task_tit4 //"UPGRADE TO LEVEL." + task.cnt
            args = task.cnt
            this._setRewards(item, task)
        } else if (task.type == CardTaskType.UnlockSlots) {
            str = cc.vv.Language.herocard_task_tit1 //"UNLOCK HERO'S SLOT"
            this._cardReward(item, task)
        }
        I18N.setI18nLabel(cc.find("lbl_title", item), str, args)
        // Global.setLabelString("lbl_title", item, str)

    },

    _initNode(item) {
        cc.find("rewards", item).active = false
        cc.find("coinBack", item).active = false
        cc.find("card", item).active = false
    },

    //三个奖励
    _setRewards(item, task) {
        cc.find("rewards", item).active = true
        let _cur = 1
        for (let i = 0; i < task.rewards.length; i++) {
            let reward = task.rewards[i]
            //金币特殊处理
            if (reward.type == Global.PROP_ID.COIN) {
                cc.find("rewards/coin/label", item).getComponent(cc.Label).string = Global.FormatNumToComma(reward.count)
                continue
            }
            let rewardItem = cc.find("rewards/item" + _cur, item)
            if (reward && rewardItem) {
                _cur++
                cc.find("icon", rewardItem).getComponent("CH_RewardItem").init(reward.type, reward.count, true, true)
            }
        }
    },

    //升星奖励
    _evolveReward(item, task) {
        let coinBack = cc.find("coinBack", item)
        coinBack.active = true
        coinBack.getComponent('CH_Herocard_CoinBack').coinBackInit(task.rewards[0], task.status)
    },

    //碎片奖励
    _cardReward(item, task) {
        cc.find("card", item).active = true
        let rewards = task.rewards[0]
        cc.find("card/icon", item).getComponent('CH_RewardFragement').showFragement(rewards)
        // let cardicon = cc.find("card/icon/icon", item)
        // cc.vv.HerocardManager.loadFragmentHero(cardicon,rewards.cardid)
        // cc.find("card/lbl_count", item).getComponent(cc.Label).string = rewards.count
    },


    onClickGo(event) {
        Global.playComEff("ch_btn_click")
        if (!this._cardInfo) return

        let gameId = this._cardInfo.cfg.gameid
        let bLock = cc.vv.UserManager.isGameLock(gameId)
        if (bLock) {
            //是否
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_game_not_released);
            // cc.vv.FloatTip.show('Sorry,the game has not been released yet, so stay tuned.');
            return
        }
        if (event && event.node) {
            event.node.off("click")
        }

        if (this._delegate) {
            this._delegate.onGoSpin()
        }

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_REWARDS_GO, this._fromWhere + '|' + this._cardInfo.cardid)

        this.node.destroy()
    },

    onClickCollect(event) {
        Global.playComEff("ch_btn_click")
        let tid = this._doGuidemode == 47 ? 1 : 14 //引导的时候可能没有传递event过来，顾设置一个默认值
        if (event && event.node) {
            let item = event.node.parent
            tid = Number(item.name)
            event.node.off("click")
            event.interactable = false
        }

        var req = { c: MsgId.REQ_CARD_TASK_REWARD, cardid: this._cardInfo.cardid, taskid: tid }
        cc.vv.NetManager.send(req)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_REWARDS_COLLECT, this._fromWhere + '|' + this._cardInfo.cardid)
    },

    onClickCollectAll() {
        this._allCompletedFlag = true
        Global.playComEff("ch_btn_click")
        cc.find("bg/btn_collectall", this.node).getComponent(cc.Button).interactable = false
        var req = { c: MsgId.REQ_CARD_TASK_REWARD, cardid: this._cardInfo.cardid, is_all: true }
        cc.vv.NetManager.send(req)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_REWARDS_COLLECTALL, this._fromWhere + '|' + this._cardInfo.cardid)
    },

    setCollectAllState() {
        let act = false
        for (let i = 0; i < this._tasks.length; i++) {
            if (this._tasks[i].status == 1) {
                act = true
                break
            }
        }
        cc.find("bg/btn_collectall", this.node).getComponent(cc.Button).interactable = act

        return act
    },

    showPopRewards(rewards) {
        let rd = rewards
        let rdArr = []

        if (rd.length == 1) {
            rdArr.push(rd[0])
        } else {
            for (let i = 0; i < rd.length; i++) {
                if (rd[i].type == Global.PROP_ID.COIN) {
                    if (cc.vv.gameData) {
                        cc.vv.gameData.AddCoin(rd[i].count)
                        cc.vv.gameData.RefushMyCoin()
                    } else {
                        cc.vv.UserManager.AddCoin(rd[i].count, true)
                    }
                } else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD || rd[i].type == Global.PROP_ID.HERO_FRAGEMENT) {
                    rdArr.push(rd[i])
                } else {
                    Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: rd[i].type, num: rd[i].count })
                }
            }
        }

        if (rdArr.length > 0) {
            let self = this
            cc.loader.loadRes('CashHero/prefab/pop_reward', cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    let endCall = function () {
                        if (self._doGuidemode == 47) {
                            let compCall = function () {
                                Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI, 45)
                            }
                            cc.vv.NewGuide.ShowGuide(45, compCall)
                            self.node.destroy()
                        }
                        else if (self._doGuidemode == 49) {
                            let req = { c: MsgId.REQ_GUIDETASK_ADD_HEROCARD };
                            req.step = 2
                            req.cardid = self._cardInfo.cardid
                            cc.vv.NetManager.send(req, true);

                            Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI, 49)
                            // let compCall = function(){
                            //     Global.dispatchEvent(EventId.NEWGUIDE_PRO_UI,25)
                            // }
                            // cc.vv.NewGuide.ShowGuide(25,compCall)
                            // cc.vv.NewGuide.SetGuideTempData(25)
                            self.node.destroy()
                        }
                        self.refrushCardST()
                    }
                    node.getComponent('CH_popreward').showRewards(rdArr, endCall)
                    // node.getComponent('CH_popreward').showRewards(rewards, endCall)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        } else {
            this.refrushCardST()
        }
    },

    refrushCardST() {
        let _count
        if (this._allCompletedFlag) {
            _count = 0
        }
        else {
            this._cardInfo.st -= 1
            _count = this._cardInfo.st
        }
        if (this._delegate) {
            this._delegate.onTaskComplete(this._cardInfo.cardid, _count)
        } else {
            Global.dispatchEvent(EventId.HEROCARD_TASK_COMPLETE, { cardid: this._cardInfo.cardid, num: _count })
        }

        // this._delegate.onTaskComplete(this._cardInfo.cardid,_count)
        // cc.vv.HerocardManager.setState(this._cardInfo.cardid,_count)
    },

    _sortData(data) {
        // status=0 -- 0: 未完成, 1: 已完成, 2: 已领取
        let _data1 = [] //已完成
        let _data2 = [] //已领取
        let _data3 = [] //未完成
        for (let i = 0; i < data.length; i++) {
            if (data[i].status == 1) {
                _data1.push(data[i])
                continue
            }
            if (data[i].status == 2) {
                _data2.push(data[i])
                continue
            }
            _data3.push(data[i])
        }

        for (let j = _data1.length - 1; j >= 0; j--) {
            _data3.unshift(_data1[j])
        }
        for (let k = 0; k < _data2.length; k++) {
            _data3.push(_data2[k])
        }
        return _data3
    },

    showList() {
        this.listview.numItems = this._listData.length > 0 ? this._listData.length : 0;
        this.listview.active = (this._listData.length > 0);
    },

    //list
    OnListVRender(item, idx) {
        let itemData = this._listData[idx]
        if (item) {
            item.active = true
            this.initTaskItem(item, itemData)
        }
    },

    onRcvCardTaskInfo(msg) {
        if (msg.code != 200) return
        if (msg.cardid != this._cardInfo.cardid) return

        //整理数据
        this._tasks = this._sortData(msg.tasks)

        this._listData = this._tasks
        this.showList()
        // let temp = cc.find("bg/list_task/item", this.node)
        // let content = cc.find("bg/list_task/view/content", this.node)
        // content.destroyAllChildren()
        // for (let i=0; i<this._tasks.length; i++) {
        //     let item = cc.instantiate(temp)
        //     item.active = true
        //     this.initTaskItem(item, this._tasks[i])
        //     content.addChild(item)
        // }
        this.setCollectAllState()
        //容错处理 引导49里的任务id14
        let act = this._isUnlockSlots()
        if (act) {
            let tempguide = cc.vv.NewGuide.GetGuideTempData()
            if (tempguide == 102) {
                cc.vv.NewGuide.ShowGuide(49)
                this._doGuidemode = 49
            }
        }

    },

    _isUnlockSlots() {
        let act = false
        for (let i = 0; i < this._tasks.length; i++) {
            if (this._tasks[i].id == 14) {
                if (this._tasks[i].status == 1) {
                    act = true
                    break
                }
            }
        }
        return act
    },

    completeTask(taskid) {
        let content = cc.find("bg/list_task/view/content", this.node)
        for (let i = 0; i < this._tasks.length; i++) {
            let task = this._tasks[i]
            if (task.id == taskid) {
                task.status = 2
                let item = content.getChildByName("" + task.id)
                if (item) {
                    this.initTaskItem(item, task)
                }
                break
            }
        }
    },

    _luckyRewardsPop(rewards) {


        let self = this
        let url = 'CashHero/prefab/herocard/card_task_prize'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let small = cc.instantiate(prefab)
                small.parent = cc.find('Canvas')

                cc.find("coin_bg/lbl_coin", small).getComponent(cc.Label).string = Global.FormatNumToComma(rewards[0].count)
                cc.find("light_02", small).runAction(cc.repeatForever(cc.rotateBy(2, 360)))


                let endCall = function () {
                    //飞金币 消失
                    let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
                    let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
                    if (cc.vv.gameData) {
                        toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
                        endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
                    }

                    let rollData = {}
                    rollData.lblCoin = toLbl
                    rollData.addCoin = rewards[0].count
                    let srcObj = cc.find("coin_bg/lbl_coin", small)

                    Global.FlyCoin(srcObj, endNode, () => {
                        if (cc.vv.gameData) {
                            cc.vv.gameData.AddCoin(rewards[0].count, true)
                        } else {
                            cc.vv.UserManager.AddCoin(rewards[0].count, true)
                        }
                        small.active = false
                        self.refrushCardST()
                    }, rollData, true)
                }

                Global.showAlertAction(small, true, 0.1, 1, endCall)

            }
            else {
                console.log('未找到资源:' + url)
            }
        });


    },

    onRcvCardTaskReward(msg) {
        if (msg.code != 200) return
        if (msg.cardid != this._cardInfo.cardid) return
        if (msg.spcode) return

        if (msg.taskid) {
            this.completeTask(msg.taskid)
        } else if (msg.taskIds) {
            for (let i = 0; i < msg.taskIds.length; i++) {
                this.completeTask(msg.taskIds[i])
            }
        }
        if (msg.rewards && msg.rewards.length > 0) {
            // if (msg.rewards.length > 1) {
            //     this.showPopRewards(msg.rewards)
            // }else {
            //     if (msg.rewards[0].type == 1) {
            //         //调用砸蛋弹窗
            //         this._luckyRewardsPop(msg.rewards)
            //     }else {
            //         //卡牌碎片
            //         this.showPopRewards(msg.rewards)
            //     }
            // }
            let self = this
            self.refrushCardST()
            let pos = this.node.convertToWorldSpaceAR(cc.v2(0, 0))
            if (msg.taskid) {
                let content = cc.find("bg/list_task/view/content", this.node)
                let item = content.getChildByName("" + msg.taskid)
                if (item) {
                    pos = item.convertToWorldSpaceAR(cc.v2(0, 0))
                }

            }
            Global.RewardFly(msg.rewards, pos)
        }
        this.setCollectAllState()
    },

    onClickClose() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_HERO_DETAIL_REWARDS_CLOSE, this._fromWhere + '|' + this._cardInfo.cardid)

        Global.playComEff("ch_close")
        this.node.destroy()
    }

});
