/**
 * CashHero UserHead
 */

cc.Class({
    extends: require("UserHead"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    // start () {

    // },

    reset: function () {
        this._super()
        this._hideloading()
    },

    //开始下载,供项目拓展.
    _startDownloadImage() {
        this._showLoading()
    },

    //结束下载
    _finishDownloadImage() {
        this._hideloading()
    },

    //
    _isDownloading(uid) {
        let res = false
        if (Global._downing_list) {
            let index = Global._downing_list.indexOf(uid)
            if (index > -1) {
                res = true
            }
        }
        return res
    },

    //开始加载显示
    _showLoading() {
        let self = this
        let url = "CashHero/prefab/head_loading"
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let parentNode = cc.find("node_mask", self.node)
                let oldLoad = cc.find("head_loading", parentNode)
                if (self._isDownloading(self._uid)) {
                    if (!oldLoad) {
                        let loadNode = cc.instantiate(prefab)
                        let spr = cc.find("New Sprite", loadNode)
                        cc.tween(spr)
                            .repeatForever(
                                cc.tween()
                                    .by(2, { angle: -360 })
                            ).start()
                        loadNode.parent = parentNode
                        let scalex = parentNode.width / loadNode.width
                        let scaleY = parentNode.height / loadNode.height
                        loadNode.scale = scalex > scaleY ? scaleY : scalex
                    }


                }
                else {
                    console.log("已经下载完成")
                    if (oldLoad) {
                        oldLoad.destroy()
                    }
                }
            }
            else {
                console.log('未找到资源:' + url)
            }
        });

    },

    _hideloading() {
        let self = this
        let parentNode = cc.find("node_mask", self.node)
        let oldLoad = cc.find("head_loading", parentNode)
        if (oldLoad) {
            oldLoad.destroy()
        }
    },

    // update (dt) {},
});
