cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    onLoad() {
        // Global.FixDesignScale_V(this.node)

        let btnClose = cc.find("bg/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        let btnPlay = cc.find("bg/btn_play", this.node)
        btnPlay.on('click', this.onClickPlay, this)

        let notify = Global.getLocal('explore_notify')
        if (notify != "0") {
            cc.find("bg/notifyLayout/check_bg/check", this.node).active = true
        }

        let btnNotify = cc.find("bg/notifyLayout/check_bg", this.node)
        btnNotify.on('click', this.onClickNotify, this)

        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
            let self = this
            let nextCall = function () {
                self.onClickClose()
            }
            cc.vv.gameData.checkAutoPlay(this.node, nextCall)
        }
        else {
            cc.find("bg/leftLayout", this.node).active = false
            cc.find("bg/notifyLayout", this.node).active = false
        }

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_EXPROLATION_PLAYTIP_POP)
    },

    start() {
        // Global.FixDesignScale_V(this.node)
    },

    onDestroy() {
        if (cc.vv.gameData) cc.vv.gameData.ResumeSlot()
    },

    showPlayTimes(times) {
        // Global.setLabelString("bg/lbl_times", this.node, ""+times)
        I18N.setI18nLabel(cc.find('bg/leftLayout/lbl_times', this.node), cc.vv.Language.explore_playtip_time, times)
    },

    onClickPlay() {
        Global.playComEff("ch_btn_click")
        cc.loader.loadRes("CashHero/prefab/exploration/explore_main", cc.Prefab, (err, prefab) => {
            let canvas = cc.find("Canvas")
            if (!err && !canvas.getChildByName("explore_main")) {
                let node = cc.instantiate(prefab)
                node.name = "explore_main"
                node.parent = canvas
                node.getComponent('Explore_Main').setFrom(4)
                // node.getComponent("Explore_Main").showGameView(3)

                this.node.destroy()
            }
        })
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_EXPROLATION_PLAYTIP_GO)
    },

    onClickNotify() {
        Global.playComEff("ch_btn_click")
        let check = cc.find("bg/notifyLayout/check_bg/check", this.node)
        check.active = !check.active
        if (check.active) {
            Global.saveLocal('explore_notify', "1")
        } else {
            Global.saveLocal('explore_notify', "0")
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_EXPROLATION_PLAYTIP_CHECK)
    },

    onClickClose() {
        if (!cc.vv.gameData) {
            //是大厅的话，需要检查下是否有下一个弹窗
            cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_EXPROLATION_PLAYTIP_CLOSE)

        Global.playComEff("ch_close")
        this.node.destroy()
    }
});
