/**
 * IOS提审，是否显示
 */
cc.Class({
    extends: cc.Component,

    properties: {
        bVisible: {
            default: false,
            displayName: "提审状态是否显示",
        }
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        if (Global.isIOSReview()) {
            this.node.active = this.bVisible
        }
        else {
            this.node.active = !this.bVisible
        }
    },

    start() { },

    // update (dt) {},
});
