//成长基金广告页

cc.Class({
    extends: cc.Component,
    extends: require('UI_popwin_interface'),

    properties: {
        _rtype: 13,//13 成长基金
        _purchaseData: null,  //充值数据
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._purchaseData = null
        Global.onClick("bg/btn_purchase", this.node, this.onClickPurchase, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, this);
        cc.vv.NetManager.registerMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, this);
        Global.playComEff("ch_popup_l2");
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FUND_POP)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PURCHASE_CHECK_ORDER, this.onRcvMsgCheckOrder, false, this);
    },

    start() {
        if (!this._purchaseData) {
            //请求协议
            var req = { 'c': MsgId.REQ_SHOP };
            req.uid = Global.playerData.uid;
            req.stype = this._rtype;
            cc.vv.NetManager.send(req);
        }
    },

    onRcvShopDetail: function (msg) {
        if (msg.code === 200) {
            if (msg.stype === this._rtype) {
                this.initShow(msg.shoplist[0]);
                //if (msg.timeout) {
                //    Global.setLabelString("bg/time_bg/Label", this.node, "ONLY "+msg.timeout+" DAYS LEFT")
                //}
            }
        }
    },

    initShow: function (data) {
        if (data) {
            this._purchaseData = data
            let lbl_price_normal = cc.find("bg/btn_purchase/Background/lbl_normal", this.node)
            I18N.setI18nLabel(lbl_price_normal, cc.vv.Language.btn_only, data.amount)
            // Global.setLabelString("bg/btn_purchase/Lbl_normal", this.node, "ONLY $"+data.amount)
            Global.setLabelString("bg/info_bg/lbl_total_coin", this.node, Global.FormatNumToComma(data.totalCoin))
            Global.setLabelString("bg/info_bg/item1/lbl_num", this.node, "" + data.totalCard)
            Global.setLabelString("bg/info_bg/item2/lbl_num", this.node, "x" + data.totalPoint)
            let winCoin = 0
            let cardCount = 0
            let richCount = 0
            let rewards = data.detail[0].rewards
            for (let i = 0; i < rewards.length; i++) {
                let reward = rewards[i]
                if (reward.type == Global.PROP_ID.COIN) {
                    winCoin += reward.count
                } else if (reward.type == Global.PROP_ID.RICH_POINT) {
                    richCount += reward.count
                } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                    cardCount += reward.count
                }
            }
            Global.setLabelString("bg/immed_bg/prize_item_1/lblNum", this.node, Global.FormatNumToComma(winCoin))
            Global.setLabelString("bg/immed_bg/prize_item_2/lblNum", this.node, "" + cardCount)
            Global.setLabelString("bg/immed_bg/prize_item_3/lblNum", this.node, "x" + richCount)
            //benifist
            let btn = cc.find("bg/btn_benifist", this.node)
            btn.getComponent('CH_Benifist_Btn').showBenifist(this._purchaseData.rewards, '成长基金权益')
            let bDiscount = data.timeout ? true : false
            let node_discount = cc.find('bg/node_dis', this.node)
            node_discount.active = bDiscount
            let node_price_dis = cc.find('bg/btn_purchase/Background/dis_node', this.node)
            node_price_dis.active = bDiscount
            lbl_price_normal.active = !bDiscount
            btn.y = bDiscount ? -660 : -600
            // cc.find("lbl_old",node_price_dis).getComponent(cc.Label).string = "WAS  $ "+data.oamount;
            // cc.find("lbl_dis",node_price_dis).getComponent(cc.Label).string = "Only  $ "+data.amount;
            I18N.setI18nLabel(cc.find("lbl_dis", node_price_dis), cc.vv.Language.btn_only, data.amount)
            I18N.setI18nLabel(cc.find("lbl_old", node_price_dis), cc.vv.Language.shop_fund_btn_was, data.amount)
            let lbl_time = cc.find('time_bg/lbl_time', node_discount)
            // lbl_time.getComponent(cc.Label).string = Global.formatSec(data.timeout) + " LEFT"
            I18N.setI18nLabel(lbl_time, cc.vv.Language.lefttime1, Global.formatSec(data.timeout))
            lbl_time.stopAllActions()
            cc.tween(lbl_time)
                .repeatForever(
                    cc.tween()
                        .delay(1)
                        .call(() => {
                            data.timeout -= 1
                            if (data.timeout < 0) {
                                data.timeout = 0
                            }
                            // lbl_time.getComponent(cc.Label).string = Global.formatSec(data.timeout) + " LEFT"
                            I18N.setI18nLabel(lbl_time, cc.vv.Language.lefttime1, Global.formatSec(data.timeout))
                        })
                )
                .start()
        }
    },

    //购买成功
    onRcvMsgCheckOrder: function (msg) {
        if (msg.code === 200) {
            //跳转商城
            Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
        }
        this.onClickClose()
    },

    //购买
    onClickPurchase: function () {
        if (this._purchaseData) {
            let productid = this._purchaseData.id;
            cc.vv.PayMgr.reqPurchaseOrder(productid);
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FUND_BUY)
    },

    //关闭
    onClickClose: function () {
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        Global.playComEff("ch_close");
        this.node.destroy();
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FUND_CLOSE)
    },
});
