/**
 * 奖励图标
 */


let giftSpine = [
    { id: 31, img: "gift_car", name: "animation2", scale: 0.85 },
    { id: 32, img: "gift_evil", name: "ermodaiji", name2: "ermobao", yOff: -18 },
    { id: 33, img: "gift_ice", name: "animation1" },
    { id: 34, img: "gift_kiss", name: "animation" },
    { id: 35, img: "gift_money", name: "animation2" },
    { id: 36, img: "gift_poker", name: "animation2" },
    { id: 37, img: "gift_ring", name: "animation" },
    { id: 38, img: "gift_tower", name: "animation", yOff: 18 },
];


cc.Class({
    extends: cc.Component,

    properties: {
        lbl_count: cc.Label,
        lbl_name: cc.Label,
        spineNode: cc.Node, //spine物品显示节点
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        if (this.spineNode) {
            this._orgScale = this.spineNode.scale
        }
    },

    start() {

    },

    init: function (id, count, bSimple, bShort = false) {
        this._itemId = id
        this._bNumShort = bShort
        this._bNameSimple = bSimple
        if (Global.language == Global.LANGUAGE.AR) {
            if (id == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                id = Global.PROP_ID.DOUBLE_LEVEL_EXP_AR
            }
        }
        let bSpineType = this._isSpineItem(id)
        if (bSpineType && this.spineNode) {
            this.spineNode.active = true
            let sp = this.node.getComponent(cc.Sprite)
            sp.enabled = false
            this._loadSpineItem(bSpineType)
        }
        else {
            let sp = this.node.getComponent(cc.Sprite)
            sp.enabled = true
            if (this.spineNode) {
                this.spineNode.active = false
            }
            let url = 'common/rewarditem/' + id
            cc.loader.loadRes(url, cc.SpriteFrame, (err, data) => {
                if (!err && cc.isValid(this.node)) {
                    this.node.getComponent(cc.Sprite).spriteFrame = data
                }
            })
        }


        //数量
        this.showNum(count)

        if (this.lbl_name) {
            let namestr = ''
            if (Global.ITEMCFG[id]) {
                namestr = Global.ITEMCFG[id].name
            }
            //设置key 刷新
            let namei18Scp = this.lbl_name.node.getComponent("LanguageLabel")
            namei18Scp.id = 'lbl_item' + id
            namei18Scp.updateLabel()
            // this.lbl_name.string = namestr
        }

    },

    showNum: function (count) {
        //数量
        let id = this._itemId
        let bShort = this._bNumShort
        let bSimple = this._bNameSimple
        if (this.lbl_count) {
            let numStr = count
            if (id == Global.PROP_ID.COIN) {
                numStr = Global.FormatNumToComma(count)
                if (bShort) {
                    if (count >= 10000) {
                        numStr = Global.convertNumToShort(count)
                    }
                }
            }
            else if (id == Global.PROP_ID.VIP_POINT) {
                if (bSimple) {
                    numStr = count
                }
                else {
                    numStr = count + " VIP"
                }

            }
            else if (id == Global.PROP_ID.DOUBLE_LEVEL_REWARD || id == Global.PROP_ID.DOUBLE_LEVEL_EXP || id == Global.PROP_ID.DOUBLE_LEVEL_EXP_AR) {
                numStr = (count / 3600).toFixed(1) + " H"
            }
            else if (id == Global.PROP_ID.LUCKY_BOM) {
                numStr = ""
            }
            this.lbl_count.string = numStr
        }
    },

    _isSpineItem: function (id) {
        let res
        for (let i = 0; i < giftSpine.length; i++) {
            let item = giftSpine[i]
            if (item.id == id) {
                res = item
                break
            }
        }
        return res
    },

    _loadSpineItem: function (cfg) {
        let url = "CashHero/gift/spine/" + cfg.img + "/spine"
        Global.loadSpine(url, this.spineNode, cfg.name, true)
        if (cfg.scale && this._orgScale) {
            this.spineNode.scale = this._orgScale * cfg.scale
        }
        else {
            if (this._orgScale) {
                this.spineNode.scale = this._orgScale
            }
        }
    }

    // update (dt) {},
});
