    setShowTask: function (bRefush) {
        let self = this
        if (bRefush) {
            this.sendMainListReq()
        }
        else {
            if (this._taskdatas) {
                this.showTaskList()

            }
            else {
                cc.vv.NetManager.sendAndCache({ c: MsgId.REQ_BONUS_MAINLISTINFO })
            }
        }
        let nDelay = 0.1
        if (this._bInit) {
            nDelay = 0
        }

        let delayCall = function () {
            self.towerInitMoveing()
            //显示等级进度条
            self._showMainLvPro()
        }
        this.scheduleOnce(delayCall, nDelay)


    },

    towerInitMoveing: function () {
        let lv = cc.vv.UserManager.level
        let scr = cc.find("scr", this.node)
        if (lv >= 500) {
            scr.getComponent(cc.ScrollView).scrollToBottom(0)
        }
        else {
            scr.getComponent(cc.ScrollView).scrollToTop(0)
        }

        scr.getComponent(cc.ScrollView).scrollToPercentVertical(lv / 500, 1)
    },

    _showMainLvPro: function () {
        let lv = cc.vv.UserManager.level
        let preLv = Global.getLocal("lv", "")
        if (!preLv) preLv = lv

        let lvPro = cc.find("scr/view/content/mid/pro", this.node).getComponent(cc.ProgressBar)
        lvPro.progress = preLv / 500
        if (lv != preLv) {
            cc.tween(lvPro)
                .delay(1)
                .to(1, { progress: lv / 500 })
                .start()
        }

        Global.saveLocal("lv", lv)
    },

