    OnScrolling: function () {
        let scrCmp = cc.find("scr", this.node).getComponent(cc.ScrollView)
        let curOff = scrCmp.getScrollOffset()
        let maxOff = scrCmp.getMaxScrollOffset()
        let per = -curOff.y / maxOff.y
        let node_bg = cc.find("BG", this.node)
        let nMaxY = -1520
        let val = nMaxY + nMaxY * per
        if (val > 0) {
            val = 0
        }
        else if (val < nMaxY) {
            val = nMaxY
        }
        node_bg.y = val

        // console.log("PerVal:"+ per + "Y:"+node_bg.y)
    }

