/**
 * 春季礼包
 */
cc.Class({
    extends: cc.Component,

    properties: {
        // season_title: cc.Node,
        // lbl_sprite: cc.Node,
        // lbl_title: cc.Node,
        title_alta: cc.SpriteAtlas,
        bg_alta: cc.SpriteAtlas,

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_quest = cc.find('btn_quest', this.node)
        Global.btnClickEvent(btn_quest, this.onClickBenifist, this);
    },

    start() {

    },

    setSeason() {
        var testDate = new Date()
        let month = testDate.getMonth()
        //let month = 10
        if (month < 2 || month == 11) {
            this.setSprite('winter')
            return
        } else if (month < 5) {
            this.setSprite('spring')
            return
        } else if (month < 8) {
            this.setSprite('summer')
            return
        } else if (month < 11) {
            this.setSprite('autumn')
            return
        }
    },

    setSprite(sea) {
        let self = this
        let season_title = cc.find("titlebg/text", this.node.parent)
        // season_title.getComponent(cc.Sprite).spriteFrame = this.title_alta.getSpriteFrame(sea +'_0') 
        let titleCall = function () {
            season_title.getComponent(cc.Sprite).spriteFrame = self.title_alta.getSpriteFrame(sea + '_0')//Global.language==Global.LANGUAGE.EN ?self.title_alta.getSpriteFrame(sea +'_0'):self.ar_alta.getSpriteFrame(sea +'_0')
        }
        I18N.setI18SpriteChangeCall(season_title, titleCall)

        // cc.find("lbl_des/New Sprite", this.node).getComponent(cc.Sprite).spriteFrame = this.title_alta.getSpriteFrame(sea + '_1')

        let lbldesNode = cc.find("lbl_des", this.node)
        let desCall = function () {
            lbldesNode.getComponent(cc.Sprite).spriteFrame = Global.language == Global.LANGUAGE.EN ? self.title_alta.getSpriteFrame(sea + '_2') : self.title_alta.getSpriteFrame(sea + '_2')
        }
        I18N.setI18SpriteChangeCall(lbldesNode, desCall)

        this.node.getComponent(cc.Sprite).spriteFrame = this.bg_alta.getSpriteFrame(sea + '_3')
    },


    showUI(selIdx, data) {
        //设置相应季节
        this.setSeason()


        data.sort((a, b) => {
            return a.amount - b.amount
        })
        this._serverData = data
        let self = this
        for (let i = 0; i < data.length; i++) {
            let item = data[i]
            let nodeItem = cc.find('gift_item' + (i + 1), this.node)
            let lblprice = cc.find('lbl_price', nodeItem)
            // lblprice.getComponent(cc.Label).string = "$ " +  item.amount
            I18N.setI18nLabel(lblprice, cc.vv.Language.money, item.amount)
            let lblcoin = cc.find('lbl_coin', nodeItem)
            lblcoin.getComponent(cc.Label).string = Global.FormatNumToComma(item.count)
            // let vipexp = cc.find('lbl_vip',nodeItem)
            // vipexp.getComponent(cc.Label).string = "VIP "+ item.vipExp
            nodeItem.off('click')
            let onChange = function () {
                Global.playComEff("ch_tab");
                self.showSel(i)
            }
            nodeItem.on('click', onChange, this)
        }

        let buyBtn = cc.find('buy_btn', this.node)
        buyBtn.off('click')
        buyBtn.on('click', this.buySpringGift, this)

        this.showSel(selIdx)
    },



    //购买春季礼包
    buySpringGift() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BUY_SPRINGGIFT)
        Global.playComEff("ch_btn_click");
        if (this._serverData) {
            let productid = this._serverData[this._defaultSel].id
            cc.vv.PayMgr.reqPurchaseOrder(productid);
        }
    },

    showSel(idx) {
        if (this._defaultSel != idx) {
            this._defaultSel = idx
            cc.find('btn_quest/Background', this.node).getComponent(cc.Sprite).spriteFrame = this.title_alta.getSpriteFrame('wenhao_0' + (idx + 1))
            for (let i = 0; i < 3; i++) {
                let nodeItem = cc.find('gift_item' + (i + 1), this.node)
                let bSel = false
                if (idx == i) {
                    bSel = true
                }
                nodeItem.scale = bSel ? 1 : 0.9
                cc.find('spr_select', nodeItem).active = bSel
            }
        }

    },

    onClickBenifist: function () {
        cc.loader.loadRes("CashHero/prefab/benifits_pop", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas");
                if (canvas && !canvas.getChildByName('benifits_pop')) {
                    let node = cc.instantiate(prefab);
                    node.parent = canvas;
                    node.getComponent('CH_Benifits_pop').showBenifist(this._serverData[this._defaultSel].rewards, '季节礼包')
                }
            }
            else {
                console.log('未找到资源')

            }
        });
    }


    // update (dt) {},
});
