    onPageTurning() {
        let page = this._pageview.getCurrentPageIndex();
        this._tabIdx = this.Page2Index(page);
        this.BottomBtnAction(this._bottom_btns[this._tabIdx]);

        let show_head = Global.isClosePurchase() ? (page == 0 || page == 1) : (page == 1 || page == 2);
        let node_head = cc.find('top/node_head', this.node);
        node_head.stopAllActions();
        node_head.getComponent(cc.Button).interactable = show_head
        if (show_head) {
            node_head.runAction(cc.fadeIn(0.3));
        } else {
            node_head.runAction(cc.fadeOut(0.3));
        }
    },

    OnTouchPageBtnBegan: function (event) {
        if (this._pageSlotscv) {
            this._startPos = event.touch.getLocation();
            this._slotYpos = 0
            if (this._pageSlotscv.getComponent(cc.Widget)) {
                this._slotYpos = this._pageSlotscv.getComponent(cc.Widget).top
            }
        }

    },
    OnMovePageTouchMove: function (event) {
        if (this._pageSlotscv) {
            let pos = event.touch.getLocation();
            if (pos && this._startPos) {
                // let xDif = pos.x - this._startPos.x
                let yDif = pos.y - this._startPos.y

                // if (this.GetScrollviewMove()) {
                //     //y方向
                //     //设置一个滑动取消子节点点击事件的判断
                //     let bCancel = (Math.abs(yDif) >= 20)
                //     this.SetScrollviewCancelInner(bCancel)
                // }

                if (!this.isScrollviewCanMoveY(yDif)) {
                    //不能滑动，则top节点先移动. nOrgY这个数字是slotview的初始对齐位置
                    let nOrgY = 200
                    let nextVal = (this._slotYpos - yDif)
                    if (yDif > 0 && nextVal < 0) {
                        //向上
                        nextVal = 0
                        yDif = this._slotYpos
                    }
                    if (yDif < 0 && nextVal > nOrgY) {
                        //向下
                        nextVal = nOrgY
                        yDif = this._slotYpos - nOrgY
                    }

                    this._pageSlotscv.getComponent(cc.Widget).top = nextVal
                    this._pageSlotscv.getComponent(cc.Widget).updateAlignment()
                    Global.dispatchEvent(EventId.UPTATE_HALL_TOP_POSITION, nOrgY - nextVal)
                    return
                }
                // if (this._dir) {
                //     return
                // }
                // this._dir = true
                // if (Math.abs(xDif) > Math.abs(yDif)) {
                //     //x方向, 通知scrollview不能y方向滑动
                //     this.SetPageViewMove(true)
                //     this.SetScrollviewEnable(false)
                // }
                // else {
                //     if(this.isScrollviewCanMoveY(yDif)){
                //         this.SetScrollviewMove(true)
                //     }


                // }
            }
        }


    },
