    _showLockTips: function (str, xPos) {
        let obj = cc.find('Canvas/bottom/spr_lock_tip')
        let lblVal = cc.find('lbl_val', obj)
        lblVal.getComponent(cc.Label).string = str
        obj.x = xPos
        obj.stopAllActions()
        if (obj.getNumberOfRunningActions() == 0) {
            obj.active = true
            obj.opacity = 0
            cc.tween(obj)
                .to(0.2, { opacity: 255 })
                .delay(3)
                .to(0.5, { opacity: 0 })
                .start()
        }
    },

