    //bottom点击的动作
    BottomBtnAction: function (obj) {
        let self = this

        if (this._pre_click_btn == obj) {
            return
        }

        let _isSlotsBtn = obj._name == 'btn_slots'
        cc.find('spr', this._btn_slots).active = !_isSlotsBtn
        cc.find('icon', this._btn_slots).active = _isSlotsBtn

        let sprSelBg = cc.find('bottom/spr_sel', this.node)
        if (this._pre_click_btn) {
            this._isAction = true //正在移动
            this.ShowBttomSel(this._pre_click_btn, false)

            let icon = cc.find('icon', obj)
            // let from = cc.v2(sprSelBg.position.x,sprSelBg.position.y)
            // let to = cc.v2(obj.position.x,obj.position.y)
            let nDur = 0//Math.abs(from.x - to.x)/1500
            cc.tween(sprSelBg)
                .to(nDur, { x: obj.position.x })
                .call(() => {
                    self.ShowBttomSel(obj, true)
                    self._isAction = null
                    sprSelBg.getComponent(sp.Skeleton).setAnimation(0, 'Animation_Slider_jump', false)

                    let delayCall = function () {
                        icon.getComponent(sp.Skeleton).setAnimation(0, 'Animation_Icon_jump', false)

                        if (obj._name == 'btn_slots') {
                            icon.getComponent(sp.Skeleton).setCompleteListener(() => {
                                icon.getComponent(sp.Skeleton).setAnimation(0, 'Animation_Slider_jump', true)
                            })
                        }
                    }
                    self.scheduleOnce(delayCall, 0.05)
                })
                .start()
            this._pre_click_btn = obj
        }
        else {
            sprSelBg.x = obj.position.x
            self.ShowBttomSel(obj, true)
            this._pre_click_btn = obj
        }
        let idx = this.getTabIdxByBtn(obj)
        if (idx == 2) {
            Global.playBgm(Global.SOUNDS.bgm_hall_slots);
        } else if (idx == 4) {
            Global.playBgm(Global.SOUNDS.bgm_hall_club);
        }
        else if (idx == 1) {
            Global.playBgm(Global.SOUNDS.bgm_herocard);
        }
        else if (idx != null) {
            Global.playBgm(Global.SOUNDS.bgm_hall);
        }
        cc.vv.UserManager.setHallTab(idx)
        Global.dispatchEvent(EventId.CHANGE_HALLTAB, idx);
    },

    //按钮是否选中
    ShowBttomSel: function (obj, bSel) {
        if (obj) {
            let unSel = cc.find('txt_unsel', obj)
            let sel = cc.find('txt_sel', obj)
            unSel.active = !bSel
            sel.active = bSel
            sel.opacity = 0
            cc.tween(sel)
                .to(0.4, { opacity: 255 })
                .start()
        }

    },

