/**
 * ios提审的时候替换显示图片
 */
cc.Class({
    extends: cc.Component,

    properties: {
        normal_show: {
            default: null,
            type: cc.SpriteFrame,
            displayName: "非提审状态"
        },
        ios_ts_show: {
            default: null,
            type: cc.SpriteFrame,
            displayName: "IOS提审状态"
        }
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let sp = this.node.getComponent(cc.Sprite)
        if (sp) {
            if (Global.isIOSReview()) {
                sp.spriteFrame = this.ios_ts_show
            }
            else {
                sp.spriteFrame = this.normal_show
            }
        }
    },

    start() { },

    // update (dt) {},
});
