    showUI: function (complv) {
        let self = this
        this._compLv = complv
        // this._checkHWShow()
        if (complv) {
            //需要跳动展示完成效果
            let startidx
            for (let i = 0; i < Global.SYS_ROAD_CFG.length; i++) {
                let curCfg = Global.SYS_ROAD_CFG[i]
                let road = cc.find('scv_content/view/content/node_bg/road/rode' + curCfg.idx, this.node)
                let lblLv = cc.find('lv_bg/lv', road)
                if (lblLv) {
                    lblLv.getComponent(cc.Label).string = curCfg.lv
                }

                if (curCfg.lv == complv) {
                    startidx = i
                    this._setRoadDone(road, false)
                    this._setLineDone(i, false)
                }
                else {
                    let bDone = curCfg.lv < complv

                    this._setRoadDone(road, bDone)
                    this._setLineDone(i, bDone)
                }
            }



            cc.tween(self.node)
                .delay(1)
                .call(() => {
                    let toCfg = Global.SYS_ROAD_CFG[startidx]

                    if (toCfg.road) {
                        //起始点播放完成动画-》再播终点的完成动画
                        let endCall = function () {
                            self._showComp(toCfg)
                        }
                        self._jumpline(toCfg, endCall)
                    }
                    else {
                        //没有起点，直接播终点的完成动画
                        self._showComp(toCfg)
                    }
                })
                .start()

            this._curStepIdx = startidx
            // this._scrollToCurTask(startidx,1)
        }
        else {
            //直接看当前进度的
            let curIdx = this.getCurIdx()
            let curCfg = Global.SYS_ROAD_CFG[curIdx]
            for (let i = 0; i < Global.SYS_ROAD_CFG.length; i++) {
                let bDone = false
                let itemCfg = Global.SYS_ROAD_CFG[i]
                if (curCfg && itemCfg.idx <= curCfg.idx) {
                    //已经完成了
                    bDone = true
                }
                let road = cc.find('scv_content/view/content/node_bg/road/rode' + itemCfg.idx, this.node)
                let lblLv = cc.find('lv_bg/lv', road)
                if (lblLv) {
                    lblLv.getComponent(cc.Label).string = itemCfg.lv
                }

                this._setRoadDone(road, bDone)
                this._setLineDone(i, bDone)
            }



            this._curStepIdx = curIdx
        }

    },

