    _scrollToCurTask: function (idx, nTime) {
        let scrCmp = cc.find('scv_content', this.node).getComponent(cc.ScrollView)
        // let oldOff = scrCmp.getScrollOffset()
        let bInGame = cc.vv.gameData ? true : false
        let nPer = 0
        if (idx <= 0) {
            nPer = 1
        }
        else if (idx == 1) {
            nPer = bInGame ? 0.9 : 0.9
        }
        else if (idx == 2) {
            nPer = bInGame ? 0.7 : 0.7
        }
        else if (idx == 3) {
            nPer = bInGame ? 0.6 : 0.6
        }
        else if (idx == 4) {
            nPer = bInGame ? 0.7 : 0.5
        }
        else if (idx == 5) {
            nPer = 0.4
        }
        else {
            nPer = 0
        }
        scrCmp.stopAutoScroll()
        scrCmp.scrollToPercentVertical(1 - nPer, nTime)
    },

    //跳路线
    _jumpline: function (cfg, endCall) {
        let self = this
        let seqs = []
        let nodeJump = cc.find('scv_content/view/content/node_bg/road/node_jump', this.node)
        nodeJump.stopAllActions()
        let starNode = cc.find('scv_content/view/content/node_bg/road/rode' + (cfg.idx - 1), this.node)
        nodeJump.position = cc.v2(starNode.x, starNode.y + 100)
        for (let i = 0; i < cfg.road.length; i++) {
            let item = cfg.road[i]
            let nodeTemp = cc.find('scv_content/view/content/node_bg/road/' + item, this.node)
            let ac = cc.jumpTo(0.25, cc.v2(nodeTemp.position.x, nodeTemp.position.y), 200, 1)
            let playAudio = cc.callFunc(() => {
                Global.playCashEff("sys_road/sys_road_step");
                self._setLineItemDone(nodeTemp, true, true)
            })

            let delay = cc.delayTime(0.3)
            seqs.push(ac)
            seqs.push(playAudio)
            seqs.push(delay)
        }

        if (seqs.length > 0) {
            let acCall = cc.callFunc(() => {
                nodeJump.active = false
                if (endCall) {
                    endCall()
                }
            })
            seqs.push(acCall)
            let acSeq = cc.sequence(seqs)
            nodeJump.active = true
            nodeJump.runAction(acSeq)
        }
    },

