    //bPreload:预加载
    _showSysUnlock: function (lv, bPreload) {
        let url
        let uiname
        if (lv == Global.SYS_OPEN.QUEST_TASK) {
            let bOpen = cc.vv.UserManager.isOpenQuestServer()
            if (bOpen) {
                //quest开放
                url = "CashHero/prefab/quest_unlock"
                uiname = "quest_unlock"
            }
        }
        else if (lv == Global.SYS_OPEN.DAILYSIGN) {
            url = "hall_prefab/SignIn"
            uiname = "SignIn"
        }
        else if (lv == Global.SYS_OPEN.FB_BIND_PARTY) {
            url = "CashHero/prefab/fbShare/fb_binding_ad"
            uiname = "fb_binding_ad"
        }
        else if (lv == Global.SYS_OPEN.HALL_RANK) {
            url = "CashHero/prefab/ranking_list"
            uiname = "ranking_list"
        }
        else if (lv == Global.SYS_OPEN.HERO_CARD) {
            url = "slots_common/SlotRes/prefab/LMSlotsSys_float"
            uiname = "LMSlotsSys_float"
        }
        else if (lv == Global.SYS_OPEN.PIG_BANK) {
            url = "hall_prefab/MoneyBankUI"
            uiname = "MoneyBankUI"
        }
        else if (lv == Global.SYS_OPEN.DAILYTASK) {
            url == "CashHero/prefab/mission/mission_frame"
            uiname = "mission_frame"
        }
        else if (lv == Global.SYS_OPEN.CASH_BACK) {
            url = "CashHero/prefab/cashBack/cashBackPop"
            uiname = "cashBackPop"
        }

        if (url) {
            let callbacks = function (prefab) {
                if (bPreload) return
                let node = cc.instantiate(prefab);
                node.name = uiname;
                node.parent = cc.find("Canvas");
            }
            this._loadPrefab(url, callbacks)
        }

    },

    //设置里程碑的完成显示
    _setRoadDone: function (node, bDone) {
        if (node) {
            let spr_gou = cc.find('spr_cmp', node)
            if (spr_gou) {
                spr_gou.active = bDone
            }

            let spr_lv = cc.find('lv_bg', node)
            if (spr_lv) {
                spr_lv.active = !bDone
            }

        }
    },

    //设置路线的完成显示
    _setLineDone: function (idx, bDone) {
        let cfg = Global.SYS_ROAD_CFG[idx]
        if (cfg) {
            if (cfg.road) {
                for (let i = 0; i < cfg.road.length; i++) {
                    let lineObj = cc.find('scv_content/view/content/node_bg/road/' + cfg.road[i], this.node)
                    if (lineObj) {
                        this._setLineItemDone(lineObj, bDone)

                    }
                }
            }
        }
    },

    _setLineItemDone(lineObj, bDone, bJumping) {
        let doneNode = cc.find('dark', lineObj)
        let unDoneNode = cc.find('light', lineObj)
        if (doneNode && unDoneNode) {
            doneNode.active = bDone
            unDoneNode.active = !bDone
        }
        else {
            //说明是动画的
            let ske = lineObj.getComponent(sp.Skeleton)
            let ani = bDone ? "animation1" : "animation2"
            let bLoop = true
            if (bJumping) {
                ani = "animation"
                bLoop = false
            }
            ske.setAnimation(0, ani, bLoop)
        }

    },

    _loadPrefab: function (url, callbacks) {
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                callbacks(prefab)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    _showLockTips: function (str, pos) {
        let obj = cc.find('spr_lock_tip', this._roadNode)
        let lblVal = cc.find('lbl_val', obj)
        lblVal.getComponent(cc.RichText).string = '<color=#ffd83c><size=42>' + str + '</size></color>'
        obj.y = pos.y + this._posY
        obj.x = pos.x
        obj.stopAllActions()
        if (obj.getNumberOfRunningActions() == 0) {
            obj.active = true
            obj.opacity = 0
            cc.tween(obj)
                .to(0.2, { opacity: 255 })
                .delay(3)
                .to(0.5, { opacity: 0 })
                .start()
        }
    },

