let GAME_ID = require("GameIdMgr");
let itemsListCfg = require("GameItemCfg");

cc.Class({
    extends: require("CH_SlotIcon"),

    setGameId: function (gameId, ani) {
        this._gameId = gameId
        this._loadAni = ani
        let icon = cc.find('icon', this.node)
        icon.active = true
        let spine = cc.find('spine', this.node);
        spine.active = false
        this._cfg = itemsListCfg[gameId]
        this._loadCampIcon()
        if (this._cfg.animation) {
            this.LoadIconAnimation()
        }
        else {
            this.LoadIcon()
        }
    },

    // icon
    LoadIcon: function () {
        if (cfg && cfg.leader) {    // 大厅的势力主游戏没有图标，只有动画
            let icon = cc.find('icon', this.node)
            if (icon) icon.active = false
            return
        }
        this._super()
    },

    _loadCampIcon: function () {
        if (this._gameId == GAME_ID.SLOT_COMESOON) {
            console.log("comesoon")
        }
        let cfg = cc.vv.HerocardManager.getCardCfgByGame(this._gameId);
        //势力图标
        let campIcon = cc.find("camp_icon", this.node)
        if (campIcon) {
            if (cfg) {
                if (cfg.leader) {
                    campIcon.active = false
                    return
                }
                campIcon.active = true
                let changeImg = campIcon.getComponent("ImgSwitchCmp")
                if (changeImg) {
                    changeImg.setIndex(cfg.campid - 1001)
                }
            }
            else {
                campIcon.active = false
            }
        }
    },

    // _getAnimationUrl(cfg) {
    //     if (cfg.leader) {
    //         return "CashHero/slots/icon/"+ cfg.action +"/spine"
    //         // return "CashHero/slots/icon/"+ cfg.action +"_big/spine"     // 大厅里的势力主游戏加载大图标
    //     } else {
    //         return "CashHero/slots/icon/"+ cfg.action +"/spine"         // 非势力主游戏加载普通图标
    //     }
    // },

});
