
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClick, this)
    },

    start() {

    },

    initGiftChat(data, friendInfo) {
        this._giftData = data;
        this._friendInfo = friendInfo;

        let node_gift = cc.find("node_gift", this.node);
        node_gift.children.forEach(node => {
            node.active = node.name == data.msg;
        })
    },

    onClick() {
        let receiverInfo = {};
        let senderInfo = {};
        let selfInfo = {
            uid: cc.vv.UserManager.uid,
            usericon: cc.vv.UserManager.userIcon,
            playername: cc.vv.UserManager.nickName,
        }
        if (this._giftData.uid == cc.vv.UserManager.uid) {
            receiverInfo = this._friendInfo;
            senderInfo = selfInfo;
        } else {
            receiverInfo = selfInfo;
            senderInfo = this._friendInfo;
        }

        cc.loader.loadRes("CashHero/prefab/gift/gift_play", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let node = cc.find('gift_play', parObj)
                if (!node) {
                    node = cc.instantiate(prefab);
                    node.parent = parObj;
                    node.getComponent("gift_play").setInfo(receiverInfo, senderInfo, { img: this._giftData.msg });
                } else {
                    node.getComponent("gift_play").addInfo(receiverInfo, senderInfo, { img: this._giftData.msg });
                }
            }
        })
    },

    // update (dt) {},
});
