/**
 * 合成卡的礼包
 */

cc.Class({
    extends: cc.Component,

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClickOpenCardGift, this)
    },

    start() {

    },

    setData(data, scp) {
        this._pageChatScp = scp
        this._itemData = data
        //设置卡片信息
        let sprCard = cc.find('spr_card', this.node)
        let cardName = cc.find('spr_namebg/lbl_name', this.node)
        let sprGift = cc.find('spr_gift', this.node)
        if (data.cardshare) {
            let cfg = cc.vv.HerocardManager.getCardCfg(data.cardshare.cardid)
            if (cfg) {
                cc.vv.HerocardManager.loadChipHero(sprCard, cfg.cardid)
                // cardName.getComponent(cc.Label).string = cfg.name
                I18N.setI18nLabel(cardName, cc.vv.Language["cardname_" + cfg.cardid])
                let bCanOpen = data.cardshare.open
                Global.showSpriteGray(sprGift, !bCanOpen)
                if (bCanOpen) {
                    Global.breathNode(sprGift)
                }
                else {
                    sprGift.stopAllActions()
                }
            }
        }
    },

    onClickOpenCardGift: function () {
        let self = this
        Global.playComEff("ch_btn_click");
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_GIFT)
        if (this._itemData && this._itemData.stype == 3) {
            //红包灰太
            let bCanOpen = this._itemData.cardshare.open
            this._itemData.cardshare.open = 0
            let sprGift = cc.find('spr_gift', this.node)
            Global.showSpriteGray(sprGift, true)
            sprGift.stopAllActions()
            this._pageChatScp.updateChatData(this._itemData)
            //请求开礼包
            let url = 'CashHero/prefab/friend/CH_friend_cardshare_gift'
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let canvas = cc.find('Canvas')
                    let newNode = cc.instantiate(prefab)
                    newNode.parent = canvas
                    newNode.getComponent('CH_FriendCardShareGift').init(self._itemData, bCanOpen)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        }
    },


    // update (dt) {},
});
