cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClick, this)
    },

    start() {
        Global.registerEvent(EventId.CARDGIFT_CHOOSE, this.onEventCardGiftChoose, this)
        this.rightEnable(false)
    },

    initData(data, id) {
        cc.find('count', this.node).getComponent(cc.Label).string = data.chips
        let cardicon = cc.find("card/icon", this.node)
        this._cardid = data.cardid
        cc.vv.HerocardManager.loadFragmentHero(cardicon, data.cardid)
        this.rightEnable(this._cardid == id)
    },

    onEventCardGiftChoose(data) {
        let _id = data.detail
        this.rightEnable(_id == this._cardid)
    },

    rightEnable(flag) {
        cc.find('right', this.node).active = flag
    },

    onClick() {
        this.rightEnable(true)
        Global.dispatchEvent(EventId.CARDGIFT_CHOOSE, this._cardid)
    },

    // update (dt) {},
});
