//父节点->子节点->icon 排列显示

cc.Class({
    extends: cc.Component,

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.node.active = true
    },

    start() {

    },

    init: function (rewards) {
        let rdArr = rewards//this.mergData(rewards)
        let layoutChild = this.node.children
        // let _cardCount = this.getCardNum(rewards)
        for (let i = 0; i < layoutChild.length; i++) {
            let itemData = rdArr[i]
            layoutChild[i].active = itemData ? true : false
            if (itemData) {
                let _count = rdArr[i].count
                cc.find('icon', layoutChild[i]).getComponent('CH_RewardItem').init(rdArr[i].type, _count, true, true)
            }
        }
    },

    getCardNum: function (rewards) {
        let count = 0
        for (let i = 0; i < rewards.length; i++) {
            if (rewards[i].type == Global.PROP_ID.HERO_CARD) {
                count += rewards[i].count
            }
        }
        return count
    },

    mergData: function (rewards) {
        let _arr = []
        for (let i = 0; i < rewards.length; i++) {
            let _hasFlag = false
            for (let j = 0; j < _arr.length; j++) {
                if (_arr[j].type == Global.PROP_ID.HERO_CARD) {
                    _hasFlag = true
                    break
                }
            }
            if (!_hasFlag) {
                _arr.push(rewards[i])
            }
        }
        return _arr
    },

    // update (dt) {},
});
