/**
 * 经验双倍
 */
cc.Class({
    extends: cc.Component,

    properties: {
        sprBgFrames: {
            type: cc.SpriteFrame,
            default: [],
        },
        _curInterval: 0,
        _curShowIdx: -1,
        _lastShowIdx: -1,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.booster_bg = cc.find("spr_bg", this.node)
        this.txt_xp = cc.find("txt_xp", this.booster_bg)
        this.txt_level = cc.find("txt_level", this.booster_bg)
        this.txt_faster = cc.find("txt_faster", this.booster_bg)
        this.txt_level_up_party = cc.find("txt_level_up_party", this.booster_bg)
        this.lbl_double_time = cc.find("lbl_doublexp_time", this.booster_bg)
        this.lbl_levelbrust_time = cc.find("lbl_levelbrust_time", this.booster_bg)
        this.lbl_levelupparty_time = cc.find("lbl_levelupparty_time", this.booster_bg)
        this.lbl_levelupparty_leftlevel = cc.find("lbl_left_level", this.booster_bg)
        this._curShowIdx = -1;
        cc.vv.NetManager.registerMsg(MsgId.REQ_DOUBLE_XP, this.onRcvGetDoubleXP, this);//获取双倍经验信息
        //监听等级提升
        cc.vv.NetManager.registerMsg(MsgId.PULL_LEVEL_UP_EXP, this.onRecvLevelupExp, this);
        //levelUpPary
        cc.vv.NetManager.registerMsg(MsgId.LEVEL_UP_PARTY_UPDATE_NOTICE, this.onRcvNetLevelUpPartyUpdateNotice, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_DOUBLE_XP, this.onRcvGetDoubleXP, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PULL_LEVEL_UP_EXP, this.onRecvLevelupExp, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.LEVEL_UP_PARTY_UPDATE_NOTICE, this.onRcvNetLevelUpPartyUpdateNotice, false, this);
    },

    start() {
        this._sendReq()
    },

    onEnable() {
        this.showBooterNode(false)
    },

    showBooterNode: function (bShow) {
        if (this.booster_bg) {
            this.booster_bg.active = bShow
        }
    },

    showNext() {
        if (this.serverData.length <= 0) {
            this.showBooterNode(false)
            return;
        }
        this._curShowIdx++;
        if (this._curShowIdx >= this.serverData.length) this._curShowIdx = 0;
        let itemData = this.serverData[this._curShowIdx];
        if (itemData != undefined) {
            if (this.serverData[this._curShowIdx].time <= 0) {
                // 删除不需要播放的
                this.serverData.splice(this._curShowIdx, 1)
                this.showNext();
                return;
            }
        }
        let refreshBoostShow = (type) => {
            switch (type) {
                case 1: //等级
                    this.showLevelBrust(true);
                    break;
                case 2: //双倍
                    this.showDoubleXp(true);
                    break;
                case 3: //等级任务
                    this.showLevelUpParty(true);
                    break;
            }
        }
        if (this._lastShowIdx == this._curShowIdx) {
            this.scheduleOnce(() => {
                this.showBooterNode(true)
                if (itemData != undefined) {
                    refreshBoostShow(itemData.t);
                }
            }, 2.0);
        }
        else {
            this.showBooterNode(true)
            if (itemData != undefined) {
                refreshBoostShow(itemData.t);
            }
        }
        this._lastShowIdx = this._curShowIdx;
    },

    //显示等级加速
    showLevelBrust: function (bShow) {
        let self = this
        if (bShow) {
            this._hideAllChild()
            this.txt_level.active = true
            this.txt_level.scale = 1.2
            cc.tween(this.txt_level)
                .to(0.3, { scale: 1 })
                .delay(2)
                .call(() => {
                    self.txt_level.active = false
                    self.lbl_levelbrust_time.active = true
                    self.lbl_levelbrust_time.scale = 1.2
                    cc.tween(self.lbl_levelbrust_time)
                        .to(0.3, { scale: 1 })
                        .delay(5)
                        .call(() => {
                            self.lbl_levelbrust_time.active = false;
                            //显示下一个
                            this.showNext();
                        })
                        .start()
                })
                .start()
        }
        else {
            this.txt_level.active = false
            this.lbl_levelbrust_time.active = false
        }
    },

    //显示经验加速
    showDoubleXp: function (bShow) {
        let self = this
        if (bShow) {
            this._hideAllChild()
            this.txt_xp.active = true
            this.txt_xp.scale = 1.2
            cc.tween(this.txt_xp)
                .to(0.3, { scale: 1 })
                .delay(2)
                .call(() => {
                    self.txt_xp.active = false
                    self.txt_faster.active = true
                    self.txt_faster.scale = 1.2
                    cc.tween(self.txt_faster)
                        .to(0.3, { scale: 1 })
                        .delay(2)
                        .call(() => {
                            self.txt_faster.active = false
                            self.lbl_double_time.active = true
                            self.lbl_double_time.scale = 1.2
                            cc.tween(self.lbl_double_time)
                                .to(0.3, { scale: 1 })
                                .delay(5)
                                .call(() => {
                                    self.lbl_double_time.active = false
                                    //显示下一个
                                    this.showNext();
                                })
                                .start()
                        })
                        .start()
                })
                .start()
        }
        else {
            this.txt_xp.active = false
            this.lbl_double_time.active = false
            this.txt_faster.active = false
        }
    },

    showLevelUpParty: function (bShow) {
        let self = this
        if (bShow) {
            this._hideAllChild()
            this.txt_level_up_party.active = true
            this.txt_level_up_party.scale = 1.2
            cc.tween(this.txt_level_up_party)
                .to(0.3, { scale: 1 })
                .delay(2)
                .call(() => {
                    self.txt_level_up_party.active = false
                    self.lbl_levelupparty_leftlevel.active = true
                    self.lbl_levelupparty_leftlevel.scale = -1.2
                    self.lbl_levelupparty_leftlevel.getComponent(cc.Label).string = (this._getTypeData(3).leftLevel || 1) + " LEVELS LEFT";
                    cc.tween(self.lbl_levelupparty_leftlevel)
                        .to(0.3, { scale: -1 })
                        .delay(2)
                        .call(() => {
                            self.lbl_levelupparty_leftlevel.active = false
                            self.lbl_levelupparty_time.active = true
                            self.lbl_levelupparty_time.scale = 1.2
                            cc.tween(self.lbl_levelupparty_time)
                                .to(0.3, { scale: 1 })
                                .delay(5)
                                .call(() => {
                                    self.lbl_levelupparty_time.active = false
                                    //显示下一个
                                    this.showNext();
                                })
                                .start()
                        })
                        .start()
                })
                .start()
        }
        else {
            this.txt_level_up_party.active = false
            this.lbl_levelupparty_leftlevel.active = false
            this.lbl_levelupparty_time.active = false
        }
    },

    _hideAllChild: function () {
        this.txt_level.active = false
        this.lbl_levelbrust_time.active = false
        this.txt_faster.active = false
        this.txt_xp.active = false
        this.lbl_double_time.active = false
        this.txt_level_up_party.active = false
        this.lbl_levelupparty_leftlevel.active = false
        this.lbl_levelupparty_time.active = false
    },

    _sendReq: function () {
        cc.vv.NetManager.send({ c: MsgId.REQ_DOUBLE_XP });
    },

    onRcvGetDoubleXP: function (msg) {
        if (msg.code == 200) {
            this.serverData = msg.data
            //显示下一个
            this.showNext();
            //LevelUpParty
            let itemData = this._getTypeData(3);
            Global.isExistLevelUpParty = (itemData && itemData.time > 0);
            this.booster_bg.getComponent(cc.Sprite).spriteFrame = this.sprBgFrames[Global.isExistLevelUpParty ? 1 : 0];
        }
    },

    onRecvLevelupExp: function (msg) {
        if (msg.code == 200) {
            //刷新显示
            this._sendReq();
        }
    },

    onRcvNetLevelUpPartyUpdateNotice: function (msgDic) {
        if (msgDic.code === 200) {
            //刷新显示
            this._sendReq();
        }
    },

    // _isNeedShowDoubleXp:function(){
    //     let res = false
    //     // if(this.serverData && this.serverData)
    // },

    // nType 1 等级加速 2双倍经验 3等级提升任务
    _getTypeData: function (nType) {
        if (this.serverData) {
            for (let i = 0; i < this.serverData.length; i++) {
                let item = this.serverData[i]
                if (item.t == nType) {
                    return item
                }
            }
        }
    },

    updateTime() {
        if (this.serverData) {
            let allEnd = true
            for (let i = 0; i < this.serverData.length; i++) {
                let item = this.serverData[i]
                if (item.time > 0) {
                    allEnd = false
                    item.time = item.time - 1
                }
                switch (item.t) {
                    case 1: //等级
                        this.lbl_levelbrust_time.getComponent(cc.Label).string = Global.formatSec(item.time)
                        break;
                    case 2: //双倍
                        this.lbl_double_time.getComponent(cc.Label).string = Global.formatSec(item.time)
                        break;
                    case 3: //等级任务
                        this.lbl_levelupparty_time.getComponent(cc.Label).string = Global.formatSec(item.time)
                        break;
                }
            }
            if (allEnd) {
                this.showBooterNode(false)
            }
        }
    },

    update(dt) {
        this._curInterval = this._curInterval + dt
        if (this._curInterval >= 1) {
            this._curInterval = 0;
            this.updateTime();
        }
    },
});
