let FROMTYPE = {
    CHAT: 1,
    FRIEND: 2,
};

cc.Class({
    extends: cc.Component,

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('closeBtn', this.node), this.onClickClose, this)
        // this._fromFlag = FROMTYPE.CHAT
    },

    start() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CHAT_PRIVATEPOP)
    },

    initInfo(data, from) {
        this._fromFlag = from

        //姓名等等
        cc.find('name', this.node).getComponent(cc.Label).string = data.playername
        cc.find('node_head', this.node).getComponent('UserHead').setHead(data.uid, data.usericon)
    },

    onClickClose() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CHAT_PRIVATECLOSE)
        // 是否回到好友界面
        if (this._fromFlag == FROMTYPE.FRIEND) {
            Global.dispatchEvent(EventId.PRIVATECHAT_CLOSE, this._fromFlag == FROMTYPE.FRIEND)
            Global.dispatchEvent(EventId.REFRUSH_PRIVATE_LIST, { clickFlag: false })
            // this.sendReqPrivateList()
        } else {
            // 刷新私聊窗口
            Global.dispatchEvent(EventId.PRIVATECHAT_CLOSE, this._fromFlag == FROMTYPE.FRIEND)
            Global.dispatchEvent(EventId.REFRUSH_PRIVATE_LIST, { clickFlag: true })
        }
    },

    sendReqPrivateList: function () {
        let req = {
            c: MsgId.REQ_PRIVATE_LIST,
        };
        cc.vv.NetManager.send(req, true)
    },

    // update (dt) {},
});
