/**
 * 活动页面
 */

let BONUS_TAB = {
    Rewards: 1,
    Activity: 2,
    DayTask: 3,
    WeekTask: 4,
    MainTask: 5,
}


cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_rewards = cc.find("channel/rewards", this.node)
        Global.btnClickEvent(btn_rewards, this.onClickRewards, this)
        let btn_activity = cc.find("channel/activity", this.node)
        Global.btnClickEvent(btn_activity, this.onClickActivity, this)
        let btn_dayTask = cc.find("channel/day", this.node)
        Global.btnClickEvent(btn_dayTask, this.onClickDayTask, this)
        let btn_weekTask = cc.find("channel/week", this.node)
        Global.btnClickEvent(btn_weekTask, this.onClickWeekTask, this)
        let taskOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.DAILYTASK)
        cc.find("lock", btn_dayTask).active = !taskOpen
        let weekOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.WEEKLYTASK)
        cc.find("lock", btn_weekTask).active = !weekOpen
        // cc.find("channel/line6",this.node).active = taskOpen
        // cc.find("channel/line5",this.node).active = taskOpen
        let btnArrow = cc.find('channel/btn_arrow', this.node)
        Global.btnClickEvent(btnArrow, this.onClickArrow, this)
        let btnEmpty = cc.find('btn_empty', this.node)
        btnEmpty.active = false
        Global.btnClickEvent(btnEmpty, this.onClickArrow, this)


        let btn_mainTask = cc.find("channel/main", this.node)
        Global.btnClickEvent(btn_mainTask, this.onClickMainTask, this)

        Global.registerEvent("FBSHARE_ACTION", this.onEventShareAction, this)      //刷新列表
        Global.registerEvent("RefushTaskStatus", this.onEventShareAction, this)      //刷新列表
        Global.registerEvent(EventId.PAY_RESULT, this.onEventShareAction, this)      //刷新列表
        Global.registerEvent("BONUS_TAB", this.onEventBonusTab, this)      //显示默认Tab
    },

    start() {
        //设置默认选项
        this.showDefaultTab()

        this._bExpand = false
        this.onClickArrow()

    },

    showDefaultTab: function () {
        let tabName
        if (!this._curSel || this._curSel == BONUS_TAB.Rewards) {
            this._curSel = BONUS_TAB.Rewards
            tabName = "channel/rewards"

        }
        else if (this._curSel == BONUS_TAB.Activity) {
            tabName = "channel/activity"
        }
        else if (this._curSel == BONUS_TAB.DayTask) {
            tabName = "channel/day"
        }
        this._showTab(cc.find(tabName, this.node))
        this._showTabContent(this._curSel)

    },

    onClickRewards: function (event) {
        let self = this
        Global.playComEff("ch_btn_click");
        if (event && this._curSel == BONUS_TAB.Rewards) {
            return
        }
        this._curSel = BONUS_TAB.Rewards
        // //点完后隐藏
        // let endCall = function(){
        //     self.onClickArrow()
        // }
        this._showTab(event.node)
        this._showTabContent(this._curSel)
    },

    onClickActivity: function (event) {
        Global.playComEff("ch_btn_click");
        if (event && this._curSel == BONUS_TAB.Activity) {
            return
        }
        this._curSel = BONUS_TAB.Activity
        // //点完后隐藏
        // let self = this
        // let endCall = function(){
        //     self.onClickArrow()
        // }
        this._showTab(event.node)
        this._showTabContent(this._curSel)
    },

    onClickDayTask: function (event) {
        Global.playComEff("ch_btn_click");
        if (event && this._curSel == BONUS_TAB.DayTask) {
            return
        }
        let taskOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.DAILYTASK)
        if (!taskOpen) {

            this._showLockTip(event.node, Global.SYS_OPEN.DAILYTASK)
            return
        }


        this._curSel = BONUS_TAB.DayTask
        // //点完后隐藏
        // let self = this
        // let endCall = function(){
        //     self.onClickArrow()
        // }
        this._showTab(event.node)
        this._showTabContent(this._curSel)
    },

    onClickWeekTask: function (event) {
        Global.playComEff("ch_btn_click");
        if (event && this._curSel == BONUS_TAB.WeekTask) {
            return
        }

        let taskOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.WEEKLYTASK)
        if (!taskOpen) {
            // cc.vv.FloatTip.show('Feature open at level '+Global.SYS_OPEN.WEEKLYTASK)
            this._showLockTip(event.node, Global.SYS_OPEN.WEEKLYTASK)
            return
        }

        this._curSel = BONUS_TAB.WeekTask
        // //点完后隐藏
        // let self = this
        // let endCall = function(){
        //     self.onClickArrow()
        // }
        this._showTab(event.node)
        this._showTabContent(this._curSel)
    },

    onClickMainTask: function (event) {
        Global.playComEff("ch_btn_click");
        if (event && this._curSel == BONUS_TAB.MainTask) {
            return
        }
        this._curSel = BONUS_TAB.MainTask
        // //点完后隐藏
        // let self = this
        // let endCall = function(){
        //     self.onClickArrow()
        // }
        this._showTab(event.node)
        this._showTabContent(this._curSel)
    },

    _showLockTip: function (node, lv) {
        let node_lock = cc.find("channel/spr_lock_tip", this.node)
        node_lock.active = true
        Global.setLabelString("lbl_val", node_lock, cc.js.formatStr("UNLOCK AT  LEVEL %s", lv))
        node_lock.active = true
        node_lock.y = node.y
        node_lock.opacity = 255
        node_lock.stopAllActions()
        cc.tween(node_lock)
            .delay(2)
            .to(0.1, { opacity: 0 })
            .start()
    },

    _showTab: function (node, endCall) {
        // let obj = cc.find('channel/sel_bg', this.node)
        // // obj.y = node.y
        // obj.active = true
        // cc.tween(obj)
        // .to(0.2,{y:node.y})
        // .delay(0.1)
        // .call(()=>{
        //     if(endCall){
        //         endCall()
        //     }
        // })
        // .start()

        //
        let func = function (obj, bShow) {
            let selImg = cc.find('icon_light', obj)
            let unselImg = cc.find('icon_gray', obj)
            let lbl = cc.find('Label', obj)
            selImg.active = bShow
            unselImg.active = !bShow
            lbl.color = !bShow ? new cc.Color().fromHEX("#ffffff") : new cc.Color().fromHEX("#52FFC6")
        }
        if (this._preSelBtn) {
            func(this._preSelBtn, false)
        }
        func(node, true)
        this._preSelBtn = node

        if (endCall) endCall()
    },

    _showTabContent: function (val) {

        let node_task = cc.find("node_task", this.node)
        let node_activity = cc.find("node_activity", this.node)
        let node_main = cc.find("node_maintask", this.node)


        node_activity.active = (val == BONUS_TAB.Activity || val == BONUS_TAB.Rewards)
        if (node_activity.active) {
            node_activity.getComponent("bonus_activity").showType(val)
        }
        node_task.active = (val == BONUS_TAB.DayTask) || (val == BONUS_TAB.WeekTask)
        if (node_task.active) {
            node_task.getComponent("bonus_task").setShowTaskType(val, this._bRefushDayTask)
            this._bRefushDayTask = null
        }
        node_main.active = (val == BONUS_TAB.MainTask)
        if (node_main.active) {
            node_main.getComponent("bonus_maintask").setShowTask(this._bRefushMainTask)
            this._bRefushMainTask = true

        }
    },

    onEventShareAction: function () {
        this._bRefushDayTask = true
        this._bRefushMainTask = true
    },

    onClickArrow: function (bWithAudio) {
        if (bWithAudio) {
            Global.playComEff("ch_btn_click");
        }


        this._bExpand = !this._bExpand
        let tarPosx = this._bExpand ? 433.5 : 612
        // if(cc.sys.platform == cc.sys.IPAD){
        //     tarPosx = this._bExpand?cc.winSize.width/2-107:cc.winSize.width/2+95
        // }
        let nodeChannel = cc.find("channel", this.node)
        cc.tween(nodeChannel)
            .to(0.2, { x: tarPosx })
            .start()
        let arrow = cc.find('btn_arrow/arrow', nodeChannel)
        arrow.scaleX = this._bExpand ? -1 : 1
        let btnEmpty = cc.find('btn_empty', this.node)
        btnEmpty.active = this._bExpand
        arrow.x = 23
        Global.ArrowAction(arrow, cc.v2(15, 0), 0.5)

    },

    onEventBonusTab: function (data) {
        let path = data.detail

        if (path == "Activity") {
            this._curSel = BONUS_TAB.Activity
        }
        else if (path == "Login") {
            this._curSel = BONUS_TAB.Rewards
        }
        else if (path == "Daily") {
            this._curSel = BONUS_TAB.DayTask
        }

        this.showDefaultTab()
    }




    // update (dt) {},
});
