let SHARE_FROM_TYPE = {
    FRIEND: 1
}

cc.Class({
    extends: cc.Component,

    properties: {
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnShare = cc.find('share_btn', this.node)
        Global.btnClickEvent(btnShare, this.onClickShare, this)
        let btnSpin = cc.find('wheel/frame/spine_btn', this.node)
        Global.btnClickEvent(btnSpin, this.onClickSpin, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_SHARE_SUCC, this.onRcvShare, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SHARE_WHEEL, this.onRcvGetShareWheel, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_SPIN_WHEEL, this.onRcvSpinWheel, this);

        this.shareCount = 0
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHARE_SUCC, this.onRcvShare, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SHARE_WHEEL, this.onRcvGetShareWheel, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SPIN_WHEEL, this.onRcvSpinWheel, false, this);
    },

    show(shareMsg) {
        this.shareCount = shareMsg.shareCnt
        //初始化灯泡
        if (shareMsg.shareCnt > 7) {
            shareMsg.shareCnt = 7
        }

        //分享奖励金币
        let showStr = Global.FormatNumToComma(shareMsg.shareReward[0].count)
        Global.setLabelString("lay_per_share/val", this.node, showStr)
        //签到天数
        Global.setLabelString("day/lbl_val", this.node, "Day:" + shareMsg.shareCnt + "/7")

        //转盘按钮不能点击
        cc.find('wheel/frame/spine_btn', this.node).getComponent(cc.Button).interactable = shareMsg.canSpin

        //满了七次不能继续分享
        cc.find('share_btn', this.node).getComponent(cc.Button).interactable = !shareMsg.canSpin

        //初始化转盘
        let pan = cc.find("wheel/pan", this.node)
        pan.destroyAllChildren()
        let item0 = cc.find("wheel/item0", this.node)
        let item1 = cc.find("wheel/item1", this.node)

        let wheelData = shareMsg.wheel
        for (let i = 0; i < 6 && i < wheelData.length; i++) {
            let itemNode = null
            if (shareMsg.wheel[i].rewards.length > 1) {
                itemNode = cc.instantiate(item1)
                itemNode.parent = pan
                let type = shareMsg.wheel[i].rewards[1].type
                var count = (type == Global.PROP_ID.HERO_CARD) ? 5 : shareMsg.wheel[i].rewards[1].count
                let num = (type == Global.PROP_ID.DOUBLE_LEVEL_EXP) ? count / 3600 + 'h' : 'X' + count
                let url = 'common/rewarditem/' + type
                cc.loader.loadRes(url, cc.SpriteFrame, (err, data) => {
                    if (!err && cc.isValid(itemNode)) {
                        let icon = cc.find('icon', itemNode)
                        if (cc.isValid(icon)) {
                            icon.getComponent(cc.Sprite).spriteFrame = data
                        }

                    }
                })
                Global.setLabelString("lbl_num", itemNode, num)
            } else {
                itemNode = cc.instantiate(item0)
                itemNode.parent = pan
            }

            itemNode.active = true
            itemNode.position = cc.v2(0, 0)
            itemNode.angle = i * 60
            let coinStr = Global.convertNumToShort(wheelData[i].rewards[0].count, 1000, 2);
            Global.setLabelString("lbl_coin", itemNode, coinStr)
        }
    },

    setItem(id, num, itemNode) {

    },

    onClickSpin: function () {
        cc.vv.RedSys.clearRedTip(7)
        this.sendSpinWheel()
        cc.find('wheel/frame/spine_btn', this.node).getComponent(cc.Button).interactable = false
        //初始化次数
        Global.setLabelString("day/lbl_val", this.node, "Day:0/7")
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_SHAREFB_SHAREANDENJOY_SHARETOFB7_SPIN, cc.vv.gameData ? 1 : 0)
    },


    sendGetShareWheel: function () {
        var req = { 'c': MsgId.REQ_GET_SHARE_WHEEL };
        cc.vv.NetManager.sendAndCache(req);
    },

    onRcvGetShareWheel: function (msg) {
        if (msg.code == 200) {
            this.show(msg)
        }
    },

    onRcvSpinWheel: function (msg) {
        if (msg.code == 200) {
            this._lunpanMove(msg.wheelId, msg.rewards)
        }
    },

    onRcvShare: function (msg) {
        if (msg.code == 200) {
            if (msg.coin && msg.coin > 0) {
                //显示金币奖励
                let form_world_pos = cc.find("lay_per_share/val", this.node).convertToWorldSpaceAR(cc.v2(0, 0))
                Global.RewardCoinFly(msg.coin, form_world_pos)
                //刷新是否分享成功
                this.sendGetShareWheel()
            }
        }
    },

    sendSpinWheel: function () {
        var req = { 'c': MsgId.REQ_SPIN_WHEEL };
        cc.vv.NetManager.send(req);
    },

    //轮盘转动
    _lunpanMove: function (idx, rewards) {
        Global.playCashEff('fbshare/wheel_bonus_rotate')
        let objLun;     //转盘
        let nCir = 4;   //圈数
        let nTotal;     //转盘总转动角度

        objLun = cc.find('wheel/pan', this.node);

        nTotal = (idx - 1) * (360 / 6) + nCir * 360;

        let self = this;
        objLun.angle = 0
        cc.tween(objLun)
            .by(Global.WHEEL_SPIN_TIME, { angle: -nTotal }, { easing: 'quadInOut' })
            .call(() => {
                Global.playCashEff('fbshare/wheel_bonus_result')
            })
            .delay(1)
            .call(() => {
                self._showResultRewards(rewards)
                cc.find('share_btn', this.node).getComponent(cc.Button).interactable = true
            })
            .start();
    },

    _showResultRewards: function (rewards) {
        // let coin = rewards[0].count
        // let toNode = cc.find(Global.HALL_COIN_NODE_PATH);
        // cc.loader.loadRes("CashHero/prefab/fbShare/fbColloctReward",cc.Prefab, (err, prefab) => {
        //     if(!err){
        //         let objParent = cc.find('Canvas')
        //         if(!cc.find('fbColloctReward',objParent)){
        //             let endCall = function(){
        //                 cc.vv.UserManager.AddCoin(coin,true)
        //             }
        //             let node = cc.instantiate(prefab)
        //             node.name = 'fbColloctReward'
        //             node.parent = objParent
        //             let scp = node.getComponent('fbColloctReward')
        //             if(scp){
        //                 scp.setRd(rewards)
        //                 scp.setCoin(toNode,endCall)
        //             }
        //         }
        //     }
        // })

        let pos = cc.find("wheel/pan", this.node).convertToWorldSpaceAR(cc.v2(0, 0))
        Global.RewardFly(msg.rewards, pos, () => {

        })
    },

    //nType:1 来自好友，default: 来自bonus
    doShareAction: function (nType) {
        this._shareFrom = nType
        Global.playComEff("ch_btn_click");
        //直接分享
        if (Global.isNative()) {
            let imgUrl = 'https://global.rummyslot.com/fb/index2.html'
            let content = "It's time to WIN!\nAll you have to do is enjoy the Free Coins!"
            if (this._shareFrom == SHARE_FROM_TYPE.FRIEND) {
                imgUrl = 'https://global.rummyslot.com/fb/index3.html'
                content = "We found the best free casino game Cash Hero for slots fans!\nI've been playing for hours and really enjoy the great jackpots here!\nCome on,play with me!";
            }
            cc.vv.FBMgr.fbShareWeb(imgUrl, null, content, this.onShareBack.bind(this));
        }
        else {
            this.onShareBack({ result: "1" })
        }
    },

    onShareBack: function (data) {
        //分享成功/失败都算分享了
        cc.vv.RedSys.clearRedTip(7)
        if (data.result == "1" || data.result == "-2") {
            var req = { 'c': MsgId.REQ_SHARE_SUCC };
            if (this._shareFrom == SHARE_FROM_TYPE.FRIEND) {
                req = { 'c': MsgId.REQ_FRIEND_SHARE };
            }
            req.type = 1;
            cc.vv.NetManager.send(req);

            Global.dispatchEvent("FBSHARE_ACTION")

        }
    },

    onClickShare: function () {
        cc.vv.RedSys.clearRedTip(7)
        //下一次一定成功
        if (this.shareCount == 6) {
            Global.playCashEff('fbshare/win')
        }
        this.doShareAction()
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_SHAREFB_SHAREANDENJOY_SHARETOFB)
    },
});
