        onEventNextPopUI: function () {
            let id = null;

            //开启下一个弹窗
            cc.vv.QueueWinMrg.nextPop()

            if (cc.vv.gameData && this.modeType == this.ModeType.LOGIN_POP) {
                console.log('游戏里，不用弹登陆弹窗！！')
                return
            }
            if (this.modeType == this.ModeType.LOGIN_POP) id = this.getLoginPopId();
            if (this.modeType == this.ModeType.NOT_COIN_POP) id = this.getNotEnoughPopId();


            this._popById(id)
        },

        onEventPOPUI: function (data) {
            let val = data
            this._popById(val)
        },

        _popById: function (id) {
            if (id) {


                switch (id) {
                    case 1: //新手礼包
                        this.popNewerGift();
                        break;
                    case 2: //one time only
                        this.popOneTimeOnly();
                        break;
                    // case 3: //开服活动
                    //     this.popNewServiceAct();
                    //     break;
                    case 4: //FB分享
                        if (Global.isAndroidReview) {
                            this.popFbShare();
                        } else {
                            cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
                        }
                        break;
                    case 5: //签到
                        this.popSign();
                        break;
                    case 6: //商城(客户端)
                        this.popShop();
                        break;
                    case 7: //新手开始游戏
                        this.popStartGame()
                        break;
                    case 8: //金猪（也叫银行）
                        this.popPigBank()
                        break;
                    case 9: //等级礼包
                        this.popLvupGift()
                        break;
                    case 10: //离线礼包
                        this.popOfflineGift()
                        break;
                    case 11: //quest弹窗提示
                        this.popGuestplay()
                        break;
                    case 12://月卡弹窗
                        this.popMonthCard()
                        break
                    case 13://bingo新赛季弹窗
                        this.popNewSeason()
                        break
                    case 14://fb分享弹窗
                        this.popFBShare()
                        break
                    case 15://成长基金广告
                        this.popGrowthFund()
                        break
                    case 16://首充
                        this.popFirstBuyGift()
                        break
                    case 17://绑定FB广告
                        this.popFBBindingAd()
                        break
                    case 18://召回
                        this.popNoticeRewards()
                        break;
                    case 19://abTest
                        this.popABTest(19)
                        break;
                    case 20://转盘弹窗
                        this.popPrizeWheel()
                        break;
                    case 21://cash back
                        this.popCashBack()
                        break;
                    case 22://砸蛋
                        this.loadSmashEgg()
                        break;
                    case 23://骑士
                        this.loadKnight()
                        break;
                    case 24://限时购买
                        this.popLimitShop()
                        break;
                    case 100:
                        this.popGuestTips()
                        break;
                    case 101:
                        //俱乐部邀请函
                        this.popClubInvite()
                        break;
                    default: //没有处理，直接弹下一个
                        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
                        break;
                }
            }
            else {
                Global.dispatchEvent(EventId.SERVER_POP_END, this.modeType)
                //弹窗都关了 在游戏内调用队列
                if (cc.vv.gameData) {
                    cc.vv.QueueWinMrg.startPop()
                }


            }
        },

        //
        isHasLoginPopId: function (id) {
            let bHave = false
            for (let i = 0; i < this.loginPopList.length; i++) {
                if (this.loginPopList[i] == id) {
                    bHave = true
                    break
                }
            }
            return bHave
        },

