        delLoginPopId: function (id) {
            let delFun = function (arr, val) {
                if (arr) {
                    let delKey = -1
                    for (let i = 0; i < arr.length; i++) {
                        if (arr[i] == val) {
                            delKey = i
                            break
                        }
                    }
                    arr.splice(delKey, 1)
                }

            }
            delFun(this.loginPopList, id)
        },

        onEventGoGame: function (data) {
            this._need_go_id = data

            Global.dispatchEvent("enter_game", this._need_go_id);
            // this._doCheckEnter(this._need_go_id)


        },

        onEventLvUp: function () {
            let bGuest = cc.vv.UserManager.getLoginType() == Global.LoginType.Guest
            let bBindFb = cc.vv.UserManager.isBindFb()
            let bLv20 = cc.vv.UserManager.getCurLv() >= 20
            let bShow = Global.getLocal('GuestTip_lv20')
            if (bGuest && !bBindFb && bLv20 && !bShow) {
                this.loginPopList.push(100)
                if (this.loginPopIdx + 1 >= this.loginPopList.length) {
                    this.loginPopIdx = this.loginPopList.length - 2
                }
            }

        },

        _doCheckEnter: function (gameId) {
            if (!gameId) {
                return
            }
            if (cc.vv.UserManager.isDownloadSubGame(gameId)) {
                let self = this;
                //清理标准位
                this._need_go_id = null
                let enterFunc = function () {
                    if (!cc.vv.AppData.getIsInGame()) {
                        //Global.dispatchEvent("enter_game", gameId);
                        let ssid = 2
                        cc.vv.GameManager.sendEnterGameReq(gameId, ssid);
                    }
                }
                //发布后 By JerryWong
                let innerGame = cc.vv.UserManager.isNoNeedDownGame(gameId) //内置游戏
                if (!Global.publishMode || innerGame) {
                    enterFunc()
                } else {
                    let gameCfg = cc.vv.GameItemCfg[gameId]
                    console.log('>>>> p1、加载子包: ' + gameCfg.name)
                    if (gameCfg) {
                        cc.loader.downloader.loadSubpackage(gameCfg.name, (err) => {
                            if (!err) {
                                console.log('>>>> p2、加载子包成功：' + gameCfg.name)
                                enterFunc()
                            }
                            else {
                                console.log('>>>> p3、加载子包错误：' + gameCfg.name + ";" + err)
                            }
                        })
                    }
                }
            } else {
                cc.vv.SubGameUpdateNode.emit("check_subgame", gameId);
            }
        },

        onDownloadSuccess: function (data) {
            let val = data
            if (val && this._need_go_id) {
                if (this._need_go_id == val) {
                    this._doCheckEnter(val)
                }
                else {
                    console.log(cc.js.formatStr('需要进入的游戏：%s,更新完成的游戏：%s', this._need_go_id, val))
                }
            }
        }
