    _showPrivateReddot: function () {
        let flag = false
        for (let i = 0; i < this._listData.length; i++) {
            if (this._listData[i].unreadcnt > 0) {
                flag = true
                break
            }
        }
        if (!flag) {
            cc.vv.RedSys.clearRedTip(17)
        } else {
            cc.vv.RedSys.setRedTip(17)
            Global.dispatchEvent(EventId.REFUSH_RED_TIPS)
        }
    },

    onEventClickChatItem: function (data) {
        // 私聊对象的UID
        this._clickUID = data.detail.uid
        this._fromType = data.detail.fromType

        this.node.active = false

        if (this._fromType == 2) {
            //初始化uid的数据 再判断是否需要显示红点
            let _redFlag = false
            for (let i = 0; i < this._listData.length; i++) {
                if (this._listData[i].uid == this._clickUID) {
                    this._listData[i].unreadcnt = 0
                    continue
                }
                if (this._listData[i].unreadcnt > 0) {
                    _redFlag = true
                }
            }

            if (!_redFlag) {
                cc.vv.RedSys.clearRedTip(17)
            }
        }
    },

    ShowListItem: function (item, idx) {
        let itemData = this._listData[idx]
        if (itemData) {
            item.active = true;
            item.getComponent('CH_FriendListItem').init(itemData, this, this._bDelModel)
        }
        else {
            item.active = false
        }
    },

    onRcvFriendsList: function (msg) {
        if (msg.code == 200) {
            this._listData = msg.items;
            this._rescardCnt = msg.restCnt
            this._hasFriends = msg.hadFriends
            this._maxFriends = msg.maxFriends
            this._copyData = null
            //处理list数据
            this._listData = this.sortList(this._listData)
            this.refushUI()
            this.showFriendMaxNum()
        }
    },

    showFriendMaxNum: function () {
        let node_num = cc.find("bottom_op/friend_num", this.node)

        let showMax = Math.max(this._hasFriends, this._maxFriends)
        Global.setLabelString("lbl_num", node_num, cc.js.formatStr("(%s/%s)", this._hasFriends, showMax))
    },

    getMaxFriends: function () {
        return this._maxFriends
    },
    getHaveFriends: function () {
        return this._hasFriends
    },

    onEventUpdateFriendData: function (data) {
        let _objData = data.detail.datalist
        this.refushListData(_objData)
    },

    //更新list数据
    refushListData: function (data) {
        for (let j = 0; j < data.length; j++) {
            for (let i = 0; i < this._listData.length; i++) {
                if (this._listData[i].uid == data[j].uid) {
                    this._listData[i].unreadcnt = data[j].unreadcnt
                    // return this._listData[i]
                    // break
                }
            }
        }
        this.refushUI()
    },

    //list数据online排序
    sortList(sortData) {
        // console.log('sortData length:', sortData.length)
        // var listItem = null
        // var num = 0
        // for (let i = 0; i < sortData.length; i++) {
        //     if (sortData[i].isonline) {
        //         // console.log('i:', i)
        //         for (let j = num; j <= i; j++) {
        //             if (!sortData[j].isonline) {
        //                 if (j == i) {
        //                     num = i
        //                     break
        //                 } else {
        //                     listItem = sortData[j]
        //                     sortData[j] = sortData[i]
        //                     sortData[i] = listItem
        //                     listItem = null
        //                     num = j
        //                     break
        //                 }
        //             } else if (sortData[j].playername === sortData[i].playername) {
        //                 num = i
        //                 break
        //             }
        //         }
        //     }
        // }
        sortData.sort((a, b) => {
            let aVal = a.hastake == 0 ? 1 : 0
            let bVal = b.hastake == 0 ? 1 : 0
            if (aVal != bVal) {
                return bVal - aVal
            }
            else {
                let aOnline = a.isonline ? 1 : 0
                let bOnline = b.isonline ? 1 : 0
                if (aOnline != bOnline) {
                    return bOnline - aOnline
                }
                else {
                    return b.uid - a.uid
                }
            }
        })
        return sortData
    },

