    //更新本地数据
    //type: 1:send 2:recv
    updateLocalData: function (type, uid, val) {
        let bCollectAll = false
        let bSendAll = false
        for (let i = 0; i < this._listData.length; i++) {
            let item = this._listData[i]
            if (item.uid == uid || uid == -1) {
                if (type == 1) {
                    item.send = val
                }
                if (type == 2) {
                    item.hastake = val
                }
            }
            if (item.send == 0) {
                bSendAll = true
            }
            if (item.hastake == 0) {
                bCollectAll = true
            }
        }
        // let btnCollectAll = cc.find('bottom/btn_collect_all',this.node)
        // btnCollectAll.getComponent(cc.Button).interactable = bCollectAll
        // let btnSendAll = cc.find('bottom/btn_send_all',this.node)
        // if(!bCollectAll){
        //     btnSendAll.active = bSendAll 
        // }else{
        //     //有collect 优先显示collect
        //     btnSendAll.active = false 
        // }
        this.checkReddot()
    },

    //更新显示是否是首次分享
    showShareState: function (val) {
        let bFirst = val > 0
        let coin_icon = cc.find('bottom/btn_fackbook/coin_ccon', this.node)
        let lbl_coin = cc.find('bottom/btn_fackbook/Label', this.node)
        lbl_coin.getComponent(cc.Label).string = Global.formatNumShort(val, 0)
        let lbl_share = cc.find('bottom/btn_fackbook/lbl_share', this.node)
        coin_icon.active = bFirst
        lbl_coin.active = bFirst
        lbl_share.active = !bFirst
    },

    onRcvShareCoin: function (msg) {
        if (msg.code == 200) {
            this.showShareState(0)
        }
    },

    //添加了好友
    onFriendAdded(friendInfo) {
        if (!this._listData) return
        if (this._copyData) {
            this._copyData.push(friendInfo)
        }

        this._listData.push(friendInfo)
        this._hasFriends += 1
        this.refushUI()
        this.showFriendMaxNum()
    },
    //删除了好友
    onFriendRemoved(friendids, bRefush = true) {
        if (!this._listData) return
        if (!friendids || friendids.length <= 0) return

        let delKey
        for (let i = 0; i < friendids.length; i++) {
            let friendid = friendids[i]
            for (let j = 0; j < this._listData.length; j++) {
                if (friendid == this._listData[j].uid) {
                    this._hasFriends -= 1
                    this._listData.splice(j, 1)
                    delKey = j
                    break
                }
            }

            this.delCopData(friendid)
        }
        if (bRefush) {
            this.refushUI()
        }

        this.showFriendMaxNum()
        return delKey
    },

    getFriendList() {
        let lst = []
        for (let i = 0; i < this._listData.length; i++) {
            lst.push(this._listData[i])
        }
        return lst
    },

