    checkReddot() {
        let redType8 = 0
        let redType21 = 0
        for (let i = 0; i < this._listData.length; i++) {
            let item = this._listData[i]
            if (item.hastake == 0) {//可以领取
                redType8 = 1
            }
            if (item.seek_card || (item.self_seek && item.self_seek.status == 1)) {
                redType21 = 1
            }
        }
        if (redType8 == 0) {
            cc.vv.RedSys.clearRedTip(8)
        }
        if (redType21 == 0) {
            cc.vv.RedSys.clearRedTip(21)
        }

    },
    getRestCardCnt: function () {
        return this._rescardCnt
    },

    removeRestCardCnt: function () {
        this._rescardCnt -= 1
    },

    onClickDelToggle: function (event) {
        Global.playComEff("ch_btn_click");
        let del_toggle = cc.find("bottom_op/btn_mode", this.node)
        let val = del_toggle.getComponent(cc.Toggle).isChecked
        if (!val) {
            //进入删除模式
            Global.dispatchEvent("friend_del_model", 1)
            this._bDelModel = true
        }
        else {
            //退出删除模式
            Global.dispatchEvent("friend_del_model", 0)
            this._bDelModel = null
        }
    },

    onRcvRemoveFriend: function (msg) {
        if (msg.code == 200) {
            let self = this




            // 删除


            if (msg.frienduids.length > 1) {

                this.onFriendRemoved(msg.frienduids)
            }
            else {
                let delKey = this.onFriendRemoved(msg.frienduids, false)
                let delCall = function () {
                    self.refushUI()
                }
                this.friendList.aniDelItem(Number(delKey), delCall)
            }


        }
    },

    onRcvRecomlist: function (msg) {
        if (msg.code == 200) {
            this._recomlistdata = msg.recommendItems
            this._showRecomList()

        }
    },

    _showRecomList: function () {
        for (let i = 0; i < 3; i++) {
            let item = cc.find("recom_list/lay_recoms/recom_item" + (i + 1), this.node)
            let itemData = this._recomlistdata[i]
            item.active = itemData ? true : false
            if (itemData) {
                item.getComponent("CH_FriendsRecomItem").init(itemData)
            }

        }
    },

    _doDelRecomList: function (uid) {
        let addid = uid
        let delKey = null
        for (let i = 0; i < this._recomlistdata.length; i++) {
            if (this._recomlistdata[i].uid == addid) {
                delKey = i
                break
            }
        }
        if (delKey != null) {
            this._recomlistdata.splice(delKey, 1)

            let nLen = this._recomlistdata.length
            if (nLen < 4) {
                this.reqRecomendlist()
            }
            else {
                this._showRecomList()
            }


        }
    },

    onRcvAddFriend: function (msg) {
        if (msg.code == 200 && !msg.spcode) {

            this.onFriendAdded(msg.friend)
            //推荐中删除已经添加的
            this._doDelRecomList(msg.friend.uid)


        }
        else {
            let spcode = msg.spcode
            if (spcode) {
                if (spcode == 619) {
                    let self = this
                    let str = 'Friends quantity reach maximum. Upgrade your status right now?'
                    let sureCall = function () {
                        self.onClickFriendNums()
                    }
                    let cancelCall = function () {

                    }
                    cc.vv.AlertView.showSimple(str, sureCall, cancelCall)
                    return
                }
                else if (spcode == 620) {
                    cc.vv.FloatTip.show("Aready add friend Success!");
                }
                else if (spcode == 621) {
                    cc.vv.FloatTip.show("The player's friends have reached the limit！");
                    //同时删除这个推荐好友
                    if (msg.frienduid) {
                        this._doDelRecomList(msg.frienduid)
                    }

                }
                else {
                    cc.vv.FloatTip.show('Spcode:' + spcode);
                }
            }

        }


    },

    onClickSearch: function () {
        Global.playComEff("ch_btn_click");
        cc.loader.loadRes("CashHero/prefab/friend/CH_friend_search", cc.Prefab, (err, prefab) => {
            if (!err) {
                let old = cc.find("Canvas").getChildByName('CH_friend_search')
                if (!old) {
                    let node = cc.instantiate(prefab);
                    node.parent = cc.find("Canvas");

                }
            }
        })
    },

    onEditChange: function () {
        let searchKey = this._searchEdit.getComponent(cc.EditBox).string
        let results = []
        if (!this._copyData) {
            this._copyData = Global.copy(this._listData)
        }

        for (let i = 0; i < this._copyData.length; i++) {
            let item = this._copyData[i]
            if (item && item.playername && item.playername.indexOf(searchKey) > -1) {
                results.push(item)
            }
        }

        this.showByFiter(results)


    },

    showByFiter: function (datas) {
        this._listData = datas
        this.friendList.numItems = this._listData.length > 0 ? this._listData.length : 0;
    },

    delCopData: function (uid) {
        if (this._copyData) {
            let delKey = null
            for (let i = 0; i < this._copyData.length; i++) {
                let item = this._copyData[i]
                if (item && item.uid == uid) {
                    delKey = i
                }
            }
            if (delKey != null) {
                this._copyData.splice(delKey, 1)
            }
        }

    },

    isFriend: function (uid) {
        let res = false
        if (this._listData) {
            for (let i = 0; i < this._listData.length; i++) {
                let item = this._listData[i]
                if (item && item.uid == uid) {
                    res = true
                    break
                }
            }
        }

        return res
    },

    onClickInvite: function () {
        Global.playComEff("ch_btn_click");
        cc.vv.UserManager.goSystemUI("game_invite")
    }

