/**
 * 奖励显示
 */
cc.Class({
    extends: cc.Component,

    statics: {

        _coinNodePool: null,
        _hitNodePool: null,
        _coinAtlas: null,

        init: function () {
            this._coinNodePool = new cc.NodePool();
            this._hitNodePool = new cc.NodePool();


        },

        /**
         * [
         *  {
         *  type:物品ID
         *  data:物品数量/碎片信息
         *  srcObj:起点
         *  toObj:终点
         * }
         * ]
         */
        showRewards: function (rdArray) {
            for (let i = 0; i < rdArray.length; i++) {
                let item = rdArray[i]
                let itemType = item.type
                if (itemType == Global.PROP_ID.COIN) {
                    this._showCoin(item)
                }
            }
        },

        //显示金币奖励
        _showCoin: function (item) {

        },

        createCoin() {
            let coin = 0;
            if (this._coinNodePool.size() > 0) {
                coin = this._coinNodePool.get();
            } else {
                coin = new cc.Node("coin");
                let spr = coin.addComponent(cc.Sprite);
                let ani = coin.addComponent(cc.Animation);
                spr.sizeMode = cc.Sprite.SizeMode.RAW;
                var frames = [];
                let start_idx = Global.random(1, 23);
                for (let i = 0; i < 23; i++) {
                    let idx = (start_idx + i) % 23 + 1;
                    var frame = this._coinAtlas.getSpriteFrame("e0" + ((idx < 10) ? ("0" + idx) : idx));
                    if (frame) {
                        frames.push(frame);
                    }
                    else
                        break;
                }
                var clip = cc.AnimationClip.createWithSpriteFrames(frames, 40);
                clip.name = "anim";
                clip.wrapMode = cc.WrapMode.Loop;
                ani.addClip(clip);
                ani.play("anim");
            }

            return coin;
        },
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    // start () {

    // },

    // update (dt) {},
});
