let UIDATA = [
    { 'fbBtn': 1, 'str': 'And get rewards immediately!', 'strPos': [0, -116], 'strLen': 760, 'strLineH': 40, 'yesOrNo': 0 },
    { 'fbBtn': 1, 'str': 'And exchange cards with friends immediately!', 'strPos': [0, -140], 'strLen': 560, 'strLineH': 60, 'yesOrNo': 0 },
    { 'fbBtn': 0, 'str': 'Are you sure to send?', 'strPos': [0, 0], 'strLen': 760, 'strLineH': 40, 'yesOrNo': 1 },
    { 'fbBtn': 0, 'str': "You don't have this hero fragment.", 'strPos': [0, 0], 'strLen': 760, 'strLineH': 40, 'yesOrNo': 0 },
];

let FROMWHERE = {
    MAIL: 1,
    CARD: 2,
    SEND: 3,
    NOTHAS: 4,
};

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    onLoad() {
        Global.btnClickEvent(cc.find('fbBtn', this.node), this.onClickFbShare, this)
        Global.btnClickEvent(cc.find('lay_btns/btn_cancel', this.node), this.onClickClose, this)
        Global.btnClickEvent(cc.find('lay_btns/btn_sure', this.node), this.onClickSure, this)
    },

    start() {
        this.initTip()


    },

    initBoxType(boxType) {
        this._boxType = boxType
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MAIL_FBBIND_POP, this._boxType)
        this._tipType = FROMWHERE.MAIL
    },

    // 1 邮箱提示 2 卡牌详情 3 可以发送 4 没有碎片
    setFrom(from, callFunc, chatID) {
        this._tipType = from
        if (callFunc) {
            this._callFunc = callFunc
        }
        if (chatID) {
            this._chatID = chatID
        }
    },

    // {'fbBtn': 1, 'str': 'And get rewards immediately!', 'strPos':[0,-116], 'strLen':760, 'strLineH':40, 'yesOrNo': 0},
    initTip() {
        //节点属性
        let lblNode = cc.find('label', this.node)
        lblNode.y = UIDATA[this._tipType - 1].strPos[1]
        lblNode.width = UIDATA[this._tipType - 1].strLen
        //label属性
        this.setTipStr()
        //fb按钮
        cc.find('fbBtn', this.node).active = UIDATA[this._tipType - 1].fbBtn
        //yesOrNo按钮
        cc.find('lay_btns', this.node).active = UIDATA[this._tipType - 1].yesOrNo
    },

    setTipStr() {
        let lbl = cc.find('label', this.node).getComponent(cc.Label)
        // lbl.string = UIDATA[this._tipType-1].str
        // //设置key 刷新
        let lbli18Scp = lbl.node.getComponent("LanguageLabel")
        lbli18Scp.id = 'fbbind_tip' + this._tipType
        lbli18Scp.updateLabel()

        lbl.lineHeight = UIDATA[this._tipType - 1].strLineH
    },

    fbConnect() {
        Global.playComEff("ch_btn_click");
        let self = this
        // cc.vv.PlatformApiMgr.fbLoginOut();
        cc.vv.PlatformApiMgr.fbLogin((cbData) => {
            console.log("=======LMSlots--FbAuth=========:  " + JSON.stringify(cbData));
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = { c: MsgId.REQ_BIND_FACEBOOK };
                req.accesstoken = cbData.token;
                req.user = cbData.uid;
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req);
                self.onClickClose()
            }
            else {
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
            }
        });
    },

    onClickFbShare() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MAIL_FBBIND_CONNECT, this._boxType)
        this.fbConnect()
    },

    onClickClose() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MAIL_FBBIND_CLOSE, this._boxType)
        this.node.destroy()
    },

    onClickSure() {
        cc.find('lay_btns/btn_sure', this.node).getComponent(cc.Button).interactable = false
        if (this._chatID) {
            //发给服务器
            if (this._callFunc) {
                this._callFunc()
            }
            this.sendReqCard()
        }
        this.node.destroy()
    },

    sendReqCard() {
        let req = { c: MsgId.REQ_PRIVATE_SENDCARD }
        req.chatid = this._chatID
        cc.vv.NetManager.send(req)

        //本地更新聊天记录数据
        Global.dispatchEvent(EventId.REFRUSH_PRIVATE_CARD, { chatID: this._chatID })
    },

    // update (dt) {},
});
