/**
 * benifist弹窗
 */
const List = require('List')
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        listview: List,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find('btn_close', this.node)
        Global.btnClickEvent(btn_close, this.OnClickClose, this)
    },

    start() {
        this.listview.numItems = this._redwards.length
        Global.playComEff("ch_popup");
    },

    showBenifist: function (rewards, msg) {
        this._redwards = rewards
        this._msg = msg
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BENEFITS_POP, this._msg)
    },

    OnClickClose: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BENEFITS_CLOSE, this._msg)

        Global.playComEff("ch_close");
        this.node.destroy()
    },

    onListRender: function (item, idx) {
        let itemData = this._redwards[idx]
        item.active = itemData ? true : false

        if (item) {
            //
            cc.find('icon', item).getComponent('CH_RewardItem').init(itemData.type, itemData.count)
            let splitline = cc.find('line', item)
            splitline.active = (idx == this._redwards.length - 1) ? false : true
        }
    }

    // update (dt) {},
});
