/**
 * 聊天中的排行榜
 */

cc.Class({
    extends: cc.Component,

    properties: {
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_bet = cc.find("bg/btn_bet", this.node)
        Global.btnClickEvent(btn_bet, this.onClickBet, this)

    },

    start() {



        this._hasGetList = false


    },

    onRenderListItem: function (item, idx) {
        let data = this._dataList[idx]
        if (data) {
            item.active = true
            item.getComponent('CH_ChatRankItem').init(data, null, this._rankType, this)
        }
        else {
            item.active = false
        }
    },

    isFriend: function (firendUid) {
        return cc.vv.UserManager.isFriend(firendUid)
    },







    setData: function (data, rankType) {
        this._serverData = data
        this._publishtime = data.time
        this._rankType = rankType

        this._dataTop3 = []
        this._dataList = []
        for (let i = 0; i < this._serverData.rank.length; i++) {
            let itemDatas = this._serverData.rank[i]
            itemDatas.rank = i + 1
            if (i < 3) {
                this._dataTop3.push(itemDatas)
            }
            else {
                this._dataList.push(itemDatas)
            }
        }

        this._showTop3Rank()
        this._showListRank()
        let lbl_publish = cc.find("bg/top/time_bg/lbl_time", this.node)
        lbl_publish.getComponent(cc.Label).string = this._publishtime
        //是否显示押注
        let btn_bet = cc.find("bg/btn_bet", this.node)
        btn_bet.active = (this._rankType == 4)
    },

    _showTop3Rank: function () {
        for (let i = 0; i < this._dataTop3.length; i++) {
            let itemData = this._dataTop3[i]
            let itemNode = cc.find('bg/spr_top3/item' + (i + 1), this.node)
            itemNode.getComponent('CH_ChatRankItem').init(itemData, 1, this._rankType, this)
        }
    },
    _showListRank: function () {
        // this.rankList.numItems = this._dataList.length

        let lay_content = cc.find('bg/list_rank/content', this.node)

        for (let i = 0; i < this._dataList.length; i++) {
            let node = cc.find('Item' + (i + 1), lay_content)
            this.onRenderListItem(node, i)
        }
    },
    // _showMyrank:function(){

    // },

    onClickBet: function () {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_RANKQUIZ)

        //显示押注界面
        cc.loader.loadRes("CashHero/prefab/friend/chat_rank_bet", cc.Prefab, (err, prefab) => {
            if (!err) {
                let par = cc.find("Canvas")
                let old = cc.find('chat_rank_bet', par)
                if (!old) {
                    old = cc.instantiate(prefab)
                    old.parent = par
                    old.getComponent('CH_ChatRankBet').init(this._serverData)
                }
            }
        })
    },

    onDestroy() {

        // cc.vv.NetManager.unregisterMsg(MsgId.REQ_ADD_FRIENDS, this.onRcvAddFriend,false,this);
        // cc.vv.NetManager.unregisterMsg(MsgId.REQ_DELETE_FRIENDS, this.onRcvRemoveFriend,false,this);
    },

    // update (dt) {},
});
