
const List = require('List')

cc.Class({
    extends: cc.Component,

    properties: {
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_PVP_RANK, this.onRcvPvpRank, this)
        Global.registerEvent("pvp_rank_score_update", this.onUpdateRankScore, this)
        Global.registerEvent("pvp_rank_refresh", this.requestData, this)

        Global.onClick("bottom/btn_close", this.node, this.onClickClose, this)
        Global.onClick("bottom/btn_rule", this.node, this.onClickRule, this)
        Global.onClick("bottom/btn_challenge", this.node, this.onClickChallenge, this)
        Global.onClick("bottom/btn_record", this.node, this.onClickRecord, this)

        let lst = cc.find("list_ranking", this.node)
        lst.opacity = 0
        lst.runAction(cc.fadeIn(0.25).easing(cc.easeSineIn()))

        Global.playComEff("ch_popup")
        this.requestData()
    },

    formatRank(rank) {
        if (rank <= 1000) return "" + rank
        else return "1000+"
    },

    onUpdateRankScore() {
        Global.setLabelString("bottom/self/lbl_rank", this.node, this.formatRank(cc.vv.UserManager.getPvpRank()))
        Global.setLabelString("bottom/self/lbl_point", this.node, cc.vv.UserManager.getPvpScore())
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PVP_RANK, this.onRcvPvpRank, false, this)
    },

    requestData() {
        cc.vv.NetManager.send({ c: MsgId.REQ_PVP_RANK, limit: 30 })
    },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.parent.destroy()
    },

    onClickRule() {
        let parent = this.node.parent
        cc.loader.loadRes("CashHero/prefab/pvp/pvp_rule", cc.Prefab, (err, prefab) => {
            if (!err) {
                if (cc.isValid(parent) && !parent.getChildByName("pvp_rule")) {
                    let node = cc.instantiate(prefab)
                    parent.addChild(node)
                }
            }
        })
    },

    onClickChallenge() {
        Global.playComEff("ch_btn_click")
        if (this._listData) {
            this.node.active = false
            let match = cc.find("match", this.node.parent)
            match.active = true
        }
    },

    onClickRecord() {
        Global.playComEff("ch_btn_click")
        if (this._listData) {
            this.node.active = false
            let record = cc.find("record", this.node.parent)
            record.active = true
        }
    },

    refushList: function () {
        let taTemp = cc.find("list_ranking/view/ta_2", this.node)
        let content = cc.find("list_ranking/view/content", this.node)
        for (let i = 0; i < 3; i++) {
            let rank_item = cc.find("ta_1/rank_item" + (i + 1), content)
            this.showListItem(rank_item, i)
        }
        let idx = 1
        for (let i = 3; i < this._listData.length; i += 2) {
            idx += 1
            let ta = content.getChildByName("ta_" + idx)
            if (!ta) {
                ta = cc.instantiate(taTemp)
                ta.name = "ta_" + idx
                ta.active = true
                ta.parent = content
            }
            let rank_item1 = ta.getChildByName("rank_item1")
            this.showListItem(rank_item1, i)
            let rank_item2 = ta.getChildByName("rank_item2")
            this.showListItem(rank_item2, i + 1)
        }
    },

    showListItem: function (item, idx) {
        let data = this._listData[idx]
        if (data) {
            let UserHead = cc.find("node_head", item).getComponent("UserHead")
            UserHead.setHead(data.uid, data.usericon)
            Global.setLabelString("lbl_name", item, data.playername)
            //Global.setLabelString("lbl_cc", item, data.cc)
            Global.setLabelString("lbl_point", item, data.coin)
            let lblRank = cc.find("lbl_rank", item)
            if (lblRank) {
                lblRank.getComponent(cc.Label).string = data.ord
            }
            item.active = true
        }
        else {
            item.active = false
        }
    },

    formatTime(sec) {
        let day = Math.floor(sec / (24 * 3600))
        let hour = Math.floor((sec - day * 24 * 3600) / 3600)
        let min = Math.floor(((sec - day * 24 * 3600) % 3600) / 60)
        if (day > 0) {
            return day + " " + cc.vv.Language.lbl_days/*" days  "*/ + "  " + hour + " " + cc.vv.Language.lbl_hours/*" hours"*/
        } else if (hour > 0) {
            return hour + " " + cc.vv.Language.lbl_hours/*" hours  "*/ + "  " + min + " " + cc.vv.Language.lbl_mins/*" mins"*/
        } else if (min > 0) {
            return " " + min + cc.vv.Language.lbl_mins/*" mins"*/
        } else {
            return cc.vv.Language.pvp_ending/*"Ending"*/
        }
    },

    onRcvPvpRank(msg) {
        if (msg && msg.code == 200) {
            this._listData = msg.datalist
            this.refushList()
            Global.setLabelString("bottom/self/lbl_rank", this.node, this.formatRank(msg.myself.ord))
            Global.setLabelString("bottom/self/lbl_point", this.node, msg.myself.score)
            Global.setLabelString("time_bg/lbl_time", this.node, this.formatTime(msg.delayTime))
            let isEnd = msg.delayTime <= 0
            cc.find("time_bg/Label", this.node).active = !isEnd
            cc.find("time_bg/lbl_time", this.node).active = !isEnd
            cc.find("time_bg/lbl_end", this.node).active = isEnd
            cc.vv.UserManager.setPvpRank(msg.myself.ord)
            cc.vv.UserManager.setPvpScore(msg.myself.score)
            cc.vv.UserManager.setPvpCC(msg.myself.cc)
        }
    },


    update(dt) {

    },
});
