/**
 * 红包记录item
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    init: function (data, bMax) {
        //
        let nodeHead = cc.find('node_head', this.node)
        nodeHead.getComponent('UserHead').setHead(data.uid, data.avatar)
        //昵称
        cc.find("lblName", this.node).getComponent(cc.Label).string = data.name;
        //金币
        cc.find("node_coin/lbl_coin", this.node).getComponent(cc.Label).string = Global.FormatNumToComma(Math.floor(data.coin || 0));
        //等级
        cc.find("node_lv/lbl_lv", this.node).getComponent(cc.Label).string = "LV." + data.level;
        //时间
        cc.find('lbl_des', this.node).getComponent(cc.Label).string = Global.getTimeStr(data.time)
        //luck
        cc.find('spr_luck', this.node).active = bMax
    },

    // update (dt) {},
});
