const EffectConfigs = require("Pvp_Effect")

cc.Class({
    extends: cc.Component,

    properties: {
        _battleMgr: null,
        _resMgr: null,
        _roleName: "",
        _lblHp: null,
        _lblMp: null,
        _progHp: null,
        _progMp: null,
        _skillNode: null,
        _maxHp: 0,
        _maxMp: 0,
        _hp: 0,
        _mp: 0,
        _camp: 0,
        _skill: "",
    },

    init(roleInfo, battleMgr, resMgr) {
        this._battleMgr = battleMgr
        this._resMgr = resMgr
        this._lblHp = cc.find("lbl_hp", this.node).getComponent(cc.Label)
        this._lblMp = cc.find("lbl_mp", this.node).getComponent(cc.Label)
        this._progHp = cc.find("prog_hp", this.node).getComponent(cc.ProgressBar)
        this._progMp = cc.find("prog_mp", this.node).getComponent(cc.ProgressBar)
        this._skillNode = cc.find("skill", this.node)

        let headIcon = cc.find('head', this.node)
        cc.vv.HerocardManager.loadHeroCircleHead(headIcon, roleInfo.cardid)
        Global.setLabelString("lbl_lv", this.node, "Lv." + roleInfo.lv)
        let cardCfg = cc.vv.HerocardManager.getCardCfg(roleInfo.cardid)
        // Global.setLabelString("lbl_name", this.node, cardCfg.name)
        I18N.setI18nLabel(cc.find("lbl_name", this.node), cc.vv.Language["cardname_" + roleInfo.cardid])
        Global.setLabelString("skill/lbl_skill", this.node, cardCfg.skill)
        this._roleName = cc.vv.Language["cardname_" + roleInfo.cardid]//cardCfg.name
        this._camp = cardCfg.campid
        this._skill = cardCfg.skill
        this._maxHp = roleInfo.maxhp
        this._maxMp = roleInfo.maxmp
        this._pos = roleInfo.pos
        this.setHp(roleInfo.hp)
        this.setMp(roleInfo.mp)

        this._damageColor = cc.color(255, 0, 0)
        this._missColor = cc.color(255, 213, 67)
    },

    getName() {
        return this._roleName
    },

    isAlive() {
        return this._hp > 0
    },

    setHp(hp) {
        this._hp = hp
        this._lblHp.string = cc.js.formatStr('%d/%d', hp, this._maxHp)
        this._progHp.progress = Math.max(0.01, hp / this._maxHp)

        if (hp <= 0) {
            Global.showSpriteGray(cc.find('head', this.node), true)
            cc.find("defeated", this.node).active = true
        }
    },

    setMp(mp) {
        this._mp = Math.min(this._maxMp, mp)
        this._lblMp.string = cc.js.formatStr('%d/%d', mp, this._maxMp)
        this._progMp.progress = Math.max(0.01, mp / this._maxMp)
    },

    //1：左边  2：右边
    getSide() {
        if (this._pos % 2 == 1) {
            return 1
        }
        return 2
    },

    getSkillName() {
        return this._skill
    },

    playSkillName() {
        let px = 128
        let dx = 160
        if (this.getSide() == 2) {
            px = -128
            dx = -160
        }
        this._skillNode.x = px
        this._skillNode.runAction(cc.sequence(cc.fadeIn(0.1), cc.moveBy(0.4, dx, 0), cc.delayTime(0.3), cc.fadeOut(0.2)))
    },

    //显示伤害数字
    showDamage(num) {
        let hpnum = this._resMgr.get("hp_num")
        if (!hpnum) {
            cc.warn("hp_num not exist")
            return
        }
        hpnum.opacity = 255
        hpnum.scale = 0.1
        let px = 180
        if (this.getSide() == 2) {
            px = -180
        }
        hpnum.position = cc.v2(px + Math.random() * 10, 0)
        if (num > 0) {
            hpnum.getComponent(cc.Label).string = "-" + num
            hpnum.color = this._damageColor
        } else {
            hpnum.getComponent(cc.Label).string = "MISS"
            hpnum.color = this._missColor
        }

        this.node.addChild(hpnum)
        hpnum.runAction(cc.sequence(
            cc.scaleTo(0.05, 1),
            cc.moveBy(0.8, cc.v2(40, 60)),
            cc.fadeOut(0.15),
            cc.callFunc((sender) => {
                sender.getComponent("Pvp_Recycle").recycle()
            })
        ))
    },

    //显示加蓝
    showAddMp(num) {
        this.setMp(this._mp + num)

        let mpnum = this._resMgr.get("mp_num")
        if (!mpnum) {
            cc.warn("mp_num not exist")
            return
        }
        mpnum.opacity = 127
        let px = 300
        if (this.getSide() == 2) {
            px = -300
        }
        mpnum.position = cc.v2(px + Math.random() * 10, -20)
        mpnum.getComponent(cc.Label).string = "+" + num
        this.node.addChild(mpnum)
        mpnum.runAction(cc.spawn(
            cc.moveBy(0.9, cc.v2(20, 30)),
            cc.sequence(cc.fadeIn(0.15),
                cc.delayTime(0.6),
                cc.fadeOut(0.15),
                cc.callFunc((sender) => {
                    sender.getComponent("Pvp_Recycle").recycle()
                })
            )
        ))
    },

    showEffect(name, parent, pos, side) {
        let eff = this._resMgr.get(name)
        if (!eff) {
            cc.warn("effect " + name + " not exist")
            return
        }
        parent.addChild(eff)
        eff.position = pos
        eff.scaleX = (side == 1) ? 1 : -1
        let skeleton = eff.getComponent(sp.Skeleton)
        skeleton.setAnimation(0, "animation", false)
        skeleton.setCompleteListener(() => {
            skeleton.setCompleteListener(null)
            eff.getComponent("Pvp_Recycle").recycle()
        })
    },

    //进攻动画
    playAtkAnim(at) {
        if (EffectConfigs[at] && EffectConfigs[at].source) {
            this.showEffect(EffectConfigs[at].source, this.node, cc.v2(0, 0), this.getSide())
        }
        let dx = 80
        if (this.getSide() == 2) {
            dx = -80
        }
        this.node.runAction(cc.sequence(cc.delayTime(0.1), cc.moveBy(0.1, dx, 0), cc.moveBy(0.1, -dx, 0)))
        if (at == "nor") {
            Global.playCashEff("pvp/pk_attack_" + (this._camp % 10))
        } else {
            this.playSkillName()
            if (EffectConfigs[at] && EffectConfigs[at].sound) {
                Global.playCashEff("pvp/" + EffectConfigs[at].sound)
            }
        }
    },

    //受击动画
    playDefAnim(at) {
        if (EffectConfigs[at].target) {
            this.showEffect(EffectConfigs[at].target, this.node, cc.v2(0, 0), 3 - this.getSide())
        }
        let dx = -30
        if (this.getSide() == 2) {
            dx = 30
        }
        this.node.runAction(cc.sequence(cc.moveBy(0.1, cc.v2(dx, -8), 0), cc.moveBy(0.1, cc.v2(-dx, 8), 0)))
    },

    async playRoundAttack(round) {
        let attackType = round.ak.at
        //attackType = 'm5' //satk,srd,shp,m2,m3,m5
        this.playAtkAnim(attackType)
        await Global.awaitTime(this, 0.2)
        this.showAddMp(round.ak.amp)

        if (EffectConfigs[attackType] && EffectConfigs[attackType].screen) {
            let battlefield = this._battleMgr.getBattlefield()
            this.showEffect(EffectConfigs[attackType].screen, battlefield, cc.v2(0, 0), 1)
            await Global.awaitTime(this, 0.4)
        }

        for (let i = 0; i < round.rs.length; i++) {
            let rs = round.rs[i]
            let target = this._battleMgr.getRoleByPos(rs.pos)
            target.playDefAnim(attackType)
            if (attackType == 'm5') {
                await Global.awaitTime(this, 0.2)
            } else {
                await Global.awaitTime(this, 0.1)
            }
            target.showDamage(rs.dmg)
            target.setHp(rs.hp)
        }
    },

    update(dt) {

    },
});
