/**
 * 大厅弹出菜单
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _onClose: null
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.node.on('click', this.onHideMenu, this);

        //sound开关
        let btn_sound = cc.find("menu_bg/btn_sound", this.node);
        Global.btnClickEvent(btn_sound, this.onMenuSoundClicked, this);

        //music开关
        let btn_music = cc.find("menu_bg/btn_music", this.node);
        Global.btnClickEvent(btn_music, this.onMenuMusicClicked, this);



        //联系我们
        let btn_rate = cc.find("menu_bg/btn_rate", this.node)
        Global.btnClickEvent(btn_rate, this.onMenuRateClicked, this);
        // //没配置就灰太处理
        // btn_rate.getComponent(cc.Button).interactable = Global.fackbookLink?true:false
        //设置
        Global.btnClickEvent(cc.find("menu_bg/btn_setting", this.node), this.onMenuSettingClicked, this);

        //fb绑定
        let btnFb = cc.find('menu_bg/btn_fb', this.node)
        Global.btnClickEvent(btnFb, this.onClickFb, this)

        //兑换码绑定
        let btnCode = cc.find('menu_bg/btn_code', this.node)
        Global.btnClickEvent(btnCode, this.onClickCode, this)
    },

    onEnable() {
        this.checkSoundVal()
        this.isShowFbBtn()
    },

    //检查声音设置
    checkSoundVal: function () {
        let btn_sound = cc.find("menu_bg/btn_sound", this.node);
        btn_sound.getChildByName("on").active = cc.vv.AudioManager.getEffVolume() > 0;
        btn_sound.getChildByName("off").active = !btn_sound.getChildByName("on").active;

        let btn_music = cc.find("menu_bg/btn_music", this.node);
        let music_on = btn_music.getChildByName("on")
        let music_off = btn_music.getChildByName("off")
        music_on.active = cc.vv.AudioManager.getBgmVolume() > 0;
        music_off.active = !music_on.active;
    },

    onMenuRateClicked() {

        if (Global.isIOSReview()) {
            // cc.loader.loadRes("common/prefab/privacy_policy",cc.Prefab, (err, prefab) => {
            //     if (!err) {
            //         let parentNode = cc.find("Canvas")
            //         if(!cc.find('privacy_policy',parentNode)){
            //             let node = cc.instantiate(prefab);
            //             node.parent = parentNode;
            //         }

            //     }
            // })
            cc.vv.PlatformApiMgr.changeAppIcon("")
        }
        else {
            cc.vv.PlatformApiMgr.openURL(Global.fackbookLink);
        }

    },

    //音效
    onMenuSoundClicked(event, customEventData) {

        let btn_sound = cc.find("menu_bg/btn_sound", this.node);
        btn_sound.getChildByName("on").active = !btn_sound.getChildByName("on").active;
        btn_sound.getChildByName("off").active = !btn_sound.getChildByName("on").active;

        let volume = btn_sound.getChildByName("on").active ? 1 : 0;
        cc.vv.AudioManager.setEffVolume(volume);


        //打点
        let evt = StatisticsMgr.REQ_HALL_EFFECT_CLOSE
        if (volume) {
            evt = StatisticsMgr.REQ_HALL_EFFECT_OPEN
        }
        StatisticsMgr.reqReport(evt);

    },

    //背景音
    onMenuMusicClicked: function () {

        let btn_music = cc.find("menu_bg/btn_music", this.node);
        btn_music.getChildByName("on").active = !btn_music.getChildByName("on").active;
        btn_music.getChildByName("off").active = !btn_music.getChildByName("on").active;

        let volume = btn_music.getChildByName("on").active ? 1 : 0;
        cc.vv.AudioManager.setBgmVolume(volume);


        //打点
        let evt = StatisticsMgr.REQ_HALL_BGM_CLOSE
        if (volume) {
            evt = StatisticsMgr.REQ_HALL_BGM_OPEN
        }
        StatisticsMgr.reqReport(evt);
    },

    onMenuSettingClicked(event, customEventData) {
        let self = this
        if (Global.isIOSReview()) {
            cc.vv.GameManager.GameLogoout()
        }
        else {
            cc.loader.loadRes("slots_common/SlotRes/prefab/LMSlots_Setting", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let parentNode = cc.find("Canvas")
                    let old = parentNode.getChildByName('LMSlots_Setting')
                    if (!old) {
                        old = cc.instantiate(prefab)
                        old.name = 'LMSlots_Setting'
                        old.parent = parentNode
                    }

                    old.active = true;
                    old.zIndex = 1


                    self.onHideMenu();
                }
            })
        }

    },

    onHideMenu: function () {
        Global.dispatchEvent(EventId.HIDE_HALL_MENU);
    },

    isShowFbBtn: function () {
        let btn_fbbind = cc.find('menu_bg/btn_fb', this.node)
        btn_fbbind.active = !cc.vv.UserManager.isBindFb()
        //华为的不显示fb
        if (Global.appId == Global.APPID.SouthAmerica || Global.appId == Global.APPID.HuaweiDRM) {
            btn_fbbind.active = false
        }
    },

    onClickFb: function () {
        this.onHideMenu()
        //弹出fb绑定
        cc.loader.loadRes("CashHero/prefab/fb_bind/fbbind_pop", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parentNode = cc.find("Canvas")
                if (!cc.find('fbbind_pop', parentNode)) {
                    let node = cc.instantiate(prefab);
                    node.parent = parentNode;
                }

            }
        })
    },


    onClickCode: function () {
        this.onHideMenu()
        //弹出兑换码弹窗
        cc.loader.loadRes("CashHero/prefab/cdkey/cdkey", cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find("Canvas")
            }
        })
    },

    // update (dt) {},
});
