/**
 * 跑马灯-玩家大奖获得提示
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.GAME_LEVELROOM, this.OnRcvNetExitRoom, this); //退出房间
        let width = this.node.width;

        this.node_win = cc.find('node_win', this.node);

        Global.btnClickEvent(cc.find("btn_confirm", this.node_win), this.onClickPlay, this)
        Global.btnClickEvent(cc.find("btn_close", this.node_win), this.onClickClose, this)
        this._startPosX = width / 2//cc.v2(width/2, this.node_win.y);
        this._endPosX = width / 2 - this.node_win.width //cc.v2(width/2 - this.node_win.width, this.node_win.y);

        this.node_win.x = this._startPosX;

        Global.FixDesignScale_V(this.node)
    },

    onDestroy() {

        cc.vv.NetManager.unregisterMsg(MsgId.GAME_LEVELROOM, this.OnRcvNetExitRoom, false, this);
    },

    start() {

    },

    setUIData: function (data) {
        let self = this
        let otherUserInfo = data.info;
        let nick = otherUserInfo.nick;
        let uid = otherUserInfo.uid;
        let coin = otherUserInfo.coin;
        let icon = otherUserInfo.icon;
        let gameid = otherUserInfo.gameid
        this._gameId = gameid



        let headNode = cc.find('UserHead', this.node_win);
        if (!cc.isValid(headNode, true)) {
            return
        }
        let gameCfg = cc.vv.UserManager.getGameListById(gameid)
        if (gameCfg) {
            let bLock = cc.vv.UserManager.isGameLock(gameid)
            cc.find("btn_confirm", this.node_win).active = !bLock
            if (cc.vv.gameData) {
                cc.find("btn_confirm", this.node_win).getComponent(cc.Button).interactable = (gameid != cc.vv.gameData.getGameId())
            }

            let lbl_unlock = cc.find("lbl_unlock", this.node_win)
            lbl_unlock.active = bLock
            lbl_unlock.getComponent(cc.Label).string = "Game unlock at Lv." + gameCfg.level
            let slotIcon = cc.find('slot_icon', this.node_win)
            slotIcon.getComponent('CH_SlotIcon').setGameId(gameid, 'animation2')
        }



        let lbl_name = cc.find('lbl_user_name', this.node_win);
        let lbl_coin = cc.find('coin_bg/lbl_coin', this.node_win);
        headNode.getComponent('UserHead').setHead(uid, icon);
        lbl_name.getComponent(cc.Label).string = nick;
        lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(coin);

        cc.tween(this.node_win)
            .to(0.5, { x: this._endPosX }, { easing: 'backIn' })
            .delay(4)
            .to(0.8, { x: this._startPosX })
            .call(() => {
                self.node.destroy()
            })
            .start()
    },

    onClickPlay: function () {
        if (this._bNeedGoSub) return

        let bDonwload = cc.vv.UserManager.isDownloadSubGame(this._gameId)
        let bInnerGame = cc.vv.UserManager.isNoNeedDownGame(this._gameId) //是否是内置游戏
        if (cc.vv.gameData) {
            //是否已经下载
            if (bInnerGame || bDonwload) {
                this._bNeedGoSub = true
                cc.vv.gameData.setExitToHall(false);
                cc.vv.gameData.requestExit();
            }
            else {
                if (!bDonwload) {
                    //开始下载
                    cc.vv.SubGameUpdateNode.emit("check_subgame", this._gameId);
                    cc.vv.FloatTip.show('The game is downloading in the background')
                }
            }
        }
        else {
            if (cc.sys.isNative && Global.openUpdate && !bInnerGame) { // 手机平台需要检测更新
                cc.vv.SubGameUpdateNode.emit("check_subgame", this._gameId);
            } else {
                this._bNeedGoSub = true
                cc.vv.GameManager.EnterGame(this._gameId)
            }
        }

    },

    onClickClose: function () {
        this.node.destroy()
    },

    OnRcvNetExitRoom: function (msg) {
        if (msg.code == 200) {
            if (this._bNeedGoSub) {
                cc.vv.GameManager.EnterGame(this._gameId)
            }

        }
    }

    // update (dt) {},
});
