cc.Class({
    extends: cc.Component,

    properties: {
        _inter: 0,
        _leftTime: 0
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(this.node, this.onClick, this)
        Global.registerEvent(EventId.LEVELUPPARTY_CLOSE, this.onClose, this)
        Global.registerEvent(EventId.LEVELUPPARTY_UPDATETIME, this.onUpdateTime, this)
    },

    initTime(time) {
        this._leftTime = time
        this.setTime()
    },

    setTime() {
        Global.setLabelString('label', this.node, Global.formatSec(this._leftTime))
        if (this._leftTime < 1) {
            this.node.active = false
        }
    },

    onUpdateTime(data) {
        this._leftTime = data.detail.time
    },

    start() {

    },

    onClick() {
        let canvas = cc.find("Canvas");
        let prefabPath = "hall_prefab/LevelUpPartyV";

        cc.loader.loadRes(prefabPath, cc.Prefab, (err, prefab) => {
            if (!err) {
                if (!canvas.getChildByName('LevelUpParty')) {
                    let node = cc.instantiate(prefab);
                    node.name = "LevelUpParty";
                    node.parent = canvas;
                }
            }
            else {
                console.log('未找到资源')
            }
        });
    },

    onClose() {
        this.node.active = false
    },

    update(dt) {
        if (this._leftTime > 0) {
            this._inter += dt
            if (this._inter >= 1) {
                this._leftTime--
                this._inter = 0
                //修改倒计时
                this.setTime()
            }
        }
    },
});
