/**
 * 召回弹窗奖励
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _data: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_collect = cc.find('ui/btn_collect', this.node)
        Global.btnClickEvent(btn_collect, this.onClickCollect, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_NOTICE_REWARD_COLLECT, this.onRcvNetNoticeRewards, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_NOTICE_REWARD_COLLECT, this.onRcvNetNoticeRewards, false, this);
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
    },

    start() {

        let coin = cc.vv.UserManager.getNocticeRewards()
        this.setData(coin)
    },

    setData: function (data) {
        this._data = data
        //coin
        let self = this
        let onRoallFinish = function () {
            self._bFinish = true
        }
        let lblCoin = cc.find('ui/lbl_val', this.node)
        Global.doRoallNumEff(lblCoin, 0, data, 1.5, onRoallFinish, null, 0, true)
    },

    onClickCollect: function () {
        if (this._bFinish) {
            this._bFinish = null
            //领取
            cc.vv.NetManager.send({ c: MsgId.REQ_NOTICE_REWARD_COLLECT })
        }
    },

    onRcvNetNoticeRewards: function (msg) {
        if (msg.code == 200) {
            cc.vv.UserManager.SetCoin(msg.coin)
            //飞金币
            let self = this
            let flyEndCall = function () {
                cc.vv.UserManager.clearNoticeRewards()
                self.node.destroy()
            }
            let rollData = {}
            rollData.addCoin = msg.addCoin
            Global.FlyCoin(cc.find('ui/lbl_val', this.node), null, flyEndCall, rollData, true)
        }
    },

    // update (dt) {},
});
