/**
 * one time only
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _rtype: 8,//8 one time only
        _purchaseData: null,  //充值数据
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, this);
        Global.registerEvent(EventId.PAY_RESULT, this.onEventPayresult, this)
        Global.playComEff("ch_popup_l2");
    },

    start() {
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
        if (!this._purchaseData) {
            //请求协议
            var req = { 'c': MsgId.REQ_SHOP };
            req.uid = Global.playerData.uid;
            req.stype = this._rtype;
            cc.vv.NetManager.send(req);
        }
        // Global.FixDesignScale_V(this.node)
        // Global.showAlertAction(this.node,true,0.1,this.node.scale,null);
        let price_bg = cc.find("bg/price_bg", this.node)
        price_bg.runAction(cc.repeatForever(cc.sequence(cc.delayTime(2.4), cc.scaleTo(0.4, 1.1), cc.scaleTo(0.2, 1))))
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_ONETIMEONLY_POP)
    },

    onRcvShopDetail: function (msg) {
        let self = this
        if (msg.code === 200) {
            if (msg.stype === this._rtype) {
                self.initShow(msg.shoplist[0]);
                this.discountTime = msg.timeout;
                // this.showDiscountTime();
            }
        }
    },

    initShow: function (data) {
        if (data) {
            this._purchaseData = data
            // this._lbl_time = cc.find('bg/clock/lbl_time',this.node);
            //let _lbl_old_price = cc.find('bg/old_price_bg/lbl_price',this.node);
            let _lbl_coin = cc.find('bg/lbl_coin', this.node);
            // let _lbl_price = cc.find('bg/price_bg/lbl_price',this.node);
            //_lbl_discount.getComponent(cc.Label).string = cc.js.formatStr('%s%',data.discount);
            _lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(data.count);
            // _lbl_price.getComponent(cc.Label).string = "" + data.amount;
            //benifist
            let btn = cc.find("bg/btn_benifist", this.node)
            if (btn) {
                btn.getComponent('CH_Benifist_Btn').showBenifist(this._purchaseData.rewards, '首充权益')
            }
        }
    },

    //显示倒计时
    // showDiscountTime:function(){
    //     var self = this;
    //     this.callback = function() {
    //         self._lbl_time.getComponent(cc.Label).string = Global.formatSec(self.discountTime);
    //         if(self.discountTime <= 0){
    //             this.unschedule(this.callback);
    //             if(!this.isChildNode){
    //                 this.onClickClose();
    //             }
    //         }
    //         --self.discountTime;
    //     };
    //     this.schedule(this.callback,1)
    // },

    //购买
    onClickPurchase: function () {
        if (this._purchaseData) {
            //打点
            StatisticsMgr.reqReport(StatisticsMgr.REQ_ONETIMEONLY_BUY)
            let productid = this._purchaseData.id;
            cc.vv.PayMgr.reqPurchaseOrder(productid);
            // this.onClickClose()
        }
        else {
            console.log("没有充值数据");
        }
    },

    //关闭
    onClickClose: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_ONETIMEONLY_LATER)
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        Global.playComEff("ch_close");
        this.node.destroy();
    },

    onEventPayresult: function (data) {
        let res = data.detail
        if (res) {
            //支付成功,就不再弹其他充值了
            this.node.destroy()
        }
        else {
            //支付失败
            this.onClickClose()
        }
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP, this.onRcvShopDetail, false, this);
    },
});
