    _showCollectAll: function (coin) {
        let toNode = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        cc.loader.loadRes("CashHero/prefab/CommonAddCoin", cc.Prefab, (err, prefab) => {
            if (!err) {
                let objParent = cc.find('Canvas')
                if (!cc.find('CommonAddCoin', objParent)) {
                    let endCall = function () {
                        cc.vv.UserManager.AddCoin(coin, true)
                    }
                    let node = cc.instantiate(prefab)
                    node.name = 'CommonAddCoin'
                    node.parent = objParent
                    let scp = node.getComponent('CH_CommonAddCoin')
                    if (scp) {
                        scp.setCoin(coin, toNode, endCall)
                    }
                }

            }
        })
    },

