    //
    onEventRefushMailState: function (data) {
        data = data.detail
        if (this._collectAllNum) {
            this._collectAllNum--
            if (this._collectAllNum <= 0) {
                let allCollect = cc.find('spr_bg/btn_collect', this.node)
                allCollect.getComponent(cc.Button).interactable = false
            }
        }

        for (let i = 0; i < this._listData.length; i++) {
            if (data.mailId && data.mailId == this._listData[i].mailid) {
                this._listData[i].received = 1;
                if (data.btnState) {
                    this._listData[i].btnState = data.btnState;
                }
            }


        }
    },

    onEventRemoveMailItem(msg) {
        let data = msg.detail.data;

        // if(data.user && data.user.coin){
        //     cc.vv.UserManager.SetCoin(data.user.coin,true)
        // }

        let mailid = data.mailid;

        for (let i = 0; i < this._listData.length; i++) {
            if (mailid == this._listData[i].mailid) {
                this._listData[i].received = 1;

                if (this._listData[i].type === MailType.newGame_mail || this._listData[i].type === MailType.vip_mail) {   // 新游戏、vip
                    this.ShowMailList();
                }
                else {
                    this._delIdxs.push(mailid)
                    this.startDelItem(this._delIdxs[0])
                }

                break;
            }
        }
    },

    startDelItem(mailId) {
        let idx;
        for (let i = 0; i < this._listData.length; i++) {
            if (mailId == this._listData[i].mailid) {
                idx = i;
                break;
            }
        }
        let bDo = false
        let self = this
        let delCall = function () {
            if (bDo) return
            bDo = true
            self._listData.splice(parseInt(idx), 1);

            self._delIdxs.splice(0, 1)
            if (self._delIdxs.length > 0) {
                self.startDelItem(self._delIdxs[0])
            }
            if (self._listData.length < 1) {
                cc.vv.RedSys.clearRedTip(2)
                self._allCollection = 3
            }

            self.ShowMailList();
        }
        this.listview.aniDelItem(Number(idx), delCall)
    },


