cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('closeBtn', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)
        let btnGo = cc.find('goBtn', this.node)
        Global.btnClickEvent(btnGo, this.onClickGo, this)

        StatisticsMgr.reqReport(StatisticsMgr.REQ_WHEELINGAME_POP)
    },

    onClickClose() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_WHEELINGAME_CLOSE)
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        this.node.destroy()
    },

    onClickGo() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_WHEELINGAME_GO)
        cc.loader.loadRes("CashHero/prefab/fbShare/fbShareWheel", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas");
                let old = cc.find('fbShareWheel', canvas)
                if (!old) {
                    let node = cc.instantiate(prefab);
                    node.parent = canvas;
                }

            }
        });

        this.node.destroy()
    },

    onDestroy() {
        let canvas = cc.find("Canvas");
        if (!canvas || !canvas.isValid) return
        this.node_layout = canvas.getChildByName('node_layout');
        if (this.node_layout) {
            this.node_layout.active = false
        }
    },

    start() {

    },

    // update (dt) {},
});
