let RANKTAB = {
    TOTALWIN: 1,
    TOTALBET: 2,
    WINNING: 3,
    LEVELUP: 5,
    PVP: 6,
    CHARM: 7,
};

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find("btn_close", this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)
    },

    start() {

    },

    initTopData(data, idx, rankType) {
        //设置名字
        cc.find("lbl_name", this.node).getComponent(cc.Label).string = data.playername

        //设置头像
        var userHeadScript = cc.find("node_head", this.node).getComponent('UserHead');
        userHeadScript.setHead(data.uid, data.usericon);

        let num = idx == RANKTAB.LEVELUP || idx == RANKTAB.PVP ? data.coin : Global.formatNumShort(data.coin, 1)
        cc.find('des/lbl', this.node).getComponent(cc.Label).string = num

        cc.find('des/lbl/spr_icon', this.node).active = rankType == 1;   // 金币
        cc.find('des/lbl/spr_hero', this.node).active = rankType == 7;   // 魅力
        cc.find('des/lbl/spr_level', this.node).active = rankType == 5;   // 升级排行榜
        cc.find('des/lbl/spr_pvp', this.node).active = rankType == 6;   // pvp排行榜
        cc.find('des/lbl/spr_bet', this.node).active = rankType == 2;   // bet排行榜

        let spine = cc.find("spine", this.node);
        spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        spine.getComponent(sp.Skeleton).setCompleteListener(() => {
            if (cc.isValid(this.node)) {
                this.node.destroy()
            }

        })

        //
        let node_des = cc.find("des", this.node)
        node_des.active = true
        node_des.scaleY = 0
        cc.tween(node_des)
            .delay(0.2)
            .to(0.2, { scaleY: 1 })
            .start()

        // this.scheduleOnce(()=>{
        //     this.node.destroy()
        // }, 2.0)
    },

    onClickClose: function () {
        this.node.destroy()
    },

    // update (dt) {},
});
