/**
 * 押注界面
 */

const List = require('List');
cc.Class({
    extends: cc.Component,

    properties: {
        rankList: List,
        _reqBet: [],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_close = cc.find("btn_close", this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)

        let btn_rule = cc.find("btn_rule", this.node)
        Global.btnClickEvent(btn_rule, this.onClickRule, this)


        let btn_confirm = cc.find("btn_confirm", this.node)
        Global.btnClickEvent(btn_confirm, this.onClickConfirm, this)

        //
        cc.vv.NetManager.registerMsg(MsgId.REQ_FRIEND_CHATRANK_BETINFO, this.OnRcvNetBetInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_FRIEND_CHATRANK_DOBET, this.OnRcvNetDoBet, this);

        Global.registerEvent(EventId.CHAT_RANK_BET, this.onEventBetChange, this)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_FRIEND_CHATRANK_BETINFO, this.OnRcvNetBetInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_FRIEND_CHATRANK_DOBET, this.OnRcvNetDoBet, false, this);
    },

    start() {
        let req = { c: MsgId.REQ_FRIEND_CHATRANK_BETINFO }
        req.date = this._rankData.date
        cc.vv.NetManager.send(req);
    },

    init: function (data) {

        this._rankData = data
        this._nIter = 0
        this._listData = []
        for (let i = 0; i < this._rankData.rank.length; i++) {
            if (i < 10) {
                let item = this._rankData.rank[i]
                this._listData.push(item)
            }

        }
        //other固定在11的位置
        let other = {}
        other.uid = 2
        other.rank = 11
        this._listData.push(other)

        this._showMyCoin()

        this._showDate()
    },

    onClickClose: function () {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_RANKQUIZ_CLOSE)

        this.node.destroy()
    },

    onClickRule: function () {
        let spr_tips = cc.find("spr_rule_tip", this.node)
        let ac = spr_tips.getNumberOfRunningActions()
        if (ac == 0) {
            spr_tips.active = true
            spr_tips.scale = 0

            cc.tween(spr_tips)
                .to(0.3, { scale: 1 }, { easing: 'backOut' })
                .delay(5)
                .to(0.1, { scale: 0 })
                .start()
        }
        else {
            spr_tips.stopAllActions()
            spr_tips.active = false
        }

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_RANKQUIZ_RULE)
    },

    //确认下注
    onClickConfirm: function () {
        let sendData = []
        let betTotal = 0
        for (let i = 0; i < this._reqBet.length; i++) {
            let item = {}
            item.uid = this._reqBet[i].uid
            item.idx = this._reqBet[i].idx
            betTotal += this._reqBet[i].betval
            sendData.push(item)
        }
        if (betTotal > 0) {
            let req = { c: MsgId.REQ_FRIEND_CHATRANK_DOBET }
            req.bet_info = sendData
            cc.vv.NetManager.send(req)


            this._serverData.bet_info = sendData
        }
        else {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_not_bet);
            // cc.vv.FloatTip.show("You didn't make any bets.")
        }

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_RANKQUIZ_CONFIRM, this._reqBet)
    },

    _showDate: function () {
        // let res = this._rankData.date.replace(/(\d{4}).(\d{2}).(\d{2}).+/mg, '$1-$2-$3'); 
        let year = this._rankData.date.substr(0, 4)
        let mot = this._rankData.date.substr(4, 2)
        let nday = this._rankData.date.substr(6, 2)
        let nHour = this._rankData.date.substr(8, 2)
        let lblDate = cc.find('text_title/lbl_date', this.node)
        lblDate.getComponent(cc.Label).string = cc.js.formatStr("%s/%s/%s %s:00", nday, mot, year, nHour)
    },

    _showMyCoin: function () {
        let lbl_coin = cc.find('coin_bg/lbl_coin', this.node)
        let val = cc.vv.UserManager.coin
        let betTotal = 0
        for (let i = 0; i < this._reqBet.length; i++) {
            betTotal += this._reqBet[i].betval
        }
        lbl_coin.getComponent(cc.Label).string = Global.FormatNumToComma(Math.floor(val - betTotal));
    },

    //获取还可以下注的额度
    _getTempRemindCoin: function () {
        let val = cc.vv.UserManager.coin
        let betTotal = 0
        for (let i = 0; i < this._reqBet.length; i++) {
            betTotal += this._reqBet[i].betval
        }
        return val - betTotal
    },

    _showRankList: function () {
        this.rankList.numItems = this._listData.length
    },

    _showRestTime: function () {
        let lbl_time = cc.find('time_bg/lbl_time', this.node)
        lbl_time.getComponent(cc.Label).string = Global.formatSec(this._serverData.rest_time)
        //
        this._checkConfirmBtn()

    },

    _checkConfirmBtn: function () {
        let bCan = this._isCanDobet()
        let hasBet = this._serverData.bet_info.length > 0
        // let timeout = this._serverData.rest_time <= 0
        let btn_confirm = cc.find("btn_confirm", this.node)
        btn_confirm.active = bCan
        if (hasBet) {
            let spr_confirm = cc.find("spr_confirm_tip", this.node)
            spr_confirm.active = true
        }

    },

    _getBetdatabyId: function (uid) {
        let res
        for (let i = 0; i < this._serverData.bet_info.length; i++) {
            let item = this._serverData.bet_info[i]
            if (uid == item.uid) {
                res = item
                break
            }
        }
        return res
    },

    //是否可以下注，已经下注或者错过时间都不可以下注
    _isCanDobet: function () {
        let hasBet = this._serverData.bet_info.length > 0
        let timeout = this._serverData.rest_time <= 0
        return !hasBet && !timeout
    },

    onListRender: function (item, idx) {
        let data = this._listData[idx]
        if (data) {
            item.active = true
            let odds = this._serverData.odds_cfg[idx].mult
            let betdata = this._getBetdatabyId(data.uid)
            let bCan = this._isCanDobet()
            let bOpenPalace = this._serverData.is_open_palace
            item.getComponent('CH_ChatRankBetItem').init(betdata, odds, data, bCan, bOpenPalace, this)
        }
        else {
            item.active = false
        }
    },

    OnRcvNetBetInfo: function (msg) {
        if (msg.code == 200) {
            //展示基本信息
            this._serverData = msg
            this._showRankList()
            this._showRestTime()
        }
    },

    OnRcvNetDoBet: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode) {
                this._serverData.bet_info = []
                // cc.vv.FloatTip.show("Spcode:"+msg.spcode);
                cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_spcode, msg.spcode));
                return
            }
            //更新金币
            this._reqBet = []
            cc.vv.UserManager.SetCoin(msg.coin, true)
            this._showMyCoin()
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_confirm_success);
            // cc.vv.FloatTip.show("Confirm Success!");
            //这是为了立马隐藏confirm按钮，填充一个假数据
            this._serverData.bet_info = [1]
            this._checkConfirmBtn()

            Global.dispatchEvent(EventId.CHAT_RANK_BET_CONFIRM)
        }
    },

    onEventBetChange: function (data) {
        let val = data.detail
        let bIn = false
        for (let i = 0; i < this._reqBet.length; i++) {
            if (this._reqBet[i].uid == val.uid) {
                bIn = true
                //排除0
                if (val.betval == 0) {
                    this._reqBet.splice(i, 1)
                }
                else {
                    this._reqBet[i] = val
                }

                break
            }
        }
        if (!bIn && val.betval != 0) {
            this._reqBet.push(val)
        }

        //更新金币显示
        this._showMyCoin()
    },

    update(dt) {
        if (!this._serverData) {
            return
        }
        this._nIter += dt
        if (this._nIter >= 1) {
            this._nIter = 0
            this._serverData.rest_time -= 1
            if (this._serverData.rest_time < 0) {
                this._serverData.rest_time = 0

            }
            this._showRestTime()
        }
    },
});
