/**
 * 游客绑定提示
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnBind = cc.find('content/btn_bind', this.node)
        btnBind.on('click', this.onClickBindFB, this)

        let btnGo = cc.find('content/btn_go', this.node)
        btnGo.on('click', this.onClickGo, this)

        let isBindFb = cc.vv.UserManager.isBindFb()

        let fbTitle = cc.find("content/title", this.node)
        fbTitle.active = !isBindFb
        btnBind.active = !isBindFb
        btnGo.active = isBindFb
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FBBINDAD_POP)
        Global.playComEff("ch_popup_l2")

        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }

        //华为默认解锁所有游戏
        let bHW = Global.IsHuawei()
        if (bHW) {
            fbTitle.active = false
            btnBind.active = false
            btnGo.active = true
        }
    },



    onDestroy() {
        cc.vv.EventManager.emit(EventId.NEXT_POP_UI)
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },


    onClickBindFB: function () {
        cc.vv.PlatformApiMgr.fbLogin((cbData) => {
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = { c: MsgId.REQ_BIND_FACEBOOK }
                req.accesstoken = cbData.token
                req.user = cbData.uid
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req)
            }
            else {
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
            }
        });
        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FBBINDAD_CONNECT, bInGame)
        this.node.destroy()
    },

    onClickGo: function () {
        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FBBINDAD_CLOSE, bInGame)

        Global.playComEff("ch_close");
        this.node.destroy()
    },
});
