/**
 * Quest 功能开放提示
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let self = this
        let lblreward = cc.find('node_ui/lbl_coin', this.node)

        lblreward.getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.UserManager.questmaxcoin)

        let btnClose = cc.find('node_ui/btn_close', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)
        // btnClose.opacity = 0
        // cc.tween(btnClose)
        // .delay(0.8)
        // .to(0.5,{opacity:255})
        // .start()


        let btnplay = cc.find('node_ui/btn_collect', this.node)
        btnplay.active = true
        Global.btnClickEvent(btnplay, this.onClickPlay, this)
        btnplay.opacity = 255
        cc.tween(btnplay)
            .delay(0.8)
            .call(() => {
                Global.breathNode(cc.find('node_ui/spr_coin', self.node))
                cc.tween(cc.find('node_ui/spr_light', self.node))
                    .repeatForever(cc.tween()
                        .by(8, { angle: -360 }))
                    .start()

            })
            .to(0.5, { opacity: 255 })
            .start()

        Global.playCashEff("quest/loading");

        let retimer = cc.find("node_ui/btn_collect/Background/lay_out/lbl_time", this.node)

        let endCall = function () {
            self.onClickPlay()
        }
        retimer.getComponent("ReTimer").setReTimer(5, 1, endCall, "(%ss)")
    },

    start() {
        Global.FixDesignScale_V(this.node)
        cc.vv.gameData.PauseSlot()
        Global.showAlertAction(cc.find('node_ui', this.node), true, null, null, () => {
            Global.playCashEff("hall/role_questforever")
        })

        //如果开放了,就添加进去
        let bHasQuest = cc.vv.PopUIMgr.isHasLoginPopId(11)
        if (!bHasQuest) {
            cc.vv.PopUIMgr.addLoginPopList(11)
        }

        cc.vv.PlatformApiMgr.KoSDKTrackEvent('af_unlocked_questforever', JSON.stringify({ af_description: 'Questforever' }))

        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUEST_UNLOCK_UI)


    },

    onClickPlay: function () {
        if (cc.isValid(this.node)) {
            cc.vv.gameData.SetIsQuestModel({})
            cc.vv.gameData.ReqBackLobby()
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_QUEST_PLAY)
            //存一个数据 是否点击了play
            Global.saveLocal('click_questUnlock', 1)
        }

    },

    onClickClose: function () {
        Global.playComEff("ch_close");
        Global.saveLocal('click_questUnlock', 0)
        cc.vv.gameData.ResumeSlot()
        this.node.destroy()
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_QUEST_CLOSE)
    },

    // update (dt) {},
});
