
cc.Class({
    extends: cc.PageView,

    properties: {
        _move: true,
        _lastEvent: null,
    },

    // _hasNestedViewGroup (event, captureListeners) {
    //     return false;
    // },

    _onTouchMoved: function (event, captureListeners) {
        if (!this._move) return;
        if (event.eventPhase !== cc.Event.CAPTURING_PHASE) return;
        if (event == this._lastEvent) return;
        this._lastEvent = event;
        this._super(event, captureListeners);
    },

    setMove(val) {
        this._move = val;
    },

    getMove() {
        return this._move;
    }

});
