cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _stype: 0,
        _counts: [],
        _btns: [],
    },


    onLoad() {
        let btnClose = cc.find("btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_HUMMER_PRODUCT_LIST, this.onRcvNetHummerProductList, this)
        cc.vv.NetManager.registerMsg(MsgId.NOTIFY_BUY_HUMMER, this.onRcvNeBuyHummer, this)


        Global.playComEff("ch_popup_l2")
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_HUMMER_PRODUCT_LIST, this.onRcvNetHummerProductList, false, this)
        cc.vv.NetManager.unregisterMsg(MsgId.NOTIFY_BUY_HUMMER, this.onRcvNeBuyHummer, false, this)
    },

    init(stype, counts) {
        this._stype = stype
        this._counts = counts
        cc.find("silver_bg", this.node).active = (stype == 1)
        cc.find("gold_bg", this.node).active = (stype == 2)
        for (let i = 1; i <= 2; i++) {
            cc.find("items/item" + i + "/hummer/silver_hummer", this.node).active = (stype == 1)
            cc.find("items/item" + i + "/hummer/gold_hummer", this.node).active = (stype == 2)
        }
        if (counts.length <= 1) {
            cc.find("items/item2", this.node).active = false
        }

        let req = {
            c: MsgId.REQ_HUMMER_PRODUCT_LIST,
            stype: stype + 18
        };    // 19代表银锤子, 20代表金锤子
        cc.vv.NetManager.send(req);
    },

    onRcvNetHummerProductList(msg) {
        if (msg.code == 200) {
            for (let i = 0; i < this._counts.length && i < 2; i++) {
                let count = this._counts[i]
                let item = cc.find("items/item" + (i + 1), this.node)
                for (let j = 0; j < msg.shoplist.length; j++) {
                    let product = msg.shoplist[j]
                    if (product.count == count) {
                        cc.find("hummer/lbl_count", item).getComponent(cc.Label).string = "X" + product.count
                        let btnBuy = cc.find("btn_buy", item)
                        cc.find("Background/lbl_price", btnBuy).getComponent(cc.Label).string = "$ " + product.amount
                        btnBuy.off("click")
                        btnBuy.on("click", () => {
                            if (this._stype == 1) {
                                StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_SLIVER_BUY)
                            }
                            else {
                                StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_GOLD_BUY)
                            }
                            Global.playComEff("ch_btn_click")
                            cc.vv.PayMgr.reqPurchaseOrder(product.id)
                        })

                        //benifist
                        let btn = cc.find("btn_benefits", item)
                        btn.getComponent('CH_Benifist_Btn').showBenifist(product.rewards, '砸蛋权益' + '|' + this._stype)
                    }
                }
            }
        }
    },

    onRcvNeBuyHummer(msg) {
        if (msg.code == 200) {
            //buyRewardPop
            cc.loader.loadRes("CashHero/prefab/buyRewardPop/buyRewardPop", cc.Prefab, (err, prefab) => {
                let canvas = cc.find("Canvas")
                if (!err && !canvas.getChildByName("buyRewardPop")) {
                    let node = cc.instantiate(prefab)
                    node.name = "buyRewardPop"
                    node.parent = canvas
                    node.getComponent("buyRewardPop").buyHummer(msg)
                }
            })

            this.node.destroy()
        }
    },

    onClickClose() {
        if (this._stype == 1) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_SLIVER_BUY_CANCEL)
        }
        else {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_GOLD_BUY_CANCEL)
        }

        Global.playComEff("ch_close")
        this.node.destroy();
    },

});
