let daySec = 86400;
// let daySec = 300;

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find('tipBtn', this.node), this.onClickTipBtn, this)
        Global.btnClickEvent(this.node, this.onClick, this)

        this._inter = 0
        // this._time = 0
    },

    start() {

    },

    initCardBtn(time, uid) {
        this._time = time
        this._toUID = uid
        this.showLock(time)
        this.showTime(time)
        this.btnEnable(time)
    },

    btnEnable(flag) {
        this.scheduleOnce(() => {
            Global.showSpriteGray(cc.find('Background', this.node), flag)
        }, 0.01)

        this.node.getComponent(cc.Button).interactable = !flag
    },

    showTip(flag) {
        let tip = cc.find('privateDetail', this.node)
        tip.active = flag
        if (flag) {
            tip.stopAllActions()
            cc.tween(tip)
                .to(0.5, { opacity: 255 })
                .delay(2)
                .to(0.5, { opacity: 0 })
                .call(() => {
                    tip.active = false
                })
                .start()
        }
    },

    showLock(flag) {
        cc.find('lock', this.node).active = flag
    },

    showTime(flag) {
        cc.find('time', this.node).active = flag
        if (flag) {
            this.updateTime(flag)
        }
    },

    updateTime(time) {
        Global.setLabelString('label', cc.find('time', this.node), Global.formatSec(time))
        if (time < 1) {
            this.showTime(false)
            this.showLock(false)
            this.btnEnable(false)
        }
    },

    onClickTipBtn() {
        Global.playComEff("ch_btn_click")
        this.showTip(true)
    },

    onClick() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CHAT_PRIVATEGIFT)
        Global.playComEff("ch_btn_click")

        if (!cc.vv.UserManager.isBindFb()) {
            this.fbConnectPop()
            return
        }

        let self = this
        let url = 'CashHero/prefab/friend/CH_friend_cardGift'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                let callback = () => {
                    self.initTime(daySec)
                }
                node.getComponent('CH_FriendCardGift').setCallBack(callback, this._toUID)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    initTime(time) {
        this._time = time
        this.showLock(time)
        this.showTime(time)
        this.btnEnable(time)
    },

    fbConnectPop() {
        let self = this
        cc.loader.loadRes("CashHero/prefab/CH_MailTipPop", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas");
                if (canvas.isValid && !cc.find('CH_MailTipPop', canvas)) {
                    let obj = cc.instantiate(prefab)
                    obj.parent = canvas
                    obj.getComponent('CH_MailTipPop').setFrom(2)
                }
            }
        })
    },

    update(dt) {
        if (this._time) {
            this._inter += dt
            if (this._inter >= 1) {
                this._inter = 0
                this._time--
                this.updateTime(this._time)
            }
        }
    },
});
