/**
 * 红点组件
 */

cc.Class({
    extends: cc.Component,

    properties: {
        reddotType: {
            type: [cc.Integer],
            default: [],
            tooltip: "具体定义参考reddotmgr"
        },
        red_node: cc.Node,
        lbl_num: cc.Label,

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.registerEvent(EventId.REFUSH_RED_TIPS, this.onEventRefushRedTips, this)
        Global.registerEvent(EventId.REDDOT_SHOW, this.onEventShowRedTips, this)
        Global.registerEvent(EventId.REDDOT_HIDE, this.onEventHideRedTips, this)
    },

    start() {
        this._refushAllReddot()
    },

    onEnable() {

    },

    _refushAllReddot: function () {
        let res = this._getShowRedNum()
        this._setNodeShow(res)
        this._setRedNum(res)
    },

    _setReddot: function (redType, bShow) {
        let res = false

        for (let i = 0; i < this.reddotType.length; i++) {
            if (redType == this.reddotType[i]) {
                res = true
                break
            }
        }

        if (res) {
            if (bShow) {

                if (this.lbl_num) {
                    let redNum = this._getShowRedNum()
                    if (redNum) {
                        this._setNodeShow(true)
                        this._setRedNum(redNum)
                    }

                }
            }
            else {
                this._refushAllReddot()
            }

        }
    },

    _setNodeShow: function (bShow) {
        if (cc.isValid(this.red_node)) {
            this.red_node.active = bShow
        }
    },

    _setRedNum: function (val) {
        if (this.lbl_num) {
            this.lbl_num.getComponent(cc.Label).string = val
        }
    },

    //获取显示的红点数量
    _getShowRedNum: function () {
        let redNum = 0
        for (let i = 0; i < this.reddotType.length; i++) {
            let item = cc.vv.RedSys.getRedTip(this.reddotType[i])
            if (item) {
                if (cc.js.isNumber(item)) {
                    redNum += item
                }
                else {
                    redNum += 1
                }

            }
        }
        return redNum
    },



    onEventRefushRedTips: function () {
        this._refushAllReddot()
    },

    onEventShowRedTips: function (data) {
        let redType = data.detail
        this._setReddot(redType, true)
    },

    onEventHideRedTips: function (data) {
        let redType = data.detail
        this._setReddot(redType, false)
    },
    // update (dt) {},
});
