/**
 * 礼物列表-赠送
 */
const List = require('CH_List');
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        giftList: List,
        _dataList: [],
        _curPage: 1,
        // _hasNextPage:false,
        // _bSendPanel:false,
        _tab: 1,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('btn_close', this.node);
        Global.btnClickEvent(btnClose, this.onClickClose, this);

        let btnLeft = cc.find('tabs/btn_recv', this.node);
        Global.btnClickEvent(btnLeft, this.onClickRecv, this);
        let btnRight = cc.find('tabs/btn_send', this.node);
        Global.btnClickEvent(btnRight, this.onClickSend, this);

        let btn_send = cc.find("node_datas/btn_send", this.node)
        Global.btnClickEvent(btn_send, this.onClickFriendSend, this);
        let btn_quest = cc.find("node_datas/btn_quest", this.node)
        Global.btnClickEvent(btn_quest, this.onClickQuestGift, this);

        cc.vv.NetManager.registerMsg(MsgId.REQ_GIFT_SENDLIST, this.onRcvSendInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GIFT_RECEIVELIST, this.onRcvReceiveInfo, this);

        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GIFT_SENDLIST, this.onRcvSendInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GIFT_RECEIVELIST, this.onRcvReceiveInfo, false, this);

        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, false, this);
    },

    start() {
        this.showInfo(false)
        this.showSelectTab(this._tab)
    },

    showSelectTab: function (nIdx) {
        let btn_recv = cc.find("tabs/btn_recv", this.node)
        btn_recv.getComponent(cc.Button).interactable = (nIdx != 1)
        cc.find("Label", btn_recv).getComponent(cc.LabelOutline).color = nIdx == 1 ? cc.color("#5F0126") : cc.color("#000000");
        cc.find("light", btn_recv).active = nIdx == 1
        cc.find("gray", btn_recv).active = !(nIdx == 1)
        let btn_send = cc.find("tabs/btn_send", this.node)
        btn_send.getComponent(cc.Button).interactable = (nIdx != 2)
        cc.find("Label", btn_send).getComponent(cc.LabelOutline).color = nIdx == 2 ? cc.color("#5F0126") : cc.color("#000000");
        cc.find("light", btn_send).active = nIdx == 2
        cc.find("gray", btn_send).active = !(nIdx == 2)
    },

    showInfo: function (bSend) {
        this._bSendPanel = bSend;
        if (bSend) {
            this.sendGiftInfo(1);
        } else {
            this.receiveGiftInfo(1);
        }
    },

    sendGiftInfo: function (page) {
        let req = {
            c: MsgId.REQ_GIFT_SENDLIST,
            page: page,
            size: 50,  //客户端控制请求数量
        };
        cc.vv.NetManager.sendAndCache(req)
    },

    receiveGiftInfo: function (page) {
        let req = {
            c: MsgId.REQ_GIFT_RECEIVELIST,
            page: page,
            size: 50,  //客户端控制请求数量
        };
        cc.vv.NetManager.sendAndCache(req)
    },

    onRcvSendInfo: function (msg) {
        if (msg.code == 200) {
            this._dataList = msg.data;
            // this._hasNextPage = msg.hasNextPage;
            this.showGiftList(this._dataList);
            // this.showPage();
        }
    },

    onRcvReceiveInfo: function (msg) {
        if (msg.code == 200) {
            this._dataList = msg.data;
            let _unRead = msg.charmCnt
            for (let i = 0; i < _unRead; i++) {
                this._dataList[i].unread = 1
            }
            // this._hasNextPage = msg.hasNextPage;
            this.showGiftList(this._dataList);
            // this.showPage();
        }
    },

    showGiftList(data) {
        let nNum = data.length
        this.giftList.numItems = nNum
        if (nNum == 0) {
            this.showNoData(true)
        }
        else {
            this.showNoData(false)
        }
    },

    // showPage(){
    //     cc.find("node_page/lbl_page",this.node).getComponent(cc.Label).string = this._curPage;
    //     if(this._hasNextPage){

    //     }
    // },

    showNoData: function (bShow) {
        let node_no = cc.find("node_datas", this.node)
        node_no.active = bShow

        let lblstr = "NO MORE GIFTS!"
        if (this._tab == 2) {
            lblstr = "NO MORE RECORDS!"
        }
        Global.setLabelString("lbl_tips", node_no, lblstr)
        let btn_send = cc.find("btn_send", node_no)
        let btn_quest = cc.find("btn_quest", node_no)
        btn_send.active = bShow && (this._tab == 2)
        btn_quest.active = bShow && (this._tab == 1)
    },

    onRenderListItem: function (item, idx) {
        let data = this._dataList[idx]
        if (data) {
            item.active = true
            item.getComponent('gift_detail_item').init(data, this._tab == 2)
        }
        else {
            item.active = false
        }
    },

    onClickClose: function () {
        this.node.destroy()
    },

    onClickRecv() {
        Global.playComEff("ch_btn_click");
        if (this._tab != 1) {
            this._tab = 1
            this.showInfo(false)
            this.showSelectTab(this._tab)
        }
    },

    onClickSend() {
        Global.playComEff("ch_btn_click");
        if (this._tab != 2) {
            this._tab = 2
            this.showInfo(true)
            this.showSelectTab(this._tab)
        }
    },

    onRcvPersonInfo: function (msg) {
        let self = this
        if (msg.code == 200) {
            if (msg.act == 1 || msg.act == 2) {
                //detail
                cc.loader.loadRes("CashHero/prefab/friend/CH_friend_detail", cc.Prefab, (err, prefab) => {
                    if (!err) {
                        let parentNode = cc.find("Canvas")
                        let oldNode = parentNode.getChildByName('CH_friend_detail')
                        if (!oldNode) {
                            let node = cc.instantiate(prefab);
                            node.parent = parentNode;
                            node.getComponent('CH_FriendsDetail').init(msg.playerInfo.uid, msg, self)

                        }
                        else {
                            oldNode.active = true
                            oldNode.getComponent('CH_FriendsDetail').init(msg.playerInfo.uid, msg, self)
                        }
                    }
                });
            }
        }

    },

    onClickFriendSend: function () {
        Global.playComEff("ch_btn_click");
        //调到好友界面
        this.node.destroy()
        //聊天界面
        Global.dispatchEvent(EventId.GO_HALL_TAB, 4)
        //好友界面
        Global.dispatchEvent(EventId.OPEN_HALL_FRIENDS)
    },

    onClickQuestGift: function () {
        Global.playComEff("ch_btn_click");
        //调到世界聊天
        this.node.destroy()
        //聊天界面
        Global.dispatchEvent(EventId.GO_HALL_TAB, 4)
        //好友界面
        Global.dispatchEvent(EventId.OPEN_HALL_FRIENDS, "chat")
    },

    // update (dt) {},
});
