/**
 * 礼物播放
 */

let giftSpine = {
    "gift_car": { name: "animation1" },
    "gift_evil": { name: "ermodaiji", name2: "ermobao" },
    "gift_ice": { name: "animation1", },
    "gift_kiss": { name: "animation" },
    "gift_money": { name: "animation1" },
    "gift_poker": { name: "animation1" },
    "gift_ring": { name: "animation" },
    "gift_tower": { name: "animation" },
};
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _giftList: [],
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('btn_close', this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)
    },

    start() {

    },

    setInfo(receiverInfo, senderInfo, giftInfo) {
        this._giftList.push({ receiverInfo: receiverInfo, senderInfo: senderInfo, giftInfo: giftInfo });
        this.playGiftAnim();
    },
    addInfo(receiverInfo, senderInfo, giftInfo) {
        this._giftList.push({ receiverInfo: receiverInfo, senderInfo: senderInfo, giftInfo: giftInfo });
    },

    playGiftAnim() {
        let receiverInfo = this._giftList[0].receiverInfo;
        let senderInfo = this._giftList[0].senderInfo;
        let giftInfo = this._giftList[0].giftInfo;
        this._giftList.splice(0, 1);

        let receiver = cc.find("receiver", this.node);
        let sender = cc.find("sender", this.node);
        receiver.getComponent('UserHead').setHead(receiverInfo.uid, receiverInfo.usericon);
        sender.getComponent('UserHead').setHead(senderInfo.uid, senderInfo.usericon);
        Global.setLabelString("name", sender, senderInfo.playername)
        Global.setLabelString("name", receiver, receiverInfo.playername)
        let recv_me_flag = cc.find("spr_Me", receiver)
        recv_me_flag.active = cc.vv.UserManager.isMySelf(receiverInfo.uid)
        let send_me_flag = cc.find("spr_Me", sender)
        send_me_flag.active = cc.vv.UserManager.isMySelf(senderInfo.uid)

        // receiver.position =

        let ePos1 = cc.v2(-cc.winSize.width / 2 + 200, receiver.position.y);
        let ePos2 = cc.v2(cc.winSize.width / 2 - 200, sender.position.y);
        let sPos1 = cc.v2(-cc.winSize.width, receiver.y);
        let sPos2 = cc.v2(cc.winSize.width, sender.y);

        receiver.position = sPos1;
        sender.position = sPos2;


        cc.tween(receiver).to(0.5, { position: ePos1 }).start();
        cc.tween(sender)
            .delay(0.3)
            .to(0.5, { position: ePos2 })
            .delay(0.3)
            .call(() => {
                let gift_img = cc.find("gift_img", this.node);
                gift_img.position = sender.position;
                gift_img.active = true
                cc.tween(gift_img)
                    .to(0.5, { position: receiver.position })
                    .call(() => {
                        gift_img.active = false;

                        //飘魅力值
                        let node_charm = cc.find("node_charm_add", receiver)
                        Global.setLabelString('lbl_add', node_charm, "+" + giftInfo.charm)
                        node_charm.active = true
                        node_charm.opacity = 255
                        cc.tween(node_charm)
                            .to(0.5, { y: node_charm.y + 60 })
                            .to(0.2, { opacity: 0 })
                            .call(() => {
                                node_charm.active = false
                            })
                            .start()


                    })
                    .start()


                cc.tween(this.node)
                    .delay(0.3)
                    .call(() => {
                        let gift_spine = cc.find("gift_spine", this.node);
                        let url = "CashHero/gift/spine/" + giftInfo.img + "/spine"
                        cc.loader.loadRes(url, sp.SkeletonData, (err, data) => {
                            if (!err) {
                                if (!cc.isValid(gift_spine)) return
                                gift_spine.active = true;
                                let giftSp = gift_spine.getComponent(sp.Skeleton);
                                if (giftSp) {
                                    cc.vv.AudioManager.pauseAll()
                                    Global.playCashEff("gift/" + giftInfo.img);
                                    giftSp.skeletonData = data
                                    giftSp.setAnimation(0, giftSpine[giftInfo.img].name, false);
                                    if (giftSpine[giftInfo.img].name2) {
                                        giftSp.addAnimation(0, giftSpine[giftInfo.img].name2, false);
                                    }
                                    giftSp.setCompleteListener(() => {
                                        gift_spine.active = false;
                                        this.onClickClose();
                                        cc.vv.AudioManager.resumeAll()
                                    })
                                }
                            }
                        })
                    })
                    .start()




            }
            )
            .start();

    },

    onClickClose: function () {
        if (this._giftList.length > 0) {
            this.playGiftAnim();
        }
        else {
            this.node.destroy()
        }
    },

    // update (dt) {},
});
