cc.Class({
    extends: cc.Component,

    properties: {
        _winCoin: 0,
        _callback: null,
        _rewards: null,
    },

    onDestroy() {

    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    //金币奖励
    showWinCoin(coin, callback) {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_REWARD_POP, cc.vv.UserManager.getBingoFrom())

        this._winCoin = coin
        this._callback = callback
        this.showSmallPrize("item_coin", Global.formatNumShort(coin, 0))
    },

    //次数奖励
    showWinCount(count, callback) {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_REWARD_POP, cc.vv.UserManager.getBingoFrom())

        this._winCoin = 0
        this._callback = callback
        this.showSmallPrize("item_count", "x" + count)
    },

    showSmallPrize(item, count) {
        Global.playCashEff("bingo/small_prize")
        cc.find("big_prize", this.node).active = false
        let prize = cc.find("small_prize", this.node)
        prize.active = true
        Global.showAlertAction(prize, true, 0.1, 1)

        cc.find("item_coin", prize).active = (item == "item_coin")
        cc.find("item_count", prize).active = (item == "item_count")
        Global.setLabelString("lbl_count", prize, count)

        let btnCollect = cc.find("btn_collect", prize)
        btnCollect.on("click", this.onClickCollectSmallPrize, this)
        btnCollect.opacity = 0
        btnCollect.runAction(cc.sequence(cc.delayTime(0.2), cc.fadeIn(0.2)))

        cc.find("guang_02", prize).runAction(cc.repeatForever(cc.rotateBy(2, 360)))
    },

    onClickCollectSmallPrize(event) {
        event.node.getComponent(cc.Button).interactable = false
        Global.playComEff("ch_collect")
        //加金币
        if (this._winCoin > 0) {
            if (cc.vv.gameData) {
                cc.vv.gameData.AddCoin(this._winCoin, true)
            } else {
                cc.vv.UserManager.AddCoin(this._winCoin, true)
            }
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_REWARD_COIN, cc.vv.UserManager.getBingoFrom())
        } else {
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_REWARD_COUNT, cc.vv.UserManager.getBingoFrom())
        }
        //关闭弹窗
        let prize = cc.find("small_prize", this.node)
        Global.showAlertAction(prize, false, 1, 0.1, () => {
            this.node.destroy()
            if (this._callback) {
                this._callback()
            }
        })
        cc.vv.AudioManager.stopEffectByName("small_prize")
    },

    showLevelPrize(level, rewards, callback) {
        this._rewards = rewards
        this._callback = callback
        cc.find("big_prize/level", this.node).active = Global.language == Global.LANGUAGE.EN
        cc.find("big_prize/round", this.node).active = false
        cc.find("big_prize/arRound", this.node).active = false
        let arLanNode = cc.find("big_prize/arLevel", this.node)
        arLanNode.active = Global.language == Global.LANGUAGE.AR
        if (Global.language == Global.LANGUAGE.AR) {
            I18N.setI18nLabel(arLanNode, cc.vv.Language.bingo_rewards_level, level)
        } else {
            Global.setLabelString("big_prize/level/lbl_level", this.node, level)
        }
        this.showBigPrize(rewards)
    },

    showRoundPrize(round, rewards, callback) {
        this._rewards = rewards
        this._callback = callback
        cc.find("big_prize/level", this.node).active = false
        cc.find("big_prize/round", this.node).active = Global.language == Global.LANGUAGE.EN
        cc.find("big_prize/arLevel", this.node).active = false
        let arRoundNode = cc.find("big_prize/arRound", this.node)
        arRoundNode.active = Global.language == Global.LANGUAGE.AR
        if (Global.language == Global.LANGUAGE.EN) {
            Global.setLabelString("big_prize/round/lbl_round", this.node, round)
        } else {
            I18N.setI18nLabel(arRoundNode, cc.vv.Language.bingo_rewards_round, round)
        }
        this.showBigPrize(rewards)
    },

    showItem(item, count) {
        Global.setLabelString("lbl_count", item, count)
        item.scale = 0
        item.active = true
        item.runAction(cc.scaleTo(0.45, 1).easing(cc.easeBackOut()))
    },

    async showDropCard(cardid, count) {
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showDropUI(cardid, count, sucess, false)
        });
    },

    popRewards(rd) {
        let rdArr = []
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.COIN) {
                rdArr.push(rd[i])
            } else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD) {
                rdArr.push(rd[i])
            } else if (rd[i].type == Global.PROP_ID.DIAMOND) {
                cc.vv.UserManager.AddDiamond(rd[i].count, true)
            } else {
                //活跃度不是物品 不更新
                if (rd[i].type == Global.PROP_ID.ACTIVITY) {
                    continue
                }
                Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: rd[i].type, num: rd[i].count })
            }
        }

        let url = 'CashHero/prefab/pop_reward'
        let self = this
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                let endCall = function () {
                    if (self._callback) {
                        self._callback()
                    }
                    self.node.destroy()
                }
                node.getComponent('CH_popreward').showRewards(rdArr, endCall)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    async showBigPrize(rewards) {
        Global.playCashEff("bingo/big_prize")
        cc.find("small_prize", this.node).active = false
        let prize = cc.find("big_prize", this.node)
        prize.active = true
        Global.showAlertAction(prize, true, 0.1, 1)

        let btnCollect = cc.find("big_prize/btn_collect", this.node)
        btnCollect.on("click", this.onClickCollectBigPrize, this)
        btnCollect.opacity = 0

        //依次显示物品
        let winCoin = 0
        let cardCount = 0
        let vipCount = 0
        let expCount = 0
        await this.awaitTime(0.3)
        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            if (reward.type == Global.PROP_ID.COIN) {
                winCoin += reward.count
            } else if (reward.type == Global.PROP_ID.VIP_POINT) {
                vipCount += reward.count
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                cardCount += reward.count
            } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                expCount += reward.count / 3600
            }
        }
        this._winCoin = winCoin
        if (winCoin > 0) {
            this.showItem(cc.find("reward/item_coin", prize), Global.formatNumShort(winCoin, 0))
            await this.awaitTime(0.5)
        }
        if (vipCount > 0) {
            this.showItem(cc.find("reward/item_vip", prize), "" + vipCount)
            await this.awaitTime(0.5)
        }
        if (expCount > 0) {
            this.showItem(cc.find("reward/item_exp", prize), "x" + expCount)
            await this.awaitTime(0.5)
        }
        if (cardCount > 0) {
            this.showItem(cc.find("reward/item_package", prize), "x" + cardCount)
            await this.awaitTime(0.5)
        }
        //显示收集按钮
        btnCollect.runAction(cc.sequence(cc.delayTime(0.2), cc.fadeIn(0.2)))
    },

    onClickCollectBigPrize(event) {
        event.node.getComponent(cc.Button).interactable = false
        Global.playComEff("ch_collect")
        this.popRewards(this._rewards)
        cc.vv.AudioManager.stopEffectByName("big_prize")
    },

});
