/**
 * quest 超时结束
 */
cc.Class({
    extends: require("CH_popwin_base"),

    properties: {
        _inter: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._super()
        let btn = cc.find('btn_complete', this.node)
        Global.btnClickEvent(btn, this.OnClickBackHall, this)
    },

    start() {
        this._super()
    },

    OnClickBackHall: function () {
        if (cc.vv.gameData) {
            cc.vv.gameData.SetIsQuestModel(null)
            cc.vv.gameData.ReqBackLobby()
        }
        else {
            let goScene = Global.SCENE_NAME.HALL
            cc.vv.SceneMgr.enterScene(goScene, null, Global.APP_ORIENTATION)
        }
    },


});
