/**
 * 一键收集所有金币
 */

cc.Class({
    extends: cc.Component,

    properties: {
        //cc
        _coinNode: null,
        _btnConfirm: null,
        _bCanClose: true,

        //属性
        _coin: null,
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.FRIEND_COLLECTALL_DOUBLE, this.onRcvFBInfo, this);

        this._coinNode = cc.find('spr_bg/coin_bg/lbl_coin', this.node)
        this._btnConfirm = cc.find('spr_bg/btn_confirm', this.node)
        let btn_share = cc.find('spr_bg/btn_share', this.node)
        Global.btnClickEvent(btn_share, this.onClickShareDouble, this)

        Global.btnClickEvent(this._btnConfirm, function () {
            if (!this._bCanClose) return
            if (!this._btnConfirm.getComponent(cc.Button).enabled) return
            this._btnConfirm.getComponent(cc.Button).enabled = false;
            cc.vv.UserManager.AddCoin(this._coin, false)

            this.uiFlyCoin(this._coin)
            // let rollData = {}
            // rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
            // rollData.addCoin = this._coin
            // let coinNode = this._coinNode
            // let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
            // let endCall = function () {
            //     this._btnConfirm.getComponent(cc.Button).enabled = true;
            //     this.node.destroy();

            // }.bind(this)
            // cc.vv.UserManager.AddCoin(this._coin, false)
            // Global.FlyCoin(coinNode, endNode, endCall, rollData,true)
        }.bind(this))
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.FRIEND_COLLECTALL_DOUBLE, this.onRcvFBInfo, false, this);
    },

    start() {
        if (this._coinNode) {
            this._coinNode.getComponent(cc.Label).string = Global.FormatNumToComma(this._coin);
        }
        //弹窗动作
        Global.showAlertAction(cc.find('spr_bg', this.node), true)
    },

    changeCoin(coinNum) {
        this._coin = coinNum;
        if (this._coinNode) {
            this._coinNode.getComponent(cc.Label).string = Global.FormatNumToComma(coinNum);
        }

    },

    onClickShareDouble: function () {
        Global.playComEff("ch_btn_click");
        this._bCanClose = false
        //直接分享
        if (Global.isNative()) {
            let urlLink = 'https://global.rummyslot.com/fb/?code=' + Global.playerData.uid;
            let imgUrl = 'http://global.rummyslot.com/share.png';
            let content = 'Let\'s play together!\nJoin the most famous card games and slots to WIN BIG!';

            cc.vv.FBMgr.fbShareWeb(urlLink, imgUrl, content, this.onShareBack.bind(this));
        }
        else {
            this.onShareBack({ result: "1" })
        }
    },

    onShareBack: function (data) {
        if (data.result == "1") {
            var req = { 'c': MsgId.FRIEND_COLLECTALL_DOUBLE };

            cc.vv.NetManager.send(req);
        }
        else {
            //分享不成功
            this._bCanClose = true
        }
    },


    onRcvFBInfo: function (msg) {

        if (msg.code == 200) {
            if (msg.coin) {
                let self = this
                cc.find('spr_bg/spr_double', this.node).active = false
                let lblCoin = cc.find('spr_bg/coin_bg/lbl_coin', this.node)
                let nBegin = msg.coin
                let nEnd = 2 * nBegin
                let finishCall = function () {

                    //飞金币
                    self.uiFlyCoin(2 * nBegin)
                    cc.vv.UserManager.AddCoin(2 * nBegin, false)

                }
                Global.doRoallNumEff(lblCoin, nBegin, nEnd, 1.5, finishCall, null, 0, true)

                // let delayCall = function(){
                //     self._bCanClose = true
                //     self.node.destroy()


                // }
                // this.scheduleOnce(delayCall,2.5)
            }

        }
        else {
            this._bCanClose = true
        }
    },

    uiFlyCoin: function (coin) {
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
        rollData.addCoin = coin
        let coinNode = this._coinNode
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        let endCall = function () {

            this.node.destroy();

        }.bind(this)

        Global.FlyCoin(coinNode, endNode, endCall, rollData, true)
    },
});
