/**
 * 版本号显示
 */

cc.Class({
    extends: cc.Component,

    properties: {
        // _click_acount:0
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        Global.btnClickEvent(cc.find("btn_dev", this.node), this.onOpenDevMode, this);
        // let btn_ans = cc.find("btn_anousment",this.node)
        // Global.btnClickEvent(btn_ans, this.onOpenAnnousment, this);
    },

    start() {
        this.showResVision()
    },

    showResVision: function () {
        let ver = cc.find("ver", this.node);
        ver.active = !Global.isIOSReview()
        ver.getComponent(cc.Label).string = "V" + Global.resVersion;
    },

    //
    onOpenDevMode: function () {
        // this._click_acount++
        // if(this._click_acount>8){
        //     //进入开发者模式
        //     Global.localVersion = true
        // }
        this._nClickCount = this._nClickCount || 0
        this._nClickCount++
        // console.log(">>>> 点击: " + this._nClickCount)
        if (this._nClickCount >= 8) {
            let val = cc.sys.localStorage.getItem('screen_log');
            if (!val) {
                val = 1
                cc.sys.localStorage.setItem('screen_log', val);
                //进入开发者模式
                Global.localVersion = true
            }
            else {
                val = 0
                cc.sys.localStorage.removeItem('screen_log');
                //进入开发者模式
                Global.localVersion = false
            }
        }
    },

    //打开公告
    onOpenAnnousment: function () {
        // this.reqStateInfo()
        this._servData = cc.vv.AppData.getLaunchAnnousment
        this.showNoctice(this._servData)
    },

    reqStateInfo: function () {
        // this._servData = {"state":0,"areacode":"00","msg":"","la":"hao","code":200}
        if (!this._servData) {
            let tData = {}
            tData.appVer = Global.appVersion
            if (Global.isIOS()) {
                Global.appVersion = cc.vv.PlatformApiMgr.getAppVersion()
                tData.appVer = Global.appVersion
            }
            tData.os = cc.sys.os
            cc.vv.NetManager.requestHttp('', tData, this.recvMailtenance.bind(this), Global.haoUrl, "GET", false);
        }
        else {
            //
            this.showNoctice(this._servData)
        }
    },

    recvMailtenance: function (state, data) {
        if (state && data.code === 200) {
            //
            this._servData = data
            this.showNoctice(this._servData)
        }
    },

    showNoctice: function (data) {
        if (data) {
            let content = data.upmsg
            let url = "CashHero/prefab/update_notice"
            let parNode = cc.director.getScene();
            let old = cc.find('update_notice', parNode)
            if (old) {
                return
            }
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err && cc.isValid(parNode)) {
                    let node = cc.instantiate(prefab);
                    node.parent = parNode
                    node.getComponent('update_notice').showNotice(content)
                }
            })
        }
    },

    showNocticeBtn: function (bShow) {
        // let btn_ans = cc.find("btn_anousment",this.node)
        // if(btn_ans){
        //     btn_ans.active = bShow
        // }
    }

    // update (dt) {},
});
