
cc.Class({
    extends: cc.Component,

    properties: {
    },

    onLoad() {
        this._pools = new Map()
        this._prefabs = new Map()
        this._refer = 0

        let resources = ["hp_num", "mp_num", "eff_attack_1", "eff_attack_2", "eff_punch_1", "eff_punch_2",
            "eff_behead_1", "eff_behead_2", "eff_deadlyblow_1", "eff_deadlyblow_2", "eff_series_1", "eff_series_2",
            "eff_bomb_1", "eff_bomb_2", "eff_bomb_3"]
        for (let i = 0; i < resources.length; i++) {
            let res = resources[i]
            this.loadPredab(res, "CashHero/prefab/pvp/preload/" + res)
        }
    },

    onDestroy() {
        for (let key in this._pools) {
            this._pools[key].clear()
        }
    },

    loadPredab(key, url) {
        this._refer += 1
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                this._prefabs.set(key, prefab)
            }
            this._refer -= 1
        })
    },

    isAllLoaded() {
        return this._refer <= 0
    },

    get(key) {
        let prefab = this._prefabs.get(key)
        if (!prefab) {
            console.log(key + " prefab is not exist")
            return null
        }
        let pool = this._pools.get(key)
        if (!pool) {
            pool = new cc.NodePool()
            this._pools.set(key, pool)
        }

        let node = null
        if (pool.size() > 0) {
            node = pool.get()
            //console.log("ues pool node "+ key)
        } else {
            node = cc.instantiate(prefab)
            node.addComponent("Pvp_Recycle").setPool(pool)
        }

        return node
    },

});
