
// 1-锁 2-钱够可点击 3-钱不够不可点击 4-打开钱 5-打开bonus 6-打开免费
let itemType = {
    lock     : 1,
    canClick : 2,
    notClick  : 3,
    coin     : 4,
    bonus    : 5,
    free      : 6,
};

cc.Class({
    extends: cc.Component,

    properties: {
        // _rtype:1,

        _itemList:[],

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this._node_box = cc.find("safe_node/node_box", this.node);
        this._node_box.active = false;
        this._btn_close = cc.find("layout/btn_close", this._node_box);
        Global.btnClickEvent(this._btn_close, this.onClickCloseBtn, this);

        this._node_items = cc.find("layout/boxKuang/node_items", this._node_box);
        for (let i = 1; i <= 9; i++){
            let item = cc.find("item"+i, this._node_items);
            item.off("click");
            Global.btnClickEvent(item, this.onClickItem, this);

            this._itemList[i] = {node:item,type:1,data:null};
        }

        this._box_tip = cc.find("layout/box_tip", this._node_box);
        this._box_tip.active = false;
        this._spr_tip = cc.find("layout/spr_tip", this._node_box);
        this._spr_tip.active = false;
        let btn_tip = cc.find("layout/node_flag/btn_tip", this._node_box);
        Global.btnClickEvent(btn_tip, this.clickHelpBtn, this);
        let btn_left = cc.find("layout/btn_left", this._node_box);
        Global.btnClickEvent(btn_left, this.clickLeftBtn, this);
        let btn_right = cc.find("layout/btn_right", this._node_box);
        Global.btnClickEvent(btn_right, this.clickRightBtn, this);

    },

    // 打开商店页面
    openStorePage(){
        return new Promise(async(success, failed)=> {
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.playEffect("mapin");

            this._node_box.active = true;
            this._node_box.opacity = 0;
            let layout = cc.find("layout", this._node_box);
            layout.setScale(0);
            cc.tween(this._node_box).to(0.5, {opacity: 255}).start();
            cc.tween(layout).to(0.5, {scale: 1}).start();

            this._flagStore = cc.vv.gameData.getFlagStore();
            // this._pageDetails = this._flagStore.pageDetails;
            this._curPage = this._flagStore.unlockPage;
            // this._unlockPage = this._flagStore.unlockPage;
            // this._unlockItems = this._flagStore.unlockItems;


            // this.showTitleSpr();
            this.showCurMoney(this._flagStore.flagCnt);
            this.showAllItems();
            this.showPageFooter();
            this.showPageWinDetail();

            // this.updateCurMoney();

            await cc.vv.gameData.awaitTime(0.5);
            this._canClickItem = true;

            success();
        })
    },

    // 关闭商店页面
    async closeStorePage(){
        return new Promise(async(success, failed)=>{
            Global.SlotsSoundMgr.playEffect("mapout");
            let layout = cc.find("layout", this._node_box);
            cc.tween(this._node_box).to(0.5,{opacity:0}).start();
            cc.tween(layout).to(0.5,{scale:0}).start();

            await cc.vv.gameData.awaitTime(0.5);
            this._node_box.active = false;

            success();
        })
    },

    showCurMoney(cnt){
        cc.find("layout/node_flag/desctext", this._node_box).getComponent(cc.Label).string = Global.FormatNumToComma(cnt);
    },

    // 所有箱子
    showAllItems(){
        let pageData = this._flagStore.unlockItems[this._curPage - 1];
        let pagePrice = this._flagStore.pageDetails[this._curPage - 1].price;

        for(let i = 1; i <= 9; i++){
            let item = this._itemList[i].node;

            let type = this._itemList[i].type;
            let data;
            if(this._curPage <= this._flagStore.unlockPage){  // 页面解锁
                let itemData = this.getItemData(i, pageData);
                if(itemData){   // 已经打开
                    if(itemData.coin > 0){
                        type = itemType.coin;
                        data = itemData.coin;
                        this.setItemState(item, itemType.coin, itemData.coin);
                    } else if(itemData.bonusGame){
                        type = itemType.bonus;
                        this.setItemState(item, itemType.bonus);
                    } else if(itemData.freeInfo){
                        type = itemType.free;
                        this.setItemState(item, itemType.free);
                    }
                }
                else {
                    if(pagePrice <= this._flagStore.flagCnt){ // 钱足够
                        type = itemType.canClick;
                        data = pagePrice;
                        this.setItemState(item, itemType.canClick, pagePrice);
                    } else {    // 钱不够
                        type = itemType.notClick;
                        data = pagePrice;
                        this.setItemState(item, itemType.notClick, pagePrice);
                    }
                }
            }
            else {  // 箱子锁住
                type = itemType.lock;
                data = pagePrice;
                this.setItemState(item, itemType.lock, pagePrice);
            }
            this._itemList[i].type = type;
            this._itemList[i].data = data;
        }
    },

    // 获取单个房子的数据
    getItemData(idx, pageData){
        for (let i = 0; i < pageData.length; i++){
            if(idx == pageData[i].idx){
                return pageData[i]
            }
        }
        return null
    },

    // 设置单个房子的状态  type: 1-锁 2-窝可点击 3-窝不可点击 4-骨头钱 5-骨头bonus 6-骨头map
    setItemState(item, type, data){
        let spine_box = cc.find("Map_XiangZi", item);
        let spr_disabled = cc.find("map_item_disabled", item);
        // let map_lock = cc.find("map_lock", item);
        let map_pay_board = cc.find("map_pay_board", item);
        let win_lbl = cc.find("boxOpenNum", item);
        let win_fg = cc.find("Map_fg_EN", item);
        let win_bonus = cc.find("map_bonus_EN", item);

        spine_box.active = type !== itemType.notClick;
        if(type === itemType.lock){
            spine_box.getComponent(sp.Skeleton).setAnimation(0,"Map_XiangZi_Suo_Loop",true);
        } else if(type === itemType.canClick){
            spine_box.getComponent(sp.Skeleton).setAnimation(0,"Map_XiangZi_Xiang_Loop1",true);
        } else if(type === itemType.coin ||type === itemType.bonus || type === itemType.free){
            spine_box.getComponent(sp.Skeleton).setAnimation(0,"Map_XiangZi_Xiang_Loop2",true);
        }

        spr_disabled.active = type === itemType.notClick;
        // map_lock.active = type === itemType.lock;
        map_pay_board.active = type === itemType.lock || type === itemType.canClick || type === itemType.notClick;
        if(map_pay_board.active){
            cc.find("collectFlag", map_pay_board).getComponent(cc.Label).string = Global.FormatNumToComma(data);
        }
        win_lbl.active = type === itemType.coin;
        if(win_lbl.active){
            win_lbl.getComponent(cc.Label).string = Global.formatNumShort(data,1)
        }
        win_fg.active = type === itemType.free;
        win_bonus.active = type === itemType.bonus;

    },

    // 箱子打开后动画
    setItemResult(idx, data){
        return new Promise(async(success, failed)=>{
            let item = this._itemList[idx].node;
            let spine_box = cc.find("Map_XiangZi", item);
            let map_pay_board = cc.find("map_pay_board", item);
            let win_lbl = cc.find("boxOpenNum", item);
            let win_fg = cc.find("Map_fg_EN", item);
            let win_bonus = cc.find("map_bonus_EN", item);

            spine_box.getComponent(sp.Skeleton).setAnimation(0, "Map_XiangZi_Xiang_DaKai", false);
            spine_box.getComponent(sp.Skeleton).addAnimation(0, "Map_XiangZi_Xiang_Loop2", true);

            map_pay_board.active = false;

            let showNode;
            if(data.coin > 0){
                this._itemList[idx].type = itemType.coin;
                win_lbl.getComponent(cc.Label).string = Global.formatNumShort(data.coin,1);
                showNode = win_lbl;
            } else if(data.bonusGame){
                this._itemList[idx].type = itemType.bonus;
                showNode = win_bonus;
            } else if(data.freeInfo){
                this._itemList[idx].type = itemType.free;
                showNode = win_fg;
            }

            showNode.active = true;
            showNode.setScale(0)
            cc.tween(showNode).to(0.5, {scale:1}, {easing:"backOut"}).start()
            await cc.vv.gameData.awaitTime(0.5)

            success();
        })
    },

    // 点箱子
    onClickItem(event){
        if(!this._canClickItem){
            return
        }

        let idx =  Number(event.node.name.substring("item".length));
        let curType = this._itemList[idx].type;
        if(curType === itemType.lock || curType === itemType.notClick){
            this.playBoxTipAnim(event.node);
        } else if(this._itemList[idx].type === itemType.canClick){
            Global.SlotsSoundMgr.playEffect("caseopen");

            this._canClickItem = false;
            this.onSendSeq(idx);
        }
    },
    //
    async onSendSeq(idx){
        let data = {
            rtype:4,
            pageId:this._curPage,
            choiceId:idx,
        }
        let msg = await cc.vv.gameData.reqSubGame(data);
        cc.log(msg);
        if(msg.code === 200 && msg.data && msg.data.rtype == 4){
            this.showClickResult(msg.data);
        }
    },

    // 点击结果
    async showClickResult(data){

        this._flagStore = data.flagStore;
        cc.vv.gameData.setFlagStore(this._flagStore);
        // this.updateCurMoney();
        this.showCurMoney(this._flagStore.flagCnt);
        cc.vv.gameData.GetSlotsScript().setFlagCnt(this._flagStore.flagCnt);

        let result = data.result;
        let idx = data.choiceId;


        await this.setItemResult(idx, result);
        if(this._flagStore.pageDetails[this._curPage-1].price > this._flagStore.flagCnt){  // 钱不够
            for (let i = 1; i <= 9; i++){
                if(this._itemList[i].type === itemType.canClick){
                    this._itemList[i].type = itemType.notClick;
                    this.setItemState(this._itemList[i].node, itemType.notClick, this._itemList[i].data)
                }
            }
            Global.SlotsSoundMgr.playEffect("caseunlock");
        }

        if(result.coin > 0){    // 赢钱
            cc.vv.gameData.AddCoin(result.coin);
            cc.vv.gameData.GetBottomScript().SetWin(result.coin);
            cc.vv.gameData.GetTopScript().ShowCoin();
        }
        if(result.freeInfo || result.bonusGame || result.pageReward){
            await cc.vv.gameData.awaitTime(0.5);
            cc.vv.gameData.setIsBoxGame(true);
            await this.closeStorePage();

            if(result.freeInfo){  // 赢免费
                cc.vv.gameData.SetTotalFree(result.freeInfo.freeCnt);
                cc.vv.gameData.SetFreeTime(result.freeInfo.freeCnt);

                await cc.vv.gameData.awaitTime(0.5);
                await cc.vv.gameData.getPopupScript().showFreeGameStartUI(result.freeInfo.freeCnt, true);
                cc.vv.gameData.getPopupScript().playFreeQPAnim();

                await cc.vv.gameData.awaitTime(2);
                cc.vv.gameData.GetBottomScript().SetWin(0);
                cc.vv.gameData.GetSlotsScript().ShowGameview(true);
                await cc.vv.gameData.awaitTime(1);
                cc.vv.gameData.GetBottomScript().CanDoNextRound();

            }
            else if(result.bonusGame){ // 赢bonus
                cc.vv.gameData.setBonusGame(result.bonusGame);
                await cc.vv.gameData.getBonusGameMgr().showBonusGame(result.bonusGame, true);

            }

            if(result.pageReward){  // 集满

                cc.vv.gameData.setPageReward(result.pageReward);
                cc.vv.gameData.setIsSuperFree(true);
                cc.vv.gameData.SetTotalFree(result.pageReward.freeCnt);
                cc.vv.gameData.SetFreeTime(result.pageReward.freeCnt);

                await cc.vv.gameData.awaitTime(0.5);
                await cc.vv.gameData.getPopupScript().showSuperFreeStartFreeUI(result.pageReward);
                cc.vv.gameData.getPopupScript().playFreeQPAnim();

                await cc.vv.gameData.awaitTime(2);
                cc.vv.gameData.GetBottomScript().SetWin(0);
                cc.vv.gameData.GetBottomScript().ShowFreeModel(true, 0, result.pageReward.freeCnt);
                // 初始化
                cc.vv.gameData.getSuperFreeMgr().initShowSlotsDate();
                await cc.vv.gameData.awaitTime(2);
                cc.vv.gameData.GetBottomScript().CanDoNextRound();
            }
            // await this.openStorePage()
        } else {
            // 设置可以再次点击
            this._canClickItem = true;
        }
    },

    onClickCloseBtn(){
    //     Global.SlotsSoundMgr.playEffect("click1");

        this.closeStorePage();

        // this._btn_entrance.getComponent(cc.Button).interactable = true;
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("idle");
    },


    // 箱子提示动画
    playBoxTipAnim(node){

        if(this._popBoxTix){
            return;
        }

        this._box_tip.stopAllActions();
        if(this._box_tip.active){
            this._box_tip.runAction(cc.sequence(
                cc.scaleTo(this._box_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false;})
            ))
        } else {
            Global.SlotsSoundMgr.playEffect("tips");
            this._box_tip.position = this._box_tip.parent.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0,0)));
            this._box_tip.active = true;
            this._box_tip.setScale(0);
            this._box_tip.runAction(cc.sequence(
                cc.callFunc(()=>{ this._popBoxTix = true;}),
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._box_tip.active = false; this._popBoxTix = false;})
            ))
        }
    },

    // 点击问号
    clickHelpBtn(){
        Global.SlotsSoundMgr.playEffect("tips");

        this._spr_tip.stopAllActions();
        if(this._spr_tip.active){
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(this._spr_tip.scaleX/2,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        } else {
            this._spr_tip.active = true;
            this._spr_tip.setScale(0);
            this._spr_tip.runAction(cc.sequence(
                cc.scaleTo(0.5,1,1),
                cc.delayTime(1),
                cc.scaleTo(0.5,0,0),
                cc.callFunc(()=>{ this._spr_tip.active = false;})
            ))
        }
    },

    // 左翻页
    async clickLeftBtn(){
        if(!this._canClickItem){
            return
        }
        this._canClickItem = false;
        Global.SlotsSoundMgr.playEffect("changebutton");

        if(this._curPage<=1){
            this._curPage = 4;
        }else{
            this._curPage--;
        }

        this.refreshDataWithAction(20);
        this.showPageFooter();
        this.showPageWinDetail();

        await cc.vv.gameData.awaitTime(1);
        this._canClickItem = true
    },

    // 右翻页
    async clickRightBtn(){
        if(!this._canClickItem){
            return
        }
        this._canClickItem = false;
        Global.SlotsSoundMgr.playEffect("changebutton");

        if(this._curPage>=4){
            this._curPage = 1;
        }else{
            this._curPage++;
        }


        this.refreshDataWithAction(20);
        this.showPageFooter();
        this.showPageWinDetail();

        await cc.vv.gameData.awaitTime(1);
        this._canClickItem = true
    },

    async refreshDataWithAction(deltaX){

        if(deltaX != 0){
            this._node_items.stopAllActions();
            this._node_items.x = 0;
            this._node_items.runAction(cc.sequence(cc.spawn(cc.fadeTo(0.15,63),cc.moveBy(0.15,deltaX,0)),
                cc.spawn(cc.fadeTo(0.15,255),cc.moveBy(0.15,-deltaX,0))));
        }

        this.showAllItems();
        for(let i=1; i<=9; i++){
            let item = this._itemList[i].node;
            item.setScale(0.1);
            item.stopAllActions();
            item.runAction(cc.scaleTo(0.1*i, 1,1).easing(cc.easeBackOut()))
        }
    },

    // 当前页码
    showPageFooter(){
        for (let i = 1; i <= 4; i++){
            let choosed = cc.find(cc.js.formatStr("layout/choose_bg/point%s/choice", i), this._node_box);

            choosed.active = i === this._curPage;
        }
    },

    // 当前页集满赢free
    showPageWinDetail(){
        let node_lock = cc.find("layout/node_lock", this._node_box);
        let node_unlock = cc.find("layout/node_unlock", this._node_box);

        if(this._curPage <= this._flagStore.unlockPage){
            node_lock.active = false;
            node_unlock.active = true;

            cc.find("page", node_unlock).getComponent("ImgSwitchCmp").setIndex(this._curPage-1);
            cc.find("pan", node_unlock).getComponent("ImgSwitchCmp").setIndex(this._curPage-1);

        } else {
            node_lock.active = true;
            node_unlock.active = false;

            cc.find("page", node_lock).getComponent("ImgSwitchCmp").setIndex(this._curPage-2);
        }

    },

    // update (dt) {},
});
