/**
 * quest gameitem
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _gameId: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        //绑定点击事件
        Global.btnClickEvent(this.node, this.OnClickGame, this)
        //监听进度
        cc.vv.SubGameUpdateNode.on("update_subgame_pro", this.downloadingPro.bind(this))
        Global.registerEvent("checkSubFinish", this.downloadingFinish, this);
        Global.registerEvent("enter_game", this.downloadingFinish, this);
    },

    start() {},

    /**
     * 
     * @param {*} gameId 游戏ID
     * @param {*} localIdx 本地序号，0开始
     * @param {*} curIdx 当前所在游戏序号，0开始
     * @param {*} nodeScale 节点的缩放倍数
     */
    setInfo: function (gameId, localIdx, curIdx, nodeScale) {
        this._gameId = gameId
        this._localIdx = localIdx
        this._curIdx = curIdx
        this._bLock = localIdx > curIdx
        if (localIdx == curIdx) {
            cc.tween(this.node)
                .to(0.2, { scale: nodeScale })
                .start()
        }

        //设置icon
        let iconNode = cc.find('slot_icon', this.node)
        // let iconUrl = 'CashHero/slots/quest/'+gameId
        // cc.vv.HerocardManager._comloadsprite(iconUrl,iconNode,gameId)
        iconNode.getComponent("CH_SlotIcon").setGameId(gameId, 'animation2')

        //TODO 是否解锁
        cc.find('spr_comp', this.node).active = localIdx < curIdx
        cc.find('spr_lock', this.node).active = this._bLock
        cc.find('gray_pro', this.node).active = this._bLock || localIdx < curIdx
        if (1.2 == nodeScale)    //nodeScale缩放1.2倍，是从CH_quest场景传进来；loginpop界面不需要显示按钮
            cc.find('btn_spin', this.node).active = (localIdx == curIdx)
        let spr_light = cc.find('spr_light', this.node)
        spr_light.active = (localIdx == curIdx)
        let spr_select = cc.find('spr_frame_select', this.node)
        if (spr_select) {
            spr_select.active = (localIdx == curIdx)
            // if(localIdx == curIdx){

            cc.tween(spr_select)
                .repeatForever(cc.tween()
                    .to(1, { opacity: 0 })
                    .delay(0.1)
                    .to(1, { opacity: 255 })
                    .delay(0.1)
                )
                .start()
        }



        //背景光旋转动画
        cc.tween(spr_light)
            .repeatForever(
                cc.tween()
                    .by(6, { angle: -360 })
            )
            .start()
        // }



    },

    setCurIndex: function (val) {
        this._curIdx = val
    },

    //解锁瞬间的表现
    showUnLock: function (nextCall) {
        let self = this
        this.showSelect(nextCall)
        cc.find('gray_pro', self.node).active = false
        cc.find('spr_lock', self.node).active = false
        cc.find('btn_spin', self.node).active = true
        cc.find('spr_light', self.node).active = true
        let spr_select = cc.find('spr_frame_select', self.node)
        if (spr_select) {
            spr_select.active = true
        }

    },

    showSelect: function (nextCall) {
        this.node.scale = 1
        cc.tween(this.node)
            .to(0.2, { scale: 1.2 })
            .call(() => {
                if (nextCall) {
                    nextCall()
                }
            })
            .start()
    },

    //完成瞬间的表现
    showComplete: function (nextCall) {
        let self = this
        cc.tween(this.node)
            .to(0.2, { scale: 1 })
            .call(() => {
                //显示勾
                cc.find('gray_pro', self.node).active = true
                cc.find('spr_comp', self.node).active = true
                cc.find('btn_spin', self.node).active = false
                cc.find('spr_light', self.node).active = false
                let spr_select = cc.find('spr_frame_select', self.node)
                if (spr_select) {
                    spr_select.active = false
                }

                if (nextCall) {
                    nextCall()
                }
            })
            .start()
        Global.playCashEff("quest/congrat");
    },



    //点击游戏
    OnClickGame: function () {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_START)

        if (this._localIdx > this._curIdx) {
            //给出提示
            this.showUnlockTip()
            cc.vv.AudioManager.stopEffectByName("locked");
            Global.playCashEff("quest/locked");
        }
        else if (this._localIdx < this._curIdx) {
            //已经完成了的任务
        }
        else {
            //是否需要下载
            // cc.vv.SubGameUpdateNode.getComponent('subGameMgr').setLoadingCheckModel(false,null)
            let gameId = this._gameId
            let bInnerGame = cc.vv.UserManager.isNoNeedDownGame(gameId) //是否是内置游戏
            if (cc.sys.isNative && Global.openUpdate && !bInnerGame) { // 手机平台需要检测更新
                cc.vv.SubGameUpdateNode.emit("check_subgame", gameId);
            } else {
                this.enterGame()

            }

            cc.vv.PlatformApiMgr.KoSDKTrackEvent('enter_quest_lv' + this._curIdx, JSON.stringify({ questlv: this._curIdx }))
        }
    },

    showUnlockTip: function () {
        let nodeTip = cc.find('spr_tip_bg', this.node)
        nodeTip.active = true
        if (nodeTip.getNumberOfRunningActions() == 0) {
            nodeTip.stopAllActions()
            nodeTip.scale = 0
            cc.tween(nodeTip)
                .to(0.3, { scale: 1 }, { easing: 'bounceOut' })
                .delay(3)
                .to(0.2, { scale: 0 })
                .start()
        }

    },

    downloadingPro: function (data) {
        if (cc.isValid(this.node)) {
            let gameid = data.gameId
            let pro = data.per
            if (gameid == this._gameId) {
                this._showPro(pro)
            }
        }
    },

    downloadingFinish: function (data) {
        if (cc.isValid(this.node)) {
            let gameid = data.detail
            if (gameid == this._gameId) {
                Global.playCashEff("hall/download_finish");
                let grayPro = cc.find('gray_pro', this.node)
                grayPro.active = false
                //直接进入游戏
                this.enterGame()
            }
        }
    },

    enterGame: function () {
        if (this._localIdx == this._curIdx) {
            //打点
            StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_DOWNLOAD)
            cc.vv.GameManager.setEnterOpation({ gameTask: 1 })
            //从这里进入游戏是不受等级限制的
            cc.vv.GameManager.EnterGame(this._gameId)
        }

    },

    _showPro: function (val) {
        let grayPro = cc.find('gray_pro', this.node)
        grayPro.active = true
        let lblVal = cc.find('lbl_pro', grayPro)
        lblVal.active = true
        lblVal.getComponent(cc.Label).string = val + '%'
        grayPro.getComponent(cc.ProgressBar).progress = 1 - val / 100
    },

    // update (dt) {},
});
