cc.Class({
    extends: cc.Component,

    properties: {
        bg: cc.Node,
        panel: cc.Node,
        symbol: cc.Node,
        reel: cc.Node,
        frame: cc.Node,
        spineRunPointer: sp.Skeleton,    // 火花spine
        spineResult: sp.Skeleton,        // 中奖结果spine
        btn_ok: cc.Button,

        _cbHandler: null,
        _reelLen: 6, // 卷轴元素
        _itemHeight: 138,
        _symbolItems: [],
        _reelResult: null, // 卷轴结果
        _moveObj: null, // 移动总距离
        _jpData: null, // 服务器返回数据 {"id":1,"value":526000}
        _resultId: 0, // 旋转结果
        _cfg: null,
    },

    onLoad() {
        this._cfg = SlotsFacade.dm.getGameCfg();
        // 初始化卷轴
        for (let i = 0; i < this._reelLen; i++) {
            let item = cc.instantiate(this.symbol);
            item.active = true;
            item.parent = this.reel;
            item.idx = i;
            this._symbolItems.push(item);
        }
        this._itemHeight = this._symbolItems[0].height;
        this.setReelPos();
        this._initMoveObj();
        this.btn_ok.node.on("click", this._onOkBtn, this);
    },

    onDestroy() {
        this._cfg = null;
    },

    _onOkBtn() {
        SlotsFacade.soundMgr.playEffect("wheel_click");
        this.btn_ok.node.stopAllActions();
        this.btn_ok.interactable = false;
        cc.find("spine", this.btn_ok.node).active = false;
        SlotsFacade.dm.reqSubGame({ rtype: 3 });
    },

    _initView() {
        this.bg.active = true;
        this.panel.active = true;
        this.spineRunPointer.node.active = false;
        this.spineResult.node.active = false;
        this.btn_ok.interactable = true;
        cc.find("spine", this.btn_ok.node).active = true;
        cc.vv.gameData.checkAutoPlay(this.btn_ok.node, this._onOkBtn.bind(this));
    },

    setReelPos() {
        for (let i = 0; i < this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            item.y = this._itemHeight / 2 + this._itemHeight * i;
        }
    },

    _initMoveObj() {
        this._moveObj = {
            round: 12,        // 剩余圈数
            minSpeed: 200,   // 最小速度/s
            maxSpeed: 1800,  // 最大速度/s
            currSpeed: 0,    // 当前速度
            acc: 20,         // 加速度
            totalDis: 0,     // 总移动距离
            movedDis: 0,      // 已经移动距离
            canMove: false,  // 是否可移动
            addSpeedPer: 0.94, // 加速百分比
        };
        this._moveObj.currSpeed = this._moveObj.minSpeed;
        this._moveObj.totalDis = this._moveObj.round * this._reelLen * this._itemHeight;
    },

    /**
     * 收到请求结果
     * @param msg
     */
    onMsg(msg) {
        if (msg.code == 200 && msg.data.rtype == 3) {
            this._resultId = msg.data.resultId;
            this._reelResult = this.genReelData(msg.data.resultId - 1);
            SlotsFacade.dm.respinData = msg.data.bonusGame;
            this._initMoveObj();
            this._startReel();
        }
    },

    /**
     * 通过jpId 生成卷轴数据
     * @param {*} jpId
     */
    genReelData(idx) {
        let ret = [];
        for (let i = 0; i < this._reelLen; i++) {
            if (idx >= this._cfg.WheelGameConfig.length) {
                idx = 0;
            }
            ret.push(this._cfg.WheelGameConfig[idx]);
            idx += 1;
        }
        ret.unshift(ret.pop());
        ret.unshift(ret.pop());
        return ret;
    },

    async close() {
        await SlotsFacade.mainPanel.showSceneTransition(2);
        this.bg.active = false;
        this.panel.active = false;
        await SlotsFacade.delayTime(0.5);
        if (this._cbHandler) {
            this._cbHandler(this._resultId);
        }
    },

    async open(cbHandler) {
        this._cbHandler = cbHandler;
        await SlotsFacade.mainPanel.showSceneTransition(2);
        SlotsFacade.soundMgr.playBgm("wheel_bgm");
        this._initView();
        this._initReel();
    },

    /**
     * 初始化卷轴
     */
    _initReel() {
        let reelData = this.genReelData(Math.floor(Math.random() * this._cfg.WheelGameConfig.length));
        let reelDataLen = reelData.length;
        for (let i = 0; i < this._symbolItems.length; i++) {
            let symbol = this._symbolItems[i];
            this._bindSymbolData(symbol, reelData[i % reelDataLen]);
        }
    },

    /**
     * 绑定symbol数据
     * @param symbol
     * @param data
     * @private
     */
    _bindSymbolData(symbol, data) {
        let bgImg = symbol.getChildByName("bg").getComponent("ImgSwitchCmp");
        let iconImg = symbol.getChildByName("icon").getComponent("ImgSwitchCmp");
        let labelGreen = symbol.getChildByName("label_green").getComponent(cc.Label);
        let labelYellow = symbol.getChildByName("label_yellow").getComponent(cc.Label);
        bgImg.setIndex(data.bgIdx);
        if (data.mult) {
            iconImg.node.active = false;
            let val = Global.FormatNumToComma(SlotsFacade.dm.GetTotalBet() * data.mult);
            if (data.mult == 15) {
                labelGreen.node.active = false;
                labelYellow.node.active = true;
                labelYellow.string = val;
            } else {
                labelGreen.node.active = true;
                labelYellow.node.active = false;
                labelGreen.string = val;
            }
        } else {
            iconImg.node.active = true;
            labelGreen.node.active = false;
            labelYellow.node.active = false;
            iconImg.setIndex(data.iconIdx);
        }
    },

    /**
     * 开始旋转
     * @private
     */
    _startReel() {
        SlotsFacade.soundMgr.playEffect("wheel_roll");
        this._moveObj.canMove = true;
        this.spineRunPointer.node.active = true;
    },

    /**
     * 旋转完毕
     */
    async _endReel() {
        this._moveObj.canMove = false;
        SlotsFacade.soundMgr.playEffect("option");
        this.spineRunPointer.node.active = false;
        this.spineResult.node.active = true;
        await SlotsFacade.delayTime(2);
        this.close();
    },

    update(dt) {
        if (!this._moveObj || !this._moveObj.canMove) {
            return;
        }
        // 前1/4距离加速 后1/5距离减速
        let per = this._moveObj.movedDis / this._moveObj.totalDis;
        per = Math.min(per, 1);
        let speed = this._moveObj.currSpeed;
        if (per < this._moveObj.addSpeedPer) {
            speed += this._moveObj.acc;
        } else if (per >= this._moveObj.addSpeedPer) {
            speed -= this._moveObj.acc;
        }
        speed = Math.max(this._moveObj.minSpeed, speed);
        speed = Math.min(this._moveObj.maxSpeed, speed);
        this._moveObj.currSpeed = speed;
        let dis = this._moveObj.currSpeed * dt;
        if (dis > this._itemHeight) {
            dis = this._itemHeight;
        }
        this._moveObj.movedDis += dis;
        // 修改位置
        for (let i = 0; i < this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            item.y -= dis;
        }
        // 将超过底边的icon放到最上面
        for (let i = 0; i < this._symbolItems.length; i++) {
            let item = this._symbolItems[i];
            if (item.y < -this._itemHeight / 2) {
                let nextIdx = item.idx - 1;
                if (nextIdx < 0) {
                    nextIdx = this._reelLen - 1;
                }
                let nextItem = this._symbolItems[nextIdx];
                item.y = nextItem.y + this._itemHeight;
                if (item.idx == this._reelLen - 1) {
                    this._moveObj.round -= 1;
                }
                // 最后一圈需要设置结果数据
                if (this._moveObj.round == 0) {
                    let data = this._reelResult[i % this._reelResult.length];
                    this._bindSymbolData(item, data);
                } else {
                    this._bindSymbolData(item, this._cfg.WheelGameConfig[Math.floor(Math.random() * this._cfg.WheelGameConfig.length)]);
                }
                // 转完
                if (this._moveObj.round < 0) {
                    this._endReel();
                }
            }
        }
    }
})