let QuestData = [
    { 'labelPos': [27, -60] },
    { 'labelPos': [157, -60] },
];

let ADCFG = {
    1: { titlePos: [185, 5] },
    2: { titlePos: [114, 66] },
    3: { titlePos: [-1, 66] },
    4: { titlePos: [-1, 80] },
    5: { titlePos: [150, 42] }
};

cc.Class({
    extends: cc.Component,

    properties: {
        itemAtlas: {
            default: null,
            type: cc.SpriteAtlas,
        },
        // itemARAtlas: {
        //     default: null,        
        //     type: cc.SpriteAtlas, 
        // },
    },

    onLoad() {
        //单次滑动结束 防止出现多点触摸
        this.canTouchFlag = true
        this.activeIsClick = false
        //监听触摸事件
        cc.find("mask", this.node).on("click", this.onClickAd, this)
        // //监听触摸开始事件
        // this.node.on(cc.Node.EventType.TOUCH_START,this.on_touch_start,this);
        // this.node.on(cc.Node.EventType.TOUCH_MOVE,this.on_touch_move,this);
        // //监听作用域内触摸抬起事件
        // this.node.on(cc.Node.EventType.TOUCH_END,this.on_touch_end,this);
        // //监听作用域外触摸抬起事件
        // this.node.on(cc.Node.EventType.TOUCH_CANCEL,this.on_touch_cancel,this);
        //X的差值
        this.offX = 870
        this._curAdNodeFlag = 0
        this._curAdFlag = 0
        this.maxAd = 4

        this._inter = 0

        //底部白条
        this.halfOpa = 120
        this.disX = 60

        // Global.registerEvent(EventId.SYS_CHANGE_LANGUAGE,this.onEventChangeLan,this)
    },

    start() {
        //根据等级不一样分别显示不同的展示面
        this.pageArray = []
        // this.pageArray.push(0)

        //月卡  id = 1
        if (!Global.isIOSReview()) {
            this.pageArray.push(1)
        }

        //quest     id = 2
        let bHasQuest = cc.vv.PopUIMgr.isHasLoginPopId(11)
        if (bHasQuest) {
            this.pageArray.push(2)
        }

        //lucky     id = 3
        let bOpenSmash = cc.vv.UserManager.isOpen(Global.SYS_OPEN.LUCKY_SMASH)
        if (bOpenSmash) {
            this.pageArray.push(3)
        }

        //BINGO
        let bOpenBingo = cc.vv.UserManager.isOpen(Global.SYS_OPEN.BINGO)
        if (cc.vv.UserManager.isActivityOpen(1) && bOpenBingo) {
            this.pageArray.push(4)
        }

        // 骑士的探索
        let bOpenExplore = cc.vv.UserManager.isOpen(Global.SYS_OPEN.EXPLORATION)
        if (cc.vv.UserManager.isActivityOpen(2) && bOpenExplore) {
            this.pageArray.push(5)
        }

        //初始化底部白条
        // let whitePrefab = cc.find('buttom/white', this.node)
        // whitePrefab.opacity = 255
        // whitePrefab.x = -(this.pageArray.length-1)*this.disX/2

        // this.whiteArray = []
        // this.whiteArray.push(whitePrefab)

        // var itemNode = null
        // for (let i = 1; i < this.pageArray.length; i++) {
        //     itemNode = cc.instantiate(whitePrefab);
        //     itemNode.parent = whitePrefab.parent;
        //     itemNode.opacity = this.halfOpa
        //     itemNode.x = whitePrefab.x + i*this.disX
        //     this.whiteArray.push(itemNode)
        // }

        //初始化
        let adNode = cc.find('mask/ad_0', this.node)
        this.setAdNodeSprite(1, adNode)
    },

    onEventChangeLan() {
        let adNode = cc.find(cc.js.formatStr('mask/ad_%s', this._curAdNodeFlag), this.node)
        this.setAdNodeSprite(this.pageArray[this._curAdFlag], adNode)
    },

    onClickAd() {
        this.setBtnClick(this.pageArray[this._curAdFlag])
    },

    // on_touch_start (event) {
    //     if (!this.canTouchFlag) {
    //         return
    //     }
    //     this._touchStartPos = event.touch.getLocation();

    //     this._inter = 0
    //     this.actionIsClick = true
    //     this.canTouchFlag = false
    //     this.clickEffect(true)
    // },
    // on_touch_move (t) {
    //     this.actionIsClick = false
    //     // if (this.canTouchFlag) {
    //     //     return
    //     // }
    //     // let pos = t.touch.getLocation();

    //     // let deltaDis = this._touchStartPos.x - pos.x
    //     // if (Math.abs(deltaDis) > 50) {
    //     //     if (deltaDis < 0) {
    //     //         //向右滑动
    //     //         this.autoSlide(1)
    //     //         this.canTouchFlag = true
    //     //     }else {
    //     //         //向左滑动
    //     //         this.autoSlide(0)
    //     //         this.canTouchFlag = true
    //     //     }
    //     // }
    // },

    //向左0 向右1
    autoSlide(flag) {
        // this.whiteArray[this._curAdFlag].opacity = this.halfOpa
        let len = this.pageArray.length
        if (len <= 1) {
            return
        }
        if (flag) {
            if (!this._curAdFlag) {
                // this._curAdFlag = this.maxAd
                this._curAdFlag = len - 1
            } else {
                this._curAdFlag--
            }
        } else {
            if (this._curAdFlag == (len - 1)) {
                this._curAdFlag = 0
            } else {
                this._curAdFlag++
            }
        }
        let nextFlag = this._curAdNodeFlag ? 0 : 1
        let moveFlag = flag ? 1 : -1
        let posFlag = flag ? -1 : 1

        let curNode = cc.find(cc.js.formatStr('mask/ad_%s', this._curAdNodeFlag), this.node)
        curNode.off('click')
        this.moveAction(moveFlag, curNode)

        let nextNode = cc.find(cc.js.formatStr('mask/ad_%s', nextFlag), this.node)
        this.setPos(posFlag, nextNode)
        this.moveAction(0, nextNode)

        let adId = parseInt(this.pageArray[this._curAdFlag])
        this.setAdNodeSprite(adId, nextNode)

        let lblreward = cc.find('lbl_coin', nextNode)
        if (adId == 2) {
            lblreward.active = true
            lblreward.getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.UserManager.questmaxcoin)
            //修改questLabel位置
            let questID = cc.vv.UserManager.getCurQuestId()
            let _labelPos = (questID > 1) ? QuestData[1].labelPos : QuestData[0].labelPos
            // lblreward.setPosition(cc.Vec2(_labelPos[0],_labelPos[1]))
        } else {
            lblreward.active = false
        }

        // this.whiteArray[this._curAdFlag].opacity = 255

        this._curAdNodeFlag = this._curAdNodeFlag ? 0 : 1
    },

    moveAction(flag, adNode) {
        cc.tween(adNode)
            .to(0.6, { x: flag * this.offX }, { easing: 'quartOut' })
            .start()
    },

    setPos(flag, adNode) {
        adNode.x = flag * this.offX
    },

    setAdNodeSprite(flag, adNode) {
        // let num = flag
        // if (flag == 2) {
        //     let questID = cc.vv.UserManager.getCurQuestId()
        //     num = (questID > 1) ? 5: 2
        // }
        let self = this
        cc.find('icon', adNode).getComponent(cc.Sprite).spriteFrame = this.itemAtlas.getSpriteFrame(cc.js.formatStr('ad_%s', flag))
        let titleNode = cc.find('title', adNode)
        if (titleNode) {
            let changeCall = function () {
                titleNode.getComponent(cc.Sprite).spriteFrame = Global.language == Global.LANGUAGE.EN ? self.itemAtlas.getSpriteFrame(cc.js.formatStr('ad_%s_%s', flag, flag)) : self.itemARAtlas.getSpriteFrame(cc.js.formatStr('ad_%s_%s', flag, flag))
                let _posX = (Global.language == Global.LANGUAGE.AR && flag == 1) ? ADCFG[flag].titlePos[0] - 30 : ADCFG[flag].titlePos[0]
                titleNode.setPosition(cc.v2(_posX, ADCFG[flag].titlePos[1]))
            }
            I18N.setI18SpriteChangeCall(titleNode, changeCall)

            // cc.find('sprFrame', adNode).active = flag==2
        }

    },

    // on_touch_end () {
    //     if(this.pageArray){
    //         if (this.actionIsClick || !this.canTouchFlag) {
    //             this.setBtnClick(this.pageArray[this._curAdFlag])
    //             this.actionIsClick = false
    //         }

    //         this.canTouchFlag = true
    //         this._inter = 0
    //     }
    //     this.clickEffect(false)

    // },
    // on_touch_cancel () {
    //     this.canTouchFlag = true
    //     this._inter = 0
    //     this.clickEffect(false)
    // },

    clickEffect(bDown) {
        if (bDown) {
            if (this.node.scale == 0.9) return
            cc.tween(this.node)
                .to(0.1, { scale: 0.9 })
                .start()
        }
        else {
            if (this.node.scale == 1) return
            cc.tween(this.node)
                .to(0.1, { scale: 1 })
                .call(() => {
                    this.setBtnClick(this.pageArray[this._curAdFlag])
                })
                .start()
        }

    },

    setBtnClick(flag) {
        if (!flag) {
            return
        }
        if (flag == 1) {
            this.onClickMonth()
        } else if (flag == 2) {
            this.onClickQuest()
        } else if (flag == 3) {
            this.onClickLuckysmath()
        } else if (flag == 4) {
            this.onClickBingo()
        } else if (flag == 5) {
            this.onClickExplore()
        }
    },

    onClickQuest: function () {
        this._inter = 0
        cc.vv.NetManager.send({ c: MsgId.REQ_QUEST_INFO })
    },

    onClickMonth: function () {
        this._inter = 0
        cc.loader.loadRes("CashHero/prefab/month_card", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas");
                if (canvas.isValid && !cc.find('month_card', canvas)) {
                    let obj = cc.instantiate(prefab)
                    obj.parent = canvas
                }
            }

        })
    },

    //金蛋
    onClickLuckysmath: function () {
        this._inter = 0
        let url = "CashHero/prefab/lucky_smash/lucky_main"
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find("Canvas")
            }


        })

        // cc.loader.loadRes("CashHero/prefab/mission/mission_frame",cc.Prefab, (err, prefab) => {
        //     if (!err) {
        //         let canvas = cc.find("Canvas");
        //         let old = cc.find('mission_frame',canvas)
        //         if(!old){
        //             let node = cc.instantiate(prefab);
        //             node.parent = canvas;
        //             node.getComponent("Mission_Frame").onTabLuckyClick()
        //         }
        //     }
        // });
    },

    //BINGO
    onClickBingo: function () {
        this._inter = 0
        cc.loader.loadRes("CashHero/prefab/bingo/bingo_main", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas")
                let old = cc.find('bingo_main', canvas)
                if (!old) {
                    let node = cc.instantiate(prefab)
                    node.parent = canvas
                    node.getComponent("Bingo_Main").showLevelView(1)
                }
            }
        })
    },

    // 骑士的探索
    onClickExplore: function () {
        this._inter = 0
        cc.loader.loadRes("CashHero/prefab/exploration/explore_main", cc.Prefab, (err, prefab) => {
            if (!err) {
                let canvas = cc.find("Canvas")
                let old = cc.find('explore_main', canvas)
                if (!old) {
                    let node = cc.instantiate(prefab)
                    node.parent = canvas
                    node.getComponent('Explore_Main').setFrom(1)
                }
            }
        })
    },


    update(dt) {
        this._inter += dt
        if (this._inter >= 5) {
            this._inter = 0
            //滑动
            this.autoSlide(0)
        }
    },
});
