/**
 * 系统消息
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_go = cc.find('btn_action', this.node)
        Global.btnClickEvent(btn_go, this.onClickGo, this)
    },

    start() {

    },

    setData: function (data) {
        this._sysdata = data
        //title
        let lbl_title = cc.find('lbl_title', this.node)
        lbl_title.getComponent(cc.Label).string = data.title
        //content
        let lbl_content = cc.find('lbl_content', this.node)
        lbl_content.getComponent(cc.Label).string = data.content

        let btn_go = cc.find('btn_action', this.node)
        btn_go.active = (data.sys_type == 1 || data.sys_type == 2)
        let btnStr = "Goto Inboxs"
        if (data.sys_type == 2) {
            btnStr = "Play With Him"
        }
        Global.setLabelString("Background/Label", btn_go, btnStr)
    },

    onClickGo: function () {
        let sysVal = this._sysdata.sys_type

        if (sysVal == 1) {
            //跳转到邮件
            Global.dispatchEvent(EventId.GO_HALL_TAB, 2)
            cc.vv.UserManager.setEnterHallAction('open_mail')
            Global.dispatchEvent(EventId.CHECK_HALL_USERACTION)
            //打卡
            StatisticsMgr.reqReport(StatisticsMgr.REQ_SOCIAL_GOTOINBOX)
        }
        else if (sysVal == 2) {
            //跳转游戏
            cc.vv.UserManager.goSystemUI("entergame", this._sysdata.gameid)
        }


    },

    // update (dt) {},
});
