/**
 * 英雄经验浮窗
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_START, this.OnRcvNetSpin, this)
        Global.registerEvent(EventId.CLOSE_BIG_LV_UP, this.onEventCloseBigLevelup, this)

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onBetChange, this)
        Global.registerEvent("HEROCARD_UPDATED", this.onCardUpate, this)
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_START, this.OnRcvNetSpin, false, this)

    },

    start() {
        this.showInfo()

        //是否押注额满足解锁
        this.onBetChange()
    },

    onEnable() {
        this.node.on(cc.Node.EventType.TOUCH_START, this._onTouchStart, this)
        this.node.on(cc.Node.EventType.TOUCH_MOVE, this._onTouchMove, this)
        this.node.on(cc.Node.EventType.TOUCH_END, this._onTouchEnd, this)
    },

    onDisable() {
        this.node.off(cc.Node.EventType.TOUCH_START, this._onTouchStart, this)
        this.node.off(cc.Node.EventType.TOUCH_MOVE, this._onTouchMove, this)
        this.node.off(cc.Node.EventType.TOUCH_END, this._onTouchEnd, this)
    },

    onCardUpate: function () {
        this.showInfo();
    },

    showInfo: function () {

        let exp = cc.vv.UserManager.getPvpCardExp();
        cc.find("lbl", this.node).getComponent(cc.Label).string = Global.convertNumToShort(exp, 1000, 1);

        let cardId = cc.vv.gameData.getDeskInfo().spCardId
        this._cardId = cardId
    },

    //点击按钮响应
    onNodeClicked: function () {
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)
        if (bOpen) {
            let bHeroUnlock = false
            let info = cc.vv.HerocardManager.getCardInfo(this._cardId)
            if (info) {
                bHeroUnlock = info.lv > 0 ? true : false
            }
            if (bHeroUnlock) {
                let minBet = cc.vv.gameData.getDeskInfo().needbet
                let curBetIdx = cc.vv.gameData.GetBetIdx()
                if (minBet <= curBetIdx) {
                    //点开升级界面
                    this.showDetail()
                }
                else {
                    //押注额不够，需要自动设置到此押注额
                    let bottom = cc.vv.gameData.GetBottomScript()
                    bottom.SetBetIdx(minBet)
                }

            }
            else {
                // this.showDetail()
                cc.vv.FloatTip.show(cc.js.formatStr('Please unlock the hero first!'));
                //打卡
                // StatisticsMgr.reqReport(StatisticsMgr.REQ_FLOAT_EXPUNLOCK, this._cardId)
            }
        }
        else {
            // cc.vv.FloatTip.show(cc.js.formatStr('Hero system will unlocked at level %s',Global.SYS_OPEN.HERO_CARD));
            cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_hero_system_unlock, Global.SYS_OPEN.HERO_CARD));
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FLOAT_EXPLOCK, '点击了游戏内万能经验浮窗')
    },

    updateExp: function (exp) {
        //exp
        cc.find("lbl", this.node).getComponent(cc.Label).string = Global.convertNumToShort(exp, 1000, 1);

    },

    OnRcvNetSpin: function (msg) {
        if (msg.code == 200) {
            if (msg.pvp_card_exp) {
                //更新数据
                // let oldVal = cc.vv.HerocardManager.getCardInfo(this._cardId)

                // cc.vv.HerocardManager.updateCardInfo(msg.cardInfo)
                cc.vv.UserManager.setPvpCardExp(msg.pvp_card_exp);
                cc.vv.HerocardManager.setRemainExp(msg.pvp_card_exp);
                this.updateExp(msg.pvp_card_exp)
                // if(oldVal && oldVal.lv != msg.cardInfo.lv){
                //     let bReward = this.isHaveRewardLv(msg.cardInfo.lv)
                //     if(bReward){
                //         //有奖励的升级表现
                //         cc.loader.loadRes("CashHero/prefab/herocard/card_levelup_tip",cc.Prefab, (err, prefab) => {
                //             if (!err) {
                //                 let parObj = cc.find("Canvas");
                //                 let node = cc.find('card_levelup_tip',parObj)
                //                 if(!node){
                //                     node = cc.instantiate(prefab);
                //                     node.parent = parObj
                //                 }
                //                 node.getComponent("CH_Herocard_Explevelup").setInfo(msg.cardInfo,oldVal.lv);
                //             }
                //         })
                //     }
                //     else{
                let bResume
                if (!this.node.active) {
                    bResume = true
                    Global.dispatchEvent(EventId.SHOW_FLOAT_ITEM, 'heroexp')
                }

                //普通升级表现
                let nodeSpine = cc.find('spine', this.node)
                nodeSpine.active = true
                nodeSpine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                this.scheduleOnce(() => {
                    if (bResume) {
                        Global.dispatchEvent(EventId.RESUME_FLOAT_ITEM)
                    }
                }, 1)
                // let url = 'CashHero/prefab/herocard/herocard_levelup/spine'
                // cc.vv.HerocardManager._comloadspine(url,nodeSpine,'animation',null,false)
                //     }
                //
                // }

                if (cc.vv.NewGuide.GetGuideTempData() == 114) {
                    let bDone115 = cc.vv.NewGuide.ShowGuide(115)
                    if (!bDone115) {
                        cc.vv.NewGuide.SetGuideTempData(115)
                    }
                }
            }
        }
    },

    onEventCloseBigLevelup: function () {
        this.showInfo()
    },

    //检查押注额是否影响解锁显示
    onBetChange: function () {

        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)
        let minBet = cc.vv.gameData.getDeskInfo().needbet
        let curBetIdx = cc.vv.gameData.GetBetIdx()
        let betReq = minBet <= curBetIdx

        let info = cc.vv.HerocardManager.getCardInfo(this._cardId)
        let bcardUnlock = info && info.lv > 0
        this.showLock(!(bOpen && betReq && bcardUnlock))
    },

    showDetail: function () {
        let cardId = cc.vv.gameData.getDeskInfo().spCardId
        if (!cardId) {
            //没有卡的不显示
            return
        }
        cc.loader.loadRes("CashHero/prefab/herocard/card_upGrade", cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                let node = cc.find('CH_Herocard_upGrade', parObj)
                if (!node) {
                    node = cc.instantiate(prefab);
                    node.parent = parObj
                }
                let cardInfo = cc.vv.HerocardManager.getCardInfo(this._cardId)
                node.getComponent("CH_Herocard_upGrade").Init(cardInfo);
            }
        })

        // cc.loader.loadRes("CashHero/prefab/herocard/card_detail",cc.Prefab, (err, prefab) => {
        //     if (!err) {
        //         let parObj = cc.find("Canvas");
        //         let old = cc.find('card_detail',parObj)
        //         if(!old){
        //             let node = cc.instantiate(prefab);
        //             node.parent = parObj
        //             let cardInfo = cc.vv.HerocardManager.getCardInfo(this._cardId)
        //             let campId = 0
        //             node.getComponent("CH_Herocard_Detail").init(cardInfo,false,campId);
        //         }

        //     }
        // })
    },

    showLock: function (bShow) {
        // let node_lock = cc.find('node_lock',this.node)
        // node_lock.active = bShow

    },

    _checkReddot: function () {
        let cardInfo = cc.vv.HerocardManager.getCardInfo(this._cardId)
        let bCanAddStar = cc.vv.HerocardManager.isCardCanAddStar(cardInfo)
        this.showReddot(bCanAddStar)
    },

    //是否显示大窗口提示
    isHaveRewardLv: function (lv) {
        let res = false
        // let cfg = [10, 30, 50, 65, 80, 90, 100]
        // for(let i = 0; i < cfg.length; i++){
        //     if(lv == cfg[i]){
        //         res = true
        //         break
        //     }
        // }
        res = (lv % 10 == 0)
        return res
    },


    _onTouchStart(event) {
        this._moved = false
        this._startPos = event.getLocation()
        this._lastPos = cc.v2(this._startPos.x, this._startPos.y)
    },

    _onTouchMove(event) {
        let location = event.getLocation()
        if (this._lastPos.sub(location).len() > 4) {
            this._lastPos = cc.v2(location.x, location.y)
            let box = this.node.getBoundingBox()
            if (location.x + box.width / 2 > cc.winSize.width) location.x = cc.winSize.width - box.width / 2
            if (location.x - box.width / 2 < 0) location.x = box.width / 2
            if (location.y + box.height / 2 > cc.winSize.height) location.y = cc.winSize.height - box.height / 2
            if (location.y - 2 * box.height / 2 < 0) location.y = 2 * box.height / 2
            // this.node.position = this.node.parent.convertToNodeSpaceAR(location)
            if (this._startPos.sub(location).len() > 10) {
                this._moved = true
            }
        }

    },

    _onTouchEnd(event) {
        if (!this._moved) { //未移动过，触发点击
            this.onNodeClicked()
        }
    },

    showReddot(flag) {
        cc.find('reddot', this.node).active = flag
    },


    // update (dt) {},
});
