/**
 * 下载成功提示
 */

cc.Class({
    extends: cc.Component,

    properties: {
        _gameId: null,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_yes = cc.find('spr_ui_bg/btn_yes', this.node)
        let btn_no = cc.find('spr_ui_bg/btn_no', this.node)
        Global.btnClickEvent(btn_yes, this.onClickYes, this)
        Global.btnClickEvent(btn_no, this.onClickNo, this)

    },

    start() {
        Global.showAlertAction(cc.find('spr_ui_bg', this.node), true)
    },

    //显示游戏图标
    //showType:默认是热更进入，1就是新手游戏推荐
    ShowGameInfo: function (id, showType) {
        this._gameId = id
        this._showType = showType
        let bShowNewer = this._showType == 1
        cc.find('spr_ui_bg/spr_txt1', this.node).active = !bShowNewer
        cc.find('spr_ui_bg/spr_txt2', this.node).active = bShowNewer
        if (bShowNewer) {
            StatisticsMgr.reqReport(StatisticsMgr.REQ_START_GAME_GUIDE);
        }
        let cfg = cc.vv.GameItemCfg[id]
        if (!cfg) {
            console.warn(cc.js.formatStr('>>>> %s 未配置GameItemCfg', id))
            return
        }
        let slot = cc.find('spr_ui_bg/spr_game_bg', this.node)
        slot.active = false
        let poker = cc.find('spr_ui_bg/poker', this.node)
        poker.active = false
        let icon = slot
        let path = "CashHero/slots/icon/"
        if (cfg.poker) {
            path = "CashHero/poker/"
            icon = poker
        }

        cc.loader.loadRes(path + cfg.action, cc.SpriteFrame, (err, spriteFrame) => {
            if (!err) {
                icon.getComponent(cc.Sprite).spriteFrame = spriteFrame;
                icon.active = true

            }
        });

        let spine = cc.find('icon_ani', icon)
        if (spine) {
            spine.active = false
        }


        if (!cfg.animation) return;

        cc.loader.loadRes("CashHero/slots/icon/" + cfg.action + "/spine", sp.SkeletonData, (err, data) => {
            if (!err) {
                spine.active = true;
                let ske = spine.getComponent(sp.Skeleton);
                ske.skeletonData = data;
                ske.setAnimation(0, cfg.animation, true);
            }
        });
    },

    onClickNo: function () {
        if (this._showType == 1) {
            cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        }

        this.node.destroy()
    },

    onClickYes: function () {
        //进入游戏
        Global.dispatchEvent("enter_game", this._gameId);
    },

    // update (dt) {},
});
