    //检查红点显示
    _checkReddot() {
        let bShowRed = false
        let cardId = cc.vv.gameData.getDeskInfo().spCardId
        let cardInfo = cc.vv.HerocardManager.getCardInfo(cardId)
        if (cardInfo) {
            let bCanUnlock = cc.vv.HerocardManager.isCardCanUnlock(cardInfo)
            let bCanAddStar = cc.vv.HerocardManager.isCardCanAddStar(cardInfo)
            let bCanAchive = cc.vv.HerocardManager.isCardHasAcviment(cardInfo)
            bShowRed = bCanUnlock || bCanAddStar || bCanAchive
        }

        this.showReddot(bShowRed)
    },

    showReddot(flag) {
        cc.find('reddot', this.node).active = flag
    },

    onEventExpLevelup: function () {
        //检查是否解锁
        this.onBetChange()
    },

    onCardUpate: function (data) {
        let val = data.detail
        let cardId = cc.vv.gameData.getDeskInfo().spCardId
        if (val && val.cardid == cardId) {
            this.setInfo()
            this.onBetChange()
            this._checkReddot()
        }
    },


    showLock: function (bShow) {
        let node_lock = cc.find('node_lock', this.node)
        node_lock.active = bShow

        let cardId = cc.vv.gameData.getDeskInfo().spCardId
        let herounlock = cc.vv.HerocardManager.isCardUnlock(cardId)
        if (herounlock) {
            cc.find('node_unlock', this.node).active = false
        }
        else {
            cc.find('node_unlock', this.node).active = !bShow
        }


        if (bShow) {
            //押注额不够
            this.showTips()
        } else {
            cc.find('spr_tip', this.node).active = false
        }
    },

    //点击按钮响应
    onNodeClicked: function () {
        this.showReddot(false)
        let bOpen = cc.vv.UserManager.isOpen(Global.SYS_OPEN.HERO_CARD)
        if (bOpen) {
            let minBet = cc.vv.gameData.getDeskInfo().needbet
            let curBetIdx = cc.vv.gameData.GetBetIdx()
            if (minBet <= curBetIdx) {
                //点开升星
                this.showDetail()


            }
            else {
                if (cc.vv.gameData.GetSlotState() == 'idle' && !cc.vv.gameData.GetFreeTime()) {
                    //押注额不够，需要自动设置到此押注额
                    let bottom = cc.vv.gameData.GetBottomScript()
                    bottom.SetBetIdx(minBet)
                    bottom._ShowBetProTip()
                }
            }

        }
        else {
            // cc.vv.FloatTip.show(cc.js.formatStr('Hero system will unlocked at level %s',Global.SYS_OPEN.HERO_CARD));
            cc.vv.FloatTip.show(I18N.getI18nLabel(cc.vv.Language.float_tip_hero_system_unlock, Global.SYS_OPEN.HERO_CARD));
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FLOAT_100SPIN, '点击了游戏内卡包浮窗')
    },

    showTips() {
        //解锁了才显示
        let nodeTip = cc.find('spr_tip', this.node)

        if (nodeTip.scale && nodeTip.active) {
            return
        }

        nodeTip.scale = 0
        nodeTip.active = true
        cc.tween(nodeTip)
            .to(0.3, { scale: 1 }, { easing: 'backOut' })
            .delay(3)
            .to(0.2, { scale: 0 })
            .start()
    },

