/**
 * bonus activity sign
 */

cc.Class({
    extends: cc.Component,

    properties: {
        atlas: cc.SpriteAtlas,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this.giftsNode = cc.find('giftsNode', this.node)

        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SIGN_INFO, this.onRcvGetSignInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_SIGN_ACTION, this.onRcvGetSignAction, this);
        // let btn_collect = cc.find("btn_collect",this.node)
        // Global.btnClickEvent(btn_collect, this.onClickCollect, this)
        // let btn_check = cc.find("btn_check",this.node)
        // Global.btnClickEvent(btn_check, this.onClickCheck, this)

        for (let i = 1; i <= 7; i++) {
            let itemNode = cc.find("day" + i, this.node)
            Global.btnClickEvent(itemNode, this.onClickCollect, this)
        }
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SIGN_INFO, this.onRcvGetSignInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_SIGN_ACTION, this.onRcvGetSignAction, false, this);
    },

    start() {
        this.sendGetSignInfo()
    },

    sendGetSignInfo() {
        var req = { 'c': MsgId.REQ_GET_SIGN_INFO };
        cc.vv.NetManager.sendAndCache(req);
    },

    initGift(giftData) {
        let bFirst = -1
        for (let i = 0; i < this.giftsNode.children.length; i++) {
            this.giftsNode.children[i].getComponent('Signin_gift').initItem(giftData[i].prize)
            let doneNode = cc.find(cc.js.formatStr("lay_num/item%s/done", i + 1), this.node)
            let lbl_val = cc.find(cc.js.formatStr("lay_num/item%s/lbl", i + 1), this.node)
            let bCanGet = giftData[i].can
            doneNode.active = bCanGet
            lbl_val.active = !bCanGet
            let bCollect = this.allCollectDays > giftData[i].day
            this.giftsNode.children[i].getComponent('Signin_gift').setCanGetGift(!bCollect)
            // if (!giftData[i].can) {
            //     if(bFirst == -1){
            //         this.giftsNode.children[i].getComponent('Signin_gift').setCanGetGift(bCollect)
            //         bFirst = i
            //     }

            // }
        }
    },

    initGiftProgress: function (val, bAni, aniEndCall) {
        let nPer = val / 30
        let proNode = cc.find("pro", this.node)
        let proCmp = proNode.getComponent(cc.ProgressBar)
        if (bAni) {
            cc.tween(proCmp)
                .to(1, { progress: nPer })
                .call(() => {
                    if (aniEndCall) aniEndCall()
                })
                .start()
        }
        else {
            proNode.getComponent(cc.ProgressBar).progress = nPer
        }


    },

    initToday: function (days, count) {

        //设置每天的奖励
        for (let kIdx = 0; kIdx < days.length; kIdx++) {
            let itemDay = cc.find("day" + (kIdx + 1), this.node)
            if (itemDay) {
                //奖励
                let today = count - 1
                let itemData = days[kIdx]
                for (let i = 0; i < itemData.prize.length; i++) {
                    let item = cc.find("rewards/icon" + (i + 1), itemDay)
                    let prize = itemData.prize[i]
                    if (prize) {
                        item.active = true
                        if (prize.type == Global.PROP_ID.BINGO_BALL) {
                            if (cc.vv.UserManager.getOpenActiveType() == 2) {  //配置的是bingo,然而开的游戏是骑士就替换下显示
                                prize.type = Global.PROP_ID.EXPLORE_DICE
                            }

                        }

                        cc.find("spr", item).getComponent('CH_RewardItem').init(prize.type, prize.count, true, true)
                    }
                    else {
                        item.active = false
                    }
                }
                let bSigin = false
                if (kIdx < today || (kIdx == today && this.isGetSignFlag)) {
                    //已经签过了
                    bSigin = true
                }
                let node_done = cc.find("node_done", itemDay)
                node_done.active = bSigin

                let bCanSign = !bSigin && kIdx == today
                itemDay.getComponent(cc.Button).interactable = bCanSign || (kIdx > today && this.isGetSignFlag)

                //可以签到的光效
                if (kIdx == today) {
                    let node_frame = cc.find("sign_frame_ani", this.node)
                    node_frame.active = bCanSign
                    if (node_frame.active) {
                        node_frame.x = itemDay.x
                        node_frame.y = itemDay.y
                        let aniName = "animation1"
                        if (today == 6) {
                            aniName = "animation2"
                        }
                        node_frame.getComponent(sp.Skeleton).setAnimation(0, aniName, true)
                    }
                }

            }
        }

        // //title
        // let title = cc.find("day/title",this.node)
        // title.getComponent(cc.Sprite).spriteFrame = this.atlas.getSpriteFrame('day'+count)


        // let btn_collect = cc.find("btn_collect",this.node)
        // let btn_check = cc.find("btn_check",this.node)
        // btn_collect.active = !this.isGetSignFlag
        // btn_check.active = this.isGetSignFlag

    },

    onRcvGetSignInfo: function (msg) {
        if (msg.code == 200) {
            this._signInfo = msg
            this.isGetSignFlag = msg.signFlag
            this.allCollectDays = msg.signTimes + 1
            this.signTodayCount = msg.signCount

            //top
            this.initGift(msg.pack)
            this.initGiftProgress(msg.signTimes)
            //today
            this.initToday(msg.signData, this.signTodayCount)
        }
    },

    onClickCheck: function () {
        let url = "hall_prefab/SignIn"
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find("Canvas")
            }
        })
    },

    onClickCollect: function () {
        if (this.isGetSignFlag) {
            cc.vv.FloatTip.show("Today's rewards has been claimed.")
        }
        else {
            this.sendGetSignAction()
        }

    },

    sendGetSignAction() {
        var req = { 'c': MsgId.REQ_GET_SIGN_ACTION };
        cc.vv.NetManager.send(req);
    },

    onRcvGetSignAction: function (msg) {
        if (msg.code == 200) {
            cc.vv.RedSys.clearRedTip(5)
            if (msg.spcode) {

                return
            }
            this._activityRewards = msg.srewards
            //更新数据
            this.isGetSignFlag = 1
            this.signTodayCount = msg.curSignCount

            //显示奖励
            //let rd = msg.rewards
            //this._showItemRewards(rd)
            let srcObj = cc.find("day" + this.signTodayCount, this.node)
            let pos = srcObj.convertToWorldSpaceAR(cc.v2(0, 0))
            Global.RewardFly(msg.rewards, pos, () => {
                this.checkDaiyActiveRewards()
            })
        }
    },


    _showItemRewards(rewards, typeWhere) {
        //金币直接飞，物品弹出显示
        let coin = 0
        let tempItems = []
        for (let i = 0; i < rewards.length; i++) {
            if (rewards[i].type == Global.PROP_ID.COIN) {
                coin = rewards[i].count
            }
            else {
                tempItems.push(rewards[i])
            }
        }
        if (coin) {
            let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
            let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
            if (cc.vv.gameData) {
                toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
                endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
            }

            let rollData = {}
            rollData.lblCoin = toLbl
            rollData.addCoin = coin
            let srcObj
            if (typeWhere == 2) {
                //活跃度奖励
                let nIdx = this.getBoxGiftIdx(this.allCollectDays)
                srcObj = cc.find("giftsNode/gifts" + nIdx, this.node)
            }
            else {
                srcObj = cc.find("day/rewards/icon1", this.node)
            }


            Global.FlyCoin(srcObj, endNode, () => {


                if (cc.vv.gameData) {
                    cc.vv.gameData.AddCoin(coin)
                    cc.vv.gameData.RefushMyCoin()
                }

                if (tempItems.length > 0) {
                    this.loadPopReward(tempItems, typeWhere)
                }
            }, rollData, true)
        }
        else {
            if (tempItems.length > 0) {
                this.loadPopReward(tempItems, typeWhere)
            } else {
                this.checkDaiyActiveRewards()
            }
        }

    },

    loadPopReward(rdArr, typeWhere) {


        let self = this
        let nextCall = function () {
            if (typeWhere != 2) {
                self.checkDaiyActiveRewards()
            }
        }
        cc.vv.UserManager.loadPopReward(rdArr, nextCall)
    },

    checkDaiyActiveRewards: function () {

        this.initToday(this._signInfo.signData, this.signTodayCount)
        this.initGiftProgress(this.allCollectDays, true, () => {
            if (this._activityRewards && this._activityRewards.length > 0) {
                //this._showItemRewards(this._activityRewards,2)
                let nIdx = this.getBoxGiftIdx(this.allCollectDays)
                let srcObj = cc.find("giftsNode/gifts" + nIdx, this.node)
                let pos = srcObj.convertToWorldSpaceAR(cc.v2(0, 0))
                Global.RewardFly(this._activityRewards, pos)
            }
        })
    },

    getBoxGiftIdx: function (day) {
        let res = Math.floor(day / 7)
        return res
    },

    // update (dt) {},
});
