/**
 * 在线奖励
 */
let PRO_MUL = {
    MUL_1: 1,
    MUL_2: 2,
    MUL_3: 3,
    MUL_4: 4,
    MUL_5: 5,
    MUL_10: 10,
};

let PRO_DATA = [
    [0, 55],
    [55, 177],
    [177, 408],
    [408, 909],
    [909, 2000],
    [2000],
];

let PRO_LEN = [
    [0, 134],
    [134, 280],
    [280, 426],
    [426, 572],
    [572, 698],
    [698, 824],
];

cc.Class({
    extends: cc.Component,

    properties: {
        _award_turbo: null,     //'turbo'奖励
        _award_instant: null,   //'instant'奖励
        _selectType: '',      //点击领取的类型 'instant'-时间短的 'turbo'-时间长的
        _resetTime: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._lbl_time_turbo = cc.find('node_center/node_scratch/spr_time_bg/lbl_time', this.node);
        this._spine = cc.find('spine', this.node)
        this._cha = cc.find("cha", this.node);
        this._lbl_val = cc.find('lbl_spin_val', this.node);
        this._lbl_reset_time = cc.find("node_center/node_mult/lbl_time", this.node);
        this._node_prize = cc.find('node_result/node_prize', this.node);
        this._node_prize.active = false;
        // this._btn_info = cc.find('node_center/node_scratch/btn_info',this.node);
        cc.vv.NetManager.registerMsg(MsgId.REQ_ONLINE_REWARDS, this.onRcvOnlineRewards, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_ONLINE_COIN, this.onRcvGetOnlineCoin, this);
        //btn place quest
        let btn_quest = cc.find("node_center/node_palac/btn_go", this.node)
        Global.btnClickEvent(btn_quest, this.onClickGoPlace, this)
        this._award_turbo = {};
        this._award_instant = {};
        Global.playComEff("ch_popup");
        this._node_bg = cc.find("node_result/node_bg", this.node);
        this._node_bg.getComponent(cc.Button).interactable = false;
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_ONLINE_REWARDS, this.onRcvOnlineRewards, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_ONLINE_COIN, this.onRcvGetOnlineCoin, false, this);
    },

    start() {
        Global.showAlertAction(this.node, true, 0.1, 1, null)
        this.sendEnterReq()
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FRIENZY_COLLECT)
    },

    getDesignSpaceX() {
        return 440;
    },

    setAutoCollect: function (val) {
        this._bAutoCollect = val
    },

    sendEnterReq: function () {
        var req = { 'c': MsgId.REQ_ONLINE_REWARDS };
        req.uid = Global.playerData.uid;
        req.rtype = 1;
        cc.vv.NetManager.send(req);
    },

    //发送领取奖励协议
    sendGetReq: function () {
        var req = { 'c': MsgId.REQ_GET_ONLINE_COIN };
        req.uid = Global.playerData.uid;
        req.rtype = 1;
        cc.vv.NetManager.send(req);
    },

    initShow: function () {
        let _lbl_coin_turbo = cc.find('node_center/node_scratch/spr_win_bg/lbl/lbl_coin', this.node);
        _lbl_coin_turbo.getComponent(cc.Label).string = Global.FormatNumToComma(this._award_turbo.coinPool);
        this.showDiscountTime(this._lbl_time_turbo, this._award_turbo.remainTime);
        this.showSpin(this._award_turbo.remainTime)
        //是否有富豪庭加成
        let node_palace = cc.find('node_center/node_palac', this.node)
        let icon = cc.find('icon', node_palace)
        let bActive = this._hall_palace ? true : false
        Global.showSpriteGray(icon, !bActive)
        let lbl = cc.find('lbl', node_palace)
        lbl.color = bActive ? cc.Color(255, 255, 255) : cc.Color(125, 125, 125)
    },

    onRcvOnlineRewards: function (msg) {
        if (msg.code === 200) {
            if (!cc.isValid(this.node)) return
            this._hall_palace = msg.palaceMult
            for (let key in msg) {
                let idx = key.indexOf('award_');
                if (idx >= 0) {
                    this._award_turbo = eval('msg.' + key);
                    let idx = key.lastIndexOf('_');
                    let t = key.substr(idx + 1);
                    this._turboTime = parseInt(t);
                    this._resetTime = this._award_turbo.resetTime;
                    break;
                }
            }
            this.initShow();
            this._curMultAdd = msg.mult
            this.showCurMult(msg.mult, msg.percent)
            if (this._bAutoCollect) {
                this._doCollectAction()
                this._bAutoCollect = null
            }
        }
    },

    //显示当前倍率
    showCurMult: function (nMul, nPro) {
        let _maskPro = cc.find('node_center/node_mult/prog', this.node)
        let _spinLeft = cc.find('node_center/spin_left', this.node)
        _spinLeft.active = nMul != PRO_MUL.MUL_10
        if (nMul == PRO_MUL.MUL_10) {
            _maskPro.width = PRO_LEN[PRO_LEN.length - 1][1]
        } else {
            //长度设置
            let off = PRO_LEN[nMul - 1][1] - PRO_LEN[nMul - 1][0]
            _maskPro.width = Math.floor(off * nPro / 100) + PRO_LEN[nMul - 1][0]
            //数量设置
            off = PRO_DATA[nMul - 1][1] - PRO_DATA[nMul - 1][0]
            cc.find('times', _spinLeft).getComponent(cc.Label).string = off - Math.floor(off * nPro / 100)
        }
    },

    onRcvGetOnlineCoin: function (msg) {
        if (msg.code === 200) {
            this._resultMsg = msg
            let addCoin = msg.addCoin;//抽到的
            this._AddCoin = addCoin
            this._otherCoin = msg.otherCoin
            let otherCoin = msg.otherCoin//加成
            this._hall_place_add = 0
            if (this._hall_palace) {
                this._hall_place_add = this._AddCoin * this._hall_palace
            }
            let totalCoin = msg.coin
            cc.vv.UserManager.coin = totalCoin
            let vipMulAdd = addCoin
            if (this._curMultAdd) {
                vipMulAdd = addCoin / this._curMultAdd
            }
            this._lbl_val.getComponent(cc.Label).string = Global.FormatNumToComma(vipMulAdd)
            let lblTotal = cc.find('node_result/node_prize/lbl_prize', this.node)
            lblTotal.getComponent(cc.Label).string = Global.FormatNumToComma(addCoin + otherCoin - this._hall_place_add)
            let lblOther = cc.find('node_result/node_prize/lbl_bounus', this.node)
            lblOther.getComponent(cc.Label).string = Global.FormatNumToComma(otherCoin - this._hall_place_add)
            let lblscratch = cc.find('node_result/node_prize/lbl_scratch', this.node)
            lblscratch.getComponent(cc.Label).string = Global.FormatNumToComma(addCoin)
            let vipLen = 8
            for (let i = 0; i < vipLen; i++) {
                let addValLbl = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/lbl_add', i), this.node)
                let showStr = cc.js.formatStr('+%s%', msg.vipList[i] * 100)
                if (i == vipLen - 1) {
                    showStr = "GET\nMORE"
                }
                if (addValLbl) {
                    addValLbl.getComponent(cc.Label).string = showStr
                }
                let selImg = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/spr_sel', i), this.node)
                let selImg1 = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/spr_sel%s', i, i), this.node)
                //lbl_add
                let lbl_add = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/lbl_add', i), this.node);
                if (lbl_add && i == msg.svip) {
                    lbl_add.color = cc.Color.WHITE;
                    console.log("设置颜色为白色")
                } else if (i > msg.svip) {
                    console.log("大于当前的设置颜色为深绿色色")
                    lbl_add.color = cc.color(0, 211, 143, 255);
                }
                if (selImg) {
                    selImg.active = (i == msg.svip)
                    selImg1.active = (i == msg.svip)
                    //选中背景不让他闪烁
                    // if(selImg.active){
                    //     cc.tween(selImg)
                    //     .repeatForever(
                    //         cc.tween()
                    //         .to(0.8,{opacity:80})
                    //         .to(0.8,{opacity:255})
                    //         )
                    //     .start()
                    // }
                }
                let bounsTitle = cc.find(cc.js.formatStr('node_result/node_prize/node_vip_bouns/spr_bouns_v%s', i), this.node)
                if (bounsTitle) {
                    bounsTitle.active = (i == msg.svip)
                }
            }
            //
            this.showScratch()
            //标记位已经刮奖了
            this._isScratched = true;
            //如果没有可领取的就清理小红点
            let btnCollect = cc.find('node_center/node_scratch/btn_collect', this.node)
            if (btnCollect.active == false) {
                cc.vv.RedSys.clearRedTip(1)
            }
            cc.vv.PlatformApiMgr.KoSDKTrackEvent('FrienzyReward', JSON.stringify({ uid: Global.playerData.uid }))
            Global.dispatchEvent(EventId.HEROPALACE_REFUSH)
        }
    },

    //显示我手动调用奖励结果ui
    showMyselfPrize: function () {
        Global.playEff(Global.SOUNDS.sound_pick)
        if (this._isClicked || this._isPlay) {
            return
        }
        this._isClicked = true;
        let nodeResult = this.node.getChildByName('node_result')
        nodeResult.active = true
        this._node_prize.active = true;
        this._node_prize.y = -1367
        cc.tween(this._node_prize)
            .to(0.5, { position: cc.v2(0, -80) })//显示奖励结果从下方移动过来的距离
            .call(() => {
                Global.playEff(Global.SOUNDS.sound_celebration);
                this._isClicked = false;
                console.log("动作的call回调函数，此时_isClicked等于false")
                this._node_bg.getComponent(cc.Button).interactable = true;
            })
            .start()
        // this.sendGetReq();
        let lblTotal = cc.find('node_result/node_prize/lbl_prize', this.node)
        lblTotal.getComponent(cc.Label).string = 0;
        let lblOther = cc.find('node_result/node_prize/lbl_bounus', this.node)
        lblOther.getComponent(cc.Label).string = 0;
        let lblscratch = cc.find('node_result/node_prize/lbl_scratch', this.node)
        lblscratch.getComponent(cc.Label).string = 0;
        let vipLen = 8
        for (let i = 1; i < vipLen; i++) {
            if (i == vipLen - 1) {
                let showStr = "GET\nMORE"
                let addValLbl = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/lbl_add', vipLen - 1), this.node)
                if (addValLbl) {
                    addValLbl.getComponent(cc.Label).string = showStr
                }
            }
            let selImg = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/spr_sel', i), this.node)
            let selImg1 = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/spr_sel%s', i, i), this.node)
            let lbl_add = cc.find(cc.js.formatStr('node_result/node_prize/spr_vip%s/lbl_add', i), this.node);
            lbl_add.color = cc.color(0, 152, 114, 255);//还原为初始颜色
            if (selImg && selImg1) {
                selImg.active = false
                selImg1.active = false
            }
            let bounsTitle = cc.find(cc.js.formatStr('node_result/node_prize/node_vip_bouns/spr_bouns_v%s', i), this.node)
            if (bounsTitle) {
                bounsTitle.active = false
            }
        }
        let bounsTitle0 = cc.find(cc.js.formatStr('node_result/node_prize/node_vip_bouns/spr_bouns_v%s', 0), this.node)
        bounsTitle0.active = true;
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_FRIENZY_QUESTMASK)
    },

    //显示奖励结果
    showPrize: function () {
        Global.playEff(Global.SOUNDS.sound_pick)
        let nodeResult = this.node.getChildByName('node_result')
        nodeResult.active = true
        let icon_palace = cc.find("icon_place", this._node_prize)
        icon_palace.active = false
        this._node_prize.active = true;
        this._node_prize.y = -1367
        if (this._hall_place_add > 0) {
            //有富豪庭加成
            cc.tween(this._node_prize)
                .to(0.5, { position: cc.v2(0, -80) })//显示奖励结果从下方移动过来的距离
                .delay(0.1)
                .call(() => {
                    let icon_palace = cc.find("icon_place", this._node_prize)
                    icon_palace.scale = 2
                    icon_palace.active = true
                    cc.tween(icon_palace)
                        .to(0.2, { scale: 0.6 }, { easing: "backOut" })
                        .start()
                    let lbl1 = cc.find("lbl_bounus", this._node_prize)
                    Global.doRoallNumEff(lbl1, this._otherCoin - this._hall_place_add, this._otherCoin, 0.3, null, null, 0, true)
                    let lbl2 = cc.find("lbl_prize", this._node_prize)
                    Global.doRoallNumEff(lbl2, this._AddCoin + this._otherCoin - this._hall_place_add, this._AddCoin + this._otherCoin, 0.3, null, null, 0, true)
                })
                .delay(0.3)
                .call(() => {
                    Global.playEff(Global.SOUNDS.sound_celebration);
                    //自动调用领奖接口
                    this.onClickConfirmBtn();
                })
                .start()
        }
        else {
            cc.tween(this._node_prize)
                .to(0.5, { position: cc.v2(0, -80) })//显示奖励结果从下方移动过来的距离
                .call(() => {
                    Global.playEff(Global.SOUNDS.sound_celebration);
                    //自动调用领奖接口
                    this.onClickConfirmBtn();
                })
                .start()
        }
        // let btn = this._node_prize.getChildByName('btn_confirm')
        // btn.getComponent(cc.Button).interactable = true
        let nTime = this._turboTime * 60
        this.showDiscountTime(this._lbl_time_turbo, nTime);
    },

    //显示倒计时
    showDiscountTime: function (node, discountTime) {
        if (node) {
            Global.dispatchEvent(EventId.REFUSH_BONUS_ONLINE_TIME, discountTime)
            let _btn_colltct = node.parent.parent.getChildByName('btn_collect');
            if (discountTime === 0) {
                node.parent.active = false;
                _btn_colltct.active = true;
                _btn_colltct.getComponent(cc.Button).interactable = true
            } else {
                node.parent.active = true;
                _btn_colltct.active = false;
                // this._btn_info.getComponent(cc.Button).interactable = true
                var self = this;
                let labelCmp = node.getComponent(cc.Label)
                this.callback = function () {
                    labelCmp.string = Global.formatSec(discountTime);
                    if (discountTime <= 0) {
                        labelCmp.unscheduleAllCallbacks();
                        node.parent.active = false;
                        _btn_colltct.active = true;
                        //重新刷新一下界面
                        self.sendEnterReq()
                    }
                    --discountTime;
                };
                labelCmp.schedule(this.callback, 1)
                this.callback()
            }
        }
    },

    //点击collect按钮
    onClickCollect: function (event, data) {
        Global.playComEff("ch_btn_click");
        if (this._isClicked || this._isPlay) {
            //有在播放的
            return
        }
        this._isPlay = true
        event.target.getComponent(cc.Button).interactable = false
        this._doCollectAction()
    },

    _doCollectAction() {
        // this._btn_info.getComponent(cc.Button).interactable = false
        this._selectType = 'turbo';
        this.sendGetReq();
        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_SCRATCH, bInGame)
    },

    //刮奖以后自动飞金币
    onClickConfirmBtn: function () {
        Global.playComEff("ch_collect");
        this._isPlay = false
        let endCall = function () {
            Global.dispatchEvent(EventId.UPATE_COINS)
        }
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
        rollData.addCoin = this._otherCoin + this._AddCoin
        //飞金币
        let srcObj = cc.find('node_result/node_prize/lbl_prize', this.node)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        Global.FlyCoin(srcObj, endNode, endCall, rollData, true)
        //领奖金币飞完之后在让可点击关闭
        this._node_bg.getComponent(cc.Button).interactable = true;
        Global.dispatchEvent(EventId.REFUSH_HALL_BONUS_LIST)
    },

    //点击奖励页面confirm按钮
    onClickConfirm: function (event) {
        Global.playComEff("ch_collect");
        let self = this
        this._isPlay = false
        event.target.getComponent(cc.Button).interactable = false
        let endCall = function () {

            Global.dispatchEvent(EventId.UPATE_COINS)
            self.hitResultUI()
        }
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH);
        rollData.addCoin = this._otherCoin + this._AddCoin
        //飞金币
        let srcObj = cc.find('node_result/node_prize/lbl_prize', this.node)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        Global.FlyCoin(srcObj, endNode, endCall, rollData, true)
    },

    //关闭
    onClickClose: function () {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_SCRATCH_CLOSE)
        Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
        if (this._isPlay) return
        Global.playComEff("ch_close");
        Global.dispatchEvent(EventId.UPATE_COINS)
        this.node.destroy();
    },

    onCloseResultUI: function () {
        let self = this
        this._node_bg.getComponent(cc.Button).interactable = false;
        if (this._isClicked) {
            return
        }
        if (this._isScratched) {
            let spCmp = this._spine.getComponent(sp.Skeleton)
            spCmp.timeScale = Global.ANIM_TIMESCALE_X2
            spCmp.setAnimation(0, "animation1_6", false);
            spCmp.addAnimation(0, "animation1_1", true);
            this._cha.active = false;
            this._lbl_val.active = false;
            //翻转一次动画以后置为false
            this._isScratched = false;
        }
        cc.tween(this._node_prize)
            .to(0.4, { position: cc.v2(0, -1367) })
            .call(() => {
                self._node_prize.active = false;
                self._node_prize.parent.active = false;
            })
            .start()
    },

    //显示spin状态
    showSpin: function (remindTime) {
        if (this._spine) {
            let bShowAni = 'animation1_1'
            if (remindTime == 0) { //可以领取
                bShowAni = 'animation1_2'
            }
            let spCmp = this._spine.getComponent(sp.Skeleton)
            spCmp.timeScale = Global.ANIM_TIMESCALE_X2
            spCmp.setAnimation(0, bShowAni, true)
        }
    },

    showScratch: function () {
        if (this._spine) {
            let spCmp = this._spine.getComponent(sp.Skeleton)
            spCmp.timeScale = Global.ANIM_TIMESCALE_X2
            spCmp.setAnimation(0, 'animation1_3', false)
            spCmp.addAnimation(0, 'animation1_4', false)
            spCmp.setCompleteListener(this.AniEndCall.bind(this))
        }
    },

    AniEndCall: function (trackEntry, data2) {
        let name = trackEntry.animation ? trackEntry.animation.name : '';
        console.log(name)
        if (name == 'animation1_4') {
            this.showMidSpin()
        }
    },

    //刮奖过程
    showMidSpin: function (ani) {
        let self = this
        this._lbl_val.active = true
        this._lbl_val.opacity = 255
        this._cha.active = true
        let spCmp = this._spine.getComponent(sp.Skeleton)
        spCmp.timeScale = Global.ANIM_TIMESCALE_X2
        spCmp.setAnimation(0, 'animation1_5', false)
        let chaAni = this._cha.getComponent(sp.Skeleton)
        chaAni.timeScale = Global.ANIM_TIMESCALE_X2
        chaAni.setAnimation(0, 'animation1', false)
        chaAni.addAnimation(0, 'animation2', false, 1)
        chaAni.setCompleteListener(this.midAniEndCall.bind(this))
        chaAni.setStartListener(this.chaAniStartCall.bind(this))
        //倍率砸下来
        if (this._curMultAdd >= 2) {
            let delay = function () {
                self.showAddMultIn()
            }
            this.scheduleOnce(delay, 0.2)
        }
    },

    chaAniStartCall: function (trackEntry, data2) {
        let name = trackEntry.animation ? trackEntry.animation.name : '';
        if (name == 'animation2') {
            Global.playEff(Global.SOUNDS.sound_scratch)
        }
    },

    midAniEndCall: function (trackEntry, data2) {
        let name = trackEntry.animation ? trackEntry.animation.name : '';
        if (name == 'animation2') {
            //显示倍率加成
            if (this._curMultAdd >= 2) {
                this.showAddMultOut(this.showPrize.bind(this))
            } else {
                //显示结果界面
                this.showPrize()
            }
        }
    },

    hitResultUI: function () {
        let self = this
        let spCmp = this._spine.getComponent(sp.Skeleton)
        spCmp.timeScale = Global.ANIM_TIMESCALE_X2
        spCmp.setAnimation(0, "animation1_6", false);
        spCmp.addAnimation(0, "animation1_1", true);
        this._cha.active = false;
        this._lbl_val.active = false;
        cc.tween(this._node_prize)
            .to(0.4, { position: cc.v2(0, -1367) })
            .call(() => {
                self._node_prize.active = false;
                self._node_prize.parent.active = false
            })
            .start()
    },

    //显示倍率加成动画飞出去
    showAddMultOut: function (endCall) {
        let obj = cc.find('spr_mult', this.node)
        if (obj) {
            let startPos = obj.position
            let endPos = this._lbl_val.position
            let midPos = cc.v2(startPos.x - 50, endPos.y + 100)
            let bzAction = cc.bezierTo(0.6, [cc.v2(startPos.x, startPos.y), midPos, cc.v2(endPos.x, endPos.y)])
            let scaleActino = cc.scaleTo(0.6, 0)
            let sp = cc.spawn(bzAction, scaleActino)
            let acCall = cc.callFunc(() => {
                //数字滚动
                let finishCall = function () {
                    if (endCall) {
                        endCall()
                    }
                }
                let vipAdd = this._AddCoin
                if (this._curMultAdd) {
                    vipAdd = this._AddCoin / this._curMultAdd
                }
                Global.doRoallNumEff(this._lbl_val, vipAdd, this._AddCoin, 1.5, finishCall, null, 0, true)
            })
            obj.runAction(cc.sequence(sp, acCall))
        }
    },

    showAddMultIn: function () {
        let obj = cc.find('spr_mult', this.node)
        if (obj) {
            obj.active = true
            obj.position = cc.v2(270, -80)
            obj.getChildByName('lbl_val').getComponent(cc.Label).string = 'x' + this._curMultAdd
            let effNode = obj.getChildByName('node_eff')
            effNode.active = false
            obj.opacity = 100
            obj.scale = 5
            obj.stopAllActions()
            cc.tween(obj)
                .to(0.2, { opacity: 255, scale: 1 }, { easing: 'quadIn' })
                .call(() => {
                    effNode.active = true
                    let spAni = effNode.getComponent(sp.Skeleton)
                    spAni.timeScale = Global.ANIM_TIMESCALE_X2
                    spAni.setAnimation(0, 'animation', false)
                })
                .start()
        }
    },

    onClickGoPlace: function () {
        cc.vv.UserManager.goSystemUI("heropalace")
        this.node.destroy()
    },

    update(dt) {
        if (this._resetTime > 0) {
            this._resetTime -= dt;
            if (this._resetTime < 0) {
                this._resetTime = 86400;
                this.sendEnterReq();
            } else {
                this._lbl_reset_time.getComponent(cc.Label).string = Global.formatSec(this._resetTime);
            }
        }
    },
});
