
const SILVER_EGG = 1
const GOLD_EGG = 2

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _data: null,
        _leftTime: 0,
        _status: 0,  //0:非砸蛋日  1：砸蛋日
        _disableTime: 0,
        _lblTime: null,
        _interval: 0,
        _refresh: false,
    },

    onLoad() {
        // Global.FixDesignScale_V(this.node)
        this._lblTime = cc.find("lay_des/time_bg/lbl_time", this.node).getComponent(cc.Label)

        let btnHelp = cc.find("btn_help", this.node)
        btnHelp.on('click', this.onClickHelp, this)

        let btnPlaySilver = cc.find("silver/btn_play", this.node)
        btnPlaySilver.on('click', this.onClickPlaySilver, this)
        // btnPlaySilver.active = false

        let btnPlayGold = cc.find("gold/btn_play", this.node)
        btnPlayGold.on('click', this.onClickPlayGold, this)
        // btnPlaySilver.active = false

        let btnClose = cc.find("btn_close", this.node)
        if (btnClose) {
            Global.btnClickEvent(btnClose, this.onClickClose, this)
        }

        let btnGetSilver = cc.find("silver/tips", this.node)
        Global.btnClickEvent(btnGetSilver, this.onClickGetSilver, this)

        let btnGetGold = cc.find("gold/tips", this.node)
        Global.btnClickEvent(btnGetGold, this.onClickGetGold, this)


        cc.vv.NetManager.registerMsg(MsgId.REQ_LUCKYSMASH_INFO, this.onRcvNetLucksmashInfo, this)
        Global.registerEvent("REFRESH_LUCKYSMASH_HUMMER", this.onRcvEvtRefreshHummer, this);

        this.requestData()

        Global.registerEvent(EventId.COMM_ITEM_ADD, this.onEventItemChange, this)

        this._completeSmash = false

        StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_POP)
    },

    getSecond() {
        return (new Date().getTime()) / 1000
    },

    onEnable() {    //补偿update停止期间的时间差
        this._super()
        if (this._disableTime > 0) {
            let dt = this.getSecond() - this._disableTime
            this._leftTime -= dt
            this._disableTime = 0
        }
        if (this._refresh) {
            this.requestData()
        }
    },

    onDisable() {
        this._super()
        this._disableTime = this.getSecond()
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_LUCKYSMASH_INFO, this.onRcvNetLucksmashInfo, false, this)
    },

    start() {
        let btnGetGold = cc.find("gold/tips", this.node)
        let btnGetSilver = cc.find("silver/tips", this.node)

        btnGetGold.scale = 0
        btnGetSilver.scale = 0

        cc.tween(btnGetSilver)
            .delay(0.3)
            .to(0.2, { scale: 1 }, { easing: "backOut" })
            .start()

        cc.tween(btnGetGold)
            .delay(0.35)
            .to(0.2, { scale: 1 }, { easing: "backOut" })
            .start()
    },

    onEventItemChange: function (data) {
        let val = data.detail
        if (val && val.id == Global.PROP_ID.GLOD_HUMER) {
            //在任务界面完成任务后收到金锤子
            this.setHummer(GOLD_EGG, this._data.hammers[1] + val.num)
        }
    },

    update(dt) {
        this._interval += dt
        if (this._interval < 0.25) return  //控制刷新率

        this._leftTime -= this._interval
        this._interval = 0
        if (this._status == 1) {
            if (this._leftTime <= 0) {
                //切换状态并刷新数据
                this._status = 0
                this.requestData()
            } else {
                this.showLeftTime(this._leftTime)
            }
        }
    },

    onRcvEvtRefreshHummer() {
        this._refresh = true
    },

    requestData() {
        this._refresh = false
        let req = { c: MsgId.REQ_LUCKYSMASH_INFO };
        cc.vv.NetManager.send(req);
    },

    onRcvNetLucksmashInfo(msg) {
        if (msg.code == 200) {
            this._data = msg
            this.refreshView()
        }
    },

    showLeftTime(leftTime) {
        let _time = 0
        let leftType = cc.vv.Language.luckysmash_lefttime1
        if (leftTime > 86400) {
            let day = Math.floor(leftTime / 86400)
            if (day == 1) {
                leftType = cc.vv.Language.luckysmash_lefttime1
                // this._lblTime.string = "In "+day+" day"
            } else {
                // this._lblTime.string = "In "+day+" days"
                leftType = cc.vv.Language.luckysmash_lefttime2
            }
            _time = day
        } else {
            // this._lblTime.string = Global.formatSec(leftTime)
            _time = leftTime
            leftType = cc.vv.Language.lefttime
        }
        I18N.setI18nLabel(this._lblTime, leftType, _time)
    },

    getLeftTime() {
        return this._leftTime
    },

    getHummer(stype) {
        if (stype == SILVER_EGG) {
            return this._data.hammers[0]
        } else if (stype == GOLD_EGG) {
            return this._data.hammers[1]
        }
    },

    setHummer(stype, count) {
        if (stype == SILVER_EGG) {
            this._data.hammers[0] = count
            cc.find("silver/count_bg/lbl_count", this.node).getComponent(cc.Label).string = (count + "/7")
        } else if (stype == GOLD_EGG) {
            this._data.hammers[1] = count
            cc.find("gold/count_bg/lbl_count", this.node).getComponent(cc.Label).string = (count + "/7")
        }
    },

    setEnd(stype, is_end) {
        if (stype == SILVER_EGG) {
            this._data.is_end[0] = is_end
            cc.find("silver/rewards_bg/rewards_list", this.node).active = !is_end
            cc.find("silver/rewards_bg/completed", this.node).active = is_end
            cc.find("silver/rewards_bg/win", this.node).active = !is_end
            cc.find("silver/rewards_bg/welldone", this.node).active = is_end
            if (is_end) {
                cc.find("silver/btn_play", this.node).getComponent(cc.Button).interactable = false
                cc.find("silver/count_bg/lbl_count", this.node).getComponent(cc.Label).string = "Done"
            }
        } else if (stype == GOLD_EGG) {
            this._data.is_end[1] = is_end
            cc.find("gold/rewards_bg/rewards_list", this.node).active = !is_end
            cc.find("gold/rewards_bg/completed", this.node).active = is_end
            cc.find("gold/rewards_bg/win", this.node).active = !is_end
            cc.find("gold/rewards_bg/welldone", this.node).active = is_end
            if (is_end) {
                cc.find("gold/count_bg/lbl_count", this.node).getComponent(cc.Label).string = "Done"
                cc.find("gold/btn_play", this.node).getComponent(cc.Button).interactable = false
            }
        }
    },

    getRewards(stype) {
        for (let i = 0; i < this._data.cfgs.length; i++) {
            let cfg = this._data.cfgs[i]
            if (cfg.type == stype) {
                return cfg.rewards
            }
        }
        return null
    },

    refreshView() {
        let data = this._data

        this._leftTime = data.end_time
        if (this._leftTime > 86400) {  //非砸蛋日
            this._status = 0
        } else {
            this._status = 1
        }
        this.showLeftTime(this._leftTime)
        cc.find("title1", this.node).active = (this._status == 0)
        cc.find("title2", this.node).active = (this._status == 1)
        // cc.find("silver/btn_play", this.node).getComponent(cc.Button).interactable = (this._status == 1) //砸蛋日且未砸完
        // cc.find("gold/btn_play", this.node).getComponent(cc.Button).interactable = (this._status == 1)    //砸蛋日且未砸完
        cc.find("lay_des", this.node).active = (this._status == 0)
        cc.find("silver/tips", this.node).active = (this._status == 0)
        cc.find("gold/tips", this.node).active = (this._status == 0)

        this.setHummer(SILVER_EGG, data.hammers[0])
        this.setHummer(GOLD_EGG, data.hammers[1])
        this.setEnd(SILVER_EGG, data.is_end[0])
        this.setEnd(GOLD_EGG, data.is_end[1])

        if (data.is_end[0] && data.is_end[1]) {
            this._completeSmash = true
            Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
        }

        //奖励列表
        this.showRewardList(cc.find("silver/rewards_bg/rewards_list", this.node), this.getRewards(SILVER_EGG))
        this.showRewardList(cc.find("gold/rewards_bg/rewards_list", this.node), this.getRewards(GOLD_EGG))
    },

    _getHeroCount(rd) {
        let count = 0
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.HERO_CARD) {
                count += rd[i].count
            }
        }
        return count
    },

    showRewardList(node, rewards) {
        let heroCount = this._getHeroCount(rewards)

        for (let i = 0; i < rewards.length; i++) {
            let reward = rewards[i]
            if (reward.type == Global.PROP_ID.COIN) {
                cc.find("item_coin/lbl_count", node).getComponent(cc.Label).string = Global.formatNumShort(reward.count, 0)
            } else if (reward.type == Global.PROP_ID.VIP_POINT) {
                cc.find("item_vip/lbl_count", node).getComponent(cc.Label).string = "" + reward.count
            } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                cc.find("item_exp/lbl_count", node).getComponent(cc.Label).string = reward.count + 'H'
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                cc.find("item_package/lbl_count", node).getComponent(cc.Label).string = 'X' + heroCount
            }
        }
    },

    onClickHelp() {
        Global.playComEff("ch_btn_click");
        cc.loader.loadRes("CashHero/prefab/lucky_smash/lucky_help", cc.Prefab, (err, prefab) => {
            let canvas = cc.find("Canvas")
            if (!err && !canvas.getChildByName("lucky_help")) {
                let node = cc.instantiate(prefab)
                node.name = "lucky_help"
                node.parent = canvas

                StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_RULE)
            }
        })
    },

    onClickPlaySilver() {
        Global.playComEff("ch_btn_click");
        if (!this._data) return
        if (this._status == 1) {
            this.loadLuckyCrush(SILVER_EGG)


        }
        else {
            cc.vv.FloatTip.show("Saturday is the lucky day");
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_SLIVER_POP)

    },

    onClickPlayGold() {
        Global.playComEff("ch_btn_click");
        if (!this._data) return
        if (this._status == 1) {
            this.loadLuckyCrush(GOLD_EGG)
        }
        else {
            cc.vv.FloatTip.show("Saturday is the lucky day");
        }


        StatisticsMgr.reqReport(StatisticsMgr.REQ_SMASHUI_GOLD_POP)
    },

    loadLuckyCrush(stype) {
        let name = (stype == SILVER_EGG) ? "silver" : "gold"
        cc.loader.loadRes("CashHero/prefab/lucky_smash/lucky_crush_" + name, cc.Prefab, (err, prefab) => {
            if (!err && !this.node.getChildByName("lucky_crush")) {
                let node = cc.instantiate(prefab)
                node.name = "lucky_crush"
                node.getComponent("LuckySmash_Crush").init(stype, this)
                node.parent = this.node
            }
        })
    },

    onClickClose: function () {
        this.node.destroy()
    },

    onClickGetSilver: function () {
        Global.playComEff("ch_btn_click");
        cc.vv.Shop.show("Shop_Sale")
        this.node.destroy()
    },

    onClickGetGold: function () {
        Global.playComEff("ch_btn_click");
        if (cc.vv.gameData) {
            //游戏内
            let canvas = cc.find("Canvas");
            cc.loader.loadRes("CashHero/prefab/mission/mission_frame", cc.Prefab, (err, prefab) => {
                if (!err) {
                    let old = cc.find('mission_frame', canvas)
                    if (!old) {
                        let node = cc.instantiate(prefab);
                        node.parent = canvas;
                    }
                }
            });
        }
        else {
            //大厅
            Global.dispatchEvent(EventId.GO_HALL_TAB, 3)
            Global.dispatchEvent("BONUS_TAB", "Daily")
        }
        this.node.destroy()
    },

});
