cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },



    onLoad() {
        let btnClose = cc.find("closeBtn", this.node);
        Global.btnClickEvent(btnClose, this.onClickClose, this);

        let btnCollect = cc.find("collectBtn", this.node);
        Global.btnClickEvent(btnCollect, this.onClickCollect, this);

        this.offX = 260
        this._callFunc = null

        this._canClickCloseFlag = true
    },

    init(ty, data, callFunc) {
        // console.log('init (ty, data) {：', data)

        this.rankGift = data
        if (ty == 1) {
            //从排行榜进来
            this._canClickCloseFlag = true
            // cc.find('closeBtn', this.node).active = true
            this.setCloseTipEnable(true)
            cc.find('collectBtn', this.node).active = false
            this.initItem(data)
        } else if (ty == 2 || ty == 3) {
            //从邮箱里进来
            cc.find('collectBtn', this.node).active = true
            // cc.find('closeBtn', this.node).active = false
            this._canClickCloseFlag = false
            this.setCloseTipEnable(false)
            this.initItem(data)
        }

        if (cc.isValid(callFunc)) {
            this._callFunc = callFunc
        }
    },

    setCloseTipEnable(flag) {
        cc.find('comm_pop_ui_bg/tap_close_tip', this.node).active = flag
        if (!flag) {
            cc.find('closeBtn', this.node).off('click')
        }
    },

    //数据清洗 卡牌8 全部靠后 金币第一
    dataSort(data) {
        let sorFunc = function (a, b) {
            let aVal = 0
            if (a.type == Global.PROP_ID.COIN) {
                aVal = 1
            }
            let bVal = 0
            if (b.type == Global.PROP_ID.COIN) {
                bVal = 1
            }

            if (aVal != bVal) {
                return bVal - aVal
            }
            else {
                aVal = 0
                if (a.type == Global.PROP_ID.HERO_CARD) {
                    aVal = 1
                }
                bVal = 0
                if (b.type == Global.PROP_ID.HERO_CARD) {
                    bVal = 1
                }
                if (aVal != bVal) {
                    return aVal - bVal
                }
                else {
                    return a.type < b.type
                }
            }

        }
        data.sort(sorFunc)
        return data;
    },

    initItem(rd) {
        let newRd = this.dataSort(rd)
        //奖励图标
        let itemChild = cc.find('itemArray', this.node).children
        for (let i = 0; i < itemChild.length; i++) {
            itemChild[i].active = false
            if (newRd[i]) {
                itemChild[i].active = true
                let count = newRd[i].count
                let sprNode = cc.find('spr', itemChild[i])
                sprNode.getComponent('CH_RewardItem').init(newRd[i].type, count, true, true)
            }
        }
    },

    onClickCollect() {
        cc.find("collectBtn", this.node).getComponent(cc.Button).interactable = false

        //单个弹出 多个只弹卡牌
        let rd = this.rankGift
        let rdArr = []
        if (rd.length == 1) {
            rdArr.push(rd[0])
        } else {
            for (let i = 0; i < rd.length; i++) {
                if (rd[i].type == Global.PROP_ID.COIN) {
                    if (cc.vv.gameData) {
                        cc.vv.gameData.AddCoin(rd[i].count)
                        cc.vv.gameData.RefushMyCoin()
                    } else {
                        cc.vv.UserManager.AddCoin(rd[i].count, true)
                    }
                } else if (rd[i].type == Global.PROP_ID.HERO_CARD || rd[i].type == Global.PROP_ID.FULL_CARD) {
                    rdArr.push(rd[i])
                } else {
                    Global.dispatchEvent(EventId.COMM_ITEM_ADD, { id: rd[i].type, num: rd[i].count })
                }
            }
        }

        if (rdArr.length > 0) {
            let url = 'CashHero/prefab/pop_reward'
            let self = this
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                if (!err) {
                    let node = cc.instantiate(prefab)
                    node.parent = cc.find('Canvas')
                    let endCall = function () {
                        node.destroy()
                        self.node.destroy()
                    }
                    node.getComponent('CH_popreward').showRewards(rdArr, endCall)
                }
                else {
                    console.log('未找到资源:' + url)
                }
            });
        } else {
            this.node.destroy()
        }
    },


    onClickClose() {
        if (!this._canClickCloseFlag) {
            return
        }

        if (cc.isValid(this._callFunc)) {
            this._callFunc()
        }
        this.node.destroy()
    },

    start() {

    },

    // update (dt) {},
});
