let itemsListCfg = require("GameItemCfg");

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    onLoad() {
        Global.registerEvent("checkSubFinish", this.downloadingFinish, this);
        Global.btnClickEvent(cc.find('btn', this.node), this.onClickGoGame, this)
        Global.btnClickEvent(cc.find('closeBtn', this.node), this.onClickClose, this)
        this._canEnterGame = false
    },

    start() {
        this.ShowItem()
        StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_HODEON_POP)
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
        // else {
        //     cc.vv.NewGuide.ShowGuide(113);
        // }
    },

    initGameID(gameID) {
        this._gameID = gameID
    },

    //显示item
    ShowItem: function () {
        let gameId = this._gameID

        let gameCfg = itemsListCfg[gameId]
        //item  初始化图像
        let itemNode = cc.find('slots_item', this.node)
        //icon
        let iconNode = cc.find('slot_icon', itemNode)
        let iconscp = iconNode.getComponent("CH_SlotIcon")
        iconNode.setScale(0.8)
        let bLeader = cc.vv.HerocardManager.isLeader(gameId)
        if (gameCfg && bLeader) {
            iconscp.setGameId(gameId, "animation3")
        } else {
            iconscp.setGameId(gameId)
        }

        //是否下载了    显示进度条
        let bDown = cc.vv.UserManager.isDownloadSubGame(gameId)
        let nodeDown = cc.find('node_downing', itemNode)
        nodeDown.active = false

        if (bDown) {
            //已经下载了
            if (Global.isNative()) {
                //是否是最新了
                let bUpdated = cc.vv.SubGameUpdateNode.getComponent('subGameMgr')._isAreadyNew(gameId)
                if (!bUpdated) {
                    nodeDown.active = true
                    nodeDown.getComponent('node_downing').initGameId(this._gameID)
                } else {
                    this._canEnterGame = true
                }
            }
        }
        else {
            nodeDown.active = true
            nodeDown.getComponent('node_downing').initGameId(this._gameID)
        }
    },

    downloadingFinish: function (data) {
        if (cc.isValid(this.node)) {
            let gameid = data.detail
            if (gameid == this._gameID) {
                //直接进入游戏
                this._canEnterGame = true
                if (!cc.vv.gameData) {
                    //在大厅中，直接进入游戏
                    cc.vv.GameManager.EnterGame(this._gameID)
                }
            }
        }
    },

    //进入游戏
    onClickGoGame() {
        if (!this._canEnterGame) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_wait_game_load);
            // cc.vv.FloatTip.show("Wait for a while, the game will load immediately.")
            return
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_HODEON_CONFIRM)
        cc.vv.GameManager.EnterGame(this._gameID)
    },

    onClickClose() {
        if (cc.vv.gameData) {
            //没有跳过新游戏里 引导押注
            cc.vv.gameData.ResumeSlot()
            cc.vv.NewGuide.ShowGuide(15)
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_HODEON_CLOSE)
        this.node.destroy()
    },

    // update (dt) {},
});
