
cc.Class({
    extends: cc.Component,

    properties: {
        _pool: null,
    },

    setPool(pool) {
        this._pool = pool
    },

    recycle() {
        this.node.stopAllActions()
        if (this._pool) {
            this._pool.put(this.node)
        } else {
            this.node.destroy()
        }
    }
});
