cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    onLoad() {

    },

    start() {
        Global.FixDesignScale_V(this.node)
        //监听动画执行完即销毁节点 并告诉付费转盘
        let spine = cc.find("spine", this.node)
        spine.getComponent(sp.Skeleton).setCompleteListener(() => {
            spine.getComponent(sp.Skeleton).setCompleteListener(null)
            if (this._callback) {
                this._callback()
            }
            this.node.destroy()
        })
    },

    initPop(callback) {
        if (callback) {
            this._callback = callback
        }
    },

    // update (dt) {},
});
