let StateType = {
    FirstDay: 1,
    SecondDay: 2,
};

let CoinLabelPos = {
    FirstDayPos: -97,
    SecondDayPos: -147,
};

cc.Class({
    extends: cc.Component,

    properties: {},

    onLoad() {
        Global.btnClickEvent(this.node, this.onClick, this)
        this._inter = 0
        this._timeFlag = true
        this._animInter = 0
        this._animFlag = false
    },

    start() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_START, this.OnRcvNetRefush, this)
        Global.registerEvent(EventId.CLOSE_CASHBACK, this.onEventClose, this)
        Global.registerEvent(EventId.SHOW_CASHBACK_ANIM, this.changeAnim, this)
    },

    init(msg) {
        //设置金币
        this._msgInfo = msg
        this._cashBackCoin = msg.coin
        //剩余时间
        this._leftTime = Math.ceil(((msg.expire_time * 1000) - new Date().getTime()) / 1000)
        this._setTime(this._leftTime > 0)
        //设置显示类型
        if (msg.state == StateType.SecondDay) {
            if (msg.coin > 0) {
                // this._loadCashBackPop(msg.coin)
                // this._setType(false)
                this._setTime(false)
            } else {
                this.onEventClose()
            }
        }
    },

    _loadCashBackPop(coin) {
        // cc.loader.loadRes("CashHero/prefab/cashBack/cashBack", cc.Prefab, (err, prefab) => {
        //     let canvas = cc.find("Canvas")
        //     if (!err) {
        //         let node = cc.instantiate(prefab)
        //         node.name = "cashBack"
        //         node.parent = canvas
        //         node.getComponent("cashBack").initCoin(coin)
        //     }
        // })
        let initData = function (node, data) {
            node.getComponent("cashBack").initCoin(data)
        }
        cc.vv.QueueWinMrg.addPop('cashBack', coin, { type: 1, initDataCall: initData, prefabUrl: 'CashHero/prefab/cashBack/cashBack' })
    },

    OnRcvNetRefush(msg) {
        if (msg.code == 200) {
            if (cc.isValid(msg.cashBackInfo)) {
                this._msgInfo = msg.cashBackInfo
                this.changeAnim()
                let addVal = msg.cashBackInfo.coin - this._cashBackCoin
                if (addVal > 0) {
                    this._floatAddVal(addVal)
                }
                this._cashBackCoin = msg.cashBackInfo.coin
            }
        }
    },

    _setTime(flag) {
        this._timeFlag = flag
        cc.find('label', this.node).active = flag
        if (flag) {
            this.changeTime()
        } else {
            cc.find('frame', this.node).active = false
            cc.find("spr_collect", this.node).active = true
        }
    },

    changeTime() {
        let _str = Global.formatSec(this._leftTime)
        Global.setLabelString("label", this.node, _str)
    },

    onClick() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_CASHBACKWALLET_CLICK)
        let self = this
        Global.playComEff("ch_btn_click");
        // cc.loader.loadRes("slots_common/SlotRes/prefab/LMSlots_OL_CashWallet",cc.Prefab, (err, prefab) => {
        //     if (!err && cc.isValid(self.node,true)) {
        //         let old = self.node.getChildByName('LMSlots_OL_CashWallet')
        //         if(!old){
        //             let node = cc.instantiate(prefab);
        //             node.name = 'LMSlots_OL_CashWallet'
        //             let parentNode = self.node.parent.parent
        //             node.parent = parentNode;
        //             let pos = self.node.convertToWorldSpaceAR(cc.v2(0,0))
        //             let tempPos = parentNode.convertToNodeSpaceAR(pos)
        //             node.position = cc.v2(tempPos.x,tempPos.y - 40)
        //             old = node
        //         }
        //         let labelNode = cc.find('label', old)
        //         labelNode.getComponent(cc.Label).string = Global.FormatNumToComma(self._cashBackCoin)
        //         labelNode.y = self._timeFlag ? CoinLabelPos.FirstDayPos: CoinLabelPos.SecondDayPos
        //         cc.find('tip', old).active = true
        //         cc.find('normal', old).active = self._timeFlag
        //         cc.find('end', old).active = !self._timeFlag
        //         old.stopAllActions()
        //         old.active = true
        //         old.opacity = 50
        //         old.runAction(cc.sequence(
        //             cc.fadeIn(0.5),
        //             cc.delayTime(1.5),
        //             cc.fadeOut(0.5),
        //             cc.callFunc(function(){
        //                 old.destroy()
        //             }, this)
        //         ))
        //     }
        // })  

        if (this._msgInfo.state == StateType.SecondDay) {
            //可以领取
            this._loadCashBackPop(this._cashBackCoin)
        }
        else {
            let url = "CashHero/prefab/cashBack/cashBackPop"
            let uiname = "cashBackPop"
            let callbacks = function (prefab) {
                let node = cc.instantiate(prefab);
                node.name = uiname;
                node.parent = cc.find("Canvas");
                node.getComponent('cashBackPop').initCoin(self._cashBackCoin)
            }
            this._loadPrefab(url, callbacks)
        }
    },

    _loadPrefab: function (url, callbacks) {
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                callbacks(prefab)
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    onEventClose() {
        this.node.destroy()
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_START, this.OnRcvNetRefush, false, this)
    },

    changeAnim() {
        if (this._animFlag) {
            return
        }
        this._animFlag = true
        this._animInter = 9
        let self = this
        let spine = cc.find('spr', this.node).getComponent(sp.Skeleton)
        spine.setAnimation(0, "animation2", false);
        spine.getComponent(sp.Skeleton).setCompleteListener(() => {
            spine.setCompleteListener(null)
            spine.setAnimation(0, "animation1", true)
            self._animInter = 0
            self._animFlag = false
        })
    },

    _floatAddVal: function (val) {
        let lbl_add = cc.find("lbl_add", this.node)
        lbl_add.getComponent(cc.Label).string = "+" + Global.convertNumToShort(val)
        lbl_add.active = true
        lbl_add.y = -20
        cc.tween(lbl_add)
            .to(0.6, { y: 25 })
            .call(() => {
                lbl_add.active = false
            })
            .start()
    },

    update(dt) {
        if (this._msgInfo) {
            this._inter += dt
            this._animInter += dt
            if (this._inter >= 1) {
                this._inter = 0
                if (this._leftTime > 0) {
                    this._leftTime--
                    this.changeTime()
                    if (this._leftTime == 0) {
                        this._msgInfo.state = StateType.SecondDay
                        this._setTime(false)
                    }
                }
            }
        }

        // if (this._animInter >= 8 && !this._animFlag) {
        //     this.changeAnim()
        // }
    },
});
