/**
 * 礼物列表的item
 */

let giftSpine = {
    "gift_car": { name: "animation2", scale: 0.2 },
    "gift_evil": { name: "ermodaiji", name2: "ermobao", scale: 1 },
    "gift_ice": { name: "animation2" },
    "gift_kiss": { name: "animation" },
    "gift_money": { name: "animation2", scale: 0.2 },
    "gift_poker": { name: "animation2" },
    "gift_ring": { name: "animation" },
    "gift_tower": { name: "animation", scale: 0.4 },
};
const ListItem = require('ListItem');
cc.Class({
    extends: ListItem,

    properties: {
        giftAtlas: cc.SpriteAtlas,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_reback = cc.find("btn_reback", this.node)
        Global.btnClickEvent(btn_reback, this.onClickReback, this);
    },

    start() {

    },

    init(data, bSend) {
        this._itemData = data
        cc.find("node_head", this.node).getComponent('UserHead').setHead(data.uid, data.usericon);
        // cc.find("lv_bg/lbl_playerlv",this.node).getComponent(cc.Label).string = "LV."+ (data.level || 1)
        cc.find("lblName", this.node).getComponent(cc.Label).string = data.playername;
        cc.find("num_bg/charm_add", this.node).getComponent(cc.Label).string = "+" + Math.floor(data.coin / 10000);//Global.FormatNumToComma(data.coin);
        // cc.find("gift",this.node).getComponent(cc.Sprite).spriteFrame = this.giftAtlas.getSpriteFrame(data.img);
        //时间
        let dif = cc.vv.UserManager.getServerTime() - data.time
        cc.find("lbl_time", this.node).getComponent(cc.Label).string = Global.formatTimeDiff(dif) + " Ago"
        //礼物
        let gift = cc.find("gift", this.node)
        let url = "CashHero/gift/spine/" + data.img + "/spine"
        Global.loadSpine(url, gift, giftSpine[data.img].name, true)
        gift.scale = giftSpine[data.img].scale ? giftSpine[data.img].scale : 0.3
        //回赠按钮
        let btn_reback = cc.find("btn_reback", this.node)
        btn_reback.active = !bSend

        //新的礼物
        let redNode = cc.find("reddot", this.node)
        redNode.active = (data.unread) ? true : false

    },

    onClickReback: function () {
        this._itemData.unread = null
        let redNode = cc.find("reddot", this.node)
        redNode.active = false

        let req = { c: MsgId.PERSIONAL_INFO };
        req.otheruid = this._itemData.uid
        req.act = 2
        cc.vv.NetManager.send(req);
    }

    // update (dt) {},
});
