cc.Class({
    extends: cc.Component,

    properties: {
        sprTopRank: {
            default: [],
            type: cc.SpriteFrame,
        }
    },


    onLoad() {
        let btnClose = cc.find("content/top/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        let btnHelp = cc.find("content/top/btn_help", this.node)
        btnHelp.on('click', this.onClickHelp, this)

        let btnCloseHelp = cc.find("rules/help/btn_close", this.node)
        btnCloseHelp.on('click', this.onClickCloseHelp, this)

        Global.playComEff("ch_popup_l2")

        cc.vv.NetManager.registerMsg(MsgId.REQ_BINGO_RANK, this.onRcvNeBingoRank, this)

        let req = { c: MsgId.REQ_BINGO_RANK }
        cc.vv.NetManager.send(req)

        this._bingoInfo = null
        this._inter = 0
        this._endTime = 0
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_BINGO_RANK, this.onRcvNeBingoRank, false, this)
    },

    showItem(item, data) {
        let icon_top = cc.find("icon_top", item)
        icon_top.active = (data.ord <= 3)
        if (data.ord <= 3) {
            icon_top.getComponent(cc.Sprite).spriteFrame = this.sprTopRank[data.ord - 1]
        }
        var userHead = cc.find("node_head", item).getComponent('UserHead')
        userHead.setHead(data.uid, data.usericon)
        Global.setLabelString("lbl_rank", item, "" + data.ord)
        Global.setLabelString("lbl_name", item, data.playername)
        Global.setLabelString("lbl_count", item, "" + data.score)
    },

    showTime(startTime, endTime) {
        let difTime = (endTime * 1000) - new Date().getTime()
        let leftTime = parseInt(difTime / (24 * 60 * 60 * 1000))
        if (leftTime > 0) {
            let _lanStr = cc.vv.Language['lefttime3']
            if (leftTime >= 2) {
                _lanStr = (leftTime == 2 && Global.language == Global.LANGUAGE.AR) ? cc.vv.Language['lefttime3'] : cc.vv.Language['lefttime4']
            }
            I18N.setI18nLabel(cc.find("top_bg/lbl_time", this.node), _lanStr, leftTime)

            // Global.setLabelString("top_bg/lbl_time", this.node, leftTime+" DAYS LEFT")
        } else {
            this._bingoInfo = true  //开始倒计时
            let _str = Global.formatSec(difTime / 1000)
            Global.setLabelString("top_bg/lbl_time", this.node, _str)
        }
        this._endTime = endTime
    },

    show(datalist, myself) {
        let content = cc.find("content/list/view/content", this.node)
        let itemTmp = cc.find("content/bottom/item", this.node)
        for (let i = 0; i < datalist.length; i++) {
            let item = cc.instantiate(itemTmp)
            item.parent = content
            this.showItem(item, datalist[i])
        }
        this.showItem(itemTmp, myself)
    },

    // 获取时间字符串 
    _getTimeStr: function (time) {
        var date = new Date(time * 1000)
        var month = date.getMonth() + 1;
        var day = date.getDate();

        var hour = date.getHours();
        if (10 > hour) {
            hour = '0' + hour
        }
        var minutes = date.getMinutes();
        if (10 > minutes) {
            minutes = '0' + minutes
        }
        var seconds = date.getSeconds();
        if (10 > seconds) {
            seconds = '0' + seconds
        }
        return month + '-' + day + ' ' + hour + ':' + minutes + ':' + seconds
    },

    onRcvNeBingoRank(msg) {
        if (msg.code == 200) {
            this.show(msg.datalist, msg.myself)
            for (let i = 0; i < msg.rewards.length; i++) {
                let rk = msg.rewards[i].lRank
                let coin = 0
                let rewards = msg.rewards[i].rewards
                for (let j = 0; j < rewards.length; j++) {
                    if (rewards[j].type == Global.PROP_ID.COIN) {
                        coin += rewards[j].count
                    }
                }
                Global.setLabelString("rules/help/lbl_coin" + rk, this.node, Global.FormatNumToComma(coin))
                if (rk == 1) {
                    Global.setLabelString("content/top/lbl_coin", this.node, Global.FormatNumToComma(coin))
                }
                Global.setLabelString("rules/help/lbl_time", this.node, this._getTimeStr(this._endTime))
            }
        }
    },

    onClickClose() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_RANK_CLOSE, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_close")
        this.node.destroy()
    },

    onClickHelp() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_RANK_HELP, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_btn_click")
        cc.find("rules", this.node).active = true
        let help = cc.find("rules/help", this.node)
        Global.showAlertAction(help, true, 0.1, 1)
    },

    onClickCloseHelp() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_RANK_HELP_CLOSE, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_close")
        cc.find("rules", this.node).active = false
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1) {
            this._inter = 0
            if (this._bingoInfo) {
                let difStr = (this._endTime * 1000) - new Date().getTime()
                if (difStr < 0) {
                    this._bingoInfo = null
                    return
                }
                let str = Global.formatSec(difStr / 1000)
                Global.setLabelString("top_bg/lbl_time", this.node, str)
            }
        }
    },


});
