cc.Class({
    extends: cc.Component,

    properties: {
        _difY: 410,
        _difX: 293,
        _difPage: 1100,
        _maxOnePage: 9,
        _inter: 0,
        _time: 2,
    },

    onLoad() {
        Global.FixDesignScale_V(this.node)
        this.leftBtn = cc.find('left', this.node)
        Global.btnClickEvent(this.leftBtn, this.onClickLeft, this)
        this.rightBtn = cc.find('right', this.node)
        Global.btnClickEvent(this.rightBtn, this.onClickRight, this)
        this.collectBtn = cc.find('collectBtn', this.node)
        Global.btnClickEvent(this.collectBtn, this.onClickCollect, this)

        this.curPage = 0
        this.maxPage = 0
        this.heroData = null
        this.canUpdate = false

        this.page1 = cc.find('block', this.node)
        this.page2 = cc.find('other', this.node)

        this.clickFlag = true
        this._autoModel = false
    },

    start() {
        //单次滑动结束 防止出现多点触摸
        this.canTouchFlag = true

        if (cc.vv.gameData) {
            this._autoModel = cc.vv.gameData.GetAutoModelTime()
        }

        //如果有popreward 则遮布隐藏 
        let canvas = cc.find('Canvas')
        let bPop = cc.find('pop_reward', canvas)
        cc.find('lay_bg', this.node).active = !bPop
    },

    touchOn() {
        //监听触摸开始事件
        this.node.on(cc.Node.EventType.TOUCH_START, this.on_touch_start, this);
        this.node.on(cc.Node.EventType.TOUCH_MOVE, this.on_touch_move, this);
        //监听作用域内触摸抬起事件
        this.node.on(cc.Node.EventType.TOUCH_END, this.on_touch_end, this);
    },

    init(callBack, id, data) {
        this._cardId = id
        this._callBack = callBack
        this.heroData = data
        let kinds = this.hasKinds(this.heroData)
        this.maxPage = Math.floor((kinds - 1) / 9)
        this.initLeftAndRight(kinds > 9)
        //展示碎片布局
        this.initBlock()
    },

    //大于九种才出现左右切换按钮
    initLeftAndRight(flag) {
        if (flag) {
            this.touchOn()
        }
        this.leftBtn.active = flag
        this.leftBtn.getComponent(cc.Button).interactable = flag
        this.rightBtn.active = flag
        this.rightBtn.getComponent(cc.Button).interactable = flag
    },

    //总共多少种卡牌    剔除除了卡牌以外的数据
    hasKinds(data) {
        let count = 0
        let heroArray = []
        for (let i = 0; i < data.length; i++) {
            if (data[i].type == 8) {
                heroArray.push(data[i])
                count++
            }
        }
        this.heroData = heroArray
        return count
    },

    on_touch_start(event) {
        if (!this.canTouchFlag) {
            return
        }
        console.log('on_touch_start')
        this.canTouchFlag = false
        this._touchStartPos = event.touch.getLocation();
    },
    on_touch_move(t) {
        if (this.canTouchFlag) {
            return
        }
        let pos = t.touch.getLocation();

        let deltaDis = this._touchStartPos.x - pos.x
        if (Math.abs(deltaDis) > 50) {
            if (deltaDis < 0) {
                //向右滑动
                this.onClickRight()
                this.canTouchFlag = true
            } else {
                //向左滑动
                this.onClickLeft()
                this.canTouchFlag = true
            }
        }
    },
    on_touch_end() {
        console.log('on_touch_end')
        this.canTouchFlag = true
    },

    //当前块的数据
    _blockSort() {
        let blockArray = []
        let len = this.heroData.length > (this.curPage + 1) * this._maxOnePage ? 9 : this.heroData.length - this.curPage * this._maxOnePage
        let startLen = this.curPage * this._maxOnePage
        for (let i = startLen; i < startLen + len; i++) {
            blockArray.push(this.heroData[i])
        }
        return blockArray
    },

    //判断当前是哪块
    _isWhichPage() {
        if (this.page1.x == 0) {
            this.posZero = this.page1
            this.posOther = this.page2
        } else {
            this.posZero = this.page2
            this.posOther = this.page1
        }
    },

    //显示当前页面需要多少个元素
    _creatItem(data, pageNode) {
        //item是否大于所需要的
        let childNum = pageNode.children.length

        //item数量大于数据长度 则隐藏最后的
        if (childNum > data.length) {
            for (let i = childNum - 1; i >= data.length; i--) {
                pageNode.children[i].active = false
            }
        } else if (childNum < data.length) {
            for (let index = 0; index < data.length - childNum; index++) {
                let item = cc.instantiate(pageNode.children[0])
                item.parent = pageNode
            }
        } else {
            for (let index = 0; index < childNum; index++) {
                pageNode.children[index].active = true
            }
        }
    },

    //设置位置
    _setPos(blockData, pageNode) {
        let child = pageNode.children
        let len = blockData.length
        let flagY = Math.ceil(len / 3)
        for (let i = 0; i < flagY; i++) {
            //当前行有多少元素
            let num = (((i + 1) * 3) <= len) ? 3 : len - (i * 3)
            for (let j = 0; j < num; j++) {
                if (flagY == 1) {
                    child[i * 3 + j].x = -(num - 1) * this._difX / 2 + j * this._difX
                } else {
                    child[i * 3 + j].x = -this._difX + j * this._difX
                }
                child[i * 3 + j].y = (flagY - 1) * this._difY / 2 - i * this._difY
            }
        }
    },

    //设置碎片数据
    _setData(data, pageNode) {
        for (let i = 0; i < data.length; i++) {
            if (data[i].cardID == this._cardId) {
                this.canUpdate = true
            }
            if (this.canUpdate) {
                this._updateCardInfo(data[i].cardInfo)
            }
            this._showCardFragement(data[i].cardID, data[i].count, pageNode.children[i])
        }
    },

    _updateCardInfo(info) {
        cc.vv.HerocardManager.updateCardInfo(info)
        Global.dispatchEvent("HEROCARD_UPDATED", info)
    },

    _showCardFragement: function (cardid, num, node) {
        let cardInfo = cc.vv.HerocardManager.getCardInfo(cardid)
        let cfg = cardInfo.cfg
        if (cfg) {
            let lblName = cc.find('lbl_name', node)
            // lblName.getComponent(cc.Label).string = cfg.name
            I18N.setI18nLabel(lblName, cc.vv.Language["cardname_" + cardid])
            let lblAdd = cc.find('lbl_add', node)
            lblAdd.getComponent(cc.Label).string = 'x' + num
            let cardicon = cc.find("icon", node)
            cc.vv.HerocardManager.loadFragmentHero(cardicon, cardid)
            let chipNum = cc.find('pro/lbl_num', node)
            let proVal = 0
            if (cardInfo.lv <= 0) {
                proVal = cardInfo.chips / cfg.unlock_chips
                chipNum.getComponent(cc.Label).string = cardInfo.chips + "/" + cfg.unlock_chips
            } else {
                let starCfg = cc.vv.HerocardManager.getCardStarCfg(cardInfo.cardid, cardInfo.star + 1)
                if (starCfg) {
                    proVal = cardInfo.chips / starCfg.need_chips
                    chipNum.getComponent(cc.Label).string = cardInfo.chips + "/" + starCfg.need_chips
                } else {
                    chipNum.getComponent(cc.Label).string = cardInfo.chips
                }
            }
            let pro = cc.find('pro', node)
            pro.getComponent(cc.ProgressBar).progress = (proVal == 0 ? 0.01 : proVal)
        }
    },

    //初始化当前块
    initBlock(blockNode = null) {
        let curBlockData = this._blockSort()
        if (!blockNode) {
            this._isWhichPage()
        }
        let posNode = blockNode ? blockNode : this.posZero
        this._creatItem(curBlockData, posNode)
        this._setPos(curBlockData, posNode)
        this._setData(curBlockData, posNode)
    },

    //block滑动 flag:方向
    blockSlide(flag) {
        this._isWhichPage()
        this.posOther.x = -flag * 1080
        this.initBlock(this.posOther)
        cc.tween(this.posOther)
            .to(0.35, { x: 0 }, { easing: 'quartOut' })
            .start()

        cc.tween(this.posZero)
            .to(0.35, { x: flag * 1080 }, { easing: 'quartOut' })
            .start()
    },

    onClickCollect() {
        this._autoModel = false
        this._callBack()
        this.node.destroy()
    },

    onClickLeft() {
        this._autoModel = false
        if (!this.clickFlag) {
            return
        }
        this.clickFlag = false
        if (this.curPage == 0) {
            this.curPage = this.maxPage
        } else {
            this.curPage--
        }
        this.clickDelay()
        this.blockSlide(-1)

    },

    onClickRight() {
        this._autoModel = false
        if (!this.clickFlag) {
            return
        }
        this.clickFlag = false
        if (this.curPage == this.maxPage) {
            this.curPage = 0
        } else {
            this.curPage++
        }
        this.clickDelay()
        this.blockSlide(1)
    },

    clickDelay() {
        cc.tween(this.node)
            .delay(0.5)
            .call(() => {
                this.clickFlag = true
            })
            .start()
    },

    update(dt) {
        if (this._time && this._autoModel) {
            this._inter += dt
            if (this._inter >= 1) {
                this._inter = 0
                this._time--
                if (this._time < 1) {
                    this.onClickCollect()
                }
            }
        }
    },
});
