
/**
 * 月卡弹窗
 */

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _btnBuy: null,
        _btnCollect: null,
        _btnTrial: null,

        _data: null,
        _stype: 15,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

        this._stype = 15;
        this._btnBuy = cc.find('content/layout/btn_buy', this.node);
        this._btnCollect = cc.find('content/btn_collect', this.node);
        this._btnTrial = cc.find("content/layout/btn_trial", this.node)

        Global.btnClickEvent(this._btnBuy, this.onClickBuy, this);
        Global.btnClickEvent(this._btnCollect, this.onClickCollect, this);
        Global.btnClickEvent(this._btnTrial, this.onClickTrail, this);

        let btnClose = cc.find("content/btn_close", this.node)
        Global.btnClickEvent(btnClose, this.onClickClose, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_SHOP_EX, this.onRcvShopEx, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_COLLECT_WEEK_MONTH_CARD, this.onRcvCollectCoin, this);
        cc.vv.NetManager.registerMsg(MsgId.NOTICE_BUY_WEEK_MONTH_CARD_SUCCESS, this.onRcvBuySuccess, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_OPEN_TRIAL_CARD, this.onRcvOpenTrialCard, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_GET_TRIAL_CARD, this.onRcvGetTrialCard, this);

        Global.playComEff("ch_popup");
    },

    start() {
        var req = { 'c': MsgId.REQ_SHOP_EX };
        req.uid = Global.playerData.uid;
        req.stype = "15";
        cc.vv.NetManager.send(req);

        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MONTHCARD_POP)

    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_SHOP_EX, this.onRcvShopEx, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_COLLECT_WEEK_MONTH_CARD, this.onRcvNeCollectCoin, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.NOTICE_BUY_WEEK_MONTH_CARD_SUCCESS, this.onRcvNeBuySuccess, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_OPEN_TRIAL_CARD, this.onRcvOpenTrialCard, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_GET_TRIAL_CARD, this.onRcvGetTrialCard, false, this);

        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },

    onRcvShopEx: function (msg) {
        if (msg.code === 200) {
            if (msg.shoplist["data15"]) {
                this._showUI(msg.shoplist["data15"][0]);
            }
        }
    },

    _showUI: function (data) {
        this._data = data
        console.log(data)
        let state = data.collect; //0只能购买 1需要收集了 2今日已收集过了

        cc.find("lbl_time", this._btnCollect).getComponent(cc.Label).string = data.leftdays + " DAYS LEFT";
        // cc.find('lbl_price',this._btnBuy).getComponent(cc.Label).string = "For $ " + data.amount;
        I18N.setI18nLabel(cc.find('lbl_price', this._btnBuy), cc.vv.Language.btn_for, data.amount)

        let lbl_total_gold = cc.find("content/lbl_total", this.node);
        lbl_total_gold.getComponent(cc.Label).string = Global.FormatNumToComma(data.total);

        let lbl_gold_num1 = cc.find("content/Item1/lbl_num", this.node);
        lbl_gold_num1.getComponent(cc.Label).string = Global.FormatNumToComma(data.count);

        let lbl_gold_num2 = cc.find("content/Item2/lbl_num", this.node);
        lbl_gold_num2.getComponent(cc.Label).string = Global.FormatNumToComma(data.countday);

        this._btnBuy.active = state == 0;
        this._btnCollect.active = state != 0;
        this._btnCollect.getComponent(cc.Button).interactable = state == 1;

        //试用: -1:未开启 0:使用结束 1/2/3试用剩余天数  <100未领取 >100已领取
        let trial = data.trial
        this._btnTrial.active = (state == 0 && trial != 0)
        this._btnTrial.getComponent(cc.Button).interactable = (trial < 0 || (trial >= 1 && trial <= 3))
        let labelTrial = cc.find("lbl_desc", this._btnTrial).getComponent(cc.Label)
        let labelTime = cc.find("lbl_time", this._btnTrial).getComponent(cc.Label)

        //设置key 刷新
        let triali18Scp = labelTrial.node.getComponent("LanguageLabel")
        triali18Scp.id = (trial < 0) ? 'month_pop_btnleft1' : 'month_pop_btnleft2'
        triali18Scp.updateLabel()

        if (trial < 0) {
            // labelTrial.string = "Free 3-day trial"
            labelTime.string = ""
        } else if (trial > 0) {
            // labelTrial.getComponent(cc.Label).string = "Receive Award"
            let days = trial
            if (days >= 100) days -= 101
            let _leftType = 'month_pop_leftday1'
            if (days == 1) {
                // labelTime.string = "Trial Remain:" + days + " day"
                _leftType = 'month_pop_leftday1'
            } else if (days > 1) {
                _leftType = (Global.language == Global.LANGUAGE.AR && days == 2) ? 'month_pop_leftday1' : 'month_pop_leftday2'
                // labelTime.string = "Trial Remain:" + days + " days"
            } else {
                labelTime.node.active = false
            }
            if (labelTime.node.active) {
                I18N.setI18nLabel(labelTime.node, cc.vv.Language[_leftType], days)
            }
        }

        //benifist
        let btn = cc.find("content/btn_benifist", this.node)
        btn.getComponent('CH_Benifist_Btn').showBenifist(this._data.rewards, '月卡礼包')
    },


    onClickBuy: function () {
        if (this._data == null) return;
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MONTHCARD_BUY)

        cc.vv.PayMgr.reqPurchaseOrder(this._data.id);
    },

    onClickCollect: function () {
        Global.playComEff("ch_collect")
        this._btnCollect.getComponent(cc.Button).interactable = false;
        cc.vv.NetManager.send({ c: MsgId.REQ_COLLECT_WEEK_MONTH_CARD, stype: this._stype });

        Global.dispatchEvent(EventId.REFUSH_SHOP_REQ)
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MONTHCARD_RECEIVED)
    },

    onClickTrail: function () {
        if (this._data == null) return

        Global.dispatchEvent(EventId.REFUSH_SHOP_REQ)
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MONTHCARD_TRAI3)

        let trial = this._data.trial
        if (trial < 0) { //开启
            Global.playComEff("ch_btn_click")
            this._btnTrial.getComponent(cc.Button).interactable = false
            cc.vv.NetManager.send({ c: MsgId.REQ_OPEN_TRIAL_CARD, stype: this._stype })

            //月卡试用
            cc.vv.PlatformApiMgr.KoSDKTrackEvent('month_card_trial', JSON.stringify({ uid: Global.playerData.uid }))

        } else if (trial >= 1 && trial <= 3) {
            Global.playComEff("ch_collect")
            this._btnTrial.getComponent(cc.Button).interactable = false
            cc.vv.NetManager.send({ c: MsgId.REQ_GET_TRIAL_CARD, stype: this._stype })
            cc.vv.RedSys.clearRedTip(19)
        }
    },

    onClickClose() {
        if (cc.isValid(this.node, true)) {
            //打点
            StatisticsMgr.reqReport(StatisticsMgr.REQ_MONTHCARD_CLOSE)
            cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
            Global.playComEff("ch_close")
            this.node.destroy()
        }

        // let mask = cc.find('mask',this.node)
        // cc.tween(mask)
        // .to(1,{opacity:0})
        // .start()
        // Global.showAlertAction(this.node,false,1,0,()=>{
        //     cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        //     
        // });
    },

    _trialPop(data) {
        if (data.trial > 0) {
            //开启了未领取完
            let days = data.trial
            if (days >= 100) days -= 101
            if (days > 0) {
                this.showCoinCollectTip(days, data)
            }
        }
    },

    showCoinCollectTip(count, data) {
        let tips = cc.find("open_trial_tip", this.node)
        tips.active = true
        cc.find("open_trial_bg", tips).active = false
        let bg = cc.find("coin_collect", tips)
        bg.active = true
        Global.showAlertAction(bg, true, 0.1, 1, null);
        let btnClose = cc.find("closeBtn", bg)
        btnClose.on("click", () => {
            btnClose.off("click")
            tips.active = false
        }, this)
        //显示
        cc.find('label', bg).getComponent(cc.Label).string = 'with ' + count + '-day trial will be given to you together!'
        cc.find('coinNum', bg).getComponent(cc.Label).string = Global.FormatNumToComma(data.countday * count)
    },

    showOpenTrialTips() {
        let tips = cc.find("open_trial_tip", this.node)
        tips.active = true
        cc.find("coin_collect", tips).active = false
        let bg = cc.find("open_trial_bg", tips)
        Global.showAlertAction(bg, true, 0.1, 1, null);
        let btnGo = cc.find("btn_go", bg)
        btnGo.on("click", () => {
            btnGo.off("click")
            tips.active = false
        }, this)
    },

    showCollectCoin(coin, addCoin) {
        let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
        if (cc.vv.gameData) {
            toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
        }
        let rollData = {}
        rollData.lblCoin = toLbl;
        rollData.addCoin = addCoin;
        let srcObj = cc.find("content/Item2/lbl_num", this.node);

        Global.FlyCoin(srcObj, endNode, () => {
            //刷新金币
            if (cc.vv.gameData) {
                cc.vv.gameData.AddCoin(addCoin, true)
            } else {
                cc.vv.UserManager.AddCoin(addCoin, true)
            }
        }, rollData, true)
    },

    onRcvCollectCoin(msg) {
        if (msg.stype != this._stype) return;

        if (msg.code === 200) {
            this._data.collect = 2;
            this._showUI(this._data);
            this.showCollectCoin(msg.coin, msg.addCoin)
        }
        else {
            let str = "";
            switch (msg.code) {
                case 210:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_invalid_parameter);
                    // str = "Invalid Parameter!";
                    break;
                case 496:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_had_collected);
                    // str = "Had Collected!";
                    break;
                default:
                    break;
            }
            // if (str) {
            //    cc.vv.FloatTip.show(str);
            // }

            this._btnCollect.getComponent(cc.Button).interactable = true;
        }
    },

    onRcvBuySuccess(msg) {
        if (msg.stype != this._stype) return;

        if (msg.code === 200) {
            this._data.collect = 1;
            this._showUI(this._data);
            //付款成功
            this._trialPop(this._data)
        }
        else {
            let str = "";
            switch (msg.code) {
                case 210:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_invalid_parameter);
                    // str = "Invalid Parameter!";
                    break;
                case 496:
                    cc.vv.FloatTip.show(cc.vv.Language.float_tip_had_collected);
                    // str = "Had Collected!";
                    break;
                default:
                    break;
            }
            // if (str) {
            // cc.vv.FloatTip.show(str);
            // }

            this._btnBuy.getComponent(cc.Button).interactable = true;
        }
    },

    onRcvOpenTrialCard(msg) {
        if (msg.code == 200) {
            this._data.trial = msg.trial
            this._showUI(this._data)
            //显示tips
            this.showOpenTrialTips()
        } else {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_had_opend);
            // cc.vv.FloatTip.show("Had Opend!");
        }
    },

    onRcvGetTrialCard(msg) {
        if (msg.code == 200) {
            this._data.trial = msg.trial
            this._showUI(this._data)
            this.showCollectCoin(msg.coin, msg.addCoin)
        } else {
            cc.vv.FloatTip.show("Had Collected!");
        }
    },

});
