let CollectGameMap = cc.Class({
    extends: cc.Component,

    properties: {
        callBack: null,
        map_node: null,
        panel: null,
        bg: null,
        btn_close: null,
        scrollView: null,
        map_flag: null,
        mapItems: [],

        _wheelResp: null, // mapWheel结果
    },

    onLoad() {
        this._initView();
        this._initListener();
    },

    _initView() {
        this.map_node = this.node;
        this.panel = this.map_node.getChildByName("panel");
        this.bg = this.map_node.getChildByName("bg");
        this.btn_close = this.panel.getChildByName("btn_close").getComponent(cc.Button);
        this.scrollView = this.panel.getChildByName("scrollview").getComponent(cc.ScrollView);
        this.map_flag = this.scrollView.content.getChildByName("map_flag");
        this.map_flag.originPos = { x: this.map_flag.x, y: this.map_flag.y };
        this.mapItems = [];
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        for (let i = 1; i <= 33; i++) {
            let item = this.scrollView.content.getChildByName("item" + i);
            item["id"] = i;
            let vo = mapCfg[i.toString()];
            this.mapItems.push(item);
        }
        this._reset();
    },

    /**
     * 当通过最后一关后需要重置地图
     */
    resetMap() {
        this.map_flag.getChildByName("hama").active = true;
        this.map_flag.getChildByName("wangzi").active = false;
        this.map_flag.x = this.map_flag.originPos.x;
        this.map_flag.y = this.map_flag.originPos.y;

        for (let i = 0; i < this.mapItems.length; i++) {
            let index = i + 1;
            let vo = SlotsFacade.dm.getGameCfg().mapCfg[index.toString()];
            let item = this.mapItems[i];
            if (vo.type == 1) {
                let node = item.getChildByName("type1");
                node.getChildByName("spine").active = true;
                let img = node.getChildByName("icon").getComponent("ImgSwitchCmp");
                if (vo.id > 18) {
                    img.setIndex(2);
                } else {
                    img.setIndex(0);
                }
            }
        }
    },

    _initListener() {
        this.btn_close.node.on("click", this._onBtnCloseHandler.bind(this), this);
    },

    /**
     * 显示关闭按钮
     * @returns {Promise<unknown>}
     * @private
     */
    _showCloseBtn() {
        return new Promise((res) => {
            this.btn_close.node.active = true;
            this.btn_close.node.scale = 0;
            this.btn_close.interactable = true;
            this.btn_close.node.getChildByName("spine").active = true;
            cc.tween(this.btn_close.node)
                .to(0.3, { scale: 1 }, { easing: "backOut" })
                .call(() => {
                    res();
                })
                .start();
        });
    },

    async _onBtnCloseHandler() {
        SlotsFacade.soundMgr.playEffect("click");
        this.btn_close.interactable = false;
        this.btn_close.node.getChildByName("spine").active = false;
        cc.tween(this.btn_close.node)
            .to(0.3, { scale: 0 }, { easing: "backIn" })
            .call(() => {
                this.exitMap(this._wheelResp);
            })
            .start();
    },

    /**
     * 退出
     */
    exitMap(data) {
        SlotsFacade.soundMgr.playEffect("map_close");
        let svNode = this.scrollView.node;
        cc.tween(svNode)
            .to(0.3, { y: svNode.height }, { easing: "cubicOut" })
            .call(() => {
                this._reset();
                if (SlotsFacade.dm.energyData.currId == SlotsFacade.dm.getGameCfg().TheFinalHurdleID) {
                    this.resetMap();
                }
                if (this.callBack) {
                    this.callBack(data);
                    this.callBack = null;
                }
            })
            .start();
    },

    /**
     * 进入
     * @param isView 是否是查看
     * @param cb
     * @returns {Promise<void>}
     */
    async enterMap(isView, cb) {
        SlotsFacade.soundMgr.playEffect("map_open");
        this.callBack = cb;
        this._wheelResp = null;
        this.map_node.active = true;
        this.panel.active = true;
        this.bg.active = true;
        let data = SlotsFacade.dm.energyData;
        let currIndex = data.currId;
        if (!isView && data.state > 0) {
            currIndex -= 1;
            SlotsFacade.collectProgress.setProgress(0);
        }
        this._freshMap(currIndex);

        if (currIndex > 0) {
            if (currIndex > 14) {
                this.scrollView.scrollToTop();
            } else {
                this.scrollView.scrollToBottom();
            }
        } else {
            this.scrollView.scrollToBottom();
        }
        await this._scrollViewShow();
        if (isView) {
            this._showCloseBtn();
        } else {
            await this._moveMapFlag(data.currId);
            let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
            let vo = mapCfg[data.currId];
            switch (vo.type) {
                case 1:
                    SlotsFacade.slots777.showEnter(SlotsFacade.dm.energyData.startPrice);
                    break;
                case 2:
                    break;
                case 3:
                    break;
                case 4:
                    break;
                case 5:
                    break;
            }
            await SlotsFacade.delayTime(1);
            this.exitMap();
        }
    },

    /**
     * 移动地图标记
     * @param toIdx
     * @private
     */
    async _moveMapFlag(toIdx) {
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[toIdx.toString()];
        let item = this.mapItems[toIdx - 1];
        // 角色移动动画
        await new Promise((res) => {
            let spine = this.map_flag.getChildByName(toIdx - 1 < 18 ? "hama" : "wangzi").getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation1_1", false);
            spine.addAnimation(0, "animation1", true);
            spine.setCompleteListener(() => {
                spine.setCompleteListener(null);
                if (toIdx == 18) {
                    this.map_flag.getChildByName("hama").active = false;
                    this.map_flag.getChildByName("wangzi").active = true;
                }
            });
            SlotsFacade.soundMgr.playEffect("pass1");
            cc.tween(this.map_flag)
                .to(0.4, { x: item.x, y: item.y })
                .call(() => {
                    res();
                })
                .start();
        });

        // 播放动画
        await new Promise((res) => {
            let spineName = "spine";
            let startAnimation = "animation2"
            let endAnimation = "animation3";
            if (vo.type == 3) {
                spineName = `spine${vo.min}x${vo.max}`;
            }
            if (vo.type == 1) {
                if (vo.id < 18) {
                    startAnimation = "animation1_1";
                } else {
                    startAnimation = "animation2_1";
                }
                SlotsFacade.soundMgr.playEffect("pass2");
            } else {
                SlotsFacade.soundMgr.playEffect("pass3");
            }

            let spine = cc.find(`type${vo.type}/${spineName}`, item).getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, startAnimation, false);
            if (vo.type != 1) {
                spine.addAnimation(0, endAnimation, false);
            }
            spine.setCompleteListener(() => {
                spine.setCompleteListener(null);
                if (vo.type == 1) {
                    spine.node.active = false;
                    this._markItemCmp(toIdx);
                }
                res();
            });
        });
    },

    _freshMap(currIndex) {
        for (let i = 1; i <= currIndex; i++) {
            this._markItemCmp(i);
        }
        if (currIndex > 0) {
            let item = this.mapItems[currIndex - 1];
            this.map_flag.x = item.x;
            this.map_flag.y = item.y;
        }

        this.map_flag.getChildByName("hama").active = currIndex < 18;
        this.map_flag.getChildByName("wangzi").active = currIndex >= 18;
    },

    /**
     * 标记完成
     */
    _markItemCmp(index) {
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[index.toString()];
        let item = this.mapItems[index - 1];
        if (vo.type == 1) {
            let node = item.getChildByName("type1");
            node.getChildByName("spine").active = false;
            let img = node.getChildByName("icon").getComponent("ImgSwitchCmp");
            if (vo.id > 18) {
                img.setIndex(3);
            } else {
                img.setIndex(1);
            }
        }
    },

    /**
     * map显示
     * @returns {Promise<unknown>}
     * @private
     */
    _scrollViewShow() {
        return new Promise((res) => {
            let svNode = this.scrollView.node;
            svNode.active = true;
            cc.tween(svNode)
                .to(0.5, { y: 0 }, { easing: "backOut" })
                .call(() => {
                    res();
                })
                .start();
        });
    },

    /**
     * 重置
     */
    _reset() {
        this.bg.active = false;
        this.panel.active = false;
        this.scrollView.node.y = this.scrollView.node.height / 2;
        this.btn_close.node.active = false;
        this.map_node.active = false;
    },
});
