        /**
         * 
         * @param {*} cardid 
         * @param {*} num 
         * @param {*} endCall 界面关闭后的回调
         * @param {*} bCheckUnlock 是否检查可以解锁
         * @param {*} packType 1 卡包（需要有打开的过程），2 碎片（碎片不需要打开的过程）
         */
        showDropUI: function (cardId, num, endCall = null, bCheckUnlock = true, packType = 1) {
            cc.loader.loadRes('CashHero/prefab/herocard/open_herocard', cc.Prefab, (err, res) => {
                if (!err) {
                    let curScene = cc.director.getScene();
                    //if(!curScene.getChildByName('open_herocard')){
                    let nodecopy = cc.instantiate(res)
                    curScene.addChild(nodecopy)
                    nodecopy.name = 'open_herocard'
                    let script = nodecopy.getComponent('CH_Herocard_OpenFragement')
                    script.showOpen(cardId, num, endCall, bCheckUnlock, packType)
                    //}
                }
            })
        },

        /**
         * 掉落整卡
         * @param {*} cardId 
         * @param {*} againCall  抽卡中的again按钮回调 
         * @param {*} endCall 
         * @param {*} actionType    单抽还是十连类型
         */
        showFullDropUI: function (rewards, againCall = null, endCall = null, actionType = null) {



            cc.loader.loadRes('CashHero/prefab/herocard/card_drop', cc.Prefab, (err, res) => {
                if (!err) {
                    let curScene = cc.find('Canvas')//cc.director.getScene();
                    let oldUI = curScene.getChildByName('card_drop')
                    if (!oldUI) {
                        oldUI = cc.instantiate(res)
                        curScene.addChild(oldUI)
                        oldUI.name = 'card_drop'

                    }
                    let script = oldUI.getComponent('CH_Herocard_packdrop')
                    script.showSummon(rewards, againCall, endCall, actionType)

                    //更新卡牌数据
                    for (let i = 0; i < rewards.length; i++) {
                        let newInfo = this.updateCardInfo(rewards[i].cardInfo)
                        Global.dispatchEvent("HEROCARD_UPDATED", rewards[i].cardInfo);
                        //是否是整卡
                        if (rewards[i].type == Global.PROP_ID.FULL_CARD) {
                            if (newInfo.cfg) {
                                cc.vv.UserManager.setGameUnlock(newInfo.cfg.gameid)
                            }
                        }
                    }
                }
            })
        },

