
cc.Class({
    extends: cc.Component,

    properties: {

    },

    Init(){
        this._node_popup = cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;

        this._bg_guochang = cc.find("BG_GuoChang", this._node_popup);
        this._fg_guochang = cc.find("FG_GuoChang", this._node_popup);
        this._bg_guochang.active = false;
        this._fg_guochang.active = false;

        this._bonusGameStartUI = cc.find('bonusGameStartUI',this._node_popup);
        this._gameWinUI = cc.find('gameWinUI',this._node_popup);
        this._freeGameStartUI = cc.find('freeGameStartUI',this._node_popup);
        this._bonusGameAddSpinsUI = cc.find('bonusGameAddSpins',this._node_popup);
        this._bonusGamePickOneUI = cc.find("bonusGamePickOneUI", this._node_popup);
        this._superFreeStartUI = cc.find("superFreeStartUI", this._node_popup);
        this._winJpUI = cc.find("winJpUI", this._node_popup);
        this._bonusGameStartUI.active = false;
        this._gameWinUI.active = false;
        this._freeGameStartUI.active = false;
        this._bonusGameAddSpinsUI.active = false;
        this._bonusGamePickOneUI.active = false;
        this._superFreeStartUI.active = false;
        this._winJpUI.active = false;


    },

    //显示bonus游戏结束界面
    // winCoin-赢的钱  bBonus-bonus赢钱显示后边小旗子
    showGameWinUI(winCoin, bBonus){
        return new Promise(async (success, failed) => {

            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            if(bBonus){
                this._bg_guochang.active = true;
                this._bg_guochang.getComponent(sp.Skeleton).setAnimation(0,"BG_GuoChang_Intro",false);
                this._bg_guochang.getComponent(sp.Skeleton).addAnimation(0,"BG_GuoChang_Loop",true);
            } else {
                Global.SlotsSoundMgr.playEffect("fg_bg_end");
            }

            this._gameWinUI.active = true;
            // let mainnode = cc.find("mainnode", this._bonusGameStartUI);
            this._gameWinUI.setScale(0);
            cc.tween(this._gameWinUI).to(0.5,{scale:1},{easing:"backOut"}).start();

            cc.find("total_grand/lbl", this._gameWinUI).getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);

            let btn = cc.find('FG_btn',this._gameWinUI);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;
            let self = this;
            let clickFunc = async()=>{
                btn.getComponent(cc.Button).interactable = false;
                cc.tween(self._gameWinUI).to(0.5, {scale: 0}, {easing: "backIn"}).start();

                await cc.vv.gameData.awaitTime(0.3);
                if(bBonus){
                    self._bg_guochang.getComponent(sp.Skeleton).setAnimation(0,"BG_GuoChang_End",false);
                    await cc.vv.gameData.awaitTime(0.8);
                } else {
                    await cc.vv.gameData.awaitTime(0.2);
                }
                self._node_popup.active = false;
                self._bg_guochang.active = false;
                self._gameWinUI.active = false;

                success();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            });
        });
    },

    //显示bonus游戏开始界面
    async showBonusStartUI(type){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playEffect("bgTransition");

            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            this._bg_guochang.active = true;
            this._bg_guochang.getComponent(sp.Skeleton).setAnimation(0,"BG_GuoChang_Intro",false);
            this._bg_guochang.getComponent(sp.Skeleton).addAnimation(0,"BG_GuoChang_Loop",true);

            this._bonusGameStartUI.active = true;
            this._bonusGameStartUI.setScale(0);
            cc.tween(this._bonusGameStartUI).to(0.5,{scale:1},{easing:"backOut"}).start();
            cc.find("BGOne/ACTIVATED_EN",this._bonusGameStartUI).getComponent("ImgSwitchCmp").setIndex(type-1);

            await cc.vv.gameData.awaitTime(2);
            cc.tween(this._bonusGameStartUI).to(0.5, {scale: 0}, {easing: "backIn"}).start();

            await cc.vv.gameData.awaitTime(0.3);
            this._bg_guochang.getComponent(sp.Skeleton).setAnimation(0,"BG_GuoChang_End",false);
            // await cc.vv.gameData.awaitTime(0.8);
            this._node_popup.active = false;
            this._bg_guochang.active = false;
            this._bonusGameStartUI.active = false;

            success();
        })
    },

    async showBonusAddSpinsUI(){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.playEffect("wandshow");
            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            this._bonusGameAddSpinsUI.active = true;
            this._bonusGameAddSpinsUI.setScale(0);
            cc.tween(this._bonusGameAddSpinsUI).to(0.5,{scale:1},{easing:"backOut"}).start();
            let tit1 = cc.find("select_additional_EN",this._bonusGameAddSpinsUI);
            let tit2 = cc.find("youve_won_EN",this._bonusGameAddSpinsUI);
            tit1.active = true;
            tit2.active = false;

            let canClick = true;
            let itemList = [];
            for(let i = 1; i <= 3; i++) {
                let item = cc.find("number" + i, this._bonusGameAddSpinsUI);
                itemList.push(item);
            }
            let self = this;
            let clickFunc = async (item,idx) => {
                if (!canClick) {
                    return
                }
                canClick = false;
                itemList[0].stopAllActions();
                item.getComponent(cc.Button).interactable = false;
                let lingpai = cc.find("lingpai", item).getComponent(sp.Skeleton);
                Global.SlotsSoundMgr.playEffect("wandclick");

                let reqdata = {rtype: 2, choiceId: idx + 1}
                let msg = await cc.vv.gameData.reqSubGame(reqdata);
                if (msg && msg.code == 200 && msg.data.rtype == 2) {
                    let extraspins = msg.data.extraSpins;
                    let bonusgame = msg.data.bonusGame;
                    cc.vv.gameData.setBonusGame(bonusgame);
                    tit1.active = false;
                    tit2.active = true;
                    lingpai.setSkin(cc.js.formatStr("result_bg_%s_EN", extraspins[idx]))
                    lingpai.setAnimation(0,"lingpai_bg_click",false);
                    Global.SlotsSoundMgr.playEffect("wandreverse");
                    await cc.vv.gameData.awaitTime(1.3);
                    for(let i = 0; i < itemList.length; i++){
                        if(i != idx){
                            let restItem = itemList[i];
                            let lingpai = cc.find("lingpai", restItem).getComponent(sp.Skeleton);
                            lingpai.setSkin(cc.js.formatStr("result_bg_%s_EN",extraspins[i]));
                            lingpai.setAnimation(0,"lingpai_bg_grey",false);
                        }
                    }
                    await cc.vv.gameData.awaitTime(2);
                    cc.tween(self._bonusGameAddSpinsUI).to(0.5,{scale:0},{easing:"backIn"}).start();
                    await cc.vv.gameData.awaitTime(0.5);
                    self._bonusGameAddSpinsUI.active = false;
                    self._node_popup.active = false;
                    success();
                }
            }
            // 自动模式默认选第一个
            cc.vv.gameData.checkAutoPlay(itemList[0], function () {
                clickFunc(itemList[0],0);
            })
            itemList.forEach((item, idx)=> {
                let lingpai = cc.find("lingpai", item).getComponent(sp.Skeleton);
                lingpai.setSkin("default");
                lingpai.setAnimation(0, "lingpai_bg_idle", true);
                item.off("click");
                item.getComponent(cc.Button).interactable = true;
                item.on("click", async () => {
                    clickFunc(item, idx);
                })
            })
        });
    },

    async showFreeGameStartUI(cnt,bFirst){
        return new Promise(async(success, failed) => {
            Global.SlotsSoundMgr.playEffect(bFirst?"fgbegin":"fgretrigger");

            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            this._freeGameStartUI.active = true;
            this._freeGameStartUI.setScale(0);
            cc.tween(this._freeGameStartUI).to(0.5,{scale:1},{easing:"backOut"}).start();
            cc.find("lbl", this._freeGameStartUI).getComponent(cc.Label).string = cnt;
            cc.find("freeGame", this._freeGameStartUI).active = bFirst;
            cc.find("extraFreeGame", this._freeGameStartUI).active = !bFirst;
            let btn = cc.find("FG_btn", this._freeGameStartUI);
            btn.active = bFirst
            await cc.vv.gameData.awaitTime(0.5);

            if(bFirst){
                let self = this;
                let clickFunc = async()=>{
                    btn.getComponent(cc.Button).interactable = false;
                    cc.tween(self._freeGameStartUI).to(0.5,{scale:0},{easing:"backIn"}).start();
                    await cc.vv.gameData.awaitTime(0.5);
                    self._freeGameStartUI.active = false;
                    self._node_popup.active = false;
                    success()
                };
                cc.vv.gameData.checkAutoPlay(btn, clickFunc);
                btn.off("click");
                btn.getComponent(cc.Button).interactable = true;
                btn.on("click", async()=>{
                    btn.stopAllActions();
                    clickFunc();
                });
            } else {
                await cc.vv.gameData.awaitTime(2);
                cc.tween(this._freeGameStartUI).to(0.5,{scale:0},{easing:"backIn"}).start();
                await cc.vv.gameData.awaitTime(0.5);
                this._freeGameStartUI.active = false;
                this._node_popup.active = false;
                success()
            }
        });
    },

    async showBonusGamePickOneUI(){
        return new Promise(async(success, failed) => {
            Global.SlotsSoundMgr.playEffect("wandshow");
            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            this._bonusGamePickOneUI.active = true;
            this._bonusGamePickOneUI.setScale(0);
            cc.tween(this._bonusGamePickOneUI).to(0.5,{scale:1},{easing:"backOut"}).start();
            let canClick = true;

            let itemList = [];
            for(let i = 1; i <= 5; i++) {
                let item = cc.find("item" + i, this._bonusGamePickOneUI);
                itemList.push(item);
            }

            let self = this;
            let clickFunc = async(item, idx)=>{
                if(!canClick){
                    return
                }
                canClick = false;
                item.getComponent(cc.Button).interactable = false;
                let lingpai = cc.find("lingpai", item).getComponent(sp.Skeleton);
                Global.SlotsSoundMgr.playEffect("wandclick");

                let reqdata = {rtype:1,choiceId:idx+1}
                let msg = await cc.vv.gameData.reqSubGame(reqdata);
                if(msg && msg.code == 200 && msg.data.rtype == 1){
                    let result = msg.data.result;
                    let bonusType = msg.data.bonusTypes;
                    let bonusGame = msg.data.bonusGame;
                    cc.vv.gameData.setBonusGame(bonusGame);
                    lingpai.setSkin(cc.js.formatStr("result_fg_%s_EN", result.spinCnt));
                    lingpai.setAnimation(0,"lingpai_fg_click",false);
                    Global.SlotsSoundMgr.playEffect("wandreverse");
                    await cc.vv.gameData.awaitTime(1.3);
                    for(let i = 0; i < itemList.length; i++){
                        if(i != idx){
                            let restItem = itemList[i];
                            let lingpai = cc.find("lingpai", restItem).getComponent(sp.Skeleton);
                            lingpai.setSkin(cc.js.formatStr("result_fg_%s_EN",bonusType[i].spinCnt));
                            lingpai.setAnimation(0,"lingpai_fg_grey",false);
                        }
                    }
                    await cc.vv.gameData.awaitTime(2);
                    cc.tween(self._bonusGamePickOneUI).to(0.5,{scale:0},{easing:"backIn"}).start();
                    await cc.vv.gameData.awaitTime(0.5);
                    self._bonusGamePickOneUI.active = false;
                    self._node_popup.active = false;
                    success();
                }
            };
            // 自动模式默认选第一个
            cc.vv.gameData.checkAutoPlay(itemList[0], function () {
                clickFunc(itemList[0], 0);
            });
            itemList.forEach((item, idx)=>{
                let lingpai = cc.find("lingpai", item).getComponent(sp.Skeleton);
                lingpai.setSkin("default");
                lingpai.setAnimation(0,"lingpai_fg_idle",true);
                item.off("click");
                item.getComponent(cc.Button).interactable = true;
                item.on("click", async()=>{
                    clickFunc(item, idx)
                })
            });
        })
    },

    async showSuperFreeStartFreeUI(pageReward){
        return new Promise(async(success, failed) => {
    //         Global.SlotsSoundMgr.playEffect("collect_popup");
    //
            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            this._superFreeStartUI.active = true;
            this._superFreeStartUI.setScale(0);
            cc.tween(this._superFreeStartUI).to(0.5,{scale:1},{easing:"backOut"}).start();
            cc.find("lbl", this._superFreeStartUI).getComponent(cc.Label).string = pageReward.freeCnt;
            cc.find("slots_cnt", this._superFreeStartUI).getComponent("ImgSwitchCmp").setIndex(pageReward.slotCnt-1)
            cc.find("OneTable", this._superFreeStartUI).getComponent("ImgSwitchCmp").setIndex(pageReward.slotCnt==4 ? 1 : 0)

            let btn = cc.find("FG_btn", this._superFreeStartUI);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;
            await cc.vv.gameData.awaitTime(0.5);

            let self = this;
            let clickFunc = async()=>{
                btn.getComponent(cc.Button).interactable = false;
                cc.tween(self._superFreeStartUI).to(0.5,{scale:0},{easing:"backIn"}).start();
                await cc.vv.gameData.awaitTime(0.5);
                self._superFreeStartUI.active = false;
                self._node_popup.active = false;
                success()
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
                btn.stopAllActions();
                clickFunc();
            });

        })
    },

    async showWinJpUI(jpIdx, winCoin){
        return new Promise(async(success, failed) => {
    //         Global.SlotsSoundMgr.playEffect("collect_popup");
    //
            this._node_popup.active = true;
            cc.find("mask", this._node_popup).active = true;
            this._winJpUI.active = true;
            this._winJpUI.setScale(0);
            cc.tween(this._winJpUI).to(0.5,{scale:1},{easing:"backOut"}).start();
            cc.find("jpmini_EN", this._winJpUI).getComponent("ImgSwitchCmp").setIndex(jpIdx-1);
            cc.find("lbl", this._winJpUI).getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);

            let btn = cc.find("FG_btn", this._winJpUI);
            btn.off("click");
            btn.getComponent(cc.Button).interactable = true;
            await cc.vv.gameData.awaitTime(0.5);

            let self = this;
            let clickFunc = async()=>{
                btn.getComponent(cc.Button).interactable = false;
                cc.tween(self._winJpUI).to(0.5,{scale:0},{easing:"backIn"}).start();
                await cc.vv.gameData.awaitTime(0.5);
                self._winJpUI.active = false;
                self._node_popup.active = false;
                success()
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=>{
               btn.stopAllActions();
                clickFunc();
            });

        })
    },

    async playFreeQPAnim(){
        let character = cc.find("Canvas/safe_node/character");
        Global.SlotsSoundMgr.playEffect("fgTransition");
        this._node_popup.active = true;
        character.active = false;
        cc.find("mask", this._node_popup).active = false;
        this._fg_guochang.active = true;
        this._fg_guochang.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        this._fg_guochang.getComponent(sp.Skeleton).setCompleteListener(()=>{
            this._fg_guochang.getComponent(sp.Skeleton).setCompleteListener();
            this._node_popup.active = false;
            this._fg_guochang.active = false;
        })
        await cc.vv.gameData.awaitTime(2);
        character.active = true;
    },

});
