/**埃及幻想-符号表 
 * 
*/
cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() { },

    updataSymbol() {
        let symbol = this._symbols.shift()
        let symbolData = null
        if (this._stopTime <= 0 && this._bStoping && this._result && !this._bResizing) {
            if (this._result instanceof Array) {
                //开始设置结果
                this.ReadyToStop()
                symbolData = this._result.shift()
                if (!symbolData) {
                    this._bMoving = false
                }
            }
            else {
                console.log('>>>> LMSlots_Reel_Base.updataSymbol设置的结果不是数组!')
            }
        }
        if (symbolData) {
            symbol.ShowById(symbolData.sid, symbolData.data)
        } else {
            switch (cc.vv.gameData.GetSlotsScript()._randSymbolType) {
                case 0: {
                    symbol.ShowRandomSymbol()
                } break;
                case 1: {
                    symbol.ShowRandomSymbol_scatter()
                } break;
                case 2: {
                    symbol.ShowRandomSymbol_bonus()
                } break;
            }
        }
        this._symbols.push(symbol)
        this.ReLayOut()
        this._curY = 0
        this._holderNode.y = this._holderOrigPosY
        if (!this._bMoving) {
            this.scheduleOnce(() => {
                symbol.showTopMove()
                this.OnReelBounsAction()
            }, 0);
        } else {
            this.scheduleOnce(() => {
                symbol.showTopMove()
            }, 0);
        }
    },

    //重写
    //列停止
    OnReelBounsActionDeep: function () {
        this._super()
        if (cc.vv.gameData.GetSlotsScript()._bStopRightnow) {
            Global.SlotsSoundMgr.stopEffectByName(Global.SlotsSoundMgr.anticipation)
        }
        cc.vv.gameData.getStayKuang().stopJiLiDonghua(this._reelIdx)
    },

    // update (dt) {},
});
