/**
 * 结果卡片
 */
cc.Class({
    extends: cc.Component,

    properties: {
        cardfront: cc.SpriteFrame,
        cardback: cc.SpriteFrame,
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start() {

    },

    showIdle: function () {
        let card = cc.find('spr_card', this.node)
        card.getComponent(cc.Sprite).spriteFrame = this.cardback
        let reward = cc.find('reward', this.node)
        reward.active = false
        let spinidle = cc.find('spine', this.node)
        spinidle.active = true
        let resultgray = cc.find('node_gray', this.node)
        resultgray.active = false
    },

    showResult: function (data, bSel) {
        let card = cc.find('spr_card', this.node)
        card.getComponent(cc.Sprite).spriteFrame = this.cardfront
        let reward = cc.find('reward', this.node)
        reward.active = true
        let spinidle = cc.find('spine', this.node)
        spinidle.active = false
        let resultgray = cc.find('node_gray', this.node)
        resultgray.active = !bSel
        //显示奖励
        let scp = reward.getComponent('CH_Luckycard_resultitem')
        scp.init(data)
    },

    // update (dt) {},
});
