/**
 * fb 绑定弹窗
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_bind = cc.find("btn_bind", this.node)
        Global.btnClickEvent(btn_bind, this.onClickBind, this);
        let btn_close = cc.find("btn_close", this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this);
    },

    start() {

    },

    onClickClose: function () {
        this.node.destroy()
    },

    onClickBind: function () {

        cc.vv.PlatformApiMgr.fbLogin((cbData) => {
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = { c: MsgId.REQ_BIND_FACEBOOK };
                req.accesstoken = cbData.token;
                req.user = cbData.uid;
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req);
            }
            else {
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
            }
        });
        this.node.destroy()
    }

    // update (dt) {},
});
