/**
 * 骑士的探索
 */

let normalWheelCfg = [1, 2, 3, 4, 5, 6, 8, 10];
let buffWheelCfg = [2, 4, 6, 8, 10, 12, 16, 20];
cc.Class({
    extends: cc.Component,

    properties: {
        _curPoint: 0,    // 剩余可转次数
        _curPos: 0,      // 当前位置
        _boxesData: [],  // 获得宝箱状态
        _roundId: 0,     // 当前轮次
        _roundReward: null,// 轮次奖励
        _buff: 0,        // 付费点
        _buffInfo: null, // 付费明细
        _endTime: 0,     // 此轮结束时间
        _startTime: 0,   // 此轮开始时间

        _canClick: false,// 当前是否为可以点击状态
        _boxesItemList: [], //底部箱子item
        itemPrefab: cc.Prefab,
    },

    onLoad() {
        Global.FixDesignScale_V(this.node);

        if (cc.vv.gameData && Global.SlotsSoundMgr) {
            Global.SlotsSoundMgr.stopBgm()
        }
        else {
            cc.vv.AudioManager.stopBgm()
        }
        Global.playBgm({ path: 'CashHero/', filename: 'exploration/base_bgm', common: true })
        if (cc.vv.gameData) cc.vv.gameData.PauseSlot()

        this._closeBtn = cc.find("top_bg/btn_close", this.node);
        this._helpBtn = cc.find("top_bg/btn_help", this.node);
        this._roundlbl = cc.find("top_bg/lbl_round", this.node);
        this._roundRewardNode = cc.find("top_bg/reward", this.node);
        let _jumpTime = 0.8
        this._roundRewardNode.stopAllActions()
        cc.tween(this._roundRewardNode)
            .repeatForever(
                cc.tween()
                    .to(_jumpTime / 2, { scale: 1.1 }, { easing: 'quadOut' })
                    .to(_jumpTime / 2, { scale: 0.9 }, { easing: 'quadOut' })
                    .to(_jumpTime / 2, { scale: 1.05 }, { easing: 'quadOut' })
                    .to(_jumpTime / 3, { scale: 0.95 }, { easing: 'quadOut' })
                    .to(_jumpTime / 3, { scale: 1 }, { easing: 'quadOut' })
                    .delay(1)
            )
            .start()

        Global.btnClickEvent(this._closeBtn, this.clickCloseBtn, this);
        Global.btnClickEvent(this._helpBtn, this.clickHelpBtn, this);

        this._boxesItemList.push(cc.find("bottom_bg/item1", this.node));
        this._boxesItemList.push(cc.find("bottom_bg/item2", this.node));
        this._boxesItemList.push(cc.find("bottom_bg/item3", this.node));
        this._leftLbl = cc.find("bottom_bg/xialan_luopan/anniu_shuzi_db/lbl", this.node);
        this._spinBtn = cc.find("bottom_bg/xialan_luopan", this.node);
        Global.btnClickEvent(this._spinBtn, this.clickSpinBtn, this);

        this._mapNode = cc.find("node_map", this.node);
        this._mapScp = this._mapNode.getComponent("Explore_Map");

        this._wheelNode = cc.find("explore_wheel", this.node);
        this._wheelNode.active = false;

        this._daojishiNode = cc.find("daojishi", this.node);
        this._daojishiNode.active = false;

        this._buyBtn1 = cc.find("entrance_buy/btn_1", this.node);
        this._buyBtn2 = cc.find("entrance_buy/btn_2", this.node);
        this._buyBtn3 = cc.find("entrance_buy/btn_3", this.node);
        Global.btnClickEvent(this._buyBtn1, this.clickBuyBtn, this);
        Global.btnClickEvent(this._buyBtn2, this.clickBuyBtn, this);
        Global.btnClickEvent(this._buyBtn3, this.clickBuyBtn, this);

        let tipKuang = cc.find("tipKuang", this.node);
        tipKuang.active = true;
        tipKuang.setScale(0);
        cc.tween(tipKuang).to(0.5, { scale: 1 }).delay(3).to(0.5, { scale: 0 }).start()

        cc.vv.NetManager.registerMsg(MsgId.REQ_EXPLORE_INFO, this.onRcvNetExploreInfo, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_EXPLORE_SPIN, this.onRcvNetExploreSpin, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_EXPLORE_OPENBOX, this.onRcvNetExploreOpenBox, this);
        Global.registerEvent(EventId.CHANGE_BINGO_EXPLORE, this.onEventBingoChange, this)
        this._inter = 0;

        this._from = 0
    },

    start() {
        let req = { c: MsgId.REQ_EXPLORE_INFO };
        cc.vv.NetManager.send(req);
    },

    onDestroy() {
        if (cc.vv.gameData) {
            cc.vv.AudioManager.stopBgm()
            cc.vv.gameData.ResumeSlot()
            cc.vv.QueueWinMrg.startPop()
        } else {
            Global.popBgm()
            //是大厅的话，需要检查下是否有下一个弹窗
            cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
        }



        cc.vv.NetManager.unregisterMsg(MsgId.REQ_EXPLORE_INFO, this.onRcvNetExploreInfo, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_EXPLORE_SPIN, this.onRcvNetExploreSpin, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_EXPLORE_OPENBOX, this.onRcvNetExploreOpenBox, false, this);
    },

    setFrom(from) {
        this._from = from
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    async onRcvNetExploreInfo(msg) {
        if (msg.code == 200) {
            this._curPoint = msg.point;
            this._curPos = msg.position;
            this._boxesData = msg.boxes;
            this._roundId = msg.roundId;
            this._roundReward = msg.roundReward;
            this._buff = msg.buff;
            this._buffInfo = msg.buffInfo;
            this._endTime = msg.endTime;
            this._startTime = msg.startTime;

            this.setCurRound(this._roundId);
            this.setRoundReward(this._roundReward);
            this.setLeftTimes(this._curPoint);
            this.setAllBoxes(this._boxesData);
            this.setBuffRestTime(this._buffInfo);
            this.setBuffRestCnt(this._buffInfo);
            this.setDaojishiActive();
            await this.awaitTime(0);
            this._mapScp.setFlagPosition(this._curPos);
            // this._mapScp.scrollToFlag();

            //显示引导
            cc.vv.NewGuide.ShowGuide(105)

            this._canClick = true;
        } else {
            this.node.destroy()
        }
    },

    refreshPanel() {
        this.setCurRound(this._roundId);
        this.setRoundReward(this._roundReward);
        this.setLeftTimes(this._curPoint);
        this.setAllBoxes(this._boxesData);
        this.setBuffRestTime(this._buffInfo);
        this.setBuffRestCnt(this._buffInfo);
        this.setDaojishiActive();
        this._mapScp.setFlagPosition(this._curPos);
        // this._mapScp.scrollToFlag();

        this._canClick = true;
    },

    clickCloseBtn() {
        Global.dispatchEvent("EXPLORE_UPDATED", { point: this._curPoint, percent: this._percent }) //同步给浮窗
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_CLOSE, this._from)
        Global.playComEff("ch_btn_click");
        this.node.destroy()
    },

    clickHelpBtn() {
        Global.playComEff("ch_btn_click");
        this.loadPreb("explore_pop", (node) => {
            node.getComponent("Explore_Pop").popHelp();
        })
    },

    clickBuyBtn() {
        Global.playComEff("ch_btn_click");
        this.loadPreb("explore_buy", (node) => {
            node.getComponent("Explore_Buy").showEndTime(this._buff, this._endTime, this._from);
            this._canClick = true;
        })
    },

    getRoundStr(cnt) {
        let str = cnt.toString();
        let lastStr = str.charAt(str.length - 1);
        if (lastStr === "1") {
            str += "ST"
        } else if (lastStr === "2") {
            str += "ND"
        } else if (lastStr === "3") {
            str += "RD"
        } else {
            str += "TH"
        }
        return str;
    },

    // 当前轮次
    setCurRound(cnt) {
        this._roundlbl.getComponent(cc.Label).string = this.getRoundStr(cnt);
    },

    // 通关奖励
    setRoundReward(data) {
        let coin_count = 0
        let package_count = 0
        let exp_count = 0
        for (let i = 0; i < data.length; i++) {
            let reward = data[i];
            if (reward.type == Global.PROP_ID.COIN) {
                coin_count += reward.count
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                package_count += reward.count
            } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                exp_count += reward.count
            }
        }

        Global.setLabelString("lbl_coin", this._roundRewardNode, Global.FormatNumToComma(coin_count))
        cc.find("item_package", this._roundRewardNode).active = package_count > 0
        Global.setLabelString("item_package/lbl_count", this._roundRewardNode, "X" + package_count)
        cc.find("item_exp", this._roundRewardNode).active = exp_count > 0
        Global.setLabelString("item_exp/lbl_count", this._roundRewardNode, (exp_count / 3600).toFixed(1) + "h")
    },

    // 剩余可转次数
    setLeftTimes(cnt) {
        // this._leftLbl.getComponent(cc.Label).string = cc.js.formatStr("LEFT:%s", cnt);
        I18N.setI18nLabel(this._leftLbl, cc.vv.Language.lefttime2, cnt)
    },

    // 付费点入口2
    setBuffRestTime(data) {
        let db2 = cc.find("shuzi_db", this._buyBtn2);
        let lblTime = cc.find("lbl", db2).getComponent(cc.Label);
        if (data && data.expireTime) {
            let endTime = data.expireTime * 1000;
            let nowtime = new Date().getTime();
            if (endTime > nowtime) {
                this._mapScp.replaceEmpty(true);

                lblTime.string = Global.formatSec((endTime - nowtime) / 1000);

                let self = this;
                let recountCall = function () {
                    let nowtime = new Date().getTime();
                    lblTime.string = Global.formatSec((endTime - nowtime) / 1000);
                    if (endTime <= nowtime) {
                        self._mapScp.replaceEmpty(false);
                        lblTime.unscheduleAllCallbacks();
                        lblTime.string = "00:00:00";
                        db2.active = false
                    }
                };
                lblTime.unscheduleAllCallbacks();
                lblTime.schedule(recountCall, 1);
            }
        } else {
            lblTime.string = "00:00:00";
            db2.active = false
        }
    },

    // 付费点入口3
    setBuffRestCnt(data) {
        cc.find("shuzi_db", this._buyBtn3).active = data && data.restCnt ? data.restCnt : 0;
        Global.setLabelString("shuzi_db/lbl", this._buyBtn3, data && data.restCnt ? data.restCnt : 0)
    },

    // 点spin按钮
    clickSpinBtn() {
        if (!this._canClick) {
            return
        }
        this._canClick = false;

        Global.playCashEff("exploration/btn_click")
        if (this._curPoint <= 0) {
            this.clickBuyBtn();
        } else {
            let req = { c: MsgId.REQ_EXPLORE_SPIN };
            cc.vv.NetManager.send(req);
            this.setLeftTimes(this._curPoint - 1);
        }

        StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_SPIN, this._from)
    },

    async onRcvNetExploreSpin(msg) {
        if (msg.code === 200) {
            let self = this
            let dice = msg.dice;
            this._curPoint = msg.point;
            this._curPos = msg.roundReward ? this._mapScp.getMapMaxIdx() : msg.position;
            this._boxesData = msg.boxes;
            this._percent = msg.percent;

            let list = normalWheelCfg;
            if (this._buffInfo && this._buffInfo.restCnt > 0) {
                list = buffWheelCfg;
                this._buffInfo.restCnt -= 1;
                this.setBuffRestCnt(this._buffInfo);
            }
            await this.turnWheel(list, list.indexOf(dice));
            await this._mapScp.jumpFlag(this._curPos);

            let curData = this._mapScp.getMapRoadData(this._curPos);
            if (curData && (curData.type === 1 || curData.type === 2 || curData.type === 3)) {  // 箱子
                await this.gainBoxAnim(this._mapScp.getIdxNode(this._curPos), this._boxesData);
            }
            if (msg.rewards) {    //此轮获得的奖励
                if (!curData && this._buffInfo.expireTime) {
                    curData = { type: 5 } // 买了buff，所有空格变为金币
                }
                await this.showJumpReward(msg.rewards, curData.type, this._mapScp.getIdxNode(this._curPos));

                if (cc.isValid(this.node)) {//可能界面已经关闭了
                    // 刷新色子数
                    this.setLeftTimes(this._curPoint);

                    //首次获得奖励
                    let compCall = function () {
                        if (self._curPoint == 0) {
                            cc.vv.NewGuide.ShowGuide(107)
                        }
                    }
                    let bDone = cc.vv.NewGuide.ShowGuide(106, compCall)
                    if (bDone && this._curPoint == 0) {
                        cc.vv.NewGuide.ShowGuide(107)
                    }
                }


            }
            else {
                let bDone = cc.vv.NewGuide._isDoneGuide(106)
                if (bDone && this._curPoint == 0) {
                    cc.vv.NewGuide.ShowGuide(107)
                }
            }
            if (msg.roundReward) {
                await this.awaitTime(0.5)
                await this.showRoundReward(msg.roundReward, this._roundId);

                // 刷新页面，从0开始
                this._roundId = msg.nextRoundInfo.id;
                this._roundReward = msg.nextRoundInfo.rewards;
                this.setCurRound(this._roundId);
                this.setRoundReward(this._roundReward);
                this._curPos = 0;
                this._mapScp.setFlagPosition(this._curPos);
                // this._mapScp.scrollToFlag(1);

                await this.awaitTime(1);
            }

            this._canClick = true;
        }
    },

    // 转转盘，得结果
    turnWheel(list, idx) {
        return new Promise(async (sucess, failed) => {
            Global.playCashEff("exploration/expression_shouhui")

            this._wheelNode.active = true;
            let wheel = cc.find("luopan_db", this._wheelNode);
            for (let i = 1; i <= 8; i++) {
                let str = list[i - 1];
                cc.find("items/item" + i, wheel).getComponent(cc.Label).string = str;
            }
            let zhizhen = cc.find("luopan_zhizhen", wheel);
            zhizhen.angle = 0;
            let xuanzhong = cc.find("luopan_xuanzhong", wheel);
            xuanzhong.active = false;

            wheel.setScale(0);
            cc.tween(wheel).to(0.3, { scale: 1 }, { easing: "backOut" }).start();
            await this.awaitTime(0.5);

            let total = 5 * 360 + 360 / 8 * idx;
            // cc.tween(zhizhen).to(3, {angle:-total}, {easing:"quadInOut"}).start();


            await new Promise((sucess1) => {
                Global.playCashEff("exploration/reel_scroll");

                let btn = cc.find("pop", this._wheelNode)
                btn.getComponent(cc.Button).interactable = true

                cc.tween(zhizhen)
                    .to(3, { angle: -total }, { easing: "quadInOut" })
                    .call(() => {
                        btn.off("click");
                        btn.getComponent(cc.Button).interactable = false
                        sucess1()
                    })
                    .start();

                btn.off("click");
                btn.on("click", () => {
                    zhizhen.stopAllActions();
                    zhizhen.angle = -total;
                    btn.getComponent(cc.Button).interactable = false
                    // 停止reel_scroll音效
                    cc.vv.AudioManager.stopEffectByName('reel_scroll')
                    sucess1()
                })


            })

            // Global.playCashEff("exploration/reel_scroll");
            // await this.awaitTime(3);
            Global.playCashEff("exploration/reel_stop");
            xuanzhong.active = true;
            xuanzhong.opacity = 0;
            xuanzhong.angle = -360 / 8 * idx;
            cc.tween(xuanzhong).to(0.3, { opacity: 255 }).start();

            await this.awaitTime(0.8);
            cc.tween(wheel).to(0.3, { scale: 0 }, { easing: "backIn" }).start();
            await this.awaitTime(0.3);
            this._wheelNode.active = false;
            sucess()
        })
    },

    // 设置所有箱子
    setAllBoxes(data) {
        let list;
        for (let i = 0; i < 3; i++) {
            let item = this._boxesItemList[i];

            if (data && data[i]) {
                this.setBoxState(item, data[i], i + 1);
            } else {
                this.setBoxState(item);
            }
        }
    },

    getBoxSpinSkin(type) {
        let skin = "default";
        if (type === 1) {
            skin = "L3";
        } else if (type === 2) {
            skin = "L2";
        } else if (type === 3) {
            skin = "L1";
        }
        return skin;
    },

    // 单个宝箱状态
    // data-箱子数据 idx-第几个箱子
    setBoxState(node, data, idx) {
        let self = this;
        // let nor_spr = cc.find("xialan_chushiicon", node);
        let baoxiang = cc.find("baoxiang", node);
        // nor_spr.active = !data || data.status === 0;
        baoxiang.active = data && data.status > 0;
        baoxiang.position = cc.v2(0, 0);

        if (data && data.status > 0) {
            let spine = cc.find("spine", baoxiang);
            // let spr = cc.find("spr", baoxiang);
            let btn_open = cc.find("btn_open", baoxiang);
            let btn_buy = cc.find("btn_buy", baoxiang);
            let shuzi_db = cc.find("anniu_shuzi_db", baoxiang);

            // spine.active = data.status === 2;

            spine.getComponent(sp.Skeleton).setSkin(this.getBoxSpinSkin(data.type));
            spine.getComponent(sp.Skeleton).setAnimation(0, data.status === 2 ? "animation" : "animation0", true);
            // spr.active = data.status === 1;
            // spr.getComponent("ImgSwitchCmp").setIndex(data.type-1);
            btn_open.active = data.status === 2;
            btn_buy.active = data.status === 1;
            shuzi_db.active = data.status === 1;

            if (data.status === 1) {  // 不可打开
                let nDiamond = data.diamond;
                let openTime = data.openTime * 1000;
                cc.find("btn_buy/cnt", baoxiang).getComponent(cc.Label).string = nDiamond;

                let lblTime = cc.find("lbl", shuzi_db).getComponent(cc.Label);
                lblTime.string = Global.formatSec((openTime - new Date().getTime()) / 1000);
                let recountCall = function () {
                    let nowtime = new Date().getTime();
                    lblTime.string = Global.formatSec((openTime - nowtime) / 1000);
                    if (openTime <= nowtime) {
                        lblTime.unscheduleAllCallbacks();
                        data.status = 2;
                        self.setBoxState(node, data, idx);
                    }
                };
                lblTime.schedule(recountCall, 1);

                btn_buy.off("click");
                btn_buy.getComponent(cc.Button).interactable = true;
                btn_buy.on("click", async () => {
                    if (!this._canClick) {
                        return
                    }
                    this._canClick = false;
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_BOXOPENNOW, self._from)
                    Global.playComEff("ch_btn_click");
                    btn_buy.getComponent(cc.Button).interactable = false;

                    let popData = {};
                    let nMyDiamond = cc.vv.UserManager.getDiamond();
                    if (nMyDiamond < nDiamond) {  //钻石不够
                        popData.infoStr = "Diamonds are not enough! Go get the diamond?";
                        popData.strType = 1
                        popData.sureCall = function () {
                            StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_BOXOPENNOW_YES, self._from)
                            //跳转充值钻石
                            cc.vv.UserManager.setEnterHallAction('Shop_Diamond')
                            Global.dispatchEvent(EventId.GO_HALL_TAB, 0)

                            // cc.vv.Shop.show('Shop_Coin')
                            self.clickCloseBtn()
                        }
                    } else {    //钻石足够
                        popData.infoStr = cc.js.formatStr("Sure you want to use %s diamonds for opening chest?", nDiamond);
                        popData.strType = 2
                        popData.sureCall = function () {
                            StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_BOXOPENNOW_YES, self._from)

                            lblTime.unscheduleAllCallbacks();
                            self._nDiamond = nDiamond;
                            self.sendOpenBoxReq(2, idx)
                        }
                    }
                    await new Promise((sucess, failed) => {
                        this.loadPreb("explore_popNotice", (node) => {
                            popData.cancelCall = function () {
                                StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_BOXOPENNOW_NO, self._from)

                                self._canClick = true;
                                btn_buy.getComponent(cc.Button).interactable = true;
                                sucess();
                            }
                            StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_BOXOPENNOW_POP, self._from)

                            node.getComponent("Explore_PopNotice").popNotice(popData);
                        })
                    })
                })
            } else if (data.status === 2) {   // 可打开
                btn_open.off("click");
                btn_open.getComponent(cc.Button).interactable = true;
                btn_open.on("click", () => {
                    if (!this._canClick) {
                        return
                    }
                    this._canClick = false;
                    StatisticsMgr.reqReport(StatisticsMgr.REQ_BOUNUS_EXPROLATION_BOXOPEN, self._from)
                    Global.playComEff("ch_btn_click");
                    btn_open.getComponent(cc.Button).interactable = false;
                    self.sendOpenBoxReq(1, idx)
                })
            }
        }
    },

    // 得到一个新箱子
    gainBoxAnim(fromNode, boxes) {
        let self = this
        let _isFullBox = true

        for (let i = 0; i < this._boxesItemList.length; i++) {
            let item = this._boxesItemList[i];
            let baoxiang = cc.find("baoxiang", item);
            if (!baoxiang.active) {   // 当前位置是空的，没有箱子

                Global.playCashEff("exploration/four_chests_lighting")

                let fly_xiangzi = cc.find("fly_xiangzi", this.node);
                fly_xiangzi.active = true;
                let sPos = this.node.convertToNodeSpaceAR(fromNode.convertToWorldSpaceAR(cc.v2(0, 0)));
                let ePos = this.node.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0, 0)));

                fly_xiangzi.getComponent(sp.Skeleton).setSkin(this.getBoxSpinSkin(boxes[i].type));
                fly_xiangzi.getComponent(sp.Skeleton).setAnimation(0, "animation", true)//setIndex(boxes[i].type-1)
                fly_xiangzi.position = sPos;
                cc.tween(fly_xiangzi)
                    .bezierTo(0.7, sPos, cc.v2(0, 0), ePos, { easing: "quadIn" })
                    .call(() => {
                        this.setBoxState(item, boxes[i], i + 1);
                        fly_xiangzi.active = false;
                    })
                    .start();
                _isFullBox = false
                break;
            }
        }

        if (_isFullBox) {
            //满了 
            let popData = {};
            popData.infoStr = "The place for the treasure chest is full,please open the treasure chest as soon as possible!";
            popData.strType = 3
            popData.sureCall = function () {
                //开一个宝箱
                let selIdx = -1
                let buyIdx = -1
                for (let i = 0; i < self._boxesData.length; i++) {
                    let item = self._boxesData[i]
                    if (item.status == 2) {
                        //可以打开
                        selIdx = i
                        break
                    }
                    if (item.status == 1) {
                        buyIdx = i
                    }
                }
                //模拟点开
                if (selIdx != -1) {
                    let btnOpen = cc.find(cc.js.formatStr("bottom_bg/item%s/baoxiang/btn_open", selIdx + 1), self.node)
                    btnOpen.emit("click")
                    return
                }
                if (buyIdx != -1) {
                    let btnBuy = cc.find(cc.js.formatStr("bottom_bg/item%s/baoxiang/btn_buy", buyIdx + 1), self.node)
                    btnBuy.emit("click")
                    return
                }


            }
            this.loadPreb("explore_popNotice", (node) => {
                node.getComponent("Explore_PopNotice").popNotice(popData);
            })
        }
    },

    // 开一个箱子
    openOneBox(item, rewards, idx) {
        return new Promise(async (sucess, failed) => {
            let baoxiang = cc.find("baoxiang", item);
            cc.find("btn_open", baoxiang).active = false;
            cc.find("btn_buy", baoxiang).active = false;
            cc.find("anniu_shuzi_db", baoxiang).active = false;
            // let spr = cc.find("spr", baoxiang);
            let spine = cc.find("spine", baoxiang);
            cc.tween(baoxiang)
                .to(0.5, { position: spine.parent.convertToNodeSpaceAR(cc.v2(cc.winSize.width / 2, cc.winSize.height / 2)) })
                .start()
            await this.awaitTime(0.5);
            // spr.active = false;
            spine.active = true;
            spine.getComponent(sp.Skeleton).setSkin(this.getBoxSpinSkin(rewards.type));
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
            spine.getComponent(sp.Skeleton).setCompleteListener(() => {
                spine.getComponent(sp.Skeleton).setCompleteListener();
                // item.active = false;
            })
            await this.awaitTime(0.5);
            sucess();
            await this.awaitTime(0.2);
            this.setBoxState(item, rewards, idx)
        })
    },

    // 发送开宝箱请求
    sendOpenBoxReq(type, idx) {
        let req = {
            c: MsgId.REQ_EXPLORE_OPENBOX,
            rtype: type, // 1: 免费打开，2：使用钻石打开
            box_id: idx,  // 箱子的id，对应1-4个箱子
        };
        cc.vv.NetManager.send(req)
    },

    // 开宝箱
    async onRcvNetExploreOpenBox(msg) {
        if (msg.code === 200 && !msg.spcode) {

            let box_id = msg.box_id;
            let rewards = msg.rewards;
            let boxes = msg.boxes;

            if (msg.rtype == 2 && this._nDiamond) {
                //更新钻石
                cc.vv.UserManager.setDiamond(cc.vv.UserManager.getDiamond() - this._nDiamond, true)
                this._nDiamond = 0;
            }

            await this.openOneBox(this._boxesItemList[box_id - 1], boxes[box_id - 1], box_id);
            await this.showBoxReward(rewards, box_id);

            // 箱子加了点数
            let self = this;
            rewards.forEach(data => {
                if (data.type == Global.PROP_ID.EXPLORE_DICE) {
                    self._curPoint += data.count
                    self.setLeftTimes(self._curPoint);
                }
            })
            this._canClick = true;
        }
        else if (msg.spcode && msg.spcode == 3) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_open_free);
            // cc.vv.FloatTip.show("You can open it for free now!");
            this._canClick = true;
        }
    },

    loadPreb(name, callback) {
        let parent = cc.find("Canvas")
        cc.loader.loadRes("CashHero/prefab/exploration/" + name, cc.Prefab, (err, prefab) => {
            if (!err && cc.isValid(parent) && parent.active == true && !parent.getChildByName(name)) {
                let node = cc.instantiate(prefab)
                node.parent = parent
                if (callback) {
                    callback(node)
                }
            }
        })
    },


    // 移动后奖励
    showJumpReward(rewards, type, formNode) {
        return new Promise(async (success, failed) => {
            let self = this
            if (type == 5 || type == 6) {
                //coin
                Global.playCashEff("exploration/celebration")
                //显示金币数量
                let lbl = new cc.Node()
                let lblCmp = lbl.addComponent(cc.Label)
                let lbloutline = lbl.addComponent(cc.LabelOutline)
                lbloutline.color = cc.Color.BLACK
                lbloutline.width = 3
                lblCmp.string = Global.formatNumShort(rewards[0].count)
                lblCmp.fontSize = 60
                lblCmp.enableBold = true
                lbl.position = cc.v2(0, -40)
                lbl.parent = formNode
                lbl.scale = 0
                cc.tween(lbl)
                    .to(0.2, { scale: 1 }, { easing: "backOut" })
                    .delay(0.3)
                    .call(() => {
                        //砸开金币
                        let pos = formNode.convertToWorldSpaceAR(cc.v2(0, 0))
                        Global.RewardFly(rewards, pos, () => {

                        })
                        success()
                    })
                    .delay(0.3)
                    .removeSelf()
                    .start()
            }
            else if (type == 4) {
                //轮盘次数
                let fromWorldPos = formNode.convertToWorldSpaceAR(cc.v2(0, 0))
                let toWorldPos = this._spinBtn.convertToWorldSpaceAR(cc.v2(0, 0))
                Global.FlyAnimToPos(fromWorldPos, toWorldPos, {
                    prefab: this.itemPrefab,
                    scale: 1.35,
                    endScale: 1,
                    count: rewards.length,
                    onInit: (index, node) => {
                        let data = rewards[index];
                        node.getComponent("CH_RewardItem").init(data.type);
                    },
                    onStart: () => {
                        this._spinBtn.stopAllActions();
                        cc.tween(this._spinBtn).to(0.2, { scale: 1.1 }).start();

                    },
                    onEndOne: () => {

                    },
                    onEnd: () => {
                        this._spinBtn.stopAllActions();
                        cc.tween(this._spinBtn).to(0.2, { scale: 1 }).start();

                    },
                });

                success()

            }
            else {
                let itemData = this._mapScp.getMapItemData(type);
                let data = {
                    skinName: itemData.skinName,
                    btnName: itemData.btnName,
                    type: type
                }

                this.loadPreb("explore_reward", (node) => {
                    if (type < 7) {
                        Global.playCashEff("exploration/celebration")
                    } else {
                        Global.playCashEff("exploration/finish")
                    }
                    node.getComponent("Explore_Reward").showPrize(rewards, data, success, 1, self._from)
                })
            }

        })
    },

    // 打开箱子的奖励
    showBoxReward(rewards, type) {
        return new Promise(async (success, failed) => {
            let self = this
            let itemData = this._mapScp.getMapItemData(type);
            let data = {
                skinName: itemData.skinName,
                btnName: itemData.btnName,
                type: type
            }

            this.loadPreb("explore_reward", (node) => {
                Global.playCashEff("exploration/gift_open")
                node.getComponent("Explore_Reward").showPrize(rewards, data, success, 2, self._from)
            })
        })
    },

    // 一轮的奖励
    showRoundReward(rewards, roundId) {
        return new Promise((success, failed) => {
            let self = this
            let data = {
                skinName: "ZI6",
                btnName: "WOW!",
                roundId: this.getRoundStr(roundId),
            }

            this.loadPreb("explore_reward", (node) => {
                Global.playCashEff("exploration/finish_all")
                node.getComponent("Explore_Reward").showPrize(rewards, data, success, 3, self._from)
            })
        })
    },

    // 倒计时
    setDaojishiActive() {
        let diffTime = Math.floor((this._endTime * 1000 - new Date().getTime()) / 1000);
        this._daojishiNode.active = diffTime <= 600;
    },

    onEventBingoChange: function () {
        this.node.destroy()
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1 && this._endTime * 1000 >= new Date().getTime()) {
            this._inter = 0

            let diffTime = Math.floor((this._endTime * 1000 - new Date().getTime()) / 1000);
            if (diffTime <= 600) {
                if (diffTime === 600 || diffTime === 10) {
                    let pop = cc.find("Canvas/explore_pop")
                    if (!pop) {
                        let self = this;
                        this.loadPreb("explore_pop", (node) => {
                            let okCall = function () {
                                if (diffTime >= 0) {
                                    if (!self._daojishiNode.active) {
                                        let endPos = self._daojishiNode.position;
                                        self._daojishiNode.position = cc.v2(0, 0);
                                        self._daojishiNode.active = true;
                                        cc.tween(self._daojishiNode)
                                            .to(0.5, { position: endPos })
                                            .start()
                                    }
                                }
                            }
                            node.getComponent("Explore_Pop").popTimeLeft(diffTime, okCall);
                        })
                    }
                }
                if (diffTime === 0) {
                    let pop = cc.find("Canvas/explore_pop")
                    if (!pop) {
                        let self = this;
                        this.loadPreb("explore_pop", (node) => {
                            node.getComponent("Explore_Pop").popTimeLeft(0);
                        })
                    }
                }
                Global.setLabelString("lbl", this._daojishiNode, Global.formatSec(diffTime))
            }
        }
    },
});
