/**
 * 新游戏解锁提示
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _gameid: [],
        _hasDown: [],
    },

    onLoad() {
        cc.vv.NetManager.registerMsg(MsgId.GAME_LEVELROOM, this.OnRcvNetExitRoom, this); //退出房间
        Global.registerEvent("checkSubFinish", this.downloadingFinish, this);

        let btn_close = cc.find("bg/btn_close", this.node);
        btn_close.on("click", this.onClickClose, this);

        let btn_confirm1 = cc.find("bg/content_bg1/btn_confirm", this.node);
        btn_confirm1.on("click", this.onClickConfirm1, this);

        let btn_confirm2 = cc.find("bg/content_bg2/btn_confirm", this.node);
        btn_confirm2.on("click", this.onClickConfirm2, this);


        // Global.registerEvent(cc.vv.gameData._EventId.SLOT_START_MOVE, this.onEventStartMove, this);
        // Global.registerEvent(cc.vv.gameData._EventId.SLOT_STOP_MOVE,this.onEventStopMove,this);
    },

    onDestroy() {
        this._bNeedGoSub = null
        cc.vv.NetManager.unregisterMsg(MsgId.GAME_LEVELROOM, this.OnRcvNetExitRoom);
    },

    onEnable() {
        let designResolution = cc.find('Canvas').getComponent(cc.Canvas).designResolution;
        let scaleX = designResolution.width / 1080;
        let scaleY = designResolution.height / 1920;
        this.node.scale = Math.min(scaleX, scaleY);
        Global.playComEff("ch_notification");
    },

    //设置数据
    setGameId(id) {
        this._gameid = id;
        this._showBg(false)
        this._hasDown = []



        //通知下载
        if (cc.sys.isNative && Global.openUpdate) { // 手机平台需要检测更新
            cc.vv.SubGameUpdateNode.emit("check_subgame", id[0]);
        } else {
            this.show()
        }
    },

    _showGames(id) {
        for (let i = 0; i < 2; i++) {
            let item = id[i]
            let nodeItem = cc.find('bg/content_bg' + (i + 1), this.node)
            nodeItem.active = item ? true : false


            if (item) {
                let slotIcon = cc.find('slot_icon', nodeItem)
                slotIcon.getComponent('CH_SlotIcon').setGameId(item, 'animation2')

            }

        }
    },

    _showBg(bShow) {
        cc.find('bg', this.node).active = bShow
    },

    setBtnInteractable(val) {
        let btn_confirm1 = cc.find("bg/content_bg1/btn_confirm", this.node);
        btn_confirm1.getComponent(cc.Button).interactable = val;
        let btn_confirm2 = cc.find("bg/content_bg2/btn_confirm", this.node);
        btn_confirm2.getComponent(cc.Button).interactable = val;
    },

    onEventStopMove: function () {
        if (!cc.vv.gameData) return;
        let bFreeGame = cc.vv.gameData.isFreeTime();
        this.setBtnInteractable(!bFreeGame);
    },

    onEventStartMove: function () {
        this.setBtnInteractable(false);
    },

    show() {

        this.node.stopAllActions();
        this.node.opacity = 0;
        this._showBg(true)
        this.node.runAction(cc.sequence(cc.fadeIn(0.5), cc.delayTime(30), cc.fadeOut(0.5), cc.destroySelf()));
        this._showGames(this._gameid)
        // if (!cc.vv.gameData) return;
        // let bFreeGame = cc.vv.gameData.isFreeTime();  //是否处于免费游戏
        // let bIdle = (cc.vv.gameData.GetSlotState() == 'idle');  //是否处于spin状态
        // this.setBtnInteractable(bIdle && !bFreeGame);
    },

    onClickClose() {
        Global.playComEff("ch_close");
        this.node.stopAllActions();
        this.node.runAction(cc.sequence(cc.fadeOut(0.5), cc.destroySelf()));
    },

    onClickConfirm1() {

        Global.playComEff("ch_btn_click");
        if (this._bNeedGoSub) return
        this._bNeedGoSub = true


        cc.director.pause()
        this.node.stopAllActions();
        this.node.runAction(cc.sequence(cc.fadeOut(0.5), cc.callFunc(() => {
            this.node.active = false;
        })));
        this.setBtnInteractable(false);
        if (cc.vv.gameData) {
            this._goId = this._gameid[0]
            cc.vv.gameData.setExitToHall(false);
            //todo:  这里子游戏还没下载好，无法直接进入子游戏
            cc.vv.gameData.requestExit();
        }
    },
    onClickConfirm2() {
        Global.playComEff("ch_btn_click");
        if (this._bNeedGoSub) return
        this._bNeedGoSub = true


        cc.director.pause()
        this.node.stopAllActions();
        this.node.runAction(cc.sequence(cc.fadeOut(0.5), cc.callFunc(() => {
            this.node.active = false;
        })));
        this.setBtnInteractable(false);
        if (cc.vv.gameData) {
            this._goId = this._gameid[1]
            cc.vv.gameData.setExitToHall(false);
            //todo:  这里子游戏还没下载好，无法直接进入子游戏
            cc.vv.gameData.requestExit();
        }
    },

    downloadingFinish: function (data) {
        let gameid = data.detail
        if (cc.isValid(this.node)) {
            let bHas = false
            for (let i = 0; i < this._hasDown.length; i++) {
                if (gameid == this._hasDown[i]) {
                    bHas = true
                    break
                }
            }
            if (!bHas) {
                this._hasDown.push(gameid)
            }


            if (this._hasDown.length == this._gameid.length) {
                this.show()
            }
            else {
                cc.vv.SubGameUpdateNode.emit("check_subgame", this._gameid[1]);
            }

        }
    },

    OnRcvNetExitRoom: function (msg) {
        if (msg.code == 200) {
            if (this._bNeedGoSub) {
                cc.vv.GameManager.EnterGame(this._goId)
            }

        }
    }
});
