/**
 * 破产
 */
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _lblCoinNum: null,
        _btnCollect: null,

        _userCoin: 0,
        _retData: null,
    },

    // LIFE-CYCLE CALLBACKS:
    onLoad() {
        this._lblCoinNum = cc.find('spr_ui_bg/lblCoinNum', this.node);
        this._btnCollect = cc.find("spr_ui_bg/btnCollect", this.node);
        Global.btnClickEvent(this._btnCollect, this.onBtnCollectClicked, this);
        // Global.btnClickEvent(cc.find("spr_ui_bg/btnClose", this.node), this.onBtnCloseClicked, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_COLLECT_BREAKGRANT_COIN, this.onRcvNetCollectBreakGrant, this);
        Global.playComEff("ch_notification");
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_COLLECT_BREAKGRANT_COIN, this.onRcvNetCollectBreakGrant);
        // cc.vv.EventManager.emit(EventId.NOT_ENOUGH_COIN_POP_UI);
    },

    start() {
        this._lblCoinNum.getComponent(cc.Label).string = cc.js.formatStr('%s', Global.formatMoney(this._retData.coin));
        StatisticsMgr.reqReport(StatisticsMgr.REQ_JJJ_POP)
    },

    init(data) {
        this._retData = data;
    },

    // 飞金币到自己
    flyCoinsToSelf(srcNode, addCoin, callback) {
        // let flycoinsNode = cc.find("flycoins", this.node);
        let desNode = cc.find("Canvas/LMSlots_Top/playerCoins/lbl_coinsNum"); //游戏内（旧框架）
        if (!desNode) {
            desNode = cc.find("Canvas/safe_node/LMSlots_Top/playerCoins/lbl_coinsNum"); //游戏内(新框架)
        }
        if (!desNode) {
            //desNode = cc.find("Canvas/node_lobby/node_top/spr_bg/spr_coin/lbl_coin"); //大厅
            desNode = cc.find(Global.HALL_COIN_NODE_PATH);
            if (Global.isIOSReview()) {
                desNode = cc.find("Canvas/scene_node/node_lobby/node_bottom/spr_btm_bg/spr_gold_bg/spr_gold/lbl_coin")
            }
            if (!desNode) {
                this.onBtnCloseClicked();
                cc.vv.NetManager.dispatchNetMsg({ uid: Global.playerData.uid, c: MsgId.MONEY_CHANGED, code: 200, coin: addCoin });
            }
        }
        if (srcNode && desNode) {
            let rollData = {}
            rollData.lblCoin = desNode;
            rollData.addCoin = addCoin;
            Global.FlyCoin(srcNode, desNode, callback, rollData, true)
            // flycoinsNode.getComponent("FlyCoins").showFlyCoins(
            //     flycoinsNode.convertToNodeSpaceAR(srcNode.parent.convertToWorldSpaceAR(srcNode.position)),
            //     flycoinsNode.convertToNodeSpaceAR(desNode.parent.convertToWorldSpaceAR(desNode.position)),
            //     20,
            //     callback,
            //     rollData
            // );
        }
    },

    onRcvNetCollectBreakGrant: function (msg) {
        let self = this
        if (msg.code === 200) {
            this._userCoin = msg.coin;
            cc.vv.UserManager.coin = msg.coin;
            this.flyCoinsToSelf(this._lblCoinNum, msg.addCoin, () => {
                //主动同步一次金币
                cc.vv.NetManager.send({ c: MsgId.SYNC_COIN });
                self.onBtnCloseClicked();
            });
        }
        else {
            this._btnCollect.getComponent(cc.Button).interactable = true;
        }
    },

    //收集
    onBtnCollectClicked: function (btn) {
        cc.vv.gameData.SetBreakGrant(null)
        Global.playComEff("ch_collect");
        this._btnCollect.getComponent(cc.Button).interactable = false;
        cc.vv.NetManager.send({ c: MsgId.REQ_COLLECT_BREAKGRANT_COIN });
        StatisticsMgr.reqReport(StatisticsMgr.REQ_JJJ_COLLECT)
    },

    //关闭
    onBtnCloseClicked: function () {
        if (cc.isValid(this.node)) {
            this.node.destroy();
        }
    },
});
