let itemsListCfg = require("GameItemCfg");

cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
    },

    onLoad() {
        Global.btnClickEvent(cc.find('bg/btn_go', this.node), this.onClickGoGame, this)
        Global.btnClickEvent(cc.find('closeBtn', this.node), this.onClickClose, this)

        Global.registerEvent("checkSubFinish", this.onDownloadingFinish, this);
        cc.vv.NetManager.registerMsg(MsgId.GAME_LEVELROOM, this.OnRcvNetExitRoom, this)
    },

    onDestroy() {

        cc.vv.QueueWinMrg.nextPop()
        cc.vv.NetManager.unregisterMsg(MsgId.GAME_LEVELROOM, this.OnRcvNetExitRoom);
    },

    start() {
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
        //统计
        StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_POP)
    },

    OnRcvNetExitRoom: function (msg) {
        if (msg.code == 200) {
            cc.vv.UserManager.setEnterMaxBet(true)
            cc.vv.GameManager.EnterGame(this._gameID)
        }
    },

    onDownloadingFinish: function (data) {
        if (cc.isValid(this.node)) {
            let gameid = data.detail
            if (gameid == this._gameID) {
                this._updating = false
                this.goNewGame()
            }
        }
    },

    ShowGame(gameId) {
        this._updating = false
        this._gameID = gameId
        let gameCfg = itemsListCfg[gameId]
        //icon
        let iconNode = cc.find('bg/slot_icon', this.node)
        let iconscp = iconNode.getComponent("CH_SlotIcon")
        iconNode.setScale(0.8)
        let bLeader = cc.vv.HerocardManager.isLeader(gameId)
        if (gameCfg && bLeader) {
            iconscp.setGameId(gameId, "animation3")
        } else {
            iconscp.setGameId(gameId)
        }
        let nodeDown = cc.find('bg/node_downing', this.node)
        nodeDown.active = false
    },

    //进入游戏
    onClickGoGame() {
        if (this._updating) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_wait_game_load);
            // cc.vv.FloatTip.show("Wait for a while, the game will load immediately.")
            return
        }
        let gameId = this._gameID
        if (Global.isNative()) {
            //是否是最新了
            let bUpdated = cc.vv.SubGameUpdateNode.getComponent('subGameMgr')._isAreadyNew(gameId)
            if (!bUpdated) {
                // this._updating = true
                // cc.find("bg/title1", this.node).active = false
                // cc.find("bg/title2", this.node).active = true
                // Global.setLabelString("bg/lbl_desc", this.node, "The slot you need is downloading.")

                // let nodeDown = cc.find('bg/node_downing',this.node)
                // nodeDown.active = true
                // nodeDown.getComponent('node_downing').initGameId(gameId)
                this.unDownloadTip(gameId)
                StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_GOSPIN, '弹出holdon')
                this.node.destroy()
                return
            }
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_GOSPIN, '进入子游戏')
        this.goNewGame()
        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },

    //调用未下载游戏组件
    unDownloadTip(gameId) {
        let url = 'CashHero/prefab/unDownloadTip/unDownloadTip'
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let old = cc.find('Canvas').getChildByName('unDownloadTip')
                if (!old) {
                    old = cc.instantiate(prefab)
                    old.parent = cc.find('Canvas')
                    old.getComponent('unDownloadTip').initGameID(gameId)
                }
            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },

    goNewGame() {
        if (cc.vv.gameData) {
            cc.vv.gameData.setExitToHall(false)
            cc.vv.gameData.requestExit()
            cc.find('bg/btn_go', this.node).getComponent(cc.Button).interactable = false
        } else {
            cc.vv.UserManager.setEnterMaxBet(true)
            cc.vv.GameManager.EnterGame(this._gameID)
            this.node.destroy()
        }
    },

    onClickClose() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_NEWGAME_CLOSE)
        // //没有跳过新游戏里 引导押注
        // cc.vv.NewGuide.ShowGuide(15)

        this.node.destroy()
    },
});
