/**
 * 排行榜
 */
let RANKTAB = {
    1: { title: 'totalWin', namecolor: new cc.Color().fromHEX("81ffef"), nameoutcolor: new cc.Color().fromHEX("00332f"), bgImg: "playerBg1", selfBgImg: "selfBg1" },// 总赢榜
    2: { title: 'totalBet', namecolor: new cc.Color().fromHEX("b2d8ff"), nameoutcolor: new cc.Color().fromHEX("0d2a4b"), bgImg: "playerBg2", selfBgImg: "selfBg2" },// 总下注
    3: { title: 'winrank', namecolor: new cc.Color().fromHEX("b2d8ff"), nameoutcolor: new cc.Color().fromHEX("0d2a4b"), bgImg: "playerBg3", selfBgImg: "selfBg3" }, // 大奖排行榜
    4: { title: 'heroCard', namecolor: new cc.Color().fromHEX("b7b2ff"), nameoutcolor: new cc.Color().fromHEX("000432"), bgImg: "playerBg4", selfBgImg: "selfBg4" },// 卡牌碎片获得排行榜
    5: { title: 'levelUp', namecolor: new cc.Color().fromHEX("ffa4b3"), nameoutcolor: new cc.Color().fromHEX("330200"), bgImg: "playerBg5", selfBgImg: "selfBg5" }, // 升级排行榜
    6: { title: 'pvp', namecolor: new cc.Color().fromHEX("e9a7ff"), nameoutcolor: new cc.Color().fromHEX("1d0033"), bgImg: "playerBg6", selfBgImg: "selfBg6" },     // PVP
    7: { title: 'charm', namecolor: new cc.Color().fromHEX("b7b2ff"), nameoutcolor: new cc.Color().fromHEX("000432"), bgImg: "playerBg4", selfBgImg: "selfBg4" },     // 魅力榜
};

const List = require('List');
cc.Class({
    extends: cc.Component,

    properties: {
        listview: List,
        // listScrollView:cc.ScrollView,
        _getFriendInfoNode: null,//个人信息面板

        itemAtlas: {
            default: null,
            type: cc.SpriteAtlas,
        },
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        // Global.FixDesignScale_V(this.node)

        let btnClose = cc.find("spr_bg/btn_close", this.node);
        Global.btnClickEvent(btnClose, this.onClickClose, this);

        Global.playComEff("ch_popup");

        cc.vv.NetManager.registerMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, this);
    },

    start() {
        Global.FixDesignScale_V(this.node)
        this.registerMsg();
        this.onTabPvpClick()
        if (cc.vv.gameData) {
            cc.vv.gameData.PauseSlot()
        }
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_POP, cc.vv.gameData ? 1 : 0)
    },

    registerMsg() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_RANK, this.onRcvRank, this);
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_RANK, this.onRcvRank, false, this);
        cc.vv.NetManager.unregisterMsg(MsgId.PERSIONAL_INFO, this.onRcvPersonInfo, false, this);

        if (cc.vv.gameData) {
            cc.vv.gameData.ResumeSlot()
        }
    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_ADD_FRIENDS, this.onRcvAddFriends, this);
        cc.vv.NetManager.registerMsg(MsgId.REQ_DELETE_FRIENDS, this.onRcvRemovedFriends, this);
        cc.vv.NetManager.registerMsg(MsgId.FRIEND_PRESENT, this.onRcvSendGift, this);
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_ADD_FRIENDS, this.onRcvAddFriends);
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_DELETE_FRIENDS, this.onRcvRemovedFriends);
        cc.vv.NetManager.unregisterMsg(MsgId.FRIEND_PRESENT, this.onRcvSendGift);
    },

    onRcvRank(msg) {
        if (msg.code == 200) {

            this._myself = msg.myself;
            // this._listData = msg.datalist;

            let _dataTop3 = []
            // this._dataTop3 = []
            this._listData = []
            for (let i = 0; i < msg.datalist.length; i++) {
                let itemDatas = msg.datalist[i]
                itemDatas.rank = i + 1
                if (i < 3) {
                    _dataTop3.push(itemDatas)
                }
                else {
                    this._listData.push(itemDatas)
                }
            }

            if (cc.isValid(this._listData)) {
                this._showTop3Rank(_dataTop3);
                this.showRankList();
                this.showMyselfList();
            }

            cc.find("spr_bg/bg_top", this.node).active = msg.delay >= 0;
            if (msg.delay) {
                this._delayTime = msg.delay;
                this.showDelayTime();
                this.unschedule(this.showDelayTime, this);
                this.schedule(this.showDelayTime, 1)
            }

            this._checkToday(msg.datalist[0], this._tabSwitch)
        }
    },

    showDelayTime() {
        let bg_top = cc.find("spr_bg/bg_top", this.node);
        if (cc.isValid(bg_top, true)) {
            let lblTime = cc.find('lbl', bg_top)
            if (cc.isValid(lblTime, true)) {
                lblTime.getComponent(cc.Label).string = `Refresh in ${Global.formatSec(this._delayTime)}`;
                --this._delayTime;
                if (this._delayTime < 0) {
                    this.unschedule(this.showDelayTime, this);
                    this.sendRankReq(this._rankType);
                }
            }
        }
    },

    _checkToday: function (topData, idx) {
        let _curDate = new Date().getDate()
        let _bRankDate = Global.getLocal(RANKTAB[idx].title)
        if (!_bRankDate || _curDate != _bRankDate) {
            Global.saveLocal(RANKTAB[idx].title, _curDate)
            let self = this;
            //弹出榜首动画
            let url = 'CashHero/prefab/rank/ranking_top'
            let callback = function (prefab) {
                let node = cc.instantiate(prefab)
                node.parent = cc.find('Canvas')
                node.getComponent('CH_RankTopPop').initTopData(topData, idx, self._rankType)
            }
            this._loadPrefab(url, callback)
        }
    },

    _loadPrefab: function (url, callbacks) {
        cc.vv.AssetMgr.loadResPrefab(url, (prefab) => {
            if (prefab) {
                callbacks(prefab)
            }
        })
    },

    _showTop3Rank: function (dataTop3) {
        for (let i = 0; i < dataTop3.length; i++) {
            let itemData = dataTop3[i]
            let itemNode = cc.find('spr_bg/spr_top3/item' + (i + 1), this.node)
            this.showItem(itemNode, itemData)
            // itemNode.getComponent('CH_ChatRankItem').init(itemData,1,this._rankType,this,true)
        }
    },

    sendRankReq(type) {

        this._rankType = type;

        let req = { c: MsgId.REQ_RANK };

        req.type = type;
        cc.vv.NetManager.sendAndCache(req);

    },

    showRankList() {
        this.listview.getComponent("CH_ScrollView").scrollToTop(0.1);
        this.listview.numItems = this._listData.length > 0 ? this._listData.length : 0;
        this.listview.active = (this._listData.length > 0);
    },


    showMyselfList() {
        let item_self = cc.find("spr_bg/node_center/listview/view/item_self", this.node);
        if (this._myself) {
            item_self.active = true;

            item_self.getComponent(cc.Sprite).spriteFrame = this.itemAtlas.getSpriteFrame(RANKTAB[this._tabSwitch].selfBgImg)

            this.showItem(item_self, this._myself, true);

            // if (this._tabSwitch == 3) {
            //     cc.find('lbl_lv', item_self).active = false
            // }

        } else {
            item_self.active = false;
        }
    },

    showItem(node, data, isself = false) {
        if (node) {
            let str_lv = data.ord + "";
            if (str_lv.indexOf("%") != -1) {
                str_lv = str_lv;
            }

            let box = cc.find('clickBox/Background', node);
            // let frameSprite = cc.find('node_head/img_head_frame', node).getComponent(cc.Sprite);
            let lbl_lv = cc.find("lbl_lv", node);
            let lblVal = cc.find("lbl_coin", node).getComponent(cc.Label);
            let lblName = cc.find("lbl_name", node).getComponent(cc.Label);
            let lblPlayerLv = cc.find("lv_bg/lbl_playerlv", node)
            if (lblPlayerLv) {
                lblPlayerLv.getComponent(cc.Label).string = "LV." + (data.level || 1)
            }


            if (Number(str_lv) < 4) {
                if (box) {
                    box.getComponent(cc.Sprite).spriteFrame = this.itemAtlas.getSpriteFrame(`box${str_lv}`);
                }
                // frameSprite.spriteFrame = this.itemAtlas.getSpriteFrame(`head_frame${str_lv}`);
                lblName.string = Global.subStrOfChinese(data.playername, 10, true);
            } else {
                if (box) {
                    box.getComponent(cc.Sprite).spriteFrame = this.itemAtlas.getSpriteFrame("box4");
                }
                // frameSprite.spriteFrame = this.itemAtlas.getSpriteFrame("head_frame");
                lblName.string = Global.subStrOfChinese(data.playername, 13, true);

                let nameout = lblName.node.getComponent(cc.LabelOutline)
                if (nameout) {
                    lblName.node.color = RANKTAB[this._tabSwitch].namecolor
                    nameout.color = RANKTAB[this._tabSwitch].nameoutcolor
                }
            }
            if (lbl_lv) {
                lbl_lv.getComponent(cc.Label).string = str_lv;
            }

            let coin = cc.find('spr_coin', node)
            let hero = cc.find('spr_hero', node)
            let level = cc.find('spr_level', node)
            let pvp = cc.find("spr_pvp", node)
            let bet = cc.find("spr_bet", node)
            coin.active = (this._tabSwitch == 1) ? true : false
            hero.active = (this._tabSwitch == 7) ? true : false
            level.active = (this._tabSwitch == 5) ? true : false
            if (pvp) {
                pvp.active = (this._tabSwitch == 6) ? true : false
            }
            bet.active = (this._tabSwitch == 2) ? true : false


            if (Number(str_lv) >= 4 && !isself) {
                // lblVal.horizontalAlign = (this._tabSwitch == 2 || this._tabSwitch == 4 || this._tabSwitch == 5) ? cc.Label.HorizontalAlign.CENTER : cc.Label.HorizontalAlign.LEFT;
                lblVal.horizontalAlign = cc.Label.HorizontalAlign.CENTER;
            }
            lblVal.string = Global.formatNumShort(data.coin, 1);
            cc.find("node_head", node).getComponent('UserHead').setHead(data.uid, data.usericon);
            //data.friend  0 --不是好友，可以添加对方为好友
            // 1 --不能添加好友，自己好友超过了
            // 2 --不能添加好友，对方已是好友
            // 3 --不能添加好友，对方好友超过了

            //点击头像查看个人信息
            let clickBtn = cc.find("node_head", node);
            clickBtn.off("click");
            let self = this
            Global.btnClickEvent(clickBtn, () => {
                if (data.uid) {
                    // clickBtn.getComponent(cc.Button).interactable = false
                    let req = { c: MsgId.PERSIONAL_INFO };
                    req.otheruid = data.uid
                    req.act = 2
                    cc.vv.NetManager.send(req);
                    // this.loadPrefab("friend/CH_friend_detail", this.node, (uiNode) => {
                    //     let callFunc = function() {
                    //         clickBtn.getComponent(cc.Button).interactable = true
                    //     }
                    //     uiNode.active = true
                    //     uiNode.getComponent("CH_FriendsDetail").init(data.uid, data, callFunc);
                    // })
                    // }
                    // this.loadPrefab("friend/CH_FriendInfo", this.node, (uiNode) => {
                    //     let callFunc = function(){
                    //         clickBtn.getComponent(cc.Button).interactable = true
                    //     }
                    //     uiNode.active = true
                    //     uiNode.getComponent("CH_FriendInfo").init(data.uid, data.friend == 2, data.send, callFunc);
                    // })
                }
            }, this)

            //点击宝箱
            let boxBtn = cc.find("clickBox", node)
            if (boxBtn) {
                boxBtn.off("click");
                Global.btnClickEvent(boxBtn, () => {
                    if (data.rewards) {
                        boxBtn.getComponent(cc.Button).interactable = false
                        this.loadPrefab("rankRewardPop", this.node, (uiNode) => {
                            let callFunc = function () {
                                boxBtn.getComponent(cc.Button).interactable = true
                            }
                            uiNode.active = true
                            uiNode.getComponent("rankRewardPop").init(1, data.rewards, callFunc);
                        })
                    }
                }, this)
            }
            else {
                console.log('dddd')
            }

        }
    },

    onTabTotalWinClick() {
        if (this._tabSwitch == 1) {
            return
        }
        this._tabSwitch = 1
        Global.playComEff("ch_tab");

        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_TOTALWIN, bInGame)

        this.sendRankReq(1);
    },
    onTabTotalBetClick() {
        if (this._tabSwitch == 2) {
            return
        }
        this._tabSwitch = 2
        Global.playComEff("ch_tab");

        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_BET, bInGame)

        this.sendRankReq(2);
    },
    onTabWinrankClick() {
        if (this._tabSwitch == 3) {
            return
        }
        this._tabSwitch = 3
        Global.playComEff("ch_tab");

        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_WINRANK, bInGame)

        this.sendRankReq(3);
    },

    onTabHeroCardClick() {
        if (this._tabSwitch == 7) {
            return
        }
        this._tabSwitch = 7
        Global.playComEff("ch_tab");

        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_HREOCARD, bInGame)

        this.sendRankReq(7);
    },

    onTabLevelUpClick() {
        if (this._tabSwitch == 5) {
            return
        }
        this._tabSwitch = 5
        Global.playComEff("ch_tab");

        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_LEVELUP, bInGame)

        this.sendRankReq(5);
    },

    onTabPvpClick() {
        if (this._tabSwitch == 6) {
            return
        }
        this._tabSwitch = 6
        Global.playComEff("ch_tab");

        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_PVP, bInGame)

        this.sendRankReq(6);
    },

    OnListVRender(item, idx) {
        if (cc.isValid(item)) {
            let itemData = this._listData[idx];
            item.getComponent(cc.Sprite).getComponent(cc.Sprite).spriteFrame = this.itemAtlas.getSpriteFrame(RANKTAB[this._tabSwitch].bgImg);
            this.showItem(item, itemData)
            this.isMe(item, itemData)
        }
    },

    isMe(item, itemData) {
        let meNode = cc.find('me', item)
        if (itemData.uid == this._myself.uid) {
            meNode.active = true
        } else {
            meNode.active = false
        }
    },

    onClickClose: function () {
        let bInGame = cc.vv.gameData ? 1 : 0
        StatisticsMgr.reqReport(StatisticsMgr.REQ_SLOTLEVEL_RANKING_CLOSE, bInGame)

        Global.playComEff("ch_close");
        this.node.destroy()
    },


    //添加好友
    onRcvAddFriends(msg) {
        if (msg.code == 200 && !msg.spcode) {
            //修改数据
            // console.log("---1操作前", this._listData);
            for (let userdata of this._listData) {
                if (userdata.uid == msg.friend.uid) {
                    // console.log("操作的好友id", userdata.uid, msg.friend.uid);
                    userdata.friend = 2; //已添加好友
                    break;
                }
            }
            // console.log("---1操作后", this._listData);
        }
    },

    //删除好友
    onRcvRemovedFriends(msg) {
        if (msg.code == 200 && !msg.spcode) {
            // console.log("---1操作前", this._listData);
            for (let userdata of this._listData) {
                if (userdata.uid == msg.frienduids[0]) {
                    userdata.friend = 0; //已添加好友
                    break;
                }
            }
            // console.log("---1操作后", this._listData);
        }
    },

    //好友赠送礼物 改本地数据好友列表中已赠送礼物好友的 send字段
    onRcvSendGift(msg) {
        if (msg.code == 200 && !msg.spcode) {
            //修改数据
            // console.log("---1操作前", this._listData);
            for (let userdata of this._listData) {
                if (userdata.uid == msg.frienduid) {
                    // console.log("操作的好友id", userdata.uid, msg.frienduid);
                    userdata.send = 1; //已发送
                    break;
                }
            }
            // console.log("---1操作后", this._listData);
        }
    },

    onRcvPersonInfo: function (msg) {
        if (msg.code == 200) {
            if (msg.spcode == 423) {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_not_find_friendsinfo);
                // cc.vv.FloatTip.show('No friend information found');
                return
            }
            else if (msg.act == 1 || msg.act == 2) {
                //detail
                cc.loader.loadRes("CashHero/prefab/friend/CH_friend_detail", cc.Prefab, (err, prefab) => {
                    if (!err) {
                        let parentNode = cc.find("Canvas")
                        let oldNode = parentNode.getChildByName('CH_friend_detail')
                        if (!oldNode) {
                            let node = cc.instantiate(prefab);
                            node.parent = parentNode;
                            node.getComponent('CH_FriendsDetail').init(msg.playerInfo.uid, msg)

                        }
                        else {
                            oldNode.active = true
                            oldNode.getComponent('CH_FriendsDetail').init(msg.playerInfo.uid, msg)
                        }
                    }
                });
            }

        }
    },

    loadPrefab: function (prefabName, fatherNode, callbacks) {
        let url = 'CashHero/prefab/' + prefabName;
        cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
            if (!err) {
                let parObj = cc.find("Canvas");
                if (fatherNode) {
                    parObj = fatherNode
                }
                if (cc.isValid(parObj)) {
                    if (!cc.find(prefabName, parObj)) {
                        let ui = cc.instantiate(prefab);
                        ui.parent = parObj
                        ui.active = true;

                        callbacks(ui);
                    }
                }

            }
            else {
                console.log('未找到资源:' + url)
            }
        });
    },
});
