/**
 * 推荐游戏
 */
cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_play = cc.find("node_content/btn_play", this.node)
        Global.btnClickEvent(btn_play, this.onClickPlay, this)
        let btn_close = cc.find("node_content/btn_close", this.node)
        Global.btnClickEvent(btn_close, this.onClickClose, this)
    },

    start() {
        this.showUIAnition()
    },

    //设置推荐游戏
    setRecomGame: function (gameId) {
        let gameCfg = cc.vv.GameItemCfg[gameId]
        //icon
        let iconNode = cc.find('node_content/node_text/bg1/slot_icon', this.node)
        let iconscp = iconNode.getComponent("CH_SlotIcon")
        let bLeader = cc.vv.HerocardManager.isLeader(gameId)
        if (gameCfg && bLeader) {
            iconscp.setGameId(gameId, "animation3")
        } else {
            iconscp.setGameId(gameId)
        }

    },

    showUIAnition: function () {
        let node_role = cc.find("node_content/node_role", this.node)
        let node_text = cc.find("node_content/node_text", this.node)
        let btn_play = cc.find("node_content/btn_play", this.node)
        let btn_close = cc.find("node_content/btn_close", this.node)

        node_role.x = -609
        node_role.active = true
        cc.tween(node_role)
            .to(0.6, { x: -309 }, { easing: "backOut" })
            .start()

        node_text.active = true
        node_text.scale = 0
        cc.tween(node_text)
            .to(0.5, { scale: 1 }, { easing: "backIn" })
            .call(() => {
                btn_play.active = true
                btn_play.opacity = 0
                cc.tween(btn_play)
                    .to(0.6, { opacity: 255 })
                    .start()
            })
            .delay(0.5)
            .call(() => {
                btn_close.active = true
                btn_close.opacity = 0
                cc.tween(btn_close)
                    .to(0.6, { opacity: 255 })
                    .start()
            })
            .start()


    },

    onClickClose: function () {
        Global.playComEff("ch_btn_click");
        this.node.destroy()
    },

    onClickPlay: function () {
        Global.playComEff("ch_btn_click");
    },

    // update (dt) {},
});
