
cc.Class({
    extends: cc.Component,

    properties: {
        _stype: 0,
        _data: null,
        _callback: null,
        _winCoin: 0
    },

    onLoad() {
        this.clickSkip = true
        let btnCollectSmall = cc.find("small_prize/btn_collect", this.node)
        btnCollectSmall.on("click", this.onClickCollectSmallPrize, this)
        btnCollectSmall.active = false

        let btnCollectFinal = cc.find("final_prize/btn_collect", this.node)
        btnCollectFinal.on("click", this.onClickCollectFinalPrize, this)
        btnCollectFinal.active = false

        Global.FixDesignScale_V(this.node)
        Global.registerEvent(EventId.CLICK_SKIP, this.setSkipFlag, this);
    },

    setSkipFlag() {
        this.clickSkip = false
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    show(stype, data, callback) {
        this._stype = stype
        this._data = data
        this._callback = callback

        if (data.isWin) {
            this.showFinalPrize()
        } else {
            this.showSmallPrize()
        }
    },

    showSmallPrize() {
        this._winCoin = this._data.failCoin
        cc.find("final_prize", this.node).active = false
        let small = cc.find("small_prize", this.node)
        small.active = true
        cc.find("coin_bg/lbl_coin", small).getComponent(cc.Label).string = Global.FormatNumToComma(this._winCoin)
        cc.find("btn_collect", small).active = true
        cc.find("light_02", small).runAction(cc.repeatForever(cc.rotateBy(2, 360)))
        Global.showAlertAction(small, true, 0.1, 1)
    },

    onClickCollectSmallPrize(event) {
        event.node.getComponent(cc.Button).interactable = false
        Global.playComEff("ch_collect")
        if (cc.vv.gameData) {
            cc.vv.gameData.AddCoin(this._winCoin)
        } else {
            cc.vv.UserManager.AddCoin(this._winCoin)
        }

        //飞金币
        let fromNode = cc.find("small_prize/coin_bg", this.node)
        let toNode = cc.find(Global.HALL_COIN_NODE_PATH)
        if (!toNode) {
            toNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
        }
        let copyNode = true
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        if (!rollData.lblCoin) {
            rollData.lblCoin = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            copyNode = false
        }
        rollData.addCoin = this._winCoin
        Global.FlyCoin(fromNode, toNode, () => {
            this.node.destroy()
            if (this._callback) {
                this._callback()
            }
        }, rollData, copyNode)
    },

    setLabelString(route, node, str) {
        let label = cc.find(route, node)
        if (label) {
            label.getComponent(cc.Label).string = str
        }
    },

    async showDropCard(cardid, count) {
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showDropUI(cardid, count, sucess, false)
        });
    },

    _getHeroCount(rd) {
        let count = 0
        for (let i = 0; i < rd.length; i++) {
            if (rd[i].type == Global.PROP_ID.HERO_CARD) {
                count += rd[i].count
            }
        }
        return count
    },

    async showFinalPrize() {
        Global.playCashEff("luckysmash/win")
        cc.find("small_prize", this.node).active = false
        let final = cc.find("final_prize", this.node)
        final.active = true
        cc.find("items/items_silver", final).active = (this._stype == 1)
        cc.find("items/items_gold", final).active = (this._stype == 2)
        cc.find("egg/egg_silver", final).active = (this._stype == 1)
        cc.find("egg/egg_gold", final).active = (this._stype == 2)
        Global.showAlertAction(final, true, 0.1, 1)

        let items = cc.find((this._stype == 1) ? "items/items_silver" : "items/items_gold", final)
        //物品先隐藏
        let children = items._children
        for (let i = 0; i < children.length; i++) {
            children[i].active = false
        }
        let winCoin = 0
        let heroCount = this._getHeroCount(this._data.rewards)
        for (let i = 0; i < this._data.rewards.length; i++) {
            let reward = this._data.rewards[i]
            if (reward.type == Global.PROP_ID.COIN) {
                winCoin += reward.count
                this.setLabelString("item_coin/lbl_count", items, Global.formatNumShort(reward.count, 0))
            } else if (reward.type == Global.PROP_ID.VIP_POINT) {
                this.setLabelString("item_vip/lbl_count", items, "" + reward.count)
            } else if (reward.type == Global.PROP_ID.DOUBLE_LEVEL_EXP) {
                cc.find("item_exp/lbl_count", items).getComponent(cc.Label).string = reward.count + 'H'
            } else if (reward.type == Global.PROP_ID.HERO_CARD) {
                cc.find("item_package/lbl_count", items).getComponent(cc.Label).string = 'X' + heroCount
            }
        }
        //依次显示物品
        await this.awaitTime(0.4)
        for (let i = 0; i < children.length; i++) {
            let child = children[i]
            child.active = true
            cc.find("spine", child).getComponent(sp.Skeleton).setAnimation(0, "animation", false)
            await this.awaitTime(0.8)
        }

        cc.vv.UserManager.setHeroData(this._data.rewards)
        //显示获得的卡牌
        for (let i = 0; i < this._data.rewards.length; i++) {
            if (!this.clickSkip) {
                break
            }
            let reward = this._data.rewards[i]
            if (reward.type == Global.PROP_ID.HERO_CARD) {
                if (reward.cardInfo) {
                    cc.vv.HerocardManager.updateCardInfo(reward.cardInfo)
                    Global.dispatchEvent("HEROCARD_UPDATED", reward.cardInfo)
                }
                await this.showDropCard(reward.cardID, reward.count)
            }
        }
        cc.vv.UserManager.clearHeroData()
        //收集按钮
        let btnCollect = cc.find("btn_collect", final)
        //显示金币
        if (this._data.remainInfo) {
            winCoin += this._data.remainInfo.coin
        }
        this._winCoin = winCoin
        let spine = cc.find("coin_bg/spine", final)
        spine.active = true
        spine.getComponent(sp.Skeleton).setAnimation(0, "animation", true)
        let lblcoin = cc.find("coin_bg/lbl_coin", final)
        Global.doRoallNumEff(lblcoin, Math.floor(winCoin * 0.1), winCoin, 2, () => {
            btnCollect.active = true
            spine.active = false
        }, null, 0, true);

    },

    onClickCollectFinalPrize(event) {
        event.node.getComponent(cc.Button).interactable = false
        Global.playComEff("ch_collect")
        if (cc.vv.gameData) {
            cc.vv.gameData.AddCoin(this._winCoin)
        } else {
            cc.vv.UserManager.AddCoin(this._winCoin)
        }


        //飞金币
        let fromNode = cc.find("final_prize/coin_bg", this.node)
        let toNode = cc.find(Global.HALL_COIN_NODE_PATH)
        if (!toNode) {
            toNode = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
        }
        let copyNode = true
        let rollData = {}
        rollData.lblCoin = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
        if (!rollData.lblCoin) {
            rollData.lblCoin = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
            copyNode = false
        }
        rollData.addCoin = this._winCoin
        Global.FlyCoin(fromNode, toNode, () => {
            cc.vv.AudioManager.stopEffectByName("win")
            this.node.destroy()
            if (this._callback) {
                this._callback()
            }
        }, rollData, copyNode)
    }

});
