cc.Class({
    extends: cc.Component,

    properties: {
        // foo: {
        //     // ATTRIBUTES:
        //     default: null,        // The default value will be used only when the component attaching
        //                           // to a node for the first time
        //     type: cc.SpriteFrame, // optional, default is typeof default
        //     serializable: true,   // optional, default is true
        // },
        // bar: {
        //     get () {
        //         return this._bar;
        //     },
        //     set (value) {
        //         this._bar = value;
        //     }
        // },
    },

    onLoad() {
        Global.btnClickEvent(this.node, this.onClickFunc, this)
    },

    start() { },

    setChicked(flag) {
        cc.find('checkmark', this.node).active = flag
    },

    onClickFunc() {
        this._picid = this.node.name.slice(5)
        if (this._picid == 7) {
            //fb
            if (cc.vv.UserManager.isBindFb()) {
                Global.dispatchEvent(EventId.UPDATE_USER_HEAD_PICID, { picid: this._picid })
            } else {
                this.fbConnect()
            }
        } else if (this._picid > 100) {
            let cfg = this.node.heroCfg;
            let isUnlock = cc.vv.HerocardManager.isCardUnlock(cfg.cardid);
            if (!isUnlock) { // 锁
                let gameName = cfg.name.toUpperCase();
                Global.dispatchEvent(EventId.SHOW_USER_HEAD_TIP, { gameName: gameName, node: this.node })
            } else {
                Global.dispatchEvent(EventId.UPDATE_USER_HEAD_PICID, { picid: this._picid })
            }
        } else {
            Global.dispatchEvent(EventId.UPDATE_USER_HEAD_PICID, { picid: this._picid })
        }
    },

    fbConnect() {
        Global.playComEff("ch_btn_click");
        let self = this
        cc.vv.PlatformApiMgr.fbLogin((cbData) => {
            console.log("=======LMSlots--FbAuth=========:  " + JSON.stringify(cbData));
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = { c: MsgId.REQ_BIND_FACEBOOK };
                req.accesstoken = cbData.token;
                req.user = cbData.uid;
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req);
                //发消息关闭
                Global.dispatchEvent(EventId.CLOSE_USER_HEAD)
            }
            else {
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
            }
        });
    },
    
    // update (dt) {},
});
