cc.Class({
    extends: cc.Component,

    properties: {
        _suo: null,
        _clickNode: null,
        _pointList: [],
        _needBet: 0,
        _collectLock: true,
        _pointIndex: 0,
        _maxCount: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._suo = cc.find("sjt_suo", this.node)
        this._clickNode = cc.find("clickNode", this.node)
        for (let i = 1; i < 7; i++) {
            let point = cc.find("point" + i, this.node)
            this._pointList.push(point)
        }
        this._clickNode.on("click", this.onClickNode, this)
    },

    onDestroy() {},

    start() {},

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

    isSuperBonus() {
        return this._pointIndex == this._maxCount
    },

    setCollectData(collect) {
        this._needBet = collect.needbet
        this._pointIndex = collect.count || 0
        this._maxCount = collect.maxCount
        for (let i = 0; i < this._pointIndex; i++) {
            const element = this._pointList[i];
            cc.find("select", element).active = true
        }
        this.initCollectNode()
    },

    onClickNode() {
        if (cc.vv.gameData.GetSlotsScript()._isInFree) { //在免费游戏中不能修改押注
            return
        }
        if (cc.vv.gameData.GetSlotState() != 'idle') {
            return
        }
        if (cc.vv.gameData.GetAutoModelTime() > 0) {
            return
        }
        if (this._needBet <= cc.vv.gameData._deskInfo.mults.length) {
            this._clickNode.getComponent(cc.Button).interactable = false
            let bottom = cc.vv.gameData.GetBottomScript()
            bottom.SetBetIdx(this._needBet)
        }
    },

    initCollectNode() {
        let curmult = cc.vv.gameData.GetBetIdx()
        if (curmult >= this._needBet) {  //已经解锁
            this._collectLock = false
            let spineSp = this._suo.getComponent(sp.Skeleton)
            spineSp.setAnimation(0, "animation3", true)
            for (let i = 0; i < this._pointList.length; i++) {
                const element = this._pointList[i];
                element.opacity = 255
            }
            this._clickNode.getComponent(cc.Button).interactable = false
        } else {
            let spineSp = this._suo.getComponent(sp.Skeleton)
            spineSp.setAnimation(0, "animation1", true)
            for (let i = 0; i < this._pointList.length; i++) {
                const element = this._pointList[i];
                element.opacity = 0
            }
            this._clickNode.getComponent(cc.Button).interactable = true
            this._collectLock = true
        }
    },

    changeCollectNode() {
        let curmult = cc.vv.gameData.GetBetIdx()
        if (curmult >= this._needBet) {  //已经解锁
            if (this._collectLock) {
                this._collectLock = false
                let spineSp = this._suo.getComponent(sp.Skeleton)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.unlock)
                spineSp.setAnimation(0, "animation2", false)
                spineSp.addAnimation(0, "animation3", true)
                for (let i = 0; i < this._pointList.length; i++) {
                    const element = this._pointList[i];
                    element.stopAllActions()
                    cc.tween(element).to(0.5, { opacity: 255 }).start()
                }
                this._clickNode.getComponent(cc.Button).interactable = false
            }
        } else {
            if (!this._collectLock) {
                this._collectLock = true
                let spineSp = this._suo.getComponent(sp.Skeleton)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.lock)
                spineSp.setAnimation(0, "animation4", false)
                spineSp.addAnimation(0, "animation1", true)
                for (let i = 0; i < this._pointList.length; i++) {
                    const element = this._pointList[i];
                    element.stopAllActions()
                    cc.tween(element).to(0.5, { opacity: 0 }).start()
                }
                this._clickNode.getComponent(cc.Button).interactable = true
            }
        }
    },

    showQiePin() {
        return new Promise((sucess, failed) => {
            this._qiePin.active = true
            let qiePinSp = this._qiePin.getComponent(sp.Skeleton)
            qiePinSp.setAnimation(0, "skill02", false)
            // qiePinSp.addAnimation(0,"animation2",false)
            // qiePinSp.addAnimation(0,"animation3",false)
            // let animationNum = 0
            qiePinSp.setCompleteListener(() => {
                // animationNum++
                // if(animationNum === 3){
                qiePinSp.setCompleteListener(null)
                this._qiePin.active = false
                sucess()
                // }
            })
        })
    },

    addPoint() {
        let curmult = cc.vv.gameData.GetBetIdx()
        if (curmult < this._needBet) {  //未解锁
            return
        }
        this._pointIndex++
        if (this._pointIndex > this._maxCount) {
            this._pointIndex = this._maxCount
        }
        let point = this._pointList[this._pointIndex - 1]
        let effect = cc.find("effect", point)
        effect.active = true
        let effectSp = effect.getComponent(sp.Skeleton)
        effectSp.setCompleteListener(() => {
            effectSp.setCompleteListener(null)
            effect.active = false
        })
        cc.find("select", point).active = true
    },

    resetCollect() {
        for (let i = 0; i < this._pointList.length; i++) {
            const element = this._pointList[i];
            cc.find("select", element).active = false
        }
        this._pointIndex = 0
    }

    // update (dt) {},
});
