let MapCfg = {    // 每张地图上的个数
    bottom: { cnt: 3, type: 1 },
    middle: { cnt: 88, type: 2 },
    top: { cnt: 80, type: 3 },
};

cc.Class({
    extends: cc.Component,

    properties: {
        _curIdx: 0,  // 当前位置
        _finalIdx: 435,  // 总关卡

        flag_Prefab: cc.Prefab,
        bottom_Prefab: cc.Prefab,    // 3个
        middle_Prefab: cc.Prefab,    // 88个
        top_Prefab: cc.Prefab,       // 80个
        _effPool: [],
        effect_Prefab: cc.Prefab,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        this._finalIdx = 435;

        this._content = cc.find("view/content", this.node);

        this._effPool = new cc.NodePool()

        //
        // this.node.on("scrolling",this.onScrolling,this)
    },

    onDestroy() {
        if (this._effPool && this._effPool.length > 0) {
            this._effPool.clear()
        }

    },

    start() {
        // this.initMap();



    },

    // onScrolling:function(){

    // },

    generalEffectNode: function () {
        let self = this
        let showNode = null
        if (this._effPool.size() > 0) {
            showNode = this._effPool.get()
        }
        else {
            showNode = cc.instantiate(this.effect_Prefab)
        }
        showNode.parent = this.node
        //随机位置
        let effType
        if (this._bClould) {
            effType = Global.random(3, 4)
        }
        else {
            effType = Global.random(2, 4)
        }

        showNode.name = "effect_node" + effType
        if (effType == 2) {
            this._bClould = true
        }
        showNode.getComponent(sp.Skeleton).setAnimation(0, "animation" + effType, true)
        showNode.x = 0
        let size = cc.winSize;
        showNode.y = this._flag.y + Global.random(-size.height / 2, size.height / 2)

        cc.tween(showNode)
            .delay(Global.random(3, 5))
            .call(() => {
                if (showNode.name == "effect_node2") {
                    self._bClould = false
                }
                self._effPool.put(showNode)
                self.generalEffectNode()
            })
            .start()

    },

    // 得到点所在的地图id和地图类型
    getMapIdByItem(idx) {
        let b_cnt = MapCfg.bottom.cnt;
        let m_cnt = MapCfg.middle.cnt;
        let t_cnt = MapCfg.top.cnt;

        let mapId;
        let mapType;
        if (idx <= b_cnt) {
            mapId = 1;
            mapType = MapCfg.bottom.type;
        } else if (idx > b_cnt && idx <= this._finalIdx - t_cnt) {
            mapId = Math.ceil((idx - b_cnt) / m_cnt) + 1;
            mapType = MapCfg.middle.type;
        } else {
            mapId = Math.ceil((idx - b_cnt) / m_cnt) + 1;
            mapType = MapCfg.top.type;
        }
        return { id: mapId, type: mapType }
    },

    initMap(curIdx) {
        let total_Map = Math.ceil((this._finalIdx - MapCfg.bottom.cnt) / MapCfg.middle.cnt) + 1;
        let curMapInfo = this.getMapIdByItem(curIdx)//当前所在的地图
        let curMapIdx = curMapInfo.id


        for (let m_i = total_Map; m_i >= 1; m_i--) {
            let mapNode = cc.find("map_" + m_i, this._content);
            if (m_i == curMapIdx || m_i == curMapIdx + 1) {
                if (!mapNode) {
                    this.addOneMap(m_i)
                }
                else {
                    mapNode.active = true
                }
            }
            else {
                if (mapNode) {
                    mapNode.active = false
                }

            }


        }
        this._content.getComponent(cc.Layout).updateLayout()

        this.scheduleOnce(() => {
            let h = this._content.height;
            this._content.getComponent(cc.Layout).enabled = false;
        }, 0);
    },

    addOneMap(m_i) {
        let total_Map = Math.ceil((this._finalIdx - MapCfg.bottom.cnt) / MapCfg.middle.cnt) + 1;
        let mapCnt;
        let mapNode;
        if (m_i === 1) {
            mapNode = cc.instantiate(this.bottom_Prefab);
            mapCnt = MapCfg.bottom.cnt;
        } else if (m_i === total_Map) {
            mapNode = cc.instantiate(this.top_Prefab);
            mapCnt = MapCfg.top.cnt;
        } else {
            mapNode = cc.instantiate(this.middle_Prefab);
            mapCnt = MapCfg.middle.cnt;
        }

        mapNode.active = true;
        mapNode.parent = this._content;
        mapNode.name = "map_" + m_i;
        mapNode.setSiblingIndex(m_i)

        // 初始化地图上所有的节点
        let s_i = m_i === 1 ? 1 : 4;    // 由于预制节点编辑问题，节点名称不是从1开始的
        for (let i = s_i; i < mapCnt + s_i; i++) {
            let item = cc.find("item" + i, mapNode);
            let r_idx = i + (m_i > 1 ? (m_i - 2) * MapCfg.middle.cnt : 0)
            item.name = "item" + r_idx

            let _cfgType = MapRoadCfg[r_idx] ? MapRoadCfg[r_idx].type : 0
            item.active = _cfgType
            if (_cfgType) {
                let _itemCfg = this.getMapItemData(_cfgType)
                item.getComponent(sp.Skeleton).setSkin('L' + _itemCfg.skin)
                item.getComponent(sp.Skeleton).timeScale = _itemCfg.time
            }
        }
    },

    // 用金币代替空位置
    replaceEmpty(bReplace) {
        for (let i = 1; i <= this._finalIdx; i++) {
            if (!MapRoadCfg[i]) {
                let item = this.getIdxNode(i)
                let _cfgType = bReplace ? 5 : 0
                item.active = _cfgType
                if (_cfgType) {
                    let _itemCfg = this.getMapItemData(_cfgType)
                    item.getComponent(sp.Skeleton).setSkin('L' + _itemCfg.skin)
                    item.getComponent(sp.Skeleton).timeScale = _itemCfg.time
                }
                // let spr = cc.find("spr", item);
                // spr.active = true;
                // spr.getComponent("ImgSwitchCmp").setIndex(bReplace?5:0);
            }
        }
    },

    setCurIdx(idx) {
        this._curIdx = idx;
    },

    scrollToFlag(time) {
        if (this._flag) {
            let offY = this._content.height - this._flag.y - this.node.height + 200
            this.node.getComponent(cc.ScrollView).scrollToOffset(cc.v2(0, offY), time)
        }

    },

    // 上过了场景的一半，下超出了场景 => 旗子回到屏幕底端
    refreshOffset() {
        let curOffY = this.node.getComponent(cc.ScrollView).getScrollOffset().y;
        let flagOffY = this._content.height - this._flag.y - this.node.height + 200;

        if (curOffY - flagOffY > (this.node.height / 2 - 200) || curOffY < flagOffY) {
            this.scrollToFlag(0.5);
            return 0.5
        }

        return 0;
    },

    getIdxNode(idx) {
        let node;
        if (idx > 0) {
            node = cc.find(cc.js.formatStr("map_%s/item%s", this.getMapIdByItem(idx).id, idx), this._content);
        } else {
            node = cc.find("map_1/startPos", this._content);
        }
        return node;
    },

    setFlagPosition(idx) {
        this._curIdx = idx;
        this.initMap(idx)

        this.scheduleOnce(() => {
            if (!this._flag) {
                this._flag = cc.instantiate(this.flag_Prefab);
                this._flag.active = true;
                this._flag.parent = this._content;
                this._flag.zIndex = 100
            }

            this._flag.position = this._flag.parent.convertToNodeSpaceAR(this.getIdxNode(idx).convertToWorldSpaceAR(cc.v2(0, 0)));
            this.refreshOffset();

            for (let i = 0; i < 5; i++) {
                this.generalEffectNode()
            }
            this.scrollToFlag()
        }, 0.05)
    },

    jumpFlag(toIdx) {
        return new Promise(async (sucess, failed) => {
            let self = this;
            //往后20个都没有，就加一张地图
            if (toIdx + 20 <= this._finalIdx) {
                let nextMapInfo = this.getMapIdByItem(toIdx + 20)
                let nextMapNode = cc.find("map_" + nextMapInfo.id, this._content)
                if (!nextMapNode) {
                    //加一张
                    this.addOneMap(nextMapInfo.id)
                }
            }

            let seqs = []
            let awaitT = self.refreshOffset();
            seqs.push(cc.delayTime(awaitT));
            for (let i = this._curIdx + 1; i <= toIdx; i++) {
                let toPos = this._flag.parent.convertToNodeSpaceAR(this.getIdxNode(i).convertToWorldSpaceAR(cc.v2(0, 0)));
                let ac = cc.jumpTo(0.4, toPos, 150, 1)
                let call = cc.callFunc(() => { Global.playCashEff("exploration/expression_sp") })
                seqs.push(ac)
                seqs.push(call)
            }
            if (seqs.length > 0) {
                let acCall = cc.callFunc(() => {
                    self._curIdx = toIdx;
                    self.refreshOffset();

                    sucess();
                });
                seqs.push(acCall)
                let acSeq = cc.sequence(seqs)
                this._flag.runAction(acSeq)
            }
        })
    },


    getMapRoadData(idx) {
        return MapRoadCfg[idx];
    },

    getMapMaxIdx() {
        return this._finalIdx;
    },

    getMapItemData(idx) {
        return MapItemCfg[idx];
    },

    // update (dt) {},
});
