/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _stayKuang: null,
        _collectNode: null,
        _qiePin: null,
        _popWin: null,
        _wheel: null,
    },

    //获取免费游戏数据
    getStayKuang: function () {
        return this._stayKuang
    },

    setStayKuang(script) {
        this._stayKuang = script
    },

    getCollectNode: function () {
        return this._collectNode
    },

    setCollectNode(script) {
        this._collectNode = script
    },

    getQiePin: function () {
        return this._qiePin
    },

    setQiePin(script) {
        this._qiePin = script
    },

    getPopWinManage() {
        return this._popWin
    },

    setPopWinManage(script) {
        this._popWin = script
    },

    getWheelNode() {
        return this._wheel
    },

    setWheelNode(script) {
        this._wheel = script
    },

    getBonusFrames() {
        return this._deskInfo.bonusFrames
    },

    setBonusFrames(bonusFrames) {
        let curbet = this.GetBetIdx()
        this._deskInfo.bonusFrames[curbet - 1] = bonusFrames
    },

    // update (dt) {},
});
