/**
 * 商城弹出UI
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _prefabUI: null, //加载的预制
    },

    // LIFE-CYCLE CALLBACKS:

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.MONEY_CHANGED, this.OnRcvNetMoneyChanged, false, this)
    },

    //初始化
    Init: function () {
        cc.vv.NetManager.registerMsg(MsgId.MONEY_CHANGED, this.OnRcvNetMoneyChanged, this);
        Global.registerEvent(EventId.REFRESH_SHOP_COIN, this.onEventRefreshShopCoin, this)
        Global.registerEvent(EventId.UPATE_DIAMOND, this.onEventRefushHallDiamond, this)
    },

    //显示商店弹窗
    //showTab:Shop_Coin,Shop_Diamond,Shop_Sale
    show: function (showTab) {
        let self = this
        if (this._bShow) return
        this._bShow = true
        cc.vv.UserManager.setEnterHallAction(showTab)
        if (cc.vv.gameData) {
            //游戏内
            let parNode = cc.find('Canvas')
            let oldNode = cc.find('shop_pop_ui', parNode)
            if (oldNode) {
                oldNode.active = true
                if (cc.vv.gameData) {
                    cc.vv.gameData.PauseSlot()
                }
                self.showBaseInfo()
                let scp = oldNode.getComponent('CH_ShopPopUI')
                scp.refushShopList()
                return
            }
            let endCall = function () {

                if (cc.isValid(parNode)) {

                    if (cc.vv.gameData) {
                        cc.vv.gameData.PauseSlot()
                    }

                    let node = cc.instantiate(self._prefabUI)
                    node.parent = parNode
                    self.shopNode = node
                    self.showBaseInfo()

                    let topNode = cc.find('top', node)
                    topNode.zIndex = 2
                    let closeBtn = cc.find('btn_close', node)
                    closeBtn.zIndex = 2
                    Global.btnClickEvent(closeBtn, self.OnClickClose, self)
                    Global.FixDesignScale_V(self.shopNode)


                }

            }
            this._loadUIPrefab(endCall)

        }
        else {
            //游戏外

            Global.dispatchEvent(EventId.GO_HALL_TAB, 0)
        }


        Global.playComEff("ch_notification");
    },

    clearShow: function () {
        this._bShow = null
    },

    //设置基本信息
    showBaseInfo: function () {
        // if(!cc.isValid(this.shopNode)){
        //     return
        // }

        // //隐藏掉top
        // let topSprite = cc.find('page_shop/list_shop/view/content/bg_top',this.shopNode)
        // if(topSprite) topSprite.active = false

        // let contentLay = cc.find('page_shop/list_shop/view/content',this.shopNode)
        // if(contentLay) {
        //     let layCmp = contentLay.getComponent(cc.Layout)
        //     layCmp.paddingTop = 200
        //     layCmp.updateLayout()
        // }


        //设置经验等级
        cc.find("top/exp_bg/pro_exp/lbl_lv", this.shopNode).getComponent(cc.Label).string = "" + cc.vv.UserManager.level;
        let exp = cc.vv.UserManager.getCurExp()
        let upExp = cc.vv.UserManager.getUpdateExp()

        let per = exp / upExp
        if (per > 1) {
            per = 1
        }

        cc.find("top/exp_bg/pro_exp", this.shopNode).getComponent(cc.ProgressBar).progress = Math.max(0.01, per);

        //设置金币
        this.ShowCoin()

        //设置钻石
        this.ShowDiamond()

        // //显示动画
        // let scriptShop = cc.find('page_shop',this.shopNode).getComponent('CH_PageShop')
        // if(scriptShop){
        //     scriptShop.playSwingAnim()
        // }
    },

    ShowCoin: function () {
        if (cc.isValid(this.shopNode)) {
            let val = cc.vv.UserManager.coin
            let lblCoin = cc.find('top/coin_bg/lbl_coin', this.shopNode)
            lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(val);
        }

    },

    ShowDiamond: function () {
        if (cc.isValid(this.shopNode)) {
            let nVal = cc.vv.UserManager.getDiamond()
            cc.find("top/dio_bg/lbl_val", this.shopNode).getComponent(cc.Label).string = Global.FormatNumToComma(nVal);
        }
    },

    setShowNextPopUI: function (val) {
        this.show_next = val
    },

    OnClickClose: function () {
        Global.playComEff("ch_close");
        if (cc.isValid(this.shopNode)) {
            if (this.show_next) {
                // let script = this.shopNode.getComponentInChildren("CH_PageShop")
                // if (script) script.showOneTimeOnly(false)
            }
            // this.shopNode.destroy()
            // this.shopNode = null
            this.shopNode.active = false

            if (cc.vv.gameData) {
                cc.vv.gameData.ResumeSlot()
            }
            if (this.show_next) {
                cc.vv.EventManager.emit(EventId.NEXT_POP_UI);
            }
            this.show_next = null
        }

    },

    OnRcvNetMoneyChanged: function (msg) {
        if (msg.code == 200) {
            if (msg.uid == Global.playerData.uid) {
                cc.vv.UserManager.coin = msg.coin
                this.ShowCoin()
            }
        }
    },

    _loadUIPrefab: function (endCall) {
        let self = this
        if (!cc.isValid(this._prefabUI)) {
            let url = 'CashHero/prefab/shop_pop_ui'
            cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                self._prefabUI = prefab
                if (cc.isValid(endCall)) {
                    endCall()
                }
            })
        }
        else {
            if (cc.isValid(endCall)) {
                endCall()
            }
        }
    },

    onEventRefreshShopCoin() {
        this.ShowCoin();
    },

    onEventRefushHallDiamond() {
        this.ShowDiamond()
    },

    // onEventClosePopShop:function(){
    //     this.OnClickClose()
    // }



    // update (dt) {},
});
