/**
 * bonus taskitem
 */

let task_des =
{
    bonus_maintask_des1: "Upgrade to level %s.",
    bonus_maintask_des2: "Unlock %s slots.",
    bonus_maintask_des3: "Unlock %s heroes.",
    bonus_maintask_des4: "Upgrade %s heroes to 1 star.",
    bonus_maintask_des5: "Upgrade %s heroes to level 10.",
    bonus_maintask_des6: "Do summonX10 for %s times.",
    bonus_maintask_des7: "Connect to Facebook.",
    bonus_maintask_des8: "Participate in PVP matches %s times.",
    bonus_maintask_des9: "Accumulated Lucky Card levels reached %s.",
    bonus_maintask_des10: "Open %s Lucky Eggs in total.",
    bonus_maintask_des11: "Accumulate %s BIGWIN prizes or more.",
}

cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btn_diamond = cc.find("task_des", this.node)
        Global.btnClickEvent(btn_diamond, this.onClickGo, this)

        let collectBtn = cc.find('reward_bg', this.node)
        Global.btnClickEvent(collectBtn, this.onClickCollect, this)

        cc.vv.NetManager.registerMsg(MsgId.REQ_BONUS_MAINLISTREWARD, this.onRcvBonusMainListReward, this)//获得主线任务
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_BONUS_MAINLISTREWARD, this.onRcvBonusMainListReward, false, this)
    },

    start() {

    },

    init: function (data, mainTask) {
        this._showData = data
        this._mainTask = mainTask

        if (!data) return
        //lv
        Global.setLabelString("spr_lv/val", this.node, data.lv)
        //des
        let lbl_des = task_des["bonus_maintask_des" + data.type]
        if (data.type != 7) {
            lbl_des = cc.js.formatStr(task_des["bonus_maintask_des" + data.type], data.need)
        }

        Global.setLabelString("task_des/des", this.node, lbl_des)
        //pro
        let proVal = data.count / data.need
        let proNode = cc.find("task_des/pro", this.node)
        // proNode.getComponent(cc.ProgressBar).progress = proVal
        cc.tween(proNode.getComponent(cc.ProgressBar))
            .to(0.2, { progress: proVal })
            .start()
        Global.setLabelString("lbl_val", proNode, Math.ceil(proVal * 100) + "%")
        //rewards
        this.initReward(data.rewards)

        // //任务状态
        // let collectBtn = cc.find("collectBtn",this.node)
        // let goBtn = cc.find("goBtn",this.node)

        //完成标志
        let compFlag = cc.find("reward_bg/node_comp", this.node)
        compFlag.active = (data.state == 3)

        //奖励是否可以领取
        let reward_lock = cc.find("reward_bg/spr_lock", this.node)
        Global.shakeNodeR(reward_lock)
        let reward_comp = cc.find("reward_bg/spr_comp", this.node)
        Global.blinkAction(reward_comp, 0.5)
        let lvCondition = cc.vv.UserManager.isOpen(data.lv)


        let status = data.state
        switch (status) {
            case 0://未解锁

                break;
            case 1://已解锁，不可领取
                reward_comp.active = false
                reward_lock.active = true
                break;
            case 2://已解锁，可以领取
                reward_comp.active = true && lvCondition
                reward_lock.active = false || !lvCondition
                break;
            case 3://已领取

                reward_comp.active = false
                reward_lock.active = false
                break;
            default:
                break;
        }

    },

    initReward(rd) {
        let icon = cc.find('reward_bg/lay_out', this.node)
        let childArray = icon.children
        //奖励元素隐藏
        for (let j = 0; j < childArray.length; j++) {
            childArray[j].active = false
        }
        //奖励
        for (let i = 0; i < rd.length; i++) {
            let sprNode = cc.find('spr', childArray[i])
            sprNode.getComponent('CH_RewardItem').init(rd[i].type, rd[i].count, true, true)
            childArray[i].active = true
        }
    },

    onClickGo: function () {
        Global.playComEff("ch_btn_click");
        let nType = this._showData.type
        if (nType == 1) {
            // 升级:进入游戏
            cc.vv.UserManager.goSystemUI("entergame", Global.DEFAULT_GAMEID)
        }
        else if (nType == 2) {
            //slot页面
            Global.dispatchEvent(EventId.GO_HALL_TAB, 2);
        }
        else if (nType == 3 || nType == 4 || nType == 5 || nType == 6) {
            //hero页面
            cc.vv.UserManager.goSystemUI("Tabhero")
        }
        else if (nType == 7) {
            //fb
            this.fbConnect()
        }
        else if (nType == 8) {
            //pvp
            cc.vv.UserManager.goSystemUI("Tabhero")

        }
        else if (nType == 9) {
            //luckycard
            cc.vv.UserManager.goSystemUI("luckycard")
        }
        else if (nType == 10) {
            //egg
            cc.vv.UserManager.goSystemUI("smash")
        }
        else if (nType == 11) {
            cc.vv.UserManager.goSystemUI("entergame", Global.DEFAULT_GAMEID)
        }

    },

    onClickCollect: function () {
        Global.playComEff("ch_btn_click");
        let status = this._showData.state
        let blinkPath
        if (status == 2) {
            //屏蔽点击
            let collectLv = this._showData.lv
            if (cc.vv.UserManager.isOpen(collectLv)) {
                cc.vv.NewGuide.SetIsLoadingGuide(true)
                this.sendSeq()
                cc.vv.RedSys.changeRed(14, -1)
            }
            else {
                //等级未达到要求
                blinkPath = "spr_lv/val"
                cc.vv.FloatTip.show(cc.js.formatStr("You can get this reward at level %s", collectLv))
            }
        }
        else {
            let tips = "Mission rewards have been received!"
            if (status == 1) {
                //任务未完成
                tips = "Mission not completed!"
                blinkPath = "task_des/pro"
            }
            cc.vv.FloatTip.show(tips)

        }
        if (blinkPath) {
            let actionNode = cc.find(blinkPath, this.node)
            Global.blinkAction(actionNode, 0.1, 0.1, 3)
        }


    },

    sendSeq: function () {
        let req = { 'c': MsgId.REQ_BONUS_MAINLISTREWARD }
        req.type = this._showData.type
        req.taskid = this._showData.taskid
        cc.vv.NetManager.send(req)
    },

    getItemData: function () {
        return this._showData
    },

    fbConnect() {
        StatisticsMgr.reqReport(StatisticsMgr.REQ_MAIL_BOX, '主线任务fb连接按钮')
        let self = this
        cc.vv.PlatformApiMgr.fbLogin((cbData) => {
            console.log("=======LMSlots--FbAuth=========:  " + JSON.stringify(cbData));
            let result = parseInt(cbData.result);
            if (result == 1) {
                let req = { c: MsgId.REQ_BIND_FACEBOOK };
                req.accesstoken = cbData.token;
                req.user = cbData.uid;
                req.type = Global.LoginType.FB
                cc.vv.NetManager.send(req);
                //刷新任务列表
                Global.dispatchEvent("REFUSH_MAINTASK")
            }
            else {
                // cc.vv.FloatTip.show("FB Account Bind Failed!");
                cc.vv.FloatTip.show(cc.vv.Language.float_tip_FB_bind_failed);
            }
        });
    },

    onRcvBonusMainListReward: function (msg) {
        if (msg.code == 200) {
            this._clickQuestid = msg.taskid

            if (msg.shadow) {
                //删除这条数据
                this._mainTask.delTaskItemData(this._clickQuestid, msg.type)
            }
            else {
                //最后一条了，需要保留
                this._mainTask.updateTaskItemData(this._clickQuestid, msg.type, 3)
            }
            if (msg.taskid == this._showData.taskid && msg.type == this._showData.type) {
                //飞奖励
                //this._showItemRewards(msg.rewards)
                let pos = cc.find("reward_bg/lay_out", this.node).convertToWorldSpaceAR(cc.v2(0, 0))
                Global.RewardFly(msg.rewards, pos, () => {
                    this._mainTask.showTaskList()
                })
            }


        }
        cc.vv.NewGuide.SetIsLoadingGuide(false)
    },

    _showItemRewards(rewards) {
        //金币直接飞，物品弹出显示
        let coin = 0
        let tempItems = []
        for (let i = 0; i < rewards.length; i++) {
            if (rewards[i].type == Global.PROP_ID.COIN) {
                coin = rewards[i].count
            }
            else {
                tempItems.push(rewards[i])
            }
        }
        if (coin) {
            let toLbl = cc.find(Global.HALL_COIN_LABEL_NODE_PATH)
            let endNode = cc.find(Global.HALL_COIN_NODE_PATH);
            if (cc.vv.gameData) {
                toLbl = cc.find(Global.INGAME_COIN_LABEL_NODE_PATH)
                endNode = cc.find(Global.INGAME_COIN_NODE_PATH);
            }

            let rollData = {}
            rollData.lblCoin = toLbl
            rollData.addCoin = coin
            let srcObj

            let coinGiftObj = this.node

            let giftcp = coinGiftObj.getComponentInChildren("MissionGift")
            srcObj = coinGiftObj
            if (giftcp) {
                srcObj = giftcp.node
            }



            Global.FlyCoin(srcObj, endNode, () => {


                if (cc.vv.gameData) {
                    cc.vv.gameData.AddCoin(coin)
                    cc.vv.gameData.RefushMyCoin()
                } else {
                    cc.vv.UserManager.AddCoin(coin, true)
                }


                this.loadPopReward(tempItems)

            }, rollData, true)
        }
        else {

            this.loadPopReward(tempItems)

        }

    },

    loadPopReward(rdArr) {
        this._mainTask.showTaskList()

        if (rdArr.length > 0) {


            let self = this
            let nextCall = function () {

            }
            cc.vv.UserManager.loadPopReward(rdArr, nextCall)
        }

    },



    // update (dt) {},
});
