// 骑士的探索-弹窗  --没有tap to close按钮
cc.Class({
    extends: require('UI_popwin_interface'),

    properties: {
        _helpNode: cc.Node,
        _noticeNode: cc.Node,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {

        this._noticeNode = cc.find("notice", this.node);
        this._noticeNode.active = false;
    },

    start() {
        // let nScale = this.node.scale
        // Global.showAlertAction(this.node,true,0.1,nScale,null)
    },

    popNotice(data, callBack) {
        this._noticeNode.active = true;

        if (data.strType == 2) {
            //找出数字
            let _diaCount = data.infoStr.replace(/[^0-9]/ig, "")
            //钻石足够
            I18N.setI18nLabel(cc.find("lbl", this._noticeNode), cc.vv.Language['diamond_tip2'], _diaCount)
        } else {
            let btni18Scp = cc.find("lbl", this._noticeNode).getComponent("LanguageLabel")
            btni18Scp.id = data.strType == 1 ? 'diamond_tip1' : 'explore_noticetip_des'
            btni18Scp.updateLabel()
        }
        // cc.find("lbl", this._noticeNode).getComponent(cc.Label).string = data.infoStr;

        let yesBtn = cc.find("btn_yes", this._noticeNode);
        let noBtn = cc.find("btn_no", this._noticeNode);

        yesBtn.off("click");
        yesBtn.getComponent(cc.Button).interactable = true;
        yesBtn.on("click", () => {
            yesBtn.getComponent(cc.Button).interactable = false;
            noBtn.getComponent(cc.Button).interactable = false;

            if (data.sureCall) {
                data.sureCall();
            }

            this.node.destroy();
        });
        noBtn.off("click");
        noBtn.getComponent(cc.Button).interactable = true;
        noBtn.on("click", () => {
            yesBtn.getComponent(cc.Button).interactable = false;
            noBtn.getComponent(cc.Button).interactable = false;

            if (data.cancelCall) {
                data.cancelCall();
            }
            this.node.destroy();
        });
    },


    // update (dt) {},
});
