/**
 * Quest 主场景
 */
let NMAX_ROUND = 2
let roadline = ['quest_gameitem1', 'road1', 'spr_reward1', 'road2', 'quest_gameitem2', 'spr_reward2', 'road3', 'quest_gameitem3', 'road4',
    'spr_reward3', 'road5', 'quest_gameitem4', 'road6', 'spr_reward4', 'quest_gameitem5', 'road7', 'spr_reward5', 'quest_gameitem6', 'road8', 'road9', 'spr_reward6']
cc.Class({
    extends: cc.Component,

    properties: {
        _gameIds: [], //开发的游戏列表
        _curGameIdx: null, //当前玩到的游戏序号
        _inter: 0,
        _curRoundIdx: null,  //quest轮数
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad() {
        let btnClose = cc.find('node_ui/btn_close', this.node)
        Global.btnClickEvent(btnClose, this.OnClickBackHall, this)
        this._timeLbl = cc.find('node_ui/finnal_coin/lbl_time', this.node)

        // let btnCollect_small = cc.find('node_ui/node_reward_small/btn_collect',this.node)
        // let btnCollect_big = cc.find('node_ui/node_reward_big/btn_collect',this.node)
        // Global.btnClickEvent(btnCollect_small,this.OnClickCollect,this)
        // Global.btnClickEvent(btnCollect_big,this.OnClickCollect,this)

        this._scroll_node = cc.find('scr_content', this.node)
        this._scroll_node.on('scrolling', this.OnScrolling, this)
        cc.vv.NetManager.registerMsg(MsgId.REQ_QUEST_REWARD, this.OnRcvNetQuestReward, this);


    },
    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_QUEST_REWARD, this.OnRcvNetQuestReward, false, this);
    },

    start() {
        let self = this
        self._inter = 1

        this._refushUI()

        //播放logo动画
        let logo_spine = cc.find('node_ui/finnal_coin/spine', this.node);
        let spinCMP = logo_spine.getComponent(sp.Skeleton)
        spinCMP.setAnimation(0, 'animation', false)
        spinCMP.addAnimation(0, 'animation2', true);
        // this._roleJump('quest_gameitem2','spr_reward3')

        Global.playBgm(Global.SOUNDS.bgm_quest);
        Global.playCashEff("quest/welcometoquest");
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_ENTER)
    },

    _refushUI: function () {
        let self = this
        this._isFirstRound()
        this.initData()
        this.showGames()
        this.showRewardInfo()
        this.showMyCoin()
        this.setGamesClick(true)
        //检查是否已经完成了任务
        let bComp = this.checkTaskComplete()
        let lbl_finnal = this._card.active ? cc.find('lbl_coin', this._card) : cc.find('lbl_coin', this._normal)

        let itemCfg = this._getGameCfgByidx(5)
        let nEnd = itemCfg.rewardnum

        if (bComp) {
            self._scrollToCurTask(0)
            lbl_finnal.getComponent(cc.Label).string = Global.FormatNumToComma(nEnd)
        }
        else {
            let delayCall = function () {

                cc.tween(self.node)
                    .delay(0.5)
                    .call(() => {
                        self._scrollToCurTask(3)
                    })
                    .delay(3)
                    .call(() => {
                        self.showSelectGameAni()
                    })
                    .start()
            }
            Global.doRoallNumEff(lbl_finnal, 0, nEnd, 1.5, delayCall, null, 0, true)
        }
    },

    _isFirstRound() {
        //是否有卡牌
        let questID = cc.vv.UserManager.getCurQuestId()

        this._card = cc.find('node_ui/finnal_coin/card', this.node)
        this._normal = cc.find('node_ui/finnal_coin/normal', this.node)
        let flag = (questID > 1) ? true : false
        this._card.active = !flag
        this._normal.active = flag
    },

    showSelectGameAni: function () {
        let reward_node = cc.find('Canvas/scr_content/view/content/node_bg/spr_reward' + (this._curGameIdx + 1))
        this.OnClickReward({ node: reward_node })

        // let item = cc.find('scr_content/view/content/node_bg/quest_gameitem'+(this._curGameIdx+1),this.node)
        // item.getComponent('CH_quest_gameitem').showSelect()

    },

    //显示游戏数据
    showGames() {

        for (let i = 0; i < this._gameIds.length; i++) {
            let item = cc.find('scr_content/view/content/node_bg/quest_gameitem' + (i + 1), this.node)
            item.getComponent('CH_quest_gameitem').setInfo(this._gameIds[i], i, this._curGameIdx, 1.2)
        }
    },

    showMyCoin: function () {
        let lblCoin = cc.find('node_ui/coin_bg/lbl_coin', this.node)
        lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(cc.vv.UserManager.coin)
    },

    showRewardInfo: function () {
        //设置奖励信息
        for (let localIdx = 0; localIdx < 6; localIdx++) {
            let reward_node = cc.find('Canvas/scr_content/view/content/node_bg/spr_reward' + (localIdx + 1))
            reward_node.active = (localIdx >= this._curGameIdx)
            let itemCfg = this._getGameCfgByidx(localIdx)

            if ((localIdx + 1) == 6) {
                reward_node.active = true
                let questID = cc.vv.UserManager.getCurQuestId()
                let card = cc.find('card', reward_node)
                let normal = cc.find('normal', reward_node)
                let flag = (questID > 1) ? true : false
                card.active = !flag
                normal.active = flag
                let lblCoin = card.active ? cc.find('lbl_reward', card) : cc.find('lbl_reward', normal)
                lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(itemCfg.rewardnum)
            } else {
                let lblCoin = cc.find('spr_tip_bg/lbl_reward', reward_node)
                lblCoin.getComponent(cc.Label).string = Global.FormatNumToComma(itemCfg.rewardnum)
            }

            reward_node.off('click')
            Global.btnClickEvent(reward_node, this.OnClickReward, this)
        }
    },

    //游戏入口是否可以点击
    setGamesClick(bCan) {
        for (let i = 0; i < this._gameIds.length; i++) {
            let item = cc.find('scr_content/view/content/node_bg/quest_gameitem' + (i + 1), this.node)
            item.getComponent(cc.Button).interactable = bCan
        }
    },

    //返回大厅
    OnClickBackHall() {
        Global.playComEff("ch_btn_click");
        // let loadCall = function(err,scene){
        //     if(!err){
        //         let sceneCmp = scene.getComponentInChildren('CH_quest_loading')
        //         sceneCmp.setBackType(2)
        //     }

        // }
        if (this._bClickBack) return
        this._bClickBack = true

        cc.vv.SceneMgr.enterScene(Global.SCENE_NAME.HALL, null, Global.APP_ORIENTATION)

        // //完成quest刷新bonus 列表
        // if (this._curGameIdx >= 6) {

        // }

        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_EXIST)
    },

    OnClickReward: function (evt) {
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_REWARDINFO)

        Global.playComEff("ch_notification");
        let reward_node = evt.node
        if (reward_node) {
            let showTime = evt.showTime || 5
            let nodeTip = cc.find('spr_tip_bg', reward_node)

            if (!cc.isValid(nodeTip)) {
                let questID = cc.vv.UserManager.getCurQuestId()
                nodeTip = (questID > 1) ? cc.find('normal', reward_node) : cc.find('card', reward_node)
            }

            nodeTip.active = true
            if (nodeTip.getNumberOfRunningActions() == 0) {
                nodeTip.stopAllActions()
                nodeTip.scale = 0
                cc.tween(nodeTip)
                    .to(0.3, { scale: 1 }, { easing: 'backOut' })
                    .delay(showTime)
                    .to(0.2, { scale: 0 })
                    .start()
            }
        }

    },

    initData: function () {
        this._gameIds = []
        let questInfo = cc.vv.UserManager.getQuestInfo()
        let taskList = questInfo.roundCfg.tasks
        let taskData = questInfo.data
        this._curRoundIdx = taskData.roundid

        for (let i = 0; i < taskList.length; i++) {
            this._gameIds.push(taskList[i].gameid)
            if (taskData.taskid == taskList[i].taskid) {
                this._curGameIdx = i //获取当前玩到的游戏ID序号
            }
        }

        if (taskData.finish) {
            this._curGameIdx = 6
            this._allFinish = true //全部结束了
            this.setGamesClick(false)
            // this._showRoleTip('Good!,you have completed all tasks.')
            return
        }

        // let acTaskNum = taskList[this._curGameIdx].details.length
        // let nCompleteNum = 0
        // for(let i = 0; i < taskData.details.length; i++){
        //     if(taskData.details[i].complete){
        //         nCompleteNum++
        //     }
        // }
        // if(acTaskNum == nCompleteNum){
        //     //完成了，可以领取金币奖励了
        //     this._bHasComplete = true
        //     this.setGamesClick(false)
        //     this.sendRwardQuest()
        // }

    },

    _getGameCfgByidx: function (idx) {
        let questInfo = cc.vv.UserManager.getQuestInfo()
        let taskList = questInfo.roundCfg.tasks
        return taskList[idx]
    },

    sendRwardQuest: function () {
        if (!this._bSend) {
            this._bSend = true
            cc.vv.NetManager.send({ c: MsgId.REQ_QUEST_REWARD })

        }

    },

    OnRcvNetQuestReward: function (msg) {
        if (msg.code == 200) {
            //显示奖励弹窗
            let num = 0
            for (let i = 0; i < msg.rewards.length; i++) {
                if (msg.rewards[i].type == 1) {
                    num = msg.rewards[i].count
                }
                if (msg.rewards[i].type == 21) {
                    this._cardInfo = []
                    this._cardInfo.push(msg.rewards[i])
                }
            }

            cc.vv.UserManager.AddCoin(num)
            let newData = msg.data
            cc.vv.UserManager.updateQuestInfoData(newData)
            let cfg = msg.roundCfg
            if (cfg) {
                cc.vv.UserManager.updateQuestInfoCfg(cfg)
            }
            this.showItemCompleteReward(num)
        }
    },


    //是否已经完成了关卡
    checkTaskComplete: function () {
        if (this._allFinish) {
            return
        }
        let taskInfo = cc.vv.UserManager.getQuestInfo()
        let taskData = taskInfo.data

        let taskCfg = taskInfo.roundCfg.tasks[this._curGameIdx]
        let nTotalTask = taskCfg.details.length
        let nComplete = 0
        for (let i = 0; i < taskData.details.length; i++) {
            let item = taskData.details[i]
            if (item.complete) {
                nComplete += 1
            }
        }
        if (nComplete == nTotalTask) {
            // this._bHasComplete = true
            this.setGamesClick(false)
            this.sendRwardQuest()
            return true
        }
    },

    //显示小关卡奖励
    showItemCompleteReward: function (nVal) {
        let self = this
        //打点
        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_REWARDPOP)

        //先显示完成的动画，而后，跳到金币上，显示金币奖励，然后再跳到解锁的游戏上
        let from = 'quest_gameitem' + (self._curGameIdx + 1)
        let to = 'spr_reward' + (self._curGameIdx + 1)
        let nextCall = function () {
            let showPopreward = function () {

                cc.find('scr_content/view/content/node_bg/' + to, self.node).active = false
                let uiname = 'node_reward_small'
                let effect = 'reward_small'
                if (self._curGameIdx == 5) { // 最后一关了
                    uiname = 'node_reward_big'
                    effect = 'reward_big'
                }
                let item_reward_complete = cc.find('node_ui/' + uiname, self.node)
                item_reward_complete.active = true
                let btnCollect = cc.find('btn_collect', item_reward_complete)
                btnCollect.active = false



                let lblCoinVal = cc.find('lbl_coin', item_reward_complete)
                let finishCall = function () {
                    let toNode = cc.find('node_ui/coin_bg/lbl_coin', self.node)
                    toNode.parent.active = true
                    btnCollect.active = true
                    btnCollect.off('click')
                    btnCollect.on('click', () => {
                        btnCollect.active = false
                        //打点
                        StatisticsMgr.reqReport(StatisticsMgr.REQ_QUESTMAIN_REWARDCOLLECT)

                        let rollData = {}
                        rollData.lblCoin = toNode
                        rollData.addCoin = nVal
                        let flyEndFunc = function () {
                            //结束
                            item_reward_complete.active = false
                            self._showPopBg(false)
                            toNode.parent.active = false

                            //展示卡牌
                            if (cc.isValid(self._cardInfo)) {
                                self.showCard()
                            } else {
                                self.showNextGame()
                            }
                        }
                        Global.FlyCoin(lblCoinVal, toNode, flyEndFunc, rollData)
                    })

                }
                Global.doRoallNumEff(lblCoinVal, 0, nVal, 3, finishCall, null, 0, true)

                Global.showAlertAction(item_reward_complete, true)
                self._showPopBg(true)
                Global.playCashEff("quest/" + effect);
            }

            self._roleJump(from, to, showPopreward)
        }

        let curGameItem = cc.find('scr_content/view/content/node_bg/quest_gameitem' + (this._curGameIdx + 1), this.node)
        let curGameScp = curGameItem.getComponent('CH_quest_gameitem')
        curGameScp.showComplete(nextCall)



    },

    async showCard() {
        await this.showDropCard()
        this.showNextGame()
    },

    async showDropCard() {
        return new Promise((sucess, failed) => {
            cc.vv.HerocardManager.showFullDropUI(this._cardInfo, null, sucess)
        });
    },

    //显示下一个任务
    showNextGame: function () {
        let self = this
        //TODO 如果有下一关，地图移动到下一关。如果没有退出到大厅界面

        this._curGameIdx += 1
        if (this._curGameIdx < 6) {

            let from = 'spr_reward' + (this._curGameIdx - 1 + 1)
            let to = 'quest_gameitem' + (this._curGameIdx + 1)
            let endCall = function () {

                //打开锁
                let curItem = cc.find('scr_content/view/content/node_bg/' + to, self.node)
                let scp = curItem.getComponent('CH_quest_gameitem')
                scp.showUnLock()
                scp.setCurIndex(self._curGameIdx)
                self.setGamesClick(true)
                self.showGames()
                self.showSelectGameAni()
            }
            this._roleJump(from, to, endCall)
            //移动
            this._scrollToCurTask(2)

        }
        else {

            //通关轮次
            // let nRound = this._curRoundIdx
            // let tipStr = ''
            // if(nRound < NMAX_ROUND){
            //     tipStr = cc.js.formatStr("Congratulations,<br/>let's go Round <color=#FF0000>%s</c>",nRound+1)
            // }
            // else{
            let tipStr = "Congratulations,<br/> you have completed all rounds!"
            // }
            // let self = this
            this._refushUI()
            // let nextCall = function(){
            //     // if(nRound < NMAX_ROUND){
            //     //     //刷新下一轮
            //     //     cc.vv.UserManager.setCurQuestId(2)
            //         // self._refushUI()
            //     // }
            // }
            Global.dispatchEvent(EventId.REFRUSH_BONUSLIST)
            this._showRoleTip(tipStr, null)
            // cc.loader.loadRes("CashHero/NewGuide/RoleTip",cc.Prefab, (err, prefab) => {
            //     if (!err) {
            //         let old = this.node.getChildByName('RoleTip')
            //         if(!old){
            //             let node = cc.instantiate(prefab);
            //             node.parent = this.node;
            //             let scp = node.getComponent("RoleTip")
            //             if(scp){
            //                 scp.ShowStr(tipStr,nextCall)
            //             }
            //         }
            //     }
            // })
        }
    },

    _showRoleTip: function (tipStr, nextCall) {
        cc.loader.loadRes("CashHero/NewGuide/RoleTip", cc.Prefab, (err, prefab) => {
            if (!err) {
                let old = this.node.getChildByName('RoleTip')
                if (!old) {
                    let node = cc.instantiate(prefab);
                    node.parent = this.node;
                    let scp = node.getComponent("RoleTip")
                    if (scp) {
                        scp.ShowStr(tipStr, nextCall)
                    }
                }
            }
        })
    },

    // //领取奖励
    // OnClickCollect:function(){
    //     let self = this

    // },

    _showPopBg: function (bShow) {
        let nodelay = cc.find('node_ui/lay_bg', this.node)
        nodelay.active = bShow
    },

    _scrollToCurTask: function (nTime) {
        let scrCmp = this._scroll_node.getComponent(cc.ScrollView)
        let oldOff = scrCmp.getScrollOffset()
        let offset = cc.v2(oldOff.x, 0)
        let nPer = 0
        if (this._curGameIdx == 0) {
            nPer = 1
        }
        else if (this._curGameIdx == 1) {
            nPer = 0.79
        }
        else if (this._curGameIdx == 2) {
            nPer = 0.64
        }
        else if (this._curGameIdx == 3) {
            nPer = 0.47
        }
        else if (this._curGameIdx == 4) {
            nPer = 0.30
        }
        else if (this._curGameIdx == 5) {
            nPer = 0.13
        }

        scrCmp.scrollToPercentVertical(1 - nPer, nTime)
    },

    OnScrolling: function () {
        // let scrCmp = this._scroll_node.getComponent(cc.ScrollView)
        // let curOff = scrCmp.getScrollOffset()
        // let maxOff = scrCmp.getMaxScrollOffset ()
        // console.log('y:%s,per:',curOff.y,curOff.y/maxOff.y)
    },

    //角色跳动
    _roleJump: function (from, to, endCall) {
        let seqs = []
        let bNeed = false
        let nodeJump = cc.find('scr_content/view/content/node_bg/node_spine', this.node)
        nodeJump.active = true
        nodeJump.getComponent(sp.Skeleton).setAnimation(0, 'animation3', true)
        for (let i = 0; i < roadline.length; i++) {
            let item = roadline[i]
            let nodeTemp = cc.find('scr_content/view/content/node_bg/' + item, this.node)
            if (item == from) {
                bNeed = true
                nodeJump.position = nodeTemp.position
            }
            else {
                if (bNeed) {
                    let ac = cc.jumpTo(0.25, cc.v2(nodeTemp.position.x, nodeTemp.position.y), 200, 1)
                    let playAudio = cc.callFunc(() => {
                        Global.playCashEff("quest/map_moving");
                    })

                    let delay = cc.delayTime(0.3)
                    seqs.push(ac)
                    seqs.push(playAudio)
                    seqs.push(delay)
                }
                if (item == to) {
                    //到目标点了
                    if (to.indexOf('spr_reward') > -1) {
                        let spinDaizi = cc.find('spine_reward', nodeTemp)
                        if (spinDaizi) {
                            spinDaizi.getComponent(sp.Skeleton).setAnimation(0, 'animation2', true)
                        }
                    }
                    break
                }
            }
        }
        if (seqs.length > 0) {
            let acCall = cc.callFunc(() => {
                nodeJump.active = false
                if (endCall) {
                    endCall()
                }
            })
            seqs.push(acCall)
            let acSeq = cc.sequence(seqs)
            nodeJump.runAction(acSeq)
        }
    },

    _showTimeOut: function () {
        let node_timeout = cc.find('node_ui/quest_time_out', this.node)
        node_timeout.active = true
        Global.showAlertAction(node_timeout, true)
        this._showPopBg(true)
    },

    update(dt) {
        this._inter += dt
        if (this._inter >= 1) {
            this._inter = 0
            let questInfo = cc.vv.UserManager.getQuestInfo()
            if (questInfo) {
                let endtime = questInfo.data.begintime * 1000 + questInfo.data.duration * 1000
                let nowtime = new Date().getTime();
                if (endtime - nowtime < 0) {
                    cc.vv.UserManager.setQuestInfo(null)
                    this._showTimeOut()
                    return
                }
                let str = Global.formatSec((endtime - nowtime) / 1000)
                // this._timeLbl.getComponent(cc.Label).string = str + ' LEFT'
                I18N.setI18nLabel(this._timeLbl, cc.vv.Language.lefttime1, str)
            }

        }
    },
});
