const FORMATION_KEY = "PVP_ATTACK_FORMATION"

cc.Class({
    extends: cc.Component,

    properties: {
        _pickItem: null,
        _moveItem: null,
        _camp: 0,
        _revenge: 0,
    },

    onLoad() {
        Global.onClick("bottom/btn_start", this.node, this.onClickStart, this)
        Global.onClick("bottom/btn_close", this.node, this.onClickClose, this)

        let itemTemp = cc.find("lst_heros/view/item", this.node)
        let content = cc.find("lst_heros/view/content", this.node)
        let listCards = cc.vv.HerocardManager.getCardListByCamp(0, true)
        let listItems = []
        for (let i = 0; i < listCards.length; i++) {
            let cardInfo = listCards[i]
            let item = cc.instantiate(itemTemp)
            item.active = true
            cc.vv.HerocardManager.loadHeroCircleHead(cc.find('icon', item), cardInfo.cardid)
            Global.setLabelString("lbl_lv", item, "Lv." + cardInfo.lv)
            content.addChild(item)
            item.campid = cardInfo.cfg.campid
            item.opacity = 0
            item.runAction(cc.fadeIn(0.02 * i))
            item.getComponent(cc.Button).interactable = (cardInfo.lv > 0)
            item.getChildByName("lbl_lv").active = (cardInfo.lv > 0)
            item.getChildByName("bg_cc").active = (cardInfo.lv > 0)
            if (cardInfo.lv > 0) {
                item.on('click', this.onClickCard, this)
            }
            listItems.push(item)
        }
        this._listCards = listCards
        this._listItems = listItems

        let size = cc.vv.HerocardManager.getPvpTeamPositionSize()
        this._formation = []
        for (let i = 0; i < size; i++) {
            this._formation.push(0)
        }
        this._items = []
        this._itemPoses = []
        this._formationNode = cc.find("formation/left", this.node)
        for (let i = 0; i < 5; i++) {
            if (i < size) {
                let item = cc.find("item" + i, this._formationNode)
                item.idx = i
                this._items.push(item)
                let p = item.position
                this._itemPoses.push(cc.v2(p.x, p.y))

                item.on(cc.Node.EventType.TOUCH_START, this._onTouchStart, this)
                item.on(cc.Node.EventType.TOUCH_MOVE, this._onTouchMove, this)
                item.on(cc.Node.EventType.TOUCH_END, this._onTouchEnd, this)
                item.on(cc.Node.EventType.TOUCH_CANCEL, this._onTouchEnd, this)
            }
            cc.find("itembg" + i + "/locker", this._formationNode).active = (i >= size)
        }
        Global.setLabelString("bg_info/lbl_name", this._formationNode, cc.vv.UserManager.nickName)
        this.initAttackFormation()

        let camps = cc.find("bottom/camps", this.node)
        for (let i = 0; i < 6; i++) {
            Global.onClick("" + i, camps, this.onClickCamp, this)
        }
    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.REQ_PVP_TEAM, this.onRcvPvpTeam, this)
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.REQ_PVP_TEAM, this.onRcvPvpTeam, false, this)
    },

    init(data, revenge) {
        this._data = data
        this._revenge = revenge
        if (data.team) {
            this.initDefendFormation(data.team)
        } else {
            this.initDefendFormation([])
            cc.vv.NetManager.send({ c: MsgId.REQ_PVP_TEAM, ouid: data.uid })
        }
        let bg_info = cc.find("formation/right/bg_info", this.node)
        Global.setLabelString("lbl_name", bg_info, data.playername || "")
        Global.setLabelString("lbl_cc", bg_info, data.cc || 0)
    },

    initAttackFormation() {
        //先使用保存的阵型
        let tmp = Global.getLocal(FORMATION_KEY, '')
        let cardids = tmp.length > 0 ? JSON.parse(tmp) : [];
        if (cardids.length <= 0) {
            cardids = cc.vv.UserManager.getPvpDefendTeam()
        }
        for (let j = 0; j < cardids.length; j++) {
            let cardid = cardids[j]
            for (let i = 0; i < this._listCards.length; i++) {
                if (this._listCards[i].cardid == cardid && this._listCards[i].lv > 0) {
                    if (this.pickon(this._listCards[i])) {
                        let item = this._listItems[i]
                        item.getChildByName("check").active = true
                    }
                }
            }
        }
    },

    initDefendFormation(team) {
        let right = cc.find("formation/right", this.node)
        for (let i = 0; i < 5; i++) {
            let item = cc.find("item" + i, right)
            let role = team[i]
            if (role) {
                item.active = true
                cc.vv.HerocardManager.loadHeroCircleHead(cc.find('icon', item), role.cardid)
                Global.setLabelString("lbl_lv", item, "Lv." + role.lv)
            } else {
                item.active = false
            }
        }
    },

    onRcvPvpTeam(msg) {
        if (msg.code == 200) {
            this.initDefendFormation(msg.opponent.team)
            let bg_info = cc.find("formation/right/bg_info", this.node)
            Global.setLabelString("lbl_name", bg_info, msg.opponent.playername || "")
            Global.setLabelString("lbl_cc", bg_info, msg.opponent.cc || 0)
        }
    },

    showCamp(idx) {
        let camps = cc.find("bottom/camps", this.node)
        for (let i = 0; i < 6; i++) {
            cc.find(i + "/check", camps).active = idx == i
        }
        for (let i = 0; i < this._listItems.length; i++) {
            let item = this._listItems[i]
            let cardInfo = this._listCards[i]
            item.active = (idx == 0) || (idx == cardInfo.cfg.campid % 10)
        }
    },

    _getNearestFormationIdx(location) {
        let minIdx = -1
        let minLength = 100000
        for (let i = 0; i < this._itemPoses.length; i++) {
            let np = this._itemPoses[i]
            let wp = this._formationNode.convertToWorldSpaceAR(np)
            let len = location.sub(wp).mag()
            if (minLength > len) {
                minLength = len
                minIdx = i
            }
        }
        return minIdx
    },

    _onTouchStart(event) {
        this._moved = false
        this._pickItem = event.target
        this._pickItem.zIndex = 100
        this._startPos = event.getLocation()
    },
    _onTouchMove(event) {
        let location = event.getLocation()
        if (location.sub(this._startPos).mag() > 16) {
            this._moved = true
        }
        if (this._pickItem && this._moved) {
            let np = this._pickItem.parent.convertToNodeSpaceAR(location)
            this._pickItem.position = np
        }
    },
    _onTouchEnd(event) {
        let location = event.getLocation()
        if (this._pickItem) {
            if (this._moved) {
                let tag = this._pickItem.idx
                //先判断是不是移到到下方英雄池
                let bottom = cc.find("lst_heros", this.node)
                if (bottom.getBoundingBoxToWorld().contains(location)) {
                    //下阵
                    this.pickoff(tag)
                } else {
                    //找到最近的格子
                    let idx = this._getNearestFormationIdx(location)
                    this.swap(idx, tag)
                }
                for (let i = 0; i < this._items.length; i++) {
                    let item = this._items[i]
                    item.position = this._itemPoses[i]
                    item.zIndex = i
                }
            } else {
                this.pickoff(this._pickItem.idx)
            }
            this._pickItem = null
        }
        this._moved = false
    },

    getCardInfo(cardid) {
        for (let i = 0; i < this._listCards.length; i++) {
            if (cardid == this._listCards[i].cardid) {
                return this._listCards[i]
            }
        }
        return null
    },

    calcCC() {
        let combat = 0
        for (let i = 0; i < this._formation.length; i++) {
            let cardInfo = this.getCardInfo(this._formation[i])
            if (cardInfo) {
                combat += cc.vv.HerocardManager.getCardCombat(cardInfo)
            }
        }
        Global.setLabelString("formation/left/bg_info/lbl_cc", this.node, combat)
    },

    //设置阵容位置
    setForm(idx, cardInfo) {
        let item = this._items[idx]
        if (cardInfo) {
            this._formation[idx] = cardInfo.cardid
            item.active = true
            cc.vv.HerocardManager.loadHeroCircleHead(cc.find('icon', item), cardInfo.cardid)
            Global.setLabelString("lbl_lv", item, "Lv." + cardInfo.lv)
        } else {
            this._formation[idx] = 0
            item.active = false
        }
    },

    //上阵
    pickon(cardInfo) {
        for (let i = 0; i < this._formation.length; i++) {
            if (this._formation[i] == 0) {
                this.setForm(i, cardInfo)
                this.calcCC()
                return true
            }
        }
        return false
    },

    //下阵
    pickoff(idx) {
        if (this._formation[idx] > 0) {
            this._items[idx].active = false
            for (let i = 0; i < this._listCards.length; i++) {
                if (this._formation[idx] == this._listCards[i].cardid) {
                    let item = this._listItems[i]
                    item.getChildByName("check").active = false
                }
            }
            this._formation[idx] = 0
            this.calcCC()
        }
    },

    //下阵
    pickoffbycardid(cardid) {
        for (let i = 0; i < this._formation.length; i++) {
            if (this._formation[i] == cardid) {
                this.pickoff(i)
                break
            }
        }
    },

    //交换位置
    swap(idx1, idx2) {
        if (idx1 == idx2) return
        let cardid1 = this._formation[idx1]
        let cardid2 = this._formation[idx2]
        if (cardid1 > 0 || cardid2 > 0) {
            let cardInfo1 = this.getCardInfo(cardid1)
            let cardInfo2 = this.getCardInfo(cardid2)
            this.setForm(idx1, cardInfo2)
            this.setForm(idx2, cardInfo1)
        }
    },

    onClickCard(event) {
        for (let i = 0; i < this._listItems.length; i++) {
            let item = this._listItems[i]
            if (item == event.node) {
                let check = item.getChildByName("check")
                if (check.active == true) {
                    this.pickoffbycardid(this._listCards[i].cardid)
                } else {
                    //上阵
                    if (this.pickon(this._listCards[i])) {
                        check.active = true
                    }
                }
            }
        }
    },

    async onClickStart() {
        let cardids = []
        for (let i = 0; i < this._formation.length; i++) {
            let caradid = this._formation[i]
            if (caradid > 0) {
                cardids.push(caradid)
            }
        }
        if (cardids.length < 1) {
            cc.vv.FloatTip.show(cc.vv.Language.float_tip_select_one_hero);
            // cc.vv.FloatTip.show("At least one hero needs to be selected!")
            return
        }
        Global.saveLocal(FORMATION_KEY, JSON.stringify(cardids))

        let data = this._data
        if (data) {
            await new Promise((resolve) => {
                let url = 'CashHero/prefab/pvp/pvp_enter'
                cc.loader.loadRes(url, cc.Prefab, (err, prefab) => {
                    if (!err) {
                        let node = cc.find('Canvas').getChildByName('pvp_enter')
                        if (!node) {
                            node = cc.instantiate(prefab)
                            node.parent = cc.find('Canvas')
                        }
                        node.getComponent("Pvp_Enter").init(data, cardids, this._revenge)
                    }
                    resolve()
                })
            })
            this.node.active = false
        }
    },

    onClickClose() {
        Global.playComEff("ch_close")
        this.node.active = false
        Global.dispatchEvent("pvp_battle_close")
    },

    onClickCamp(event) {
        let idx = parseInt(event.node.name)
        if (idx >= 0 && idx <= 5) {
            this.showCamp(idx)
        }
    },

});
