cc.Class({
    extends: cc.Component,

    properties: {

    },


    onLoad() {
        let btnClose = cc.find("bg/btn_close", this.node)
        btnClose.on('click', this.onClickClose, this)

        let pages = cc.find("bg/pages", this.node)
        pages.on('page-turning', this.onPageTurning, this)
        this._pageview = pages.getComponent(cc.PageView)

        let btnPrev = cc.find("bg/btn_prev", this.node)
        btnPrev.on('click', this.onClickPrev, this)

        let btnNext = cc.find("bg/btn_next", this.node)
        btnNext.on('click', this.onClickNext, this)

        let bg = cc.find("bg", this.node)
        Global.showAlertAction(bg, true, 0.1, 1)

        Global.playComEff("ch_popup_l2")

        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_HELP_POP, cc.vv.UserManager.getBingoFrom())
    },

    onClickClose() {
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_HELP_CLOSE, cc.vv.UserManager.getBingoFrom())

        Global.playComEff("ch_close")
        this.node.destroy()
    },

    onClickPrev() {
        Global.playComEff("ch_btn_click")
        let page = this._pageview.getCurrentPageIndex()
        if (page > 0) {
            this._pageview.scrollToPage(page - 1, 0.5)
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_HELP_PAGE, cc.vv.UserManager.getBingoFrom())
    },

    onClickNext() {
        Global.playComEff("ch_btn_click")
        let page = this._pageview.getCurrentPageIndex()
        let maxPage = this._pageview.getPages().length - 1
        if (page < maxPage) {
            this._pageview.scrollToPage(page + 1, 0.5)
        }
        //打卡
        StatisticsMgr.reqReport(StatisticsMgr.REQ_BINGO_HELP_PAGE, cc.vv.UserManager.getBingoFrom())
    },

    onPageTurning() {
        let page = this._pageview.getCurrentPageIndex()
        let maxPage = this._pageview.getPages().length - 1
        cc.find("bg/btn_prev", this.node).active = (page > 0)
        cc.find("bg/btn_next", this.node).active = (page < maxPage)
    },

});
